    private bool readabilityPresentationRegistered;

    private void OnEnable()=>RegisterReadabilityPresentation();

    private void RegisterReadabilityPresentation()
    {
        if(!Application.isPlaying||readabilityPresentationRegistered)return;
        CombatReadabilityPresentation.RegisterBattle();
        readabilityPresentationRegistered=true;
    }

    private void UnregisterReadabilityPresentation()
    {
        if(!readabilityPresentationRegistered)return;
        CombatReadabilityPresentation.UnregisterBattle();
        readabilityPresentationRegistered=false;
    }

    private void Awake()
    {
        RegisterReadabilityPresentation();
#if UNITY_EDITOR
        if(!GameFlowController.HasActiveExpeditionRequest&&
           !CombatEffectTestConfiguration.Active&&
           FindObjectOfType<BombBrickBalanceAgent>()==null&&
           FindObjectOfType<CombatEffectTestSceneController>()==null)
            new GameObject("Combat Effect Test Controls")
                .AddComponent<CombatEffectTestSceneController>();
#endif
        tileBlock=new MaterialPropertyBlock();
        mainCamera=Camera.main;
        if(Application.isPlaying&&(GameFlowController.HasActiveExpeditionRequest||
           CombatEffectTestConfiguration.Active))
        {
            StartCoroutine(InitializePlayerScene());
            return;
        }
        periodicStatusTick=HandlePeriodicStatusTick;
        ConfigureSkillExecutor();
        CreateMaterialsAndMeshes();
        CalculateMapOffset();
        CreateHexArena();
        FrameCameraToMap();
        if(!SpawnTeams())
        {
            enabled=false;
            return;
        }
        if(mainCamera!=null&&(GameFlowController.HasActiveExpeditionRequest||
           CombatEffectTestConfiguration.Active))
        {
            combatCameraDirector=
                mainCamera.GetComponent<CombatCameraDirector>()??
                mainCamera.gameObject.AddComponent<CombatCameraDirector>();
            combatCameraDirector.Initialize(mainCamera,
                automaticFraming:false);
        }
        IsSceneReady=true;
    }

    private void Update()
    {
        if(UpdateRank4SkillPrelude())return;
        if(UpdateRank4Cinematic())return;
        if(UpdateWolfStampedeCinematic())return;
        if(UpdateBearAvatarCinematic())return;
        if(UpdateWizardCygnusCinematic())return;
        if(UpdateKingKongLeylineCinematic())return;
        if(UpdateCrocodileAbyssDiveCinematic())return;
        if(UpdateFrogCatchCinematic())return;
        if(UpdateSabertoothCinematic())return;
        if(UpdateRaptorCinematic())return;
        UpdateCommonSkillFocus();
        if(rank4SkillPrelude!=null)return;
        if(wavePreparationAcrossFrames)return;
        if(!mlEpisodeActive&&GameFrontend.BlocksGameplay)return;
        if(!mlEpisodeActive)
        {
            float presentationDeltaTime=GameFrontend.IsProduction
                ?GameFlowController.PresentationDeltaTime:Time.unscaledDeltaTime;
            UpdateLootVisuals();
            if(mapIntroductionActive)
            {
                UpdateMapIntroduction(presentationDeltaTime);
                RefreshUnitOutlines();
                return;
            }
            UpdateHoveredTile();
            UpdatePlacementMarkerHover();
            if(augmentDraftIntroductionActive)
            {
                UpdateAugmentDraftIntroduction(presentationDeltaTime);
                RefreshUnitOutlines();
                return;
            }
            if(waveArrivalActive)
            {
                UpdateWaveArrival(presentationDeltaTime);
                RefreshUnitOutlines();
                return;
            }
            if(waveIntroActive)
            {
                UpdateWaveIntro(presentationDeltaTime);
                RefreshUnitOutlines();
                return;
            }
            if(FirstExpeditionBattleTutorialActive&&
               !FirstDeploymentGuideVisible&&!FirstBattleStartGuideVisible)
            {
                RefreshUnitOutlines();
                return;
            }
            HandleInput();
            RefreshUnitOutlines();
#if UNITY_EDITOR
            UpdateBalanceTest();
            UpdateRosterQa();
            UpdateComboQa();
#endif
        }
        if(battleEnding)
        {
            foreach(Unit unit in units)AdvanceUnitInertia(unit,Time.deltaTime);
            UpdateBattleEnding(Time.deltaTime);
            return;
        }
        if(!battleStarted||resultText.Length>0)return;
        float dt=Time.deltaTime;
        if(dt<=0f)return;
        if(paused)
        {
            foreach(Unit unit in units)StopSabertoothDragSound(unit);
            return;
        }
        battleElapsed+=dt;
#if UNITY_EDITOR
        if((balanceTestRunning||mlEpisodeActive)&&
           battleElapsed>=SimulationBattleTimeout)
        {
            ResolveSimulationTimeout();
            return;
        }
#endif
        UpdateRegionBattleRule();
        UpdateWizardCygnusShowers(dt);
        UpdateMonkeyStorms(dt);
        UpdateWolfStampedes(dt);
        UpdateCombatStalemateRecovery();
        UpdateSpiderWebZones(dt);
        UpdateMushroomPropagations(dt);
        UpdateMushroomGasZones(dt);
        UpdateMushroomCrowns(dt);
        UpdateMushroomDeathBlooms(dt);
        UpdateMammothExpulsionFlights(dt);
        UpdateRank3IceWalls(dt);
        UpdateBeetleOverturns(dt);
        UpdateBeetleGravityFields(dt);
        UpdateWyvernBreaths(dt);
        UpdateHaetaeRoars(dt);
        UpdateHaetaeDevourers();
        UpdateGriffinCrosswinds();
        for(int i=0;i<units.Count;i++)
        {
            TickGriffinRoyal(units[i],dt);
            UpdateUnit(units[i],dt);
            UpdateTraitActivationFeedback(units[i]);
        }
        telemetryTimer-=dt;
        if(telemetryTimer<=0f)
        {
            telemetryTimer=mlEpisodeActive?2f:TelemetryInterval;
            RecordTelemetrySteps();
        }
        CheckBattleResult();
    }

    private void LateUpdate()
    {
        if(rank4SkillPrelude!=null)return;
        if(wolfStampedeCinematic!=null||bearAvatarCinematic!=null||wizardCygnusCinematic!=null||kingKongCinematic!=null||raptorCinematic!=null||sabertoothCinematic!=null||frogCatchCinematic!=null||crocodileAbyssCinematic!=null)return;
        UpdateCommonSkillFocus();
        UpdatePlacementMarkerRootVisibility();
        UpdateDeploymentExpansionFeedback();
        if(wavePreparationAcrossFrames)return;
        if(mlEpisodeActive)return;
        FitEnvironmentBackdrop();
        bool revealFullField=!battleStarted&&
            ((hoveredUnit!=null&&hoveredUnit.team==Team.Enemy)||
             (tiles.TryGetValue(hoveredTile,out Tile hoveredMarkerTile)&&
              !hoveredMarkerTile.bench&&!hoveredMarkerTile.walkable));
        if(fullFieldMarkersVisible!=revealFullField)
        {
            fullFieldMarkersVisible=revealFullField;
            foreach(Tile tile in tiles.Values)RefreshPlacementMarker(tile);
        }
        foreach(Unit unit in units)UpdateUnitShieldVisual(unit);
        for(int i=0;i<units.Count;i++)
        {
            Unit unit=units[i];
            if(unit.model==null||unit.ring==null||!unit.ring.activeSelf)continue;
            if(battleStarted)
            {
                Transform visual=unit.spriteAnimation==null
                    ?unit.model.transform:unit.spriteAnimation.transform;
                Vector3 anchor=visual.position;
                unit.ring.transform.position=new Vector3(anchor.x,0.025f,anchor.z);
            }
            UpdateTargetRing(unit);
        }
    }

    private void CreateMaterialsAndMeshes()
    {
        WarmupReadabilityPresentation();
        Shader shader=Shader.Find("Universal Render Pipeline/Lit");
        if(shader==null)shader=Shader.Find("Standard");
        tileMaterial=CreateBattleTileMaterial();
        unitShadowMaterial=CreateMaterial(Shader.Find("Sprites/Default")??shader,
            new Color(0.025f,0.03f,0.04f,0.28f),0f);
        skillRadiusMarkerMaterial=CreateMaterial(
            Shader.Find("Sprites/Default")??shader,Color.white,0f);
        if(unitShadowMaterial.HasProperty("_Smoothness"))
            unitShadowMaterial.SetFloat("_Smoothness",0f);
        tileMesh=CreateBattleTileMesh();
        benchTileMesh=UsesHexDeployment
            ?CreateSquarePrism("Battle Bench Tile",
                ActiveTileSize*0.46f*HexDeploymentTileVisualScale,-0.16f,0f)
            :tileMesh;
        placementMarkerSprite=UsesHexDeployment?CreateHexPlacementMarkerSprite():CreatePlacementMarkerSprite();
        benchPlacementMarkerSprite=placementMarkerSprite;
        if(UsesPointyHexTileArena)isoTileSprites=CreateIsoTileSprites();
    }

    private static Material CreateMaterial(Shader shader,Color color,float metallic)
    {
        Material material=new Material(shader);
        if(material.HasProperty(BaseColor))material.SetColor(BaseColor,color);
        if(material.HasProperty(ColorProperty))material.SetColor(ColorProperty,color);
        if(material.HasProperty("_Metallic"))material.SetFloat("_Metallic",metallic);
        if(material.HasProperty("_Smoothness"))material.SetFloat("_Smoothness",0.28f);
        return material;
    }

    public static Material CreateBattleTileMaterial()
    {
        Shader shader=Shader.Find("Universal Render Pipeline/Lit");
        if(shader==null)shader=Shader.Find("Standard");
        return CreateMaterial(
            shader,new Color(0.18f,0.22f,0.28f),0.08f);
    }

    public static Mesh CreateBattleTileMesh()
    {
        return UsesHexDeployment
            ?CreateHexPrism("Battle Hex Tile",ActiveTileSize/Mathf.Sqrt(3f)*0.96f*
                HexDeploymentTileVisualScale,-0.16f,0f)
            :CreateSquarePrism("Battle Square Tile",TileHalfExtent,-0.16f,0f);
    }

    private static Mesh CreateHexPrism(
        string name,float radius,float bottomY,float topY)
    {
        Vector3[] vertices=new Vector3[12];
        for(int i=0;i<6;i++)
        {
            float angle=(30f+i*60f)*Mathf.Deg2Rad;
            float x=Mathf.Cos(angle)*radius;
            float z=Mathf.Sin(angle)*radius;
            vertices[i]=new Vector3(x,topY,z);
            vertices[i+6]=new Vector3(x,bottomY,z);
        }
        List<int> triangles=new List<int>(60);
        for(int i=1;i<5;i++)
        {
            triangles.Add(0);triangles.Add(i+1);triangles.Add(i);
            triangles.Add(6);triangles.Add(6+i);triangles.Add(7+i);
        }
        for(int i=0;i<6;i++)
        {
            int next=(i+1)%6;
            triangles.Add(i);triangles.Add(next);triangles.Add(i+6);
            triangles.Add(next);triangles.Add(next+6);triangles.Add(i+6);
        }
        Mesh mesh=new Mesh{name=name};
        mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);
        mesh.RecalculateNormals();mesh.RecalculateBounds();
        return mesh;
    }

    private static Sprite CreatePlacementMarkerSprite()
    {
        const int size=64;
        const int inset=2;
        const int thickness=1;
        const int length=10;
        Color32[] pixels=new Color32[size*size];
        Color32 white=new Color32(255,255,255,255);
        for(int i=0;i<length;i++)
        for(int t=0;t<thickness;t++)
        {
            int near=inset+i;
            int far=size-1-inset-i;
            int edge=inset+t;
            int opposite=size-1-inset-t;
            pixels[edge*size+near]=white;
            pixels[near*size+edge]=white;
            pixels[edge*size+far]=white;
            pixels[near*size+opposite]=white;
            pixels[opposite*size+near]=white;
            pixels[far*size+edge]=white;
            pixels[opposite*size+far]=white;
            pixels[far*size+opposite]=white;
        }
        Color32[] core=(Color32[])pixels.Clone();
        Color32 glow=new Color32(255,255,255,44);
        for(int y=1;y<size-1;y++)
        for(int x=1;x<size-1;x++)
        {
            if(core[y*size+x].a==0)continue;
            for(int oy=-1;oy<=1;oy++)
            for(int ox=-1;ox<=1;ox++)
            {
                int index=(y+oy)*size+x+ox;
                if(pixels[index].a==0)pixels[index]=glow;
            }
        }
        Texture2D texture=new Texture2D(size,size,TextureFormat.RGBA32,false)
        {
            name="Deployment Corner Marker",
            filterMode=FilterMode.Bilinear,
            wrapMode=TextureWrapMode.Clamp
        };
        texture.SetPixels32(pixels);
        texture.Apply(false,true);
        return Sprite.Create(texture,new Rect(0f,0f,size,size),
            new Vector2(0.5f,0.5f),size,0,SpriteMeshType.FullRect);
    }

    private static Sprite CreateHexPlacementMarkerSprite()
    {
        const int size=64;
        Vector2Int[] points=
        {
            new Vector2Int(32,2),new Vector2Int(59,17),
            new Vector2Int(59,47),new Vector2Int(32,62),
            new Vector2Int(5,47),new Vector2Int(5,17)
        };
        Color32[] pixels=new Color32[size*size];
        for(int i=0;i<points.Length;i++)
        {
            Vector2Int corner=points[i];
            Vector2Int previous=MarkerSegmentPoint(
                corner,points[(i+points.Length-1)%points.Length],0.22f);
            Vector2Int next=MarkerSegmentPoint(
                corner,points[(i+1)%points.Length],0.22f);
            DrawMarkerLine(pixels,size,corner,previous,
                new Color32(255,255,255,32),2);
            DrawMarkerLine(pixels,size,corner,next,
                new Color32(255,255,255,32),2);
        }
        for(int i=0;i<points.Length;i++)
        {
            Vector2Int corner=points[i];
            Vector2Int previous=MarkerSegmentPoint(
                corner,points[(i+points.Length-1)%points.Length],0.22f);
            Vector2Int next=MarkerSegmentPoint(
                corner,points[(i+1)%points.Length],0.22f);
            DrawMarkerLine(pixels,size,corner,previous,
                new Color32(255,255,255,220),1);
            DrawMarkerLine(pixels,size,corner,next,
                new Color32(255,255,255,220),1);
        }
        Texture2D texture=new Texture2D(size,size,TextureFormat.RGBA32,false)
        {
            name="Hex Deployment Marker",
            filterMode=FilterMode.Bilinear,
            wrapMode=TextureWrapMode.Clamp
        };
        texture.SetPixels32(pixels);
        texture.Apply(false,true);
        return Sprite.Create(texture,new Rect(0f,0f,size,size),
            new Vector2(0.5f,0.5f),size,0,SpriteMeshType.FullRect);
    }

    private static Sprite[] CreateIsoTileSprites()
    {
        Texture2D sheet=Resources.Load<Texture2D>("Environment/grass_03");
        if(sheet==null)return Array.Empty<Sprite>();
        sheet.filterMode=FilterMode.Point;
        sheet.wrapMode=TextureWrapMode.Clamp;
        const int columns=4,rows=4;
        int stride=(sheet.width+1)/columns;
        int width=stride-1,height=(sheet.height+1)/rows-1;
        if(width<=0||height<=0)return Array.Empty<Sprite>();
        Sprite[] sprites=new Sprite[columns*rows];
        float pixelsPerUnit=width/(ActiveTileSize*IsoTileVisualWidthFactor);
        for(int row=0;row<rows;row++)
        for(int column=0;column<columns;column++)
        {
            Rect rect=new Rect(
                column*stride,sheet.height-(row*stride+height),width,height);
            sprites[row*columns+column]=Sprite.Create(
                sheet,rect,new Vector2(0.5f,0.573f),pixelsPerUnit,
                0,SpriteMeshType.FullRect);
            sprites[row*columns+column].name=$"Iso Grass Tile {row},{column}";
        }
        return sprites;
    }

    private void CreateIsoTileVisual(
        Transform parent,Vector2Int coordinate,Vector3 world)
    {
        if(isoTileSprites.Length==0)return;
        GameObject visual=new GameObject($"Pixel Tile {coordinate.x},{coordinate.y}");
        visual.transform.SetParent(parent,false);
        visual.transform.position=world+Vector3.up*0.012f;
        SpriteRenderer renderer=visual.AddComponent<SpriteRenderer>();
        int variant=Math.Abs(coordinate.x*5+coordinate.y*11)%isoTileSprites.Length;
        renderer.sprite=isoTileSprites[variant];
        float rowDepth=ActiveTileSize*IsoTileDiagonalDepthFactor;
        renderer.sortingOrder=-300-Mathf.RoundToInt(world.z/rowDepth*2f);
        visual.AddComponent<SpriteMonsterBillboard>();
    }

    private static Vector2Int MarkerSegmentPoint(
        Vector2Int corner,Vector2Int neighbor,float ratio)
    {
        return new Vector2Int(
            Mathf.RoundToInt(Mathf.Lerp(corner.x,neighbor.x,ratio)),
            Mathf.RoundToInt(Mathf.Lerp(corner.y,neighbor.y,ratio)));
    }

    private static void DrawMarkerLine(
        Color32[] pixels,int size,Vector2Int start,Vector2Int end,
        Color32 color,int thickness)
    {
        int x=start.x,y=start.y;
        int dx=Mathf.Abs(end.x-x),sx=x<end.x?1:-1;
        int dy=-Mathf.Abs(end.y-y),sy=y<end.y?1:-1;
        int error=dx+dy;
        while(true)
        {
            int radius=thickness/2;
            for(int oy=-radius;oy<=radius;oy++)
            for(int ox=-radius;ox<=radius;ox++)
            {
                int px=x+ox,py=y+oy;
                if(px>=0&&px<size&&py>=0&&py<size)
                    pixels[py*size+px]=color;
            }
            if(x==end.x&&y==end.y)break;
            int twice=error*2;
            if(twice>=dy){error+=dy;x+=sx;}
            if(twice<=dx){error+=dx;y+=sy;}
        }
    }

    public static string EnvironmentResourceRoot(string regionId)
    {
        int index=Mathf.Clamp(HunterRegionCatalog.Get(regionId).order-1,
            0,EnvironmentResourceRoots.Length-1);
        return "Environment/"+EnvironmentResourceRoots[index];
    }

    private static Mesh CreateSquarePrism(string name,float halfExtent,float bottomY,float topY)
    {
        float h=halfExtent;
        Vector3[] vertices=
        {
            new Vector3(-h,topY,-h),new Vector3(h,topY,-h),new Vector3(h,topY,h),new Vector3(-h,topY,h),
            new Vector3(-h,bottomY,-h),new Vector3(h,bottomY,-h),new Vector3(h,bottomY,h),new Vector3(-h,bottomY,h)
        };
        int[] triangles=
        {
            0,2,1,0,3,2,
            4,5,6,4,6,7,
            0,1,5,0,5,4,
            1,2,6,1,6,5,
            2,3,7,2,7,6,
            3,0,4,3,4,7
        };
        Mesh mesh=new Mesh{name=name};
        mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);
        mesh.RecalculateNormals();mesh.RecalculateBounds();
        return mesh;
    }

    private void CalculateMapOffset()
    {
        if(UsesPointyHexTileArena)
        {
            mapOffset=-IsoArenaCenter();
            return;
        }
        if(UsesHexDeployment)
        {
            float maximumX=(ActiveColumns-0.5f)*ActiveTileSize*
                           ActiveHexSpacingScale;
            int centeredRows=HexDeploymentRows;
            float maximumZ=(centeredRows-1)*ActiveTileSize*HexRowSpacing*
                           ActiveHexSpacingScale;
            mapOffset=-new Vector3(maximumX*0.5f,0f,maximumZ*0.5f);
            return;
        }
        Vector3 first=RawGridWorld(new Vector2Int(0,0));
        Vector3 last=RawGridWorld(new Vector2Int(ActiveColumns-1,ActiveRows-1));
        mapOffset=-(first+last)*0.5f;
    }

    private void CreateHexArena()
    {
        var arena=CreateHexArenaRoutine();
        try{while(arena.MoveNext()){}}
        finally{(arena as IDisposable)?.Dispose();}
    }

    private IEnumerator CreateHexArenaRoutine()
    {
        Transform tileRoot=new GameObject(UsesHexDeployment?"Hex Tile Map":"Square Tile Map").transform;
        tileRoot.SetParent(transform,false);
        placementMarkerRoot=new GameObject("Deployment Corner Markers").transform;
        placementMarkerRoot.SetParent(transform,false);
        placementMarkerRoot.gameObject.SetActive(false);
        bool boundsInitialized=false;
        for(int row=0;row<ActiveRows;row++)
        for(int column=0;column<ActiveColumns;column++)
        {
            Vector2Int coordinate=new Vector2Int(column,row);
            if(!IsMapCoordinate(coordinate))continue;
            Vector3 world=GridWorld(coordinate);
            GameObject tileObject=new GameObject(
                $"{(UsesHexDeployment?"Hex":"Square")} {column},{row}");
            tileObject.transform.SetParent(tileRoot,false);
            tileObject.transform.position=world;
            MeshFilter filter=tileObject.AddComponent<MeshFilter>();filter.sharedMesh=tileMesh;
            Renderer renderer=tileObject.AddComponent<MeshRenderer>();renderer.sharedMaterial=tileMaterial;
            renderer.enabled=!UsesPointyHexTileArena;
            if(UsesPointyHexTileArena)
                CreateIsoTileVisual(tileRoot,coordinate,world);
            Tile tile=new Tile{coordinate=coordinate,gameObject=tileObject,renderer=renderer,world=world};
            tile.walkable=true;
            tile.baseColor=TileBaseColor(tile);
            tiles.Add(coordinate,tile);
            SetTileColor(tile,tile.baseColor);
            if(wavePreparationAcrossFrames&&column%6==5)yield return null;
            if(UsesHexDeployment&&coordinate.y>=HexDeploymentRows)continue;
            Bounds tileBounds=new Bounds(world-DeploymentTileOffset(coordinate),new Vector3(
                ActiveTileSize,0.2f,
                ActiveTileSize*(UsesHexDeployment?HexRowSpacing:1f)));
            if(!boundsInitialized)
            {
                mapBounds=tileBounds;
                combatBounds=tileBounds;
                boundsInitialized=true;
            }
            else
            {
                mapBounds.Encapsulate(tileBounds);
                combatBounds.Encapsulate(tileBounds);
            }
        }
        if(UsesHexDeployment)
        {
            combatBounds.Expand(new Vector3(ActiveTileSize,0f,ActiveTileSize));
            combatBounds.Encapsulate(new Vector3(
                combatBounds.center.x,combatBounds.center.y,
                combatBounds.max.z+ActiveTileSize*CombatArenaTopExtensionTiles));
            mapBounds.Encapsulate(combatBounds);
        }
#if UNITY_EDITOR
        if(UsesHexDeployment&&!GameFlowController.HasActiveExpeditionRequest)
        {
            CreateBoundaryLine("Combat Movement Boundary",combatBounds,
                new Color(1f,0.72f,0.12f,0.92f));
        }
#endif
        CreateBenchTiles(tileRoot,ref boundsInitialized);
        CreatePhysicsFloor();
    }

#if UNITY_EDITOR
    private void CreateBoundaryLine(string name,Bounds bounds,Color color)
    {
        GameObject boundary=new GameObject(name);
        boundary.transform.SetParent(placementMarkerRoot??transform,false);
        LineRenderer line=boundary.AddComponent<LineRenderer>();
        line.sharedMaterial=skillRadiusMarkerMaterial;
        line.useWorldSpace=true;
        line.loop=true;
        line.positionCount=4;
        line.startWidth=0.06f;
        line.endWidth=0.06f;
        line.startColor=color;
        line.endColor=color;
        line.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;
        line.receiveShadows=false;
        line.sortingOrder=45;
        const float y=0.04f;
        line.SetPositions(new[]
        {
            new Vector3(bounds.min.x,y,bounds.min.z),
            new Vector3(bounds.max.x,y,bounds.min.z),
            new Vector3(bounds.max.x,y,bounds.max.z),
            new Vector3(bounds.min.x,y,bounds.max.z)
        });
    }
#endif

    private void CreateBenchTiles(Transform tileRoot,ref bool boundsInitialized)
    {
        bool benchBoundsInitialized=false;
        Bounds benchBounds=new Bounds();
        for(int slot=0;slot<BenchSlotCount;slot++)
        {
            Vector2Int coordinate=BenchCoordinate(slot);
            Vector3 world=GridWorld(coordinate);
            GameObject tileObject=new GameObject("Battle Bench "+(slot+1));
            tileObject.transform.SetParent(tileRoot,false);
            tileObject.transform.position=world;
            MeshFilter filter=tileObject.AddComponent<MeshFilter>();filter.sharedMesh=benchTileMesh;
            Renderer renderer=tileObject.AddComponent<MeshRenderer>();renderer.sharedMaterial=tileMaterial;
            renderer.enabled=!UsesPointyHexTileArena;
            if(UsesPointyHexTileArena)
                CreateIsoTileVisual(tileRoot,coordinate,world);
            Tile tile=new Tile
            {
                coordinate=coordinate,gameObject=tileObject,renderer=renderer,world=world,
                walkable=false,bench=true
            };
            tile.baseColor=TileBaseColor(tile);
            tiles.Add(coordinate,tile);
            SetTileColor(tile,tile.baseColor);
            Bounds tileBounds=new Bounds(world-DeploymentTileOffset(coordinate),new Vector3(
                ActiveTileSize,0.2f,ActiveTileSize));
            if(!benchBoundsInitialized)
            {
                benchBounds=tileBounds;
                benchBoundsInitialized=true;
            }
            else benchBounds.Encapsulate(tileBounds);
            if(!boundsInitialized){mapBounds=tileBounds;boundsInitialized=true;}else mapBounds.Encapsulate(tileBounds);
        }
#if UNITY_EDITOR
        if(UsesHexDeployment&&benchBoundsInitialized&&
           !GameFlowController.HasActiveExpeditionRequest)
        {
            benchBounds.Encapsulate(new Vector3(
                benchBounds.center.x,benchBounds.center.y,
                benchBounds.max.z+ActiveTileSize*BenchArenaTopExtensionTiles));
            CreateBoundaryLine("Bench Deployment Boundary",benchBounds,
                new Color(0.72f,0.4f,1f,0.92f));
        }
#endif
    }

    private void CreatePhysicsFloor()
    {
        GameObject floor=new GameObject(
            UsesHexDeployment?"Hex Arena Physics Floor":"Arena Physics Floor");
        floor.transform.SetParent(transform,false);
        floor.transform.position=new Vector3(mapBounds.center.x,-0.14f,mapBounds.center.z);
        BoxCollider collider=floor.AddComponent<BoxCollider>();
        collider.center=Vector3.zero;
        collider.size=new Vector3(
            mapBounds.size.x+ActiveTileSize,0.25f,
            mapBounds.size.z+ActiveTileSize);
    }

    private static bool IsMapCoordinate(Vector2Int coordinate)
    {
        int c=coordinate.x,r=coordinate.y;
        return c>=0&&c<ActiveColumns&&r>=0&&r<ActiveRows;
    }

    private static Vector2Int BenchCoordinate(int slot)
    {
        return new Vector2Int(ActiveBenchStartColumn+slot,BenchRow);
    }

    private static int BenchSlotIndex(Vector2Int coordinate)
    {
        if(coordinate.y!=BenchRow)return -1;
        int slot=coordinate.x-ActiveBenchStartColumn;
        return slot>=0&&slot<BenchSlotCount?slot:-1;
    }

    private void ApplyBattlefieldLayoutForCurrentWave()
    {
        foreach(Tile tile in tiles.Values)
            if(!tile.bench)tile.walkable=true;
    }

    private static Color TileBaseColor(Tile tile)
    {
        Color neutral=BattleTileColor(tile.coordinate);
        if(tile.bench)return new Color(0.075f,0.18f,0.24f);
        if(!tile.walkable)return Color.Lerp(neutral,Color.black,0.52f);
        if(tile.deploymentTeam==Team.Player)return Color.Lerp(neutral,new Color(0.025f,0.32f,0.55f),0.48f);
        if(tile.deploymentTeam==Team.Enemy)return Color.Lerp(neutral,new Color(0.48f,0.055f,0.04f),0.42f);
        if(tile.neutralZone)return Color.Lerp(neutral,new Color(0.42f,0.34f,0.13f),0.34f);
        return neutral;
    }

    public static Color BattleTileColor(Vector2Int coordinate)
    {
        return ((coordinate.x+coordinate.y)&1)==0
            ?new Color(0.18f,0.22f,0.28f)
            :new Color(0.155f,0.195f,0.25f);
    }

    private void FrameCameraToMap()
    {
        FrameCameraToBattleArena(mainCamera,mapBounds);
    }

    private void CreateBattlefieldEnvironment()
    {
        if(meadowAmbientParticles!=null)
        {
            meadowAmbientParticles.gameObject.SetActive(false);
            Destroy(meadowAmbientParticles.gameObject);
        }
        meadowAmbientParticles=null;
        environmentBackdropReady=false;
        if(UsesPointyHexTileArena||mainCamera==null)return;
        string regionId=string.IsNullOrWhiteSpace(environmentPreviewRegionId)
            ?expeditionRun.regionId:environmentPreviewRegionId;
        string root=EnvironmentResourceRoot(regionId);
        Texture2D texture=Resources.Load<Texture2D>(root+"/BattleBackground")??
            Resources.Load<Texture2D>("Environment/PrimordialMeadow/BattleBackground");
        if(texture==null)return;
        mainCamera.clearFlags=CameraClearFlags.SolidColor;
        mainCamera.backgroundColor=Color.black;
        layeredBattleEnvironment=
            mainCamera.GetComponent<LayeredBattleEnvironment>()??
            mainCamera.gameObject.AddComponent<LayeredBattleEnvironment>();
        environmentBackdropReady=layeredBattleEnvironment.BuildMaster(mainCamera,texture);
        if(!environmentBackdropReady)return;
        foreach(Tile tile in tiles.Values)tile.renderer.enabled=false;
        meadowAmbientParticles=MeadowAmbientParticles.Create(transform,mainCamera,mapBounds,regionId);
    }

    private void FitEnvironmentBackdrop()
    {
        if(layeredBattleEnvironment!=null&&layeredBattleEnvironment.IsReady)
            layeredBattleEnvironment.Fit();
    }

    public static void FrameCameraToBattleArena(
        Camera camera,Bounds bounds)
    {
        if(camera==null)return;
        camera.orthographic=false;
        camera.fieldOfView=CameraFieldOfView;
        camera.transparencySortMode=UnityEngine.TransparencySortMode.CustomAxis;
        camera.transparencySortAxis=Vector3.forward;
        if(UsesPointyHexTileArena)
        {
            camera.clearFlags=CameraClearFlags.SolidColor;
            camera.backgroundColor=new Color(0.025f,0.035f,0.055f);
        }
        if(UsesHexDeployment&&!UsesPointyHexTileArena)
            bounds.Expand(new Vector3(
                ActiveTileSize*2f,0f,ActiveTileSize*0.75f));
        float pitch=(UsesHexDeployment
            ?HexDeploymentCameraPitchDegrees:CameraPitchDegrees)*Mathf.Deg2Rad;
        float aspect=Mathf.Max(1f,camera.aspect);
        float verticalHalfFov=camera.fieldOfView*0.5f*Mathf.Deg2Rad;
        float horizontalHalfFov=Mathf.Atan(Mathf.Tan(verticalHalfFov)*aspect);
        float widthDistance=(bounds.extents.x+ActiveTileSize*0.45f)/Mathf.Tan(horizontalHalfFov);
        float depthDistance=(bounds.extents.z+ActiveTileSize*0.65f)*Mathf.Sin(pitch)/Mathf.Tan(verticalHalfFov);
        float cameraDistance=Mathf.Max(widthDistance,depthDistance)*
            (UsesPointyHexTileArena?2.90002f:UsesHexDeployment?1.55f:1.30f);
        Vector3 center=bounds.center;
        float hexLookAhead=HexDeploymentCameraLookAhead;
        Vector3 lookTarget=UsesHexDeployment
            ?center+Vector3.forward*hexLookAhead
            :center+Vector3.back*1.8f;
        camera.transform.position=lookTarget+Vector3.back*(cameraDistance*Mathf.Cos(pitch))+Vector3.up*(cameraDistance*Mathf.Sin(pitch));
        camera.transform.rotation=Quaternion.LookRotation(lookTarget-camera.transform.position,Vector3.up);
        camera.nearClipPlane=0.1f;
        camera.farClipPlane=100f;
    }

    private bool SpawnTeams()
    {
        bool spawned=false;
        var teams=SpawnTeamsRoutine(value=>spawned=value);
        try{while(teams.MoveNext()){}}
        finally{(teams as IDisposable)?.Dispose();}
        return spawned;
    }

    private IEnumerator SpawnTeamsRoutine(Action<bool> spawned)
    {
        monsterDatabase=Resources.Load<MonsterDatabase>("MonsterData/MonsterDatabase");
        if(monsterDatabase==null)throw new InvalidOperationException("Monster database missing: Resources/MonsterData/MonsterDatabase");
        profileStore=new PlayerProfileStore();
        bool effectTest=CombatEffectTestConfiguration.Active;
        if(effectTest)playerProfile=CombatEffectTestConfiguration.CreateIsolatedProfile();
        else if(wavePreparationAcrossFrames)
        {
            playerProfile=null;
            yield return GameFrontend.LoadPlayerProfileAcrossFrames(profileStore,monsterDatabase,value=>playerProfile=value);
            if(playerProfile==null){spawned(false);yield break;}
            yield return null;
        }
        else if(!GameFrontend.TryLoadPlayerProfile(profileStore,monsterDatabase,out playerProfile))
            {spawned(false);yield break;}
        useRandomizedStartingRoster=effectTest||ShouldUseRandomizedStartingRoster(
            randomizeStartingAlliesForTesting,
            GameFlowController.HasActiveExpeditionRequest);
        bool resumed=false;
        List<OwnedMonsterSave> startingRoster;
        if(effectTest)
        {
            List<string> allyIds=
                CombatEffectTestConfiguration.ConfiguredMonsterIds(true);
            startingRoster=new List<OwnedMonsterSave>(allyIds.Count);
            for(int i=0;i<allyIds.Count;i++)
            {
                MonsterDefinition ally=RequireMonsterDefinition(allyIds[i]);
                OwnedMonsterSave monster=PlayerProfileStore.CreateMonster(
                    ally,"effect_test_ally_"+i,false);
                CombatEffectTestConfiguration.ApplyTestBaseline(
                    monster,CombatEffectTestConfiguration.AllyPersonalityId);
                startingRoster.Add(monster);
            }
            InitializeExpeditionRun(startingRoster);
            foreach(ExpeditionMonsterStateSave state in expeditionRun.monsters)
                CombatEffectTestConfiguration.ApplyTestProgression(state,true,
                    definition:RequireMonsterDefinition(state.monsterId));
            expeditionRun.runId="combat_effect_test";
            expeditionRun.maxDeploymentCount=8;
            expeditionRun.augmentDraftIds.Clear();
            expeditionRun.augmentDraftWave=0;
#if UNITY_EDITOR
            ConfigureReadabilityRun();
#endif
        }
        else if(!useRandomizedStartingRoster)
        {
            expeditionStore=new ExpeditionRunStore(
                playerProfile.profileId,profileStore.DirectoryPath);
            if(wavePreparationAcrossFrames)
            {
                bool loaded=false;
                yield return GameFrontend.LoadExpeditionAcrossFrames(expeditionStore,playerProfile,monsterDatabase,
                    value=>{expeditionRun=value;loaded=true;});
                if(!loaded){spawned(false);yield break;}
                yield return null;
            }
            else if(!GameFrontend.TryLoadExpedition(expeditionStore,playerProfile,
                monsterDatabase,out expeditionRun)){spawned(false);yield break;}
            if(expeditionRun!=null)
            {
                resumed=true;
                startingRoster=ExpeditionRunFactory.ResolveRoster(
                    expeditionRun,playerProfile,monsterDatabase);
            }
            else
            {
                startingRoster=BuildStartingRoster();
                InitializeExpeditionRun(startingRoster);
            }
        }
        else
        {
            startingRoster=BuildStartingRoster();
            InitializeExpeditionRun(startingRoster);
        }
        ResetMonsterRankUpFeedback();
        RestoreTransientRunState();
        if(wavePreparationAcrossFrames)yield return null;
        if(wavePreparationAcrossFrames)
            yield return Resources.LoadAsync<Texture2D>(EnvironmentResourceRoot(
                string.IsNullOrWhiteSpace(environmentPreviewRegionId)?expeditionRun.regionId:environmentPreviewRegionId)+"/BattleBackground");
        CreateBattlefieldEnvironment();
        if(wavePreparationAcrossFrames)yield return null;
        GameFlowController.Instance.Run.SyncCapturedMonsters(
            expeditionRun.capturedMonsterInstanceIds);
        additionalDeploymentSlots=Mathf.Max(0,expeditionRun.maxDeploymentCount-BaseDeploymentLimit);
        ApplyBattlefieldLayoutForCurrentWave();
        GeneratePlayerDeploymentZone();
        if(wavePreparationAcrossFrames)yield return null;
        for(int i=0;i<startingRoster.Count;i++)
        {
            OwnedMonsterSave owned=startingRoster[i];
            if(owned==null)continue;
            MonsterDefinition definition=monsterDatabase.Get(owned.monsterId);
            if(definition==null)
            {
                Debug.LogWarning("Owned monster definition missing; data preserved: "+owned.monsterId);
                continue;
            }
            if(!definition.enabled)continue;
            SpawnUnit(definition,Team.Player,BenchCoordinate(i),owned,true);
            if(wavePreparationAcrossFrames)yield return null;
        }

        var enemies=SpawnEnemiesForCurrentWaveRoutine();
        while(enemies.MoveNext())yield return enemies.Current;
        RestoreCaptureSelection();
        if(resumed)ArrangePlayerFormationFromRun();
        else ArrangePlayerFormationForNewWave(null);
        if(wavePreparationAcrossFrames)yield return WarmupUnitBodyBounds();
#if UNITY_EDITOR
        // The map introduction hides actors, so exercise navigation before it starts.
        if(wavePreparationAcrossFrames)yield return WarmupEditorNavigation();
#endif
        profileStore.Changed+=OnPlayerProfileChanged;
        if(expeditionRun.completionPending)
        {
            expeditionFailed=!expeditionRun.completion.victory;
            CompleteExpeditionPersistence(expeditionRun.completion.victory);
        }
        else if(effectTest)
        {
            if(CombatEffectTestConfiguration.ConsumeStartRequest())
            {
                resumeBattlePending=true;
                BeginWaveArrival();
            }
        }
        else if(resumed&&(CompletedItemChoiceVisible||
                         ReserveReinforcementChoiceVisible))
        {
            SaveExpeditionCheckpoint(
                expeditionRun.checkpoint,true);
        }
        else if(resumed&&
                expeditionRun.checkpoint==ExpeditionRunCheckpoint.InBattle)
        {
            resumeBattlePending=true;
            BeginWaveArrival();
        }
        else if(resumed&&
                expeditionRun.checkpoint==ExpeditionRunCheckpoint.GrowthReward)
        {
            OpenGrowthShop();
        }
        else if(resumed&&
                expeditionRun.checkpoint==ExpeditionRunCheckpoint.Shop)
        {
            OpenShop();
        }
        else if(resumed&&
                 expeditionRun.checkpoint==ExpeditionRunCheckpoint.AugmentDraft)
        {
            BeginAugmentDraftIntroduction();
            SaveExpeditionCheckpoint(
                ExpeditionRunCheckpoint.AugmentDraft,true);
        }
        else if(!CombatEffectTestConfiguration.Active&&
                 string.IsNullOrWhiteSpace(environmentPreviewRegionId))
            BeginMapIntroduction();
        spawned(true);
    }

    private List<OwnedMonsterSave> BuildStartingRoster()
    {
        if(!useRandomizedStartingRoster)
        {
            return playerProfile.expeditionPreset.rosterInstanceIds
                .Select(instanceId=>playerProfile.monsters.Find(item=>
                    item!=null&&item.instanceId==instanceId))
                .Where(item=>item!=null)
                .Take(RosterSize)
                .ToList();
        }

        List<MonsterDefinition> candidates=monsterDatabase.monsters
            .Where(definition=>definition!=null&&definition.enabled&&
                !string.IsNullOrWhiteSpace(definition.resourcePath)&&
                Resources.Load<GameObject>(definition.resourcePath)!=null)
            .ToList();
        System.Random random=new System.Random(Guid.NewGuid().GetHashCode());
        for(int i=candidates.Count-1;i>0;i--)
        {
            int swapIndex=random.Next(i+1);
            MonsterDefinition swap=candidates[i];
            candidates[i]=candidates[swapIndex];
            candidates[swapIndex]=swap;
        }
        List<OwnedMonsterSave> result=new List<OwnedMonsterSave>();
        int count=Mathf.Min(RosterSize,candidates.Count);
        for(int i=0;i<count;i++)
        {
            MonsterDefinition definition=candidates[i];
            string instanceId="test_random_"+definition.monsterId+"_"+
                Guid.NewGuid().ToString("N").Substring(0,8);
            result.Add(PlayerProfileStore.CreateMonster(
                definition,instanceId,false));
        }
        Debug.Log("[Test Roster] Random allies: "+
            string.Join(", ",result.Select(item=>monsterDatabase.Get(item.monsterId)?.displayName??item.monsterId)));
        return result;
    }

    private WaveScalingMasterRow CurrentWaveScaling()
    {
        WaveScalingMasterRow scaling=GameMasterData.WaveScaling(
            expeditionRun.regionId,expeditionRun.wave);
        if(scaling!=null)return scaling;
        return new WaveScalingMasterRow
        {
            wave=expeditionRun.wave,
            enemyCount=4,
            regionId=expeditionRun.regionId,
            enemyMonsterIds=string.Empty,
            hpMultiplier=1f,
            attackDamageMultiplier=1f,
            attackSpeedMultiplier=1f,
            moveSpeedMultiplier=1f,
            threatLabel="기본",
            enabled=true
        };
    }

    private bool UsesBalanceProductionRules
    {
        get
        {
#if UNITY_EDITOR
            return balanceTestProductionRules;
#else
            return false;
#endif
        }
    }

    private bool UsesCombatEffectTestRules=>
        CombatEffectTestConfiguration.Active&&!UsesBalanceProductionRules;

    private void SpawnEnemiesForCurrentWave()
    {
        var spawn=SpawnEnemiesForCurrentWaveRoutine();
        try{while(spawn.MoveNext()){}}
        finally{(spawn as IDisposable)?.Dispose();}
    }

    private IEnumerator SpawnEnemiesForCurrentWaveRoutine()
    {
        List<string> ids=null;
        if(UsesCombatEffectTestRules)
        {
            ids=CombatEffectTestConfiguration.ConfiguredMonsterIds(false);
        }
        else
        {
            WaveScalingMasterRow scaling=CurrentWaveScaling();
            if(wavePreparationAcrossFrames)
            {
                var composition=HunterRegionCatalog.BuildExpeditionWaveMonsterIdsAcrossFrames(
                    expeditionRun.regionId,expeditionRun.wave,scaling.enemyCount,
                    expeditionRun.runId,monsterDatabase,value=>ids=value);
                try{while(composition.MoveNext())yield return composition.Current;}
                finally{(composition as IDisposable)?.Dispose();}
            }
            else ids=HunterRegionCatalog.BuildExpeditionWaveMonsterIds(
                    expeditionRun.regionId,expeditionRun.wave,
                    scaling.enemyCount,expeditionRun.runId,monsterDatabase);
            HashSet<string> regionPool=new HashSet<string>(
                HunterRegionCatalog.Get(expeditionRun.regionId).MonsterIds(),
                StringComparer.Ordinal);
            if(ids.Count!=scaling.enemyCount||
               ids.Any(id=>!regionPool.Contains(id)||
                   monsterDatabase.Get(id)?.enabled!=true))
                throw new InvalidOperationException(
                    "Wave "+expeditionRun.wave+
                    " enemy_monster_ids is invalid for region "+
                    expeditionRun.regionId+".");
        }
        List<MonsterDefinition> definitions=ids.Select(RequireMonsterDefinition).ToList();
        List<Vector2Int> enemyStarts=GenerateEnemyDeployment(ids.Count);
        for(int i=0;i<ids.Count;i++)
        {
            MonsterDefinition definition=definitions[i];
            bool boss=i==0&&(expeditionRun.wave==8||expeditionRun.wave==ExpeditionWaveCount);
            string instanceId=boss
                ?"enemy_"+expeditionRun.runId+"_guardian_"+ids[i]
                :"enemy_"+expeditionRun.runId+"_wave_"+
                 expeditionRun.wave+"_"+i+"_"+ids[i];
            OwnedMonsterSave enemy=PlayerProfileStore.CreateMonster(definition,instanceId);
            if(UsesCombatEffectTestRules)
                CombatEffectTestConfiguration.ApplyTestBaseline(
                    enemy,CombatEffectTestConfiguration.EnemyPersonalityId);
            else
                MonsterInstanceGenerator.ApplyEnemyDifficultyQuality(enemy,expeditionRun.difficulty);
            Unit unit=SpawnUnit(definition,Team.Enemy,enemyStarts[i],enemy,false);
            ConfigureEnemyProgression(unit,i,definitions);
            if(wavePreparationAcrossFrames)
            {
                if(IsSceneReady){unit.model.SetActive(false);unit.ring.SetActive(false);}
                yield return null;
            }
        }
        if(!UsesCombatEffectTestRules&&!UsesBalanceProductionRules)
        {
            bool saveAcrossFrames=wavePreparationAcrossFrames&&Application.isPlaying&&isActiveAndEnabled;
            HunterShopSystem.RegisterEncounters(
                playerProfile,profileStore,monsterDatabase,ids,saveAcrossFrames);
            if(saveAcrossFrames)
                while(GameFrontend.HasPendingSave)yield return null;
        }
    }

    private void ConfigureEnemyProgression(
        Unit unit,int enemyIndex,IReadOnlyList<MonsterDefinition> enemyRoster)
    {
        if(unit==null)return;
        if(UsesCombatEffectTestRules)
        {
            unit.enemyProgression=new ExpeditionMonsterStateSave{monsterId=unit.definition.monsterId};
            CombatEffectTestConfiguration.ApplyTestProgression(unit.enemyProgression,false,enemyIndex,unit.definition);
            unit.expeditionRank=unit.enemyProgression.rank;
            unit.equippedEnemyItems.Clear();
            RefreshUnitFromOwnedData(unit,unit.definition,unit.ownedInstance);
            unit.hp=unit.maxHp;
            return;
        }
        unit.regionGuardian=expeditionRun.wave==ExpeditionWaveCount&&enemyIndex==0;
        unit.guardianPreview=expeditionRun.wave==8&&enemyIndex==0;
        bool boss=unit.regionGuardian||unit.guardianPreview;
        System.Random random=new System.Random(MonsterInstanceGenerator.StableSeed(
            expeditionRun.runId+"_wave_"+expeditionRun.wave+"_enemy_profile_"+enemyIndex));
        EnemyLootProfile profile=unit.guardianPreview
            ?new EnemyLootProfile{rank=ExpeditionMonsterRank.Rank3}
            :ExpeditionDropSystem.BuildEnemyProfile(
                expeditionRun.wave,enemyIndex,random,
                HunterRegionCatalog.Get(expeditionRun.regionId).order,
                CurrentWaveScaling().enemyCount);
        unit.expeditionRank=profile.rank;
        unit.enemyProgression=BuildEnemyProgression(
            unit.definition,profile.rank,
            MonsterInstanceGenerator.StableSeed(
                boss?expeditionRun.runId+"_guardian_traits_"+unit.definition.monsterId:
                expeditionRun.runId+"_wave_"+expeditionRun.wave+
                "_enemy_traits_"+enemyIndex+"_"+unit.definition.monsterId),
            enemyRoster);
        unit.enemyProgression.transcended=boss;
        if(boss)unit.enemyProgression.growthTotal=ExpeditionGrowthSystem.MaximumGrowth;
        unit.equippedEnemyItems.Clear();
        unit.equippedEnemyItems.AddRange(profile.equippedItems.Where(item=>item!=null));
        RefreshUnitFromOwnedData(unit,unit.definition,unit.ownedInstance);
        unit.hp=unit.maxHp;
        if(boss)
        {
            unit.combatEffectIcons.Show(CombatEffectIconKind.Royal);
        }
    }

    private static ExpeditionMonsterStateSave BuildEnemyProgression(
        MonsterDefinition definition,ExpeditionMonsterRank rank,int seed,
        IEnumerable<MonsterDefinition> enemyRoster)
    {
        ExpeditionMonsterStateSave state=new ExpeditionMonsterStateSave
        {
            monsterId=definition.monsterId,
            rank=rank
        };
        if(rank>=ExpeditionMonsterRank.Rank2)
            ExpeditionTraitProgression.AssignPreviewTraits(
                state,definition,new System.Random(seed),enemyRoster);
        return state;
    }

    private void RebuildEnemiesForCurrentWave()
    {
        var rebuild=RebuildEnemiesForCurrentWaveRoutine();
        try{while(rebuild.MoveNext()){}}
        finally{(rebuild as IDisposable)?.Dispose();}
    }

    private IEnumerator RebuildEnemiesForCurrentWaveRoutine()
    {
        List<Unit> enemies=units.Where(unit=>unit.team==Team.Enemy).ToList();
        recyclingEnemyVisuals=true;
        try{for(int i=0;i<enemies.Count;i++)
        {RemoveUnitFromRoster(enemies[i]);if(wavePreparationAcrossFrames)yield return null;}}
        finally{recyclingEnemyVisuals=false;}
        var spawn=SpawnEnemiesForCurrentWaveRoutine();
        while(spawn.MoveNext())yield return spawn.Current;
    }

    private void InitializeExpeditionRun(IReadOnlyList<OwnedMonsterSave> startingRoster)
    {
        combatContributionHistory.Clear();
        combatDataSelectedWave=-1;
        combatDataTeam=Team.Player;
        cachedCombatContributionWave=-1;
        combatDataPanelOpen=false;
        combatDataPanelSlide=0f;
        combatDataPanelLastRealtime=-1f;
        string regionId=GameFlowController.HasActiveExpeditionRequest
            ?GameFlowController.RequestedRegionId
            :CombatEffectTestConfiguration.Active
                ?CombatEffectTestConfiguration.RegionId:HunterRegionCatalog.FirstRegionId;
        ExpeditionDifficulty difficulty=GameFlowController.HasActiveExpeditionRequest
            ?GameFlowController.RequestedExpeditionDifficulty
            :ExpeditionDifficulty.Normal;
        if(GameFlowController.HasActiveExpeditionRequest&&
           !ExpeditionDifficultyProgress.IsUnlocked(
               playerProfile,regionId,difficulty))
            difficulty=ExpeditionDifficultyProgress.HighestUnlocked(
                playerProfile,regionId);
        expeditionRun=ExpeditionRunFactory.Create(
            playerProfile,monsterDatabase,startingRoster,
            regionId,
            StartingExpeditionLives,BaseDeploymentLimit,
            difficulty);
    }

    public static bool ShouldUseRandomizedStartingRoster(
        bool randomizationConfigured,
        bool productionExpeditionRequested)
    {
        return randomizationConfigured&&!productionExpeditionRequested;
    }

    public static List<MonsterDefinition> RosterQaBatch(
        MonsterDatabase database,int page)
    {
        if(database==null)return new List<MonsterDefinition>();
        List<MonsterDefinition> ordered=database.monsters
            .Where(definition=>definition!=null&&definition.enabled&&
                int.TryParse(definition.serialNumber,out int serial)&&
                serial>=1&&serial<=80)
            .OrderBy(definition=>int.Parse(definition.serialNumber))
            .ToList();
        int pageCount=Mathf.CeilToInt(ordered.Count/(float)RosterQaPageSize);
        if(pageCount==0)return ordered;
        int wrapped=((page%pageCount)+pageCount)%pageCount;
        return ordered.Skip(wrapped*RosterQaPageSize)
            .Take(RosterQaPageSize).ToList();
    }

    public static int RosterQaPageCount(MonsterDatabase database)
    {
        if(database==null)return 0;
        int count=database.monsters.Count(definition=>
            definition!=null&&definition.enabled&&
            int.TryParse(definition.serialNumber,out int serial)&&
            serial>=1&&serial<=80);
        return Mathf.CeilToInt(count/(float)RosterQaPageSize);
    }

    private void RestoreTransientRunState()
    {
        combatContributionHistory.Clear();
        if(expeditionRun.combatContributionHistory!=null)
        {
            foreach(ExpeditionWaveCombatContributionSave saved in
                    expeditionRun.combatContributionHistory)
            {
                if(saved==null)continue;
                WaveCombatContribution restored=new WaveCombatContribution
                {
                    wave=saved.wave,
                    won=saved.won,
                    live=false
                };
                RestoreCombatContributionTeam(saved.allies,restored.allies);
                RestoreCombatContributionTeam(saved.enemies,restored.enemies);
                combatContributionHistory.Add(restored);
            }
        }
        combatDataSelectedWave=expeditionRun.wave;
        cachedCombatContributionWave=-1;
        growthCardDraft.Clear();
        if(expeditionRun.growthCardDraft!=null)
            growthCardDraft.AddRange(expeditionRun.growthCardDraft.Where(
                entry=>entry!=null));
        if(expeditionRun.lastBlessingRewardIds!=null)
            expeditionRun.lastBlessingRewardIds.Clear();
        completedItemChoiceIds.Clear();
        if(expeditionRun.completedItemChoiceIds!=null)
            completedItemChoiceIds.AddRange(
                expeditionRun.completedItemChoiceIds.Where(
                    id=>!string.IsNullOrWhiteSpace(id)));
        completedItemChoiceSource=expeditionRun.completedItemChoiceSource??"";
        completedItemChoiceTarget=expeditionRun.completedItemChoiceTarget??"";
        completedItemChoiceRerollCount=Mathf.Max(
            0,expeditionRun.completedItemChoiceRerollCount);
        completedItemChoiceRevealStartedAt=completedItemChoiceIds.Count>0
            ?Time.unscaledTime:-1f;
        completedItemChoiceCommittedId="";
        completedItemChoiceCommitStartedAt=-1f;
        reserveReinforcementChoiceIds.Clear();
        ExpeditionAugmentSelectionSave reinforcement=
            ExpeditionAugmentRuntime.Selection(
                expeditionRun,ExpeditionAugmentRuntime.ReserveReinforcement);
        if(reinforcement!=null&&string.IsNullOrEmpty(reinforcement.runtimeState))
            PrepareReserveReinforcementChoice(reinforcement.deterministicSeed);
        growthCardDraftRerolled=expeditionRun.growthCardDraftRerolled;
        growthCardDraftSequence=expeditionRun.growthCardDraftSequence;
        augmentDraftSequence=expeditionRun.augmentDraftSequence;
        shopRollSequence=expeditionRun.shopRollSequence;
    }

    private void RestoreCombatContributionTeam(
        List<ExpeditionCombatContributionSave> saved,List<CombatContributionEntry> entries)
    {
        if(saved==null)return;
        foreach(ExpeditionCombatContributionSave unit in saved)
        {
            if(unit==null)continue;
            MonsterDefinition definition=monsterDatabase.Get(unit.monsterId);
            entries.Add(new CombatContributionEntry
            {
                stableId=unit.monsterInstanceId,
                definition=definition,
                displayName=string.IsNullOrWhiteSpace(unit.displayName)
                    ?definition?.displayName??unit.monsterId:unit.displayName,
                damageDealt=unit.damageDealt,
                damageTaken=unit.damageTaken,
                healingReceived=unit.healingReceived,
                comboActivations=unit.comboActivations,
                comboBonusDamage=unit.comboBonusDamage,
                survived=unit.survived
            });
        }
    }

    private static void SaveCombatContributionTeam(
        List<CombatContributionEntry> entries,List<ExpeditionCombatContributionSave> saved)
    {
        foreach(CombatContributionEntry unit in entries)
        {
            if(unit==null)continue;
            saved.Add(new ExpeditionCombatContributionSave
            {
                monsterInstanceId=unit.stableId,
                monsterId=unit.definition==null?"":unit.definition.monsterId,
                displayName=unit.displayName,
                damageDealt=unit.damageDealt,
                damageTaken=unit.damageTaken,
                healingReceived=unit.healingReceived,
                comboActivations=unit.comboActivations,
                comboBonusDamage=unit.comboBonusDamage,
                survived=unit.survived
            });
        }
    }

    private void SyncTransientRunState()
    {
        expeditionRun.combatContributionHistory.Clear();
        foreach(WaveCombatContribution snapshot in combatContributionHistory)
        {
            if(snapshot==null)continue;
            ExpeditionWaveCombatContributionSave saved=
                new ExpeditionWaveCombatContributionSave
                {
                    wave=snapshot.wave,
                    won=snapshot.won
                };
            SaveCombatContributionTeam(snapshot.allies,saved.allies);
            SaveCombatContributionTeam(snapshot.enemies,saved.enemies);
            expeditionRun.combatContributionHistory.Add(saved);
        }
        expeditionRun.growthCardDraft.Clear();
        expeditionRun.growthCardDraft.AddRange(growthCardDraft.Select(entry=>
            new CombatGrowthCardDraftEntry
            {
                cardId=entry.cardId,
                rarity=entry.rarity
            }));
        expeditionRun.lastBlessingRewardIds.Clear();
        expeditionRun.completedItemChoiceIds.Clear();
        expeditionRun.completedItemChoiceIds.AddRange(
            completedItemChoiceIds);
        expeditionRun.completedItemChoiceSource=
            completedItemChoiceSource??"";
        expeditionRun.completedItemChoiceTarget=
            completedItemChoiceTarget??"";
        expeditionRun.completedItemChoiceRerollCount=
            Mathf.Max(0,completedItemChoiceRerollCount);
        expeditionRun.growthCardDraftRerolled=growthCardDraftRerolled;
        expeditionRun.growthCardDraftSequence=growthCardDraftSequence;
        expeditionRun.augmentDraftSequence=augmentDraftSequence;
        expeditionRun.shopRollSequence=shopRollSequence;
    }

    private bool CanPersistExpeditionRun=>
        expeditionStore!=null&&playerProfile!=null&&monsterDatabase!=null&&
        expeditionRun!=null&&
        expeditionRun.status==ExpeditionRunStatus.Active&&
        !useRandomizedStartingRoster
#if UNITY_EDITOR
        &&!rosterQaMode
#endif
        ;

    private void SaveExpeditionCheckpoint(
        ExpeditionRunCheckpoint checkpoint,bool syncFormation,Action saved=null,bool acrossFrames=true)
    {
        if(!CanPersistExpeditionRun){saved?.Invoke();return;}
#if UNITY_EDITOR
        if(balanceTestRunning||mlEpisodeActive||corruptionDiagnosticRunning)
        {saved?.Invoke();return;}
#endif
        if(checkpoint==ExpeditionRunCheckpoint.InBattle)
        {
            expeditionRun.activeBattleWave=expeditionRun.wave;
            if(expeditionRun.activeBattleSeed==0)
            {
                expeditionRun.activeBattleSeed=MonsterInstanceGenerator.StableSeed(
                    expeditionRun.runId+"_battle_"+expeditionRun.wave);
                if(expeditionRun.activeBattleSeed==0)
                    expeditionRun.activeBattleSeed=1;
            }
        }
        else
        {
            expeditionRun.activeBattleWave=0;
            expeditionRun.activeBattleSeed=0;
        }
        expeditionRun.checkpoint=checkpoint;
        if(syncFormation&&!battleStarted&&!battleEnding)
            SyncExpeditionFormation();
        SyncTransientRunState();
        if(acrossFrames&&Application.isPlaying&&isActiveAndEnabled)
        {
            GameFrontend.TrySaveProgressAcrossFrames(()=>
            {
                if(expeditionRun.status!=ExpeditionRunStatus.Active)return null;
                var profileWrite=profileStore.PrepareSaveFile(playerProfile);
                var runWrite=expeditionStore.PrepareSaveActive(expeditionRun,playerProfile,monsterDatabase);
                return ()=>{profileWrite();runWrite();};
            },profileStore.DirectoryPath,saved);
            return;
        }
        GameFrontend.TrySaveProgress(()=>
        {
            if(expeditionRun.status!=ExpeditionRunStatus.Active)return;
            profileStore.Save(playerProfile,false);
            expeditionStore.SaveActive(expeditionRun,playerProfile,monsterDatabase);
            saved?.Invoke();
        },profileStore.DirectoryPath);
    }

    public bool SaveBeforeLeaving()
    {
        if(wavePreparationAcrossFrames||GameFrontend.HasPendingSave)return false;
        if(CanPersistExpeditionRun)
            SaveExpeditionCheckpoint(expeditionRun.checkpoint,true,null,false);
        return !GameFrontend.HasPendingSave;
    }

    private void SyncExpeditionFormation()
    {
        foreach(Unit unit in units)
        {
            if(unit==null||unit.team!=Team.Player||
               unit.augmentShadowClone)continue;
            ExpeditionMonsterStateSave state=
                ExpeditionItemSystem.MonsterState(
                    expeditionRun,unit.stableId);
            if(state==null)continue;
            bool onBench=tiles.TryGetValue(
                unit.currentTile,out Tile tile)&&tile.bench;
            state.deployed=!unit.inStorage&&!onBench;
            state.deploymentX=unit.currentTile.x;
            state.deploymentY=unit.currentTile.y;
            state.benchSlot=onBench
                ?BenchSlotIndex(unit.currentTile):-1;
            state.currentHpRatio=1f;
        }
    }

    private void CompleteExpeditionPersistence(bool victory)
    {
        if(!CanPersistExpeditionRun)
        {
            resultText=victory?ExpeditionWaveCount+"Wave 탐험 완료":
                "탐험 실패 - 목숨을 모두 잃었습니다";
            return;
        }
        SyncTransientRunState();
        GameFrontend.TrySaveProgress(()=>
        {
            ExpeditionCompletionSave receipt=expeditionStore.SettleAndComplete(
                expeditionRun,victory,playerProfile,profileStore,monsterDatabase);
            PermanentResearchSettlement research=receipt.research;
            GameFlowController.Instance.Run.RegisterPlayerExperienceSettlement(
                research.experienceBefore,research.experienceAfter,
                research.experience,research.levelBefore,research.levelAfter);
            GameFlowController.Instance.Run.RegisterRareCaptureNetReward(
                receipt.rareCaptureNets);
            if(receipt.firstBeginnerClear)
                GameFlowController.Instance.Run.RegisterExpeditionProgressUnlock(
                    expeditionRun.regionId,receipt.nextRegionId,
                    ExpeditionDifficulty.Normal);
            resultText=victory?ExpeditionWaveCount+"Wave 탐험 완료":
                "탐험 실패 - 목숨을 모두 잃었습니다";
        },profileStore.DirectoryPath);
    }

    public OwnedMonsterSave AcquireMonster(string monsterId)
    {
        if(profileStore==null||playerProfile==null||monsterDatabase==null)
            throw new InvalidOperationException("Player profile is not initialized.");
        return profileStore.AcquireMonster(playerProfile,monsterDatabase,monsterId);
    }

    public bool UpdateOwnedMonster(string instanceId,Action<OwnedMonsterSave> mutation)
    {
        return profileStore!=null&&profileStore.UpdateMonster(
            playerProfile,monsterDatabase,instanceId,mutation);
    }

    public bool RemoveOwnedMonster(string instanceId)
    {
        return profileStore!=null&&profileStore.RemoveMonster(
            playerProfile,monsterDatabase,instanceId);
    }

    private void OnPlayerProfileChanged(PlayerProfileSave changedProfile)
    {
        if(useRandomizedStartingRoster)return;
        if(changedProfile!=playerProfile||syncingOwnedRoster)return;
        SyncOwnedRoster();
    }

    private void SyncOwnedRoster()
    {
        syncingOwnedRoster=true;
        try
        {
            Dictionary<string,Unit> existing=units
                .Where(unit=>unit.team==Team.Player&&unit.ownedInstance!=null)
                .GroupBy(unit=>unit.ownedInstance.instanceId)
                .ToDictionary(group=>group.Key,group=>group.First(),StringComparer.Ordinal);
            HashSet<string> rosterIds=new HashSet<string>(
                playerProfile.expeditionPreset.rosterInstanceIds
                    .Where(id=>playerProfile.monsters.Any(item=>item!=null&&item.instanceId==id&&
                        monsterDatabase.Get(item.monsterId)?.enabled==true)),
                StringComparer.Ordinal);

            for(int i=0;i<playerProfile.expeditionPreset.rosterInstanceIds.Count;i++)
            {
                string instanceId=playerProfile.expeditionPreset.rosterInstanceIds[i];
                OwnedMonsterSave owned=playerProfile.monsters.Find(item=>item!=null&&item.instanceId==instanceId);
                if(owned==null)continue;
                MonsterDefinition definition=monsterDatabase.Get(owned.monsterId);
                if(definition==null)
                {
                    Debug.LogWarning("Owned monster definition missing; data preserved: "+owned.monsterId);
                    continue;
                }
                if(!definition.enabled)continue;

                if(!existing.TryGetValue(owned.instanceId,out Unit unit))
                {
                    unit=SpawnUnit(definition,Team.Player,BenchCoordinate(i),owned,true);
                    existing.Add(owned.instanceId,unit);
                }
                RefreshUnitFromOwnedData(unit,definition,owned);
            }

            for(int i=units.Count-1;i>=0;i--)
            {
                Unit unit=units[i];
                if(unit.team==Team.Player&&!rosterIds.Contains(unit.stableId)&&
                   !ExpeditionRunFactory.IsTemporaryRosterMember(
                       expeditionRun,unit.stableId))
                    RemoveUnitFromRoster(unit);
            }

        }
        finally
        {
            syncingOwnedRoster=false;
        }
    }

    private void RefreshUnitFromOwnedData(Unit unit,MonsterDefinition definition,OwnedMonsterSave owned)
    {
        float previousVisualScale=unit.combatBodyScale;
        float previousMax=Mathf.Max(0.01f,unit.maxHp);
        float hpRatio=Mathf.Clamp01(unit.hp/previousMax);
        CombatGrowthCardModifiers growth=GrowthModifiers(unit.team);
        ExpeditionMonsterStateSave expeditionMonster=unit.team==Team.Enemy
            ?unit.enemyProgression
            :expeditionRun==null?null:expeditionRun.monsters.Find(
                item=>item!=null&&item.instanceId==owned.instanceId);
        CombatItemModifiers items=unit.team==Team.Enemy
            ?ExpeditionItemSystem.Aggregate(unit.equippedEnemyItems)
            :ExpeditionItemSystem.Aggregate(expeditionRun,expeditionMonster);
        ExpeditionAugmentCombatModifiers augments=unit.team==Team.Player
            ?ExpeditionAugmentRuntime.CombatModifiers(
                expeditionRun,owned.instanceId,expeditionRun.wave)
            :new ExpeditionAugmentCombatModifiers();
        if(unit.team==Team.Enemy&&expeditionMonster!=null&&expeditionMonster.transcended)
            ExpeditionAugmentRuntime.ApplyTranscendenceModifiers(augments);
        ExpeditionMonsterRank rank=unit.team==Team.Enemy
            ?unit.expeditionRank
            :expeditionMonster==null?ExpeditionMonsterRank.Rank1:expeditionMonster.rank;
        ExpeditionGrowthBonuses personalGrowth=unit.team==Team.Player
            ?ExpeditionGrowthSystem.Bonuses(expeditionMonster,owned,rank)
            :new ExpeditionGrowthBonuses();
        float researchHealth=unit.team==Team.Player
            ?1f+PermanentResearchSystem.Value(
                playerProfile,PermanentResearchSystem.Health):1f;
        float researchAttack=unit.team==Team.Player
            ?1f+PermanentResearchSystem.Value(
                playerProfile,PermanentResearchSystem.Attack):1f;
        float researchDefense=unit.team==Team.Player
            ?1f+PermanentResearchSystem.Value(
                playerProfile,PermanentResearchSystem.Defense):1f;
        float researchResistance=unit.team==Team.Player
            ?1f+PermanentResearchSystem.Value(
                playerProfile,PermanentResearchSystem.Resistance):1f;
        float researchAttackSpeed=unit.team==Team.Player
            ?1f+PermanentResearchSystem.Value(
                playerProfile,PermanentResearchSystem.AttackSpeed):1f;
        unit.itemModifiers=items;
        if(unit.team==Team.Player)
            unit.itemModifiers.criticalChance+=PermanentResearchSystem.Value(
                playerProfile,PermanentResearchSystem.CriticalTraining);
        unit.definition=definition;
        unit.regionDamageMultiplier=HunterRegionCatalog.RegionDamageMultiplier(
            expeditionRun?.regionId,definition.monsterId);
        unit.ownedInstance=owned;
        unit.personalityPolicy=PersonalityCombatPolicy.From(owned);
        unit.eccentricCriterion=PersonalityCombatPolicy.EccentricCriterion(
            owned.personalitySeed);
        unit.activeTraitIds.Clear();
        unit.activeTraitIds.AddRange(MonsterTraitRuntime.ActiveTraitIds(definition,owned,expeditionMonster));
        AddDebugTraitOverrides(unit);
        if(UsesCombatEffectTestRules)
            CombatEffectTestConfiguration.AddSelectedTraits(
                unit.activeTraitIds,unit.team==Team.Player);
        unit.stableId=owned.instanceId;
        unit.displayName=(unit.guardianPreview?"거대 수호자 ":unit.regionGuardian?"수호자 ":"")+definition.displayName;
        unit.skillId=definition.skillId??string.Empty;
        unit.deploymentSlots=augments.deploymentSlots;
        unit.maxHp=CombatStatFormula.BattleHealth(
            (definition.maxHp*Mathf.Max(0.01f,owned.hpMultiplier)+
             personalGrowth.maxHealth)*
            (1f+growth.maxHealthBonus+items.maxHealthBonus+
             augments.maxHealthBonus)*researchHealth);
        unit.damage=(definition.attackDamage*Mathf.Max(0.01f,owned.damageMultiplier)+
                     personalGrowth.attackDamage)*
                    (1f+growth.attackDamageBonus+items.attackDamageBonus+
                     augments.attackDamageBonus)*researchAttack;
        unit.defense=CombatStatFormula.BattleDefense(Mathf.Max(
            0f,definition.defense*
                Mathf.Max(0.01f,owned.defenseMultiplier)+
            personalGrowth.defense+items.defenseBonus+
            growth.defenseBonus+augments.defenseBonus)*
            Mathf.Max(0.01f,augments.defenseMultiplier)*researchDefense);
        unit.statusResistance=Mathf.Max(
            0f,definition.statusResistance*
                Mathf.Max(0.01f,owned.statusResistanceMultiplier)+
            personalGrowth.statusResistance+items.statusResistanceBonus+
            growth.statusResistanceBonus+augments.statusResistanceBonus)*
            Mathf.Max(0.01f,augments.statusResistanceMultiplier)*
            researchResistance;
        unit.speedTilesPerSecond=definition.moveSpeedTilesPerSecond*
            Mathf.Max(0.01f,owned.moveSpeedMultiplier)*CombatMovementSpeedScale;
        float attackSpeedScore=100f/Mathf.Max(0.01f,definition.attackInterval)*
            Mathf.Max(0.01f,owned.attackSpeedMultiplier)+
            personalGrowth.attackSpeedScore;
        attackSpeedScore*=Mathf.Max(0.01f,
            1f+growth.attackSpeedBonus+items.attackSpeedBonus+
            augments.attackSpeedBonus)*researchAttackSpeed;
        unit.attackInterval=CombatStatFormula.BattleAttackInterval(
            100f/Mathf.Max(0.01f,attackSpeedScore))*CombatAttackIntervalScale;
        unit.damageTakenMultiplier=growth.damageTakenMultiplier*
                                   Mathf.Max(0f,1f-items.damageReductionBonus)*
                                   Mathf.Max(0f,1f-augments.damageReduction)*
                                   HunterRegionCatalog.AllDamageTakenMultiplier(
                                       expeditionRun?.regionId);
        unit.skillCooldownDuration=CombatStatFormula.Cooldown(
            BaseSkillCooldown(unit.skillId),
            items.skillCooldownReductionBonus+growth.cooldownRecoverySpeed,
            augments.skillCooldownMultiplier);
        if(unit.rank3MantisReaper)unit.skillCooldownDuration*=.75f;
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_rank2_vitality"))unit.maxHp*=1.3f;
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_rank2_might"))unit.damage*=1.25f;
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_rank2_armor"))unit.defense*=1.35f;
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_rank2_resistance"))unit.statusResistance*=1.3f;
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_rank2_mobility"))unit.speedTilesPerSecond*=1.25f;
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_rank2_haste"))unit.attackInterval/=1.25f;
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_rank2_cycle"))unit.skillCooldownDuration*=0.8f;
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_skill_instant_manifest"))
            unit.skillCooldownDuration*=0.8f;
        if(augments.minimumSkillCooldown>0f)
            unit.skillCooldownDuration=Mathf.Max(
                unit.skillCooldownDuration,augments.minimumSkillCooldown);
        unit.augmentBasicDamageMultiplier=augments.basicAttackDamageMultiplier;
        unit.augmentSkillPowerMultiplier=augments.skillPowerMultiplier*
            (unit.team==Team.Player
                ?PermanentResearchSystem.SkillPowerMultiplier(playerProfile):1f);
        unit.augmentSkillAreaMultiplier=augments.skillAreaMultiplier;
        unit.augmentHarmfulDurationMultiplier=augments.harmfulDurationMultiplier;
        unit.augmentTranscended=augments.transcended;
        unit.attackRange=definition.attackRange;
        unit.collisionRadius=definition.collisionRadius*
            (UsesHexDeployment?HexDeploymentUnitScale:1f);
        if(unit.team==Team.Enemy)
        {
            unit.maxHp*=RankHealthMultiplier(rank);
            unit.damage*=RankDamageMultiplier(rank);
        }
        ApplyRankVisualScale(unit,expeditionMonster,rank,
            augments.modelScaleMultiplier*(unit.guardianPreview
                ?GuardianPreviewVisualScale:1f));
        if(unit.team==Team.Enemy&&expeditionRun!=null)
        {
            WaveScalingMasterRow scaling=CurrentWaveScaling();
            unit.maxHp*=Mathf.Max(0.01f,scaling.hpMultiplier*
                ExpeditionDifficultyRules.HealthMultiplier(
                    expeditionRun.difficulty));
            unit.damage*=Mathf.Max(0.01f,scaling.attackDamageMultiplier);
            unit.attackInterval/=Mathf.Max(0.01f,scaling.attackSpeedMultiplier);
            unit.speedTilesPerSecond*=Mathf.Max(0.01f,scaling.moveSpeedMultiplier);
            if(unit.guardianPreview)unit.maxHp*=GuardianPreviewHealthMultiplier;
        }
        unit.hp=battleStarted?unit.maxHp*hpRatio:unit.maxHp;
        RefreshReturnMarkAura(unit);
        RefreshTranscendenceVisual(unit);
        ObserveMonsterRankUpWithScale(unit,previousVisualScale);
    }

    private static void RefreshTranscendenceVisual(Unit unit)
    {
        bool active=unit!=null&&unit.alive&&unit.augmentTranscended&&
                    unit.model!=null&&unit.model.activeInHierarchy;
        if(!active)
        {
            if(unit!=null&&unit.transcendenceFlameOutline!=null)
                Destroy(unit.transcendenceFlameOutline.gameObject);
            if(unit!=null)unit.transcendenceFlameOutline=null;
            PixelCombatEffect.StopBearSpiritAura(unit?.transcendenceFlameParticles);
            if(unit!=null)unit.transcendenceFlameParticles=null;
            return;
        }
        SpriteRenderer renderer=unit.spriteAnimation==null
            ?unit.model.GetComponentInChildren<SpriteRenderer>()
            :unit.spriteAnimation.GetComponent<SpriteRenderer>();
        if(renderer==null)return;
        if(unit.transcendenceFlameOutline==null)
            unit.transcendenceFlameOutline=
                PixelCombatEffect.PlayTranscendenceFlameOutline(renderer);
        if(unit.transcendenceFlameParticles!=null)return;
        Transform anchor=unit.spriteAnimation==null
            ?unit.model.transform:unit.spriteAnimation.transform;
        unit.transcendenceFlameParticles=
            PixelCombatEffect.PlayBearSpiritAura(anchor,renderer);
        if(unit.transcendenceFlameParticles==null)return;
        unit.transcendenceFlameParticles.name="Transcendence Red Flame Aura";
        ParticleSystem.MainModule main=unit.transcendenceFlameParticles.main;
        main.startLifetime=new ParticleSystem.MinMaxCurve(0.45f,0.78f);
        main.startSize=new ParticleSystem.MinMaxCurve(0.06f,0.13f);
        main.startColor=new ParticleSystem.MinMaxGradient(
            new Color(0.72f,0.01f,0.005f,0.92f),
            new Color(1f,0.32f,0.025f,0.96f));
        ParticleSystem.EmissionModule emission=unit.transcendenceFlameParticles.emission;
        emission.rateOverTime=13f;
    }

    private static void RefreshReturnMarkAura(Unit unit)
    {
        bool equipped=unit!=null&&unit.alive&&HasEffect(unit,"ReturnMark");
        if(!equipped)
        {
            PixelCombatEffect.StopBearSpiritAura(unit?.returnMarkAura);
            if(unit!=null)unit.returnMarkAura=null;
            return;
        }
        if(unit.returnMarkAura!=null)return;

        Transform anchor=unit.spriteAnimation==null
            ?unit.model.transform:unit.spriteAnimation.transform;
        SpriteRenderer renderer=unit.spriteAnimation==null
            ?unit.model.GetComponentInChildren<SpriteRenderer>()
            :unit.spriteAnimation.GetComponent<SpriteRenderer>();
        unit.returnMarkAura=PixelCombatEffect.PlayBearSpiritAura(anchor,renderer);
        if(unit.returnMarkAura==null)return;
        unit.returnMarkAura.name="Return Mark Equipped Aura";
        ParticleSystem.MainModule main=unit.returnMarkAura.main;
        main.startLifetime=new ParticleSystem.MinMaxCurve(0.75f,1.1f);
        main.startSize=new ParticleSystem.MinMaxCurve(0.05f,0.09f);
        main.startColor=new ParticleSystem.MinMaxGradient(
            new Color(0.22f,0.84f,1f,0.9f),new Color(0.72f,0.38f,1f,0.9f));
        ParticleSystem.EmissionModule emission=unit.returnMarkAura.emission;
        emission.rateOverTime=8f;
        ParticleSystem.ShapeModule shape=unit.returnMarkAura.shape;
        shape.scale=new Vector3(0.58f,0.16f,0.02f);
        ParticleSystem.VelocityOverLifetimeModule velocity=
            unit.returnMarkAura.velocityOverLifetime;
        velocity.y=0.38f;
    }

    public static float RankVisualScale(ExpeditionMonsterRank rank)
    {
        if(rank>=ExpeditionMonsterRank.Rank3)return 1.3f;
        if(rank>=ExpeditionMonsterRank.Rank2)return 1.15f;
        return 1f;
    }

    public static int DisplayStarCount(ExpeditionMonsterStateSave state)
    {
        if(state!=null&&state.transcended)return 4;
        return state==null?1:(int)state.rank;
    }

    public static float RankHealthMultiplier(ExpeditionMonsterRank rank)
    {
        if(rank>=ExpeditionMonsterRank.Rank3)
            return Mathf.Max(0.01f,GameMasterData.ExpeditionInt("rank3_health_percent",250)/100f);
        if(rank>=ExpeditionMonsterRank.Rank2)
            return Mathf.Max(0.01f,GameMasterData.ExpeditionInt("rank2_health_percent",160)/100f);
        return 1f;
    }

    public static float RankDamageMultiplier(ExpeditionMonsterRank rank)
    {
        if(rank>=ExpeditionMonsterRank.Rank3)
            return Mathf.Max(0.01f,GameMasterData.ExpeditionInt("rank3_damage_percent",160)/100f);
        if(rank>=ExpeditionMonsterRank.Rank2)
            return Mathf.Max(0.01f,GameMasterData.ExpeditionInt("rank2_damage_percent",125)/100f);
        return 1f;
    }

    private void ApplyRankVisualScale(
        Unit unit,ExpeditionMonsterStateSave expeditionMonster,
        ExpeditionMonsterRank effectiveRank,float augmentScale)
    {
        if(unit==null||unit.model==null)return;
        ExpeditionMonsterRank rank=unit.team==Team.Enemy
            ?unit.expeditionRank
            :effectiveRank;
        unit.combatBodyScale=RankVisualScale(rank)*Mathf.Max(0.1f,augmentScale);
        float multiplier=unit.combatBodyScale*
            (UsesHexDeployment?HexDeploymentMonsterVisualScale:1f);
        unit.model.transform.localScale=unit.baseModelScale*multiplier;
        unit.visualHeightOffset=
            (unit.baseVisualHeightOffset-PixelMonsterGroundOffset)*multiplier+
            PixelMonsterGroundOffset;
        Vector3 ground=Flat(unit.model.transform.position);
        unit.model.transform.position=ground+Vector3.up*unit.visualHeightOffset;
        CacheMeleeReadabilityBody(unit);
        ClearRoute(unit);ReleaseAttackSlot(unit);
        unit.targetRing?.SetRadius(Mathf.Max(.3f,CombatBodyRadius(unit)*1.15f));
    }

    private CombatGrowthCardModifiers GrowthModifiers(Team team)
    {
        if(team!=Team.Player||expeditionRun==null||
           expeditionRun.growthCards==null)return emptyGrowthModifiers;
        List<CombatGrowthCardSelectionSave> cards=expeditionRun.growthCards;
        if(cachedPlayerGrowthModifiers==null||
           !ReferenceEquals(cachedGrowthCards,cards)||
           cachedGrowthCardCount!=cards.Count)
        {
            cachedGrowthCards=cards;
            cachedGrowthCardCount=cards.Count;
            cachedPlayerGrowthModifiers=CombatGrowthCardCatalog.Aggregate(cards);
        }
        return cachedPlayerGrowthModifiers;
    }

    private static void ScaleItemModifiers(CombatItemModifiers items,float multiplier)
    {
        if(items==null)return;
        items.attackDamageBonus*=multiplier;
        items.attackSpeedBonus*=multiplier;
        items.maxHealthBonus*=multiplier;
        items.damageReductionBonus*=multiplier;
        items.criticalChance*=multiplier;
        items.criticalDamageBonus*=multiplier;
        items.skillPowerBonus*=multiplier;
        items.defenseBonus*=multiplier;
        items.statusResistanceBonus*=multiplier;
        items.skillCooldownReductionBonus*=multiplier;
    }

    private static float BaseSkillCooldown(string skillId)
    {
        SkillMasterRow skill=GameMasterData.Skill(skillId);
        return skill==null?0f:Mathf.Max(0f,skill.baseCooldown);
    }

    private float InitialSkillCooldown(Unit unit)
    {
        float cooldown=CombatStatFormula.BattleInitialSkillCooldown(
            unit==null?0f:unit.skillCooldownDuration);
        if(unit!=null&&unit.team==Team.Player&&
           PermanentResearchSystem.Unlocked(
               playerProfile,PermanentResearchSystem.AdvancePreparation))
            cooldown*=1f-Mathf.Clamp01(PermanentResearchSystem.Value(
                playerProfile,PermanentResearchSystem.AdvancePreparation));
        return cooldown;
    }

    private static float SkillValue(string id,Func<SkillMasterRow,float> selector,float fallback)
    {
        SkillMasterRow row=GameMasterData.Skill(id);
        return row==null?fallback:selector(row);
    }

    private void ConfigureSkillExecutor()
    {
        skillExecutor=new MonsterSkillExecutor<SkillExecutionContext>();
        skillExecutor.Register("GuardianTaunt",MonsterSkillTrigger.Active,
            (context,skill)=>UseGuardianTaunt(context.source,skill));
        skillExecutor.Register("AssassinLeap",MonsterSkillTrigger.Active,
            (context,skill)=>BeginAssassinLeap(context.source,skill));
        skillExecutor.Register("TongueHarpoon",MonsterSkillTrigger.Active,
            (context,skill)=>BeginTongueHarpoon(context.source,skill));
        skillExecutor.Register("EarthPulse",MonsterSkillTrigger.Active,
            (context,skill)=>BeginEarthPulse(context.source,skill));
        skillExecutor.Register("MagicStarBarrage",MonsterSkillTrigger.Active,
            (context,skill)=>BeginMagicStarBarrage(context.source,skill));
        skillExecutor.Register("ShadowSlash",MonsterSkillTrigger.Active,
            (context,skill)=>BeginShadowSlash(context.source,skill));
        skillExecutor.Register("DeathRoll",MonsterSkillTrigger.Active,
            (context,skill)=>BeginDeathRoll(context.source,skill));
        skillExecutor.Register("FangLock",MonsterSkillTrigger.Active,
            (context,skill)=>BeginFangLock(context.source,skill));
        skillExecutor.Register("FightingSpirit",MonsterSkillTrigger.Active,
            (context,skill)=>BeginBearFightingSpirit(context.source,skill));
        skillExecutor.Register("ThreeSidedHunt",MonsterSkillTrigger.Active,
            (context,skill)=>BeginThreeSidedHunt(context.source,skill));
        skillExecutor.Register("Skyfall",MonsterSkillTrigger.Active,
            (context,skill)=>BeginGriffinSkyfall(context.source,skill));
        skillExecutor.Register("HighHeadSlam",MonsterSkillTrigger.Active,
            (context,skill)=>UseGiraffeHighHeadSlam(context.source,skill));
        skillExecutor.Register("ClusterBreath",MonsterSkillTrigger.Active,
            (context,skill)=>UseClusterBreath(context.source,skill));
        skillExecutor.Register("GiantCaptureWeb",MonsterSkillTrigger.Active,
