    private void RemoveUnitFromRoster(Unit unit)
    {
        if(unit==null)return;
        if(capturePresentationTarget==unit)CancelCapturePresentation();
        if(unit.captureDeparture!=null)StopCoroutine(unit.captureDeparture);
        if(captureTarget==unit)captureTarget=null;
        if(selectedUnit==unit)SetSelectedUnit(null);
        if(inspectedUnit==unit)inspectedUnit=null;
        ReleaseUnitOccupancy(unit);
        ClearJaguarHuntMark(unit);
        DeactivateWolfEclipseClones(unit);
        CleanupRank3Unit(unit);
        PixelCombatEffect.StopBearSpiritAura(unit.bearSpiritParticles);
        unit.bearSpiritParticles=null;
        unit.bearSpiritFx?.Cancel();
        unit.bearSpiritFx=null;
        PixelCombatEffect.StopBearSpiritAura(unit.legacyInheritanceAura);
        unit.legacyInheritanceAura=null;
        if(unit.reaction!=null)unit.reaction.ClearDeathVisual();
        if(!ReturnEnemyVisual(unit))
        {if(unit.model!=null)Destroy(unit.model);if(unit.ring!=null)Destroy(unit.ring);}
        units.Remove(unit);
    }

    private MonsterDefinition RequireMonsterDefinition(string monsterId)
    {
        MonsterDefinition definition=monsterDatabase.Get(monsterId);
        if(definition==null)throw new InvalidOperationException("Monster definition missing: "+monsterId);
        return definition;
    }

    private List<Vector2Int> GenerateEnemyDeployment(int count)
    {
        System.Random random=new System.Random(UsesCombatEffectTestRules
#if UNITY_EDITOR
            ?CombatReadabilityPreview.Active?CombatReadabilityPreview.Seed:Guid.NewGuid().GetHashCode()
#else
            ?Guid.NewGuid().GetHashCode()
#endif
            :MonsterInstanceGenerator.StableSeed(
                expeditionRun.runId+"_"+expeditionRun.wave+"_enemy_deployment"));
        List<Vector2Int> candidates=tiles.Values
            .Where(tile=>tile.walkable&&tile.deploymentTeam!=Team.Player&&
                (!UsesHexDeployment||tile.deploymentTeam==Team.Enemy))
            .Select(tile=>tile.coordinate)
            .OrderBy(_=>random.Next())
            .ToList();
        List<Vector2Int> result=new List<Vector2Int>(count);
        for(int i=0;i<candidates.Count&&result.Count<count;i++)
        {
            Vector2Int candidate=candidates[i];
            if(result.All(existing=>(UsesHexDeployment
                ?HexDistance(existing,candidate)
                :Vector2Int.Distance(existing,candidate))>=2.5f))result.Add(candidate);
        }
        for(int i=0;i<candidates.Count&&result.Count<count;i++)
            if(!result.Contains(candidates[i]))result.Add(candidates[i]);
        if(result.Count<count)throw new InvalidOperationException("Not enough enemy deployment hexes.");
        return result;
    }

    private void GeneratePlayerDeploymentZone()
    {
        foreach(Tile tile in tiles.Values)
        {
            if(tile.bench)continue;
            tile.deploymentTeam=null;
            tile.neutralZone=false;
            if(UsesPointyHexTileArena&&
               tile.coordinate.x>=ActiveColumns-EnemyDeploymentColumns)
                tile.deploymentTeam=Team.Enemy;
            else if(UsesHexDeployment&&!UsesPointyHexTileArena)
            {
                if(tile.coordinate.x>=ActiveColumns-EnemyDeploymentColumns)
                    tile.deploymentTeam=Team.Enemy;
                else if(tile.coordinate.x>=AllyDeploymentColumns)
                    tile.neutralZone=true;
            }
        }

        int activated=0;
        for(int row=ActivePlayerDeployStartRow;
            row<ActivePlayerDeployStartRow+ActivePlayerDeployRows;row++)
        for(int column=ActivePlayerDeployStartColumn;
            column<ActivePlayerDeployStartColumn+ActivePlayerDeployColumns;column++)
        {
            Vector2Int coordinate=new Vector2Int(column,row);
            if(!tiles.TryGetValue(coordinate,out Tile tile)||!tile.walkable||tile.bench)
                throw new InvalidOperationException("Fixed player deployment tile is unavailable: "+coordinate);
            tile.deploymentTeam=Team.Player;
            activated++;
        }
        if(!UsesHexDeployment&&activated!=PlayerDeploymentTileCount)
            throw new InvalidOperationException("Fixed player deployment zone must contain exactly "+
                                                PlayerDeploymentTileCount+" tiles.");
        RefreshAllTileVisuals();
    }

    private void RefreshAllTileVisuals()
    {
        foreach(Tile tile in tiles.Values)
        {
            tile.baseColor=TileBaseColor(tile);
            Color color=IsTwinCommandTile(tile.coordinate)
                ?Color.Lerp(tile.baseColor,new Color(0.95f,0.52f,0.12f),0.72f)
                :tile.baseColor;
            SetTileColor(tile,color);
            tile.renderer.enabled=!UsesHexDeployment&&!environmentBackdropReady;
            RefreshPlacementMarker(tile);
        }
    }

    private void UpdatePlacementMarkerRootVisibility()
    {
        if(placementMarkerRoot!=null)
            placementMarkerRoot.gameObject.SetActive(
                !mlEpisodeActive&&!wavePreparationAcrossFrames&&
                !capturePresentationResolving&&TutorialPreparationVisible);
    }

    private void RefreshPlacementMarker(Tile tile)
    {
        bool visible=UsesHexDeployment||fullFieldMarkersVisible||tile.bench||
                     tile.deploymentTeam==Team.Player||beetleOverturnPreviewTiles.Contains(tile.coordinate);
        bool highlighted=visible&&highlightedPlacementTiles.Contains(tile.coordinate);
        if(visible&&tile.placementMarker==null)
        {
            GameObject marker=new GameObject(
                $"Placement Marker {tile.coordinate.x},{tile.coordinate.y}");
            marker.transform.SetParent(placementMarkerRoot,false);
            marker.transform.rotation=Quaternion.Euler(90f,0f,0f);
            marker.transform.localScale=Vector3.one*(ActiveTileSize*
                HexDeploymentTileVisualScale*
                (tile.bench?0.88f:0.96f));
            SpriteRenderer renderer=marker.AddComponent<SpriteRenderer>();
            renderer.sprite=tile.bench
                ?benchPlacementMarkerSprite:placementMarkerSprite;
            renderer.sortingOrder=6;
            tile.placementMarker=marker;
        }
        if(tile.placementMarker==null)return;
        tile.placementMarker.transform.position=tile.world+Vector3.up*0.008f;
        tile.placementMarker.SetActive(visible);
        if(!visible)return;
        tile.placementMarker.GetComponent<SpriteRenderer>().color=
            PlacementMarkerColor(tile,highlighted);
    }

    private Color PlacementMarkerColor(Tile tile,bool highlighted)
    {
        string region=meadowAmbientParticles!=null?meadowAmbientParticles.RegionId:
            expeditionRun==null?HunterRegionCatalog.FirstRegionId:expeditionRun.regionId;
        bool lightFloor=region=="frozen_highlands"||region=="sky_sanctuary";
        Color ally=new Color(.22f,.92f,1f,.90f);
        Color enemy=new Color(1f,.40f,.38f,.82f);
        Color bench=new Color(.80f,.59f,1f,.84f);
        Color neutral=new Color(1f,.86f,.48f,.46f);
        switch(region)
        {
            case "poison_fog_swamp":
                ally=new Color(.34f,1f,.86f,.92f);
                enemy=new Color(1f,.45f,.55f,.86f);
                bench=new Color(.86f,.64f,1f,.86f);break;
            case "crimson_jungle":
                ally=new Color(.48f,.96f,1f,.94f);
                enemy=new Color(1f,.68f,.72f,.92f);
                bench=new Color(.88f,.76f,1f,.90f);
                neutral=new Color(1f,.91f,.65f,.52f);break;
            case "frozen_highlands":
                ally=new Color(.06f,.22f,.48f,.96f);
                enemy=new Color(.58f,.09f,.22f,.94f);
                bench=new Color(.33f,.14f,.51f,.94f);
                neutral=new Color(.37f,.25f,.08f,.66f);break;
            case "sky_sanctuary":
                ally=new Color(.04f,.27f,.38f,.96f);
                enemy=new Color(.56f,.08f,.22f,.94f);
                bench=new Color(.36f,.16f,.52f,.94f);
                neutral=new Color(.42f,.29f,.08f,.66f);break;
        }
        if(highlighted)
            return !lightFloor?highlightedPlacementColor:highlightedPlacementColor.g>.5f
                ?new Color(.68f,.28f,.025f,1f):new Color(.78f,.025f,.08f,1f);
        if(beetleOverturnPreviewTiles.Contains(tile.coordinate))
            return lightFloor?new Color(.08f,.20f,.66f,1f):new Color(.60f,.88f,1f,1f);
        if(tile.bench)return bench;
        if(!tile.walkable)return lightFloor?new Color(.72f,.12f,.04f,.94f):new Color(1f,.48f,.2f,.90f);
        if(IsTwinCommandTile(tile.coordinate))
            return lightFloor?new Color(.68f,.28f,.025f,.96f):new Color(1f,.72f,.22f,.96f);
        return tile.deploymentTeam==Team.Player?ally:tile.neutralZone?neutral:enemy;
    }

    private List<Vector2Int> PlayerDeploymentCoordinates()
    {
        return tiles.Values.Where(tile=>tile.walkable&&tile.deploymentTeam==Team.Player)
            .Select(tile=>tile.coordinate)
            .OrderByDescending(coordinate=>coordinate.x)
            .ThenBy(coordinate=>Mathf.Abs(coordinate.y-(ActiveRows-1)*0.5f))
            .ThenBy(coordinate=>coordinate.y).ToList();
    }

    private bool CanOccupySpawn(Vector2Int anchor,Vector2Int footprint)
    {
        List<Vector2Int> occupied=GetFootprintTiles(anchor,footprint);
        return occupied.Count==footprint.x*footprint.y&&
            occupied.All(coordinate=>tiles.TryGetValue(coordinate,out Tile tile)&&tile.walkable&&!occupancy.ContainsKey(coordinate));
    }

    private static List<Vector2Int> GetFootprintTiles(Vector2Int center,Vector2Int footprint)
    {
        List<Vector2Int> result=new List<Vector2Int>(footprint.x*footprint.y);
        int startX=-(footprint.x/2);
        int startY=-(footprint.y/2);
        for(int y=0;y<footprint.y;y++)
        for(int x=0;x<footprint.x;x++)result.Add(center+new Vector2Int(startX+x,startY+y));
        return result;
    }

    private Vector3 GetFootprintCenterWorld(Vector2Int center,Vector2Int footprint)
    {
        return GridWorld(center);
    }

    private bool CanPlaceUnit(Unit unit,Vector2Int anchor,bool requirePlayerDeployment)
    {
        List<Vector2Int> occupied=GetFootprintTiles(anchor,unit.footprint);
        if(occupied.Count==0)return false;
        for(int i=0;i<occupied.Count;i++)
        {
            if(!tiles.TryGetValue(occupied[i],out Tile tile)||!tile.walkable)return false;
            if(requirePlayerDeployment&&tile.deploymentTeam!=Team.Player)return false;
            if(occupancy.TryGetValue(occupied[i],out Unit occupant)&&occupant!=unit)return false;
        }
        return true;
    }

    private int MaxDeploymentCount=>Mathf.Min(
        ExpeditionDeploymentSystem.MaximumLimit,
        BaseDeploymentLimit+Mathf.Max(0,additionalDeploymentSlots));

    private int CurrentDeploymentCount=>units
        .Where(unit=>unit.team==Team.Player&&!unit.inStorage)
        .Sum(unit=>unit.deploymentSlots);

    private bool CanAffordDeployment(Unit unit)
    {
        return unit!=null&&(!unit.inStorage||CurrentDeploymentCount+unit.deploymentSlots<=MaxDeploymentCount);
    }

    public void SetAdditionalDeploymentSlots(int value)
    {
        int previousLimit=MaxDeploymentCount;
        int maximumAdditional=Mathf.Max(0,
            ExpeditionDeploymentSystem.MaximumLimit-BaseDeploymentLimit);
        additionalDeploymentSlots=Mathf.Clamp(value,0,maximumAdditional);
        if(expeditionRun!=null)
            expeditionRun.maxDeploymentCount=BaseDeploymentLimit+additionalDeploymentSlots;
        NotifyDeploymentLimitIncrease(previousLimit);
    }

