    {
        mlEpisodeCompleted=handler;
    }

    public string StartCorruptionGreatSuccessDiagnostic()
    {
        if(battleStarted||battleEnding||corruptionDiagnosticRunning)
            return "busy";
        PrepareNextWave(true);
        expeditionRun.augmentDraftWave=0;
        expeditionRun.augmentDraftIds.Clear();
        shopVisible=false;
        List<ItemTransformMasterRow> rows=GameMasterData.Database.itemTransforms
            .Where(row=>row!=null&&row.enabled&&
                CorruptionGreatSuccessRules.Supports(row.corruptionGreatEffectId))
            .ToList();
        if(rows.Count!=36)return "invalid_transform_count="+rows.Count;

        CorruptionGreatSuccessDiagnostics.Reset();
        List<Unit> active=units.Where(unit=>unit.alive&&!unit.inStorage).ToList();
        foreach(Unit unit in active)
        {
            unit.itemModifiers.transformedEffects.Clear();
            unit.itemModifiers.transformedEffects.AddRange(rows);
            unit.itemModifiers.specialEffects.AddRange(rows
                .Select(row=>GameMasterData.Item(row.itemId))
                .Where(item=>item!=null&&!string.IsNullOrEmpty(item.specialEffect)&&
                    item.specialEffect!="None"));
            unit.itemModifiers.criticalChance=1f;
            unit.skillTimer=0f;
            unit.hp=Mathf.Min(unit.hp,unit.maxHp*.25f);
            unit.corruptCounters["storm_attacks"]=3;
            unit.corruptCounters["skill_echo_casts"]=2;
            unit.corruptCounters["berserk_attacks"]=5;
            unit.corruptCounters["time_attacks"]=2;
            unit.corruptCounters["vampire_attacks"]=4;
            unit.corruptCounters["blood_shards"]=4;
            unit.corruptCounters["shell_hits"]=4;
            unit.corruptCounters["retaliation_hits"]=3;
            unit.corruptCounters["adaptive_hits"]=4;
            unit.corruptCounters["blood_shards"]=4;
            unit.corruptValues["supernova_stored"]=unit.damage*2f;
            unit.corruptValues["grand_ready"]=1f;
            unit.combatStatuses.ApplyTimed(CombatStatusKind.Root,.25f,unit);
        }
        foreach(Unit unit in active)
        {
            foreach(Unit enemy in active.Where(other=>other.team!=unit.team))
                unit.corruptCounters["devour_"+enemy.id]=3;
        }
        corruptionDiagnosticRunning=true;
        corruptionDiagnosticOriginalTimeScale=Time.timeScale;
        Time.timeScale=8f;
        StartCurrentBattle();
        PrimeCorruptionDiagnosticActivations(active);
        StartCoroutine(CompleteCorruptionGreatSuccessDiagnostic());
        return "started; units="+active.Count+"; effects="+rows.Count;
    }

    private void PrimeCorruptionDiagnosticActivations(List<Unit> active)
    {
        foreach(Unit unit in active)
        {
            if(!IsCombatActive(unit))continue;
            SetCorruptTimer(unit,"CorruptHealthEqualize",0f);
            Unit enemy=active.FirstOrDefault(other=>other.team!=unit.team&&
                IsCombatActive(other));
            if(enemy==null)continue;
            SetTarget(unit,enemy);
            enemy.combatStatuses.ApplyTimed(CombatStatusKind.Root,2f,unit);
            unit.lastBasicAttackCritical=true;
            HandleCorruptionBasicAttack(unit,enemy,.1f);
            unit.lastSkillCritical=true;
            PrepareCorruptionSkillUse(unit);
            HandleCorruptionSkillUse(unit);
            unit.hp=Mathf.Min(unit.hp,unit.maxHp*.25f);
            ApplyLowHealthShield(unit,1f);
            HandleCorruptionDamageTaken(enemy,unit,1f,true,false,true);
            HandleCorruptionStatusRecovery(unit);
            UpdateCorruptionGreatSuccessEffects(unit,10f);
            HandleCorruptionKill(unit,enemy);
        }
    }

    public string CorruptionGreatSuccessDiagnosticSummary()
    {
        return CorruptionGreatSuccessDiagnostics.Summary();
    }

    public string PreviewCorruptionGreatSuccessFeedback(string effectId)
    {
        Unit owner=units.FirstOrDefault(unit=>unit.team==Team.Player&&
            unit.alive&&unit.model!=null);
        ItemTransformMasterRow row=GameMasterData.Database.itemTransforms
            .FirstOrDefault(value=>value!=null&&value.enabled&&
                string.Equals(value.corruptionGreatEffectId,effectId,
                    StringComparison.Ordinal));
        if(owner==null)return "owner_missing";
        if(row==null)return "effect_missing";
        expeditionRun.augmentDraftWave=0;
        expeditionRun.augmentDraftIds.Clear();
        shopVisible=false;
        owner.corruptTimers.Remove("feedback_"+effectId);
        CorruptionGreatSuccessDiagnostics.Record(effectId);
        CorruptionFeedbackStyle style=
            CorruptionGreatSuccessPresentation.Style(effectId);
        CreateSkillPulse(owner,style.color,style.pulseScale);
        return CorruptionGreatSuccessPresentation.Label(row);
    }

    private IEnumerator CompleteCorruptionGreatSuccessDiagnostic()
    {
        float realElapsed=0f;
        while(corruptionDiagnosticRunning&&realElapsed<20f&&
              (battleStarted||battleEnding||battleElapsed<=0f))
        {
            realElapsed+=Time.unscaledDeltaTime;
            yield return null;
        }
        Time.timeScale=corruptionDiagnosticOriginalTimeScale;
        corruptionDiagnosticRunning=false;
        Debug.Log("[Corruption Diagnostic] "+
            CorruptionGreatSuccessDiagnostics.Summary());
    }

    public void BeginMlEpisode(
        int wave,int seed,string regionId,ExpeditionDifficulty difficulty,
        int academyStep,string sampleSet="ml_v2")
    {
        if(monsterDatabase==null||playerProfile==null)return;
        mlEpisodeActive=true;
        combatGeneration++;
        ResetFamilyTranscendenceStates();
        meadowAmbientParticles?.ClearImpacts();
        StopAllCoroutines();
        mlScenarioSeed=seed;
        mlAcademyStep=Mathf.Max(0,academyStep);
        List<MonsterDefinition> definitions=BuildMlTrainingRoster(
            monsterDatabase,seed,RosterSize);
        if(definitions.Count==0)
            throw new InvalidOperationException("ML training roster is empty.");
        List<OwnedMonsterSave> startingRoster=new List<OwnedMonsterSave>();
        for(int i=0;i<definitions.Count;i++)
        {
            MonsterDefinition definition=definitions[i];
            startingRoster.Add(PlayerProfileStore.CreateMonster(
                definition,"ml_"+seed+"_"+i+"_"+definition.monsterId,false));
        }
        foreach(Unit unit in units.ToList())RemoveUnitFromRoster(unit);
        occupancy.Clear();
        expeditionRun=ExpeditionRunFactory.Create(
            playerProfile,monsterDatabase,startingRoster,regionId,
            StartingExpeditionLives,BaseDeploymentLimit,difficulty);
        expeditionRun.wave=Mathf.Clamp(wave,1,ExpeditionWaveCount);
        expeditionRun.lives=StartingExpeditionLives;
        expeditionRun.maxDeploymentCount=Mathf.Clamp(
            BaseDeploymentLimit+(expeditionRun.wave-1)/3,
            BaseDeploymentLimit,8);
        expeditionFailed=false;
        growthCardDraft.Clear();
        expeditionRun.runId=(string.IsNullOrWhiteSpace(sampleSet)?"ml_v2":sampleSet)+
            "_"+regionId+"_"+difficulty+
            "_wave_"+expeditionRun.wave+"_seed_"+seed;
        expeditionRun.activeBattleWave=expeditionRun.wave;
        expeditionRun.activeBattleSeed=seed==0?1:seed;
        AutoBattleHeuristicPolicy.ApplyGrowthShopProgression(
            expeditionRun,expeditionRun.wave,seed);
        ApplyMlItemProgression(seed,expeditionRun.wave);
        additionalDeploymentSlots=Mathf.Max(
            0,expeditionRun.maxDeploymentCount-BaseDeploymentLimit);
        for(int i=0;i<startingRoster.Count;i++)
        {
            OwnedMonsterSave owned=startingRoster[i];
            MonsterDefinition definition=monsterDatabase.Get(owned.monsterId);
            if(definition!=null&&definition.enabled)
                SpawnUnit(definition,Team.Player,BenchCoordinate(i),owned,true);
        }
        UnityEngine.Random.InitState(seed);
        PrepareNextWave(true);
        SuppressSimulationIntermissions();
        ArrangePlayerFormationForNewWave(Array.Empty<string>());
    }

    public static List<MonsterDefinition> BuildMlTrainingRoster(
        MonsterDatabase database,int seed,int count=8)
    {
        if(database==null||count<=0)return new List<MonsterDefinition>();
        List<MonsterDefinition> candidates=database.monsters
            .Where(definition=>definition!=null&&definition.enabled&&
                !string.IsNullOrWhiteSpace(definition.resourcePath)&&
                int.TryParse(definition.serialNumber,out int serial)&&
                serial>=1&&serial<=80)
            .OrderBy(definition=>definition.monsterId,StringComparer.Ordinal)
            .ToList();
        System.Random random=new System.Random(seed&int.MaxValue);
        ShuffleMl(candidates,random);
        int mode=((seed%3)+3)%3;
        if(mode==0)return candidates.Take(count).ToList();

        int familyCount=mode==1?2:4;
        int perFamily=mode==1?4:2;
        List<List<MonsterDefinition>> families=candidates
            .Where(definition=>!string.IsNullOrWhiteSpace(definition.familyId))
            .GroupBy(definition=>definition.familyId,StringComparer.Ordinal)
            .Select(group=>group.ToList()).ToList();
        ShuffleMl(families,random);
        List<MonsterDefinition> result=new List<MonsterDefinition>();
        foreach(List<MonsterDefinition> family in families.Take(familyCount))
        {
            ShuffleMl(family,random);
            result.AddRange(family.Take(perFamily));
        }
        foreach(MonsterDefinition definition in candidates)
        {
            if(result.Count>=count)break;
            if(!result.Contains(definition))result.Add(definition);
        }
        return result.Take(count).ToList();
    }

    private static void ShuffleMl<T>(IList<T> values,System.Random random)
    {
        for(int i=values.Count-1;i>0;i--)
        {
            int swap=random.Next(i+1);
            T value=values[i];values[i]=values[swap];values[swap]=value;
        }
    }

    private void ApplyMlItemProgression(int seed,int wave)
    {
        int mode=((seed/17%3)+3)%3;
        mlScenarioProfile=mode==0?"baseline":
            mode==1?"basic_items":"mixed_items";
        if(mode==0||GameMasterData.Database==null)return;
        List<ItemMasterRow> basic=GameMasterData.Database.items
            .Where(item=>item!=null&&item.enabled&&item.IsBase)
            .OrderBy(item=>item.id,StringComparer.Ordinal).ToList();
        List<ItemMasterRow> completed=GameMasterData.Database.items
            .Where(item=>item!=null&&item.enabled&&item.IsCompleted)
            .OrderBy(item=>item.id,StringComparer.Ordinal).ToList();
        System.Random random=new System.Random((seed^0x5F3759DF)&int.MaxValue);
        List<ItemMasterRow> grants=new List<ItemMasterRow>();
        if(mode==1&&basic.Count>0)
            for(int i=0;i<Mathf.Clamp((wave-1)/2,0,6);i++)
                grants.Add(basic[random.Next(basic.Count)]);
        if(mode==2)
        {
            if(completed.Count>0)
                for(int i=0;i<Mathf.Clamp((wave-1)/4,0,3);i++)
                    grants.Add(completed[random.Next(completed.Count)]);
            if(basic.Count>0&&wave>=3)
                grants.Add(basic[random.Next(basic.Count)]);
        }
        List<ExpeditionMonsterStateSave> states=expeditionRun.monsters
            .Where(state=>state!=null).OrderBy(_=>random.Next()).ToList();
        for(int i=0;i<grants.Count&&states.Count>0;i++)
        {
            ExpeditionMonsterStateSave target=states[i%states.Count];
            int slot=target.itemInstanceIds.FindIndex(string.IsNullOrEmpty);
            if(slot<0)continue;
            ExpeditionItemInstanceSave item=ExpeditionItemSystem.CreateItem(
                expeditionRun,grants[i].id,true);
            ExpeditionItemSystem.Equip(
                expeditionRun,target.instanceId,item.instanceId,slot,out _);
        }
    }

    public AutoBattleMlSnapshot GetMlSnapshot()
    {
        AutoBattleMlSnapshot snapshot=new AutoBattleMlSnapshot
        {
            wave=expeditionRun==null?1:expeditionRun.wave,
            regionId=expeditionRun==null?"":expeditionRun.regionId,
            difficulty=expeditionRun==null?0:(int)expeditionRun.difficulty,
            scenarioProfile=mlScenarioProfile,
            deploymentCount=CurrentDeploymentCount,
            maximumDeploymentCount=MaxDeploymentCount
        };
        List<Unit> roster=OrderedMlRoster();
        for(int i=0;i<roster.Count;i++)snapshot.roster.Add(ToMlObservation(roster[i]));
        List<Vector2Int> deployment=PlayerDeploymentCoordinates();
        for(int i=0;i<deployment.Count;i++)
        {
            Vector2Int coordinate=deployment[i];
            snapshot.deploymentTiles.Add(new AutoBattleMlTileObservation
            {
                coordinate=coordinate,occupied=UnitAt(coordinate)!=null
            });
        }
        List<Unit> enemies=units.Where(unit=>unit.team==Team.Enemy)
            .OrderBy(unit=>unit.stableId,StringComparer.Ordinal).ToList();
        for(int i=0;i<enemies.Count;i++)snapshot.enemies.Add(ToMlObservation(enemies[i]));
        return snapshot;
    }

    public bool CanMlSelectMonster(int rosterIndex)
    {
        List<Unit> roster=OrderedMlRoster();
        if(rosterIndex<0||rosterIndex>=roster.Count)return false;
        Unit unit=roster[rosterIndex];
        return mlEpisodeActive&&!battleStarted&&unit.inStorage&&
               CurrentDeploymentCount+unit.deploymentSlots<=MaxDeploymentCount;
    }

    public bool CanMlPlaceMonster(int rosterIndex,int tileIndex)
    {
        List<Unit> roster=OrderedMlRoster();
        List<Vector2Int> deployment=PlayerDeploymentCoordinates();
        if(rosterIndex<0||rosterIndex>=roster.Count||tileIndex<0||tileIndex>=deployment.Count)
            return false;
        Unit unit=roster[rosterIndex];
        return CanMlSelectMonster(rosterIndex)&&CanPlaceUnit(unit,deployment[tileIndex],true);
    }

    public bool PlaceMlMonster(int rosterIndex,int tileIndex)
    {
        if(!CanMlPlaceMonster(rosterIndex,tileIndex))return false;
        Unit unit=OrderedMlRoster()[rosterIndex];
        Vector2Int destination=PlayerDeploymentCoordinates()[tileIndex];
        OccupyUnit(unit,destination);
        unit.inStorage=false;
        unit.initialTile=destination;
        unit.model.SetActive(true);
        if(unit.ring!=null)unit.ring.SetActive(true);
        ApplyDeploymentTransform(unit);
        return true;
    }

    public bool HasMlPlacementChoice()
    {
        List<Unit> roster=OrderedMlRoster();
        for(int i=0;i<roster.Count;i++)
        {
            if(!CanMlSelectMonster(i))continue;
            List<Vector2Int> deployment=PlayerDeploymentCoordinates();
            for(int tile=0;tile<deployment.Count;tile++)
                if(CanPlaceUnit(roster[i],deployment[tile],true))return true;
        }
        return false;
    }

    public bool StartMlBattle()
    {
        if(!mlEpisodeActive||battleStarted||CurrentDeploymentCount<=0)return false;
        StartCurrentBattle();
        return battleStarted;
    }

    private List<Unit> OrderedMlRoster()
    {
        return BattleReadyUnits().OrderBy(unit=>unit.stableId,StringComparer.Ordinal).ToList();
    }

    private AutoBattleMlUnitObservation ToMlObservation(Unit unit)
    {
        ExpeditionMonsterStateSave state=unit.team==Team.Player
            ?ExpeditionItemSystem.MonsterState(expeditionRun,unit.stableId):null;
        AutoBattleMlUnitObservation observation=new AutoBattleMlUnitObservation
        {
            stableId=unit.stableId,monsterId=unit.definition.monsterId,
            familyId=unit.definition.familyId,
            personalityId=unit.ownedInstance.personalityId,
            monsterSerial=int.TryParse(unit.definition.serialNumber,out int serial)
                ?serial:0,
            present=true,deployed=!unit.inStorage,
            maxHp=unit.maxHp,damage=unit.damage,attackInterval=unit.attackInterval,
            moveSpeed=unit.speedTilesPerSecond,attackRange=unit.attackRange,
            rank=(int)(unit.team==Team.Enemy?unit.expeditionRank:
                state==null?ExpeditionMonsterRank.Rank1:state.rank),
            traitCount=unit.activeTraitIds.Count,deploymentSlots=unit.deploymentSlots,
            tile=unit.currentTile
        };
        observation.activeTraitIds.AddRange(unit.activeTraitIds);
        if(state!=null)
            observation.itemIds.AddRange(state.itemInstanceIds
                .Select(instanceId=>ExpeditionItemSystem.ItemInstance(
                    expeditionRun,instanceId)?.itemId)
                .Where(itemId=>!string.IsNullOrWhiteSpace(itemId)));
        else observation.itemIds.AddRange(unit.equippedEnemyItems
            .Where(item=>item!=null).Select(item=>item.id));
        return observation;
    }

    private void BuyDeploymentExpansion()
    {
        if(battleStarted||battleEnding||expeditionRun==null||resultText.Length>0||
           shopVisible||GrowthShopVisible)return;
        int previousLimit=MaxDeploymentCount;
        if(!ExpeditionDeploymentSystem.TryUpgrade(expeditionRun))return;
        additionalDeploymentSlots=Mathf.Max(0,
            expeditionRun.maxDeploymentCount-BaseDeploymentLimit);
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,true);
        itemUiMessage="최대 배치 수 확장: "+MaxDeploymentCount+"개체";
        NotifyDeploymentLimitIncrease(previousLimit);
    }

    private void ReleaseUnitOccupancy(Unit unit)
    {
        List<Vector2Int> keys=occupancy.Where(pair=>pair.Value==unit).Select(pair=>pair.Key).ToList();
        for(int i=0;i<keys.Count;i++)occupancy.Remove(keys[i]);
    }

    private void OccupyUnit(Unit unit,Vector2Int anchor)
    {
        ReleaseUnitOccupancy(unit);
        unit.currentTile=anchor;
        if(unit.spiritConcertOwner!=null)return;
        List<Vector2Int> occupied=GetFootprintTiles(anchor,unit.footprint);
        for(int i=0;i<occupied.Count;i++)occupancy[occupied[i]]=unit;
    }

    private void ApplyDeploymentTransform(Unit unit)
    {
        Vector3 world=GetFootprintCenterWorld(unit.currentTile,unit.footprint);
        unit.model.transform.position=world+Vector3.up*unit.visualHeightOffset;
        unit.ring.transform.position=world+Vector3.up*0.025f;
        Vector3 baseForward=DeploymentFacing(unit.team);
        unit.model.transform.rotation=Quaternion.LookRotation(baseForward,Vector3.up);
        unit.facingDirection=baseForward;
        if(unit.spriteBillboard!=null)unit.spriteBillboard.SetFacingDirection(baseForward);
        if(unit.turnAnticipation!=null)unit.turnAnticipation.SetDesiredDirection(baseForward);
        unit.lastGroundPosition=world;
    }

    private Unit SpawnUnit(MonsterDefinition definition,Team team,Vector2Int coordinate,OwnedMonsterSave ownedInstance,
        bool spawnInStorage)=>SpawnUnitModel(definition,team,coordinate,ownedInstance,spawnInStorage,null);

    private Unit SpawnUnitModel(MonsterDefinition definition,Team team,Vector2Int coordinate,OwnedMonsterSave ownedInstance,
        bool spawnInStorage,Unit concertOwner)
    {
        if(definition==null)throw new ArgumentNullException(nameof(definition));
        if(ownedInstance==null)throw new ArgumentNullException(nameof(ownedInstance));
        string displayName=(team==Team.Enemy?"적 ":"")+
            (ownedInstance.isShiny?"★ ":"")+definition.displayName;
        string resourcePath=ownedInstance.isShiny
            ?definition.shinyResourcePath
            :definition.resourcePath;
        if(string.IsNullOrWhiteSpace(resourcePath))
            resourcePath=definition.resourcePath;
        Vector2Int footprint=Vector2Int.one;
        if(concertOwner==null&&!spawnInStorage&&!CanOccupySpawn(coordinate,footprint))
            throw new InvalidOperationException("Invalid auto battle spawn hex: "+coordinate);
        GameObject prefab=Resources.Load<GameObject>(resourcePath);
        if(prefab==null)throw new InvalidOperationException("Auto battle monster prefab missing: "+resourcePath);
        EnemyVisual reused=team==Team.Enemy&&concertOwner==null?TakeEnemyVisual(resourcePath):null;
        GameObject model=reused==null?Instantiate(prefab,transform):reused.model;
        if(reused!=null)
        {model.transform.localScale=prefab.transform.localScale;model.SetActive(true);}
        model.name=(team==Team.Player?"Ally ":"Enemy ")+displayName;
        SpriteMonsterAnimationDriver spriteAnimation=
            model.GetComponentInChildren<SpriteMonsterAnimationDriver>(true);
        bool isRaptorFamily=string.Equals(definition.familyId,"raptor",StringComparison.OrdinalIgnoreCase);
        float groundOffset=spriteAnimation!=null
            ?PixelMonsterGroundOffset
            :NormalizeModel(model,definition.modelHeight*definition.visualScale,
                definition.groundSpanTileRatio*definition.visualScale);
        Vector3 world=GetFootprintCenterWorld(coordinate,footprint);
        model.transform.position=world+Vector3.up*groundOffset;
        Vector3 initialFacing=DeploymentFacing(team);
        model.transform.rotation=Quaternion.LookRotation(initialFacing,Vector3.up);

        Animator animator=model.GetComponentInChildren<Animator>(true);
        SpriteMonsterBillboard spriteBillboard=
            model.GetComponentInChildren<SpriteMonsterBillboard>(true);
        if(animator!=null)
        {
            animator.SetBool("Moving",false);
            animator.Play("Idle",0,UnityEngine.Random.value);
            animator.Update(0f);
            animator.speed=spriteAnimation!=null
                ?1f
                :UnityEngine.Random.Range(0.92f,1.08f);
            if(spriteAnimation==null)
                GroundEvaluatedModel(model,world,ref groundOffset);
        }
        VoxelEnemyReaction reaction=model.GetComponent<VoxelEnemyReaction>();
        if(reaction==null)reaction=model.AddComponent<VoxelEnemyReaction>();reaction.Initialize();
        if(reused!=null)reaction.PrepareForReuse();
        RaptorTurnAnticipation turnAnticipation=null;
        if(isRaptorFamily&&spriteAnimation==null)
        {
            turnAnticipation=model.GetComponent<RaptorTurnAnticipation>();
            if(turnAnticipation==null)turnAnticipation=model.AddComponent<RaptorTurnAnticipation>();
            turnAnticipation.Initialize();
        }
        FrogTongueWhip tongueWhip=null;
        if(string.Equals(definition.familyId,"frog",StringComparison.OrdinalIgnoreCase))
        {
            tongueWhip=model.GetComponent<FrogTongueWhip>();
            if(tongueWhip==null)tongueWhip=model.AddComponent<FrogTongueWhip>();
            tongueWhip.Initialize();
        }
        GiraffeNeckStrike neckStrike=null;
        GiraffeHighHeadSlam highHeadSlam=null;
        if(string.Equals(definition.familyId,"giraffe",StringComparison.OrdinalIgnoreCase))
        {
            neckStrike=model.GetComponent<GiraffeNeckStrike>();
            if(neckStrike==null)neckStrike=model.AddComponent<GiraffeNeckStrike>();
            neckStrike.Initialize();
            highHeadSlam=model.GetComponent<GiraffeHighHeadSlam>();
            if(highHeadSlam==null)highHeadSlam=model.AddComponent<GiraffeHighHeadSlam>();
            highHeadSlam.Initialize();
        }
        if(string.Equals(definition.familyId,"spider",StringComparison.OrdinalIgnoreCase))
        {
            SpiderProceduralLegMotion spiderLegMotion=
                model.GetComponent<SpiderProceduralLegMotion>();
            if(spiderLegMotion==null)spiderLegMotion=model.AddComponent<SpiderProceduralLegMotion>();
            spiderLegMotion.Initialize();
        }
        ScreenSpaceOutlineTarget outline=model.GetComponent<ScreenSpaceOutlineTarget>();
        if(outline==null)outline=model.AddComponent<ScreenSpaceOutlineTarget>();
        outline.RefreshRenderers();outline.SetOutlined(false);
        GameObject ring=reused==null?GameObject.CreatePrimitive(PrimitiveType.Cylinder):reused.ring;
        ring.SetActive(true);
        ring.name="Floor Shadow - "+displayName;
        ring.transform.SetParent(transform,false);
        ring.transform.position=world+Vector3.up*0.018f;
        float ringScale=Mathf.Clamp(definition.collisionRadius*1.15f,0.42f,0.82f)*
            (UsesHexDeployment?HexDeploymentUnitScale:1f);
        ringScale*=CombatReadabilityPresentation.BodyVisualScale;
        ring.transform.localScale=new Vector3(ringScale,0.012f,ringScale*0.68f);
        Renderer shadowRenderer=ring.GetComponent<Renderer>();
        shadowRenderer.sharedMaterial=unitShadowMaterial;
        shadowRenderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;
        shadowRenderer.receiveShadows=false;
        Collider collider=ring.GetComponent<Collider>();if(collider!=null)Destroy(collider);

        Unit unit=new Unit
        {
            id=units.Count,
            stableId=ownedInstance.instanceId,
            definition=definition,ownedInstance=ownedInstance,
            regionDamageMultiplier=HunterRegionCatalog.RegionDamageMultiplier(
                expeditionRun?.regionId,definition.monsterId),
            resourcePath=resourcePath,displayName=displayName,team=team,
            skillId=definition.skillId??string.Empty,
            personalityPolicy=PersonalityCombatPolicy.From(ownedInstance),
            deploymentSlots=1,
            footprint=footprint,model=model,ring=ring,animator=animator,
            spriteAnimation=spriteAnimation,spriteBillboard=spriteBillboard,
            turnAnticipation=turnAnticipation,tongueWhip=tongueWhip,neckStrike=neckStrike,
            highHeadSlam=highHeadSlam,
            facingDirection=initialFacing,
            reaction=reaction,outline=outline,
            currentTile=coordinate,initialTile=coordinate,
            visualHeightOffset=groundOffset,baseVisualHeightOffset=groundOffset,
            baseModelScale=model.transform.localScale,
            lastGroundPosition=world,
            hp=definition.maxHp*Mathf.Max(0.01f,ownedInstance.hpMultiplier),
            damage=definition.attackDamage*Mathf.Max(0.01f,ownedInstance.damageMultiplier),
            defense=Mathf.Max(
                0f,definition.defense*
                   Mathf.Max(0.01f,ownedInstance.defenseMultiplier)),
            statusResistance=Mathf.Max(
                0f,definition.statusResistance*
                   Mathf.Max(
                       0.01f,
                       ownedInstance.statusResistanceMultiplier)),
            speedTilesPerSecond=definition.moveSpeedTilesPerSecond*
                Mathf.Max(0.01f,ownedInstance.moveSpeedMultiplier)*CombatMovementSpeedScale,
            collisionRadius=definition.collisionRadius*
                (UsesHexDeployment?HexDeploymentUnitScale:1f),
            attackRange=definition.attackRange,
            attackInterval=definition.attackInterval/
                Mathf.Max(0.01f,ownedInstance.attackSpeedMultiplier)*CombatAttackIntervalScale,
            skillCooldownDuration=BaseSkillCooldown(definition.skillId)
        };
        unit.targetRing=ring.GetComponent<CombatTargetRing>()??ring.AddComponent<CombatTargetRing>();
        ConfigureTargetRing(unit);
        BindSpiritGuardianProtection(unit);
        BindProjectileSource(unit);
        unit.skillTimer=InitialSkillCooldown(unit);
        unit.maxHp=unit.hp;
        if(concertOwner==null)units.Add(unit);
        unit.combatStatuses.Applied+=
            effect=>HandleCombatStatusApplied(unit,effect);
        if(concertOwner!=null)
        {ConfigureSpiritConcertGhost(unit,concertOwner);return unit;}
        RefreshUnitFromOwnedData(unit,definition,ownedInstance);
        if(spawnInStorage)
        {
            if(!MoveUnitToBench(unit,BenchSlotIndex(coordinate),false))
            {
                unit.inStorage=true;
                model.SetActive(false);
                ring.SetActive(false);
                Debug.LogWarning("Battle bench is full; monster returned to permanent storage: "+unit.displayName);
            }
        }
        else OccupyUnit(unit,coordinate);
        return unit;
    }

    private List<Unit> BattleReadyUnits()
    {
        return units.Where(unit=>unit.team==Team.Player&&unit.ownedInstance!=null).ToList();
    }

    private int FindAvailableBenchSlot(Unit ignored=null,int preferred=-1)
    {
        if(preferred>=0&&preferred<BenchSlotCount)
        {
            Unit occupant=UnitAt(BenchCoordinate(preferred));
            if(occupant==null||occupant==ignored)return preferred;
        }
        for(int slot=0;slot<BenchSlotCount;slot++)
        {
            Unit occupant=UnitAt(BenchCoordinate(slot));
            if(occupant==null||occupant==ignored)return slot;
        }
        return -1;
    }

    private bool MoveUnitToBench(Unit unit,int preferredSlot,bool save)
    {
        if(unit==null||unit.team!=Team.Player)return false;
        int slot=FindAvailableBenchSlot(unit,preferredSlot);
        if(slot<0)return false;
        ReleaseUnitOccupancy(unit);
        unit.inStorage=true;
        unit.currentTile=BenchCoordinate(slot);
        occupancy[unit.currentTile]=unit;
        unit.velocity=Vector3.zero;
        unit.moving=false;
        SetMoving(unit,false);
        if(unit.outline!=null)unit.outline.SetOutlined(false);
        if(unit.model!=null)unit.model.SetActive(true);
        if(unit.ring!=null)unit.ring.SetActive(true);
        ApplyDeploymentTransform(unit);
        if(save)SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,true);
        return true;
    }

    private void HandleInput()
    {
        if(GameFrontend.BlocksBackgroundInput)return;
        if(battleEnding||waveIntroActive||waveArrivalActive||
           resultText.Length>0)return;
        if(CompletedItemChoiceVisible||ReserveReinforcementChoiceVisible||
           AugmentDraftVisible||
           GrowthCardDraftVisible||GrowthShopVisible||shopVisible)return;
        if(mlEpisodeActive)return;
        int tutorialStep=FirstExpeditionBattleTutorialStep;
        if(tutorialStep>=0)
        {
            if(tutorialStep==3&&Input.GetKeyDown(KeyCode.Space))
                StartCurrentBattle();
            if(tutorialStep!=2)return;
        }
#if UNITY_EDITOR
        if(balanceTestRunning)return;
        if(Input.GetKeyDown(KeyCode.F7))traitTestPanelVisible=!traitTestPanelVisible;
        if(!battleStarted&&Input.GetKeyDown(KeyCode.F8))GrantDebugBasicItems();
        if(Input.GetKeyDown(KeyCode.F9)){ToggleComboQa();return;}
#endif
        if(Input.GetKeyDown(KeyCode.Space))
        {
            if(!battleStarted)
            {
                if(expeditionFailed)return;
                StartCurrentBattle();
            }
            else if(!battleEnding)
            {paused=!paused;if(paused)Rank4CinematicAudio.StopAll();}
        }
        if(battleStarted)
        {
            if(Input.GetMouseButtonDown(1))
            {
                inspectedUnit=null;
                return;
            }
            if(Input.GetMouseButtonDown(0)&&!IsPointerOverItemUi())
                inspectedUnit=hoveredUnit;
            return;
        }
        if(draggingUnit)
        {
            UpdateDraggedVisual();
            if(Input.GetMouseButtonDown(1)||Input.GetKeyDown(KeyCode.Escape)){CancelDraggedUnit();return;}
            if(Input.GetMouseButtonUp(0))
            {
                FinishDraggedUnit();
            }
            return;
        }
        if(pressedUnit!=null)
        {
            if(Input.GetMouseButtonDown(1)||Input.GetKeyDown(KeyCode.Escape))
            {
                ClearPreparationSelection();
                return;
            }
            if(Input.GetMouseButton(0)&&
               Vector2.Distance(unitPressScreenPosition,
                   new Vector2(Input.mousePosition.x,Input.mousePosition.y))>=
               UnitDragThresholdPixels)
            {
                Unit dragTarget=pressedUnit;
                pressedUnit=null;
                BeginDragUnit(dragTarget);
                return;
            }
            if(Input.GetMouseButtonUp(0))pressedUnit=null;
            return;
        }
        if(IsPointerOverItemUi())return;
        if(Input.GetMouseButtonDown(1))
        {
            SetSelectedUnit(null);inspectedUnit=null;
            ClearCaptureTarget();
            return;
        }
        if(!Input.GetMouseButtonDown(0))return;
        if(hoveredUnit!=null&&hoveredUnit.team==Team.Enemy)
        {
            inspectedUnit=hoveredUnit;
            return;
        }
        if(hoveredUnit!=null&&hoveredUnit.team==Team.Player)
        {
            if(FirstDeploymentGuideVisible&&
               (!hoveredUnit.inStorage||!CanAffordDeployment(hoveredUnit)))return;
            inspectedUnit=hoveredUnit;
            pressedUnit=hoveredUnit;
            unitPressScreenPosition=
                new Vector2(Input.mousePosition.x,Input.mousePosition.y);
            return;
        }
        if(hoveredTile.x<0){ClearPreparationSelection();return;}
        Unit occupant=UnitAt(hoveredTile);
        if(occupant!=null&&occupant.team==Team.Player)
        {
            if(FirstDeploymentGuideVisible&&
               (!occupant.inStorage||!CanAffordDeployment(occupant)))return;
            inspectedUnit=occupant;
            pressedUnit=occupant;
            unitPressScreenPosition=
                new Vector2(Input.mousePosition.x,Input.mousePosition.y);
        }
        else ClearPreparationSelection();
    }

    private bool FirstExpeditionCaptureGuaranteed=>
        playerProfile!=null&&expeditionRun!=null&&expeditionRun.wave==1&&
        playerProfile.firstExpeditionGuideStep==
            PlayerProfileStore.FirstExpeditionGuideBattleStep;

    private int FirstExpeditionBattleTutorialStep
    {
        get
        {
            if(playerProfile==null||expeditionRun==null||
               playerProfile.firstExpeditionGuideStep!=
                   PlayerProfileStore.FirstExpeditionGuideBattleStep)return -1;
            int step=playerProfile.firstExpeditionCaptureGuideStep;
            if(expeditionRun.wave==1&&step>=0&&step<4)return step;
            if(expeditionRun.wave==2&&step>=4&&step<8)return step;
            return -1;
        }
    }

    private bool FirstExpeditionBattleTutorialActive=>
        FirstExpeditionBattleTutorialStep>=0;

    private bool FirstAugmentGuideVisible=>
        FirstExpeditionBattleTutorialStep==0&&AugmentDraftVisible;

    private bool FirstGrowthShopGuideVisible=>
        IsFirstGrowthShopTutorialPending(playerProfile)&&expeditionRun!=null&&
        expeditionRun.wave==1&&GrowthShopVisible&&
        !expeditionRun.growthShopFreePurchaseUsed;

    private static bool IsFirstGrowthShopTutorialPending(
        PlayerProfileSave profile)=>
        profile!=null&&profile.firstExpeditionGuideStep==
            PlayerProfileStore.FirstExpeditionGuideBattleStep&&
        profile.firstExpeditionCaptureGuideStep==0;

    private bool FirstCaptureGuideVisible=>
        playerProfile!=null&&expeditionRun!=null&&
        FirstExpeditionCaptureGuaranteed&&
        expeditionRun.wave==1&&
        expeditionRun.growthShopCompletedWave==expeditionRun.wave&&
        playerProfile.firstExpeditionCaptureGuideStep==1&&
        !battleStarted&&!battleEnding&&resultText.Length==0&&
        !mapIntroductionActive&&!waveArrivalActive&&!waveIntroActive&&
        !augmentDraftIntroductionActive&&!AugmentDraftVisible&&
        !GrowthShopVisible&&!shopVisible&&
        !CompletedItemChoiceVisible&&!ReserveReinforcementChoiceVisible;

    private bool FirstDeploymentGuideVisible=>
        FirstExpeditionBattleTutorialStep==2&&TutorialPreparationVisible;

    private bool FirstBattleStartGuideVisible=>
        FirstExpeditionBattleTutorialStep==3&&TutorialPreparationVisible;

    private bool FirstItemCombineGuideVisible=>
        FirstExpeditionBattleTutorialStep==5&&TutorialPreparationVisible;

    private bool FirstItemEquipGuideVisible=>
        FirstExpeditionBattleTutorialStep==6&&TutorialPreparationVisible;

    private bool FirstItemTransferGuideVisible=>
        FirstExpeditionBattleTutorialStep==7&&TutorialPreparationVisible;

    private bool FirstItemGuideVisible=>
        FirstItemCombineGuideVisible||FirstItemEquipGuideVisible||
        FirstItemTransferGuideVisible;

    private bool TutorialPreparationVisible=>
        !battleStarted&&!battleEnding&&resultText.Length==0&&
        !mapIntroductionActive&&!waveArrivalActive&&!waveIntroActive&&
        !augmentDraftIntroductionActive&&!AugmentDraftVisible&&
        !GrowthShopVisible&&!shopVisible&&
        !CompletedItemChoiceVisible&&!ReserveReinforcementChoiceVisible;

    private float EffectiveCaptureChance(CaptureNetDefinition net)
    {
        return Mathf.Clamp01(CaptureNetCatalog.EffectiveSuccessChance(
            net,FirstExpeditionCaptureGuaranteed)+
            PermanentResearchSystem.CaptureChanceBonus(playerProfile));
    }

    private bool TryBeginFirstCaptureGuide()
    {
        if(playerProfile==null||expeditionRun==null||
           !FirstExpeditionCaptureGuaranteed||expeditionRun.wave!=1||
           expeditionRun.growthShopCompletedWave!=expeditionRun.wave||
           playerProfile.firstExpeditionCaptureGuideStep>=2)
            return false;
        if(playerProfile.firstExpeditionCaptureGuideStep==0)
        {
            CaptureNetInventory.Grant(
                playerProfile,CaptureNetCatalog.StandardId,1);
            playerProfile.firstExpeditionCaptureGuideStep=1;
            firstCaptureGuideChangedAt=Time.unscaledTime;
            SaveExpeditionCheckpoint(
                ExpeditionRunCheckpoint.Preparation,true);
        }
        if(firstCaptureGuideChangedAt<0f)
            firstCaptureGuideChangedAt=Time.unscaledTime;
        return true;
    }

    private bool TryBeginFirstItemGuide()
    {
        if(playerProfile==null||expeditionRun==null||expeditionRun.wave!=2||
           playerProfile.firstExpeditionGuideStep!=
               PlayerProfileStore.FirstExpeditionGuideBattleStep)return false;
        int step=playerProfile.firstExpeditionCaptureGuideStep;
        if(step==4)
        {
            int baseItems=expeditionRun.inventoryItemInstanceIds.Count(id=>
            {
                ExpeditionItemInstanceSave instance=
                    ExpeditionItemSystem.ItemInstance(expeditionRun,id);
                return GameMasterData.Item(instance==null?"":instance.itemId)?.IsBase==true;
            });
            if(baseItems<2)return false;
            SetFirstExpeditionBattleTutorialStep(4,5);
            return true;
        }
        return step>=5&&step<=7;
    }

    private void CompleteFirstCaptureGuide()
    {
        if(!FirstCaptureGuideVisible)return;
        SetFirstExpeditionBattleTutorialStep(1,2);
        EnsureFirstTutorialDeploymentSpace();
    }

    private void CompleteFirstDeploymentGuide()
    {
        SetFirstExpeditionBattleTutorialStep(2,3);
    }

    private void CompleteFirstBattleStartGuide()
    {
        SetFirstExpeditionBattleTutorialStep(3,4);
    }

    private void SetFirstExpeditionBattleTutorialStep(int expected,int next)
    {
        if(playerProfile==null||
           playerProfile.firstExpeditionGuideStep!=
               PlayerProfileStore.FirstExpeditionGuideBattleStep||
           playerProfile.firstExpeditionCaptureGuideStep!=expected)return;
        playerProfile.firstExpeditionCaptureGuideStep=next;
        firstCaptureGuideChangedAt=Time.unscaledTime;
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,true);
        ClearPreparationSelection();
    }

    private void EnsureFirstTutorialDeploymentSpace()
    {
        if(CurrentDeploymentCount<MaxDeploymentCount)return;
        Unit unit=units.Where(value=>value!=null&&value.team==Team.Player&&
            value.alive&&!value.inStorage).OrderByDescending(value=>
                value.currentTile.y).ThenByDescending(value=>
                value.currentTile.x).FirstOrDefault();
        if(unit!=null)MoveUnitToBench(unit,-1,true);
    }

    private bool SetCaptureTarget(Unit target,string netItemId)
    {
        if(battleStarted||resultText.Length>0||target==null||target.team!=Team.Enemy||
           !target.alive||expeditionRun==null)return false;
        if(expeditionRun.captureAttemptedWave==expeditionRun.wave)
        {
            captureUiMessage="이번 Wave에서는 이미 포획 그물을 사용했습니다.";
            return false;
        }
        CaptureNetDefinition net=CaptureNetCatalog.Get(netItemId);
        if(net==null)return false;
        if(profileStore.CaptureNetCount(playerProfile,netItemId)<=0)
        {
            captureUiMessage=GameLocalization.Format("capture.net_unavailable",
                "{0}이(가) 없습니다.",GameLocalization.Text(net.displayName));
            return false;
        }
        captureTarget=target;
        expeditionRun.selectedCaptureEnemyInstanceId=target.stableId;
        expeditionRun.selectedCaptureNetItemId=netItemId;
        captureUiMessage="";
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,true);
        if(FirstCaptureGuideVisible)CompleteFirstCaptureGuide();
        return true;
    }

    private void ClearCaptureTarget(bool save=true)
    {
        captureTarget=null;
        draggedCaptureNetItemId="";
        draggingCaptureNet=false;
        pendingCapture.Clear();
        captureUiMessage="";
        if(expeditionRun!=null)
        {
            expeditionRun.selectedCaptureEnemyInstanceId="";
            expeditionRun.selectedCaptureNetItemId="";
        }
        if(save)
            SaveExpeditionCheckpoint(
                ExpeditionRunCheckpoint.Preparation,true);
    }

    private void RestoreCaptureSelection()
    {
        captureTarget=null;
        if(expeditionRun==null||
           expeditionRun.captureAttemptedWave==expeditionRun.wave||
           string.IsNullOrWhiteSpace(
               expeditionRun.selectedCaptureEnemyInstanceId)||
           !CaptureNetCatalog.IsCaptureNet(
               expeditionRun.selectedCaptureNetItemId)||
           profileStore.CaptureNetCount(
               playerProfile,expeditionRun.selectedCaptureNetItemId)<=0)
            return;
        captureTarget=units.FirstOrDefault(unit=>
            unit!=null&&unit.team==Team.Enemy&&unit.alive&&
            string.Equals(
                unit.stableId,
                expeditionRun.selectedCaptureEnemyInstanceId,
                StringComparison.Ordinal));
        if(captureTarget==null)
        {
            expeditionRun.selectedCaptureEnemyInstanceId="";
            expeditionRun.selectedCaptureNetItemId="";
            return;
        }
        captureUiMessage="";
    }

    private void StartCurrentBattle()
    {
        if(wavePreparationAcrossFrames)return;
        if(battleStarted||waveIntroActive||waveArrivalActive||expeditionFailed||
           AugmentDraftVisible||GrowthShopVisible||shopVisible||
           CompletedItemChoiceVisible||ReserveReinforcementChoiceVisible)return;
        if(CurrentDeploymentCount<=0)return;
        if(FirstExpeditionBattleTutorialActive&&!FirstBattleStartGuideVisible)return;
        if(FirstBattleStartGuideVisible)CompleteFirstBattleStartGuide();
        if(ShouldSkipWaveIntro())
        {
            BeginCurrentBattleImmediately();
            return;
        }
        shopVisible=false;
        if(draggingUnit)CancelDraggedUnit();
        SetSelectedUnit(null);
        ResetAllOutlines();
        waveIntroElapsed=0f;
        waveIntroActive=true;
        if(!mlEpisodeActive)GameAudio.Play(GameAudio.Cue.Start);
    }

    public bool CombatEffectTestBattleRunning=>
        battleStarted||waveIntroActive||waveArrivalActive;

    public bool StartPreparedCombatEffectTestBattle()
    {
        if(!CombatEffectTestConfiguration.Active||battleStarted||waveIntroActive||
           waveArrivalActive||expeditionFailed||AugmentDraftVisible||
           GrowthShopVisible)return false;
        StartCurrentBattle();
        return battleStarted||waveIntroActive;
    }

    private bool ShouldSkipWaveIntro()
    {
        if(mlEpisodeActive||corruptionDiagnosticRunning)return true;
#if UNITY_EDITOR
        if(balanceTestRunning)return true;
#endif
        return false;
    }

    private void BeginMapIntroduction()
    {
        if(ShouldSkipWaveIntro())
        {
            mapIntroductionElapsed=MapIntroductionDuration;
            ContinueWavePreparationFlow();
            return;
        }
        mapIntroductionElapsed=0f;
        mapIntroductionActive=true;
        HideMapIntroductionObjects();
        SetSelectedUnit(null);
        ResetAllOutlines();
    }

    private void UpdateMapIntroduction(float unscaledDeltaTime)
    {
        mapIntroductionElapsed+=Mathf.Max(0f,unscaledDeltaTime);
        if(mapIntroductionElapsed<MapIntroductionDuration)return;
        mapIntroductionActive=false;
        RestoreMapIntroductionObjects();
        ContinueWavePreparationFlow();
    }

    private void HideMapIntroductionObjects()
    {
        RestoreMapIntroductionObjects();
        foreach(Unit unit in units)
        {
            HideMapIntroductionObject(unit.model);
            HideMapIntroductionObject(unit.ring);
        }
        if(placementMarkerRoot!=null)
            HideMapIntroductionObject(placementMarkerRoot.gameObject);
    }

    private void HideMapIntroductionObject(GameObject target)
    {
        if(target==null||!target.activeSelf||
           mapIntroductionHiddenObjects.Contains(target))return;
        mapIntroductionHiddenObjects.Add(target);
        target.SetActive(false);
    }

    private void RestoreMapIntroductionObjects()
    {
        foreach(GameObject target in mapIntroductionHiddenObjects)
            if(target!=null)target.SetActive(true);
        mapIntroductionHiddenObjects.Clear();
    }

    private void BeginAugmentDraftIntroduction()
    {
        augmentDraftRevealStartedAt=-1f;
        if(ShouldSkipWaveIntro())
        {
            augmentDraftIntroductionActive=false;
            augmentDraftIntroductionElapsed=AugmentDraftIntroductionDuration;
            augmentDraftRevealStartedAt=Time.unscaledTime;
            return;
        }
        augmentDraftIntroductionElapsed=0f;
        augmentDraftIntroductionActive=true;
        Debug.Assert(!AugmentDraftVisible,
            "The augment cards must stay hidden during their introduction.");
        SetSelectedUnit(null);
        ResetAllOutlines();
    }

    private void UpdateAugmentDraftIntroduction(float unscaledDeltaTime)
    {
        augmentDraftIntroductionElapsed+=Mathf.Max(0f,unscaledDeltaTime);
        if(augmentDraftIntroductionElapsed<AugmentDraftIntroductionDuration)return;
        augmentDraftIntroductionActive=false;
        augmentDraftRevealStartedAt=Time.unscaledTime;
    }

    private void UpdateWaveIntro(float unscaledDeltaTime)
    {
        waveIntroElapsed+=Mathf.Max(0f,unscaledDeltaTime);
        if(waveIntroElapsed<BattleStartCueDuration)return;
        waveIntroActive=false;
        BeginCurrentBattleImmediately();
    }

    private void BeginWaveArrival()
    {
        if(ShouldSkipWaveIntro())return;
        waveArrivalElapsed=0f;
        waveArrivalActive=true;
        SetSelectedUnit(null);
        ResetAllOutlines();
    }

    private void UpdateWaveArrival(float unscaledDeltaTime)
    {
        waveArrivalElapsed+=Mathf.Max(0f,unscaledDeltaTime);
        if(waveArrivalElapsed<WaveArrivalDuration)return;
        waveArrivalActive=false;
        if(resumeBattlePending)
        {
            resumeBattlePending=false;
            StartCurrentBattle();
        }
        else ContinueWavePreparationFlow();
    }

    private void BeginCurrentBattleImmediately()
    {
        if(wavePreparationAcrossFrames)return;
        if(battleStarted||expeditionFailed||AugmentDraftVisible||
           GrowthShopVisible||shopVisible)return;
        shopVisible=false;
        shopOpenedFromPreparation=false;
        if(draggingUnit)CancelDraggedUnit();
        CaptureWaveStartingFormation();
        ExpeditionAugmentRuntime.PreparePandoraWorkshopWave(expeditionRun);
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.InBattle,true,BeginSavedBattle);
    }

    private void BeginSavedBattle()
    {
        if(expeditionRun.activeBattleSeed!=0)
            UnityEngine.Random.InitState(expeditionRun.activeBattleSeed);
        BeginWaveLootAttempt();
        pendingCapture.Clear();
        CaptureNetDefinition selectedNet=CaptureNetCatalog.Get(
            expeditionRun.selectedCaptureNetItemId);
        if(IsCombatActive(captureTarget)&&selectedNet!=null&&
           expeditionRun.captureAttemptedWave!=expeditionRun.wave)
        {
            float successChance=EffectiveCaptureChance(selectedNet);
            pendingCapture.Arm(
                captureTarget.stableId,
                selectedNet.itemId,
                successChance);
            captureUiMessage="포획 시도 중: "+captureTarget.definition.displayName+
                             "  ·  처치 시 "+
                             Mathf.RoundToInt(successChance*100f)+
                             "% 판정";
        }
        battleStarted=true;
        combatDataSelectedWave=expeditionRun.wave;
        nextCombatContributionRefreshAt=0f;
        paused=false;
        if(!mlEpisodeActive)
        {
            GameAudio.ResetCombatSounds();
            GameAudio.SetBattlePhase(true);
        }
        lastCombatProgressAt=0f;
        nextStalemateRecoveryAt=StalemateRecoveryDelay;
        stalemateRecoveryCount=0;
        SetSelectedUnit(null);
        ResetAllOutlines();
        BindTwinCommandUnits();
        occupancy.Clear();
        SpawnAugmentShadowClone();
        BeginSpiritGuardians();
        BeginHaetaeDevourers();
        // Equipment can change throughout preparation; grant opening effects only when combat begins.
        foreach(Unit unit in units)
            if(IsCombatActive(unit)&&!unit.augmentShadowClone)
            {
                ApplyBattleStartItemEffects(unit);
                UpdateUnitShieldVisual(unit);
            }
        ApplyBattleStartAugments();
        ApplyRegionBattleStartRule();
        ApplyOpeningAttackStagger();
        combatCameraDirector?.BeginBattle();
        BeginTelemetryEpisode();
        BeginGriffinStormOrbs();
    }

    private void ApplyRegionBattleStartRule()
    {
        nextRegionRuleAt=HunterRegionCatalog.PeriodicRuleInterval(
            expeditionRun.regionId);
        if(HunterRegionCatalog.Rule(expeditionRun.regionId)==
           HunterRegionRule.SkyResonance)
            foreach(Unit unit in units.Where(value=>IsCombatActive(value)&&
                         !value.inStorage))
                unit.skillTimer=ExpeditionAugmentRuntime.ChargeSkillCooldown(
                    unit.skillTimer,unit.skillCooldownDuration,0.20f);

        Unit guardian=units.FirstOrDefault(unit=>
            IsCombatActive(unit)&&(unit.regionGuardian||unit.guardianPreview));
        if(guardian!=null)
            PlayTraitBurst(guardian,new Color(1f,0.62f,0.18f),true);
    }

    private void ApplyOpeningAttackStagger()
    {
        for(int i=0;i<units.Count;i++)
        {
            Unit unit=units[i];
            if(!IsCombatActive(unit))continue;
            unit.cooldown=Mathf.Max(unit.cooldown,OpeningAttackDelay(unit.id));
        }
    }

    private void UpdateRegionBattleRule()
    {
        HunterRegionRule rule=HunterRegionCatalog.Rule(expeditionRun.regionId);
        float interval=HunterRegionCatalog.PeriodicRuleInterval(
            expeditionRun.regionId);
        if(interval<=0f||battleElapsed<nextRegionRuleAt)return;
        nextRegionRuleAt+=interval;
        List<Unit> active=units.Where(unit=>IsCombatActive(unit)&&
            !unit.inStorage).ToList();
        for(int i=0;i<active.Count;i++)
        {
            Unit target=active[i];
            Unit source=active.Where(unit=>unit.team!=target.team)
                .OrderBy(unit=>Vector3.SqrMagnitude(
                    Flat(unit.model.transform.position)-
                    Flat(target.model.transform.position)))
                .FirstOrDefault();
            if(source==null)continue;
            if(rule==HunterRegionRule.PoisonFog)
            {
                target.combatStatuses.ApplyStacks(
                    CombatStatusKind.Poison,interval*2.05f,1,
                    CombatStatusState.MaximumPoisonStacks,source,
                    target.maxHp*0.003f,1f,true,true);
                PlayPeriodicStatusDamageEffect(target,CombatStatusKind.Poison);
            }
            else if(rule==HunterRegionRule.FrostWave)
            {
                bool frozen=ApplyStackingFrost(
                    source,target,interval*2.05f,3,1f);
                if(!frozen)
                    PlayTraitBurst(target,new Color(0.34f,0.78f,1f),false);
            }
        }
    }

    private void BeginDragUnit(Unit unit)
    {
        if(unit==null||!unit.alive)return;
        if(FirstDeploymentGuideVisible&&
           (!unit.inStorage||!CanAffordDeployment(unit)))return;
        draggingUnit=true;
        inspectedUnit=unit;
        dragStartedFromBench=unit.inStorage;
        dragOrigin=unit.currentTile;
        if(unit.model!=null)unit.model.SetActive(true);
        SetMoving(unit,false);
        if(unit.spriteAnimation!=null)
            unit.spriteAnimation.SetStruggling(true);
        SetSelectedUnit(unit);
        UpdateDraggedVisual();
    }

    private void UpdateDraggedVisual()
    {
        if(!draggingUnit||selectedUnit==null||mainCamera==null)return;
        Ray ray=mainCamera.ScreenPointToRay(Input.mousePosition);
        Plane plane=new Plane(Vector3.up,Vector3.zero);
        if(plane.Raycast(ray,out float distance))
        {
            Vector3 pointer=ray.GetPoint(distance);
            Vector3 lifted=pointer+Vector3.up*(selectedUnit.visualHeightOffset+DragLiftHeight);
            selectedUnit.model.transform.position=lifted;
        }
        Vector2Int ringTile=tiles.ContainsKey(hoveredTile)?hoveredTile:dragOrigin;
        if(tiles.ContainsKey(ringTile))
            selectedUnit.ring.transform.position=GetFootprintCenterWorld(ringTile,selectedUnit.footprint)+Vector3.up*0.055f;
    }

    private void FinishDraggedUnit()
    {
        if(!draggingUnit)return;
        Unit movedUnit=selectedUnit;
        bool movedFromBench=dragStartedFromBench;
        if(selectedUnit!=null&&selectedUnit.spriteAnimation!=null)
            selectedUnit.spriteAnimation.SetStruggling(false);
        draggingUnit=false;
        if(TryPlaceSelectedUnit(hoveredTile))
        {
            GameAudio.Play(GameAudio.Cue.Place);
            dragOrigin=new Vector2Int(-1,-1);
            if(movedFromBench&&movedUnit!=null&&!movedUnit.inStorage&&
               FirstDeploymentGuideVisible)
                CompleteFirstDeploymentGuide();
            return;
        }
        ReturnDraggedUnitToOrigin();
    }

    private void CancelDraggedUnit()
    {
        if(!draggingUnit)return;
        if(selectedUnit!=null&&selectedUnit.spriteAnimation!=null)
            selectedUnit.spriteAnimation.SetStruggling(false);
        draggingUnit=false;
        ReturnDraggedUnitToOrigin();
    }

    private void ReturnDraggedUnitToOrigin()
    {
        Unit unit=selectedUnit;
        Vector2Int origin=dragOrigin;
        if(unit!=null&&tiles.ContainsKey(origin))
        {
            OccupyUnit(unit,origin);
            unit.inStorage=tiles[origin].bench;
            if(unit.ring!=null)unit.ring.SetActive(true);
            ApplyDeploymentTransform(unit);
        }
        dragOrigin=new Vector2Int(-1,-1);
        dragStartedFromBench=false;
        SetSelectedUnit(null);
        RefreshTileVisual(origin);RefreshTileVisual(hoveredTile);
    }

    private bool TryPlaceSelectedUnit(Vector2Int destination)
    {
        if(selectedUnit==null||!tiles.TryGetValue(destination,out Tile destinationTile))return false;
        if(FirstDeploymentGuideVisible&&
           (!dragStartedFromBench||destinationTile.bench))return false;
        Unit destinationOccupant=UnitAt(destination);
        if(destinationOccupant!=null&&destinationOccupant!=selectedUnit)
            return TrySwapSelectedUnit(destinationOccupant);
        if(destinationTile.bench)
        {
            if(selectedUnit.team!=Team.Player)return false;
            int slot=BenchSlotIndex(destination);
            if(slot<0||
               !MoveUnitToBench(selectedUnit,slot,true))return false;
            draggingUnit=false;
            dragStartedFromBench=false;
            dragOrigin=new Vector2Int(-1,-1);
            SetSelectedUnit(null);
            return true;
        }
        if(!CanAffordDeployment(selectedUnit)||
           !CanPlaceUnit(selectedUnit,destination,true))return false;
        Vector2Int previous=selectedUnit.currentTile;
        OccupyUnit(selectedUnit,destination);
        selectedUnit.inStorage=false;
        selectedUnit.model.SetActive(true);
        if(selectedUnit.ring!=null)selectedUnit.ring.SetActive(true);
        ApplyDeploymentTransform(selectedUnit);
        dragStartedFromBench=false;
        dragOrigin=new Vector2Int(-1,-1);
        SetSelectedUnit(null);
        RefreshTileVisual(previous);RefreshTileVisual(destination);
        SaveExpeditionCheckpoint(ExpeditionRunCheckpoint.Preparation,true);
        return true;
    }

    private bool TrySwapSelectedUnit(Unit other)
    {
        if(!CanSwapSelectedUnitWith(other))return false;
        Unit moving=selectedUnit;
        Vector2Int movingOrigin=moving.currentTile;
        Vector2Int otherOrigin=other.currentTile;
        bool movingWasStored=moving.inStorage;
        bool otherWasStored=other.inStorage;

        ReleaseUnitOccupancy(moving);
        ReleaseUnitOccupancy(other);
        OccupyUnit(moving,otherOrigin);
        OccupyUnit(other,movingOrigin);
        moving.inStorage=otherWasStored;
        other.inStorage=movingWasStored;
        moving.model.SetActive(true);
        other.model.SetActive(true);
        if(moving.ring!=null)moving.ring.SetActive(true);
        if(other.ring!=null)other.ring.SetActive(true);
        ApplyDeploymentTransform(moving);
        ApplyDeploymentTransform(other);

        dragStartedFromBench=false;
        dragOrigin=new Vector2Int(-1,-1);
        SetSelectedUnit(null);
        inspectedUnit=moving;
        RefreshTileVisual(movingOrigin);
        RefreshTileVisual(otherOrigin);
        SaveExpeditionCheckpoint(ExpeditionRunCheckpoint.Preparation,true);
        return true;
    }

    private bool CanSwapSelectedUnitWith(Unit other)
    {
        if(selectedUnit==null||other==null||other==selectedUnit||
           selectedUnit.team!=Team.Player||other.team!=Team.Player)return false;
        Vector2Int movingOrigin=selectedUnit.currentTile;
        Vector2Int otherOrigin=other.currentTile;
        if(movingOrigin==otherOrigin)return false;
        if(!CanOccupySwapDestination(selectedUnit,otherOrigin,selectedUnit,other)||
           !CanOccupySwapDestination(other,movingOrigin,selectedUnit,other))
            return false;

        HashSet<Vector2Int> movingTiles=new HashSet<Vector2Int>(
            GetFootprintTiles(otherOrigin,selectedUnit.footprint));
        if(GetFootprintTiles(movingOrigin,other.footprint)
            .Any(movingTiles.Contains))return false;

        int projected=CurrentDeploymentCount;
        if(!selectedUnit.inStorage)projected-=selectedUnit.deploymentSlots;
        if(!other.inStorage)projected-=other.deploymentSlots;
        if(!other.inStorage)projected+=selectedUnit.deploymentSlots;
        if(!selectedUnit.inStorage)projected+=other.deploymentSlots;
        return projected<=MaxDeploymentCount;
    }

    private bool CanOccupySwapDestination(
        Unit unit,Vector2Int anchor,Unit ignoredA,Unit ignoredB)
    {
        if(unit==null||!tiles.TryGetValue(anchor,out Tile anchorTile))return false;
        if(anchorTile.bench)
            return unit.footprint==Vector2Int.one&&BenchSlotIndex(anchor)>=0;
        List<Vector2Int> footprint=GetFootprintTiles(anchor,unit.footprint);
        for(int i=0;i<footprint.Count;i++)
        {
            if(!tiles.TryGetValue(footprint[i],out Tile tile)||!tile.walkable||
               tile.bench||tile.deploymentTeam!=Team.Player)return false;
            if(occupancy.TryGetValue(footprint[i],out Unit occupant)&&
               occupant!=ignoredA&&occupant!=ignoredB)return false;
        }
        return true;
    }

    private void ArrangePlayerFormationForNewWave(IReadOnlyCollection<string> preferredDeployedIds)
    {
        List<Unit> players=BattleReadyUnits();
        bool preservePreviousTiles=preferredDeployedIds!=null;
        HashSet<string> preferred=preferredDeployedIds==null
            ?new HashSet<string>(players.Take(MaxDeploymentCount).Select(unit=>unit.stableId),StringComparer.Ordinal)
            :new HashSet<string>(preferredDeployedIds,StringComparer.Ordinal);
        for(int i=0;i<players.Count;i++)ReleaseUnitOccupancy(players[i]);
        List<Vector2Int> deploymentTiles=PlayerDeploymentCoordinates();
        int deploymentIndex=0;
        int deployedSlots=0;
        int benchSlot=0;
        for(int i=0;i<players.Count;i++)
        {
            Unit unit=players[i];
            bool deploy=preferred.Contains(unit.stableId)&&
                        deployedSlots+unit.deploymentSlots<=MaxDeploymentCount;
            Vector2Int destination=new Vector2Int(-1,-1);
            if(deploy)
            {
                if(preservePreviousTiles&&CanPlaceUnit(unit,unit.initialTile,true))
                    destination=unit.initialTile;
                while(destination.x<0&&deploymentIndex<deploymentTiles.Count)
                {
                    Vector2Int candidate=deploymentTiles[deploymentIndex++];
                    if(CanPlaceUnit(unit,candidate,true)){destination=candidate;break;}
                }
            }
            if(destination.x>=0)
            {
                OccupyUnit(unit,destination);
                unit.inStorage=false;
                deployedSlots+=unit.deploymentSlots;
                unit.model.SetActive(true);
                unit.ring.SetActive(true);
                ApplyDeploymentTransform(unit);
                continue;
            }
            int preferredBench=preservePreviousTiles?BenchSlotIndex(unit.initialTile):-1;
            MoveUnitToBench(unit,preferredBench>=0?preferredBench:benchSlot,false);
            benchSlot++;
        }
    }

    private void ArrangePlayerFormationFromRun()
    {
        List<Unit> players=BattleReadyUnits();
        for(int i=0;i<players.Count;i++)ReleaseUnitOccupancy(players[i]);
        List<Vector2Int> fallbackTiles=PlayerDeploymentCoordinates();
        int deployedSlots=0;
        int fallbackBench=0;
        foreach(ExpeditionMonsterStateSave state in expeditionRun.monsters)
        {
            if(state==null)continue;
            Unit unit=players.FirstOrDefault(candidate=>
                candidate.stableId==state.instanceId);
            if(unit==null)continue;
            Vector2Int savedTile=new Vector2Int(
                state.deploymentX,state.deploymentY);
            bool wantsDeployment=state.deployed&&
                deployedSlots+unit.deploymentSlots<=MaxDeploymentCount;
            Vector2Int deploymentTile=savedTile;
            if(wantsDeployment&&!CanPlaceUnit(unit,deploymentTile,true))
                deploymentTile=fallbackTiles.FirstOrDefault(tile=>
                    CanPlaceUnit(unit,tile,true));
            bool deploy=wantsDeployment&&CanPlaceUnit(unit,deploymentTile,true);
            if(deploy)
            {
                OccupyUnit(unit,deploymentTile);
                unit.inStorage=false;
                deployedSlots+=unit.deploymentSlots;
                unit.model.SetActive(true);
                unit.ring.SetActive(true);
                ApplyDeploymentTransform(unit);
            }
            else
            {
                int preferred=state.benchSlot>=0
                    ?state.benchSlot:fallbackBench;
                if(!MoveUnitToBench(unit,preferred,false))
                {
                    unit.inStorage=true;
                    unit.model.SetActive(false);
                    unit.ring.SetActive(false);
                }
                fallbackBench++;
            }
            unit.initialTile=unit.currentTile;
        }
    }

    private void CaptureWaveStartingFormation()
    {
        for(int i=0;i<units.Count;i++)
        {
            Unit unit=units[i];
            unit.initialTile=unit.currentTile;
        }
    }

    private void RestoreWaveStartingFormation()
    {
        occupancy.Clear();
        for(int i=0;i<units.Count;i++)
        {
            Unit unit=units[i];
            unit.inStorage=unit.team==Team.Player&&tiles.TryGetValue(unit.initialTile,out Tile tile)&&tile.bench;
            OccupyUnit(unit,unit.initialTile);
            unit.model.SetActive(true);
            unit.ring.SetActive(unit.alive&&unit.model.activeInHierarchy);
            ApplyDeploymentTransform(unit);
        }
    }

    private void UpdateHoveredTile()
    {
        hoveredTile=NoHoveredTile;
        hoveredUnit=null;
        if(mainCamera==null||!Application.isFocused||GameFrontend.BlocksBackgroundInput)return;
        Vector3 mouse=Input.mousePosition;
        if(!PointerCanHoverBattlefield(mouse,Screen.width,Screen.height))
            return;
        Vector2 guiPoint=BombBrickUiLayout.ScreenToGuiPoint(mouse);
        if(IsPointerOverItemUiAt(guiPoint))return;
        Ray ray=mainCamera.ScreenPointToRay(mouse);
        Plane plane=new Plane(Vector3.up,Vector3.zero);
        if(plane.Raycast(ray,out float distance))
            hoveredTile=NearestSquare(ray.GetPoint(distance));
        hoveredUnit=FindUnitUnderPointer();
    }

    public static bool PointerCanHoverBattlefield(
        Vector3 pointer,int screenWidth,int screenHeight)
    {
        return pointer.x>0f&&pointer.x<screenWidth-1f&&
               pointer.y>0f&&pointer.y<screenHeight-1f;
    }

    private Unit FindUnitUnderPointer()
    {
        Vector2 pointer=BombBrickUiLayout.ScreenToGuiPoint(Input.mousePosition);
        Unit best=null;float bestDistance=float.MaxValue;
        for(int i=0;i<units.Count;i++)
        {
            Unit unit=units[i];
            if(!unit.alive||unit.model==null||!unit.model.activeInHierarchy)continue;
            if(!TryGetUnitGuiRect(unit,out Rect rect)||!rect.Contains(pointer))continue;
            float distance=Vector2.Distance(pointer,rect.center);
            if(distance>=bestDistance)continue;
            bestDistance=distance;best=unit;
        }
        return best;
    }

    private bool TryGetUnitGuiRect(Unit unit,out Rect rect)
    {
        rect=new Rect();
        if(unit==null||unit.model==null||mainCamera==null)return false;
        Renderer[] renderers=unit.outline!=null
            ?unit.outline.TargetRenderers
            :unit.model.GetComponentsInChildren<Renderer>(true);
        if(renderers.Length==0)return false;
        Renderer first=null;
        for(int i=0;i<renderers.Length;i++)
            if(renderers[i]!=null&&renderers[i].enabled){first=renderers[i];break;}
        if(first==null)return false;
        Bounds bounds=first.bounds;
        for(int i=0;i<renderers.Length;i++)
            if(renderers[i]!=null&&renderers[i].enabled)bounds.Encapsulate(renderers[i].bounds);
        Vector3 min=bounds.min,max=bounds.max;
        float minX=float.MaxValue,minY=float.MaxValue,maxX=float.MinValue,maxY=float.MinValue;
        for(int x=0;x<2;x++)for(int y=0;y<2;y++)for(int z=0;z<2;z++)
        {
            Vector3 world=new Vector3(x==0?min.x:max.x,y==0?min.y:max.y,z==0?min.z:max.z);
            Vector3 screen=mainCamera.WorldToScreenPoint(world);
            if(screen.z<=0f)continue;
            screen/=BombBrickUiLayout.Scale;
            float guiY=BombBrickUiLayout.Height-screen.y;
            minX=Mathf.Min(minX,screen.x);maxX=Mathf.Max(maxX,screen.x);
            minY=Mathf.Min(minY,guiY);maxY=Mathf.Max(maxY,guiY);
        }
        if(minX==float.MaxValue)return false;
        const float padding=7f;
        rect=Rect.MinMaxRect(minX-padding,minY-padding,maxX+padding,maxY+padding);
        return true;
    }

    private void UpdatePlacementMarkerHover()
    {
        ClearPlacementMarkerHighlights();
        UpdateBeetleOverturnPreview();
        if(battleStarted||!HasHoveredTile(hoveredTile)||
           !tiles.TryGetValue(hoveredTile,out Tile tile))
            return;
        List<Vector2Int> outlined=draggingUnit&&selectedUnit!=null
            ?GetFootprintTiles(tile.coordinate,selectedUnit.footprint)
            :new List<Vector2Int>{tile.coordinate};
        bool validDrop=!draggingUnit||CanDropSelectedUnit(tile);
        highlightedPlacementColor=validDrop
            ?new Color(1.45f,0.88f,0.12f,1f)
            :new Color(1.35f,0.14f,0.05f,1f);
        for(int i=0;i<outlined.Count;i++)
        {
            if(!tiles.TryGetValue(outlined[i],out Tile outlinedTile))continue;
            highlightedPlacementTiles.Add(outlined[i]);
            RefreshPlacementMarker(outlinedTile);
        }
    }

    private void ClearPlacementMarkerHighlights()
    {
        for(int i=highlightedPlacementTiles.Count-1;i>=0;i--)
        {
            Vector2Int coordinate=highlightedPlacementTiles[i];
            highlightedPlacementTiles.RemoveAt(i);
            if(tiles.TryGetValue(coordinate,out Tile previous))
                RefreshPlacementMarker(previous);
        }
    }

    private bool CanDropSelectedUnit(Tile tile)
    {
        if(selectedUnit==null||tile==null)return false;
        Unit occupant=UnitAt(tile.coordinate);
        if(occupant!=null&&occupant!=selectedUnit)
            return CanSwapSelectedUnitWith(occupant);
        if(tile.bench)
        {
            return true;
        }
        return CanAffordDeployment(selectedUnit)&&
               CanPlaceUnit(selectedUnit,tile.coordinate,true);
    }

    private Vector2Int NearestSquare(Vector3 world)
    {
        Vector2Int best=new Vector2Int(-1,-1);float bestDistance=float.MaxValue;
        foreach(KeyValuePair<Vector2Int,Tile> pair in tiles)
        {
            float distance=(Flat(pair.Value.world)-Flat(world)).sqrMagnitude;
            if(distance>=bestDistance)continue;bestDistance=distance;best=pair.Key;
        }
        return bestDistance<=TileHalfExtent*TileHalfExtent*2.15f
            ?best:NoHoveredTile;
    }

    public static bool HasHoveredTile(Vector2Int coordinate)
    {
        return coordinate!=NoHoveredTile;
    }

    private Vector2Int NearestGridCoordinate(Vector3 world)
    {
        if(UsesHexDeployment)
        {
            Tile nearest=null;
            float nearestDistance=0f;
            Vector3 position=Flat(world);
            foreach(Tile tile in tiles.Values)
            {
                if(tile.bench)continue;
                float distance=(Flat(tile.world)-position).sqrMagnitude;
                if(nearest!=null&&Comparer<float>.Default.Compare(distance,nearestDistance)>=0)continue;
                nearest=tile;nearestDistance=distance;
            }
            return nearest==null?Vector2Int.zero:nearest.coordinate;
        }
        int column=Mathf.Clamp(Mathf.RoundToInt((world.x-mapOffset.x)/TileSize),0,Columns-1);
        int row=Mathf.Clamp(Mathf.RoundToInt((world.z-mapOffset.z)/TileSize),0,Rows-1);
        return new Vector2Int(column,row);
    }

    private void RefreshTileVisual(Vector2Int coordinate)
    {
        if(!tiles.TryGetValue(coordinate,out Tile tile))return;
        tile.renderer.enabled=!UsesHexDeployment&&!environmentBackdropReady;
        Color color=IsTwinCommandTile(tile.coordinate)
            ?Color.Lerp(tile.baseColor,new Color(0.95f,0.52f,0.12f),0.72f)
            :tile.baseColor;
        SetTileColor(tile,color);
        tile.gameObject.transform.position=tile.world;
        RefreshPlacementMarker(tile);
    }

    private void SetSelectedUnit(Unit unit)
    {
        Vector2Int previous=selectedUnit!=null?selectedUnit.currentTile:new Vector2Int(-1,-1);
        if(selectedUnit!=null&&selectedUnit.outline!=null)selectedUnit.outline.SetOutlined(false);
        selectedUnit=unit;
        if(selectedUnit!=null&&selectedUnit.outline!=null)selectedUnit.outline.SetOutlined(!battleStarted);
        RefreshTileVisual(previous);
        if(selectedUnit!=null)RefreshTileVisual(selectedUnit.currentTile);
    }

    private void ResetAllOutlines()
    {
        for(int i=0;i<units.Count;i++)if(units[i].outline!=null)units[i].outline.SetOutlined(false);
    }

    private void RefreshUnitOutlines()
    {
        if(capturePresentationResolving)
        {
            ResetAllOutlines();
            return;
        }
        bool itemTargetsMonster=draggingItem&&!FirstItemCombineGuideVisible;
        Unit transferOwner=null;
        if(FirstItemTransferGuideVisible&&draggingItem)
            TryFindEquippedSlot(draggedItemInstanceId,out transferOwner,out _);
        bool unitTargetDrag=draggingCaptureNet||itemTargetsMonster||
            draggingSpecialItem&&expeditionRun.specialItems.Any(item=>
                item!=null&&item.instanceId==draggedSpecialItemInstanceId&&
                SpecialItemTargetsMonster(item.itemId));
        for(int i=0;i<units.Count;i++)
        {
            Unit unit=units[i];
            if(unit.outline==null)continue;
            bool dragTarget=draggingCaptureNet
                ?unit.team==Team.Enemy
                :unit.team==Team.Player&&(
                    itemTargetsMonster
                        ?unit!=transferOwner&&HasAvailableItemSlot(unit)
                        :unitTargetDrag);
            bool active=ShouldShowOutline(
                battleStarted,unit.inStorage,unit.alive,
                unit.model!=null&&unit.model.activeInHierarchy,
                dragTarget,unitTargetDrag,
                unit==hoveredUnit||unit==selectedUnit||unit==inspectedUnit);
            if(HasSkillCastPresentation(unit))
            {
                bool spotlight=!allyPreparationSequenceActive||SkillPresentationFor(unit).allyPreparationMember;
                unit.outline.SetOutlined(spotlight,true,CombatFlashPresentation.Peak(new Color(1f,.86f,.32f,1f)));
            }
            else
                unit.outline.SetOutlined(active,
                    dragTarget&&unit==hoveredUnit);
        }
    }

    public static bool ShouldShowOutline(
        bool combat,bool inStorage,bool alive,bool modelActive,
        bool validDragTarget,bool targetingUnits,bool focused)
    {
        return alive&&modelActive&&(
            validDragTarget||!combat&&!targetingUnits&&focused);
    }

    private void ConfigureTargetRing(Unit unit)
    {
        if(unit.targetRing==null)return;
        unit.targetRing.Configure(Mathf.Max(.3f,CombatBodyRadius(unit)*1.15f),
            unit.team==Team.Player?new Color(.25f,.92f,.83f,.8f):new Color(1f,.43f,.32f,.8f),
            skillRadiusMarkerMaterial);
    }

    private void UpdateTargetRing(Unit unit)
    {
        bool visible=battleStarted&&!battleEnding&&!capturePresentationResolving&&
            IsCombatActive(unit)&&unit.spiritConcertOwner==null&&
            (unit.spriteBillboard==null||!unit.spriteBillboard.IsFullySubmerged);
        if(unit.targetRing!=null)
        {
            unit.targetRing.SetVisible(visible);
            unit.targetRing.UpdateDirection(Vector3.zero,false);
        }
    }

    private static bool IsCombatActive(Unit unit)
    {
        return unit!=null&&unit.alive&&!unit.inStorage&&unit.model!=null&&unit.model.activeInHierarchy;
    }

    private static bool IsCombatTargetable(Unit unit)
    {
        return IsCombatActive(unit)&&unit.spiritConcertOwner==null&&unit.mantisMolt==null&&!unit.corruptUntargetable&&
            unit.ninjaUntargetableTimer<=0f&&!unit.ninjaCrossActive&&
            !unit.griffinSkyfalling&&unit.monkeyNimbus==null&&unit.augmentReturnTimer<=0f&&unit.crocodileAbyssHeldBy==null;
    }

    public static float AttackDistanceForRange(int attackRange,float sourceRadius,float targetRadius)
    {
        int range=Mathf.Max(1,attackRange);
        float contactDistance=Mathf.Max(0f,sourceRadius)+Mathf.Max(0f,targetRadius)+0.62f;
        float reach=range==1?MeleeAttackReachBonus:
                    range==2?MidrangeAttackReach:RangedAttackReach;
        return contactDistance+reach;
    }

    public static bool ShouldRangedRetreat(
        bool ranged,float distance,float attackDistance,float preferredRangeRatio,
        int attacksSinceRetreat,int attacksBeforeRetreat,bool alreadyRetreating,
        bool hasEscape)
    {
        return ranged&&hasEscape&&distance<attackDistance*preferredRangeRatio&&
               (alreadyRetreating||attacksSinceRetreat>=Mathf.Max(1,attacksBeforeRetreat));
    }

    public static bool CanKiteAtRange(int attackRange)
    {
        return attackRange>=3;
    }

    public static bool MovementMakesForwardProgress(
        int attackRange,Vector3 desired,Vector3 toTarget,
        bool followingDetour=false)
    {
        if(followingDetour||CanKiteAtRange(attackRange))return true;
        desired=Flat(desired);toTarget=Flat(toTarget);
        if(desired.sqrMagnitude<0.0001f)return true;
        if(toTarget.sqrMagnitude<0.0001f)return false;
        return Vector3.Dot(desired.normalized,toTarget.normalized)>0.08f;
    }

    public static bool ShouldMeleeDirectChase(
        bool sourceIsRanged,bool sourceActive,bool targetMoving,
        bool closerMeleeAllyAlreadyChasing,bool flankingRole=false)
    {
        return flankingRole&&!sourceIsRanged&&sourceActive&&targetMoving&&
               !closerMeleeAllyAlreadyChasing;
    }

    public static bool AllowsAttackApproach(float teamFacingDot,bool flankingRole)
    {
        return flankingRole||teamFacingDot<=0.15f;
    }

    public static float StableTargetLockDuration(float authoredDuration)
    {
        return Mathf.Max(MinimumTargetLockDuration,authoredDuration);
    }

    public static float FocusGroupScoreAdjustment(
        int alliedFocus,float personalityFocusBonus)
    {
        int supporters=Mathf.Min(Mathf.Max(0,alliedFocus),2);
        return -supporters*(personalityFocusBonus+FocusGroupBonus)+
               Mathf.Max(0,alliedFocus-2)*OvercrowdedTargetPenalty;
    }

    public static float FrontlineAggroScore(
        int candidateColumn,bool candidateIsPlayer,int columnCount)
    {
        int depth=candidateIsPlayer
            ?Mathf.Max(0,columnCount-1-candidateColumn)
            :Mathf.Max(0,candidateColumn);
        return depth*FrontlineAggroWeight;
    }

    public static float OpeningAttackDelay(int unitId)
    {
        return 0.1f+(uint)unitId%4u*0.08f;
    }

    private static bool IsRangedUnit(Unit unit)
    {
        return unit!=null&&unit.attackRange>1;
    }

    private static bool IsFlankingUnit(Unit unit)
    {
        // Basic pursuit stays direct for every monster. Leap/hunt skills already
        // perform their own movement and must not turn ordinary attacks into
        // permanent side/rear circling.
        return false;
    }

    private float AttackDistance(Unit source,Unit target)
    {
        float distance=AttackDistanceForRange(
            source.attackRange,source.collisionRadius,target.collisionRadius);
        if(MountainColossusActive(source))
            distance+=(BearCombatRules.MountainAttackRangeTiles-1f)*TileSize;
        if(source.rank3MantisReaper)distance=Mathf.Max(distance,TileSize*2f+source.collisionRadius+target.collisionRadius);
        return distance+CombatBodyRadius(source)-source.collisionRadius+
            CombatBodyRadius(target)-target.collisionRadius;
    }

    private static bool MountainColossusActive(Unit unit)
    {
        return unit!=null&&unit.bearMountainColossusActive&&
               unit.bearResolveTimer>0f;
    }

    private float CombatApproachDistance(Unit source,Unit target)
    {
        float attackDistance=AttackDistance(source,target);
        if(source.silkPuppet||source.skillTimer>0f||source.rank3SkillLockTimer>0f||source.griffinRootTimer>0f||
           source.combatStatuses.Has(CombatStatusKind.Silence)||
           source.combatStatuses.Has(CombatStatusKind.Root))return attackDistance;
        SkillMasterRow skill=GameMasterData.Skill(source.skillId);
        if(skill==null||!SkillUseDecision.SupportsBehavior(skill.behavior))return attackDistance;
        // Movement uses the active skill's reach; basic attacks retain their authored reach.
        return Mathf.Min(attackDistance,SkillActivationDistance(source,target,skill)-TileSize*.05f);
    }

    private float SkillActivationDistance(Unit source,Unit target,SkillMasterRow skill)
    {
        if(UsesSabertoothDevour(source))return float.PositiveInfinity;
        float radius=skill.radiusTiles;
        switch(skill.behavior)
        {
            case "HunterFocus": case "FightingSpirit": case "SpiritSanctuary": case "ShadowSlash":
                // Passive, self buffs, healing and unrestricted relocation do not require closing on an enemy.
                return float.PositiveInfinity;
            case "FangLock": case "DeathRoll": case "HighHeadSlam":
                return AttackDistance(source,target)+TileSize*.05f;
            case "EarthPulse":
                if(HasRank3(source,KingKongCombatRules.WorldOverturnTraitId))
                    radius=KingKongCombatRules.WorldOverturnRadiusTiles;
                return TileSize*radius*source.skillTraitRadiusMultiplier;
            case "TyrantTremor":
                if(HasFamilyTranscendence(source))return float.PositiveInfinity;
                if(HasRank3(source,TyrannoRank3Rules.MassExtinction))radius=TyrannoRank3Rules.ExtinctionRadiusTiles;
                else if(HasRank3(source,TyrannoRank3Rules.PrimordialMaw))radius=TyrannoRank3Rules.MawRadiusTiles;
                return TileSize*radius*source.skillTraitRadiusMultiplier;
            case "GuardianTaunt": case "ClusterBreath": case "GroundSlam":
            case "Skyfall":
                return TileSize*Mathf.Max(.1f,radius)*source.skillTraitRadiusMultiplier;
            case "JusticeRoar":
                return TileSize*HaetaeRoarRadius(source,skill)*source.skillTraitRadiusMultiplier;
            case "SkyDive": return GriffinDiveRange(source,skill);
            case "SkyFlip":
                return HasFamilyTranscendence(source)?float.PositiveInfinity:
                    TileSize*Mathf.Max(1f,skill.castRangeTiles)+source.collisionRadius+target.collisionRadius;
            case "WyvernBreath":
                if(HasFamilyTranscendence(source))return float.PositiveInfinity;
                if(HasRank3(source,WyvernRank3Rules.DragonCore))
                    return TileSize*WyvernRank3Rules.CoreRangeTiles+target.collisionRadius;
                if(HasRank3(source,WyvernRank3Rules.WingSweep))
                    return TileSize*WyvernRank3Rules.RainRangeTiles+target.collisionRadius;
                if(HasRank3(source,WyvernRank3Rules.CataclysmBreath))
                    return TileSize*WyvernRank3Rules.PressureRangeTiles+target.collisionRadius;
                return TileSize*Mathf.Max(1f,skill.castRangeTiles);
            case "AssassinLeap":
                return TileSize*Mathf.Max(1f,skill.castRangeTiles);
            case "EarthCharge":
                if(HasFamilyTranscendence(source))return float.PositiveInfinity;
                if(HasRank3(source,MammothRank3Rules.MountainBrace))
                    return TileSize*MammothRank3Rules.BraceSweepTiles*source.skillTraitRadiusMultiplier+target.collisionRadius;
                return TileSize*(HasRank3(source,MammothRank3Rules.MountainToss)?MammothRank3Rules.TossRangeTiles:HasRank3(source,MammothRank3Rules.MountainBrace)?MammothRank3Rules.BraceSweepTiles:MammothCombatRules.MaximumChargeDistanceTiles)+source.collisionRadius+target.collisionRadius;
            case "CrossScytheWind":
                if(source.rank3MantisReaper)return MantisReaperCastRange(source);
                return TileSize*MantisCombatRules.RangeTiles(skill.castRangeTiles,
                    HasRank3(source,MantisCombatRules.SantiusTraitId))+source.collisionRadius+target.collisionRadius;
            default:
                return TileSize*Mathf.Max(skill.behavior=="SporeColony"?0f:1f,skill.castRangeTiles)+
                    source.collisionRadius+target.collisionRadius;
        }
    }

    private static bool RagingHundredStrikesActive(Unit unit)
    {
        return unit!=null&&unit.bearResolveTimer>0f&&MonsterTraitRuntime.Has(
            unit.activeTraitIds,BearCombatRules.RagingHundredStrikesTraitId);
    }

    private bool HasClearAttackLine(Unit source,Unit target)
    {
        if(source==null||target==null||source.model==null||target.model==null)return false;
        return HasClearPathSegment(
            Flat(source.model.transform.position),
            Flat(target.model.transform.position),
            0.08f)&&!IsHostileIceWallBlocking(source,Flat(source.model.transform.position),Flat(target.model.transform.position));
    }

    private void UpdateUnitCore(Unit unit,float dt)
    {
        unit.meleeSlotReady=false;
        if(!IsCombatActive(unit))return;
        unit.spriteAnimation?.SetFrozen(unit.combatStatuses.Has(CombatStatusKind.Freeze)||SpiderSilkBound(unit));
        unit.spriteAnimation?.SetCombatPlaybackSpeed(CombatStatFormula.CombatAnimationRate);
        if(UpdateRank3SpecialUnit(unit,dt))return;
        bool wolfEclipseWasActive=unit.wolfEclipseTimer>0f;
        if(unit.monkeyNimbus==null&&!unit.mammothRicochetActive)EnsureCombatUnitInsideArena(unit);
        float actionSpeed=RaptorCombatRules.IceSpeedMultiplier(
            unit.raptorSlowTimer>0f)*
            (unit.rank3ActionSlowTimer>0f
                ?1f-Mathf.Clamp01(unit.rank3ActionSlowRatio):1f);
        float actionDt=dt*actionSpeed;
        unit.spriteAnimation?.SetGlobalSpeedMultiplier(actionSpeed);
        if(unit.spriteAnimation==null&&unit.animator!=null&&unit.animator.enabled)
            unit.animator.speed=unit.combatStatuses.Has(CombatStatusKind.Freeze)||SpiderSilkBound(unit)?0f:actionSpeed;
        bool freezeTint=unit.combatStatuses.Has(CombatStatusKind.Freeze);
        bool chilled=freezeTint||unit.raptorSlowTimer>0f||
                     unit.kingKongSlowTimer>0f||unit.mammothSlowTimer>0f;
        bool shadowClone=unit.augmentShadowClone&&unit.spiritConcertOwner==null&&!unit.silkPuppet&&unit.mantisBroodOwner==null&&!unit.rank3MycokingSummon;
        bool ironInstinct=unit.bearResolveTimer>0f&&MonsterTraitRuntime.Has(
            unit.activeTraitIds,BearCombatRules.IronKumaTraitId);
        bool fortressCarapace=unit.familyDamageReductionTimer>0f&&
            MonsterTraitRuntime.Has(
                unit.activeTraitIds,BeetleCombatRules.AtlagonTraitId);
        bool toughScales=unit.crocodileToughHideTimer>0f;
        unit.reaction?.SetStatusTint(
            freezeTint?new Color(0.62f,0.9f,1f):
            chilled?new Color(0.25f,0.68f,1f):
            shadowClone?new Color(0.42f,0.16f,0.72f):
            ironInstinct?new Color(0.76f,0.88f,1f):
            fortressCarapace?new Color(0.54f,0.78f,0.94f):
            new Color(0.42f,0.58f,0.38f),
            freezeTint?0.3f:chilled?0.22f:shadowClone?0.72f:
            ironInstinct?0.62f:
            fortressCarapace?0.4f:toughScales?0.16f:0f);
        unit.cooldown=Mathf.Max(0f,unit.cooldown-actionDt);
        unit.attackMovementLockTimer=Mathf.Max(
            0f,unit.attackMovementLockTimer-actionDt);
        if(unit.monkeyNimbus==null)unit.skillTimer=Mathf.Max(0f,unit.skillTimer-actionDt);
        unit.augmentClimaxTimer=Mathf.Max(0f,unit.augmentClimaxTimer-dt);
        unit.raptorApexPredatorTimer=Mathf.Max(
            0f,unit.raptorApexPredatorTimer-dt);
        unit.raptorApexCooldownFlash=unit.raptorApexPredatorTimer>0f
            ?Mathf.Max(0f,unit.raptorApexCooldownFlash-dt):0f;
        if(unit.raptorApexWings!=null)
        {
            unit.raptorApexWings.SetAwakened(RaptorApexPredatorActive(unit));
            unit.raptorApexWings.Tick(dt);
        }
        unit.augmentProtagonistHitGainCooldown=Mathf.Max(
            0f,unit.augmentProtagonistHitGainCooldown-dt);
        if(unit.augmentReturnTimer>0f)
        {
            unit.augmentReturnTimer=Mathf.Max(0f,unit.augmentReturnTimer-dt);
            unit.velocity=Vector3.zero;
            SetMoving(unit,false);
            if(unit.augmentReturnTimer<=0f)
            {
                ExpeditionAugmentCombatModifiers returning=
                    ExpeditionAugmentRuntime.CombatModifiers(
                        expeditionRun,unit.stableId,expeditionRun.wave);
                unit.hp=unit.maxHp*Mathf.Clamp01(returning.returnHealthRatio);
                unit.skillTimer=ExpeditionAugmentRuntime.ChargeSkillCooldown(
                    unit.skillTimer,unit.skillCooldownDuration,
                    returning.returnSkillChargeRatio);
                unit.augmentReturnInvulnerabilityTimer=Mathf.Max(
                    0f,returning.returnInvulnerableSeconds);
                unit.currentAction="idle";
                unit.reaction?.FinishReturnMark();
                if(unit.ring!=null)unit.ring.SetActive(true);
                AddCombatFloatText(
                    unit,"회귀",new Color(0.42f,0.82f,1f),true);
                CreateSkillPulse(unit,new Color(0.42f,0.82f,1f),0.95f);
            }
            return;
        }
        unit.augmentReturnInvulnerabilityTimer=Mathf.Max(
            0f,unit.augmentReturnInvulnerabilityTimer-dt);
        if(unit.skillEchoTimer>0f)
        {
            unit.skillEchoTimer=Mathf.Max(0f,unit.skillEchoTimer-actionDt);
            if(unit.skillEchoTimer<=0f)ExecuteSkillEcho(unit);
        }
        unit.guardTimer=Mathf.Max(0f,unit.guardTimer-dt);
        unit.crocodileBiteLockTimer=Mathf.Max(0f,unit.crocodileBiteLockTimer-dt);
        unit.crocodileImmobilizedTimer=Mathf.Max(0f,unit.crocodileImmobilizedTimer-dt);
        unit.crocodileToughHideTimer=Mathf.Max(0f,unit.crocodileToughHideTimer-dt);
        unit.crocodileShieldTimer=Mathf.Max(0f,unit.crocodileShieldTimer-dt);
        if(unit.crocodileShieldTimer<=0f)unit.crocodileShield=0f;
        unit.crocodileDeathMarkTimer=Mathf.Max(
            0f,unit.crocodileDeathMarkTimer-dt);
        if(unit.crocodileDeathMarkTimer<=0f)unit.crocodileDeathMarkSource=null;
        unit.fangLockTimer=Mathf.Max(0f,unit.fangLockTimer-dt);
        TickBeetleSweep(unit,dt);
        float previousBearResolve=unit.bearResolveTimer;
        if(!IsBearAvatarCinematicPending(unit))unit.bearResolveTimer=Mathf.Max(0f,unit.bearResolveTimer-dt);
        unit.wolfChaseTimer=Mathf.Max(0f,unit.wolfChaseTimer-dt);
        if(unit.wolfChaseTimer<=0f||!IsCombatActive(unit.wolfChaseTarget))
        {
            unit.wolfChaseTarget=null;
            unit.wolfChaseEnhanced=false;
        }
        unit.wolfEclipseTimer=Mathf.Max(0f,unit.wolfEclipseTimer-dt);
        if(wolfEclipseWasActive&&unit.wolfEclipseTimer<=0f)
            FinishWolfEclipsePack(unit);
        unit.griffinStormTimer=Mathf.Max(0f,unit.griffinStormTimer-dt);
        if(unit.griffinStormTimer<=0f)unit.griffinStormStacks=0;
