        unit.personalityMoveTimer=Mathf.Max(0f,unit.personalityMoveTimer-dt);
        unit.personalityCueCooldown=Mathf.Max(0f,unit.personalityCueCooldown-dt);
        unit.personalityRetreatTimer=Mathf.Max(0f,unit.personalityRetreatTimer-dt);
        unit.personalityRetreatCooldown=Mathf.Max(0f,unit.personalityRetreatCooldown-dt);
