        UpdateItemPeriodicEffects(unit,dt,false);
        UpdateCorruptionGreatSuccessEffects(unit,dt);
        UpdateJaguarStates(unit,dt,false);
        if(!IsCombatActive(unit))return;
        if(MammothRicochetControlsMovement(unit)){MaintainMammothRicochetUnit(unit);return;}
