        {unit.velocity=Vector3.zero;SetMoving(unit,false);return;}
        if(unit.wizardCygnusShower!=null)
        {unit.velocity=Vector3.zero;SetMoving(unit,false);return;}
        if(unit.crocodileAbyssDive!=null)
        {AdvanceCrocodileAbyssDive(unit,actionDt);unit.velocity=Vector3.zero;SetMoving(unit,false);return;}
        if(unit.crocodileAbyssHeldBy!=null&&UpdateCrocodileAbyssVictim(unit))return;
