            if(unit.mammothToss!=null&&!MammothTossValid(unit,unit.mammothToss))EndMammothToss(unit,unit.mammothToss);
            unit.velocity=Vector3.zero;SetMoving(unit,false);return;
        }
        if(unit.mammothCharge!=null)
        {
            if(!MammothChargeValid(unit,unit.mammothCharge))unit.spriteAnimation?.InterruptCurrentAction(true);
