            {unit.velocity=Vector3.zero;SetMoving(unit,false);unit.currentAction="primordial_maw_pulled";return;}
            unit.tyrannoMawPulledBy=null;
        }
        if(unit.mantisReaperAction!=null)
        {
            TickMantisReaper(unit,frozen?0f:dt);
