        {
            if(!MantisGuillotineValid(unit,unit.mantisGuillotine))
            {EndMantisGuillotine(unit,unit.mantisGuillotine);unit.spriteAnimation?.InterruptCurrentAction(true);}
            else {unit.velocity=Vector3.zero;return;}
