            ReconcileHiddenHexPosition(unit);
        if(IsCombatActive(unit.forcedTarget)&&unit.forcedTargetTimer>0f)SetTarget(unit,unit.forcedTarget);
        else if(unit.forcedTarget!=null){unit.forcedTarget=null;unit.forcedTargetTimer=0f;}
        ApplyPreyFocus(unit);
        if(unit.recentAttacker!=null&&(!IsCombatActive(unit.recentAttacker)||unit.threatTimer<=0f))unit.recentAttacker=null;
        if(!CanKeepCombatTarget(unit,unit.target))
        {
            Unit selected=SelectTarget(unit,true);
            if(selected==null)selected=SelectTarget(unit);
            SetTarget(unit,selected);
        }
        CombatStatusEffect airborne=unit.combatStatuses.Get(CombatStatusKind.Airborne);
        if(airborne!=null)
        {
            unit.currentAction="airborne";
            unit.velocity=Vector3.zero;SetMoving(unit,false);
            float duration=Mathf.Max(0.01f,airborne.magnitude);
            float progress=1f-Mathf.Clamp01(airborne.remaining/duration);
            Vector3 position=unit.model.transform.position;
            position.y=unit.visualHeightOffset+(IsKingKongFamily(airborne.source as Unit)
                ?KingKongCombatRules.PulseLiftHeight(progress):Mathf.Sin(progress*Mathf.PI)*0.45f);
            unit.model.transform.position=position;
            return;
        }
        if(unit.currentAction=="airborne")
        {
            Vector3 position=unit.model.transform.position;
            position.y=unit.visualHeightOffset;
            unit.model.transform.position=position;
        }
        if(unit.wolfStampede!=null)
        {
            unit.velocity=Vector3.zero;
            unit.moving=false;
            SetMoving(unit,false);
            return;
        }
        if(unit.target==null)
        {
            if(HaetaeSupportTargets(unit,GameMasterData.Skill(unit.skillId))>0&&TryUseSkill(unit))return;
            unit.currentAction="idle";
            StopForBasicAttack(unit);
            return;
        }
        if(unit.target.crocodilePreyFlying)
        {
            StopBeforeAttack(unit);
            RotateUnit(unit,unit.target.model.transform.position-unit.model.transform.position,dt);
            if(unit.cooldown<=0f&&!IsAttackMovementLocked(unit))Attack(unit,unit.target);
            return;
        }
        if(TryUseSkill(unit))return;
        if(IsAttackMovementLocked(unit))
        {
            unit.meleeSlotReady=unit.reservedAttackSlot>=0;
            unit.currentAction="attack_movement_lock";
            unit.velocity=Vector3.zero;
            unit.moving=false;
            SetMoving(unit,false);
            RotateUnit(unit,
                unit.target.model.transform.position-unit.model.transform.position,dt);
            return;
        }
        UpdatePersonalityReaction(unit);
        bool personalityRetreating=ShouldRetreatForPersonality(unit,unit.target);
        bool personalityPositioning=IsPersonalityPositioning(unit);
        if(UsesHiddenHexCombat)
        {
            UpdateHiddenHexCombat(unit,dt);
            return;
        }
        Unit immediateTarget=FindImmediateAttackTarget(unit);
        bool repositionFromImmediate=immediateTarget!=null&&
            (ShouldRepositionRanged(unit,immediateTarget)||
             personalityRetreating||personalityPositioning);
        if(immediateTarget!=null&&!repositionFromImmediate)
        {
            ClearRoute(unit);
            ReleaseAttackSlot(unit);
            unit.blockedRepathAttempts=0;
            unit.stuckTimer=0f;
            unit.detourTimer=0f;unit.detourTarget=null;
            unit.currentAction=unit.cooldown<=0f?"attack":"recover";
            StopForBasicAttack(unit);
            Vector3 immediateDirection=Flat(immediateTarget.model.transform.position-unit.model.transform.position);
            RotateUnit(unit,immediateDirection,dt);
            if(unit.cooldown<=0f)Attack(unit,immediateTarget);
            return;
        }
        if(unit.griffinRootTimer>0f||unit.combatStatuses.Has(CombatStatusKind.Root))
        {
            unit.currentAction="immobilized";
            unit.velocity=Vector3.zero;SetMoving(unit,false);
            return;
        }
        bool isRanged=IsRangedUnit(unit);
        bool usesMeleeApproach=!isRanged&&!personalityRetreating&&!personalityPositioning;
        unit.meleeSlotReady=false;
        ReleaseAttackSlot(unit);
        Vector3 toTarget=Flat(unit.target.model.transform.position-unit.model.transform.position);
        float distance=toTarget.magnitude;
        float attackDistance=CombatApproachDistance(unit,unit.target);
        Vector3 attackPosition=usesMeleeApproach?ClosestMeleeAttackPosition(unit,unit.target):Flat(unit.target.model.transform.position);
        if(personalityPositioning)attackPosition=unit.personalityMovePosition;
        Vector3 toAttackPosition=attackPosition-Flat(unit.model.transform.position);
        bool routeBlocked=usesMeleeApproach?(!MeleeSlotSegmentClear(unit,unit.target,Flat(unit.model.transform.position),attackPosition)||
            distance<=MeleeArrivalDistance(unit,unit.target)&&!HasClearAttackLine(unit,unit.target)):
            !HasClearPath(unit,attackPosition)||HasUnitBlockingPath(unit,attackPosition);
        if(routeBlocked)unit.blockedTimer+=dt;else unit.blockedTimer=0f;
        if(unit.decisionTimer<=0f)
        {
            PersonalityCombatPolicy decisionPolicy=
                unit.personalityPolicy??PersonalityCombatPolicy.Balanced();
            unit.decisionTimer=Mathf.Min(DecisionInterval,decisionPolicy.reconsiderInterval);
            ReconsiderBlockedTarget(unit,routeBlocked);
            if(unit.target==null)return;
            toTarget=Flat(unit.target.model.transform.position-unit.model.transform.position);
            distance=toTarget.magnitude;
            attackDistance=CombatApproachDistance(unit,unit.target);
            isRanged=IsRangedUnit(unit);
            usesMeleeApproach=!isRanged&&!personalityRetreating&&!personalityPositioning;
            attackPosition=usesMeleeApproach?ClosestMeleeAttackPosition(unit,unit.target):Flat(unit.target.model.transform.position);
            if(personalityPositioning)attackPosition=unit.personalityMovePosition;
            toAttackPosition=attackPosition-Flat(unit.model.transform.position);
            routeBlocked=usesMeleeApproach?(!MeleeSlotSegmentClear(unit,unit.target,Flat(unit.model.transform.position),attackPosition)||
                distance<=MeleeArrivalDistance(unit,unit.target)&&!HasClearAttackLine(unit,unit.target)):
                !HasClearPath(unit,attackPosition)||HasUnitBlockingPath(unit,attackPosition);
            personalityRetreating=ShouldRetreatForPersonality(unit,unit.target);
        }
        bool repositionForRange=ShouldRepositionRanged(unit,unit.target,distance,attackDistance);
        bool repositionForPersonality=personalityRetreating||personalityPositioning;
        bool settledForAttack=isRanged||usesMeleeApproach&&CanKeepMeleeAttackPosition(unit,unit.target)||personalityPositioning;
        bool canCounterWhileRetreating=personalityRetreating&&
            CanKiteAtRange(unit.attackRange)&&unit.cooldown<=0f;
        if(settledForAttack&&distance<=attackDistance&&
           HasClearAttackLine(unit,unit.target)&&
           !repositionForRange&&
           (!repositionForPersonality||canCounterWhileRetreating))
        {
            ClearRoute(unit);unit.detourTimer=0f;unit.detourTarget=null;
            unit.currentAction=unit.cooldown<=0f?(isRanged?"ranged_attack":"attack"):"recover";
            if(usesMeleeApproach)BeginMeleeArrivalInertia(unit);else StopForBasicAttack(unit);
            RotateUnit(unit,toTarget,dt);
            if(unit.cooldown<=0f)Attack(unit,unit.target);
            return;
        }

        if(unit.inertiaVelocity.sqrMagnitude>.000001f)
        {
            unit.currentAction="inertia_coast";
            SetMoving(unit,false);
            return;
        }
        if(YieldVoluntaryMovementToHitSlide(unit,dt))return;
        float moveSpeed=CurrentMovementSpeed(unit);
        Vector3 navigationDirection=GetNavigationDirection(unit,usesMeleeApproach||personalityPositioning?toAttackPosition:toTarget,routeBlocked);
        if(!repositionForPersonality&&
           ShouldWaitForOpenPath(routeBlocked,unit.routeIndex,unit.route.Count))
        {
            unit.currentAction="path_wait";
            unit.stuckTimer=0f;
            StopForBasicAttack(unit);
            return;
        }
        bool followingDetour=ShouldKeepNavigationRoute(
            unit.detourTarget==unit.target,unit.routeIndex,unit.route.Count);
        Vector3 desired=CalculateTacticalMovement(unit,navigationDirection,distance,moveSpeed);
        if(unit.detourTimer>0f&&unit.detourTarget==unit.target)unit.currentAction="attack_detour";
        // A collision-cleared route must not be steered back into the crowd it is bypassing.
        if(!followingDetour)
        {
            desired+=CalculateSeparation(unit,moveSpeed);
            desired+=CalculateObstacleAvoidance(unit,moveSpeed);
        }
        if(desired.magnitude>moveSpeed*1.18f)desired=desired.normalized*moveSpeed*1.18f;
        if(!MovementMakesForwardProgress(
               unit.attackRange,desired,toTarget,
               followingDetour||repositionForPersonality||usesMeleeApproach))
        {
            unit.currentAction="path_wait";
            StopForBasicAttack(unit);
            return;
        }
        if(FrogHopMovementRules.IsFrogFamily(unit.definition.familyId))
        {
            UpdateFrogHopReady(unit,desired,moveSpeed,dt);
            return;
        }
        float arrivalDistance=followingDetour?navigationDirection.magnitude:float.PositiveInfinity;
        if(!routeBlocked&&personalityPositioning&&!personalityRetreating&&!repositionForRange)
        {
            if(TryBeginArrivalGlide(unit,attackPosition,dt))return;
            arrivalDistance=toAttackPosition.magnitude;
        }
        unit.velocity=CombatMovementInertia.Advance(
            unit.velocity,desired,moveSpeed*1.18f,dt,arrivalDistance);
        Vector3 previousGround=Flat(unit.model.transform.position);
        Vector3 ground=ResolveUnitMovement(unit,previousGround,previousGround+unit.velocity*dt);
        // Crowd separation must not turn an ordinary walking step into a positional burst.
        ground=Vector3.MoveTowards(previousGround,ground,unit.velocity.magnitude*dt);
        if(IntroducesBodyOverlap(unit,previousGround,ground,true))ground=previousGround;
        ground=BlockRank3IceWallMovement(unit,previousGround,ground);
        Vector3 resolvedStep=ground-previousGround;
        unit.velocity=CombatMovementInertia.AfterCollision(unit.velocity,resolvedStep,dt);
        float moved=Vector3.Distance(ground,unit.lastGroundPosition);
        bool madeProgress=HasMovementProgress(moved,dt);
        ConsumeRangedRetreatDistance(unit,moved);
        if(desired.sqrMagnitude>0.25f&&!madeProgress)unit.stuckTimer+=dt;
        else
        {
            unit.stuckTimer=Mathf.Max(0f,unit.stuckTimer-dt*2f);
            if(madeProgress)unit.blockedRepathAttempts=0;
        }
        unit.lastGroundPosition=ground;
        unit.model.transform.position=ground+Vector3.up*unit.visualHeightOffset;
        unit.ring.transform.position=ground+Vector3.up*0.025f;
        unit.currentTile=NearestGridCoordinate(ground);
        unit.moving=madeProgress&&unit.velocity.sqrMagnitude>0.0025f;
        SetMoving(unit,unit.moving);
        if(unit.moving)UpdateFootstepDust(unit,resolvedStep);
        RotateUnit(unit,unit.velocity,dt);
        if(unit.stuckTimer>=StuckDecisionDelay)
        {
            unit.stuckTimer=0f;unit.blockedTimer=1f;unit.repathTimer=0f;
            BuildPursuitRoute(unit,unit.target);
        }
    }

    private void UpdateHiddenHexCombat(Unit unit,float dt)
    {
        if(unit.hexStepping)
        {
            UpdateHiddenHexStep(unit,dt);
            return;
        }
        if(IsImmediatelyAttackable(unit,unit.target))
        {
            unit.currentAction=unit.cooldown<=0f
                ?(IsRangedUnit(unit)?"ranged_attack":"attack")
                :"recover";
            StopBeforeAttack(unit);
            RotateUnit(unit,
                unit.target.model.transform.position-unit.model.transform.position,dt);
            if(unit.cooldown<=0f)Attack(unit,unit.target);
            return;
        }
        if(unit.griffinRootTimer>0f||unit.combatStatuses.Has(CombatStatusKind.Root))
        {
            unit.currentAction="immobilized";
            unit.velocity=Vector3.zero;
            SetMoving(unit,false);
            return;
        }
        if(TryUseSkill(unit))return;
        if(unit.repathTimer>0f)
        {
            unit.currentAction="hex_path_wait";
            unit.velocity=Vector3.zero;
            SetMoving(unit,false);
            return;
        }
        if(!TryFindNextCombatHex(unit,unit.target,out Vector2Int next))
        {
            unit.currentAction="hex_path_wait";
            unit.repathTimer=0.12f;
            unit.velocity=Vector3.zero;
            SetMoving(unit,false);
            return;
        }
        unit.hexStepTarget=next;
        unit.hexStepping=true;
        UpdateHiddenHexStep(unit,dt);
    }

    private void UpdateHiddenHexStep(Unit unit,float dt)
    {
        if(YieldVoluntaryMovementToHitSlide(unit,dt))return;
        if(!tiles.TryGetValue(unit.hexStepTarget,out Tile destinationTile)||
           !destinationTile.walkable||destinationTile.bench||
           IsCombatHexReserved(unit,unit.hexStepTarget))
        {
            unit.hexStepping=false;
            unit.repathTimer=0.06f;
            unit.velocity=Vector3.zero;
            SetMoving(unit,false);
            return;
        }
        Vector3 previous=Flat(unit.model.transform.position);
        Vector3 destination=Flat(destinationTile.world);
        Vector3 ground=Vector3.MoveTowards(
            previous,destination,CurrentMovementSpeed(unit)*dt);
        unit.velocity=dt>0f?(ground-previous)/dt:Vector3.zero;
        unit.lastGroundPosition=ground;
        unit.model.transform.position=ground+Vector3.up*unit.visualHeightOffset;
        unit.ring.transform.position=ground+Vector3.up*0.025f;
        unit.currentAction="hex_step";
        unit.moving=true;
        SetMoving(unit,true);
        UpdateFootstepDust(unit,ground-previous);
        RotateUnit(unit,destination-previous,dt);
        if((destination-ground).sqrMagnitude>0.0001f)return;
        unit.currentTile=unit.hexStepTarget;
        unit.hexStepping=false;
        unit.velocity=Vector3.zero;
        unit.lastGroundPosition=destination;
        unit.model.transform.position=destination+Vector3.up*unit.visualHeightOffset;
        unit.ring.transform.position=destination+Vector3.up*0.025f;
        unit.moving=true;
    }

    private bool TryFindNextCombatHex(Unit source,Unit target,out Vector2Int next)
    {
        next=source.currentTile;
        if(!IsCombatTargetable(target))return false;
        Vector2Int goal=target.hexStepping?target.hexStepTarget:target.currentTile;
        return TryFindShortestAttackHexStep(
            source.currentTile,goal,HiddenHexAttackRange(source),
            candidate=>tiles.TryGetValue(candidate,out Tile tile)&&
                       tile.walkable&&!tile.bench&&
                       !IsCombatHexReserved(source,candidate),out next);
    }

    public static bool TryFindShortestAttackHexStep(
        Vector2Int start,Vector2Int goal,int attackRange,
        Func<Vector2Int,bool> canTraverse,out Vector2Int next)
    {
        if(canTraverse==null)throw new ArgumentNullException(nameof(canTraverse));
        next=start;
        if(CanAttackAtHexRange(start,goal,attackRange))return false;
        Queue<Vector2Int> open=new Queue<Vector2Int>();
        Dictionary<Vector2Int,Vector2Int> cameFrom=
            new Dictionary<Vector2Int,Vector2Int>();
        Dictionary<Vector2Int,int> steps=new Dictionary<Vector2Int,int>{{start,0}};
        Dictionary<Vector2Int,float> deviations=
            new Dictionary<Vector2Int,float>{{start,0f}};
        open.Enqueue(start);
        Vector2Int closest=start;
        int closestDistance=HexDistance(start,goal);
        int closestSteps=0;
        float closestDeviation=0f;
        Vector2Int attackTile=start;
        int attackSteps=int.MaxValue;
        float attackDeviation=float.MaxValue;
        const float epsilon=0.0001f;
        while(open.Count>0)
        {
            Vector2Int current=open.Dequeue();
            int currentSteps=steps[current];
            float currentDeviation=deviations[current];
            if(currentSteps>=attackSteps)continue;
            for(int index=0;index<6;index++)
            {
                Vector2Int candidate=HexNeighbor(current,index);
                if(!canTraverse(candidate))continue;
                int candidateSteps=currentSteps+1;
                float candidateDeviation=currentDeviation+
                    HexStepDeviation(current,candidate,goal);
                if(steps.TryGetValue(candidate,out int knownSteps)&&
                   (knownSteps<candidateSteps||
                    knownSteps==candidateSteps&&
                    deviations[candidate]<=candidateDeviation+epsilon))continue;
                steps[candidate]=candidateSteps;
                deviations[candidate]=candidateDeviation;
                cameFrom[candidate]=current;
                int candidateDistance=HexDistance(candidate,goal);
                if(candidateDistance<closestDistance||
                   candidateDistance==closestDistance&&
                   (candidateSteps<closestSteps||
                    candidateSteps==closestSteps&&
                    candidateDeviation<closestDeviation-epsilon))
                {
                    closest=candidate;
                    closestDistance=candidateDistance;
                    closestSteps=candidateSteps;
                    closestDeviation=candidateDeviation;
                }
                if(CanAttackAtHexRange(candidate,goal,attackRange))
                {
                    if(candidateSteps<attackSteps||
                       candidateSteps==attackSteps&&
                       candidateDeviation<attackDeviation-epsilon)
                    {
                        attackTile=candidate;
                        attackSteps=candidateSteps;
                        attackDeviation=candidateDeviation;
                    }
                    continue;
                }
                if(candidateSteps<attackSteps)open.Enqueue(candidate);
            }
        }
        Vector2Int reached=attackSteps<int.MaxValue?attackTile:closest;
        if(reached==start)return false;
        while(cameFrom.TryGetValue(reached,out Vector2Int parent)&&parent!=start)
            reached=parent;
        next=reached;
        return next!=start;
    }

    private static float HexStepDeviation(
        Vector2Int from,Vector2Int to,Vector2Int goal)
    {
        Vector2 origin=HexPlanarPosition(from);
        Vector2 destination=HexPlanarPosition(to);
        Vector2 target=HexPlanarPosition(goal);
        Vector2 remaining=target-origin;
        if(remaining.sqrMagnitude<=0.0001f)return 0f;
        return 1f-Vector2.Dot(
            (destination-origin).normalized,remaining.normalized);
    }

    private static Vector2 HexPlanarPosition(Vector2Int coordinate)
    {
        return new Vector2(
            coordinate.x+((coordinate.y&1)==0?0f:0.5f),
            coordinate.y*HexRowSpacing);
    }

    private bool IsCombatHexReserved(Unit source,Vector2Int coordinate)
    {
        for(int i=0;i<units.Count;i++)
        {
            Unit other=units[i];
            if(other==source||!IsCombatActive(other))continue;
            if(other.currentTile==coordinate||
               other.hexStepping&&other.hexStepTarget==coordinate)return true;
        }
        return false;
    }

    private bool IsCombatHexOccupiedByOther(Unit source,Vector2Int coordinate)
    {
        for(int i=0;i<units.Count;i++)
        {
            Unit other=units[i];
            if(other!=source&&IsCombatActive(other)&&other.currentTile==coordinate)
                return true;
        }
        return false;
    }

    private void ReconcileHiddenHexPosition(Unit unit)
    {
        Vector3 position=Flat(unit.model.transform.position);
        bool occupied=IsCombatHexOccupiedByOther(unit,unit.currentTile);
        if(!occupied&&tiles.TryGetValue(unit.currentTile,out Tile current)&&
           (Flat(current.world)-position).sqrMagnitude<=
           ActiveTileSize*ActiveTileSize*0.16f)return;
        Tile destination=tiles.Values
            .Where(tile=>tile.walkable&&!tile.bench&&
                !IsCombatHexReserved(unit,tile.coordinate))
            .OrderBy(tile=>(Flat(tile.world)-position).sqrMagnitude)
            .ThenBy(tile=>HexDistance(unit.initialTile,tile.coordinate))
            .FirstOrDefault();
        if(destination==null)return;
        Vector3 ground=Flat(destination.world);
        unit.currentTile=destination.coordinate;
        unit.hexStepTarget=unit.currentTile;
        unit.model.transform.position=ground+Vector3.up*unit.visualHeightOffset;
        unit.ring.transform.position=ground+Vector3.up*0.025f;
        unit.lastGroundPosition=ground;
        unit.velocity=Vector3.zero;
    }

    private static Vector2Int HexNeighbor(Vector2Int coordinate,int index)
    {
        bool odd=(coordinate.y&1)!=0;
        switch(index)
        {
            case 0:return coordinate+Vector2Int.left;
            case 1:return coordinate+Vector2Int.right;
            case 2:return coordinate+new Vector2Int(odd?0:-1,-1);
            case 3:return coordinate+new Vector2Int(odd?1:0,-1);
            case 4:return coordinate+new Vector2Int(odd?0:-1,1);
            default:return coordinate+new Vector2Int(odd?1:0,1);
        }
    }

    public static bool CanAttackAtHexRange(
        Vector2Int source,Vector2Int target,int attackRange)
    {
        return HexDistance(source,target)<=Mathf.Max(1,attackRange);
    }

    public static int BasicAttackHexRange(int authoredAttackRange)
    {
        return authoredAttackRange<=1?1:authoredAttackRange==2?2:3;
    }

    private static int HiddenHexAttackRange(Unit unit)
    {
        int range=BasicAttackHexRange(unit.attackRange);
        if(MountainColossusActive(unit))
            range=Mathf.Max(range,Mathf.CeilToInt(BearCombatRules.MountainAttackRangeTiles));
        if(unit.rank3MantisReaper)range=Mathf.Max(range,2);
        return range;
    }

    private float CurrentMovementSpeed(Unit unit)
    {
        float frogSlowMultiplier=unit.frogSlowTimer>0f?1f-unit.frogSlowRatio:1f;
        float kingKongSlowMultiplier=unit.kingKongSlowTimer>0f
            ?1f-KingKongCombatRules.GlacialSlowRatio:1f;
        float pollenMoveMultiplier=unit.combatStatuses.Has(
            CombatStatusKind.HallucinatoryPollen)
            ?1f-MantisCombatRules.PollenMoveSpeedSlow:1f;
        float mammothMoveMultiplier=
            (unit.mammothSlowTimer>0f?1f-unit.mammothSlowRatio:1f)*
            (unit.mammothHasteTimer>0f?1f+unit.mammothHasteRatio:1f);
        return unit.speedTilesPerSecond*TileSize*
            (unit.packHuntSpeedTimer>0f?1.35f:1f)*
            (unit.wolfChaseTimer>0f
                ?1f+WolfCombatRules.ChaseMoveSpeedBonusFor(unit.wolfChaseEnhanced):1f)*
            frogSlowMultiplier*kingKongSlowMultiplier*
            pollenMoveMultiplier*mammothMoveMultiplier*
            (unit.familyMoveSpeedTimer>0f?1f+unit.familyMoveSpeedBonus:1f)*
            (unit.rank3MoveSpeedBonusTimer>0f
                ?1f+unit.rank3MoveSpeedBonusRatio:1f)*
            Mathf.Max(.01f,1f+CurrentFrogStolenBuff(unit,FrogStolenBuffKind.MoveSpeed))*
            SpiderMovementMultiplier(unit)*
            (HaetaeOppressionAffects(unit,false)?1f-HaetaeRank3Rules.OppressionSlow:1f);
    }

    public static bool HasMovementProgress(float distance,float deltaTime)
    {
        return distance>Mathf.Max(0.0001f,deltaTime*0.05f);
    }

    private void UpdateFrogHopReady(Unit unit,Vector3 desired,float moveSpeed,float dt)
    {
        unit.velocity=Vector3.Lerp(unit.velocity,Vector3.zero,1f-Mathf.Exp(-18f*dt));
        unit.moving=false;
        SetMoving(unit,false);
        if(unit.frogRestTimer>0f||desired.sqrMagnitude<0.01f)return;

        Vector3 start=Flat(unit.model.transform.position);
        Vector3 direction=Flat(desired).normalized;
        float speedTiles=moveSpeed/TileSize;
        float distance=FrogHopMovementRules.HopDistanceTiles(speedTiles)*TileSize;
        Vector3 landing=ResolveUnitMovement(unit,start,start+direction*distance);
        if(Vector3.Distance(start,landing)<0.05f)
        {
            unit.stuckTimer+=dt;
            unit.frogRestTimer=0.1f;
            return;
        }

        unit.frogHopStart=start;
        unit.frogHopEnd=landing;
        unit.frogHopProgress=0f;
        unit.frogHopping=true;
        unit.velocity=direction*(distance/FrogHopMovementRules.HopDuration);
        unit.currentAction="frog_hop";
        unit.moving=true;
        SetMoving(unit,true);
        RotateUnit(unit,direction,dt);
    }

    private void UpdateFrogHop(Unit unit,float dt)
    {
        unit.frogHopProgress=Mathf.Clamp01(
            unit.frogHopProgress+dt/FrogHopMovementRules.HopDuration);
        float eased=unit.frogHopProgress*unit.frogHopProgress*
                    (3f-2f*unit.frogHopProgress);
        Vector3 intended=Vector3.Lerp(unit.frogHopStart,unit.frogHopEnd,eased);
        Vector3 previous=Flat(unit.model.transform.position);
        Vector3 ground=ResolveUnitMovement(unit,previous,intended);
        ConsumeRangedRetreatDistance(unit,Vector3.Distance(previous,ground));
        float arc=FrogHopMovementRules.ArcHeight(unit.frogHopProgress);
        unit.model.transform.position=ground+Vector3.up*(unit.visualHeightOffset+arc);
        unit.ring.transform.position=ground+Vector3.up*0.025f;
        unit.currentTile=NearestGridCoordinate(ground);
        unit.lastGroundPosition=ground;
        RotateUnit(unit,unit.frogHopEnd-unit.frogHopStart,dt);

        if(unit.frogHopProgress<1f)return;
        unit.frogHopping=false;
        unit.frogHopProgress=0f;
        unit.frogRestTimer=FrogHopMovementRules.RestDuration;
        unit.velocity=Vector3.zero;
        unit.currentAction="frog_hop_rest";
        unit.moving=false;
        SetMoving(unit,false);
        unit.model.transform.position=ground+Vector3.up*unit.visualHeightOffset;
        UpdateFootstepDust(unit,unit.frogHopEnd-unit.frogHopStart);
    }

    private void UpdateFootstepDust(Unit unit,Vector3 step)
    {
        if(meadowAmbientParticles==null||!IsCombatActive(unit)||unit.displacing||
           unit.leaping||unit.frogHopping||unit.combatStatuses.Has(CombatStatusKind.Freeze)||
           unit.combatStatuses.Has(CombatStatusKind.Knockdown)||unit.combatStatuses.Has(CombatStatusKind.Airborne))return;
        float distance=Flat(step).magnitude;
        if(distance<.002f)return;
        unit.footstepDustDistance+=distance;
        if(unit.footstepDustDistance<TileSize*.3f||Time.time<unit.nextFootstepDustAt)return;
        unit.footstepDustDistance=0f;unit.nextFootstepDustAt=Time.time+.18f;
        SpriteRenderer renderer=unit.spriteAnimation==null?unit.model.GetComponentInChildren<SpriteRenderer>():
            unit.spriteAnimation.GetComponent<SpriteRenderer>();
        meadowAmbientParticles.Footstep(Flat(unit.model.transform.position),step,unit.collisionRadius,renderer);
    }

    private Unit FindImmediateAttackTarget(Unit unit)
    {
        if(IsCombatTargetable(unit.target)&&Vector3.Distance(
               Flat(unit.model.transform.position),Flat(unit.target.model.transform.position))>
               CombatApproachDistance(unit,unit.target))return null;
        return IsRangedUnit(unit)&&IsImmediatelyAttackable(unit,unit.target)
            ?unit.target:null;
    }

    private bool IsImmediatelyAttackable(Unit unit,Unit candidate)
    {
        if(!IsCombatTargetable(candidate)||candidate.team==unit.team)return false;
        if(UsesHiddenHexCombat)
            return !unit.hexStepping&&CanAttackAtHexRange(
                unit.currentTile,candidate.currentTile,HiddenHexAttackRange(unit));
        float distance=Vector3.Distance(Flat(unit.model.transform.position),Flat(candidate.model.transform.position));
        return distance<=AttackDistance(unit,candidate)&&HasClearAttackLine(unit,candidate);
    }

    private void SetTarget(Unit unit,Unit target)
    {
        if(HasPreyFocus(unit)&&!HasActiveTaunt(unit)&&!PreyActionInProgress(unit))
            target=unit.preyFocusTarget;
        if(target!=null&&target.crocodilePreyFlying&&
           (unit.target!=target||!CanKeepCombatTarget(unit,target)))
            target=SelectTarget(unit);
        if(unit.target==target)return;
        ReleaseAttackSlot(unit);
        unit.target=target;unit.targetChanges++;
        unit.personalityMoveTimer=0f;
        unit.targetLockTimer=target==null?0f:
            StableTargetLockDuration(
                (unit.personalityPolicy??PersonalityCombatPolicy.Balanced())
                .targetLockDuration);
        unit.detourTimer=0f;unit.detourTarget=null;
        unit.blockedTimer=0f;unit.stuckTimer=0f;unit.blockedRepathAttempts=0;
        unit.rangedAttacksSinceRetreat=0;
        unit.rangedRetreating=false;
        unit.rangedRetreatDistanceRemaining=0f;
        ClearRoute(unit);
    }

    private bool CanKeepCombatTarget(Unit unit,Unit target)
    {
        return IsCombatTargetable(target)&&(!target.crocodilePreyFlying||
            IsRangedUnit(unit)&&IsImmediatelyAttackable(unit,target));
    }

    private bool TryUseSkill(Unit unit,bool combinedCastTrigger=false)
    {
#if UNITY_EDITOR
        if(CombatReadabilityPreview.Active&&CombatReadabilityPreview.BasicOnly)return false;
#endif
        if(battleEnding)return false;
        if(NinjaSpacetimeActive(unit))return false;
        if(TyrannoReignActive(unit))return false;
        if(IsSabertoothCinematicPending(unit))return false;
        if(unit.sabertoothDevour!=null||unit.sabertoothDevouredBy!=null||unit.frogGrandSlam!=null||unit.frogGrandSlamHeldBy!=null||
           unit.crocodileAbyssDive!=null||unit.crocodileAbyssHeldBy!=null||unit.wizardCygnusShower!=null||unit.wolfStampede!=null||unit.beetleOverturn!=null)return false;
        if(HasSkillCastPresentation(unit))return false;
        if(MantisOffenseSuspended(unit)||unit.silkPuppet||unit.monkeyNimbus!=null||unit.mantisGuillotine!=null||unit.mantisReaperAction!=null||unit.wyvernBreath!=null||unit.haetaeRoar!=null)return false;
        if(!SkillUseDecision.SupportsBehavior(MonsterSkillExecutor<SkillExecutionContext>.Behavior(unit.skillId)))return false;
        // Check before interrupting an action: silence never cancels an existing cast.
        if(unit.combatStatuses.Has(CombatStatusKind.Silence)||
           unit.combatStatuses.Has(CombatStatusKind.Fear)||SpiderSilkBound(unit)||unit.bearAvatarRoarPending)return false;
        if(combinedCastTrigger&&unit.spriteAnimation!=null)
            unit.spriteAnimation.InterruptCurrentAction();
        if((!combinedCastTrigger&&unit.skillTimer>0f)||unit.rank3SkillLockTimer>0f||
           !IsCombatTargetable(unit.target)&&HaetaeSupportTargets(unit,GameMasterData.Skill(unit.skillId))==0||
           unit.spriteAnimation!=null&&unit.spriteAnimation.IsActionLocked)
            return false;
        Unit combinedCommander=ActiveCombinedCastCommander();
        if(!combinedCastTrigger&&unit.team==Team.Player&&combinedCommander!=null&&
           unit!=combinedCommander)
            return false;
        return UseReadySkill(unit,combinedCastTrigger);
    }

    private bool UseReadySkill(Unit unit,bool combinedCastTrigger)
    {
        if(IsCombatTargetable(unit.target))RotateUnit(
            unit,
            unit.target.model.transform.position-unit.model.transform.position,
            1f);
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_skill_cluster_targeting"))
        {
            Unit clusterTarget=SelectClusterSkillTarget(unit);
            if(clusterTarget!=null)SetTarget(unit,clusterTarget);
        }
        if(!combinedCastTrigger&&
           MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_skill_overcharge")&&
           !unit.traitOverchargePrepared)
        {
            unit.traitOverchargePrepared=true;
            unit.skillTimer=0.8f;
            unit.attackMovementLockTimer=Mathf.Max(unit.attackMovementLockTimer,0.8f);
            unit.currentAction="trait_overcharge_prepare";
            unit.velocity=Vector3.zero;
            StopBeforeAttack(unit);
            SetMoving(unit,false);
            return true;
        }
        unit.traitOverchargePrepared=false;
        bool finisherReady=unit.traitState.finisherReady;
        if(finisherReady)
        {
            Unit finisherTarget=SelectFinisherTarget(unit);
            if(finisherTarget!=null)SetTarget(unit,finisherTarget);
        }
        bool vanguardResolve=MonsterTraitRuntime.Has(unit.activeTraitIds,
            "trait_skill_vanguard_resolve")&&unit.traitState.bearResolveUses==0;
        if(unit.spiritConcertOwner==null&&!combinedCastTrigger&&!finisherReady&&!vanguardResolve&&
           !SkillUseDecision.ShouldUse(BuildSkillSnapshot(unit)))return false;
        if(TryQueueSabertoothCinematic(unit,combinedCastTrigger))return true;
        if(ShouldPresentCommonSkill(unit))return BeginCommonSkillFocus(unit,combinedCastTrigger);
        return ExecuteReadySkill(unit,combinedCastTrigger);
    }

    private bool ExecuteReadySkill(Unit unit,bool combinedCastTrigger)
    {
        SkillUseTraitResult traitUse=MonsterTraitRuntime.PreviewSkillUse(
            unit.activeTraitIds,unit.traitState);
        unit.skillTraitDamageMultiplier=traitUse.damageMultiplier;
        unit.skillTraitRadiusMultiplier=traitUse.radiusMultiplier*
                                        unit.augmentSkillAreaMultiplier;
        if(skillExecutor==null)ConfigureSkillExecutor();
        unit.lastSkillCritical=false;
        PrepareCorruptionSkillUse(unit);
        bool used=skillExecutor.TryExecute(unit.skillId,MonsterSkillTrigger.Active,
            new SkillExecutionContext{source=unit,target=unit.target});
        if(used&&!combinedCastTrigger)
        {
            Vector3 sourcePosition=Flat(unit.model.transform.position);
            Vector3 targetPosition=IsCombatActive(unit.target)
                ?Flat(unit.target.model.transform.position)
                :sourcePosition;
            combatCameraDirector?.ReportSkill(
                unit.stableId,unit.team==Team.Player,
                sourcePosition,targetPosition);
            layeredBattleEnvironment?.Pulse(
                targetPosition,.48f,targetPosition-sourcePosition);
        }
        if(used&&!IsRaptorFamily(unit))
            PlayCombatSound(unit,CombatSoundCue.Cast,unit.model.transform.position);
        if(used)PlayExecutedSkillAction(unit);
        if(unit.spiritConcertOwner!=null)return used;
        if(used)unit.traitActivations+=traitUse.activations+
            MonsterTraitRuntime.CommitSkillUse(unit.activeTraitIds,unit.traitState);
        if(used)TriggerSkillTeamTraits(unit);
        if(used)HandleAugmentSkillUse(unit,combinedCastTrigger);
        if(used&&!IsSpiderFamily(unit))TriggerFamilyTranscendenceSkill(unit);
        unit.skillTraitDamageMultiplier=1f;
        unit.skillTraitRadiusMultiplier=1f;
        if(used&&MonsterTraitRuntime.TryScheduleSkillEcho(unit.activeTraitIds,unit.traitState))
        {
            string behavior=MonsterSkillExecutor<SkillExecutionContext>.Behavior(unit.skillId);
            unit.skillEchoTimer=string.Equals(behavior,"SkyDive",StringComparison.OrdinalIgnoreCase)
                ?GriffinSkyDiveTotalDuration(
                    unit,GameMasterData.Skill(unit.skillId))+0.15f:0.35f;
            unit.skillEchoTarget=unit.target;
            unit.skillEchoId=unit.skillId;
        }
        if(used)BeginLocalSkillPresentation(unit);
        return used;
    }

    private void PlayExecutedSkillAction(Unit unit)
    {
        if(unit.beetleOverturn!=null)return;
        if(unit.mammothExpulsion!=null)return;
        if(NinjaSpacetimeActive(unit))return;
        if(TyrannoReignActive(unit))return;
        if(unit.wolfStampede!=null&&!unit.wolfHuntPending)return;
        if(unit.wizardCygnusShower!=null)return;
        if(unit.crocodileAbyssDive!=null)return;
        if(unit.frogGrandSlam!=null)return;
        if(unit.sabertoothDevour!=null)return;
        if(unit.spriteAnimation==null||unit.monkeyNimbus!=null)return;
        string behavior=
            MonsterSkillExecutor<SkillExecutionContext>.Behavior(unit.skillId);
        if(string.Equals(
               behavior,
               "AssassinLeap",
               StringComparison.OrdinalIgnoreCase)&&
           unit.leaping)
            PlayAssassinLeapAnimation(unit);
        else if(string.Equals(
                    behavior,
                    "FangLock",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.fangLockTarget!=null)
        {
            int generation=combatGeneration;
            unit.spriteAnimation.PlaySkillAttack(
                1f,
                ()=>
                {
                    if(generation!=combatGeneration||!IsCombatActive(unit))
                    {
                        FinishFangLock(unit,false);
                        return;
                    }
                    StartCombatCoroutine(unit,ResolveFangLock(unit,
                        GameMasterData.Skill(unit.skillId),generation));
                });
        }
        else if(string.Equals(
                    behavior,
                    "TongueHarpoon",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.tongueHarpoonTarget!=null)
        {
            int generation=combatGeneration;
            unit.spriteAnimation.PlaySkillAttack(
                SpriteSkillAttackPlaybackSpeed(unit),
                ()=>LaunchTongueHarpoon(unit,
                    GameMasterData.Skill(unit.skillId),generation));
        }
        else if(string.Equals(
                    behavior,
                    "DeathRoll",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.crocodileRollTarget!=null)
        {
            int generation=combatGeneration;
            float playbackSpeed=SpriteSkillAttackPlaybackSpeed(unit);
            StartCombatCoroutine(unit,PlayCrocodileDeathRollEffect(
                unit,unit.crocodileRollTarget,playbackSpeed,generation));
            unit.spriteAnimation.PlaySkillAttack(
                playbackSpeed,
                ()=>StartCombatCoroutine(unit,ResolveDeathRoll(
                    unit,GameMasterData.Skill(unit.skillId),generation)));
        }
        else if(string.Equals(
                    behavior,
                    "EarthPulse",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.kingKongPulsePending)
        {
            int generation=combatGeneration;
            int revision=unit.positionRevision;
            float playbackSpeed=SpriteSkillAttackPlaybackSpeed(unit);
            Vector3 origin=Flat(unit.model.transform.position);
            float damageMultiplier=unit.kingKongPulseDamageMultiplier;
            bool worldOverturn=MonsterTraitRuntime.Has(unit.activeTraitIds,KingKongCombatRules.WorldOverturnTraitId);
            Action<int> downstroke=strike=>
            {
                if(generation==combatGeneration&&unit.positionRevision==revision&&IsCombatActive(unit))
                    PlayKingKongSound(unit,KingKongSound.Swing,unit.model.transform.position,strike==2?1.1f:.85f);
            };
            Action<int> followup=null;
            if(!worldOverturn&&MonsterTraitRuntime.Has(unit.activeTraitIds,KingKongCombatRules.TripleEarthPulseTraitId))
            {
                followup=strike=>ResolveTripleEarthPulseHit(unit,GameMasterData.Skill(unit.skillId),
                    origin,damageMultiplier,generation,revision,strike);
                unit.traitActivations++;
            }
            Action impact=()=>
            {
                if(generation!=combatGeneration||unit.positionRevision!=revision)return;
                ResolveEarthPulseImpact(unit,GameMasterData.Skill(unit.skillId),1f,false,generation);
            };
            if(worldOverturn)
            {
                var charge=PixelCombatEffect.PlayKingKongWorldOverturnCharge(origin,
                    TileSize*KingKongCombatRules.WorldOverturnRadiusTiles*unit.kingKongPulseRadiusMultiplier,
                    unit.spriteAnimation.GetComponent<SpriteRenderer>());
                unit.spriteAnimation.PlayWorldOverturnAttack(playbackSpeed,impact,charge,downstroke);
            }
            else unit.spriteAnimation.PlayEarthPulseAttack(playbackSpeed,impact,followup,downstroke);
        }
        else if(string.Equals(
                    behavior,
                    "MagicStarBarrage",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.wizardBarragePending)
        {
            int generation=combatGeneration;
            unit.spriteAnimation.PlaySkillAttack(
                unit.spriteAnimation.SkillAttackHitTime/WizardMouseCombatRules.PreparationDuration,
                SpriteSkillAttackPlaybackSpeed(unit),
                ()=>
                {
                    unit.spriteAnimation.HoldSkillAttackHitFrame(
                        WizardMouseCombatRules.ProjectileInterval*4f+0.08f);
                    StartReleasedSkill(unit,ResolveMagicStarBarrage(unit,GameMasterData.Skill(unit.skillId),1f,false,generation));
                });
        }
        else if(string.Equals(
                    behavior,
                    "FightingSpirit",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.bearSpiritPending)
        {
            int generation=combatGeneration;
            unit.spriteAnimation.PlayBearFightingSpirit(
                SpriteSkillAttackPlaybackSpeed(unit),
                ()=>ApplyBearFightingSpirit(
                    unit,GameMasterData.Skill(unit.skillId),1f,false,generation));
        }
        else if(string.Equals(
                    behavior,
                    "ThreeSidedHunt",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.wolfHuntPending)
        {
            int generation=combatGeneration;
            Unit target=unit.wolfHuntTarget;
            Vector3 landing=unit.wolfHuntLanding;
            bool specialized=MonsterTraitRuntime.Has(unit.activeTraitIds,WolfCombatRules.CelestialSpectralPackTraitId);
            Action release=()=>
            {
                if(!unit.wolfHuntPending||!IsCombatActive(unit)||!IsCombatActive(target))return;
                if(!specialized)unit.spriteAnimation.HoldSkillAttackHitFrame(WolfCombatRules.HuntDashDuration);
                StartCombatCoroutine(unit,ResolveThreeSidedHunt(unit,target,landing,
                    GameMasterData.Skill(unit.skillId),1f,false,generation));
            };
            if(specialized)
            {
                unit.spriteAnimation.PlayWolfHuntAttack(SpriteSkillAttackPlaybackSpeed(unit),null,true);
                release();
            }
            else unit.spriteAnimation.PlayWolfHuntAttack(SpriteSkillAttackPlaybackSpeed(unit),release);
        }
        else if(string.Equals(
                    behavior,
                    "GiantCaptureWeb",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.spiderWebPending)
        {
            int generation=combatGeneration;
            unit.spriteAnimation.PlaySkillAttack(
                SpriteSkillAttackPlaybackSpeed(unit),
                ()=>LaunchSpiderCaptureWeb(
                    unit,GameMasterData.Skill(unit.skillId),
                    1f,false,generation));
            if(!mlEpisodeActive&&unit.spriteAnimation.HasPendingSkillAttackHit)
            {
                if(unit.spiderWebCharge!=null)unit.spiderWebCharge.Cancel();
                unit.spiderWebCharge=PixelSpiderCaptureNet.Charge(
                    unit.spriteAnimation.GetComponent<SpriteRenderer>(),SpiderSilkColor(unit),
                    ()=>this!=null&&generation==combatGeneration&&IsCombatActive(unit)&&
                        unit.spriteAnimation!=null&&unit.spriteAnimation.HasPendingSkillAttackHit);
            }
        }
        else if(string.Equals(
                    behavior,
                    "ShadowHunt",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.ninjaHuntPending)
        {
            int generation=combatGeneration;
            if(HasRank3(unit,NinjaCatRank3Rules.ShadowlessCross))
                BeginNinjaCross(unit,generation);
            else if(HasRank3(unit,NinjaCatRank3Rules.BlackMoonHunt))
                BeginNinjaBlackMoon(unit,generation);
            else if(HasRank3(unit,NinjaCatRank3Rules.EightGateFormation))
                BeginNinjaEightGate(unit,generation);
            else
                unit.spriteAnimation.PlayNinjaShadowAttack(
                    ()=>ShadowHuntValid(unit,generation),
                    ()=>VanishShadowHunt(unit),
                    ()=>SubstituteShadowHunt(unit,generation),
                    ()=>ArriveShadowHunt(unit),
                    ()=>ResolveShadowHunt(unit,GameMasterData.Skill(unit.skillId),1f,false,generation));
        }
        else if(string.Equals(
                    behavior,
                    "TyrantTremor",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.tyrannoTremorPending)
        {
            int generation=combatGeneration;
            SkillMasterRow skill=GameMasterData.Skill(unit.skillId);
            float radius=TileSize*skill.radiusTiles*
                         unit.tyrannoTremorRadiusMultiplier;
            bool extinction=HasRank3(unit,TyrannoRank3Rules.MassExtinction);
            if(extinction)radius=TileSize*TyrannoRank3Rules.ExtinctionRadiusTiles*unit.tyrannoTremorRadiusMultiplier;
            SpriteRenderer renderer=
                unit.spriteAnimation.GetComponent<SpriteRenderer>();
            float castSeconds=TyrannoWindupSeconds(unit);
            if(HasRank3(unit,TyrannoRank3Rules.TyrantMarch))StartTyrannoMarch(unit,generation);
            else if(HasRank3(unit,TyrannoRank3Rules.PrimordialMaw))StartTyrannoMaw(unit,generation);
            else if(extinction||castSeconds==TyrannoCombatRules.TremorCastSeconds)
            {
                var stomp=PixelTyrannoStomp.Charge(Flat(unit.model.transform.position),radius,renderer,
                    ()=>generation==combatGeneration&&IsCombatActive(unit)&&
                        unit.spriteAnimation!=null&&unit.spriteAnimation.HasPendingSkillAttackHit,extinction);
                unit.tyrannoStomp=stomp;
                unit.spriteAnimation.PlayTyrannoStomp(()=>{
                    if(generation!=combatGeneration||!IsCombatActive(unit)){stomp?.Cancel();return;}
                    stomp?.Impact(radius);
                    meadowAmbientParticles?.Impact(Flat(unit.model.transform.position),radius,renderer);
                    combatCameraDirector?.ReportGroundSlam(extinction);
                    ResolveTyrantTremor(unit,skill,1f,false,generation);
                    unit.tyrannoStomp=null;
                },extinction);
            }
            else
            {
                PixelGroundCastTelegraph telegraph=
                    PixelCombatEffect.PlayTyrannoTremorTelegraph(
                        Flat(unit.model.transform.position),radius,
                        castSeconds,
                        skillRadiusMarkerMaterial,renderer);
                PixelCombatEffect.PlayTyrannoTremorCharge(
                    unit.model.transform,renderer,castSeconds);
                unit.spriteAnimation.PlaySkillAttackWithHold(
                    TyrannoCombatRules.TremorWindupFrames-1,
                    castSeconds,1f,
                    ()=>
                    {
                        if(generation!=combatGeneration||!IsCombatActive(unit))
                            return;
                        if(telegraph!=null)telegraph.Impact();
                        PixelCombatEffect.PlayTyrannoTremorImpact(
                            Flat(unit.model.transform.position),radius,renderer);
                        ResolveTyrantTremor(unit,skill,1f,false,generation);
                    });
            }
        }
        else if(string.Equals(
                    behavior,
                    "AcrobaticBarrage",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.monkeyBarragePending)
        {
            int generation=combatGeneration;
            Unit target=unit.monkeyBarrageTarget;
            unit.spriteAnimation.PlaySkillAttack(
                SpriteSkillAttackPlaybackSpeed(unit),
                ()=>StartReleasedSkill(unit,ResolveAcrobaticBarrage(unit,target,GameMasterData.Skill(unit.skillId),
                    1f,false,generation)));
        }
        else if(string.Equals(
                    behavior,
                    "CrossScytheWind",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.mantisScythePending)
        {
            int generation=combatGeneration;
            Unit target=unit.mantisScytheTarget;
            if(HasRank3(unit,MantisRank3Rules.DivineGuillotine))
                StartMantisGuillotine(unit,target,unit.mantisScytheDamageMultiplier,
                    unit.mantisScytheRadiusMultiplier,generation);
            else if(unit.rank3MantisReaper)
                StartMantisReaperFlight(unit,target,unit.mantisScytheDamageMultiplier,
                    unit.mantisScytheRadiusMultiplier,generation);
            else unit.spriteAnimation.PlayMantisCrossAttack(
                ()=>StartReleasedSkill(unit,ResolveCrossScytheWind(unit,target,GameMasterData.Skill(unit.skillId),
                    1f,false,generation)),HasRank3(unit,MantisRank3Rules.MyriadEyes)
                        ?MantisRank3Rules.MyriadWaveInterval:MantisCombatRules.WaveInterval);
        }
        else if(string.Equals(
                    behavior,
                    "SporeColony",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.mushroomColonyPending)
        {
            int generation=combatGeneration;
            Unit target=unit.mushroomColonyTarget;
            unit.spriteAnimation.PlaySkillAttack(
                SpriteSkillAttackPlaybackSpeed(unit),
                ()=>StartReleasedSkill(unit,ResolveSporeColony(unit,target,GameMasterData.Skill(unit.skillId),
                    1f,false,generation)));
        }
        else if(string.Equals(
                    behavior,
                    "EarthCharge",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.mammothChargePending)
        {
            int generation=combatGeneration;
            Unit target=unit.mammothChargeTarget;
            if(HasRank3(unit,MammothRank3Rules.MountainBrace))StartMammothBrace(unit,generation);
            else if(HasRank3(unit,MammothRank3Rules.MountainToss))StartMammothToss(unit,generation);
            else if(HasRank3(unit,MammothRank3Rules.WallRush)||!HasMammothRank3(unit))StartMammothCharge(unit,generation);
            else unit.spriteAnimation.PlaySkillAttack(
                SpriteSkillAttackPlaybackSpeed(unit),
                ()=>StartCombatCoroutine(unit,ResolveEarthCharge(
                    unit,target,GameMasterData.Skill(unit.skillId),
                    1f,false,generation)));
        }
        else if(string.Equals(behavior,"SkyFlip",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.beetleSkyFlipPending)
        {
            if(!HasBeetleRank3(unit))StartBeetleFlip(unit,unit.beetleSkyFlipTarget,
                GameMasterData.Skill(unit.skillId),combatGeneration);
            else
            {
                int generation=combatGeneration;
                Unit target=unit.beetleSkyFlipTarget;
                float playbackSpeed=SpriteSkillAttackPlaybackSpeed(unit);
                unit.spriteAnimation.PlaySkillAttack(
                    playbackSpeed,
                    ()=>StartCombatCoroutine(unit,ResolveBeetleSkyFlip(
                        unit,target,GameMasterData.Skill(unit.skillId),
                        1f,false,generation)));
            }
        }
        else if(string.Equals(behavior,"SpiritSanctuary",
                    StringComparison.OrdinalIgnoreCase)&&unit.spiritSanctuaryPending)
        {
            int generation=combatGeneration;
            unit.spriteAnimation.PlaySkillAttack(
                unit.spriteAnimation.SkillAttackHitTime/SpiritDeerCombatRules.Windup,
                SpriteSkillAttackPlaybackSpeed(unit),
                ()=>StartReleasedSkill(unit,ResolveSpiritSanctuary(unit,GameMasterData.Skill(unit.skillId),1f,false,generation)));
            if(!mlEpisodeActive)PixelSpiritBlessing.Charge(Rank3Renderer(unit),
                SpiritDeerTint(unit),CaptureSkillTime(unit),
                ()=>generation==combatGeneration&&IsCombatActive(unit)&&
                    unit.spriteAnimation.HasPendingSkillAttackHit);
        }
        else if(string.Equals(behavior,"SkyDive",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.griffinSkyfallPending)
        {
            int generation=combatGeneration;
            SkillMasterRow skill=GameMasterData.Skill(unit.skillId);
            StartGriffinSkyDive(unit,skill,generation);
            if(unit.griffinHunt==null)unit.spriteAnimation.PlaySkillAttackWithHold(
                GriffinCombatRules.SkyDiveAscentFrames-1,
                GriffinSkyDiveTotalDuration(unit,skill),1f,null,CaptureSkillTime(unit));
        }
        else if(string.Equals(behavior,"WyvernBreath",
                    StringComparison.OrdinalIgnoreCase)&&
                (unit.wyvernBreathPending||unit.wyvernBreath!=null))
        {
            int generation=combatGeneration;
            Unit target=unit.wyvernBreathTarget;
            if(unit.wyvernBreath!=null)
                unit.spriteAnimation.PlaySkillAttack(unit.spriteAnimation.SkillAttackHitTime/unit.wyvernBreath.windup,
                    1f,()=>unit.spriteAnimation.HoldSkillAttackHitFrame(unit.wyvernBreath!=null&&unit.wyvernBreath.pressure?
                        WyvernRank3Rules.PressureDuration:unit.wyvernBreath!=null&&unit.wyvernBreath.rain?.25f:
                        unit.wyvernBreath!=null&&unit.wyvernBreath.overheat?WyvernRank3Rules.CoreDuration:WyvernCombatRules.BreathDuration));
            else unit.spriteAnimation.PlaySkillAttack(
                SpriteSkillAttackPlaybackSpeed(unit),
                ()=>PlayWyvernBreath(
                    unit,target,GameMasterData.Skill(unit.skillId),
                    1f,false,generation));
        }
        else if(string.Equals(behavior,"JusticeRoar",
                    StringComparison.OrdinalIgnoreCase)&&
                unit.haetaeRoar!=null)
        {
            float hold=unit.haetaeRoar.bellow?HaetaeRank3Rules.BellowWaveDuration:HaetaeCombatRules.WaveDuration;
            unit.spriteAnimation.PlaySkillAttack(
                unit.spriteAnimation.SkillAttackHitTime/unit.haetaeRoar.windup,1f,
                ()=>unit.spriteAnimation.HoldSkillAttackHitFrame(hold));
        }
        else
            unit.spriteAnimation.PlaySkillAttack();
    }

    private Unit ActiveCombinedCastCommander()
    {
        if(!ExpeditionAugmentSystem.Has(
               expeditionRun,ExpeditionAugmentRuntime.CombinedCast))return null;
        return units.FirstOrDefault(candidate=>IsCombatActive(candidate)&&
            candidate.team==Team.Player&&!candidate.augmentShadowClone&&
            ExpeditionAugmentRuntime.HasBoundSpecialItem(
                expeditionRun,"special_combined_cast_core",candidate.stableId));
    }

    private void HandleAugmentSkillUse(Unit source,bool combinedCastTrigger=false)
    {
        HandleCorruptionSkillUse(source);
        if(source==null||source.team!=Team.Player)return;
        AddProtagonistGauge(source,ExpeditionAugmentRuntime.ProtagonistParam(
            "skill_gain",25f));

        ExpeditionAugmentSelectionSave twin=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.TwinCommand);
        if(twin!=null&&!string.IsNullOrEmpty(twin.runtimeState))
        {
            string[] linked=twin.runtimeState.Split('|');
            if(linked.Contains(source.stableId))
            {
                Unit partner=units.FirstOrDefault(unit=>IsCombatActive(unit)&&
                    unit.team==Team.Player&&unit.stableId!=source.stableId&&
                    linked.Contains(unit.stableId));
                if(partner!=null)
                {
                    AugmentMasterRow master=GameMasterData.Augment(
                        ExpeditionAugmentRuntime.TwinCommand);
                    float charge=master==null?0.35f:
                        master.NumericParam("skill_resonance_charge",0.35f);
                    partner.skillTimer=ExpeditionAugmentRuntime.ChargeSkillCooldown(
                        partner.skillTimer,partner.skillCooldownDuration,charge);
                    twinCommandPulseSourceId=source.stableId;
                    twinCommandPulseTargetId=partner.stableId;
                    twinCommandPulseStartedAt=Time.unscaledTime;
                    AddCombatFloatText(partner,GameLocalization.Format(
                        "augment.twin_resonance","공명 +{0}%",Mathf.RoundToInt(charge*100f)),
                        new Color(1f,0.7f,0.18f),true);
                }
            }
        }

        if(combinedCastTrigger||!ExpeditionAugmentRuntime.HasBoundSpecialItem(
            expeditionRun,"special_combined_cast_core",source.stableId))return;
        List<Unit> contributors=units.Where(unit=>IsCombatActive(unit)&&
            unit.team==Team.Player&&unit!=source&&!unit.augmentShadowClone&&
            !string.IsNullOrEmpty(unit.skillId)).ToList();
        AugmentMasterRow combinedMaster=GameMasterData.Augment(
            ExpeditionAugmentRuntime.CombinedCast);
        var group=new QueuedCombinedSkillGroup{
            commander=source,
            perSkill=combinedMaster==null?0.5f:combinedMaster.NumericParam("extra_cooldown_per_skill",0.5f),
            maximum=combinedMaster==null?18f:combinedMaster.NumericParam("max_cooldown",18f)};
        for(int i=0;i<contributors.Count;i++)
        {
            Unit contributor=contributors[i];
            if(HasSkillCastPresentation(contributor)||IsSabertoothCinematicPending(contributor))continue;
            Unit target=IsCombatActive(contributor.target)?contributor.target:source.target;
            if(!IsCombatActive(target))continue;
            contributor.target=target;
            int usesBefore=contributor.skillUses;
            if(!TryUseSkill(contributor,true))continue;
            if(contributor.skillUses>usesBefore)
                CommitCombinedSkillFocus(group,contributor);
            else if(!AttachSabertoothCinematicCombinedSkill(contributor,group))
                AttachCombinedSkillFocus(contributor,group);
        }
    }

    private bool AddProtagonistGauge(Unit unit,float amount)
    {
        ExpeditionAugmentSelectionSave hero=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.Protagonist);
        if(unit==null||unit.team!=Team.Player||unit.augmentClimaxUsed||
           !ExpeditionAugmentRuntime.Targets(hero,unit.stableId))return false;
        float maximum=ExpeditionAugmentRuntime.ProtagonistParam("gauge_max",100f);
        unit.augmentProtagonistGauge=Mathf.Min(maximum,
            unit.augmentProtagonistGauge+Mathf.Max(0f,amount));
        if(unit.augmentProtagonistGauge<maximum)return true;
        unit.augmentClimaxUsed=true;
        unit.augmentClimaxTimer=ExpeditionAugmentRuntime.ProtagonistParam(
            "climax_duration",8f);
        unit.augmentProtagonistGauge=0f;
        Heal(unit,(unit.maxHp-unit.hp)*ExpeditionAugmentRuntime.ProtagonistParam(
            "climax_lost_health_heal",0.40f));
        CreateSkillPulse(unit,new Color(1f,0.72f,0.12f),1.35f);
        PlayProtagonistClimax(unit);
        return true;
    }

    private void PlayProtagonistClimax(Unit unit)
    {
        if(!IsCombatActive(unit))return;
        Transform anchor=unit.spriteAnimation==null
            ?unit.model.transform:unit.spriteAnimation.transform;
        SpriteRenderer renderer=unit.spriteAnimation==null
            ?unit.model.GetComponentInChildren<SpriteRenderer>()
            :unit.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelCombatEffect.PlayBearSpiritBurst(anchor,renderer);
        PixelCombatEffect.PlayKingpaRoyalAura(
            anchor,renderer,unit.augmentClimaxTimer,
            new Color(1f,0.48f,0.04f,0.94f),
            new Color(1f,0.96f,0.42f,0.96f),
            "Protagonist Climax Pixel Aura");
        PixelCombatEffect.PlayProtagonistClimaxFlameOutline(
            renderer,unit.augmentClimaxTimer);
        StartCombatCoroutine(unit,PlayProtagonistClimaxAfterimages(
            unit,unit.augmentClimaxTimer,combatGeneration));
    }

    private IEnumerator PlayProtagonistClimaxAfterimages(
        Unit unit,float duration,int generation)
    {
        float remaining=duration;
        while(remaining>0f&&generation==combatGeneration&&IsCombatActive(unit))
        {
            SpriteRenderer renderer=unit.spriteAnimation==null?null:
                unit.spriteAnimation.GetComponent<SpriteRenderer>();
            if(renderer!=null&&renderer.sprite!=null)
            {
                Vector3 direction=Flat(unit.velocity);
                if(direction.sqrMagnitude<0.001f)direction=Flat(unit.model.transform.forward);
                Vector3 end=renderer.transform.position;
                Vector3 start=end-direction.normalized*0.16f;
                PixelCombatEffect.PlayWolfHuntAfterimage(
                    renderer,start,end,new Color(1f,0.72f,0.12f,0.48f),0.22f,
                    "Protagonist Climax Afterimage");
            }
            yield return new WaitForSeconds(0.28f);
            remaining-=0.28f;
        }
    }

    private Unit SelectClusterSkillTarget(Unit source)
    {
        if(source==null||source.model==null)return null;
        SkillMasterRow skill=GameMasterData.Skill(source.skillId);
        float castRange=TileSize*Mathf.Max(1f,skill==null?source.definition.attackRange:
            Mathf.Max(source.definition.attackRange,skill.castRangeTiles));
        float clusterRadius=TileSize*Mathf.Max(1f,skill==null?1f:skill.radiusTiles);
        Vector3 origin=Flat(source.model.transform.position);
        return units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=source.team&&
                Vector3.Distance(origin,Flat(enemy.model.transform.position))<=castRange+
                source.collisionRadius+enemy.collisionRadius)
            .OrderByDescending(enemy=>CountActiveEnemiesInRadius(source.team,
                Flat(enemy.model.transform.position),clusterRadius))
            .ThenBy(enemy=>Vector3.Distance(origin,Flat(enemy.model.transform.position)))
            .FirstOrDefault();
    }

    private Unit SelectFinisherTarget(Unit source)
    {
        return units.Where(candidate=>IsCombatActive(candidate)&&candidate.team!=source.team)
            .OrderBy(candidate=>candidate.hp/Mathf.Max(1f,candidate.maxHp))
            .ThenBy(candidate=>Vector3.Distance(Flat(source.model.transform.position),
                Flat(candidate.model.transform.position)))
            .FirstOrDefault();
    }

    private Unit SelectLowestHealthAlly(Unit source)
    {
        return units.Where(ally=>IsCombatActive(ally)&&ally.team==source.team&&
                !ally.augmentShadowClone&&ally.spiritConcertOwner==null)
            .OrderBy(ally=>ally.hp/Mathf.Max(1f,ally.maxHp)).FirstOrDefault();
    }

    private void TriggerSkillTeamTraits(Unit source)
    {
        Unit nearestAlly=units.Where(ally=>ally!=source&&IsCombatActive(ally)&&ally.team==source.team)
            .OrderBy(ally=>Vector3.Distance(Flat(source.model.transform.position),
                Flat(ally.model.transform.position)))
            .FirstOrDefault();
        if(nearestAlly!=null&&MonsterTraitRuntime.GrantCommandedAttack(
            source.activeTraitIds,nearestAlly.traitState))source.traitActivations++;

        if(MonsterTraitRuntime.Has(source.activeTraitIds,"trait_skill_effect_spread"))
        {
            foreach(Unit ally in units.Where(ally=>ally!=source&&IsCombatActive(ally)&&
                     ally.team==source.team)
                .OrderBy(ally=>Vector3.Distance(Flat(source.model.transform.position),
                    Flat(ally.model.transform.position))).Take(2))
                ally.combatStatuses.ApplyTimed(CombatStatusKind.ComboRally,6f,source,0.12f);
            source.traitActivations++;
        }
        CombatStatusEffect receivedRally=source.combatStatuses.Get(CombatStatusKind.ComboRally);
        if(receivedRally!=null&&receivedRally.source is Unit&&receivedRally.source!=source&&
           MonsterTraitRuntime.Has(source.activeTraitIds,"trait_combo_resolve_barrier"))
        {
            source.combatStatuses.ApplyShield(5f,source.maxHp*0.08f,source);
            Unit weakest=units.Where(ally=>ally!=source&&IsCombatActive(ally)&&ally.team==source.team)
                .OrderBy(ally=>ally.hp/Mathf.Max(1f,ally.maxHp)).FirstOrDefault();
            if(weakest!=null)weakest.combatStatuses.ApplyShield(5f,weakest.maxHp*0.08f,source);
            RecordComboActivation(source,source,"trait_combo_resolve_barrier",0f);
        }

        MonsterCombatTag tags=MonsterTraitCatalog.ResolveTags(source.definition);
        if((tags&MonsterCombatTag.ElementalSkill)==0)return;
        for(int i=0;i<units.Count;i++)
        {
            Unit ally=units[i];
            if(ally==source||!IsCombatActive(ally)||ally.team!=source.team)continue;
            if(!MonsterTraitRuntime.GrantElementResonance(ally.activeTraitIds,ally.traitState))continue;
            ally.traitActivations++;
        }
    }

    private void ExecuteSkillEcho(Unit unit)
    {
        if(unit.combatStatuses.Has(CombatStatusKind.Silence)||unit.combatStatuses.Has(CombatStatusKind.Fear))
        {
            unit.skillEchoTimer=Mathf.Max(unit.skillEchoTimer,0.01f);
            return;
        }
        float effectScale=unit.rank3EchoScale>0f?unit.rank3EchoScale:0.65f;
        unit.rank3EchoScale=0f;
        string behavior=MonsterSkillExecutor<SkillExecutionContext>.Behavior(unit.skillEchoId);
        Unit originalTarget=unit.skillEchoTarget;
        SkillMasterRow skill=GameMasterData.Skill(unit.skillEchoId);
        Unit target=IsCombatActive(originalTarget)?originalTarget:SelectTarget(unit);
        unit.skillEchoTarget=null;
        unit.skillEchoId="";
        if(skill==null||!IsCombatActive(unit)||!IsCombatActive(target))return;
        if(string.Equals(behavior,"GuardianTaunt",StringComparison.OrdinalIgnoreCase))
            UseGuardianTaunt(unit,skill,effectScale,true);
        else if(string.Equals(behavior,"ClusterBreath",StringComparison.OrdinalIgnoreCase))
        {
            Unit previous=unit.target;
            unit.target=target;
            UseClusterBreath(unit,skill,effectScale,true);
            unit.target=previous;
        }
        else if(string.Equals(behavior,"AssassinLeap",StringComparison.OrdinalIgnoreCase))
        {
            float dealt=ApplySkillDamage(unit,target,
                unit.damage*skill.damageMultiplier*effectScale,false);
            unit.skillDamage+=dealt;
            unit.skillHits++;
            CreateSkillPulse(unit,new Color(0.78f,0.38f,1f),0.75f);
            RecordSkillEvent(unit,skill.id+"_echo",1,dealt);
        }
        else if(string.Equals(behavior,"TongueHarpoon",StringComparison.OrdinalIgnoreCase))
            ResolveTongueHarpoonEcho(unit,target,skill);
        else if(string.Equals(behavior,"EarthPulse",StringComparison.OrdinalIgnoreCase))
            ResolveEarthPulseImpact(unit,skill,effectScale,true);
        else if(string.Equals(behavior,"MagicStarBarrage",StringComparison.OrdinalIgnoreCase))
        {
            if(UsesWizardCygnusShower(unit))ResolveWizardCygnusShowerEcho(unit,target,effectScale);
            else StartReleasedSkill(unit,ResolveMagicStarBarrage(unit,skill,effectScale,true,combatGeneration));
        }
        else if(string.Equals(behavior,"ShadowSlash",StringComparison.OrdinalIgnoreCase))
            UseShadowSlashEcho(unit,target,skill);
        else if(string.Equals(behavior,"DeathRoll",StringComparison.OrdinalIgnoreCase))
        {
            if(UsesCrocodileAbyssDive(unit)){ResolveCrocodileAbyssDiveEcho(unit,target,effectScale);return;}
            PlayCrocodileSound(unit,CrocodileSound.Crush,target.model.transform.position,.7f);
            float missing=Mathf.Max(0f,target.maxHp-target.hp);
            float raw=CrocodileCombatRules.HitDamage(unit.damage,0,missing)+
                      CrocodileCombatRules.HitDamage(unit.damage,1,missing)+
                      CrocodileCombatRules.HitDamage(unit.damage,2,missing);
            float dealt=ApplySkillDamage(unit,target,raw*effectScale,false);
            unit.skillDamage+=dealt;unit.skillHits++;
            CreateSkillPulse(unit,new Color(0.38f,0.68f,0.2f),0.62f);
            RecordSkillEvent(unit,skill.id+"_echo",1,dealt);
        }
        else if(string.Equals(behavior,"FangLock",StringComparison.OrdinalIgnoreCase))
        {
            if(UsesSabertoothDevour(unit)){ResolveSabertoothDevourEcho(unit,effectScale);return;}
            SkillDamageFormulaResult hit=SabertoothCombatRules.DamagePerHit(
                SkillPower(unit),skill.damageMultiplier,target.maxHp);
            float scale=SabertoothCombatRules.HitCount*effectScale;
            float dealt=ApplySkillDamage(unit,target,
                new SkillDamageFormulaResult(
                    hit.physicalDamage*scale,hit.trueDamage*scale,0f),false);
            unit.skillDamage+=dealt;unit.skillHits++;
            target.combatStatuses.ApplyTimed(
                CombatStatusKind.Root,
                HostileStatusDuration(target,skill.statusDurationSeconds*effectScale),
                unit,skill.statusValue);
            CombatStatusEffect silence=ApplyThroatLockSilence(unit,target);
            if(silence!=null)StartCombatCoroutine(unit,HoldEchoThroatLockSilence(target,silence));
            CreateSkillPulse(unit,new Color(0.95f,0.72f,0.2f),0.7f);
            RecordSkillEvent(unit,skill.id+"_echo",1,dealt);
        }
        else if(string.Equals(behavior,"FightingSpirit",StringComparison.OrdinalIgnoreCase))
            ApplyBearFightingSpirit(unit,skill,effectScale,true,combatGeneration);
        else if(string.Equals(behavior,"ThreeSidedHunt",StringComparison.OrdinalIgnoreCase))
        {
            if(UsesWolfStampede(unit))ResolveWolfStampedeEcho(unit,effectScale);
            else StartCombatCoroutine(unit,ResolveThreeSidedHunt(
                unit,target,Flat(unit.model.transform.position),skill,
                effectScale,true,combatGeneration));
        }
        else if(string.Equals(behavior,"Skyfall",StringComparison.OrdinalIgnoreCase))
            ResolveGriffinSkyfallImpact(unit,skill,Flat(unit.model.transform.position),
                effectScale,true,false);
        else if(string.Equals(behavior,"HighHeadSlam",StringComparison.OrdinalIgnoreCase))
            ResolveGiraffeHighSlamImpact(unit,skill,Flat(target.model.transform.position),
                effectScale,true,false,false);
        else if(string.Equals(behavior,"GiantCaptureWeb",StringComparison.OrdinalIgnoreCase))
        {
            Unit previous=unit.target;
            unit.target=target;
            unit.spiderWebTarget=Flat(target.model.transform.position);
            LaunchSpiderCaptureWeb(unit,skill,effectScale,true,combatGeneration);
            unit.target=previous;
        }
        else if(string.Equals(behavior,"ShadowHunt",StringComparison.OrdinalIgnoreCase))
        {
            // One rank-4 pulse replaces the hunt; an echo cannot reintroduce rank-3 attacks.
            if(HasFamilyTranscendence(unit)&&IsNinjaCatFamily(unit))return;
            ResolveShadowHuntEcho(unit,target,skill);
        }
        else if(string.Equals(behavior,"TyrantTremor",StringComparison.OrdinalIgnoreCase))
            ResolveTyrantTremor(unit,skill,effectScale,true,combatGeneration);
        else if(string.Equals(behavior,"AcrobaticBarrage",StringComparison.OrdinalIgnoreCase))
        {
            if(HasFamilyTranscendence(unit)&&unit.definition.familyId=="monkey")return;
            StartReleasedSkill(unit,ResolveAcrobaticBarrage(unit,target,skill,effectScale,true,combatGeneration));
        }
        else if(string.Equals(behavior,"CrossScytheWind",StringComparison.OrdinalIgnoreCase))
            StartReleasedSkill(unit,ResolveCrossScytheWind(unit,target,skill,effectScale,true,combatGeneration));
        else if(string.Equals(behavior,"SporeColony",StringComparison.OrdinalIgnoreCase))
            StartReleasedSkill(unit,ResolveSporeColony(unit,target,skill,effectScale,true,combatGeneration));
        else if(string.Equals(behavior,"EarthCharge",StringComparison.OrdinalIgnoreCase))
        {
            if(HasFamilyTranscendence(unit)&&unit.definition.familyId=="mammoth")return;
            StartCombatCoroutine(unit,ResolveEarthCharge(
                unit,target,skill,effectScale,true,combatGeneration));
        }
        else if(string.Equals(behavior,"SkyFlip",StringComparison.OrdinalIgnoreCase))
        {
            if(HasFamilyTranscendence(unit))return;
            StartCombatCoroutine(unit,ResolveBeetleSkyFlip(
                unit,target,skill,effectScale,true,combatGeneration));
        }
        else if(string.Equals(behavior,"SpiritSanctuary",StringComparison.OrdinalIgnoreCase))
            StartReleasedSkill(unit,ResolveSpiritSanctuary(unit,skill,effectScale,true,combatGeneration));
        else if(string.Equals(behavior,"SkyDive",StringComparison.OrdinalIgnoreCase))
            ResolveGriffinSkyfallImpact(
                unit,skill,Flat(unit.model.transform.position),effectScale,true,false);
        else if(string.Equals(behavior,"WyvernBreath",StringComparison.OrdinalIgnoreCase))
        {
            if(HasFamilyTranscendence(unit)&&IsWyvernFamily(unit))return;
            ResolveWyvernBreath(
                unit,target,skill,effectScale,true,combatGeneration);
        }
        else if(string.Equals(behavior,"JusticeRoar",StringComparison.OrdinalIgnoreCase))
            ResolveHaetaeJusticeRoar(
                unit,skill,effectScale,true,combatGeneration);
        unit.traitActivations++;
    }

    private SkillUseSnapshot BuildSkillSnapshot(Unit unit)
    {
        SkillMasterRow skill=GameMasterData.Skill(unit.skillId);
        string behavior=skill==null?string.Empty:skill.behavior??string.Empty;
        Vector3 origin=Flat(unit.model.transform.position);
        Vector3 targetPosition=IsCombatTargetable(unit.target)?Flat(unit.target.model.transform.position):origin;
        SkillUseSnapshot snapshot=new SkillUseSnapshot
        {
            behavior=behavior,
            targetDistanceTiles=Vector3.Distance(origin,targetPosition)/TileSize,
            alliesInEffect=HaetaeSupportTargets(unit,skill)
        };

        if(string.Equals(behavior,"GuardianTaunt",StringComparison.OrdinalIgnoreCase))
        {
            float radius=SkillActivationDistance(unit,unit.target,skill);
            snapshot.enemiesInEffect=CountActiveEnemiesInRadius(unit.team,origin,radius);
        }
        else if(string.Equals(behavior,"ClusterBreath",StringComparison.OrdinalIgnoreCase))
        {
            float radius=SkillActivationDistance(unit,unit.target,skill);
            Vector3 forward=(targetPosition-origin).normalized;
            snapshot.enemiesInEffect=units.Count(enemy=>
            {
                if(!IsCombatActive(enemy)||enemy.team==unit.team)return false;
                Vector3 offset=Flat(enemy.model.transform.position)-origin;
                return offset.magnitude<=radius&&Vector3.Dot(forward,offset.normalized)>=0.55f;
            });
        }
        else if(string.Equals(behavior,"EarthPulse",StringComparison.OrdinalIgnoreCase)||
                string.Equals(behavior,"TyrantTremor",StringComparison.OrdinalIgnoreCase)||
                string.Equals(behavior,"JusticeRoar",StringComparison.OrdinalIgnoreCase))
        {
            float radius=SkillActivationDistance(unit,unit.target,skill);
            snapshot.enemiesInEffect=CountActiveEnemiesInRadius(unit.team,origin,radius);
        }
        else if(string.Equals(behavior,"HighHeadSlam",StringComparison.OrdinalIgnoreCase)||
                string.Equals(behavior,"AcrobaticBarrage",StringComparison.OrdinalIgnoreCase))
        {
            float radius=TileSize*Mathf.Max(0f,skill.radiusTiles)*unit.skillTraitRadiusMultiplier;
            snapshot.enemiesInEffect=CountActiveEnemiesInRadius(
                unit.team,targetPosition,radius);
        }
        else if(string.Equals(behavior,"GiantCaptureWeb",StringComparison.OrdinalIgnoreCase))
        {
            float radius=TileSize*Mathf.Max(0f,skill.radiusTiles)*
                         unit.skillTraitRadiusMultiplier;
            snapshot.enemiesInEffect=CountActiveEnemiesInRadius(
                unit.team,targetPosition,radius);
        }
        else if(string.Equals(behavior,"Skyfall",StringComparison.OrdinalIgnoreCase))
        {
            float radius=SkillActivationDistance(unit,unit.target,skill);
            snapshot.enemiesInEffect=CountActiveEnemiesInRadius(unit.team,origin,radius);
        }
        else if(string.Equals(behavior,"SkyFlip",StringComparison.OrdinalIgnoreCase))
        {
            snapshot.enemiesInEffect=HasFamilyTranscendence(unit)
                ?units.Count(enemy=>enemy.team!=unit.team&&IsCombatTargetable(enemy))
                :CountActiveEnemiesInRadius(unit.team,targetPosition,TileSize*Mathf.Max(1f,skill.radiusTiles));
        }
        else if(string.Equals(behavior,"SpiritSanctuary",StringComparison.OrdinalIgnoreCase))
        {
            float castRadius=TileSize*Mathf.Max(1f,skill.castRangeTiles);
            List<Unit> wounded=units.Where(ally=>IsCombatActive(ally)&&
                ally.team==unit.team&&ally.hp<ally.maxHp&&
                Vector3.Distance(origin,Flat(ally.model.transform.position))<=castRadius).ToList();
            snapshot.alliesInEffect=wounded.Count;
        }
        else if(string.Equals(behavior,"SkyDive",StringComparison.OrdinalIgnoreCase))
        {
            snapshot.enemiesInEffect=GriffinDiveTarget(unit,skill)==null?0:1;
        }
        else if(string.Equals(behavior,"WyvernBreath",StringComparison.OrdinalIgnoreCase))
        {
            Vector3 forward=(targetPosition-origin).normalized;
            snapshot.enemiesInEffect=HasFamilyTranscendence(unit)
                ?units.Count(enemy=>enemy.team!=unit.team&&IsCombatTargetable(enemy))
                :CountEnemiesInSkillLine(unit,origin,forward,TileSize*Mathf.Max(1f,skill.castRangeTiles));
        }
        else if(string.Equals(behavior,"CrossScytheWind",StringComparison.OrdinalIgnoreCase))
        {
            bool extended=MonsterTraitRuntime.Has(
                unit.activeTraitIds,MantisCombatRules.SantiusTraitId);
            Vector3 forward=(targetPosition-origin).normalized;
            float length=TileSize*MantisCombatRules.RangeTiles(
                skill.castRangeTiles,extended);
            float width=TileSize*MantisCombatRules.WidthTiles(
                skill.radiusTiles,extended)*unit.skillTraitRadiusMultiplier;
            snapshot.enemiesInEffect=units.Count(enemy=>
            {
                if(!IsCombatActive(enemy)||enemy.team==unit.team)return false;
                Vector3 point=Flat(enemy.model.transform.position);
                return IsPointInsideForwardSkillLine(
                           origin,Quaternion.AngleAxis(
                               -MantisCombatRules.WaveAngle,Vector3.up)*forward,
                           point,length,width+enemy.collisionRadius)||
                       IsPointInsideForwardSkillLine(
                           origin,Quaternion.AngleAxis(
                               MantisCombatRules.WaveAngle,Vector3.up)*forward,
                           point,length,width+enemy.collisionRadius);
            });
        }
        else if(string.Equals(behavior,"SporeColony",StringComparison.OrdinalIgnoreCase))
        {
            float radius=TileSize*(MushroomCombatRules.SporeOffsetRadiusTiles+
                                   skill.radiusTiles*unit.skillTraitRadiusMultiplier);
            snapshot.enemiesInEffect=CountActiveEnemiesInRadius(
                unit.team,targetPosition,radius);
        }
        else if(string.Equals(behavior,"EarthCharge",StringComparison.OrdinalIgnoreCase))
        {
            Vector3 forward=targetPosition-origin;
            float length=Mathf.Min(
                forward.magnitude,
                TileSize*MammothCombatRules.MaximumChargeDistanceTiles);
            snapshot.enemiesInEffect=forward.sqrMagnitude<0.001f?0:
                CountEnemiesInSkillLine(unit,origin,forward.normalized,length);
        }
        return snapshot;
    }

    private bool BeginBearFightingSpirit(Unit unit,SkillMasterRow skill)
    {
        if(unit==null||skill==null||!IsCombatActive(unit))return false;
        unit.bearSpiritPending=true;
        EnsureBearSpiritFx(unit)?.Prepare();
        bool firstVanguard=MonsterTraitRuntime.Has(unit.activeTraitIds,
            "trait_skill_vanguard_resolve")&&unit.traitState.bearResolveUses==0;
        unit.skillTimer=firstVanguard?15f:unit.skillCooldownDuration;
        unit.traitState.bearResolveUses++;
        unit.skillUses++;
        unit.currentAction="fighting_spirit_prepare";
        unit.velocity=Vector3.zero;
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        ApplyPostSkillItemEffects(unit);
        if(!HasFamilyTranscendence(unit)&&unit.spriteAnimation!=null&&MonsterTraitRuntime.Has(
               unit.activeTraitIds,BearCombatRules.KingOfBeastsRoarTraitId))
        {
            SpriteRenderer renderer=
                unit.spriteAnimation.GetComponent<SpriteRenderer>();
            PixelCombatEffect.PlayBearKingRoarSpirit(
                unit.spriteAnimation.transform,renderer);
        }
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(unit.spriteAnimation==null)
            ApplyBearFightingSpirit(unit,skill,1f,false,combatGeneration);
        return true;
    }

    private PixelBearFightingSpirit EnsureBearSpiritFx(Unit unit)
    {
        if(mlEpisodeActive||unit.spriteAnimation==null)return null;
        if(unit.bearSpiritFx!=null)return unit.bearSpiritFx;
        int generation=combatGeneration;
        unit.bearSpiritFx=PixelBearFightingSpirit.Create(unit.spriteAnimation.transform,
            unit.spriteAnimation.GetComponent<SpriteRenderer>(),
            ()=>this!=null&&isActiveAndEnabled&&!battleEnding&&generation==combatGeneration&&IsCombatActive(unit),
            ()=>unit.bearResolveTimer>0f);
        return unit.bearSpiritFx;
    }

    private bool ApplyBearFightingSpirit(Unit unit,SkillMasterRow skill,
        float effectScale,bool traitEcho,int generation)
    {
        if(generation!=combatGeneration||unit==null||skill==null||
           !IsCombatActive(unit))return false;
        unit.bearSpiritPending=false;
        bool mountain=!traitEcho&&MonsterTraitRuntime.Has(
            unit.activeTraitIds,BearCombatRules.MountainColossusTraitId);
        bool kingRoar=!traitEcho&&MonsterTraitRuntime.Has(
            unit.activeTraitIds,BearCombatRules.KingOfBeastsRoarTraitId);
        float duration=Mathf.Max(0.1f,(mountain
            ?BearCombatRules.MountainDuration:skill.durationSeconds)*effectScale);
        float attackSpeed=BearCombatRules.ResolveAttackSpeedBonus;
        float damageReduction=BearCombatRules.ResolveDamageReduction;
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_skill_time_compression"))
        {
            duration*=0.5f;attackSpeed*=2f;damageReduction=Mathf.Min(0.8f,damageReduction*2f);
            unit.traitActivations++;
        }
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_skill_overcharge"))
        {attackSpeed*=1.7f;damageReduction=Mathf.Min(0.8f,damageReduction*1.7f);}
        attackSpeed*=Rank2BuffMultiplier(unit);
        damageReduction=Mathf.Min(0.8f,damageReduction*Rank2BuffMultiplier(unit));
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_skill_stance_division"))
        {
            unit.traitState.bearDefenseStance=unit.hp<=unit.maxHp*0.5f;
            if(unit.traitState.bearDefenseStance){attackSpeed=0f;damageReduction=0.35f;}
            else {attackSpeed=0.45f;damageReduction=0f;}
            unit.traitActivations++;
        }
        float mountainDuration=duration;
        if(!traitEcho&&HasFamilyTranscendence(unit))
            duration=FamilyTranscendenceRules.BearAvatarDuration;
        if(unit.bearResolveTimer<=0f)unit.bearFrenzyStacks=0;
        unit.bearResolveTimer=Mathf.Max(unit.bearResolveTimer,duration);
        unit.bearResolveTotalDuration=duration;
        unit.bearResolveAttackSpeedBonus=GateHaetaeBenefit(unit,attackSpeed);
        unit.bearResolveDamageReduction=GateHaetaeBenefit(unit,damageReduction);
        EnsureBearSpiritFx(unit)?.Ignite(mountain||MountainColossusActive(unit));
        if(!traitEcho&&!HasFamilyTranscendence(unit)&&!kingRoar)
            PlayBearSound(unit,mountain?BearSound.Growth:BearSound.Ignite,unit.model.transform.position);
        if(mountain)ActivateBearMountainColossus(unit,mountainDuration);
        unit.currentAction="bear_resolve";
        unit.velocity=Vector3.zero;
        StopBeforeAttack(unit);
        SetMoving(unit,false);

        if(MonsterTraitRuntime.Has(
               unit.activeTraitIds,BearCombatRules.IronKumaTraitId))
        {
            PlayTraitBurst(unit,new Color(0.72f,0.88f,1f),true);
        }

        if(!traitEcho&&MonsterTraitRuntime.Has(
               unit.activeTraitIds,BearCombatRules.DamiTraitId))
        {
            Unit ally=SelectLowestHealthAlly(unit);
            if(ally!=null)
            {
                ally.combatStatuses.ApplyShield(
                    BearCombatRules.DamiShieldDuration,
                    BearCombatRules.DamiShield(unit.maxHp),unit);
                CreateSkillPulse(ally,new Color(0.96f,0.62f,0.18f),0.58f);
                PlayTraitBurst(ally,new Color(1f,0.76f,0.22f),true);
            }
            unit.traitActivations++;
        }

        if(kingRoar)
        {
            unit.bearKingRoarActive=true;
            ResolveBearKingRoar(unit,false);
        }

        if(!traitEcho&&HasFamilyTranscendence(unit))BeginBearAvatar(unit);

        RecordSkillEvent(unit,traitEcho?skill.id+"_echo":skill.id,0,0f);
        return true;
    }

    private void ActivateBearMountainColossus(Unit unit,float duration)
    {
        if(unit==null||unit.model==null)return;
        if(!unit.bearMountainColossusActive&&unit.bearMountainVisualBlend<=0f)
        {
            unit.bearMountainBaseScale=unit.model.transform.localScale;
            unit.bearMountainBaseBodyScale=unit.combatBodyScale;
            unit.bearMountainBaseVisualHeightOffset=unit.visualHeightOffset;
        }
        unit.bearMountainColossusActive=true;
        unit.bearMountainShield=GateHaetaeBenefit(unit,BearCombatRules.MountainShield(unit.maxHp)*
            Mathf.Max(0f,unit.combatStatuses.shieldGainMultiplier)*GuardianShieldMultiplier(unit),CombatBenefitKind.Shield);
        unit.bearMountainShieldTimer=duration;
        if(!HasFamilyTranscendence(unit)&&!mlEpisodeActive&&unit.bearMountainHologram==null&&unit.spriteAnimation!=null)
            unit.bearMountainHologram=PixelCombatEffect.PlayBearMountainColossusHologram(
                unit.spriteAnimation.transform,unit.spriteAnimation.GetComponent<SpriteRenderer>());
        unit.traitActivations++;
    }

    private void UpdateBearMountainScale(Unit unit,float dt)
    {
        if(unit.model==null||(!unit.bearMountainColossusActive&&unit.bearMountainVisualBlend<=0f))return;
        unit.bearMountainVisualBlend=Mathf.MoveTowards(unit.bearMountainVisualBlend,
            unit.bearMountainColossusActive?1f:0f,dt/BearCombatRules.MountainScaleTransitionDuration);
        float scale=Mathf.Lerp(1f,BearCombatRules.MountainVisualScale,
            Mathf.SmoothStep(0f,1f,unit.bearMountainVisualBlend));
        if(BearAvatarActive(unit))scale=1f;
        unit.model.transform.localScale=unit.bearMountainBaseScale*scale;
        unit.combatBodyScale=unit.bearMountainBaseBodyScale*scale;
        unit.visualHeightOffset=(unit.bearMountainBaseVisualHeightOffset-PixelMonsterGroundOffset)*
            scale+PixelMonsterGroundOffset;
        unit.model.transform.position=Flat(unit.model.transform.position)+Vector3.up*unit.visualHeightOffset;
        CacheMeleeReadabilityBody(unit);
        unit.targetRing?.SetRadius(Mathf.Max(.3f,CombatBodyRadius(unit)*1.15f));
    }

    private void EndBearMountainColossus(Unit unit,bool immediate=true)
    {
        if(unit==null)return;
        unit.bearMountainColossusActive=false;
        unit.bearMountainShield=0f;unit.bearMountainShieldTimer=0f;
        PixelCombatEffect.StopBearMountainColossusHologram(unit.bearMountainHologram);
        unit.bearMountainHologram=null;
        if(immediate)UpdateBearMountainScale(unit,BearCombatRules.MountainScaleTransitionDuration);
    }

    private void EndBearKingRoar(Unit unit)
    {
        if(unit==null||!unit.bearKingRoarActive)return;
        unit.bearKingRoarActive=false;
        if(!IsCombatActive(unit))return;
        float damage=BearCombatRules.KingRoarEndDamage(SkillPower(unit),unit.bearFrenzyStacks);
        unit.bearKingRoarEnding=true;
        StartCombatCoroutine(unit,PrepareBearKingFinalRoar(unit,damage,combatGeneration));
    }

    private IEnumerator PrepareBearKingFinalRoar(Unit source,float damage,int generation)
    {
        try
        {
            // Let an attack already in flight finish before the final roar takes the body.
            while(generation==combatGeneration&&IsCombatActive(source)&&source.bearKingRoarEnding&&
                  (source.spriteAnimation!=null&&source.spriteAnimation.IsActionLocked||
                   source.giraffeStunTimer>0f||source.displacing||source.preyDraggedBy!=null||
                   source.combatStatuses.Has(CombatStatusKind.Freeze)||
                   source.combatStatuses.Has(CombatStatusKind.Knockdown)||
                   source.combatStatuses.Has(CombatStatusKind.Fear)||
                   source.combatStatuses.Has(CombatStatusKind.Airborne)))
                yield return null;
            if(generation!=combatGeneration||!IsCombatActive(source)||!source.bearKingRoarEnding)
                yield break;
            StopUnitMovement(source);
            if(source.spriteAnimation==null)
            {
                ResolveBearKingRoar(source,true,damage);
                yield break;
            }
            SpriteRenderer renderer=source.spriteAnimation.GetComponent<SpriteRenderer>();
            if(!BearAvatarActive(source))
                PixelCombatEffect.PlayBearKingRoarSpirit(source.spriteAnimation.transform,renderer,true);
            source.spriteAnimation.PlayBearFightingSpirit(1f,()=>
            {
                if(generation==combatGeneration&&IsCombatActive(source))
                {
                    source.spriteAnimation.HoldSkillAttackHitFrame(.25f);
                    ResolveBearKingRoar(source,true,damage);
                }
            });
            while(generation==combatGeneration&&IsCombatActive(source)&&
                  source.spriteAnimation!=null&&source.spriteAnimation.IsActionLocked)
                yield return null;
        }
        finally
        {
            if(generation==combatGeneration)source.bearKingRoarEnding=false;
        }
    }

    private void ResolveBearKingRoar(Unit source,bool ending,float finalDamage=-1f)
    {
        if(!IsCombatActive(source))return;
        Vector3 center=Flat(source.model.transform.position);
        float radius=TileSize*(ending?BearCombatRules.KingRoarEndRadiusTiles:
            BearCombatRules.KingRoarStartRadiusTiles);
        float damage=ending?(finalDamage>=0f?finalDamage:
            BearCombatRules.KingRoarEndDamage(SkillPower(source),source.bearFrenzyStacks)):
            SkillPower(source)*BearCombatRules.KingRoarStartDamageRatio;
        SpriteRenderer renderer=source.spriteAnimation==null?
            source.model.GetComponentInChildren<SpriteRenderer>():
            source.spriteAnimation.GetComponent<SpriteRenderer>();
        var effect=mlEpisodeActive?null:PixelCombatEffect.PlayBearKingRoarBurst(
            center,radius,renderer,ending);
        if(!ending&&!HasFamilyTranscendence(source))
            PlayBearSound(source,BearSound.RoarStart,source.model.transform.position);
        StartReleasedSkill(source,AdvanceBearKingRoar(source,center,radius,damage,ending,
            effect,combatGeneration));
    }

    private IEnumerator AdvanceBearKingRoar(Unit source,Vector3 center,float radius,float damage,
        bool ending,PixelCombatEffect effect,int generation)
    {
        var hit=new HashSet<Unit>();
        float age=0f,dealt=0f;
        bool shook=false;
        while(ReleasedSkillValid(source,generation))
        {
            float reach=radius*Mathf.Clamp01(age/BearCombatRules.KingRoarTravelDuration);
            int before=hit.Count;
            dealt+=ApplyBearKingRoarWave(source,center,reach,damage,ending,hit);
            if(ending&&!shook&&hit.Count>before)
            {
                combatCameraDirector?.ReportGroundSlam();
                shook=true;
            }
            if(age>=BearCombatRules.KingRoarTravelDuration)break;
            yield return null;
            age+=CombatSkillClock.Delta;
        }
        if(!ReleasedSkillValid(source,generation))
        {
            if(effect!=null)effect.CancelBearRoar();
            yield break;
        }
        source.traitActivations++;
        RecordSkillEvent(source,source.skillId+(ending?"_king_roar_end":"_king_roar_start"),
            hit.Count,dealt);
    }

    private float ApplyBearKingRoarWave(Unit source,Vector3 center,float reach,float damage,
        bool ending,HashSet<Unit> hit)
    {
        float dealt=0f;
        for(int index=0;index<units.Count;index++)
        {
            Unit enemy=units[index];
            if(enemy.team==source.team||!IsCombatActive(enemy)||hit.Contains(enemy)||
               Vector3.Distance(center,Flat(enemy.model.transform.position))>reach)
                continue;
            hit.Add(enemy);
            float applied=ApplyDamageComponents(source,enemy,damage,true,false,false,true,
                0f,0f,1f,false,false,false,0f,skillImpact:true);
            dealt+=applied;source.skillDamage+=applied;source.skillHits++;
            if(!IsCombatActive(enemy))continue;
            if(ending)
            {
                CombatStatusEffect knockdown=enemy.combatStatuses.ApplyTimed(
                    CombatStatusKind.Knockdown,HostileStatusDuration(enemy,
                        BearCombatRules.KingRoarEndKnockdownDuration),source);
                if(knockdown.remaining>0f)enemy.spriteAnimation?.PlayKnockdown(knockdown.remaining);
            }
            else
                enemy.combatStatuses.ApplyTimed(CombatStatusKind.AttackSpeedDown,
                    HostileStatusDuration(enemy,BearCombatRules.KingRoarIntimidationDuration),
                    source,BearCombatRules.KingRoarAttackSpeedSlow);
            SpriteRenderer renderer=enemy.spriteAnimation==null?null:
                enemy.spriteAnimation.GetComponent<SpriteRenderer>();
            PixelCombatEffect.PlayBearRoarHit(enemy.spriteAnimation==null?
                enemy.model.transform:enemy.spriteAnimation.transform,renderer,ending);
            enemy.reaction?.PlayTintHit(new Color(.88f,.96f,1f));
            enemy.spriteAnimation?.PlayImpactRecoil(enemy.model.transform.position-center,
                ending?.1f:.055f);
        }
        return dealt;
    }

    private bool BeginThreeSidedHunt(Unit unit,SkillMasterRow skill)
    {
        if(UsesWolfStampede(unit))return BeginWolfStampede(unit,skill);
        return BeginThreeSidedHuntBody(unit,skill,true);
    }

    private bool BeginThreeSidedHuntBody(Unit unit,SkillMasterRow skill,bool accountCast)
    {
        Unit target=unit.target;
        if(!IsCombatActive(target))return false;
        Vector3 start=Flat(unit.model.transform.position);
        Vector3 targetPosition=Flat(target.model.transform.position);
        float range=TileSize*Mathf.Max(1f,skill.castRangeTiles)+
                    unit.collisionRadius+target.collisionRadius;
        if(!IsWithinCommittedSkillReach(unit,target,range))return false;
        Vector3 forward=targetPosition-start;
        if(forward.sqrMagnitude<0.001f)forward=Flat(unit.model.transform.forward);
        if(forward.sqrMagnitude<0.001f)forward=Vector3.forward;
        if(!TryResolveShadowSlashLanding(
               unit,target,start,forward.normalized,out Vector3 landing))
        {
            unit.skillTimer=0.4f;
            return false;
        }

        unit.wolfHuntPending=true;
        unit.wolfHuntTarget=target;
        unit.wolfHuntLanding=landing;
        unit.wolfHuntDirection=forward.normalized;
        unit.wolfHuntDamageMultiplier=unit.skillTraitDamageMultiplier;
        if(accountCast)
        {
            unit.skillTimer=unit.skillCooldownDuration;
            unit.skillUses++;
        }
        bool spectralPack=MonsterTraitRuntime.Has(
            unit.activeTraitIds,WolfCombatRules.CelestialSpectralPackTraitId);
        unit.attackMovementLockTimer=Mathf.Max(
            unit.attackMovementLockTimer,
            spectralPack?WolfCombatRules.SpectralCastLockDuration:0.72f);
        unit.currentAction="three_sided_hunt_prepare";
        unit.velocity=Vector3.zero;
        StopBeforeAttack(unit);
        
        ClearRoute(unit);
        SetMoving(unit,false);
        if(accountCast)
        {
            ApplyPostSkillItemEffects(unit);
            RecordSkillEvent(unit,skill.id+"_start",0,0f);
        }
        CancelWolfHuntAfterimages(unit);
        if(!mlEpisodeActive&&!spectralPack)
            PrepareWolfHuntAfterimages(unit,target);
        if(unit.spriteAnimation==null)
            StartCombatCoroutine(unit,ResolveThreeSidedHunt(
                unit,target,landing,skill,1f,false,combatGeneration));
        return true;
    }

    private IEnumerator ResolveThreeSidedHunt(
        Unit source,Unit target,Vector3 landing,SkillMasterRow skill,
        float effectScale,bool traitEcho,int generation)
    {
        if(generation!=combatGeneration||!IsCombatActive(source)||
           !IsCombatActive(target)||skill==null)yield break;
        float damageScale=effectScale*
            (traitEcho?1f:source.wolfHuntDamageMultiplier);
        int positionRevision=source.positionRevision;
        source.wolfHuntPending=false;
        source.wolfHuntTarget=null;
        source.wolfHuntDamageMultiplier=1f;
        bool frost=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,WolfCombatRules.SeollangTraitId);
        bool crimson=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,WolfCombatRules.HongaTraitId);
        bool moonShadow=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,WolfCombatRules.WolyeongTraitId);
        bool packRush=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,WolfCombatRules.PackRushTraitId);
        bool spectralPack=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,WolfCombatRules.CelestialSpectralPackTraitId);
        bool eclipsePack=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,WolfCombatRules.EclipsePackTraitId);
        if(spectralPack)
        {
            yield return ResolveWolfCelestialSpectralPack(
                source,target,skill,damageScale,frost,crimson,moonShadow,
                positionRevision,generation);
            yield break;
        }
        if(packRush)
        {
            yield return ResolveWolfPackRush(
                source,target,landing,skill,damageScale,frost,crimson,moonShadow,
                positionRevision,generation);
            yield break;
        }
        if(!traitEcho)
        {
            PlayWolfSound(source,WolfSound.Dash,source.model.transform.position);
            Vector3 dashStart=Flat(source.model.transform.position);
            Vector3 targetPosition=Flat(target.model.transform.position);
            Vector3 forward=targetPosition-dashStart;
            if(forward.sqrMagnitude<0.001f)forward=Flat(source.model.transform.forward);
            if(forward.sqrMagnitude<0.001f)forward=Vector3.forward;
            if(TryResolveShadowSlashLanding(
                   source,target,dashStart,forward.normalized,out Vector3 trackedLanding))
                landing=trackedLanding;
            landing=ResolveFreePosition(landing,source.collisionRadius);

            SpriteRenderer sourceRenderer=source.spriteAnimation==null
                ?null:source.spriteAnimation.GetComponent<SpriteRenderer>();
            if(sourceRenderer!=null)
                PixelCombatEffect.PlayWolfHuntAfterimage(
                    sourceRenderer,sourceRenderer.transform.position,
                    sourceRenderer.transform.position,
                    moonShadow
                        ?new Color(0.72f,0.42f,1f,0.78f)
                        :new Color(0.55f,0.96f,1f,0.68f),
                    WolfCombatRules.AfterimageDuration);

            float elapsed=0f;
            while(elapsed<WolfCombatRules.HuntDashDuration)
            {
                if(generation!=combatGeneration||!IsCombatActive(source)||
                   !IsCombatActive(target)||source.positionRevision!=positionRevision)
                    yield break;
                elapsed+=CombatSkillClock.Delta*CombatStatFormula.CombatAnimationRate;
                float progress=Mathf.Clamp01(elapsed/WolfCombatRules.HuntDashDuration);
                Vector3 ground=Vector3.Lerp(
                    dashStart,landing,1f-Mathf.Pow(1f-progress,3f));
                source.model.transform.position=ground+Vector3.up*source.visualHeightOffset;
                source.ring.transform.position=ground+Vector3.up*0.025f;
                RotateUnit(source,landing-dashStart,CombatSkillClock.Delta*2f);
                yield return null;
            }
            source.model.transform.position=landing+Vector3.up*source.visualHeightOffset;
            source.ring.transform.position=landing+Vector3.up*0.025f;
            source.lastGroundPosition=landing;
            source.currentTile=NearestGridCoordinate(landing);
            if(generation==combatGeneration&&source.positionRevision==positionRevision&&IsCombatActive(source))
                BeginSkillInertia(source,landing-dashStart,WolfCombatRules.HuntDashDuration);
        }
        PixelWolfHuntAfterimage[] ambush=traitEcho?null:source.wolfHuntAfterimages;
        int hits=0,afterimageHits=0;
        float dealt=0f;
        for(int hit=0;hit<WolfCombatRules.HitCount;hit++)
        {
            if(generation!=combatGeneration||!IsCombatActive(source)||
               !IsCombatActive(target)||source.positionRevision!=positionRevision)break;
            bool finalHit=hit==WolfCombatRules.HitCount-1;
            float missingHealth=Mathf.Max(0f,target.maxHp-target.hp);
            float raw=WolfCombatRules.HitDamage(
                source.damage,skill.damageMultiplier,missingHealth,finalHit,crimson)*
                damageScale;
            Vector3 attackDirection=Flat(target.model.transform.position-source.model.transform.position);
            if(hit>0&&ambush!=null&&ambush[hit-1]!=null)
                attackDirection=ambush[hit-1].ContactAmbush(finalHit);
            EmitWolfHuntStrike(source,target,hit,frost,crimson,attackDirection);
            PlayWolfSound(source,WolfSound.Hit,target.model.transform.position,finalHit?1.1f:1f);
            dealt+=ApplySkillDamage(source,target,raw,false);
            if(frost&&IsCombatActive(target))
                target.reaction?.PlayTintHit(new Color(0.48f,0.88f,1f));
            hits++;
            if(frost&&IsCombatActive(target))
                ApplyStackingFrost(source,target,
                    WolfCombatRules.FrostDuration,
                    WolfCombatRules.FrostStacksToFreeze,
                    WolfCombatRules.FreezeDuration);
            if(moonShadow&&hit>0)
            {
                afterimageHits++;
                source.combatStatuses.ApplyShield(
                    WolfCombatRules.AfterimageShieldDuration,
                    WolfCombatRules.AfterimageShield(source.maxHp,afterimageHits),
                    source);
                PlayTraitBurst(source,new Color(0.72f,0.52f,1f),false);
            }
            if(finalHit&&crimson&&!IsCombatActive(target))
                source.skillTimer*=WolfCombatRules.CrimsonKillCooldownMultiplier;
            if(!finalHit)
            {
                if(ambush!=null&&ambush[hit]!=null)
                {
                    Vector3 destination=target.model.transform.position+
                        (source.spriteAnimation.transform.position-source.model.transform.position);
                    ambush[hit].LaunchAmbush(destination,
                        Flat(source.model.transform.position-target.model.transform.position).magnitude);
                    PlayWolfSound(source,WolfSound.Dash,ambush[hit].transform.position,.7f);
                }
                yield return SkillWait(source,WolfCombatRules.HitInterval);
            }
        }

        if(ambush!=null)
        {
            for(int i=Mathf.Max(0,hits-1);i<ambush.Length;i++)if(ambush[i]!=null)ambush[i].Cancel();
            if(!eclipsePack&&source.wolfHuntAfterimages==ambush)source.wolfHuntAfterimages=null;
        }

        if(!traitEcho&&hits>0&&MonsterTraitRuntime.Has(
               source.activeTraitIds,WolfCombatRules.NukguTraitId)&&
           IsCombatActive(target))
        {
            source.wolfChaseTarget=target;
            source.wolfChaseTimer=GateHaetaeBenefit(source,WolfCombatRules.ChaseDuration);
            source.wolfChaseEnhanced=false;
            PlayTraitBurst(source,new Color(0.34f,1f,0.68f),false);
            source.traitActivations++;
        }
        if(eclipsePack&&hits>0&&IsCombatActive(source))
        {
            StartWolfEclipsePack(source);
            source.traitActivations++;
        }
        if(!traitEcho&&hits>0&&(frost||crimson||moonShadow))
            source.traitActivations++;
        if(!traitEcho&&IsCombatActive(source)&&
            source.positionRevision==positionRevision)
        {
            source.velocity=Vector3.zero;
            ClearRoute(source);
            if(IsCombatActive(target))SetTarget(source,target);
        }
        source.skillHits+=hits;
        source.skillDamage+=dealt;
        source.currentAction="three_sided_hunt";
        RecordSkillEvent(
            source,skill.id+(traitEcho?"_echo":""),hits,dealt);
    }

    private IEnumerator ResolveWolfPackRush(
        Unit source,Unit primaryTarget,Vector3 landing,SkillMasterRow skill,float damageScale,
        bool frost,bool crimson,bool moonShadow,int positionRevision,int generation)
    {
        if(!IsCombatActive(source))yield break;
        Vector3 origin=Flat(source.model.transform.position);
        Vector3 forward=source.wolfHuntDirection;
        Vector3 side=Vector3.Cross(Vector3.up,forward)*TileSize;
        Vector3[] starts={origin,origin+side,origin-side};
        float[] lengths=new float[3];
        for(int i=0;i<3;i++)
            lengths[i]=WolfCombatRules.RushDistanceToBoundary(starts[i],forward,combatBounds);
        float length=Mathf.Max(lengths[0],Mathf.Max(lengths[1],lengths[2]));
        float speed=TileSize*WolfCombatRules.RushSpeedTiles;
        landing=ResolveFreePosition(landing,source.collisionRadius);
        float bodyDistance=Mathf.Max(.01f,Vector3.Distance(origin,landing));
        length=Mathf.Max(length,bodyDistance);
        Vector3 visualOffset=source.spriteAnimation==null?Vector3.zero:
            source.spriteAnimation.transform.position-source.model.transform.position;
        var ghosts=source.wolfHuntAfterimages;
        if(ghosts!=null)
            foreach(var ghost in ghosts)if(ghost!=null)ghost.LaunchRush(forward);
        PlayWolfSound(source,WolfSound.Rush,source.model.transform.position);
        source.attackMovementLockTimer=Mathf.Max(source.attackMovementLockTimer,length/speed+.05f);
        var victims=new HashSet<Unit>();
        float traveled=0f,nextTrail=0f,dealt=0f;
        int hits=0;
        bool completed=false,shieldGranted=false,bodyLanded=false;
        try
        {
            while(traveled<length)
            {
                if(generation!=combatGeneration||battleEnding||!IsCombatActive(source)||source.hp<=0f||
                   source.positionRevision!=positionRevision)yield break;
                float previous=traveled;
                traveled=Mathf.Min(length,traveled+speed*CombatSkillClock.Delta*CombatStatFormula.CombatAnimationRate);
                if(!bodyLanded)
                {
                    Vector3 ground=Vector3.Lerp(origin,landing,Mathf.Clamp01(traveled/bodyDistance));
                    source.model.transform.position=ground+Vector3.up*source.visualHeightOffset;
                    source.ring.transform.position=ground+Vector3.up*.025f;
                    source.lastGroundPosition=ground;
                    source.currentTile=NearestGridCoordinate(ground);
                    if(traveled>=bodyDistance)
                    {
                        bodyLanded=true;
                        BeginSkillInertia(source,landing-origin,bodyDistance/speed);
                    }
                }
                if(traveled<=bodyDistance+speed*CombatSkillClock.Delta*CombatStatFormula.CombatAnimationRate)
                    RotateUnit(source,forward,CombatSkillClock.Delta*2f);
                if(ghosts!=null)
                    for(int i=0;i<ghosts.Length;i++)
                    {
                        var ghost=ghosts[i];if(ghost==null)continue;
                        ghost.transform.position=starts[i]+forward*Mathf.Min(traveled,lengths[i])+
                            Vector3.up*source.visualHeightOffset+visualOffset;
                        var renderer=ghost.GetComponent<SpriteRenderer>();
                        if(i==0)renderer.enabled=traveled>=bodyDistance;
                        if(traveled>=nextTrail&&traveled<=lengths[i]&&renderer.enabled)
                            ghost.EmitRushTrail();
                    }
                if(traveled>=nextTrail)nextTrail=traveled+speed*.045f;

                for(int i=0;i<units.Count;i++)
                {
                    if(!IsCombatActive(source)||source.hp<=0f||
                       source.positionRevision!=positionRevision)yield break;
                    Unit enemy=units[i];
                    if(!IsCombatActive(enemy)||enemy.team==source.team||victims.Contains(enemy)||
                       !WolfCombatRules.IsInsideRushSweep(Flat(enemy.model.transform.position),
                           origin,forward,previous,traveled,TileSize,enemy.collisionRadius))continue;
                    victims.Add(enemy);
                    EmitWolfHuntStrike(source,enemy,2,frost,crimson,forward);
                    PlayWolfSound(source,WolfSound.RushHit,enemy.model.transform.position);
                    dealt+=ApplySkillDamage(source,enemy,WolfCombatRules.RushDamage(
                        source.damage,Mathf.Max(0f,enemy.maxHp-enemy.hp),crimson)*damageScale,false);
                    hits++;
                    if(frost&&IsCombatActive(enemy))
                        ApplyStackingFrost(source,enemy,WolfCombatRules.FrostDuration,
                            WolfCombatRules.FrostStacksToFreeze,WolfCombatRules.FreezeDuration);
                    if(crimson&&enemy==primaryTarget&&!IsCombatActive(enemy))
                        source.skillTimer*=WolfCombatRules.CrimsonKillCooldownMultiplier;
                    if(moonShadow&&!shieldGranted)
                    {
                        shieldGranted=true;
                        source.combatStatuses.ApplyShield(WolfCombatRules.AfterimageShieldDuration,
                            WolfCombatRules.AfterimageShield(source.maxHp,2),source);
                        PlayTraitBurst(source,new Color(.72f,.52f,1f),true);
                    }
                }
                yield return null;
            }
            if(ghosts!=null)
                foreach(var ghost in ghosts)if(ghost!=null)ghost.FinishRush();
            completed=true;
        }
        finally
        {
            if(!completed&&ghosts!=null)
                foreach(var ghost in ghosts)if(ghost!=null)ghost.Cancel();
            if(source.wolfHuntAfterimages==ghosts)source.wolfHuntAfterimages=null;
            source.skillHits+=hits;
            source.skillDamage+=dealt;
            RecordSkillEvent(source,skill.id+"_pack_rush",hits,dealt);
        }
        if(hits>0)
        {
            source.traitActivations++;
            if(frost||crimson||moonShadow)source.traitActivations++;
        }
        if(IsCombatActive(primaryTarget))
        {
            SetTarget(source,primaryTarget);
            if(MonsterTraitRuntime.Has(source.activeTraitIds,WolfCombatRules.NukguTraitId))
            {
                source.wolfChaseTarget=primaryTarget;
                source.wolfChaseTimer=GateHaetaeBenefit(source,WolfCombatRules.ChaseDuration);
                source.wolfChaseEnhanced=false;
                PlayTraitBurst(source,new Color(.34f,1f,.68f),false);
            }
        }
        source.currentAction="wolf_pack_rush";
        source.velocity=Vector3.zero;
        ClearRoute(source);
    }

    private IEnumerator ResolveWolfCelestialSpectralPack(
        Unit source,Unit primaryTarget,SkillMasterRow skill,float damageScale,
        bool frost,bool crimson,bool moonShadow,int positionRevision,int generation)
    {
        if(!IsCombatActive(source)||!IsCombatActive(primaryTarget))yield break;
        bool previousControlImmunity=source.combatStatuses.ControlImmune;
        source.combatStatuses.ControlImmune=true;
        var ghosts=new PixelWolfHuntAfterimage[WolfCombatRules.SpectralSpiritCount];
        source.wolfHuntAfterimages=ghosts;
        Func<bool> valid=()=>this!=null&&generation==combatGeneration&&!battleEnding&&
            IsCombatActive(source)&&source.hp>0f&&source.positionRevision==positionRevision;
        int hits=0;
        float dealt=0f;
        bool completed=false;
        try
        {
            SpriteRenderer sourceRenderer=source.spriteAnimation==null
                ?null:source.spriteAnimation.GetComponent<SpriteRenderer>();
            SpriteRenderer targetRenderer=primaryTarget.spriteAnimation==null
                ?null:primaryTarget.spriteAnimation.GetComponent<SpriteRenderer>();
            Vector3 origin=Flat(source.model.transform.position);
            Vector3 center=Flat(primaryTarget.model.transform.position);
            Vector3 radial=(origin-center).normalized;
            if(radial.sqrMagnitude<.001f)radial=Vector3.back;
            Vector3 visualOffset=Vector3.up*source.visualHeightOffset+(sourceRenderer==null
                ?Vector3.zero:sourceRenderer.transform.position-source.model.transform.position);
            var offsets=new Vector3[ghosts.Length];
            float radius=TileSize*WolfCombatRules.SpectralFormationRadiusTiles;
            for(int i=0;i<offsets.Length;i++)
                offsets[i]=Quaternion.AngleAxis(i*360f/offsets.Length,Vector3.up)*radial*radius;
            if(moonShadow)
                source.combatStatuses.ApplyShield(WolfCombatRules.AfterimageShieldDuration,
                    WolfCombatRules.AfterimageShield(source.maxHp,2),source);

            // One shared clock keeps birth order and the simultaneous release stable at any frame rate.
            float elapsed=0f;
            float formation=ghosts.Length*WolfCombatRules.SpectralSpiritInterval;
            float windup=formation+WolfCombatRules.SpectralReadyDuration;
            int spawned=0;
            PlayWolfSound(source,WolfSound.Formation,center);
            while(elapsed<windup)
            {
                if(!valid()||!IsCombatActive(primaryTarget))yield break;
                center=Flat(primaryTarget.model.transform.position);
                while(spawned<ghosts.Length&&elapsed>=spawned*WolfCombatRules.SpectralSpiritInterval)
                {
                    int i=spawned++;
                    if(sourceRenderer==null||mlEpisodeActive)continue;
                    var renderer=PixelCombatEffect.PlayWolfSpectralSpirit(sourceRenderer,
                        center+offsets[i]+visualOffset,center+visualOffset,i,
                        source.spriteAnimation.GetSkillAttackFrame(0));
                    var ghost=renderer.GetComponent<PixelWolfHuntAfterimage>();
                    ghost.PrepareAmbush(targetRenderer,valid,
                        source.spriteAnimation.GetSkillAttackFrame(2),source.spriteAnimation);
                    ghosts[i]=ghost;
                }
                for(int i=0;i<spawned;i++)
                {
                    if(ghosts[i]==null)continue;
                    float reveal=Mathf.Clamp01((elapsed-i*WolfCombatRules.SpectralSpiritInterval)/
                        WolfCombatRules.SpectralSpiritInterval);
                    ghosts[i].transform.position=center+offsets[i]*(1f+.1f*(1f-reveal))+visualOffset;
                    ghosts[i].SetPreparationGlow(reveal,Mathf.Clamp01((elapsed-formation)/
                        WolfCombatRules.SpectralReadyDuration));
                }
                elapsed+=CombatSkillClock.Delta*CombatStatFormula.CombatAnimationRate;
                yield return null;
            }
            if(!valid()||!IsCombatActive(primaryTarget))yield break;
            Vector3 forward=-radial;
            source.spriteAnimation?.HoldSkillAttackHitFrame(WolfCombatRules.SpectralSpiritTravelDuration+
                WolfCombatRules.SpectralContactHoldDuration+WolfCombatRules.SpectralExitDuration);
            foreach(var ghost in ghosts)
                if(ghost!=null)ghost.LaunchRush(center+visualOffset-ghost.transform.position);
            PlayWolfSound(source,WolfSound.Dash,center);
            elapsed=0f;
            while(elapsed<WolfCombatRules.SpectralSpiritTravelDuration)
            {
                if(!valid()||!IsCombatActive(primaryTarget))yield break;
                center=Flat(primaryTarget.model.transform.position);
                elapsed+=CombatSkillClock.Delta*CombatStatFormula.CombatAnimationRate;
                float progress=Mathf.Clamp01(elapsed/WolfCombatRules.SpectralSpiritTravelDuration);
                Vector3 ground=Vector3.Lerp(origin,center,progress);
                source.model.transform.position=ground+Vector3.up*source.visualHeightOffset;
                source.ring.transform.position=ground+Vector3.up*.025f;
                source.lastGroundPosition=ground;
                source.currentTile=NearestGridCoordinate(ground);
                RotateUnit(source,forward,CombatSkillClock.Delta*4f);
                for(int i=0;i<ghosts.Length;i++)
                {
                    if(ghosts[i]==null)continue;
                    ghosts[i].transform.position=center+offsets[i]*(1f-progress)+visualOffset;
                }
                if(progress<1f)yield return null;
            }
            Vector3 landing;
            if(!TryResolveShadowSlashLanding(source,primaryTarget,origin,forward,out landing))
                landing=ResolveFreePosition(center+forward*(source.collisionRadius+
                    primaryTarget.collisionRadius+.5f),source.collisionRadius);
            // All nine hits resolve at contact; only the body hit ignores defense.
            PlayWolfSound(source,WolfSound.SpectralHit,center);
            if(!mlEpisodeActive)
            {
                PixelCombatEffect.PlayWolfSpectralImpact(
                    targetRenderer==null?primaryTarget.model.transform:targetRenderer.transform,
                    targetRenderer??sourceRenderer,crimson);
                primaryTarget.reaction?.PlayTintHit(new Color(.65f,.8f,1f));
                primaryTarget.spriteAnimation?.PlayImpactRecoil(forward,.09f);
            }
            for(int i=0;i<ghosts.Length&&IsCombatActive(primaryTarget)&&valid();i++)
            {
                dealt+=ApplySkillDamage(source,primaryTarget,
                    WolfCombatRules.SpectralSpiritDamage(source.damage)*damageScale,false);
                hits++;
                if(frost&&WolfCombatRules.SpectralSpiritAddsFrost(i)&&IsCombatActive(primaryTarget))
                    ApplyStackingFrost(source,primaryTarget,WolfCombatRules.FrostDuration,
                        WolfCombatRules.FrostStacksToFreeze,WolfCombatRules.FreezeDuration);
            }
            if(IsCombatActive(primaryTarget)&&valid())
            {
                dealt+=ApplySkillDamage(source,primaryTarget,new SkillDamageFormulaResult(
                    WolfCombatRules.SpectralExecutionDamage(source.damage,
                        Mathf.Max(0f,primaryTarget.maxHp-primaryTarget.hp),crimson)*damageScale,
                    0f,WolfCombatRules.SpectralExecutionDefenseIgnoreRatio),false);
                hits++;
            }
            if(crimson&&hits>0&&!primaryTarget.alive)
                source.skillTimer*=WolfCombatRules.CrimsonKillCooldownMultiplier;
            float exitDistance=Vector3.Distance(center,landing);
            elapsed=0f;
            while(elapsed<WolfCombatRules.SpectralContactHoldDuration+WolfCombatRules.SpectralExitDuration)
            {
                if(!valid())yield break;
                elapsed+=CombatSkillClock.Delta*CombatStatFormula.CombatAnimationRate;
                float progress=Mathf.Clamp01((elapsed-WolfCombatRules.SpectralContactHoldDuration)/
                    WolfCombatRules.SpectralExitDuration);
                Vector3 ground=Vector3.Lerp(center,landing,progress);
                source.model.transform.position=ground+Vector3.up*source.visualHeightOffset;
                source.ring.transform.position=ground+Vector3.up*.025f;
                source.lastGroundPosition=ground;
                source.currentTile=NearestGridCoordinate(ground);
                for(int i=0;i<ghosts.Length;i++)
                    if(ghosts[i]!=null)ghosts[i].transform.position=
                        center-offsets[i].normalized*exitDistance*progress+visualOffset;
                yield return null;
            }
            foreach(var ghost in ghosts)if(ghost!=null)ghost.FinishRush();
            completed=true;
            if(IsCombatActive(primaryTarget))
            {
                SetTarget(source,primaryTarget);
                if(MonsterTraitRuntime.Has(source.activeTraitIds,WolfCombatRules.NukguTraitId))
                {
                    source.wolfChaseTarget=primaryTarget;
                    source.wolfChaseTimer=GateHaetaeBenefit(source,WolfCombatRules.EnhancedChaseDuration);
                    source.wolfChaseEnhanced=true;
                }
            }
            source.currentAction="wolf_celestial_spectral_pack";
            source.velocity=Vector3.zero;
            ClearRoute(source);
            BeginSkillInertia(source,landing-center,WolfCombatRules.SpectralExitDuration);
        }
        finally
        {
            if(!completed)
            {
                foreach(var ghost in ghosts)if(ghost!=null)ghost.Cancel();
                if(valid())source.spriteAnimation?.InterruptCurrentAction(true);
            }
            if(source.wolfHuntAfterimages==ghosts)source.wolfHuntAfterimages=null;
            source.combatStatuses.ControlImmune=source.alive&&previousControlImmunity;
            source.skillHits+=hits;
            source.skillDamage+=dealt;
            if(hits>0)source.traitActivations+=1+(frost||crimson||moonShadow?1:0);
            RecordSkillEvent(source,skill.id+"_celestial_spectral_pack",hits,dealt);
        }
    }

    private void StartWolfEclipsePack(Unit source)
    {
        if(!IsCombatActive(source))return;
        var retained=source.wolfHuntAfterimages;
        source.wolfHuntAfterimages=null;
        FinishWolfEclipsePack(source);
        source.wolfEclipseRevision++;
        source.wolfEclipseTimer=WolfCombatRules.EclipseDuration;
        source.wolfEclipseLeft=SpawnWolfEclipseCompanion(source,-1,
            retained!=null&&retained.Length>0?retained[0]:null);
        source.wolfEclipseRight=SpawnWolfEclipseCompanion(source,1,
            retained!=null&&retained.Length>1?retained[1]:null);
        PlayWolfSound(source,WolfSound.Companion,source.model.transform.position);
    }

    private Vector3 WolfEclipseFollowPosition(Unit source,int side)
    {
        Vector3 forward=IsCombatActive(source.target)
            ?Flat(source.target.model.transform.position-source.model.transform.position)
            :Flat(source.model.transform.forward);
        if(forward.sqrMagnitude<.001f)forward=Vector3.forward;
        forward.Normalize();
        return source.spriteAnimation.transform.position+
            (Vector3.Cross(Vector3.up,forward)*side-forward*.65f)*
            (TileSize*WolfCombatRules.EclipseFollowDistanceTiles);
    }

    private PixelWolfHuntAfterimage SpawnWolfEclipseCompanion(
        Unit source,int side,PixelWolfHuntAfterimage retained)
    {
        if(mlEpisodeActive||source.spriteAnimation==null)return null;
        var renderer=source.spriteAnimation.GetComponent<SpriteRenderer>();
        Vector3 position=WolfEclipseFollowPosition(source,side);
        Color tint=side<0?new Color(.48f,.48f,1f,.68f):new Color(.65f,.4f,1f,.68f);
        var ghost=retained!=null?retained.GetComponent<SpriteRenderer>():
            PixelCombatEffect.PlayWolfHuntAfterimage(renderer,position,position,tint,
            WolfCombatRules.EclipseDuration,side<0?"Eclipse Companion Left":"Eclipse Companion Right",
            0f,source.spriteAnimation.GetIdleFrame(0f));
        if(ghost==null)return null;
        int generation=combatGeneration;
        var companion=ghost.GetComponent<PixelWolfHuntAfterimage>();
        companion.name=side<0?"Eclipse Companion Left":"Eclipse Companion Right";
        companion.PrepareCompanion(renderer,source.spriteAnimation,
            ()=>WolfEclipseFollowPosition(source,side),
            ()=>this!=null&&isActiveAndEnabled&&!battleEnding&&generation==combatGeneration&&
                IsCombatActive(source)&&source.hp>0f,tint);
        return companion;
    }

    private IEnumerator ResolveWolfEclipseFollowup(Unit source,Unit target,int generation)
    {
        int revision=source.wolfEclipseRevision;
        float damage=WolfCombatRules.EclipseCloneDamage(source.damage,
            source.wolfChaseTimer>0f&&source.wolfChaseTarget==target,source.wolfChaseEnhanced);
        for(int hit=0;hit<2;hit++)
        {
            yield return new WaitForSeconds(WolfCombatRules.EclipseHitDelay);
            if(generation!=combatGeneration||battleEnding||!IsCombatActive(source)||
               !IsCombatTargetable(target)||source.wolfEclipseTimer<=0f||
               source.wolfEclipseRevision!=revision)yield break;
            PlayWolfSound(source,WolfSound.Hit,target.model.transform.position,.55f);
            ApplyDamage(source,target,damage,false,false,false,false);
            target.spriteAnimation?.PlayImpactRecoil(
                target.model.transform.position-source.model.transform.position,.065f);
            if(hit==0&&IsCombatActive(target)&&MonsterTraitRuntime.Has(
                   source.activeTraitIds,WolfCombatRules.SeollangTraitId))
                ApplyStackingFrost(source,target,WolfCombatRules.FrostDuration,
                    WolfCombatRules.FrostStacksToFreeze,WolfCombatRules.FreezeDuration);
            source.traitActivations++;
        }
    }

    private static void FinishWolfEclipsePack(Unit source)
    {
        source.wolfEclipseLeft?.FinishCompanion();
        source.wolfEclipseRight?.FinishCompanion();
    }

    private static void DeactivateWolfEclipseClones(Unit source)
    {
        if(source==null)return;
        source.wolfEclipseTimer=0f;
        source.wolfEclipseRevision++;
        source.wolfEclipseLeft?.Cancel();
        source.wolfEclipseRight?.Cancel();
        source.wolfEclipseLeft=null;
        source.wolfEclipseRight=null;
    }

    private void EmitWolfHuntStrike(
        Unit source,Unit target,int hit,bool frost,bool crimsonFang,Vector3 direction=default(Vector3))
    {
        if(!IsCombatActive(source)||!IsCombatActive(target))return;
        if(direction.sqrMagnitude<.0001f)direction=target.model.transform.position-source.model.transform.position;
        SpriteRenderer targetRenderer=target.spriteAnimation==null
            ?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
        bool crimson=crimsonFang&&hit==WolfCombatRules.HitCount-1;
        PixelCombatEffect.PlayWolfHuntImpact(
            target.spriteAnimation==null?target.model.transform:
            target.spriteAnimation.transform,targetRenderer,direction,frost
                ?new Color(.58f,.9f,1f):crimson?new Color(1f,.28f,.18f):Color.white,
            hit==WolfCombatRules.HitCount-1);
        target.spriteAnimation?.PlayImpactRecoil(direction,hit==WolfCombatRules.HitCount-1?.075f:.045f);
        if(crimson)
        {
            target.reaction?.PlayTintHit(new Color(1f,0.12f,0.06f));
            PlayTraitBurst(target,new Color(1f,0.08f,0.03f),true);
        }
    }

    private static void CancelWolfHuntAfterimages(Unit source)
    {
        if(source.wolfHuntAfterimages==null)return;
        foreach(var ghost in source.wolfHuntAfterimages)if(ghost!=null)ghost.Cancel();
        source.wolfHuntAfterimages=null;
    }

    private void PrepareWolfHuntAfterimages(Unit source,Unit target)
    {
        if(source.spriteAnimation==null)return;
        SpriteRenderer sourceRenderer=source.spriteAnimation.GetComponent<SpriteRenderer>();
        if(sourceRenderer==null||sourceRenderer.sprite==null)return;
        Vector3 targetGround=Flat(target.model.transform.position);
        Vector3 casterGround=Flat(source.model.transform.position);
        Vector3 visualOffset=sourceRenderer.transform.position-source.model.transform.position;
        SpriteRenderer targetRenderer=target.spriteAnimation==null
            ?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
        bool moonShadow=MonsterTraitRuntime.Has(source.activeTraitIds,WolfCombatRules.WolyeongTraitId);
        bool rush=MonsterTraitRuntime.Has(source.activeTraitIds,WolfCombatRules.PackRushTraitId);
        Vector3 side=Vector3.Cross(Vector3.up,source.wolfHuntDirection)*TileSize;
        int generation=combatGeneration,revision=source.positionRevision;
        source.wolfHuntAfterimages=new PixelWolfHuntAfterimage[rush?3:2];
        for(int i=0;i<source.wolfHuntAfterimages.Length;i++)
        {
            Vector3 from=rush?casterGround+side*(i==0?0:i==1?1:-1):
                WolfCombatRules.HuntVertex(targetGround,casterGround,i+1);
            Vector3 to=rush?from+source.wolfHuntDirection:targetGround;
            var ghost=PixelCombatEffect.PlayWolfHuntAfterimage(sourceRenderer,
                from+Vector3.up*source.visualHeightOffset+visualOffset,
                to+Vector3.up*source.visualHeightOffset+visualOffset,
                moonShadow?new Color(.8f,.55f,1f):new Color(.6f,.94f,1f),
                WolfCombatRules.HitInterval,(rush?"Wolf Pack Rush ":"Wolf Ambush ")+(i+1),0f,
                source.spriteAnimation.GetSkillAttackFrame(0));
            var ambush=ghost.GetComponent<PixelWolfHuntAfterimage>();
            ambush.PrepareAmbush(targetRenderer,()=>this!=null&&isActiveAndEnabled&&!battleEnding&&
                generation==combatGeneration&&source.positionRevision==revision&&
                IsCombatActive(source)&&source.hp>0f&&(rush||IsCombatActive(target)),
                source.spriteAnimation.GetSkillAttackFrame(2),source.spriteAnimation);
            source.wolfHuntAfterimages[i]=ambush;
            if(rush&&i==0)ghost.enabled=false;
        }
    }

    private static void EmitWolfChaseTrail(Unit source)
    {
        if(source==null||source.spriteAnimation==null)return;
        SpriteRenderer renderer=source.spriteAnimation.GetComponent<SpriteRenderer>();
        if(renderer==null||renderer.sprite==null)return;
        Vector3 end=renderer.transform.position;
        Vector3 forward=Flat(source.model.transform.forward);
        if(forward.sqrMagnitude<0.001f)forward=Vector3.forward;
        PixelCombatEffect.PlayWolfHuntAfterimage(
            renderer,end-forward.normalized*0.38f,end,
            new Color(0.38f,1f,0.78f,0.52f),0.13f);
    }

    private int CountActiveEnemiesInRadius(Team sourceTeam,Vector3 origin,float radius)
    {
        return units.Count(enemy=>IsCombatActive(enemy)&&enemy.team!=sourceTeam&&
            Vector3.Distance(origin,Flat(enemy.model.transform.position))<=radius);
    }

    private bool IsInsideTraitArea(Unit source,Vector3 center,Vector3 point,float radius)
    {
        Vector3 offset=point-center;
        if(MonsterTraitRuntime.Has(source.activeTraitIds,"trait_skill_forward_deploy"))
        {
            Vector3 forward=IsCombatActive(source.target)
                ?Flat(source.target.model.transform.position)-center:Flat(source.model.transform.forward);
            if(forward.sqrMagnitude<0.001f)forward=Vector3.forward;
            forward.Normalize();
            return offset.magnitude<=radius*1.8f&&offset.sqrMagnitude>0.001f&&
                   Vector3.Dot(forward,offset.normalized)>=0.55f;
        }
        return offset.magnitude<=radius;
    }

    private float TraitAreaEffectScale(Unit source,Vector3 center,Vector3 point,float radius)
    {
        if(!MonsterTraitRuntime.Has(source.activeTraitIds,"trait_skill_outer_amplification")||
           radius<=0.001f)return 1f;
        return Vector3.Distance(center,point)<=radius*0.5f?0.7f:1.4f;
    }

    private List<Vector3> TraitSkillCenters(Unit source,Vector3 center,float radius)
    {
        List<Vector3> result=new List<Vector3>{center};
        if(!MonsterTraitRuntime.Has(source.activeTraitIds,"trait_skill_scatter_deploy"))return result;
        result.Clear();
        Vector3 forward=IsCombatActive(source.target)
            ?Flat(source.target.model.transform.position-source.model.transform.position).normalized:
            Flat(source.model.transform.forward).normalized;
        if(forward.sqrMagnitude<0.001f)forward=Vector3.forward;
        Vector3 side=Vector3.Cross(Vector3.up,forward).normalized;
        result.Add(center+forward*radius*0.55f);
        result.Add(center-forward*radius*0.28f+side*radius*0.48f);
        result.Add(center-forward*radius*0.28f-side*radius*0.48f);
        return result;
    }

    private int CountEnemiesInSkillLine(Unit source,Vector3 origin,Vector3 forward,float length)
    {
        int count=0;
        for(int i=0;i<units.Count;i++)
            if(IsEnemyInsideSkillLine(source,units[i],origin,forward,length))count++;
        return count;
    }

    private bool BeginFangLock(Unit unit,SkillMasterRow skill)
    {
        if(UsesSabertoothDevour(unit))return BeginSabertoothDevour(unit,skill);
        Unit victim=unit.target;
        if(!IsCombatActive(victim)||!IsWithinCommittedSkillReach(
               unit,victim,AttackDistance(unit,victim)+TileSize*0.25f))
            return false;

        unit.fangLockTarget=victim;
        unit.fangLockDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="fang_lock";
        unit.velocity=Vector3.zero;
        unit.attackMovementLockTimer=Mathf.Max(
            unit.attackMovementLockTimer,
            Mathf.Max(0.2f,skill.durationSeconds));
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        RotateUnit(unit,victim.model.transform.position-unit.model.transform.position,1f);
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        PlaySabertoothSound(unit,SabertoothSound.Start,unit.model.transform.position);
        if(unit.spriteAnimation==null)
            StartCombatCoroutine(unit,ResolveFangLock(unit,skill,combatGeneration));
        return true;
    }

    private IEnumerator ResolveFangLock(
        Unit source,SkillMasterRow skill,int generation)
    {
        Unit target=source==null?null:source.fangLockTarget;
        if(skill==null||generation!=combatGeneration||
           !IsCombatActive(source)||!IsCombatActive(target))
        {
            FinishFangLock(source,false);
            yield break;
        }

        float duration=Mathf.Max(0.1f,
            skill.statusDurationSeconds>0f
                ?skill.statusDurationSeconds:skill.durationSeconds);
        source.fangLockTimer=duration;
        source.fangLockDamageTakenStart=source.damageTaken;
        source.fangLockBloodReflux=MonsterTraitRuntime.Has(
            source.activeTraitIds,SabertoothCombatRules.BloodRefluxTraitId);
        target.combatStatuses.ApplyTimed(
            CombatStatusKind.Root,
            HostileStatusDuration(target,duration),
            source,
            Mathf.Clamp01(skill.statusValue));

        source.fangLockSilence=ApplyThroatLockSilence(source,target);
        if(source.fangLockSilence!=null)source.fangLockSilence.activeHolds++;

        int cast=source.skillUses;
        int hits=0;
        float totalDamage=0f;
        for(int hit=0;hit<SabertoothCombatRules.HitCount;hit++)
        {
            if(hit>0)yield return SkillWait(source,
                duration*ConcertDurationScale(source)/(SabertoothCombatRules.HitCount-1));
            if(generation!=combatGeneration||
               !IsCombatActive(source)||!IsCombatActive(target)||
               source.skillUses!=cast||source.fangLockTarget!=target||
               source.combatStatuses.Has(CombatStatusKind.Fear))
                break;

            SkillDamageFormulaResult hitDamage=SabertoothCombatRules.DamagePerHit(
                SkillPower(source),skill.damageMultiplier,target.maxHp);
            bool execution=hit==SabertoothCombatRules.HitCount-1&&
                MonsterTraitRuntime.Has(
                    source.activeTraitIds,SabertoothCombatRules.NoxTraitId)&&
                target.hp/Mathf.Max(1f,target.maxHp)<=
                    SabertoothCombatRules.ExecutionHealthThreshold;
            PlaySabertoothSound(source,SabertoothSound.Bite,
                target.model.transform.position,hit==SabertoothCombatRules.HitCount-1?1.1f:.9f);
            float fangScale=execution?SabertoothCombatRules.ExecutionFangEffectScale:1f;
            SpriteRenderer targetRenderer=target.spriteAnimation==null
                ?null
                :target.spriteAnimation.GetComponent<SpriteRenderer>();
            SpriteRenderer sourceRenderer=source.spriteAnimation==null
                ?null
                :source.spriteAnimation.GetComponent<SpriteRenderer>();
            if(target.fangLockDebuffEffect!=null&&
               target.fangLockDebuffEffect.IsFangLockBinding(target.combatStatuses))
                target.fangLockDebuffEffect.PulseFangLockBite(
                    fangScale);
            else PixelCombatEffect.PlaySabertoothFangLock(
                target.spriteAnimation==null
                    ?target.model.transform
                    :target.spriteAnimation.transform,
                targetRenderer,
                sourceRenderer!=null&&sourceRenderer.flipX,
                fangScale);
            float dealt=ApplySkillDamage(
                source,target,
                new SkillDamageFormulaResult(
                    hitDamage.physicalDamage*source.fangLockDamageMultiplier,
                    hitDamage.trueDamage*source.fangLockDamageMultiplier,
                    execution
                        ?SabertoothCombatRules.ExecutionDefenseIgnoreRatio:0f),
                markSabertoothPrey:false);
            totalDamage+=dealt;
            hits++;
            source.skillHits++;
            source.skillDamage+=dealt;
            if(execution)source.traitActivations++;
            ApplySeolaFrostFang(source,target);
            target.spriteAnimation?.PlayImpactRecoil(
                target.model.transform.position-source.model.transform.position,
                hit==SabertoothCombatRules.HitCount-1?0.16f:0.09f);
            CreateSkillPulse(
                target,
                hit==SabertoothCombatRules.HitCount-1
                    ?new Color(1f,0.96f,0.8f)
                    :new Color(0.55f,0.82f,0.92f),
                0.48f+hit*0.08f);
            if(hit==0&&IsCombatActive(target)&&MonsterTraitRuntime.Has(
                   source.activeTraitIds,SabertoothCombatRules.PreyDriveTraitId))
                BeginPreyDrag(source,target);
        }

        if(generation==combatGeneration&&source!=null)
            RecordSkillEvent(source,skill.id,hits,totalDamage);
        if(source.skillUses==cast&&source.fangLockTarget==target)
            FinishFangLock(source,generation==combatGeneration);
    }

    private static bool HasActiveTaunt(Unit unit)=>
        unit.forcedTargetTimer>0f&&IsCombatTargetable(unit.forcedTarget);

    private static bool HasPreyFocus(Unit unit)=>
        (unit.preyFocusTimer>0f||unit.preyFocusPending)&&IsCombatTargetable(unit.preyFocusTarget)&&
        unit.preyFocusTarget.team!=unit.team;

    private static bool PreyActionInProgress(Unit unit)=>
        IsAttackMovementLocked(unit)||unit.fangLockTarget!=null||
        unit.crocodileRollTarget!=null||unit.displacing||unit.leaping||
        unit.shadowSlashing||unit.griffinSkyfalling||unit.monkeyNimbus!=null||unit.giraffeSlamming||
        unit.mammothChargeTarget!=null||unit.preyDraggedBy!=null;

    private void ApplyPreyFocus(Unit unit)
    {
        if(!HasPreyFocus(unit)||HasActiveTaunt(unit)||PreyActionInProgress(unit))return;
        // A long cast still hands off its target once, without extending the focus buff.
        unit.preyFocusPending=false;
        StopTimidRetreat(unit);
        SetTarget(unit,unit.preyFocusTarget);
    }

    private void RallyPreyAttack(Unit source,Unit target)
    {
        if(!IsCombatActive(source)||!IsCombatTargetable(target))return;
        target.combatEffectIcons.Show(
            CombatEffectIconKind.Hunted,SabertoothCombatRules.PreyFocusDuration);
        target.preyMarkFlash=0.3f;
        source.traitActivations++;
        Vector3 center=Flat(target.model.transform.position);
        float radius=TileSize*SabertoothCombatRules.PreyAssistRadiusTiles;
        // Recruitment is a single snapshot, not a continuously expanding aura.
        for(int i=0;i<units.Count;i++)
        {
            Unit ally=units[i];
            if(!IsCombatActive(ally)||ally.team!=source.team||HasActiveTaunt(ally)||
               HasPreyFocus(ally)||
               (Flat(ally.model.transform.position)-center).sqrMagnitude>radius*radius)continue;
            ally.preyFocusTarget=target;
            ally.preyFocusTimer=SabertoothCombatRules.PreyFocusDuration;
            ally.preyFocusPending=true;
            ApplyPreyFocus(ally);
        }
    }

    private static bool PreyDisplacementImmune(Unit unit)=>
        unit.rank3MycokingSummon||unit.mantisMolt!=null||MountainColossusActive(unit)||MantisReaperFlying(unit)||unit.rank3ForceImmuneTimer>0f||(TyrannoExtinctionCharging(unit)||TyrannoMarchProtected(unit)||TyrannoMawProtected(unit))||unit.ninjaCrossActive||
        unit.combatStatuses.RejectHarmfulEffect()||unit.combatStatuses.ControlImmune;

    private void BeginPreyDrag(Unit source,Unit target)
    {
        if(target.preyDraggedBy!=null)return;
        source.preyDragTarget=target;
        source.preyDragRemaining=SabertoothCombatRules.PreyDragDuration;
        source.preyDragRevision=source.positionRevision;
        if(!PreyDisplacementImmune(target))
        {
            InterruptPositionalAction(target);
            target.displacing=false;
            target.preyDraggedBy=source;
            StopBeforeAttack(target);
            source.spriteAnimation?.SetSkillPoseScale(new Vector3(1.04f,0.90f,1f));
        }
        source.preyDragTargetRevision=target.positionRevision;
    }

    private void UpdatePreyDrag(Unit source,float dt)
    {
        Unit target=source.preyDragTarget;
        if(!IsCombatActive(source)||!IsCombatActive(target)||source.fangLockTarget!=target||
           source.positionRevision!=source.preyDragRevision||
           target.positionRevision!=source.preyDragTargetRevision||
           source.combatStatuses.Has(CombatStatusKind.Freeze)||
           source.combatStatuses.Has(CombatStatusKind.Knockdown)||
           source.combatStatuses.Has(CombatStatusKind.Airborne))
        {
            FinishPreyDrag(source,false);
            return;
        }
        float previousProgress=1f-source.preyDragRemaining/SabertoothCombatRules.PreyDragDuration;
        float elapsed=Mathf.Min(Mathf.Max(0f,dt),source.preyDragRemaining);
        source.preyDragRemaining-=elapsed;
        float progress=1f-source.preyDragRemaining/SabertoothCombatRules.PreyDragDuration;
        if(!PreyDisplacementImmune(target)&&target.preyDraggedBy==source)
        {
            // Integrate the eased path so changing the frame rate cannot change the pull distance.
            float distance=TileSize*SabertoothCombatRules.PreyDragDistanceTiles*
                (Mathf.SmoothStep(0f,1f,progress)-Mathf.SmoothStep(0f,1f,previousProgress));
            Vector3 direction=-DeploymentFacing(source.team);
            // Short swept steps keep both bodies together and stop at moving blockers.
            while(distance>0f)
            {
                float step=Mathf.Min(distance,TileSize*0.05f);
                Vector3 movement=direction*step;
                if(!PreyDragStepClear(source,target,movement)||
                   !PreyDragStepClear(target,source,movement))
                {
                    source.preyDragRemaining=0f;
                    break;
                }
                MovePreyBody(source,movement);
                MovePreyBody(target,movement);
                if(!source.preyDragSoundStarted)
                {
                    PlaySabertoothSound(source,SabertoothSound.Drag,target.model.transform.position,.7f);
                    source.preyDragSoundStarted=true;
                }
                distance-=step;
            }
            RotateUnit(source,target.model.transform.position-source.model.transform.position,1f);
        }
        if(source.preyDragRemaining<=0f)FinishPreyDrag(source,true);
    }

    private bool PreyDragStepClear(Unit unit,Unit partner,Vector3 movement)
    {
        Vector3 start=Flat(unit.model.transform.position),end=start+movement;
        if((ResolveFreePosition(end,unit.collisionRadius)-end).sqrMagnitude>0.000001f)
            return false;
        for(int i=0;i<units.Count;i++)
        {
            Unit other=units[i];
            if(other==unit||other==partner||!IsCombatActive(other))continue;
            Vector3 center=Flat(other.model.transform.position);
            float minimum=unit.collisionRadius+other.collisionRadius+UnitMovementClearance;
            float before=Vector3.Distance(start,center);
            if(before<minimum&&Vector3.Distance(end,center)>=before)continue;
            if(WolfCombatRules.DistanceToSegment(center,start,end)<minimum)return false;
        }
        return true;
    }

    private void MovePreyBody(Unit unit,Vector3 movement)
    {
        Vector3 ground=Flat(unit.model.transform.position)+movement;
        unit.model.transform.position=ground+Vector3.up*unit.visualHeightOffset;
        if(unit.ring!=null)unit.ring.transform.position=ground+Vector3.up*0.025f;
        unit.lastGroundPosition=ground;
        unit.currentTile=NearestGridCoordinate(ground);
        unit.hexStepping=false;
        unit.hexStepTarget=unit.currentTile;
        StopBeforeAttack(unit);
    }

    private void FinishPreyDrag(Unit source,bool rally)
    {
        StopSabertoothDragSound(source);
        Unit target=source.preyDragTarget;
        if(target==null)return;
        source.preyDragTarget=null;
        source.preyDragRemaining=0f;
        if(target.preyDraggedBy==source)target.preyDraggedBy=null;
        source.spriteAnimation?.SetSkillPoseScale(Vector3.one);
        if(rally)RallyPreyAttack(source,target);
    }

    private void ApplySeolaFrostFang(Unit source,Unit target)
    {
        if(!IsCombatActive(target)||!MonsterTraitRuntime.Has(
               source.activeTraitIds,SabertoothCombatRules.SeolaTraitId))
            return;
        if(ApplyStackingFrost(source,target,
               SabertoothCombatRules.FrostDuration,
               SabertoothCombatRules.FrostStacksForFreeze,
               SabertoothCombatRules.FreezeDuration))
            source.traitActivations++;
    }

    private CombatStatusEffect ApplyThroatLockSilence(Unit source,Unit target)
    {
        if(!IsCombatActive(target)||!MonsterTraitRuntime.Has(
               source.activeTraitIds,SabertoothCombatRules.ThroatLockTraitId))return null;
        CombatStatusEffect effect=target.combatStatuses.ApplyTimed(
            CombatStatusKind.Silence,SabertoothCombatRules.SilenceAfterReleaseDuration,source);
        if(effect.remaining<=0f||effect.stacks<=0)return null;
        source.traitActivations++;
        return effect;
    }

    private IEnumerator HoldEchoThroatLockSilence(Unit target,CombatStatusEffect silence)
    {
        // Echoes have no caster channel; their actual root is the hold lifetime.
        silence.activeHolds++;
        while(IsCombatActive(target)&&SabertoothCombatRules.HasFangLockDebuff(target.combatStatuses)&&
              target.combatStatuses.Get(CombatStatusKind.Silence)==silence)
            yield return null;
        silence.activeHolds=Mathf.Max(0,silence.activeHolds-1);
    }

    private void FinishFangLock(Unit source,bool grantEndEffects)
    {
        if(source==null)return;
        FinishPreyDrag(source,false);
        if(source.fangLockSilence!=null)
        {
            source.fangLockSilence.activeHolds=Mathf.Max(0,source.fangLockSilence.activeHolds-1);
            source.fangLockSilence=null;
        }
        source.fangLockTarget=null;
        source.fangLockTimer=0f;
        source.fangLockDamageMultiplier=1f;
        source.fangLockBloodReflux=false;
        if(!grantEndEffects||!IsCombatActive(source))return;
        if(MonsterTraitRuntime.Has(
               source.activeTraitIds,SabertoothCombatRules.GeomchiTraitId))
        {
            Heal(source,SkillSupportAmount(source,
                SabertoothCombatRules.PredatoryRecovery(
                    source.damageTaken-source.fangLockDamageTakenStart)));
            source.traitActivations++;
        }
        if(MonsterTraitRuntime.Has(
               source.activeTraitIds,SabertoothCombatRules.TerakanTraitId))
        {
            source.combatStatuses.ApplyShield(
                SabertoothCombatRules.StoneShieldDuration,
                SkillSupportAmount(source,
                    SabertoothCombatRules.StoneShield(CurrentDefense(source))),
                source);
            source.traitActivations++;
        }
    }

    private static bool IsBloodRefluxActive(Unit unit)
    {
        return IsCombatActive(unit)&&unit.hp>0f&&unit.fangLockBloodReflux&&
            IsCombatActive(unit.fangLockTarget)&&unit.fangLockTarget.hp>0f;
    }

    private void ApplyBloodReflux(Unit attacker,Unit holder,float healthLost)
    {
        if(reflectedDamageDepth>0||healthLost<=0f||attacker==null||
           attacker.team==holder.team||!IsBloodRefluxActive(holder))return;
        Unit prey=holder.fangLockTarget;
        if(prey.fangLockDebuffEffect!=null&&
           prey.fangLockDebuffEffect.IsFangLockBinding(prey.combatStatuses))
            prey.fangLockDebuffEffect.PulseFangLockBloodReflux();
        float reflected=ApplyReflectedDamage(holder,prey,
            healthLost*SabertoothCombatRules.BloodRefluxRatio,true);
        if(reflected>0f)
        {
            PlaySabertoothSound(holder,SabertoothSound.Reflux,prey.model.transform.position,.8f);
            holder.traitActivations++;
        }
    }

    private bool IsEnemyInsideSkillLine(
        Unit source,Unit enemy,Vector3 origin,Vector3 forward,float length)
    {
        if(!IsCombatActive(enemy)||enemy.team==source.team||forward.sqrMagnitude<0.001f)return false;
        return IsPointInsideForwardSkillLine(origin,forward,
            Flat(enemy.model.transform.position),length,TileSize*0.48f+enemy.collisionRadius);
    }

    private bool BeginDeathRoll(Unit unit,SkillMasterRow skill)
    {
        if(UsesCrocodileAbyssDive(unit))return BeginCrocodileAbyssDive(unit,skill);
        Unit victim=unit.target;
        if(!IsCombatActive(victim)||victim.griffinSkyfalling)return false;
        float distance=Vector3.Distance(
            Flat(unit.model.transform.position),Flat(victim.model.transform.position));
        bool charge=MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_skill_charge_bite");
        float allowed=charge?TileSize*3f+unit.collisionRadius+victim.collisionRadius:
            AttackDistance(unit,victim)+TileSize*0.35f;
        if(!IsWithinCommittedSkillReach(unit,victim,allowed))return false;
        if(charge&&distance>AttackDistance(unit,victim)+TileSize*0.35f)
        {
            DisplaceUnit(unit,victim.model.transform.position-unit.model.transform.position,
                Mathf.Max(0f,distance-AttackDistance(unit,victim)),false);
            unit.traitActivations++;
        }

        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.crocodileRollTarget=victim;
        unit.crocodileRollDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.currentAction="death_roll_prepare";
        unit.velocity=Vector3.zero;
        
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        RotateUnit(unit,victim.model.transform.position-unit.model.transform.position,1f);
        ApplyPostSkillItemEffects(unit);

        if(MonsterTraitRuntime.Has(unit.activeTraitIds,CrocodileCombatRules.TarvilTraitId)&&
           !victim.combatStatuses.RejectHarmfulEffect())
        {
            victim.crocodileDeathMarkSource=unit;
            victim.crocodileDeathMarkTimer=CrocodileCombatRules.UnderworldMarkDuration;
            PlayTraitBurst(victim,new Color(0.58f,0.12f,0.72f),true);
            unit.traitActivations++;
        }
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,CrocodileCombatRules.AgerTraitId))
        {
            float windup=unit.spriteAnimation==null?0f:
                unit.spriteAnimation.SkillAttackHitTime/
                Mathf.Max(0.01f,SpriteSkillAttackPlaybackSpeed(unit));
            bool absoluteJaw=MonsterTraitRuntime.Has(
                unit.activeTraitIds,CrocodileCombatRules.AbsoluteJawTraitId);
            float rollDuration=MonsterTraitRuntime.Has(unit.activeTraitIds,CrocodileCombatRules.PreyCannonTraitId)
                ?CrocodileCombatRules.PreyCannonLaunchTime:absoluteJaw
                    ?CrocodileCombatRules.AbsoluteJawDuration:
                    CrocodileCombatRules.RollDuration;
            unit.crocodileToughHideTimer=GateHaetaeBenefit(unit,windup+rollDuration);
            PlayTraitBurst(unit,new Color(0.48f,0.66f,0.42f),true);
            unit.traitActivations++;
        }
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,CrocodileCombatRules.KrogalTraitId))
        {
            unit.crocodileShield=GateHaetaeBenefit(unit,unit.crocodileShield+unit.maxHp*CrocodileCombatRules.GuardianShieldRatio*GuardianShieldMultiplier(unit),CombatBenefitKind.Shield);
            unit.crocodileShieldTimer=Mathf.Max(
                unit.crocodileShieldTimer,CrocodileCombatRules.GuardianShieldDuration);
            unit.traitActivations++;
            PlayTraitBurst(unit,new Color(0.78f,0.96f,1f),true);
        }
        return true;
    }

    private IEnumerator ResolveDeathRoll(Unit source,SkillMasterRow skill,int generation)
    {
        Unit victim=source.crocodileRollTarget;
        source.crocodileRollTarget=null;
        if((battleEnding||generation!=combatGeneration)||!IsCombatActive(source)||
           !IsCombatActive(victim)||skill==null)yield break;

        bool crushing=MonsterTraitRuntime.Has(
            source.activeTraitIds,"trait_skill_crushing_bite");
        bool instant=MonsterTraitRuntime.Has(
            source.activeTraitIds,"trait_skill_instant_bite");
        bool crushingRoll=MonsterTraitRuntime.Has(
            source.activeTraitIds,CrocodileCombatRules.CrushingRollTraitId);
        bool absoluteJaw=MonsterTraitRuntime.Has(
            source.activeTraitIds,CrocodileCombatRules.AbsoluteJawTraitId);
        bool preyCannon=MonsterTraitRuntime.Has(
            source.activeTraitIds,CrocodileCombatRules.PreyCannonTraitId);
        bool transcended=HasFamilyTranscendence(source);
        if(transcended)
        {
            source.traitActivations++;
            PlayFamilyTranscendenceFeedback(source,"crocodile");
        }
        float duration=preyCannon?CrocodileCombatRules.PreyCannonLaunchTime:
            crushingRoll?CrocodileCombatRules.RollDuration:
            absoluteJaw?CrocodileCombatRules.AbsoluteJawDuration:
            instant?0f:crushing?1.6f:
            Mathf.Max(0f,skill.durationSeconds);
        float scale=(crushing||instant)?0.8f:1f;
        if(crushing||instant)source.traitActivations++;
        source.crocodileBiteLockTimer=duration/CombatStatFormula.CombatAnimationRate;
        source.attackMovementLockTimer=Mathf.Max(source.attackMovementLockTimer,(duration+0.12f)/CombatStatFormula.CombatAnimationRate);
        source.spriteAnimation?.SetDeathRollFrame(true);
        LockDeathRollTarget(source,victim,duration/CombatStatFormula.CombatAnimationRate);

        float totalDealt=0f;
        int hits=0;
        int sweeps=0;
        bool rollSoundPlayed=false;
        PixelCrocodileCrushingSweep crushingSweep=null;
        Action completeCannonCamera=null;
        int totalHitCount=CrocodileCombatRules.HitCount;
        float interval=totalHitCount>1?duration/(totalHitCount-1):0f;
        Unit activeVictim=victim;
        int sourceRevision=source.positionRevision;
        int victimRevision=activeVictim.positionRevision;
        try
        {
        for(int hit=0;hit<totalHitCount;)
        {
            if((battleEnding||generation!=combatGeneration)||!IsCombatActive(source)||
               !IsCombatActive(activeVictim)||source.positionRevision!=sourceRevision||
               activeVictim.positionRevision!=victimRevision)break;
            int phaseHit=hit;
            bool cannonImpact=preyCannon&&phaseHit==CrocodileCombatRules.HitCount-1;
            if(cannonImpact)
            {
                completeCannonCamera=HoldSkillCameraEffect(source);
                UpdateDeathRollPose(source,activeVictim,CrocodileCombatRules.PreyCannonLaunchTime,false);
                ResetDeathRollPose(source);
                ResetDeathRollPose(activeVictim);
                source.crocodileBiteLockTimer=0f;
                activeVictim.crocodileImmobilizedTimer=0f;
                if(BeginCrocodilePreyFlight(source,activeVictim))
                {
                    PlayCrocodileSound(source,CrocodileSound.Throw,activeVictim.model.transform.position);
                    victimRevision=activeVictim.positionRevision;
                    while(!battleEnding&&generation==combatGeneration&&IsCombatActive(activeVictim)&&
                          activeVictim.positionRevision==victimRevision&&activeVictim.displacing)
                        yield return null;
                    if((battleEnding||generation!=combatGeneration)||!IsCombatActive(activeVictim)||
                       activeVictim.positionRevision!=victimRevision)break;
                }
            }
            SpriteRenderer shockwaveSorting=activeVictim.spriteAnimation==null
                ?activeVictim.model.GetComponentInChildren<SpriteRenderer>()
                :activeVictim.spriteAnimation.GetComponent<SpriteRenderer>();
            Vector3 impactCenter=shockwaveSorting==null
                ?Flat(activeVictim.model.transform.position):Flat(shockwaveSorting.bounds.center);
            float missing=Mathf.Max(0f,activeVictim.maxHp-activeVictim.hp);
            bool absoluteImpact=absoluteJaw&&phaseHit==CrocodileCombatRules.HitCount-1;
            PlayCrocodileSound(source,cannonImpact?CrocodileSound.Collision:
                absoluteImpact?CrocodileSound.Jaw:phaseHit==CrocodileCombatRules.HitCount-1
                    ?CrocodileSound.Crush:CrocodileSound.Bite,impactCenter,phaseHit==1?.8f:1f);
            if(transcended&&(cannonImpact||absoluteImpact))
                PlayCrocodileSound(source,CrocodileSound.Resonance,impactCenter);
            float attackRatio=absoluteImpact?(transcended
                ?CrocodileCombatRules.TranscendentAbsoluteJawDamageRatio
                :CrocodileCombatRules.AbsoluteJawFinalDamageRatio):
                DeathRollDamageRatio(phaseHit,skill);
            float raw=(attackRatio*source.damage+
                (phaseHit==CrocodileCombatRules.HitCount-1
                    ?missing*skill.targetMissingHpRatio:0f))*
                source.crocodileRollDamageMultiplier*scale;
            if(absoluteImpact)
            {
                PixelCombatEffect.PlayCrocodileAbsoluteJaw(
                    activeVictim.spriteAnimation==null
                        ?activeVictim.model.transform:
                        activeVictim.spriteAnimation.transform,
                    shockwaveSorting,transcended);
                PlayTraitBurst(activeVictim,transcended?PixelCombatEffect.CrocodileAbyssHighlight:
                    new Color(1f,0.75f,0.3f),true);
                activeVictim.reaction?.PlayTintHit(Color.white);
            }
            if(hit==totalHitCount-1&&!cannonImpact)
            {
                UpdateDeathRollPose(source,activeVictim,1f,false,absoluteJaw:absoluteJaw);
                if(!absoluteJaw)
                    PixelCombatEffect.PlayCrocodileJawCrush(
                        shockwaveSorting==null?activeVictim.model.transform:
                            shockwaveSorting.transform,shockwaveSorting);
                PixelCombatEffect.PlayBeetleHornImpact(
                    shockwaveSorting==null?activeVictim.model.transform:
                        shockwaveSorting.transform,shockwaveSorting);
                combatCameraDirector?.ReportJawCrush();
            }
            // Reserve the landing shake before generic damage feedback requests a weaker one.
            if(cannonImpact)combatCameraDirector?.ReportGroundSlam();
            float dealt=absoluteImpact
                ?ApplySkillDamage(source,activeVictim,
                    new SkillDamageFormulaResult(
                        raw,0f,CrocodileCombatRules.AbsoluteJawDefenseIgnoreRatio),
                    false)
                :ApplySkillDamage(source,activeVictim,raw,false);
            totalDealt+=dealt;hits++;source.skillDamage+=dealt;source.skillHits++;
            totalDealt+=ApplyScatteredDeathRollHit(source,activeVictim,
                attackRatio*source.damage*
                source.crocodileRollDamageMultiplier*scale);
            if(cannonImpact)
            {
                PixelCombatEffect.PlayCrocodilePreyCannonImpact(
                    impactCenter,TileSize*(transcended?CrocodileCombatRules.TranscendentPreyCannonRadiusTiles:
                        CrocodileCombatRules.PreyCannonRadiusTiles),shockwaveSorting,transcended);
                meadowAmbientParticles?.Impact(impactCenter,TileSize*(transcended?
                    CrocodileCombatRules.TranscendentPreyCannonRadiusTiles:CrocodileCombatRules.PreyCannonRadiusTiles),shockwaveSorting);
                if(transcended)PlayTraitBurst(activeVictim,PixelCombatEffect.CrocodileAbyssHighlight,true);
                totalDealt+=ApplyCrocodilePreyCannonSplash(
                    source,activeVictim,impactCenter,
                    source.crocodileRollDamageMultiplier*scale);
                completeCannonCamera?.Invoke();
            }

            int nextHit=hit+1;
            if(nextHit<totalHitCount&&duration>0f&&IsCombatActive(activeVictim))
            {
                float effectDelay=PixelCombatEffect.CrocodileDeathRollLeadTime(
                    interval,1f);
                bool effectPlayed=false;
                float elapsed=0f;
                while(!battleEnding&&elapsed<interval&&generation==combatGeneration&&
                      IsCombatActive(source)&&IsCombatActive(activeVictim)&&
                      source.positionRevision==sourceRevision&&
                      activeVictim.positionRevision==victimRevision)
                {
                    if(!effectPlayed&&elapsed>=effectDelay&&!(absoluteJaw&&hit==1))
                    {
                        effectPlayed=true;
                        PlayCrocodileDeathRollEffect(activeVictim,1f,transcended:transcended);
                    }
                    float phase=hit;
                    float rollProgress=preyCannon?phase*interval+elapsed:(phase+elapsed/interval)/2f;
                    UpdateDeathRollPose(source,activeVictim,rollProgress,false,absoluteJaw:absoluteJaw);
                    if(!rollSoundPlayed&&!crushingRoll&&rollProgress>=.08f&&rollProgress<.43f)
                    {
                        rollSoundPlayed=true;
                        PlayCrocodileSound(source,CrocodileSound.Spin,activeVictim.model.transform.position);
                    }
                    if(crushingRoll)
                    {
                        // Include the interval endpoint, so a long frame cannot skip a sweep.
                        float rollTime=(hit+Mathf.Min((elapsed+CombatSkillClock.Delta*CombatStatFormula.CombatAnimationRate)/interval,1f))*0.5f;
                        UpdateDeathRollPose(source,activeVictim,rollTime,false);
                        if(crushingSweep==null&&sweeps==0&&rollTime>=CrocodileCombatRules.CrushingRollStart)
                            crushingSweep=PixelCrocodileCrushingSweep.Create(
                                Flat(activeVictim.model.transform.position),
                                TileSize*CrocodileCombatRules.CrushingRollRadiusTiles,shockwaveSorting,transcended);
                        if(crushingSweep!=null)crushingSweep.SetProgress(rollTime);
                        while(!battleEnding&&IsCombatActive(source)&&IsCombatActive(activeVictim)&&
                              source.positionRevision==sourceRevision&&activeVictim.positionRevision==victimRevision&&
                              sweeps<CrocodileCombatRules.CrushingRollSweepCount&&
                              rollTime>=CrocodileCombatRules.CrushingRollStart+
                                  CrocodileCombatRules.CrushingRollSpinDuration*(sweeps+1)/2f)
                        {
                            sweeps++;
                            totalDealt+=ApplyCrocodileCrushingRollSweep(source,activeVictim,
                                source.crocodileRollDamageMultiplier*scale,sweeps==CrocodileCombatRules.CrushingRollSweepCount);
                        }
                    }
                    yield return null;
                    elapsed+=CombatSkillClock.Delta*CombatStatFormula.CombatAnimationRate;
                }
            }
            hit=nextHit;
        }
        if(!preyCannon&&duration>0f&&hits==totalHitCount)
        {
            float release=0f;
            while(!battleEnding&&release<0.12f&&generation==combatGeneration&&IsCombatActive(source)&&
                  IsCombatActive(activeVictim)&&source.positionRevision==sourceRevision&&
                  activeVictim.positionRevision==victimRevision)
            {
                UpdateDeathRollPose(source,activeVictim,1f,false,1f-release/0.12f,absoluteJaw);
                yield return null;
                release+=CombatSkillClock.Delta*CombatStatFormula.CombatAnimationRate;
            }
        }
        }
        finally
        {
            completeCannonCamera?.Invoke();
            if(crushingSweep!=null&&!CombatEffectEndFade.IsFading(crushingSweep))Destroy(crushingSweep.gameObject);
            if(source.positionRevision==sourceRevision)
            {
                ResetDeathRollPose(source);
                source.crocodileBiteLockTimer=0f;
            }
            if(activeVictim.positionRevision==victimRevision)
            {
                ResetDeathRollPose(activeVictim);
                activeVictim.crocodileImmobilizedTimer=0f;
            }
        }

        if(preyCannon&&hits>0)source.traitActivations++;
        if(crushingRoll&&sweeps>0)source.traitActivations++;
        if(absoluteJaw&&hits==totalHitCount&&IsCombatActive(source)&&
           source.positionRevision==sourceRevision&&
           activeVictim.positionRevision==victimRevision)
            source.traitActivations++;

        if(totalDealt>0f&&MonsterTraitRuntime.Has(
               source.activeTraitIds,CrocodileCombatRules.KimbulTraitId))
        {
            Heal(source,CrocodileCombatRules.GoldenFeastHealing(totalDealt));
            PlayTraitBurst(source,new Color(1f,0.72f,0.12f),true);
            Transform anchor=source.spriteAnimation==null
                ?source.model.transform:source.spriteAnimation.transform;
            SpriteRenderer renderer=source.spriteAnimation==null
                ?source.model.GetComponentInChildren<SpriteRenderer>()
                :source.spriteAnimation.GetComponent<SpriteRenderer>();
            ParticleSystem aura=PixelCombatEffect.PlayKingpaRoyalAura(
                anchor,renderer,0.9f);
            if(aura!=null)aura.name="Kimbul Golden Feast Aura";
            source.traitActivations++;
        }
        source.crocodileRollDamageMultiplier=1f;
        CreateSkillPulse(source,new Color(0.22f,0.62f,0.16f),0.85f);
        RecordSkillEvent(source,skill.id,hits,totalDealt);
    }

    private IEnumerator PlayCrocodileDeathRollEffect(
        Unit source,Unit target,float playbackSpeed,int generation)
    {
        float hitTime=source.spriteAnimation.SkillAttackHitTime/
                      Mathf.Max(0.01f,playbackSpeed);
        float delay=PixelCombatEffect.CrocodileDeathRollLeadTime(
            hitTime,playbackSpeed);
        if(delay>0f)yield return new WaitForSeconds(delay);
        if(generation!=combatGeneration||!IsCombatActive(source)||
           !IsCombatActive(target))yield break;
        PlayCrocodileDeathRollEffect(target,playbackSpeed,transcended:HasFamilyTranscendence(source));
    }

    private static void PlayCrocodileDeathRollEffect(
        Unit target,float playbackSpeed,bool reverse=false,bool transcended=false)
    {
        SpriteRenderer renderer=target.spriteAnimation==null
            ?null
            :target.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelCombatEffect.PlayCrocodileDeathRoll(
            target.spriteAnimation==null
                ?target.model.transform
                :target.spriteAnimation.transform,
            renderer,
            playbackSpeed,
            reverse,transcended);
    }

    private void LockDeathRollTarget(Unit source,Unit target,float duration)
    {
        if(!IsCombatActive(target)||target.combatStatuses.RejectHarmfulEffect())return;
        if(!target.combatStatuses.ControlImmune)
        {
            target.crocodileImmobilizedTimer=Mathf.Max(
                target.crocodileImmobilizedTimer,
                HostileStatusDuration(target,duration)*ConcertDurationScale(source));
        }
        if(target.crocodileImmobilizedTimer>0f)
        {
            target.displacing=false;
            InterruptPositionalAction(target);
        }
        target.velocity=Vector3.zero;
        ClearRoute(target);
        SetMoving(target,false);
    }

    private static float DeathRollDamageRatio(int hit,SkillMasterRow skill)
    {
        return hit<=0?skill.damageMultiplier:
            hit>=CrocodileCombatRules.HitCount-1?skill.damagePerStackMultiplier:
            skill.secondaryDamageMultiplier;
    }

    private static void ResetDeathRollPose(Unit unit)
    {
        if(unit==null||unit.model==null)return;
        unit.spriteAnimation?.SetDeathRollFrame(false);
        unit?.spriteBillboard?.SetRollPose(0f,Vector3.zero,Vector3.zero);
        unit?.spriteAnimation?.SetSkillPoseScale(Vector3.one);
    }

    private static void UpdateDeathRollPose(Unit source,Unit victim,float progress,bool reverse,
        float contactWeight=1f,bool absoluteJaw=false)
    {
        if(source.spriteBillboard==null||source.spriteAnimation==null)return;
        SpriteRenderer jaw=source.spriteAnimation.GetComponent<SpriteRenderer>();
        SpriteRenderer prey=victim.spriteAnimation==null?null:
            victim.spriteAnimation.GetComponent<SpriteRenderer>();
        if(jaw==null||jaw.sprite==null||prey==null||prey.sprite==null)return;
        float facing=jaw.flipX?-1f:1f;
        // The generated 256px frames contain wide transparent margins. These
        // coordinates match the snout in the held bite frame, not its canvas edge.
        Bounds jawBounds=jaw.sprite.bounds;
        Vector3 mouth=new Vector3(facing*jawBounds.size.x*0.16f,
            jawBounds.min.y+jawBounds.size.y*0.43f,0f);
        Vector3 bite=prey.sprite.bounds.center;
        Vector3 gap=victim.spriteBillboard==null
            ?prey.bounds.center-source.spriteBillboard.UnposedPoint(mouth)
            :victim.spriteBillboard.UnposedPoint(bite)-source.spriteBillboard.UnposedPoint(mouth);
        float contact=Mathf.SmoothStep(0f,1f,Mathf.Clamp01(progress/0.08f))*contactWeight;
        float angle=720f*Mathf.SmoothStep(0f,1f,Mathf.Clamp01((progress-0.08f)/0.35f))*
            facing*(reverse?-1f:1f);
        bool held=!victim.combatStatuses.ControlImmune&&victim.crocodileImmobilizedTimer>0f;
        float brace=absoluteJaw?Mathf.Clamp01((progress-(1f-CrocodileCombatRules.AbsoluteJawBraceDuration))/
            CrocodileCombatRules.AbsoluteJawBraceDuration)*contactWeight:0f;
        Vector3 tremble=absoluteJaw&&progress<1f
            ?Vector3.up*(Mathf.Sin(progress*180f)*0.04f*brace):Vector3.zero;
        source.spriteBillboard.SetRollPose(angle,mouth,gap*contact*(held?0.75f:1f));
        if(held)victim.spriteBillboard?.SetRollPose(angle,bite,-gap*contact*0.25f+tremble);
        else victim.spriteBillboard?.SetRollPose(0f,Vector3.zero,Vector3.zero);
        float squeeze=Mathf.Clamp01((progress-0.43f)/0.57f)*contactWeight;
        source.spriteAnimation.SetSkillPoseScale(absoluteJaw
            ?new Vector3(1f+0.22f*brace,1f-0.35f*brace,1f)
            :new Vector3(1f+0.12f*squeeze,1f-0.2f*squeeze,1f));
        if(absoluteJaw)
            victim.spriteAnimation?.SetSkillPoseScale(progress>=1f
                ?new Vector3(1f+0.2f*contactWeight,1f-0.35f*contactWeight,1f):Vector3.one);
    }

    private static void PlayTraitBurst(Unit unit,Color color,bool strong)
    {
        if(unit==null||unit.model==null)return;
        SpriteRenderer renderer=unit.spriteAnimation==null
            ?unit.model.GetComponentInChildren<SpriteRenderer>()
            :unit.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelStarProjectile.PlayImpact(renderer==null
                ?unit.model.transform.position+Vector3.up*0.7f
                :renderer.bounds.center,
            renderer,color,strong);
    }

    private float ApplyScatteredDeathRollHit(Unit source,Unit victim,float directDamage)
    {
        if(!MonsterTraitRuntime.Has(
               source.activeTraitIds,"trait_skill_scattered_bite"))return 0f;
        List<Unit> extras=units.Where(enemy=>enemy!=victim&&IsCombatActive(enemy)&&
                enemy.team!=source.team&&Vector3.Distance(Flat(victim.model.transform.position),
                    Flat(enemy.model.transform.position))<=TileSize*1.5f)
            .OrderBy(enemy=>Vector3.Distance(Flat(victim.model.transform.position),
                Flat(enemy.model.transform.position))).Take(2).ToList();
        float total=0f;
        for(int i=0;i<extras.Count;i++)
        {
            float dealt=ApplySkillDamage(source,extras[i],directDamage*0.6f,false);
            total+=dealt;
            source.skillDamage+=dealt;source.skillHits++;
        }
        if(extras.Count>0)source.traitActivations++;
        return total;
    }

    private float ApplyCrocodileCrushingRollSweep(Unit source,Unit primary,float damageScale,bool finalSweep)
    {
        if(!IsCombatActive(source)||!IsCombatActive(primary))return 0f;
        Vector3 center=Flat(primary.model.transform.position);
        float radius=TileSize*CrocodileCombatRules.CrushingRollRadiusTiles;
        bool transcended=HasFamilyTranscendence(source);
        PlayCrocodileSound(source,CrocodileSound.Sweep,center,finalSweep?1f:.85f);
        if(transcended&&finalSweep)PlayCrocodileSound(source,CrocodileSound.Resonance,center);
        float ratio=transcended&&finalSweep?CrocodileCombatRules.TranscendentFinalSweepDamageRatio:
            CrocodileCombatRules.CrushingRollDamageRatio;
        PixelCombatEffect.PlayCrocodileCrushingRollChips(center,radius,
            primary.model.GetComponentInChildren<SpriteRenderer>(),transcended&&finalSweep);
        float total=0f;
        // Snapshot: damage can kill units and trigger other combat callbacks.
        var nearby=units.Where(enemy=>enemy!=primary&&enemy.team!=source.team&&
            IsCombatTargetable(enemy)&&!enemy.crocodilePreyFlying&&
            Vector3.Distance(center,Flat(enemy.model.transform.position))<=radius+enemy.collisionRadius).ToList();
        foreach(Unit enemy in nearby)
        {
            if(!IsCombatActive(source)||!IsCombatTargetable(enemy))continue;
            float dealt=ApplySkillDamage(source,enemy,
                source.damage*ratio*damageScale,false);
            total+=dealt;source.skillDamage+=dealt;source.skillHits++;
            if(dealt<=0f)continue;
            PlayTraitBurst(enemy,transcended?(finalSweep?PixelCombatEffect.CrocodileAbyssHighlight:
                PixelCombatEffect.CrocodileAbyssColor):new Color(1f,0.85f,0.48f),true);
            enemy.reaction?.PlayTintHit(Color.white);
            enemy.spriteAnimation?.PlayImpactRecoil(enemy.model.transform.position-center,0.12f);
        }
        return total;
    }

    private bool BeginCrocodilePreyFlight(Unit source,Unit target)
    {
        Vector3 start=Flat(target.model.transform.position);
        Vector3 direction=start-Flat(source.model.transform.position);
        Unit nearest=null;
        for(int i=0;i<units.Count;i++)
        {
            Unit enemy=units[i];
            if(enemy==target||enemy.team==source.team||!IsCombatTargetable(enemy)||
               enemy.crocodilePreyFlying)continue;
            if(nearest==null||IsPreferredNearestTarget(start,enemy.model.transform.position,
                   enemy.id,nearest.model.transform.position,nearest.id))nearest=enemy;
        }
        if(nearest!=null)
        {
            Vector3 aim=Flat(nearest.model.transform.position)-start;
            if(aim.sqrMagnitude>0.001f)direction=aim;
        }
        if(!DisplaceUnit(target,direction,TileSize*CrocodileCombatRules.PreyCannonDistanceTiles,
               true,true))return false;
        target.crocodileImmobilizedTimer=0f;
        target.displacementEnd=ResolveFreePosition(start+direction.normalized*
            TileSize*CrocodileCombatRules.PreyCannonDistanceTiles,target.collisionRadius);
        target.displacementDuration=CrocodileCombatRules.PreyCannonFlightDuration;
        target.displacementArcHeight=CrocodileCombatRules.PreyCannonArcHeight;
        target.crocodilePreyFlying=true;
        target.currentAction="prey_cannon_flying";
        for(int i=0;i<units.Count;i++)
        {
            Unit ally=units[i];
            if(!IsCombatActive(ally)||ally.team!=source.team||ally.target!=target)continue;
            if(ally!=source&&CanKeepCombatTarget(ally,target))continue;
            SetTarget(ally,SelectTarget(ally));
            StopUnitMovement(ally);
        }
        return true;
    }

    private float ApplyCrocodilePreyCannonSplash(
        Unit source,Unit primary,Vector3 center,float damageScale)
    {
        bool transcended=HasFamilyTranscendence(source);
        float radius=TileSize*(transcended?CrocodileCombatRules.TranscendentPreyCannonRadiusTiles:
            CrocodileCombatRules.PreyCannonRadiusTiles);
        List<Unit> targets=units.Where(enemy=>enemy!=primary&&
                IsCombatActive(enemy)&&enemy.team!=source.team&&
                Vector3.Distance(center,Flat(enemy.model.transform.position))<=
                    radius+enemy.collisionRadius).ToList();
        float total=0f;
        for(int i=0;i<targets.Count;i++)
        {
            Unit enemy=targets[i];
            float dealt=ApplySkillDamage(source,enemy,
                source.damage*CrocodileCombatRules.PreyCannonDamageRatio*
                damageScale,false);
            total+=dealt;
            source.skillDamage+=dealt;
            source.skillHits++;
            if(!IsCombatActive(enemy))continue;
            ApplyCrocodilePreyCannonKnockdown(source,enemy);
        }
        if(IsCombatActive(primary))
            ApplyCrocodilePreyCannonKnockdown(source,primary);
        return total;
    }

    private void ApplyCrocodilePreyCannonKnockdown(Unit source,Unit target)
    {
        if(target.combatStatuses.ControlImmune)return;
        float duration=HostileStatusDuration(
            target,CrocodileCombatRules.PreyCannonKnockdownDuration);
        if(duration>0f)InterruptPositionalAction(target);
        target.combatStatuses.ApplyTimed(CombatStatusKind.Knockdown,duration,source);
        if(duration>0f)target.spriteAnimation?.PlayKnockdown(duration);
    }

    public static bool IsPointInsideForwardSkillLine(
        Vector3 origin,Vector3 forward,Vector3 point,float length,float halfWidth)
    {
        forward.y=0f;
        if(forward.sqrMagnitude<0.001f||length<=0f||halfWidth<0f)return false;
        forward.Normalize();
        Vector3 offset=point-origin;offset.y=0f;
        float along=Vector3.Dot(offset,forward);
        if(along<0.05f||along>length)return false;
        return (offset-forward*along).magnitude<=halfWidth;
    }

    private bool UseGuardianTaunt(Unit unit,SkillMasterRow skill,float effectScale=1f,bool traitEcho=false)
    {
        float radius=TileSize*skill.radiusTiles*unit.skillTraitRadiusMultiplier;
        float duration=skill.durationSeconds*effectScale*
                       (1f+unit.itemModifiers.skillPowerBonus);
        int hits=0;
        Vector3 origin=Flat(unit.model.transform.position);
        for(int i=0;i<units.Count;i++)
        {
            Unit enemy=units[i];
            if(!IsCombatActive(enemy)||enemy.team==unit.team)continue;
            if(Vector3.Distance(origin,Flat(enemy.model.transform.position))>radius)continue;
            if(enemy.combatStatuses.ControlImmune||enemy.combatStatuses.RejectHarmfulEffect())continue;
            enemy.forcedTarget=unit.spiritConcertOwner??unit;enemy.forcedTargetTimer=duration*ConcertDurationScale(unit);
            SetTarget(enemy,enemy.forcedTarget);enemy.decisionTimer=DecisionInterval;
            hits++;
        }
        if(hits==0&&!IsCommittingFocusedSkill(unit))
        {
            if(!traitEcho)unit.skillTimer=0.35f;
            return false;
        }
        if(!traitEcho)
        {
            unit.skillTimer=unit.skillCooldownDuration;unit.skillUses++;
            ApplyPostSkillItemEffects(unit);
        }
        unit.guardTimer=GateHaetaeBenefit(unit,Mathf.Max(unit.guardTimer,duration));unit.skillHits+=hits;
        unit.currentAction="guardian_taunt";unit.velocity=Vector3.zero;SetMoving(unit,false);
        CreateSkillPulse(unit,new Color(0.1f,0.65f,1f),1.8f);
        RecordSkillEvent(unit,skill.id+(traitEcho?"_echo":""),hits,0f);
        return true;
    }

    private bool BeginAssassinLeap(Unit unit,SkillMasterRow skill)
    {
        float castRange=Mathf.Max(1f,skill.castRangeTiles);
        Unit victim=SelectRaptorLeapTarget(unit,castRange);
        if(victim==null)return false;
        if(!StartAssassinLeap(
               unit,victim,unit.skillTraitDamageMultiplier))return false;
        SetTarget(unit,victim);
        unit.skillTimer=unit.skillCooldownDuration;unit.skillUses++;
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        return true;
    }

    private Unit SelectRaptorLeapTarget(Unit source,float castRange)
    {
        Unit committed=CommittedSkillTarget(source);
        if(IsCombatTargetable(committed))return committed;
        if(IsCombatActive(source.forcedTarget)&&source.forcedTargetTimer>0f)
            return IsWithinRaptorLeapRange(
                source,source.forcedTarget,castRange)
                ?source.forcedTarget:null;
        if(HasPreyFocus(source))
            return IsWithinRaptorLeapRange(source,source.preyFocusTarget,castRange)
                ?source.preyFocusTarget:null;
        Vector3 origin=Flat(source.model.transform.position);
        return units.Where(candidate=>
                IsCombatTargetable(candidate)&&candidate.team!=source.team&&
                IsWithinRaptorLeapRange(source,candidate,castRange))
            .OrderBy(candidate=>RaptorCombatRules.PhysicalEffectiveHealth(
                candidate.hp,CurrentDefense(candidate)))
            .ThenBy(candidate=>candidate.hp)
            .ThenBy(candidate=>CurrentDefense(candidate))
            .ThenBy(candidate=>Vector3.Distance(
                origin,Flat(candidate.model.transform.position)))
            .ThenBy(candidate=>candidate.id)
            .FirstOrDefault();
    }

    private bool StartAssassinLeap(
        Unit unit,Unit victim,float damageMultiplier)
    {
        SkillMasterRow leapSkill=GameMasterData.Skill(unit.skillId);
        if(!IsCombatTargetable(victim)||CommittedSkillTarget(unit)!=victim&&!IsWithinRaptorLeapRange(
               unit,victim,Mathf.Max(1f,
                   leapSkill==null?5f:leapSkill.castRangeTiles)))return false;
        unit.leaping=true;unit.leapProgress=0f;unit.leapTarget=victim;
        unit.leapReturning=false;
        unit.leapGroundScuffs=0;
        unit.leapPiercing=MonsterTraitRuntime.Has(
            unit.activeTraitIds,RaptorCombatRules.PiercingHuntTraitId);
        unit.leapPiercingHits.Clear();
        unit.leapHitCount=0;unit.leapDamageDealt=0f;
        unit.leapImpactResolved=false;
        unit.leapWindupRemaining=RaptorCombatRules.LeapWindupDuration;
        unit.leapImpactHoldRemaining=0f;
        unit.leapAfterimages=0;
        unit.leapTraitDamageMultiplier=damageMultiplier;
        unit.leapRelentless=!unit.leapPiercing&&MonsterTraitRuntime.Has(
            unit.activeTraitIds,RaptorCombatRules.RelentlessHuntTraitId);
        unit.leapComboElapsed=0f;
        unit.leapComboStrikes=0;
        if(unit.leapRelentless)unit.traitActivations++;
        unit.leapStart=Flat(unit.model.transform.position);
        unit.leapImpactPosition=Flat(victim.model.transform.position);
        bool remoteProjection=MonsterTraitRuntime.Has(
            unit.activeTraitIds,"trait_skill_remote_projection");
        unit.leapEnd=RaptorCombatRules.LeapContactPosition(
            unit.leapStart,unit.leapImpactPosition,
            unit.collisionRadius,victim.collisionRadius);
        if(unit.leapPiercing)
        {
            unit.leapEnd=ResolveFreePosition(
                RaptorCombatRules.PiercingLandingPosition(unit.leapStart,
                    unit.leapImpactPosition,AttackDistance(unit,victim)),unit.collisionRadius);
            unit.traitActivations++;
        }
        else if(remoteProjection)
        {
            unit.leapEnd=unit.leapStart;
            unit.traitActivations++;
        }
        unit.currentAction="assassin_leap";
        FaceRaptorLeapTarget(unit,victim.model.transform.position-unit.model.transform.position,0f);
        unit.leapExitVelocity=Vector3.zero;
        unit.velocity=Vector3.zero;SetMoving(unit,false);
        return true;
    }

    private static bool IsWithinRaptorLeapRange(
        Unit source,Unit target,float castRange)
    {
        if(!IsCombatActive(target))return false;
        return Vector3.Distance(
            Flat(source.model.transform.position),
            Flat(target.model.transform.position))<=TileSize*castRange;
    }

    private void PlayAssassinLeapAnimation(Unit unit)
    {
        if(unit.spriteAnimation==null)return;
        int generation=combatGeneration;
        float contactTime=RaptorCombatRules.LeapWindupDuration+
            RaptorCombatRules.LeapApproachDuration(
                SkillValue(unit.skillId,row=>row.durationSeconds,0.24f));
        float playbackSpeed=unit.spriteAnimation.SkillAttackHitTime/
            Mathf.Max(0.01f,contactTime);
        unit.spriteAnimation.PlaySkillAttack(
            playbackSpeed,2.2f,
            ()=>
            {
                if(generation!=combatGeneration||!IsCombatActive(unit)||
                   !unit.leaping||unit.leapReturning||unit.leapProgress<1f)return;
                ResolveAssassinLeapImpact(unit);
            });
    }

    private void UpdateAssassinLeap(Unit unit,float dt)
    {
        if(unit.leapRelentless&&unit.leapImpactResolved&&!unit.leapReturning)
        {
            UpdateRelentlessHunt(unit,dt);
            return;
        }
        bool returning=unit.leapReturning;
        if(unit.leapWindupRemaining>0f)
        {
            float used=Mathf.Min(dt,unit.leapWindupRemaining);
            unit.leapWindupRemaining-=used;
            dt-=used;
            float crouch=Mathf.Sin((1f-unit.leapWindupRemaining/
                RaptorCombatRules.LeapWindupDuration)*Mathf.PI*0.5f);
            unit.spriteAnimation?.SetSkillPoseScale(
                new Vector3(1f+0.12f*crouch,1f-0.2f*crouch,1f));
            if(IsCombatActive(unit.leapTarget))FaceRaptorLeapTarget(unit,
                unit.leapTarget.model.transform.position-unit.model.transform.position,used);
            if(unit.leapWindupRemaining>0f)return;
            PlayRaptorSkillSound(unit,false,unit.model.transform.position);
        }
        if(returning&&unit.leapImpactHoldRemaining>0f)
        {
            float used=Mathf.Min(dt,unit.leapImpactHoldRemaining);
            unit.leapImpactHoldRemaining-=used;
            dt-=used;
            if(unit.leapImpactHoldRemaining>0f)return;
        }
        if(returning&&unit.leapPiercing)
        {
            FinishAssassinLeap(unit);
            return;
        }
        bool remoteProjection=MonsterTraitRuntime.Has(
            unit.activeTraitIds,"trait_skill_remote_projection");
        if(!returning&&!unit.leapPiercing&&!remoteProjection&&IsCombatActive(unit.leapTarget))
        {
            unit.leapImpactPosition=Flat(unit.leapTarget.model.transform.position);
            unit.leapEnd=RaptorCombatRules.LeapContactPosition(
                unit.leapStart,unit.leapImpactPosition,
                unit.collisionRadius,unit.leapTarget.collisionRadius);
        }
        float duration=returning
            ?RaptorCombatRules.LeapReturnDuration
            :RaptorCombatRules.LeapApproachDuration(
                SkillValue(unit.skillId,row=>row.durationSeconds,0.24f));
        unit.leapProgress=Mathf.Min(1f,unit.leapProgress+dt/Mathf.Max(0.01f,duration));
        float stretch=returning?0f:Mathf.Sin(unit.leapProgress*Mathf.PI);
        unit.spriteAnimation?.SetSkillPoseScale(
            new Vector3(1f+0.14f*stretch,1f-0.08f*stretch,1f));
        float eased=returning
            ?1f-Mathf.Pow(1f-unit.leapProgress,2f)
            :unit.leapProgress;
        Vector3 ground=Vector3.Lerp(unit.leapStart,unit.leapEnd,eased);
        Vector3 previousGround=Flat(unit.model.transform.position);
        float arc=Mathf.Sin(unit.leapProgress*Mathf.PI)*
            (returning
                ?RaptorCombatRules.LeapReturnArcHeight
                :RaptorCombatRules.LeapApproachArcHeight);
        unit.model.transform.position=ground+Vector3.up*(unit.visualHeightOffset+arc);
        unit.ring.transform.position=ground+Vector3.up*0.025f;
        int scuffLimit=3,afterimageLimit=3;
        float afterimageAlpha=.3f;
        if(CombatReadabilityPresentation.RefinedSkills&&!unit.augmentTranscended)
        {scuffLimit=2;afterimageLimit=1;afterimageAlpha=.18f;}
        if(!returning&&unit.leapPiercing)
        {
            while(unit.leapGroundScuffs<scuffLimit&&
                  unit.leapProgress>=0.2f+unit.leapGroundScuffs*0.3f)
            {
                // Only the travelled ground is marked; never preview the route ahead.
                float progress=0.1f+unit.leapGroundScuffs*0.3f;
                PixelCombatEffect.PlayRaptorGroundScuff(
                    Vector3.Lerp(unit.leapStart,unit.leapEnd,progress),
                    unit.leapEnd-unit.leapStart,unit.spriteAnimation==null?null:
                        unit.spriteAnimation.GetComponent<SpriteRenderer>());
                unit.leapGroundScuffs++;
            }
            ApplyRaptorPiercingSweep(unit,previousGround,ground);
            if(!IsCombatActive(unit)||!unit.leaping)return;
        }
        if(!returning&&!remoteProjection&&unit.spriteAnimation!=null&&
           unit.leapProgress<0.95f&&unit.leapAfterimages<afterimageLimit&&
           unit.leapProgress>=0.2f+unit.leapAfterimages*0.25f)
        {
            SpriteRenderer renderer=unit.spriteAnimation.GetComponent<SpriteRenderer>();
            Color tint=RaptorLeapTint(unit);tint.a=afterimageAlpha;
            SpriteRenderer ghost=Rank3CombatFx.Ghost("Raptor Leap Afterimage",
                renderer,renderer.transform.position,tint,1f,0.09f);
            if(ghost!=null)
            {
                ghost.transform.rotation=renderer.transform.rotation;
                ghost.sharedMaterial=renderer.sharedMaterial;
                ghost.sortingOrder=renderer.sortingOrder-1;
            }
            unit.leapAfterimages++;
        }
        if(unit.leapPiercing&&!returning&&unit.leapProgress<1f)
            FaceRaptorLeapTarget(unit,unit.leapEnd-unit.leapStart,dt);
        else if(IsCombatActive(unit.leapTarget))
            FaceRaptorLeapTarget(unit,unit.leapTarget.model.transform.position-unit.model.transform.position,dt);
        if(unit.leapProgress<1f)return;
        if(returning)
        {
            FinishAssassinLeap(unit);
            return;
        }
        // Arrival resolves the landing; piercing hits are swept during travel.
        unit.spriteAnimation?.NotifySkillAttackHitFrameFromAnimation();
        ResolveAssassinLeapImpact(unit);
    }

    private void FinishAssassinLeap(Unit unit)
    {
        Vector3 ground=unit.leapEnd;
        unit.model.transform.position=ground+Vector3.up*unit.visualHeightOffset;
        unit.ring.transform.position=ground+Vector3.up*0.025f;
        unit.leaping=false;
        unit.leapReturning=false;
        unit.spriteAnimation?.SetSkillPoseScale(Vector3.one);
        unit.leapProgress=1f;
        unit.lastGroundPosition=ground;
        unit.currentTile=NearestGridCoordinate(ground);
        unit.currentAction="assassin_leap_recover";
        unit.velocity=Vector3.zero;
        SetMoving(unit,false);
        unit.leapTarget=null;
        BeginUnitInertia(unit,unit.leapExitVelocity*CombatStatFormula.CombatAnimationRate);
    }

    private void ResolveAssassinLeapImpact(Unit unit)
    {
        if(unit==null||!unit.leaping||unit.leapImpactResolved)return;
        unit.leapImpactResolved=true;
        unit.spriteAnimation?.SetSkillPoseScale(Vector3.one);
        unit.spriteAnimation?.HoldSkillAttackHitFrame(RaptorCombatRules.LeapImpactHoldDuration);
        Unit victim=unit.leapTarget;
        bool victimWasAlive=IsCombatActive(victim);
        Vector3 impactPoint=RaptorCombatRules.LeapImpactPosition(
            unit.leapImpactPosition,
            victimWasAlive?Flat(victim.model.transform.position):Vector3.zero,
            victimWasAlive);
        Vector3 ground=unit.leapEnd;
        layeredBattleEnvironment?.Pulse(
            impactPoint,0.82f,impactPoint-ground);
        unit.model.transform.position=
            ground+Vector3.up*unit.visualHeightOffset;
        unit.ring.transform.position=ground+Vector3.up*0.025f;
        unit.lastGroundPosition=ground;
        unit.currentTile=NearestGridCoordinate(ground);
        if(unit.leapRelentless)
        {
            unit.spriteAnimation?.HoldSkillAttackHitFrame(RaptorCombatRules.RelentlessDuration);
            UpdateRelentlessHunt(unit,0f);
            return;
        }
        SkillMasterRow leapSkill=GameMasterData.Skill(unit.skillId);
        float impactRadius=ActiveTileSize*Mathf.Max(
            0f,leapSkill==null?1.5f:leapSkill.radiusTiles);
        bool targetInside=victimWasAlive&&Vector3.Distance(
            impactPoint,Flat(victim.model.transform.position))<=impactRadius;
        if(targetInside&&!unit.leapPiercing)ApplyRaptorLeapHit(unit,victim);
        if(IsCombatActive(unit)&&unit.leaping)FinishRaptorLeapAttack(unit);
    }

    private void FaceRaptorLeapTarget(Unit unit,Vector3 direction,float dt)
    {
        RotateUnit(unit,direction,dt);
        // The skill owns facing while its attack frame is held.
        unit.spriteBillboard?.SetFacingDirection(direction,true);
    }

    private void UpdateRelentlessHunt(Unit unit,float dt)
    {
        if(!unit.leaping||unit.leapReturning||!IsCombatActive(unit))return;
        unit.leapComboElapsed+=Mathf.Max(0f,dt);
        Unit victim=unit.leapTarget;
        if(!IsCombatTargetable(victim))
        {
            FinishRaptorLeapAttack(unit);
            return;
        }
        unit.currentAction="raptor_relentless_hunt";
        unit.velocity=Vector3.zero;SetMoving(unit,false);
        Vector3 attackDirection=victim.model.transform.position-unit.model.transform.position;
        FaceRaptorLeapTarget(unit,attackDirection,dt);
        while(unit.leapComboStrikes<RaptorCombatRules.RelentlessStrikeCount&&
              unit.leapComboElapsed>=RaptorCombatRules.RelentlessStrikeTime(unit.leapComboStrikes))
        {
            int strike=unit.leapComboStrikes++;
            unit.spriteAnimation?.PlayRaptorRelentlessStrike(attackDirection,strike);
            bool inReach=Vector3.Distance(Flat(unit.model.transform.position),
                Flat(victim.model.transform.position))<=AttackDistance(unit,victim);
            if(inReach)ApplyRaptorLeapHit(unit,victim,
                RaptorCombatRules.RelentlessStrikeDamageMultiplier(strike),strike);
            if(!IsCombatActive(unit)||!unit.leaping)return;
            if(inReach&&strike==2)layeredBattleEnvironment?.Pulse(
                Flat(victim.model.transform.position),0.85f,
                victim.model.transform.position-unit.model.transform.position);
            if(!IsCombatTargetable(victim))break;
        }
        if(!IsCombatTargetable(victim)||unit.leapComboElapsed>=RaptorCombatRules.RelentlessDuration)
            FinishRaptorLeapAttack(unit);
    }

    private void FinishRaptorLeapAttack(Unit unit)
    {
        CompleteSkillCameraImpact(unit);
        Unit victim=unit.leapTarget;
        Vector3 ground=Flat(unit.model.transform.position);
        Vector3 impactPoint=IsCombatActive(victim)
            ?Flat(victim.model.transform.position):unit.leapImpactPosition;
        int hits=unit.leapHitCount;
        float dealt=unit.leapDamageDealt;
        if(hits>0&&MonsterTraitRuntime.Has(
               unit.activeTraitIds,RaptorCombatRules.WiloTraitId))
            ApplyWiloIceCarapace(unit,impactPoint,1f);
        if(hits>0&&unit.augmentTranscended&&IsRaptorFamily(unit))
            ActivateRaptorApexPredator(unit);
        unit.leapTraitDamageMultiplier=1f;
        RecordSkillEvent(unit,unit.skillId+
            (unit.leapRelentless?"_relentless_land":"_land"),hits,dealt);
        if(IsCombatActive(victim))SetTarget(unit,victim);
        unit.spriteAnimation?.HoldSkillAttackHitFrame(RaptorCombatRules.LeapImpactHoldDuration);
        bool remoteProjection=MonsterTraitRuntime.Has(
            unit.activeTraitIds,"trait_skill_remote_projection");
        float returnDistance=victim==null
            ?AttackDistanceForRange(
                unit.attackRange,unit.collisionRadius,unit.collisionRadius)
            :AttackDistance(unit,victim);
        unit.leapExitVelocity=(unit.leapEnd-unit.leapStart)/Mathf.Max(.01f,
            RaptorCombatRules.LeapApproachDuration(SkillValue(unit.skillId,row=>row.durationSeconds,.24f)));
        unit.leapStart=ground;
        unit.leapEnd=remoteProjection||unit.leapPiercing
            ?ground
            :ResolveFreePosition(
                RaptorCombatRules.LeapReturnPosition(
                    ground,impactPoint,returnDistance),
                unit.collisionRadius);
        if(!unit.leapPiercing)unit.leapExitVelocity=(unit.leapEnd-unit.leapStart)/RaptorCombatRules.LeapReturnDuration;
        unit.leapProgress=0f;
        unit.leapReturning=true;
        unit.leapImpactHoldRemaining=RaptorCombatRules.LeapImpactHoldDuration;
        unit.currentAction="assassin_leap_return";
        unit.velocity=Vector3.zero;
        SetMoving(unit,false);
    }

    private void ApplyRaptorPiercingSweep(Unit unit,Vector3 previous,Vector3 current)
    {
        int count=units.Count;
        for(int i=0;i<count;i++)
        {
            Unit victim=units[i];
            if(!IsCombatTargetable(victim)||victim.team==unit.team||
               unit.leapPiercingHits.Contains(victim))continue;
            // Wider melee staging must not widen this skill's damage corridor.
            float sweepReach=AttackDistance(unit,victim)-(IsRangedUnit(unit)?0f:MeleeReadabilitySpacing)-
                (CombatBodyRadius(unit)-unit.collisionRadius)-
                (CombatBodyRadius(victim)-victim.collisionRadius);
            if(!RaptorCombatRules.IsInPiercingSweep(victim.model.transform.position,
                   previous,current,sweepReach))continue;
            unit.leapPiercingHits.Add(victim);
            ApplyRaptorLeapHit(unit,victim);
            if(!IsCombatActive(unit)||!unit.leaping)return;
        }
    }

    private void ApplyRaptorLeapHit(Unit unit,Unit victim,float hitMultiplier=1f,int strike=-1)
    {
        Vector3 impactPoint=Flat(victim.model.transform.position);
        Vector3 impactDirection=strike>=0
            ?impactPoint-Flat(unit.model.transform.position):unit.leapEnd-unit.leapStart;
        PlayRaptorSkillSound(unit,true,impactPoint,strike<0?1f:strike==2?1.15f:.8f);
        SpriteRenderer renderer=victim.spriteAnimation==null?null:
            victim.spriteAnimation.GetComponent<SpriteRenderer>();
        var claws=PixelCombatEffect.PlayRaptorClawImpact(
            victim.spriteAnimation==null?victim.model.transform:victim.spriteAnimation.transform,
            renderer,impactDirection,RaptorLeapTint(unit),strike);
        if(CombatReadabilityPresentation.RefinedSkills&&!unit.augmentTranscended&&strike>=0&&strike<2&&claws!=null)
            claws.transform.localScale*=.85f;
        float intrinsicMultiplier=MonsterTraitRuntime.Has(
            unit.activeTraitIds,RaptorCombatRules.VelokTraitId)
            ?RaptorCombatRules.LeapDamageMultiplier(
                RaptorCombatRules.VelokTraitId,victim.hp/Mathf.Max(1f,victim.maxHp)):1f;
        float dealt=ApplySkillFormulaDamage(unit,victim,GameMasterData.Skill(unit.skillId),false,0,
            unit.leapTraitDamageMultiplier*hitMultiplier*intrinsicMultiplier);
        unit.leapHitCount++;unit.leapDamageDealt+=dealt;
        unit.skillHits++;unit.skillDamage+=dealt;
        if(IsCombatActive(victim))
            victim.spriteAnimation?.PlayImpactRecoil(strike>=0?impactDirection:impactPoint-unit.leapStart,0.12f);
        if(IsCombatActive(victim)&&victim.team!=unit.team&&MonsterTraitRuntime.Has(
            unit.activeTraitIds,RaptorCombatRules.ArmorHuntTraitId))
        {
            // Apply after impact: the initial leap keeps its normal damage.
            CombatStatusEffect broken=victim.combatStatuses.ApplyTimed(
                CombatStatusKind.ArmorBroken,RaptorCombatRules.ArmorBreakDuration,
                unit,RaptorCombatRules.ArmorBreakRatio);
            if(broken.remaining>0f)
            {
                PixelCombatEffect.PlayArmorBreak(
                    victim.spriteAnimation==null?victim.model.transform:
                        victim.spriteAnimation.transform,renderer);
                unit.traitActivations++;
            }
        }
        if(!IsCombatActive(victim)&&MonsterTraitRuntime.Has(
            unit.activeTraitIds,RaptorCombatRules.VelosTraitId))
        {
            unit.skillTimer=RaptorCombatRules.CooldownAfterLeapKill(unit.skillTimer);
            unit.traitActivations++;
        }
        if(IsCombatActive(victim)&&MonsterTraitRuntime.Has(
            unit.activeTraitIds,RaptorCombatRules.RaputoTraitId))
        {
            victim.combatStatuses.ApplyStacks(
                CombatStatusKind.Poison,RaptorCombatRules.VenomDuration,
                1,CombatStatusState.MaximumPoisonStacks,unit,
                RaptorCombatRules.VenomTickDamage(unit.damage),
                RaptorCombatRules.VenomTickInterval,true);
            unit.traitActivations++;
        }
    }

    private static bool RaptorApexPredatorActive(Unit unit)
    {
        return unit!=null&&unit.augmentTranscended&&IsRaptorFamily(unit)&&
               unit.raptorApexPredatorTimer>0f;
    }

    private void ActivateRaptorApexPredator(Unit unit)
    {
        bool newlyActivated=unit.raptorApexPredatorTimer<=0f;
        unit.raptorApexPredatorTimer=Mathf.Max(
            unit.raptorApexPredatorTimer,
            ExpeditionAugmentRuntime.TranscendenceParam(
                "raptor_apex_duration",RaptorCombatRules.ApexPredatorDuration));
        if(!newlyActivated)return;
        SpriteRenderer renderer=unit.spriteAnimation==null
            ?unit.model.GetComponentInChildren<SpriteRenderer>()
            :unit.spriteAnimation.GetComponent<SpriteRenderer>();
        unit.raptorApexWings=PixelRaptorApexWings.Attach(renderer);
        unit.raptorApexWings?.SetAwakened(true);
        unit.raptorApexWings?.SetForeground(HasSkillCastPresentation(unit));
        PixelCombatEffect.PlayRaptorApexActivation(unit.model.transform,renderer);
        AddCombatFloatText(unit,"정점 포식자",new Color(0.96f,0.9f,0.7f),true);
        unit.traitActivations++;
        QueueRaptorApexCinematic(unit);
    }

    private static Color RaptorLeapTint(Unit unit)
    {
        if(unit.spiritConcertOwner!=null)return PixelSpiritConcert.Color;
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,RaptorCombatRules.VelokTraitId))
            return new Color(0.84f,0.28f,1f);
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,RaptorCombatRules.RaputoTraitId))
            return new Color(0.52f,0.95f,0.24f);
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,RaptorCombatRules.WiloTraitId))
            return new Color(0.38f,0.86f,1f);
        return new Color(1f,0.85f,0.55f);
    }

    private void ShowImpactRadius(
        Vector3 center,float radius,bool targetInside)
    {
        GameObject root=new GameObject("Skill Impact Radius");
        root.transform.position=center+Vector3.up*0.08f;
        LineRenderer line=root.AddComponent<LineRenderer>();
        line.sharedMaterial=skillRadiusMarkerMaterial;
        line.useWorldSpace=false;
        line.loop=true;
        line.positionCount=48;
        line.startWidth=0.07f;
        line.endWidth=0.07f;
        line.numCornerVertices=2;
        line.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;
        line.receiveShadows=false;
        Color color=targetInside
            ?new Color(0.15f,1f,0.58f,0.95f)
            :new Color(1f,0.18f,0.12f,0.95f);
        line.startColor=color;
        line.endColor=color;
        for(int i=0;i<line.positionCount;i++)
        {
            float angle=i*Mathf.PI*2f/line.positionCount;
            line.SetPosition(i,new Vector3(
                Mathf.Cos(angle)*radius,0f,Mathf.Sin(angle)*radius));
        }
        Destroy(root,0.65f);
    }

    private static float SpriteSkillAttackPlaybackSpeed(Unit unit)
    {
        return 1f;
    }

    private void ApplyWiloIceCarapace(
        Unit source,Vector3 landing,float fieldScale=1f)
    {
        source.raptorShield=GateHaetaeBenefit(source,Mathf.Max(source.raptorShield,
            RaptorCombatRules.IceShield(
                source.maxHp,source.combatStatuses.shieldGainMultiplier*GuardianShieldMultiplier(source))),CombatBenefitKind.Shield);
        source.raptorShieldTimer=RaptorCombatRules.IceShieldDuration;
        float radius=TileSize*SkillValue(source.skillId,row=>row.radiusTiles,1.5f)*
                     Mathf.Max(0f,fieldScale);
        SpriteRenderer renderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelCombatEffect.PlayWiloIceField(
            landing,radius,RaptorCombatRules.IceSlowDuration,
            skillRadiusMarkerMaterial,renderer);
        HashSet<Unit> chilled=new HashSet<Unit>();
        int slowed=RefreshWiloIceSlow(source,landing,radius,chilled);
        StartCombatCoroutine(source,ResolveWiloIceField(
            source,landing,radius,chilled,combatGeneration));
        source.traitActivations++;
        CreateSkillPulse(source,new Color(0.32f,0.82f,1f),1f);
        RecordSkillEvent(source,source.skillId+"_ice_carapace",slowed,0f);
    }

    private int RefreshWiloIceSlow(
        Unit source,Vector3 center,float radius,HashSet<Unit> chilled)
    {
        int slowed=0;
        for(int i=0;i<units.Count;i++)
        {
            Unit enemy=units[i];
            if(!IsCombatActive(enemy)||enemy.team==source.team||
               Vector3.Distance(center,Flat(enemy.model.transform.position))>
               radius+enemy.collisionRadius)continue;
            enemy.raptorSlowTimer=Mathf.Max(enemy.raptorSlowTimer,
                HostileStatusDuration(
                    enemy,RaptorCombatRules.IceSlowRefreshDuration));
            if(chilled.Add(enemy))
                ApplyStackingFrost(source,enemy,
                    RaptorCombatRules.IceChillDuration,
                    RaptorCombatRules.IceChillStacksToFreeze,
                    RaptorCombatRules.IceFreezeDuration);
            slowed++;
        }
        return slowed;
    }

    private IEnumerator ResolveWiloIceField(
        Unit source,Vector3 center,float radius,HashSet<Unit> chilled,int generation)
    {
        const float refreshInterval=0.1f;
        float remaining=RaptorCombatRules.IceSlowDuration;
        WaitForSeconds wait=new WaitForSeconds(refreshInterval);
        while(remaining>0f&&generation==combatGeneration)
        {
            RefreshWiloIceSlow(source,center,radius,chilled);
            remaining-=refreshInterval;
            yield return wait;
        }
    }

    private bool UseClusterBreath(Unit unit,SkillMasterRow skill,float effectScale=1f,bool traitEcho=false)
    {
        Vector3 origin=Flat(unit.model.transform.position);
        Vector3 forward=Flat(unit.target.model.transform.position-unit.model.transform.position).normalized;
        float radius=TileSize*skill.radiusTiles*unit.skillTraitRadiusMultiplier;
        int hits=0;float dealt=0f;
        for(int i=0;i<units.Count;i++)
        {
            Unit enemy=units[i];
            if(!IsCombatActive(enemy)||enemy.team==unit.team)continue;
            Vector3 offset=Flat(enemy.model.transform.position)-origin;
            if(offset.magnitude>radius||Vector3.Dot(forward,offset.normalized)<0.55f)continue;
            dealt+=ApplySkillDamage(unit,enemy,unit.damage*skill.damageMultiplier*effectScale,!traitEcho);hits++;
        }
        if(hits==0&&!IsCommittingFocusedSkill(unit))
        {
            if(!traitEcho)unit.skillTimer=0.3f;
            return false;
        }
        if(!traitEcho)
        {
            unit.skillTimer=unit.skillCooldownDuration;unit.skillUses++;
            ApplyPostSkillItemEffects(unit);
        }
        unit.skillHits+=hits;unit.skillDamage+=dealt;
        unit.currentAction="cluster_breath";unit.velocity=Vector3.zero;SetMoving(unit,false);
        CreateSkillPulse(unit,new Color(1f,0.28f,0.04f),1.35f);
        RecordSkillEvent(unit,skill.id+(traitEcho?"_echo":""),hits,dealt);
        return true;
    }

    private bool BeginTongueHarpoon(Unit unit,SkillMasterRow skill)
    {
        Unit target=unit.target;
        float castRange=TileSize*Mathf.Max(1f,skill.castRangeTiles)+
                        unit.collisionRadius+(target==null?0f:target.collisionRadius);
        if(!IsWithinCommittedSkillReach(unit,target,castRange))
            return false;

        unit.tongueHarpoonTarget=target;
        unit.tongueHarpoonDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.tongueHarpoonRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="tongue_harpoon";
        unit.velocity=Vector3.zero;
        unit.attackMovementLockTimer=Mathf.Max(
            unit.attackMovementLockTimer,Mathf.Max(0.2f,skill.durationSeconds));
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        RotateUnit(unit,target.model.transform.position-unit.model.transform.position,1f);
        ApplyPostSkillItemEffects(unit);
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,FrogCombatRules.KingpaTraitId))
        {
            ApplyKingpaRoyalDecree(unit);
            unit.traitActivations++;
        }
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(HasFamilyTranscendence(unit))
        {BeginFrogGrandSlam(unit,target,skill,unit.tongueHarpoonDamageMultiplier,unit.tongueHarpoonRadiusMultiplier);return true;}
        if(unit.spriteAnimation==null)
            LaunchTongueHarpoon(unit,skill,combatGeneration);
        return true;
    }

    private void LaunchTongueHarpoon(Unit source,SkillMasterRow skill,int generation)
    {
        Unit target=source==null?null:source.tongueHarpoonTarget;
        if(skill==null||generation!=combatGeneration||
           !IsCombatActive(source)||!IsCombatActive(target))
        {
            if(source!=null)source.tongueHarpoonTarget=null;
            return;
        }
        PlayFrogSound(source,FrogSound.Launch,source.model.transform.position);
        Action impact=()=>StartCombatCoroutine(source,ResolveTongueHarpoon(
            source,target,skill,generation,
            source.tongueHarpoonDamageMultiplier,
            source.tongueHarpoonRadiusMultiplier));
        if(source.tongueWhip!=null)
            source.tongueWhip.Play(
                target.spriteAnimation==null
                    ?target.model.transform:target.spriteAnimation.transform,
                impact,
                true,1f,0f,true);
        else impact();
    }

    private sealed class FrogHarpoonCatch
    {
        public Unit target;
        public int revision;
        public bool pulled;
        public bool attached=true;
        public FrogTongueWhip branch;
    }

    private List<Unit> FrogFishingSecondaries(Unit source,Unit primary)
    {
        Vector3 center=Flat(primary.model.transform.position);
        return units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=source.team&&
                enemy!=primary&&Vector3.Distance(center,Flat(enemy.model.transform.position))<=
                    TileSize*FrogCombatRules.TranscendentBranchRadiusTiles)
            .OrderBy(enemy=>Vector3.SqrMagnitude(Flat(enemy.model.transform.position)-center))
            .ThenBy(enemy=>enemy.id).Take(2).ToList();
    }

    private IEnumerator ResolveTongueHarpoon(
        Unit source,Unit target,SkillMasterRow skill,int generation,
        float damageMultiplier,float radiusMultiplier)
    {
        if(generation!=combatGeneration||!IsCombatActive(source)||
           !IsCombatActive(target))
        {
            if(source!=null)
            {
                source.tongueHarpoonTarget=null;
                source.tongueWhip?.Cancel();
            }
            yield break;
        }

        int hits=1;
        int sourceRevision=source.positionRevision;
        int targetRevision=target.positionRevision;
        bool pulled=false,recoiled=false,landed=false;
        bool transcended=HasFamilyTranscendence(source);
        var catches=new List<FrogHarpoonCatch>();
        bool slam=MonsterTraitRuntime.Has(source.activeTraitIds,FrogCombatRules.TongueSlamTraitId);
        PlayFrogSound(source,FrogSound.Hit,target.model.transform.position);
        float dealt=ApplySkillDamage(source,target,
            source.damage*skill.damageMultiplier*damageMultiplier);
        Vector3 sourcePosition=Flat(source.model.transform.position);
        try
        {
            // Frog transcendence resolves at tongue contact, together with its branches.
            if(transcended){PlayFamilyTranscendenceFeedback(source,"frog");source.traitActivations++;}
            if(IsCombatActive(target))
            {
                if(MonsterTraitRuntime.Has(
                       source.activeTraitIds,FrogCombatRules.BuffThiefTraitId))
                    ApplyFrogBuffTheft(source,target);
                if(MonsterTraitRuntime.Has(
                       source.activeTraitIds,FrogCombatRules.GolgaebiTraitId)&&!target.combatStatuses.RejectHarmfulEffect())
                {
                    ApplyDefenseShred(source,target,FrogCombatRules.AncientMucusDefenseReduction,
                        FrogCombatRules.AncientMucusDuration);
                    source.traitActivations++;
                }
            }
            CreateSkillPulse(target,new Color(0.94f,0.22f,0.48f),0.72f);

            if(transcended&&IsCombatActive(target))
            {
                foreach(Unit enemy in FrogFishingSecondaries(source,target))
                {
                    catches.Add(new FrogHarpoonCatch{target=enemy,revision=enemy.positionRevision,
                        branch=source.tongueWhip?.Fork(enemy.spriteAnimation==null
                            ?enemy.model.transform:enemy.spriteAnimation.transform)});
                }
                if(catches.Count>0)
                {
                    PlayFrogSound(source,FrogSound.Branch,target.model.transform.position,1.1f);
                    source.currentAction="tongue_branch";
                    yield return new WaitForSeconds(FrogTongueWhip.ImpactDelay);
                    if(generation!=combatGeneration||!IsCombatActive(source)||!IsCombatActive(target)||
                       source.positionRevision!=sourceRevision||target.positionRevision!=targetRevision||
                       source.tongueHarpoonTarget!=target)yield break;
                    foreach(FrogHarpoonCatch caught in catches)
                    {
                        if(!IsCombatActive(caught.target)||caught.target.positionRevision!=caught.revision)
                        {caught.attached=false;caught.branch?.Cancel();continue;}
                        PlayFrogSound(source,FrogSound.Hit,caught.target.model.transform.position,.8f);
                        dealt+=ApplySkillDamage(source,caught.target,source.damage*skill.damageMultiplier*
                            damageMultiplier*FrogCombatRules.TranscendentSecondaryDamageRatio);
                        hits++;
                        if(IsCombatActive(caught.target)&&MonsterTraitRuntime.Has(
                               source.activeTraitIds,FrogCombatRules.BuffThiefTraitId))
                        {
                            ApplyFrogBuffTheft(source,caught.target);
                            caught.branch?.ShowBuffTransfer(new Color(.35f,1f,.78f));
                        }
                    }
                }
            }
            source.currentAction="tongue_tension";
            yield return new WaitForSeconds(FrogCombatRules.TongueTensionDuration);
            if(generation!=combatGeneration||!IsCombatActive(source)||
               !IsCombatActive(target)||source.positionRevision!=sourceRevision||
               target.positionRevision!=targetRevision||
               source.tongueHarpoonTarget!=target)yield break;

            Vector3 pullDirection=Flat(source.model.transform.position)-
                Flat(target.model.transform.position);
            pulled=BeginFrogHarpoonDisplacement(target,pullDirection,
                TileSize*FrogCombatRules.PullDistanceTiles,slam?FrogCombatRules.SlamHeight:0f,true,slam);
            targetRevision=target.positionRevision;
            foreach(FrogHarpoonCatch caught in catches)
            {
                if(!caught.attached||!IsCombatActive(caught.target)||caught.target.positionRevision!=caught.revision)
                {caught.attached=false;caught.branch?.Cancel();continue;}
                Vector3 direction=sourcePosition-Flat(caught.target.model.transform.position);
                caught.pulled=BeginFrogHarpoonDisplacement(caught.target,direction,
                    TileSize*FrogCombatRules.PullDistanceTiles,slam?FrogCombatRules.SlamHeight:0f,true,slam);
                caught.revision=caught.target.positionRevision;
            }
            recoiled=BeginFrogHarpoonDisplacement(source,pullDirection,
                TileSize*FrogCombatRules.RecoilDistanceTiles,
                FrogCombatRules.RecoilHopHeight,false,slam);
            if(pulled||recoiled||catches.Any(caught=>caught.pulled))
                PlayFrogSound(source,FrogSound.Pull,source.model.transform.position,slam?1.1f:.9f);
            source.currentAction="tongue_recoil_hop";
            while((recoiled&&source.displacing)||(pulled&&target.displacing)||
                  catches.Any(caught=>caught.attached&&caught.pulled&&caught.target.displacing))
            {
                if(generation!=combatGeneration||!IsCombatActive(source)||
                   !IsCombatActive(target)||source.positionRevision!=sourceRevision||
                   target.positionRevision!=targetRevision||
                   source.tongueHarpoonTarget!=target)yield break;
                foreach(FrogHarpoonCatch caught in catches)
                    if(caught.attached&&(!IsCombatActive(caught.target)||caught.target.positionRevision!=caught.revision))
                    {
                        caught.attached=false;caught.branch?.Cancel();
                        if(caught.pulled&&caught.target.positionRevision==caught.revision)
                            EndFrogHarpoonDisplacement(caught.target);
                    }
                yield return null;
            }
            if(generation!=combatGeneration||!IsCombatActive(source)||
               !IsCombatActive(target)||source.positionRevision!=sourceRevision||
               target.positionRevision!=targetRevision||
               source.tongueHarpoonTarget!=target)yield break;
            landed=true;
            source.tongueWhip?.Release();
            source.currentAction="tongue_landing";
            Vector3 returnPosition=target!=null&&target.model!=null
                ?Flat(target.model.transform.position):sourcePosition;
            if(slam)PlayFrogTongueSlamImpact(source,target,returnPosition);
            else PlayFrogSound(source,FrogSound.Hit,returnPosition,1.1f);
            if(generation==combatGeneration&&IsCombatActive(source)&&
               IsCombatActive(target))
            {
                dealt+=ApplySkillDamage(source,target,
                    source.damage*skill.secondaryDamageMultiplier*damageMultiplier);
                hits++;
                if(IsCombatActive(target))
                {
                    if(MonsterTraitRuntime.Has(source.activeTraitIds,FrogCombatRules.ReflexSnatchTraitId))
                        DrainFrogCooldownCharge(source,target);
                    if(slam)ApplyFrogSlamKnockdown(source,target);
                    target.frogSlowRatio=Mathf.Max(
                        target.frogSlowRatio,Mathf.Clamp01(skill.statusValue));
                    target.frogSlowTimer=Mathf.Max(target.frogSlowTimer,
                        HostileStatusDuration(target,skill.statusDurationSeconds)*ConcertDurationScale(source));
                    SetTarget(source,target);
                }
            }
            foreach(FrogHarpoonCatch caught in catches)
            {
                Unit enemy=caught.target;
                if(!caught.attached||!IsCombatActive(enemy)||enemy.positionRevision!=caught.revision)continue;
                if(slam)PixelCombatEffect.PlayFrogTongueSlamImpact(Flat(enemy.model.transform.position),
                    enemy.spriteAnimation==null?null:enemy.spriteAnimation.GetComponent<SpriteRenderer>());
                dealt+=ApplySkillDamage(source,enemy,source.damage*skill.secondaryDamageMultiplier*
                    damageMultiplier*FrogCombatRules.TranscendentSecondaryDamageRatio);
                hits++;
                if(!IsCombatActive(enemy))continue;
                if(MonsterTraitRuntime.Has(source.activeTraitIds,FrogCombatRules.ReflexSnatchTraitId))
                    DrainFrogCooldownCharge(source,enemy);
                if(slam)ApplyFrogSlamKnockdown(source,enemy);
                enemy.frogSlowRatio=Mathf.Max(enemy.frogSlowRatio,Mathf.Clamp01(skill.statusValue));
                enemy.frogSlowTimer=Mathf.Max(enemy.frogSlowTimer,
                    HostileStatusDuration(enemy,skill.statusDurationSeconds)*ConcertDurationScale(source));
            }
            if(generation==combatGeneration&&IsCombatActive(source)&&
               MonsterTraitRuntime.Has(
                   source.activeTraitIds,FrogCombatRules.RokrokTraitId))
            {
                int splashHits=0;
                float radius=TileSize*FrogCombatRules.ExplosiveSalivaRadiusTiles*
                             Mathf.Max(0.01f,radiusMultiplier);
                for(int i=0;i<units.Count;i++)
                {
                    Unit enemy=units[i];
                    if(enemy==target||!IsCombatActive(enemy)||enemy.team==source.team||
                       Vector3.Distance(returnPosition,
                           Flat(enemy.model.transform.position))>radius)continue;
                    dealt+=ApplySkillDamage(source,enemy,
                        source.damage*FrogCombatRules.ExplosiveSalivaDamageRatio*
                        damageMultiplier);
                    hits++;
                    splashHits++;
                }
                if(splashHits>0)source.traitActivations++;
                SpriteRenderer targetRenderer=target==null||target.spriteAnimation==null
                    ?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
                PixelGroundCastTelegraph field=PixelCombatEffect.PlayGroundAreaTelegraph(
                    "Rokrok Explosive Saliva Area",returnPosition,radius,0.4f,
                    skillRadiusMarkerMaterial,targetRenderer,
                    new Color(0.48f,0.9f,0.08f,0.4f));
                field.HoldFilled(0.4f);
                PixelStarProjectile.PlaySpiritLeafImpact(
                    returnPosition+Vector3.up*0.25f,targetRenderer,
                    new Color(0.62f,1f,0.08f),"Rokrok Saliva Explosion",
                    0.55f,1.25f,0.25f,0.12f);
            }
        }
        finally
        {
            if(generation==combatGeneration&&IsCombatActive(source)&&dealt>0f&&
               MonsterTraitRuntime.Has(
                   source.activeTraitIds,FrogCombatRules.FroskTraitId))
            {
                Unit ally=units.Where(candidate=>IsCombatActive(candidate)&&
                        !candidate.augmentShadowClone&&candidate.team==source.team&&
                        candidate.hp<candidate.maxHp)
                    .OrderBy(candidate=>candidate.hp/Mathf.Max(1f,candidate.maxHp))
                    .FirstOrDefault();
                if(ally!=null)
                {
                    Heal(ally,FrogCombatRules.SoulHealing(dealt));
                    SpriteRenderer allyRenderer=ally.spriteAnimation==null
                        ?null:ally.spriteAnimation.GetComponent<SpriteRenderer>();
                    PixelStarProjectile.PlaySpiritLeafImpact(
                        ally.model.transform.position+Vector3.up*0.55f,allyRenderer,
                        new Color(0.3f,1f,0.62f),"Frosk Soul Recovery",
                        0.25f,0.72f,-0.12f,0.1f);
                    source.traitActivations++;
                }
            }
            if(generation==combatGeneration)
            {
                if(recoiled&&source.positionRevision==sourceRevision)
                    EndFrogHarpoonDisplacement(source);
                if(pulled&&target.positionRevision==targetRevision)
                    EndFrogHarpoonDisplacement(target);
                foreach(FrogHarpoonCatch caught in catches)
                {
                    if(caught.pulled&&caught.target.positionRevision==caught.revision)
                        EndFrogHarpoonDisplacement(caught.target);
                    if(!landed)caught.branch?.Cancel();
                }
                if(source.tongueHarpoonTarget==target)
                {
                    source.tongueHarpoonTarget=null;
                    if(!landed)source.tongueWhip?.Cancel();
                }
                source.skillHits+=hits;
                source.skillDamage+=dealt;
                RecordSkillEvent(source,skill.id,hits,dealt);
            }
        }
    }

    private bool BeginFrogHarpoonDisplacement(
        Unit unit,Vector3 direction,float distance,float arcHeight,bool interrupt,bool slam)
    {
        if(!DisplaceUnit(unit,direction,distance,interrupt,allowInPlace:slam&&interrupt))return false;
        unit.displacementDuration=slam?FrogCombatRules.SlamDuration:FrogCombatRules.PullDuration;
        unit.displacementArcHeight=arcHeight;
        unit.displacementCheckUnits=true;
        unit.displacementSlam=slam&&interrupt;
        unit.attackMovementLockTimer=Mathf.Max(unit.attackMovementLockTimer,
            unit.displacementDuration+DisplacementRecoveryDuration);
        return true;
    }

    private static void EndFrogHarpoonDisplacement(Unit unit)
    {
        unit.displacing=false;
        unit.displacementArcHeight=0f;
        unit.displacementCheckUnits=false;
        unit.displacementSlam=false;
        if(unit.model!=null)
            unit.model.transform.position=Flat(unit.model.transform.position)+
                Vector3.up*unit.visualHeightOffset;
    }

    private void DrainFrogCooldownCharge(Unit source,Unit target)
    {
        if(target.combatStatuses.RejectHarmfulEffect())return;
        float remaining=Mathf.Max(0f,target.skillTimer);
        float charged=Mathf.Max(0f,target.skillCooldownDuration-remaining);
        if(charged<=0f)return;
        target.skillTimer=remaining+charged*(HasFamilyTranscendence(source)
            ?FrogCombatRules.TranscendentChargeDrainRatio:.5f);
        PlayTraitBurst(target,new Color(0.38f,0.86f,1f),true);
        source.traitActivations++;
    }

    private void PlayFrogTongueSlamImpact(Unit source,Unit target,Vector3 position)
    {
        PlayFrogSound(source,FrogSound.Slam,position,HasFamilyTranscendence(source)?1.2f:1f);
        SpriteRenderer renderer=target.spriteAnimation==null?null:
            target.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelCombatEffect.PlayFrogTongueSlamImpact(position,renderer);
        meadowAmbientParticles?.Impact(position,TileSize,renderer);
        combatCameraDirector?.ReportGroundSlam();
        source.traitActivations++;
    }

    private void ApplyFrogSlamKnockdown(Unit source,Unit target)
    {
        if(target.combatStatuses.ControlImmune||target.combatStatuses.DebuffImmune)return;
        float duration=HostileStatusDuration(target,HasFamilyTranscendence(source)
            ?FrogCombatRules.TranscendentKnockdownDuration:FrogCombatRules.SlamKnockdownDuration);
        if(duration<=0f)return;
        target.combatStatuses.ApplyTimed(CombatStatusKind.Knockdown,duration,source);
        target.spriteAnimation?.PlayKnockdown(duration);
    }

    private void ApplyFrogBuffTheft(Unit source,Unit target)
    {
        if(HasFamilyTranscendence(source)){ApplyAllFrogBuffTheft(source,target);return;}
        bool boss=target.definition!=null&&target.definition.isBoss;
        FrogStolenBuffKind kind;
        float magnitude;
        if(!TryTakeFrogBuff(source,target,boss,out kind,out magnitude))return;
        ApplyFrogStolenBuff(source,source,kind,magnitude);
        PlayFrogSound(source,FrogSound.Steal,source.model.transform.position);
        source.tongueWhip?.ShowBuffTransfer(new Color(0.35f,1f,0.78f));
        PlayTraitBurst(target,new Color(0.54f,0.18f,0.92f),true);
        source.traitActivations++;
    }

    private static float CurrentFrogStolenBuff(Unit unit,FrogStolenBuffKind kind)
    {
        if(unit==null)return 0f;
        float value=unit.frogStolenBuffTimer>0f&&unit.frogStolenBuffKind==kind
            ?unit.frogStolenBuffMagnitude:0f;
        foreach(FrogStolenBuff buff in unit.frogStolenBuffs)
            if(buff.remaining>0f&&buff.kind==kind)
                value=kind==FrogStolenBuffKind.DamageReduction
                    ?1f-(1f-value)*(1f-Mathf.Clamp01(buff.magnitude)):value+buff.magnitude;
        return value;
    }

    private static void ReceiveAllFrogBuff(Unit source,FrogStolenBuffKind kind,float magnitude)
    {
        if(magnitude<=0f)return;
        if(source.combatStatuses.RejectBenefit(kind==FrogStolenBuffKind.Shield?CombatBenefitKind.Shield:CombatBenefitKind.Enhancement))return;
        if(kind==FrogStolenBuffKind.Shield)
        {
            CombatStatusEffect shield=source.combatStatuses.Get(CombatStatusKind.Shield);
            float previous=shield==null?0f:shield.magnitude;
            shield=source.combatStatuses.ApplyShield(FrogCombatRules.BuffTheftDuration,magnitude,source);
            shield.magnitude=previous+magnitude*Mathf.Max(0f,source.combatStatuses.shieldGainMultiplier)*GuardianShieldMultiplier(source);
        }
        else source.frogStolenBuffs.Add(new FrogStolenBuff{kind=kind,magnitude=magnitude*Rank2BuffMultiplier(source),
            remaining=FrogCombatRules.BuffTheftDuration});
    }

    private static bool TakeAllFrogStat(Unit source,FrogStolenBuffKind kind,
        ref float magnitude,float timer)
    {
        if(timer<=0f||magnitude<=0f)return false;
        ReceiveAllFrogBuff(source,kind,magnitude);
        magnitude=0f;
        return true;
    }

    private void ApplyAllFrogBuffTheft(Unit source,Unit target)
    {
        bool stolen=false;
        if(target.spiritLifeReturnTimer>0f)
        {
            GrantSpiritLifeReturn(source,target.spiritLifeReturnTimer);
            target.spiritLifeReturnTimer=0f;stolen=true;
        }
        float shield=TotalVisibleShield(target);
        if(shield>0f)
        {
            RemoveVisibleShield(target,shield);
            ReceiveAllFrogBuff(source,FrogStolenBuffKind.Shield,shield);
            stolen=true;
        }
        if(target.frogStolenBuffTimer>0f&&target.frogStolenBuffMagnitude>0f)
        {
            ReceiveAllFrogBuff(source,target.frogStolenBuffKind,target.frogStolenBuffMagnitude);
            ClearFrogStolenBuff(target);stolen=true;
        }
        for(int i=target.frogStolenBuffs.Count-1;i>=0;i--)
        {
            FrogStolenBuff buff=target.frogStolenBuffs[i];
            if(buff.remaining<=0f||buff.magnitude<=0f)continue;
            ReceiveAllFrogBuff(source,buff.kind,buff.magnitude);
            target.frogStolenBuffs.RemoveAt(i);stolen=true;
        }
        if(target.tyrannoFeedingReady)
        {
            ReceiveAllFrogBuff(source,FrogStolenBuffKind.AttackDamage,TyrannoCombatRules.FeedingBonusDamageRatio);
            target.tyrannoFeedingReady=false;target.combatEffectIcons.Hide(CombatEffectIconKind.AttackUp);stolen=true;
        }
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.AttackDamage,ref target.rank3AttackBonusRatio,target.rank3AttackBonusTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.AttackSpeed,ref target.itemAttackSpeedBonus,target.itemAttackSpeedTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.AttackSpeed,ref target.itemPostSkillAttackSpeedBonus,target.itemPostSkillAttackSpeedTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.AttackSpeed,ref target.itemStatusRecoveryAttackSpeedBonus,target.itemStatusRecoveryAttackSpeedTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.AttackSpeed,ref target.familyAttackSpeedBonus,target.familyAttackSpeedTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.AttackSpeed,ref target.rank3AttackSpeedBonusRatio,target.rank3AttackSpeedBonusTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.Defense,ref target.itemTemporaryDefenseBonus,target.itemTemporaryStatTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.Defense,ref target.itemPostSkillDefenseBonus,target.itemPostSkillStatTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.Defense,ref target.itemTwilightDefenseBonus,target.itemTwilightStatTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.DefenseRatio,ref target.rank3DefenseBonusRatio,target.rank3DefenseBonusTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.Resistance,ref target.itemTemporaryResistanceBonus,target.itemTemporaryStatTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.Resistance,ref target.itemPostSkillResistanceBonus,target.itemPostSkillStatTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.Resistance,ref target.itemTwilightResistanceBonus,target.itemTwilightStatTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.MoveSpeed,ref target.familyMoveSpeedBonus,target.familyMoveSpeedTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.MoveSpeed,ref target.rank3MoveSpeedBonusRatio,target.rank3MoveSpeedBonusTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.MoveSpeed,ref target.mammothHasteRatio,target.mammothHasteTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.DamageReduction,ref target.familyDamageReductionRatio,target.familyDamageReductionTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.AttackSpeed,ref target.bearResolveAttackSpeedBonus,target.bearResolveTimer);
        stolen|=TakeAllFrogStat(source,FrogStolenBuffKind.DamageReduction,ref target.bearResolveDamageReduction,target.bearResolveTimer);
        if(target.crocodileToughHideTimer>0f)
        {
            ReceiveAllFrogBuff(source,FrogStolenBuffKind.DamageReduction,CrocodileCombatRules.ToughScalesDamageReduction);
            target.crocodileToughHideTimer=0f;stolen=true;
        }
        if(target.packHuntSpeedTimer>0f)
        {
            ReceiveAllFrogBuff(source,FrogStolenBuffKind.MoveSpeed,.35f);
            target.packHuntSpeedTimer=0f;stolen=true;
        }
        if(target.wolfChaseTimer>0f)
        {
            ReceiveAllFrogBuff(source,FrogStolenBuffKind.MoveSpeed,WolfCombatRules.ChaseMoveSpeedBonusFor(target.wolfChaseEnhanced));
            target.wolfChaseTimer=0f;stolen=true;
        }
        if(target.guardTimer>0f)
        {
            ReceiveAllFrogBuff(source,FrogStolenBuffKind.DamageReduction,.35f);
            target.guardTimer=0f;stolen=true;
        }
        if(target.rank3ForceImmuneTimer>0f)
        {
            target.rank3ForceImmuneTimer=0f;
            source.rank3ForceImmuneTimer=GateHaetaeBenefit(source,Mathf.Max(source.rank3ForceImmuneTimer,FrogCombatRules.BuffTheftDuration));
            stolen=true;
        }
        if(target.itemOpeningImmunityTimer>0f)
        {
            target.itemOpeningImmunityTimer=0f;
            source.itemOpeningImmunityTimer=GateHaetaeBenefit(source,Mathf.Max(source.itemOpeningImmunityTimer,FrogCombatRules.BuffTheftDuration));
            stolen=true;
        }
        if(target.frogRoyalAttackSpeedTimer>0f)
        {
            ReceiveAllFrogBuff(source,FrogStolenBuffKind.AttackSpeed,FrogCombatRules.RoyalAttackSpeedBonus*target.frogRoyalBuffScale);
            ReceiveAllFrogBuff(source,FrogStolenBuffKind.ResistanceRatio,FrogCombatRules.RoyalResistanceBonus*target.frogRoyalBuffScale);
            target.frogRoyalAttackSpeedTimer=0f;stolen=true;
        }
        if(target.kingKongRallyTimer>0f)
        {
            ReceiveAllFrogBuff(source,FrogStolenBuffKind.AttackSpeed,KingKongCombatRules.RallyAttackSpeedBonus);
            target.kingKongRallyTimer=0f;stolen=true;
        }
        if(target.giraffeDanceAttackSpeedTimer>0f)
        {
            ReceiveAllFrogBuff(source,FrogStolenBuffKind.AttackSpeed,GiraffeCombatRules.MoonwalkAttackSpeedBonus);
            target.giraffeDanceAttackSpeedTimer=0f;stolen=true;
        }
        CombatStatusEffect rally=target.combatStatuses.Get(CombatStatusKind.ComboRally);
        if(rally!=null)
        {
            ReceiveAllFrogBuff(source,FrogStolenBuffKind.AttackSpeed,rally.magnitude);
            target.combatStatuses.Remove(CombatStatusKind.ComboRally);stolen=true;
        }
        // Expired/emptied sources must not keep advertising a removed enhancement.
        if(target.itemAttackSpeedBonus<=0f)target.itemAttackSpeedTimer=0f;
        if(target.itemPostSkillAttackSpeedBonus<=0f)target.itemPostSkillAttackSpeedTimer=0f;
        if(target.itemStatusRecoveryAttackSpeedBonus<=0f)target.itemStatusRecoveryAttackSpeedTimer=0f;
        if(target.familyAttackSpeedBonus<=0f)target.familyAttackSpeedTimer=0f;
        if(target.rank3AttackBonusRatio<=0f)target.rank3AttackBonusTimer=0f;
        if(target.rank3AttackSpeedBonusRatio<=0f)target.rank3AttackSpeedBonusTimer=0f;
        if(target.rank3DefenseBonusRatio<=0f)target.rank3DefenseBonusTimer=0f;
        if(target.familyMoveSpeedBonus<=0f)target.familyMoveSpeedTimer=0f;
        if(target.rank3MoveSpeedBonusRatio<=0f)target.rank3MoveSpeedBonusTimer=0f;
        if(target.mammothHasteRatio<=0f)target.mammothHasteTimer=0f;
        if(target.familyDamageReductionRatio<=0f)target.familyDamageReductionTimer=0f;
        if(!stolen)
        {
            float duration=HostileStatusDuration(target,FrogCombatRules.BuffTheftDuration);
            if(duration>0f)
            {
                ApplyFrogStolenBuff(target,source,FrogStolenBuffKind.AttackSpeed,-FrogCombatRules.FallbackAttackSpeedTheft);
                target.frogStolenBuffTimer=duration;
                target.combatEffectIcons.Hide(CombatEffectIconKind.AttackSpeedDown);
                target.combatEffectIcons.Show(CombatEffectIconKind.AttackSpeedDown,duration);
            }
            ApplyFrogStolenBuff(source,source,FrogStolenBuffKind.AttackSpeed,FrogCombatRules.FallbackAttackSpeedTheft);
        }
        PlayFrogSound(source,FrogSound.Steal,source.model.transform.position,1.15f);
        source.tongueWhip?.ShowBuffTransfer(new Color(.35f,1f,.78f));
        PlayTraitBurst(target,new Color(.54f,.18f,.92f),true);
        source.traitActivations++;
    }

    private bool TryTakeFrogBuff(Unit source,Unit target,bool boss,
        out FrogStolenBuffKind kind,out float magnitude)
    {
        kind=FrogStolenBuffKind.None;
        magnitude=0f;
        float shield=TotalVisibleShield(target);
        if(shield>0f)
        {
            kind=FrogStolenBuffKind.Shield;
            magnitude=FrogCombatRules.StolenShield(source.maxHp,shield,boss);
            if(!boss)RemoveVisibleShield(target,magnitude);
            return magnitude>0f;
        }

        // A Rank 3 thief can also take one of the independently stored Rank 4 buffs.
        foreach(FrogStolenBuff buff in target.frogStolenBuffs.OrderBy(value=>(int)value.kind).ToList())
        {
            if(buff.remaining<=0f||buff.magnitude<=0f)continue;
            kind=buff.kind;magnitude=FrogCombatRules.StolenMagnitude(buff.magnitude,boss);
            if(!boss)target.frogStolenBuffs.Remove(buff);
            return true;
        }

        if(target.frogStolenBuffTimer>0f&&
           target.frogStolenBuffKind==FrogStolenBuffKind.AttackDamage&&
           target.frogStolenBuffMagnitude>0f)
        {
            kind=FrogStolenBuffKind.AttackDamage;
            magnitude=FrogCombatRules.StolenMagnitude(
                target.frogStolenBuffMagnitude,boss);
            if(!boss)ClearFrogStolenBuff(target);
            return true;
        }
        if(target.tyrannoFeedingReady)
        {
            kind=FrogStolenBuffKind.AttackDamage;
            magnitude=FrogCombatRules.StolenMagnitude(
                TyrannoCombatRules.FeedingBonusDamageRatio,boss);
            if(!boss)
            {
                target.tyrannoFeedingReady=false;
                target.combatEffectIcons.Hide(CombatEffectIconKind.AttackUp);
            }
            return true;
        }

        if(target.frogStolenBuffTimer>0f&&
           target.frogStolenBuffKind==FrogStolenBuffKind.AttackSpeed&&
           target.frogStolenBuffMagnitude>0f)
        {
            kind=FrogStolenBuffKind.AttackSpeed;
            magnitude=FrogCombatRules.StolenMagnitude(
                target.frogStolenBuffMagnitude,boss);
            if(!boss)ClearFrogStolenBuff(target);
            return true;
        }
        float attackSpeed=target.itemAttackSpeedTimer>0f&&
                          target.itemAttackSpeedBonus>0f
            ?target.itemAttackSpeedBonus
            :target.frogRoyalAttackSpeedTimer>0f
                ?FrogCombatRules.RoyalAttackSpeedBonus*target.frogRoyalBuffScale
                :target.kingKongRallyTimer>0f
                    ?KingKongCombatRules.RallyAttackSpeedBonus
                :target.mammothHasteTimer>0f&&target.mammothHasteRatio>0f
                        ?target.mammothHasteRatio
                        :target.familyAttackSpeedTimer>0f&&
                         target.familyAttackSpeedBonus>0f
                            ?target.familyAttackSpeedBonus:0f;
        if(attackSpeed>0f)
        {
            kind=FrogStolenBuffKind.AttackSpeed;
            magnitude=FrogCombatRules.StolenMagnitude(attackSpeed,boss);
            if(!boss)ClearTargetAttackSpeedBuff(target);
            return true;
        }

        if(target.frogStolenBuffTimer>0f&&
           target.frogStolenBuffKind==FrogStolenBuffKind.Defense&&
           target.frogStolenBuffMagnitude>0f)
        {
            kind=FrogStolenBuffKind.Defense;
            magnitude=FrogCombatRules.StolenMagnitude(
                target.frogStolenBuffMagnitude,boss);
            if(!boss)ClearFrogStolenBuff(target);
            return true;
        }
        if(target.itemTemporaryStatTimer>0f&&
           target.itemTemporaryDefenseBonus>0f)
        {
            kind=FrogStolenBuffKind.Defense;
            magnitude=FrogCombatRules.StolenMagnitude(
                target.itemTemporaryDefenseBonus,boss);
            if(!boss)target.itemTemporaryDefenseBonus=0f;
            return true;
        }

        if(target.frogStolenBuffTimer>0f&&
           target.frogStolenBuffKind==FrogStolenBuffKind.MoveSpeed&&
           target.frogStolenBuffMagnitude>0f)
        {
            kind=FrogStolenBuffKind.MoveSpeed;
            magnitude=FrogCombatRules.StolenMagnitude(
                target.frogStolenBuffMagnitude,boss);
            if(!boss)ClearFrogStolenBuff(target);
            return true;
        }
        if(target.familyMoveSpeedTimer>0f&&target.familyMoveSpeedBonus>0f)
        {
            kind=FrogStolenBuffKind.MoveSpeed;
            magnitude=FrogCombatRules.StolenMagnitude(
                target.familyMoveSpeedBonus,boss);
            if(!boss)
            {
                target.familyMoveSpeedTimer=0f;
                target.familyMoveSpeedBonus=0f;
            }
            return true;
        }

        kind=FrogStolenBuffKind.AttackSpeed;
        magnitude=FrogCombatRules.StolenMagnitude(
            FrogCombatRules.FallbackAttackSpeedTheft,boss);
        if(!boss)ApplyFrogStolenBuff(target,source,kind,
            -FrogCombatRules.FallbackAttackSpeedTheft);
        return true;
    }

    private static void ClearTargetAttackSpeedBuff(Unit target)
    {
        if(target.itemAttackSpeedTimer>0f&&target.itemAttackSpeedBonus>0f)
        {
            target.itemAttackSpeedTimer=0f;
            target.itemAttackSpeedBonus=0f;
        }
        else if(target.frogRoyalAttackSpeedTimer>0f)
            target.frogRoyalAttackSpeedTimer=0f;
        else if(target.kingKongRallyTimer>0f)
            target.kingKongRallyTimer=0f;
        else if(target.mammothHasteTimer>0f&&target.mammothHasteRatio>0f)
        {
            target.mammothHasteTimer=0f;
            target.mammothHasteRatio=0f;
        }
        else
        {
            target.familyAttackSpeedTimer=0f;
            target.familyAttackSpeedBonus=0f;
        }
    }

    private static void ApplyFrogStolenBuff(Unit recipient,Unit source,
        FrogStolenBuffKind kind,float magnitude)
    {
        if(recipient==null||magnitude==0f)return;
        if(magnitude>0f&&recipient.combatStatuses.RejectBenefit(kind==FrogStolenBuffKind.Shield?CombatBenefitKind.Shield:CombatBenefitKind.Enhancement))return;
        if(kind==FrogStolenBuffKind.Shield)
        {
            recipient.combatStatuses.ApplyShield(
                FrogCombatRules.BuffTheftDuration,magnitude,source);
            return;
        }
        if(recipient.frogStolenBuffTimer<=0f||
           recipient.frogStolenBuffKind!=kind)
            ClearFrogStolenBuff(recipient);
        if(magnitude>0f)magnitude*=Rank2BuffMultiplier(source);
        recipient.frogStolenBuffKind=kind;
        recipient.frogStolenBuffMagnitude=magnitude<0f
            ?Mathf.Min(recipient.frogStolenBuffMagnitude,magnitude)
            :Mathf.Max(recipient.frogStolenBuffMagnitude,magnitude);
        recipient.frogStolenBuffTimer=Mathf.Max(
            recipient.frogStolenBuffTimer,FrogCombatRules.BuffTheftDuration);
        CombatEffectIconKind icon=FrogStolenBuffIcon(kind,recipient.frogStolenBuffMagnitude);
        recipient.combatEffectIcons.Show(icon,FrogCombatRules.BuffTheftDuration);
    }

    private static void ClearFrogStolenBuff(Unit unit)
    {
        if(unit==null)return;
        if(unit.frogStolenBuffKind==FrogStolenBuffKind.None)
        {
            unit.frogStolenBuffMagnitude=0f;
            unit.frogStolenBuffTimer=0f;
            return;
        }
        CombatEffectIconKind icon=FrogStolenBuffIcon(
            unit.frogStolenBuffKind,unit.frogStolenBuffMagnitude);
        unit.combatEffectIcons.Hide(icon);
        unit.frogStolenBuffKind=FrogStolenBuffKind.None;
        unit.frogStolenBuffMagnitude=0f;
        unit.frogStolenBuffTimer=0f;
    }

    private static CombatEffectIconKind FrogStolenBuffIcon(FrogStolenBuffKind kind,float magnitude)
    {
        bool reduced=magnitude<0f;
        switch(kind)
        {
            case FrogStolenBuffKind.AttackDamage:
                return reduced?CombatEffectIconKind.AttackDown:CombatEffectIconKind.AttackUp;
            case FrogStolenBuffKind.Resistance:
            case FrogStolenBuffKind.ResistanceRatio:return CombatEffectIconKind.ResistanceUp;
            case FrogStolenBuffKind.DamageReduction:return CombatEffectIconKind.DamageReduction;
            case FrogStolenBuffKind.DefenseRatio:
            case FrogStolenBuffKind.Defense:
                return reduced?CombatEffectIconKind.DefenseDown:CombatEffectIconKind.DefenseUp;
            case FrogStolenBuffKind.MoveSpeed:
                return reduced?CombatEffectIconKind.MoveSpeedDown:CombatEffectIconKind.MoveSpeedUp;
            case FrogStolenBuffKind.Shield:return CombatEffectIconKind.Shield;
            default:return reduced?CombatEffectIconKind.AttackSpeedDown:CombatEffectIconKind.AttackSpeedUp;
        }
    }

    private static void RemoveVisibleShield(Unit target,float amount)
    {
        float remaining=Mathf.Max(0f,amount);
        remaining=DrainShield(ref target.crocodileShield,remaining);
        remaining=DrainShield(ref target.griffinShield,remaining);
        remaining=DrainShield(ref target.raptorShield,remaining);
        remaining=DrainShield(ref target.kingKongShield,remaining);
        remaining=DrainShield(ref target.bearMountainShield,remaining);
        remaining=DrainShield(ref target.spiritLifeShield,remaining);
        remaining-=target.combatStatuses.AbsorbShield(remaining);
        DrainShield(ref target.itemShield,remaining);
    }

    private static float DrainShield(ref float shield,float amount)
    {
        float drained=Mathf.Min(Mathf.Max(0f,shield),Mathf.Max(0f,amount));
        shield-=drained;
        return amount-drained;
    }

    private void ResolveTongueHarpoonEcho(
        Unit source,Unit target,SkillMasterRow skill)
    {
        if(!IsCombatActive(source)||!IsCombatActive(target))return;
        PlayFrogSound(source,FrogSound.Hit,target.model.transform.position,.7f);
        float dealt=ApplySkillDamage(source,target,
            source.damage*(skill.damageMultiplier+
                           skill.secondaryDamageMultiplier)*0.5f,false);
        source.skillHits++;
        source.skillDamage+=dealt;
        CreateSkillPulse(target,new Color(0.94f,0.22f,0.48f),0.55f);
        RecordSkillEvent(source,skill.id+"_echo",1,dealt);
    }

    private void ApplyKingpaRoyalDecree(Unit source)
    {
        float radius=TileSize*FrogCombatRules.RoyalBuffRadiusTiles;
        Vector3 origin=Flat(source.model.transform.position);
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?null:source.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelSpiritSanctuaryEffect ground=PixelCombatEffect.PlaySpiritSanctuary(
            origin,TileSize*0.75f,FrogCombatRules.RoyalBuffDuration,
            new Color(1f,0.76f,0.18f),sourceRenderer);
        if(ground!=null)ground.name="Kingpa Royal Decree Ground";
        for(int i=0;i<units.Count;i++)
        {
            Unit ally=units[i];
            if(!IsCombatActive(ally)||ally.team!=source.team||
               Vector3.Distance(origin,Flat(ally.model.transform.position))>radius)continue;
            ally.frogRoyalAttackSpeedTimer=GateHaetaeBenefit(ally,Mathf.Max(
                ally.frogRoyalAttackSpeedTimer,FrogCombatRules.RoyalBuffDuration));
            ally.frogRoyalBuffScale=Rank2BuffMultiplier(source);
            SpriteRenderer allyRenderer=ally.spriteAnimation==null
                ?null:ally.spriteAnimation.GetComponent<SpriteRenderer>();
            PixelCombatEffect.PlayKingpaRoyalAura(
                ally.spriteAnimation==null
                    ?ally.model.transform:ally.spriteAnimation.transform,
                allyRenderer,FrogCombatRules.RoyalBuffDuration);
        }
    }

    private bool BeginEarthPulse(Unit unit,SkillMasterRow skill)
    {
        Vector3 origin=Flat(unit.model.transform.position);
        bool worldOverturn=MonsterTraitRuntime.Has(unit.activeTraitIds,KingKongCombatRules.WorldOverturnTraitId);
        float radius=TileSize*(worldOverturn?KingKongCombatRules.WorldOverturnRadiusTiles:skill.radiusTiles)*unit.skillTraitRadiusMultiplier;
        if(!IsCommittingFocusedSkill(unit)&&!units.Any(enemy=>IsCombatActive(enemy)&&enemy.team!=unit.team&&
           IsInsideTraitArea(unit,origin,Flat(enemy.model.transform.position),radius)))
        {
            unit.skillTimer=0.3f;
            return false;
        }
        unit.kingKongPulsePending=true;
        unit.kingKongPulseDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.kingKongPulseRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="earth_pulse_prepare";
        unit.velocity=Vector3.zero;
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(worldOverturn)PlayKingKongSound(unit,KingKongSound.Charge,origin);
        if(unit.spriteAnimation==null)
        {
            if(worldOverturn)
            {
                StartCombatCoroutine(unit,ResolveWorldOverturn(unit,skill,origin,combatGeneration,unit.positionRevision));
                return true;
            }
            float damageMultiplier=unit.kingKongPulseDamageMultiplier;
            ResolveEarthPulseImpact(unit,skill,1f,false,combatGeneration);
            if(MonsterTraitRuntime.Has(unit.activeTraitIds,KingKongCombatRules.TripleEarthPulseTraitId))
            {
                StartCombatCoroutine(unit,ResolveTripleEarthPulse(unit,skill,origin,damageMultiplier,
                    combatGeneration,unit.positionRevision));
                unit.traitActivations++;
            }
        }
        return true;
    }

    private bool ResolveEarthPulseImpact(
        Unit unit,SkillMasterRow skill,float effectScale,bool traitEcho,int generation=-1,
        float radiusTiles=0f,CombatStatusKind controlKind=CombatStatusKind.Airborne,
        float controlDuration=-1f,Vector3? fixedOrigin=null,string eventSuffix=null,bool heavySlam=false)
    {
        if(generation>=0&&generation!=combatGeneration)return false;
        if(!IsCombatActive(unit)||skill==null)return false;
        float damageMultiplier=traitEcho?1f:unit.kingKongPulseDamageMultiplier;
        float radiusMultiplier=traitEcho?1f:unit.kingKongPulseRadiusMultiplier;
        bool worldOverturn=!traitEcho&&MonsterTraitRuntime.Has(unit.activeTraitIds,KingKongCombatRules.WorldOverturnTraitId);
        if(worldOverturn)
        {
            effectScale*=KingKongCombatRules.WorldOverturnDamageRatio;
            radiusTiles=KingKongCombatRules.WorldOverturnRadiusTiles*radiusMultiplier;
            controlKind=CombatStatusKind.Knockdown;
            controlDuration=KingKongCombatRules.WorldOverturnKnockdownDuration;
            heavySlam=true;
            unit.traitActivations++;
        }
        if(!traitEcho)
        {
            unit.kingKongPulsePending=false;
            unit.kingKongPulseDamageMultiplier=1f;
            unit.kingKongPulseRadiusMultiplier=1f;
        }
        Vector3 origin=fixedOrigin??Flat(unit.model.transform.position);
        PlayKingKongSound(unit,worldOverturn?KingKongSound.Overturn:
            heavySlam?KingKongSound.TripleFinish:KingKongSound.Impact,
            origin,worldOverturn?1.1f:eventSuffix=="_triple_followup"?.85f:1f);
        float radius=TileSize*(radiusTiles>0f
            ?radiusTiles:skill.radiusTiles*radiusMultiplier);
        List<Unit> victims=units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=unit.team&&
            IsInsideTraitArea(unit,origin,Flat(enemy.model.transform.position),radius)).ToList();
        SpriteRenderer renderer=unit.spriteAnimation==null
            ?unit.model.GetComponentInChildren<SpriteRenderer>()
            :unit.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelCombatEffect.PlayKingKongGroundSlam(origin,radius,renderer,heavySlam,worldOverturn);
        meadowAmbientParticles?.Impact(origin,radius,renderer);
        combatCameraDirector?.ReportGroundSlam(heavySlam);
        int hits=0;float dealt=0f;
        bool lilas=!traitEcho&&MonsterTraitRuntime.Has(
            unit.activeTraitIds,KingKongCombatRules.LilasTraitId);
        bool bingareu=!traitEcho&&MonsterTraitRuntime.Has(
            unit.activeTraitIds,KingKongCombatRules.BingareuTraitId);
        for(int i=0;i<victims.Count;i++)
        {
            Unit enemy=victims[i];
            if(!IsCombatActive(enemy))continue;
            bool comboControl=HasPriorComboControl(unit,enemy);
            bool comboChill=bingareu&&HasOtherAllyStatus(unit,enemy,CombatStatusKind.ComboChilled);
            float scale=effectScale*damageMultiplier*
                        TraitAreaEffectScale(unit,origin,
                            Flat(enemy.model.transform.position),radius)*
                        (comboControl?KingKongCombatRules.ComboDamageMultiplier:1f)*
                        (comboChill?1f+KingKongCombatRules.GlacialComboDamageBonus:1f);
            dealt+=ApplySkillFormulaDamage(unit,enemy,skill,false,0,scale,!traitEcho);
            hits++;
            PlayTraitBurst(enemy,new Color(1f,0.83f,0.55f),true);
            enemy.reaction?.PlayTintHit(Color.white);
            if(heavySlam)enemy.spriteAnimation?.PlayImpactRecoil(
                Flat(enemy.model.transform.position)-origin,0.13f);
            float appliedControlDuration=controlDuration>=0f
                ?controlDuration:KingKongCombatRules.AirborneDuration+
                    (comboControl?KingKongCombatRules.ComboAirborneBonusDuration:0f);
            appliedControlDuration=HostileStatusDuration(enemy,appliedControlDuration);
            if(appliedControlDuration>0f&&controlKind==CombatStatusKind.Knockdown)
            {
                if(!enemy.combatStatuses.ControlImmune)
                {
                    enemy.combatStatuses.ApplyTimed(
                        controlKind,appliedControlDuration,unit);
                    if(appliedControlDuration>0f)
                        enemy.spriteAnimation?.PlayKnockdown(enemy.combatStatuses.Get(controlKind)?.remaining??0f);
                }
            }
            else if(appliedControlDuration>0f)enemy.combatStatuses.ApplyTimed(
                controlKind,appliedControlDuration,unit,appliedControlDuration);
            if(lilas&&!enemy.combatStatuses.RejectHarmfulEffect())
            {
                enemy.kingKongWeakTimer=Mathf.Max(
                    enemy.kingKongWeakTimer,KingKongCombatRules.LilasWeakDuration*ConcertDurationScale(unit));
                enemy.combatStatuses.ApplyTimed(
                    CombatStatusKind.ComboWeakened,
                    KingKongCombatRules.LilasWeakDuration,unit);
            }
            if(bingareu&&!enemy.combatStatuses.RejectHarmfulEffect())
            {
                enemy.kingKongSlowTimer=Mathf.Max(
                    enemy.kingKongSlowTimer,KingKongCombatRules.GlacialSlowDuration*ConcertDurationScale(unit));
                if(comboChill)
                {
                    enemy.combatStatuses.Remove(CombatStatusKind.ComboChilled);
                    enemy.combatStatuses.ApplyTimed(CombatStatusKind.Freeze,
                        HostileStatusDuration(enemy,KingKongCombatRules.GlacialComboFreezeDuration),unit);
                    PlayFreezeVisual(enemy,enemy.combatStatuses.Get(CombatStatusKind.Freeze)?.remaining??0f);
                }
                else ApplyStackingFrost(
                    unit,enemy,KingKongCombatRules.GlacialSlowDuration,
                    KingKongCombatRules.GlacialChillStacksToFreeze,
                    KingKongCombatRules.GlacialFreezeDuration);
                PlayTraitBurst(enemy,new Color(0.34f,0.82f,1f),false);
                enemy.reaction?.PlayTintHit(new Color(0.34f,0.76f,1f));
            }
        }
        if(!traitEcho&&hits>0)
        {
            SpriteRenderer sourceRenderer=unit.spriteAnimation==null
                ?unit.model.GetComponentInChildren<SpriteRenderer>()
                :unit.spriteAnimation.GetComponent<SpriteRenderer>();
            if(lilas)
            {
                unit.kingKongShield=GateHaetaeBenefit(unit,unit.kingKongShield+unit.maxHp*
                    KingKongCombatRules.LilasShieldPerHitRatio*hits*GuardianShieldMultiplier(unit),CombatBenefitKind.Shield);
                unit.kingKongShieldTimer=KingKongCombatRules.LilasShieldDuration;
                unit.combatStatuses.ApplyTimed(
                    CombatStatusKind.ComboShielded,
                    KingKongCombatRules.LilasShieldDuration,unit);
                PixelHaetaeRoarWave pressure=PixelCombatEffect.PlayHaetaeRoarWave(
                    origin,radius,sourceRenderer,new Color(0.86f,0.62f,1f,0.84f));
                if(pressure!=null)pressure.name="Lilas Royal Pressure Wave";
                PlayTraitBurst(unit,new Color(0.9f,0.72f,1f),true);
                unit.traitActivations++;
            }
            if(MonsterTraitRuntime.Has(
                   unit.activeTraitIds,KingKongCombatRules.MagrilTraitId))
            {
                StartReleasedSkill(unit,ResolveLavaFissure(unit,origin,radius,combatGeneration));
                unit.traitActivations++;
            }
            if(bingareu)
            {
                PixelHaetaeRoarWave glacial=PixelCombatEffect.PlayHaetaeRoarWave(
                    origin,radius,sourceRenderer,new Color(0.22f,0.72f,1f,0.86f));
                if(glacial!=null)glacial.name="Bingareu Glacial Pulse Wave";
                unit.traitActivations++;
            }
            if(MonsterTraitRuntime.Has(
                   unit.activeTraitIds,KingKongCombatRules.MoskaTraitId))
            {
                ApplyLifeResonance(unit,dealt,radius);
                unit.traitActivations++;
            }
        }
        unit.skillHits+=hits;unit.skillDamage+=dealt;
        unit.currentAction="earth_pulse";
        unit.velocity=Vector3.zero;SetMoving(unit,false);
        RecordSkillEvent(unit,skill.id+(eventSuffix??(traitEcho?"_echo":"")),hits,dealt);
        if(!traitEcho&&MonsterTraitRuntime.Has(
               unit.activeTraitIds,KingKongCombatRules.ContinentalFissureTraitId))
        {
            StartReleasedSkill(unit,ResolveContinentalFissure(unit,skill,origin,damageMultiplier,
                generation<0?combatGeneration:generation));
            unit.traitActivations++;
        }
        return hits>0;
    }

    private IEnumerator ResolveTripleEarthPulse(
        Unit source,SkillMasterRow skill,Vector3 origin,float damageMultiplier,
        int generation,int revision)
    {
        // Non-sprite fallback; sprite combat dispatches all three hits from contact frames.
        yield return new WaitForSeconds(KingKongCombatRules.TriplePulseFollowupDelay);
        if(!ResolveTripleEarthPulseHit(source,skill,origin,damageMultiplier,generation,revision,1))yield break;
        yield return new WaitForSeconds(KingKongCombatRules.TriplePulseFinalDelay);
        ResolveTripleEarthPulseHit(source,skill,origin,damageMultiplier,generation,revision,2);
    }

    private bool ResolveTripleEarthPulseHit(
        Unit source,SkillMasterRow skill,Vector3 origin,float damageMultiplier,
        int generation,int revision,int strike)
    {
        if(generation!=combatGeneration||!IsCombatActive(source)||source.positionRevision!=revision)return false;
        bool final=strike==2;
        ResolveEarthPulseImpact(source,skill,damageMultiplier*(final
                ?KingKongCombatRules.TriplePulseFinalDamageRatio:KingKongCombatRules.TriplePulseFollowupDamageRatio),
            true,generation,final?KingKongCombatRules.TriplePulseFinalRadiusTiles:KingKongCombatRules.TriplePulseFollowupRadiusTiles,
            controlDuration:0f,fixedOrigin:origin,eventSuffix:final?"_triple_final":"_triple_followup",heavySlam:final);
        return true;
    }

    private IEnumerator ResolveContinentalFissure(
        Unit source,SkillMasterRow skill,Vector3 origin,float damageMultiplier,int generation)
    {
        if((battleEnding||generation!=combatGeneration))yield break;
        PlayKingKongSound(source,KingKongSound.Fissure,origin);
        float radius=TileSize*KingKongCombatRules.ContinentalFissureRadiusTiles;
        float duration=KingKongCombatRules.ContinentalFissureTravelDuration;
        SpriteRenderer reference=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        GameObject wave=null;
        SpriteRenderer crest=null;
        ParticleSystem debris=null;
        HashSet<Unit> hitTargets=new HashSet<Unit>();
        float elapsed=0f,previousRadius=0f,dealt=0f;
        int hits=0;
        bool reachedEnd=false;
        Action completeCameraEffect=HoldSkillCameraEffect(source);
        try
        {
            wave=PixelCombatEffect.PlayKingKongContinentalFissure(origin,duration,reference);
            crest=wave.GetComponent<SpriteRenderer>();
            debris=wave.GetComponentInChildren<ParticleSystem>();
            while(!battleEnding&&elapsed<duration)
            {
                yield return null;
                if((battleEnding||generation!=combatGeneration)||wave==null)yield break;
                elapsed=Mathf.Min(duration,elapsed+CombatSkillClock.Delta);
                float currentRadius=radius*elapsed/duration;
                wave.transform.localScale=Vector3.one*(currentRadius*2f/crest.sprite.bounds.size.x);
                for(int i=0;i<units.Count;i++)
                {
                    Unit enemy=units[i];
                    if(enemy.team==source.team||!IsCombatTargetable(enemy)||
                       enemy.crocodilePreyFlying||hitTargets.Contains(enemy))continue;
                    Vector3 offset=Flat(enemy.model.transform.position)-origin;
                    if(!KingKongCombatRules.InsideContinentalFissure(
                           offset,currentRadius,previousRadius))continue;
                    hitTargets.Add(enemy);
                    float damage=ApplySkillFormulaDamage(source,enemy,skill,false,0,
                        KingKongCombatRules.ContinentalFissureDamageRatio*damageMultiplier,false);
                    dealt+=damage;hits++;source.skillHits++;source.skillDamage+=damage;
                    PlayTraitBurst(enemy,new Color(1f,0.83f,0.55f),true);
                    enemy.reaction?.PlayTintHit(Color.white);
                    enemy.spriteAnimation?.PlayImpactRecoil(offset,0.1f);
                }
                previousRadius=currentRadius;
            }
            completeCameraEffect?.Invoke();
            reachedEnd=true;
            debris.Stop(false,ParticleSystemStopBehavior.StopEmitting);
            debris.Emit(6);
            for(float fade=0f;fade<0.12f;fade+=CombatSkillClock.Delta)
            {
                if((battleEnding||generation!=combatGeneration)||wave==null)yield break;
                Color tint=crest.color;tint.a=1f-Mathf.Clamp01(fade/0.12f);
                crest.color=tint;
                yield return null;
            }
        }
        finally
        {
            completeCameraEffect?.Invoke();
            if(wave!=null&&!CombatEffectEndFade.IsFading(wave.transform))
            {
                if(crest!=null)crest.enabled=false;
                if(debris!=null)debris.Stop(false,ParticleSystemStopBehavior.StopEmitting);
                Destroy(wave,reachedEnd?0.3f:0f);
            }
            if(generation==combatGeneration)
                RecordSkillEvent(source,skill.id+"_continental_fissure",hits,dealt);
        }
    }

    private IEnumerator ResolveWorldOverturn(
        Unit source,SkillMasterRow skill,Vector3 origin,int generation,int revision)
    {
        // Non-sprite fallback; sprite combat resolves directly on its contact frame.
        var charge=PixelCombatEffect.PlayKingKongWorldOverturnCharge(origin,
            TileSize*KingKongCombatRules.WorldOverturnRadiusTiles*source.kingKongPulseRadiusMultiplier,
            source.model.GetComponentInChildren<SpriteRenderer>());
        try
        {
            float playbackSpeed=Mathf.Max(0.1f,SpriteSkillAttackPlaybackSpeed(source));
            yield return new WaitForSeconds(KingKongCombatRules.WorldOverturnWindupDuration/playbackSpeed);
            if((battleEnding||generation!=combatGeneration)||!IsCombatActive(source)||source.positionRevision!=revision)yield break;
            PlayKingKongSound(source,KingKongSound.Swing,origin,.85f);
            yield return new WaitForSeconds(0.08f/playbackSpeed);
            if((battleEnding||generation!=combatGeneration)||!IsCombatActive(source)||source.positionRevision!=revision)yield break;
            charge.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);
            ResolveEarthPulseImpact(source,skill,1f,false,generation);
        }
        finally
        {
            if(charge!=null&&!CombatEffectEndFade.IsFading(charge))Destroy(charge.gameObject);
        }
    }

    private static float TyrannoWindupSeconds(Unit unit)
    {
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,TyrannoRank3Rules.MassExtinction))return TyrannoRank3Rules.ExtinctionWindup;
        if(HasRank3(unit,TyrannoRank3Rules.TyrantMarch))return TyrannoRank3Rules.MarchWindup;
        return MonsterTraitRuntime.Has(unit.activeTraitIds,TyrannoRank3Rules.PrimordialMaw)
            ?TyrannoRank3Rules.MawWindup:TyrannoCombatRules.TremorCastSeconds;
    }

    private bool BeginTyrantTremor(Unit unit,SkillMasterRow skill)
    {
        if(HasFamilyTranscendence(unit))return BeginTyrannoReign(unit,skill);
        Vector3 origin=Flat(unit.model.transform.position);
        float radius=TileSize*skill.radiusTiles*unit.skillTraitRadiusMultiplier;
        if(HasRank3(unit,TyrannoRank3Rules.MassExtinction))
            radius=TileSize*TyrannoRank3Rules.ExtinctionRadiusTiles*unit.skillTraitRadiusMultiplier;
        else if(HasRank3(unit,TyrannoRank3Rules.PrimordialMaw))
            radius=TileSize*TyrannoRank3Rules.MawRadiusTiles*unit.skillTraitRadiusMultiplier;
        if(!IsCommittingFocusedSkill(unit)&&!units.Any(enemy=>IsCombatActive(enemy)&&enemy.team!=unit.team&&
           Vector3.Distance(origin,Flat(enemy.model.transform.position))<=radius))
        {
            unit.skillTimer=0.3f;
            return false;
        }
        unit.tyrannoTremorPending=true;
        unit.tyrannoTremorDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.tyrannoTremorRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="tyrant_tremor_prepare";
        PlayTyrannoSound(unit,TyrannoSound.Prepare,origin,HasRank3(unit,TyrannoRank3Rules.PrimordialMaw)?.65f:1f);
        unit.attackMovementLockTimer=Mathf.Max(
            unit.attackMovementLockTimer,TyrannoWindupSeconds(unit)+0.25f);
        unit.velocity=Vector3.zero;
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(unit.spriteAnimation==null&&HasRank3(unit,TyrannoRank3Rules.TyrantMarch))
            StartTyrannoMarch(unit,combatGeneration);
        else if(unit.spriteAnimation==null&&HasRank3(unit,TyrannoRank3Rules.PrimordialMaw))
            StartTyrannoMaw(unit,combatGeneration);
        else if(unit.spriteAnimation==null)
            ResolveTyrantTremor(unit,skill,1f,false,combatGeneration);
        return true;
    }

    private bool ResolveTyrantTremor(
        Unit source,SkillMasterRow skill,float effectScale,bool traitEcho,int generation)
    {
        if(generation!=combatGeneration||!IsCombatActive(source)||skill==null)return false;
        if(HasFamilyTranscendence(source))return false;
        float damageMultiplier=traitEcho?1f:source.tyrannoTremorDamageMultiplier;
        float radiusMultiplier=traitEcho?1f:source.tyrannoTremorRadiusMultiplier;
        if(!traitEcho)
        {
            source.tyrannoTremorPending=false;
            source.tyrannoTremorDamageMultiplier=1f;
            source.tyrannoTremorRadiusMultiplier=1f;
        }
        if(!traitEcho&&TryResolveTyrannoRank3(
               source,skill,effectScale*damageMultiplier,generation,radiusMultiplier))return true;
        Vector3 origin=Flat(source.model.transform.position);
        PlayTyrannoSound(source,TyrannoSound.Stomp,origin,traitEcho?.65f:1f);
        float radius=TileSize*skill.radiusTiles*radiusMultiplier;
        List<Unit> victims=units.Where(enemy=>IsCombatActive(enemy)&&
            enemy.team!=source.team&&
            Vector3.Distance(origin,Flat(enemy.model.transform.position))<=radius).ToList();
        bool fissure=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,TyrannoCombatRules.BoneRexTraitId);
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        if(fissure)PixelCombatEffect.PlayTyrannoFissure(
            origin,radius,1.15f,sourceRenderer);
        int hits=0;float dealt=0f;
        for(int i=0;i<victims.Count;i++)
        {
            Unit enemy=victims[i];
            float scale=effectScale*damageMultiplier*
                TraitAreaEffectScale(source,origin,
                    Flat(enemy.model.transform.position),radius);
            PixelCombatEffect.PlayTyrannoTremorHit(
                enemy.model.transform,
                enemy.spriteAnimation==null?null:
                enemy.spriteAnimation.GetComponent<SpriteRenderer>());
            if(!mlEpisodeActive)
                PixelCombatEffect.PlayWolfHuntImpact(enemy.model.transform,Rank3Renderer(enemy),
                    Vector3.down,new Color(1f,.88f,.65f),false,.75f);
            dealt+=ApplySkillFormulaDamage(source,enemy,skill,false,0,scale,!traitEcho);
            hits++;
            if(IsCombatActive(enemy)&&!enemy.combatStatuses.ControlImmune)
            {
                float knockdownDuration=HostileStatusDuration(
                    enemy,Mathf.Max(0f,skill.statusDurationSeconds));
                enemy.combatStatuses.ApplyTimed(
                    CombatStatusKind.Knockdown,knockdownDuration,source);
                if(knockdownDuration>0f)
                    enemy.spriteAnimation?.PlayKnockdown(knockdownDuration);
            }
            if(!fissure||!IsCombatActive(enemy)||enemy.combatStatuses.RejectHarmfulEffect())continue;
            ApplyDefenseShred(source,enemy,TyrannoCombatRules.FissureShredRatio,
                TyrannoCombatRules.FissureDuration);
            enemy.tyrannoResistanceShredRatio=Mathf.Max(
                enemy.tyrannoResistanceShredRatio,TyrannoCombatRules.FissureShredRatio);
            enemy.tyrannoResistanceShredTimer=Mathf.Max(
                enemy.tyrannoResistanceShredTimer,TyrannoCombatRules.FissureDuration);
            enemy.combatEffectIcons.Show(
                CombatEffectIconKind.DefenseDown,TyrannoCombatRules.FissureDuration);
            enemy.combatEffectIcons.Show(
                CombatEffectIconKind.ResistanceDown,TyrannoCombatRules.FissureDuration);
            enemy.reaction?.PlayTintHit(new Color(0.48f,0.16f,0.34f));
            PlayTraitBurst(enemy,new Color(0.42f,0.1f,0.22f),true);
        }
        if(!traitEcho&&hits>0)
        {
            if(MonsterTraitRuntime.Has(
                   source.activeTraitIds,TyrannoCombatRules.TinoTraitId)&&hits>=2)
            {
                source.tyrannoFeedingReady=true;
                source.combatEffectIcons.Show(CombatEffectIconKind.AttackUp);
                PlayTraitBurst(source,new Color(1f,0.24f,0.06f),true);
                PlayTraitBurst(source,new Color(1f,0.78f,0.18f),false);
            }
            if(MonsterTraitRuntime.Has(
                   source.activeTraitIds,TyrannoCombatRules.MagnoTraitId))
                StartReleasedSkill(source,ResolveTyrannoLavaZone(source,origin,radius,combatGeneration));
            if(MonsterTraitRuntime.Has(
                   source.activeTraitIds,TyrannoCombatRules.IronRexTraitId))
            {
                source.combatStatuses.ApplyShield(
                    TyrannoCombatRules.ShieldDuration,
                    TyrannoCombatRules.SteelSkinShield(CurrentDefense(source),hits),source);
                source.reaction?.PlayTintHit(new Color(0.72f,0.88f,1f));
                PlayTraitBurst(source,new Color(0.58f,0.78f,0.94f),true);
                PlayTraitBurst(source,new Color(0.92f,0.96f,1f),false);
            }
            source.traitActivations++;
        }
        source.skillHits+=hits;
        source.skillDamage+=dealt;
        source.currentAction="tyrant_tremor";
        source.velocity=Vector3.zero;
        SetMoving(source,false);
        RecordSkillEvent(source,skill.id+(traitEcho?"_echo":""),hits,dealt);
        return hits>0;
    }

    private IEnumerator ResolveTyrannoLavaZone(
        Unit source,Vector3 origin,float radius,int generation)
    {
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelTyrannoLavaFieldEffect lava=PixelCombatEffect.PlayTyrannoLavaField(
            origin,radius,TyrannoCombatRules.LavaDuration,sourceRenderer);
        int ticks=Mathf.RoundToInt(
            TyrannoCombatRules.LavaDuration/TyrannoCombatRules.LavaTickInterval);
        for(int tick=0;tick<ticks;tick++)
        {
            yield return new WaitForSeconds(TyrannoCombatRules.LavaTickInterval);
            if((battleEnding||generation!=combatGeneration))
            {
                if(lava!=null)lava.Stop();
                yield break;
            }
            int hits=0;float dealt=0f;
            for(int i=0;i<units.Count;i++)
            {
                Unit enemy=units[i];
                if(!IsCombatActive(enemy)||enemy.team==source.team||
                   Vector3.Distance(origin,Flat(enemy.model.transform.position))>radius)continue;
                dealt+=ApplyGroundSkillDamage(source,enemy,
                    source.damage*TyrannoCombatRules.LavaTickDamageRatio,false);
                enemy.reaction?.PlayTintHit(new Color(1f,0.24f,0.02f));
                PlayTraitBurst(enemy,new Color(1f,0.3f,0.02f),false);
                hits++;
            }
            source.skillHits+=hits;
            source.skillDamage+=dealt;
            if(lava!=null)lava.Pulse();
            RecordSkillEvent(source,source.skillId+"_lava",hits,dealt);
        }
    }

    private IEnumerator ResolveLavaFissure(
        Unit source,Vector3 origin,float radius,int generation)
    {
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelSpiritSanctuaryEffect lava=PixelCombatEffect.PlaySpiritSanctuary(
            origin,radius,KingKongCombatRules.LavaDuration,
            new Color(1f,0.2f,0.02f),sourceRenderer);
        if(lava!=null)lava.name="Magril Lava Fissure";
        int ticks=Mathf.RoundToInt(
            KingKongCombatRules.LavaDuration/KingKongCombatRules.LavaTickInterval);
        for(int tick=0;tick<ticks;tick++)
        {
            yield return new WaitForSeconds(KingKongCombatRules.LavaTickInterval);
            if((battleEnding||generation!=combatGeneration))yield break;
            int hits=0;float dealt=0f;
            for(int i=0;i<units.Count;i++)
            {
                Unit enemy=units[i];
                if(!IsCombatActive(enemy)||enemy.team==source.team||
                   Vector3.Distance(origin,Flat(enemy.model.transform.position))>radius)continue;
                bool combo=tick==0&&(HasOtherAllyStatus(source,enemy,CombatStatusKind.Poison)||
                    enemy.itemDefenseShredTimer>0f&&enemy.defenseShredSources.Any(
                        donor=>IsOtherAllySource(source,donor)));
                dealt+=ApplyGroundSkillDamage(source,enemy,
                    source.damage*KingKongCombatRules.LavaTickDamageRatio*
                    (combo?1f+KingKongCombatRules.LavaComboBonus:1f),false);
                PlayTraitBurst(enemy,new Color(1f,0.28f,0.03f),combo);
                enemy.reaction?.PlayTintHit(new Color(1f,0.24f,0.03f));
                enemy.combatStatuses.ApplyTimed(
                    CombatStatusKind.ComboBurning,
                    KingKongCombatRules.LavaDuration,source);
                hits++;
            }
            source.skillHits+=hits;source.skillDamage+=dealt;
            CreateSkillPulseAt(origin,new Color(1f,0.24f,0.03f),radius/TileSize);
            RecordSkillEvent(source,source.skillId+"_lava",hits,dealt);
        }
    }

    private void ApplyLifeResonance(Unit source,float damage,float radius)
    {
        List<Unit> allies=units.Where(ally=>IsCombatActive(ally)&&
            !ally.augmentShadowClone&&ally.team==source.team&&Vector3.Distance(
                Flat(source.model.transform.position),
                Flat(ally.model.transform.position))<=radius).ToList();
        if(allies.Count==0)return;
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelHaetaeRoarWave lifeWave=PixelCombatEffect.PlayHaetaeRoarWave(
            Flat(source.model.transform.position),radius,sourceRenderer,
            new Color(0.36f,1f,0.56f,0.82f));
        if(lifeWave!=null)lifeWave.name="Moska Life Resonance Wave";
        float healing=damage*KingKongCombatRules.LifeHealingRatio/allies.Count;
        for(int i=0;i<allies.Count;i++)
        {
            Unit ally=allies[i];
            Heal(ally,healing);
            if(ally==source)
                PlayTraitBurst(ally,new Color(0.42f,1f,0.62f),false);
            else
                EmitSpiritLight(source,ally,null);
            CombatStatusEffect shield=ally.combatStatuses.Get(CombatStatusKind.Shield);
            bool externalShield=shield!=null&&shield.magnitude>0f&&
                shield.source is Unit donor&&donor!=ally&&donor.team==ally.team;
            if(!externalShield)continue;
            ally.kingKongRallyTimer=GateHaetaeBenefit(ally,Mathf.Max(
                ally.kingKongRallyTimer,KingKongCombatRules.RallyDuration));
            ally.combatStatuses.ApplyTimed(
                CombatStatusKind.ComboRally,KingKongCombatRules.RallyDuration,source);
            PlayTraitBurst(ally,new Color(0.78f,1f,0.28f),false);
        }
    }

    private static bool HasPriorComboControl(Unit source,Unit target)
    {
        CombatStatusEffect airborne=target.combatStatuses.Get(CombatStatusKind.Airborne);
        return target.crocodileImmobilizedTimer>0f||
               target.frogSlowTimer>0f||
               target.combatStatuses.Has(CombatStatusKind.Root)||
               target.combatStatuses.Has(CombatStatusKind.Freeze)||
               target.combatStatuses.Has(CombatStatusKind.Knockdown)||
               airborne!=null&&airborne.source!=source;
    }

    private static bool HasPriorChill(Unit source,Unit target)
    {
        CombatStatusEffect chilled=target.combatStatuses.Get(CombatStatusKind.ComboChilled);
        return target.raptorSlowTimer>0f||
               target.combatStatuses.Has(CombatStatusKind.Freeze)||
               chilled!=null&&chilled.source!=source;
    }

    private static bool IsOtherAllySource(Unit source,object donor)=>
        donor is Unit ally&&ally!=source&&ally.team==source.team;

    private static bool HasOtherAllyStatus(Unit source,Unit target,CombatStatusKind kind)
    {
        CombatStatusEffect effect=target.combatStatuses.Get(kind);
        return effect!=null&&effect.stacks>0&&effect.contributors.Any(donor=>IsOtherAllySource(source,donor));
    }

    private static void ApplyDefenseShred(Unit source,Unit target,float ratio,float duration)
    {
        if(ratio<=0f||duration<=0f)return;
        target.itemDefenseShredRatio=Mathf.Max(target.itemDefenseShredRatio,ratio);
        target.itemDefenseShredTimer=Mathf.Max(target.itemDefenseShredTimer,duration);
        target.defenseShredSources.Apply(source,duration);
    }

    private bool BeginMagicStarBarrage(Unit unit,SkillMasterRow skill)
    {
        if(UsesWizardCygnusShower(unit))return BeginWizardCygnusShower(unit,skill);
        float range=TileSize*Mathf.Max(1f,skill.castRangeTiles);
        List<Unit> plannedTargets=CaptureMagicStarTargets(unit,range);
        if(plannedTargets.Count==0)return false;
        unit.wizardBarrageTargets=plannedTargets;
        unit.wizardBarragePending=true;
        unit.wizardBarrageDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.wizardBarrageFan=CreateWizardStarFan(unit,combatGeneration);
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="magic_star_barrage_prepare";
        unit.velocity=Vector3.zero;
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(unit.spriteAnimation==null)
            StartReleasedSkill(unit,ResolveMagicStarBarrage(unit,skill,1f,false,combatGeneration));
        return true;
    }

    private PixelWizardStarFan CreateWizardStarFan(Unit source,int generation)
    {
        int revision=source.positionRevision;
        SpriteRenderer renderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        Color color=MonsterTraitRuntime.Has(source.activeTraitIds,WizardMouseCombatRules.SeoljwiTraitId)
            ?new Color(0.38f,0.84f,1f):new Color(0.78f,0.38f,1f);
        PlayWizardSound(source,WizardSound.Prepare,source.model.transform.position);
        return PixelWizardStarFan.Play(source.model.transform,renderer,color,
            ()=>generation==combatGeneration&&IsCombatActive(source)&&source.positionRevision==revision);
    }

    private IEnumerator ResolveMagicStarBarrage(
        Unit source,SkillMasterRow skill,float effectScale,bool traitEcho,int generation)
    {
        if((battleEnding||generation!=combatGeneration)||!IsCombatActive(source)||skill==null)yield break;
        int revision=source.positionRevision;
        float range=TileSize*Mathf.Max(1f,skill.castRangeTiles);
        List<Unit> plannedTargets=traitEcho?null:
            source.wizardBarrageTargets??CaptureMagicStarTargets(source,range);
        float damageScale=effectScale*(traitEcho?1f:source.wizardBarrageDamageMultiplier);
        PixelWizardStarFan fan=traitEcho?CreateWizardStarFan(source,generation):source.wizardBarrageFan;
        if(!traitEcho)
        {
            source.wizardBarrageTargets=null;
            source.wizardBarrageFan=null;
            source.wizardBarragePending=false;
            source.wizardBarrageDamageMultiplier=1f;
        }
        bool prepare=traitEcho||source.spriteAnimation==null;
        source.attackMovementLockTimer=Mathf.Max(source.attackMovementLockTimer,
            (prepare?WizardMouseCombatRules.PreparationDuration:0f)+
            WizardMouseCombatRules.ProjectileInterval*(WizardMouseCombatRules.ProjectileCount-1)+0.08f);
        bool focused=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,WizardMouseCombatRules.PatjwiTraitId);
        bool frost=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,WizardMouseCombatRules.SeoljwiTraitId);
        bool refract=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,WizardMouseCombatRules.ByeoljwiTraitId);
        bool milkyWay=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,WizardMouseCombatRules.MilkyWayBarrageTraitId);
        bool pentagram=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,WizardMouseCombatRules.PentagramAnnihilationTraitId);
        bool supernova=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,WizardMouseCombatRules.SupernovaDescentTraitId);
        // Reserve at launch to spread simultaneous shots; count victims only on arrival.
        HashSet<Unit> reservedTargets=new HashSet<Unit>();
        HashSet<Unit> allHitTargets=new HashSet<Unit>();
        Unit focusMarkedTarget=null;
        int hits=0;
        float dealt=0f;
        int pendingSecondary=0;
        int pendingOriginal=0;
        PixelWizardPentagramField pentagramField=null;
        try
        {
            if(prepare)yield return SkillWait(source,WizardMouseCombatRules.PreparationDuration);
            if(supernova)
            {
                yield return ResolveSupernovaDescent(source,skill,range,damageScale,generation,revision,fan,plannedTargets);
                yield break;
            }
            if(!IsCombatActive(source)||source.positionRevision!=revision)yield break;
            float barrageStarted=CombatSkillClock.CurrentTime;
            for(int index=0;index<WizardMouseCombatRules.ProjectileCount;index++)
            {
                if(!ReleasedSkillValid(source,generation))break;
                Unit target=SelectPlannedMagicStarTarget(source,range,reservedTargets,focused,plannedTargets);
                if(target==null)break;
                reservedTargets.Add(target);
                if(focused&&target!=focusMarkedTarget)
                {
                    SpriteRenderer targetRenderer=target.spriteAnimation==null
                        ?target.model.GetComponentInChildren<SpriteRenderer>()
                        :target.spriteAnimation.GetComponent<SpriteRenderer>();
                    PixelCombatEffect.PlayStarMarker(
                        "Patjwi Spiteful Focus Mark",
                        target.spriteAnimation==null?target.model.transform:target.spriteAnimation.transform,
                        targetRenderer,new Color(0.95f,0.18f,0.72f,0.9f),1.1f);
                    focusMarkedTarget=target;
                }
                bool last=index==WizardMouseCombatRules.ProjectileCount-1;
                float raw=WizardMouseCombatRules.ProjectileDamage(
                    source.damage,skill.damageMultiplier,focused,index)*damageScale;
                Color color=frost?new Color(0.38f,0.84f,1f):
                    focused&&last?new Color(0.72f,0.08f,0.62f):new Color(0.78f,0.38f,1f);
                if(last)color=Color.Lerp(color,Color.white,0.35f);
                pendingOriginal++;
                Action arrived=()=>
                {
                    pendingOriginal--;
                    if((battleEnding||generation!=combatGeneration)||!IsCombatActive(target))return;
                    Vector3 impactPosition=Flat(target.model.transform.position);
                    if(pentagram)
                    {
                        if(pentagramField==null)
                        {
                            SpriteRenderer sorting=source.spriteAnimation==null
                                ?source.model.GetComponentInChildren<SpriteRenderer>()
                                :source.spriteAnimation.GetComponent<SpriteRenderer>();
                            pentagramField=PixelWizardPentagramField.Create(impactPosition,
                                TileSize*WizardMouseCombatRules.PentagramRadiusTiles,sorting,
                                skillRadiusMarkerMaterial,()=>this!=null&&!battleEnding&&generation==combatGeneration);
                        }
                        pentagramField.AddStar();
                    }
                    dealt+=ApplyMagicStarArrivalDamage(source,target,raw,color,last?1.25f:1f);
                    hits++;
                    allHitTargets.Add(target);
                    if(frost&&IsCombatActive(target))
                        ApplyStackingFrost(source,target,WizardMouseCombatRules.FrostDuration,
                            WizardMouseCombatRules.FrostStacksToFreeze,WizardMouseCombatRules.FreezeDuration);
                    if(milkyWay)
                    {
                        float fragmentRange=TileSize*WizardMouseCombatRules.MilkyWayFragmentRadiusTiles;
                        List<Unit> fragmentTargets=SelectMilkyWayFragmentTargets(source,target,impactPosition,fragmentRange);
                        if(fragmentTargets.Count>0)PlayWizardSound(source,WizardSound.Split,impactPosition,.8f);
                        for(int fragmentIndex=0;fragmentIndex<fragmentTargets.Count;fragmentIndex++)
                        {
                            Unit fragmentTarget=fragmentTargets[fragmentIndex];
                            pendingSecondary++;
                            LaunchMilkyWayFragment(source,target,fragmentTarget,fragmentIndex,frost,
                                WizardMouseCombatRules.MilkyWayFragmentDamage(source.damage)*damageScale,generation,
                                (hitTarget,hitDamage)=>
                                {
                                    allHitTargets.Add(hitTarget);
                                    hits++;
                                    dealt+=hitDamage;
                                },()=>pendingSecondary--);
                        }
                    }
                    if(refract)
                    {
                        Unit reflected=units.Where(enemy=>IsCombatActive(enemy)&&
                                enemy.team!=source.team&&!reservedTargets.Contains(enemy)&&
                                Vector3.Distance(Flat(source.model.transform.position),
                                    Flat(enemy.model.transform.position))<=
                                range+source.collisionRadius+enemy.collisionRadius)
                            .OrderBy(enemy=>Vector3.Distance(impactPosition,
                                Flat(enemy.model.transform.position))).FirstOrDefault();
                        if(reflected!=null)
                        {
                            reservedTargets.Add(reflected);
                            pendingSecondary++;
                            Color reflectionColor=new Color(0.58f,0.74f,1f);
                            PlayTraitBurst(target,new Color(0.58f,0.84f,1f),false);
                            Action reflectedArrived=()=>
                            {
                                pendingSecondary--;
                                if((battleEnding||generation!=combatGeneration)||!IsCombatActive(reflected))return;
                                dealt+=ApplyMagicStarArrivalDamage(source,reflected,
                                    source.damage*WizardMouseCombatRules.RefractionDamageRatio*damageScale,reflectionColor);
                                allHitTargets.Add(reflected);
                                hits++;
                            };
                            PixelStarProjectile reflection=EmitMagicStar(target,reflected,reflectionColor,false,reflectedArrived);
                            if(reflection!=null)
                            {reflection.SetImpactEnabled(false);reflection.SetCombatOwner(source.model.transform);reflection.OnDeflected=()=>pendingSecondary--;}
                            else reflectedArrived();
                        }
                    }
                };
                PixelStarProjectile projectile=EmitMagicStar(source,target,color,false,arrived);
                if(projectile!=null)
                {
                    projectile.name="Wizard Barrage Star "+(index+1);
                    projectile.OnDeflected=()=>pendingOriginal--;
                    projectile.SetImpactEnabled(false);
                    if(fan!=null)projectile.LaunchFrom(fan.Release(index),index);
                    if(last)projectile.MultiplyVisualScale(focused?1.4f:1.25f);
                    PlayWizardSound(source,WizardSound.Launch,projectile.transform.position,last?1f:.8f);
                }
                else pendingOriginal--;
                if(index<WizardMouseCombatRules.ProjectileCount-1)
                    yield return SkillWait(source,Mathf.Max(0f,barrageStarted+
                        (index+1)*WizardMouseCombatRules.ProjectileInterval-CombatSkillClock.CurrentTime));
            }
        }
        finally
        {
            if(fan!=null&&!CombatEffectEndFade.IsFading(fan))Destroy(fan.gameObject);
        }
        while(!battleEnding&&pendingOriginal>0&&generation==combatGeneration)yield return null;
        if((battleEnding||generation!=combatGeneration))yield break;
        if(pentagramField!=null)
            yield return ResolvePentagramAnnihilation(source,pentagramField,damageScale,generation,allHitTargets);
        while(!battleEnding&&pendingSecondary>0&&generation==combatGeneration)yield return null;
        if((battleEnding||generation!=combatGeneration))yield break;
        if(hits>0&&!traitEcho&&MonsterTraitRuntime.Has(
               source.activeTraitIds,WizardMouseCombatRules.KongjwiTraitId))
        {
            ApplyKongjwiGratefulHealing(source,allHitTargets.Count);
            source.traitActivations++;
        }
        if(!traitEcho&&(focused||frost||refract||milkyWay)&&hits>0)source.traitActivations++;
        source.skillHits+=hits;
        source.skillDamage+=dealt;
        source.currentAction="magic_star_barrage";
        RecordSkillEvent(source,skill.id+(traitEcho?"_echo":""),hits,dealt);
    }

    private void ApplyKongjwiGratefulHealing(Unit source,int distinctTargets)
    {
        Unit ally=SelectLowestHealthAlly(source);
        if(ally==null)return;
        Heal(ally,SkillSupportAmount(source,
            WizardMouseCombatRules.GratefulHealing(source.damage,distinctTargets)));
        CreateSkillPulse(ally,new Color(0.88f,0.76f,1f),0.65f);
        PlayTraitBurst(ally,new Color(0.9f,0.78f,1f),true);
        SpriteRenderer renderer=Rank3Renderer(ally);
        PixelCombatEffect.PlayStarMarker("Kongjwi Grateful Starlight",
            ally.spriteAnimation==null?ally.model.transform:ally.spriteAnimation.transform,
            renderer,new Color(0.92f,0.82f,1f,0.9f),0.75f,0.68f);
    }

    private float ApplyMagicStarArrivalDamage(Unit source,Unit target,float raw,Color color,float visualScale=1f,bool playSound=true,bool groundHit=false)
    {
        SpriteRenderer renderer=target.spriteAnimation==null
            ?target.model.GetComponentInChildren<SpriteRenderer>()
            :target.spriteAnimation.GetComponent<SpriteRenderer>();
        Vector3 position=renderer==null?target.model.transform.position+Vector3.up*0.35f:renderer.bounds.center;
        float damage=groundHit?ApplyGroundSkillDamage(source,target,raw,false):ApplySkillDamage(source,target,raw,false);
        PixelStarProjectile.PlayImpact(position,renderer,color,source.lastSkillHitCritical,false,visualScale);
        if(playSound)PlayWizardSound(source,WizardSound.Hit,position,.8f*visualScale);
        return damage;
    }

    private IEnumerator ResolvePentagramAnnihilation(
        Unit source,PixelWizardPentagramField field,float damageScale,int generation,HashSet<Unit> allHitTargets)
    {
        bool finished=false;
        try
        {
            if(field==null||(battleEnding||generation!=combatGeneration))yield break;
            field.Complete();
            Vector3 center=Flat(field.transform.position);
            PlayWizardSound(source,WizardSound.Complete,center,.8f);
            float radius=TileSize*WizardMouseCombatRules.PentagramRadiusTiles;
            bool frost=MonsterTraitRuntime.Has(source.activeTraitIds,WizardMouseCombatRules.SeoljwiTraitId);
            float started=CombatSkillClock.CurrentTime;
            source.traitActivations++;
            for(int pulse=0;pulse<WizardMouseCombatRules.PentagramPulseCount;pulse++)
            {
                if(pulse>0)yield return new WaitForSeconds(Mathf.Max(0f,
                    started+pulse*WizardMouseCombatRules.PentagramPulseInterval-CombatSkillClock.CurrentTime));
                if(field==null||(battleEnding||generation!=combatGeneration))yield break;
                field.Pulse();
                PlayWizardSound(source,WizardSound.Pulse,center,pulse==2?1.1f:1f);
                int hits=0;float dealt=0f;
                for(int i=0;i<units.Count;i++)
                {
                    Unit enemy=units[i];
                    if(!IsCombatActive(enemy)||enemy.team==source.team||
                       (Flat(enemy.model.transform.position)-center).sqrMagnitude>radius*radius)continue;
                    SpriteRenderer renderer=enemy.spriteAnimation==null
                        ?enemy.model.GetComponentInChildren<SpriteRenderer>()
                        :enemy.spriteAnimation.GetComponent<SpriteRenderer>();
                    field.PlayHitColumn(Flat(enemy.model.transform.position),renderer,pulse==2);
                    dealt+=ApplyMagicStarArrivalDamage(source,enemy,
                        WizardMouseCombatRules.PentagramPulseDamage(source.damage)*damageScale,
                        new Color(0.78f,0.62f,1f),pulse==2?1.2f:0.85f,playSound:false,groundHit:true);
                    hits++;allHitTargets.Add(enemy);
                    if(frost&&IsCombatActive(enemy))
                        ApplyStackingFrost(source,enemy,WizardMouseCombatRules.FrostDuration,
                            WizardMouseCombatRules.FrostStacksToFreeze,WizardMouseCombatRules.FreezeDuration);
                }
                source.skillHits+=hits;source.skillDamage+=dealt;
                RecordSkillEvent(source,source.skillId+"_pentagram_pulse_"+(pulse+1),hits,dealt);
            }
            field.Finish();finished=true;
        }
        finally
        {
            if(!finished&&field!=null)field.Cancel();
        }
    }

    private IEnumerator ResolveSupernovaDescent(Unit source,SkillMasterRow skill,float range,
        float damageScale,int generation,int revision,PixelWizardStarFan fan,List<Unit> plannedTargets=null)
    {
        bool focused=MonsterTraitRuntime.Has(source.activeTraitIds,WizardMouseCombatRules.PatjwiTraitId);
        Unit primary=SelectPlannedMagicStarTarget(source,range,new HashSet<Unit>(),focused,plannedTargets);
        if(primary==null)yield break;
        Vector3 center=Flat(primary.model.transform.position);
        float radius=TileSize*WizardMouseCombatRules.SupernovaRadiusTiles;
        SpriteRenderer renderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>():source.spriteAnimation.GetComponent<SpriteRenderer>();
        Color color=WizardMouseCombatRules.SupernovaColor(source.definition==null?null:source.definition.monsterId);
        bool launched=false,finished=false;
        Func<bool> valid=()=>ReleasedSkillValid(source,generation)&&
            (launched||IsCombatActive(source)&&source.positionRevision==revision);
        PixelWizardSupernova meteor=PixelWizardSupernova.Create(center,source.model.transform.position,
            radius,renderer,color,valid);
        try
        {
            float started=CombatSkillClock.CurrentTime;
            for(int i=0;i<WizardMouseCombatRules.ProjectileCount;i++)
            {
                if(!valid())yield break;
                Vector3 start=fan!=null?fan.Release(i):
                    (renderer==null?source.model.transform.position+Vector3.up:renderer.bounds.center);
                launched=true;meteor.Launch(start,i);
                PlayWizardSound(source,WizardSound.Launch,start,.8f);
                if(i<WizardMouseCombatRules.ProjectileCount-1)
                    yield return new WaitForSeconds(Mathf.Max(0f,
                        started+(i+1)*WizardMouseCombatRules.ProjectileInterval-CombatSkillClock.CurrentTime));
            }
            launched=true;
            yield return new WaitForSeconds(WizardMouseCombatRules.SupernovaAscentDuration);
            if(!valid()||meteor==null)yield break;
            meteor.BeginDescent();
            PlayWizardSound(source,WizardSound.Descent,center);
            yield return new WaitForSeconds(WizardMouseCombatRules.SupernovaDelay-WizardMouseCombatRules.SupernovaPullDuration);
            if(!valid()||meteor==null)yield break;
            foreach(Unit enemy in units)
            {
                if(!IsCombatActive(enemy)||enemy.team==source.team)continue;
                Vector3 direction=center-Flat(enemy.model.transform.position);
                if(direction.sqrMagnitude>radius*radius)continue;
                float distance=Mathf.Min(direction.magnitude,TileSize*WizardMouseCombatRules.SupernovaPullTiles);
                if(DisplaceUnit(enemy,direction,distance))
                    enemy.displacementDuration=WizardMouseCombatRules.SupernovaPullDuration;
            }
            yield return new WaitForSeconds(WizardMouseCombatRules.SupernovaPullDuration);
            if(!valid()||meteor==null)yield break;
            if(meteor.DeflectBeforeImpact())yield break;
            meteor.Impact();
            PlayWizardSound(source,WizardSound.Crash,center,1.15f);
            combatCameraDirector?.ReportGroundSlam(true);
            meadowAmbientParticles?.Impact(center,radius,renderer);
            bool frost=MonsterTraitRuntime.Has(source.activeTraitIds,WizardMouseCombatRules.SeoljwiTraitId);
            float stored=WizardMouseCombatRules.SupernovaStoredStarDamage(source.damage,skill.damageMultiplier,focused);
            int hits=0;float dealt=0f;
            foreach(Unit enemy in units)
            {
                if(!IsCombatActive(enemy)||enemy.team==source.team||
                   (Flat(enemy.model.transform.position)-center).sqrMagnitude>radius*radius)continue;
                float damage=WizardMouseCombatRules.SupernovaDamage(source.damage)+(enemy==primary?stored:0f);
                dealt+=ApplyMagicStarArrivalDamage(source,enemy,damage*damageScale,color,1.5f,playSound:false);
                hits++;
                if(!IsCombatActive(enemy))continue;
                if(!enemy.combatStatuses.ControlImmune)
                {
                    float duration=HostileStatusDuration(enemy,WizardMouseCombatRules.SupernovaKnockdownDuration);
                    if(duration>0f)
                    {
                        enemy.combatStatuses.ApplyTimed(CombatStatusKind.Knockdown,duration,source);
                        enemy.spriteAnimation?.PlayKnockdown(duration);
                    }
                }
                if(frost)ApplyStackingFrost(source,enemy,WizardMouseCombatRules.FrostDuration,
                    WizardMouseCombatRules.FrostStacksToFreeze,WizardMouseCombatRules.FreezeDuration);
            }
            source.skillHits+=hits;source.skillDamage+=dealt;source.traitActivations++;
            RecordSkillEvent(source,source.skillId+"_supernova_descent",hits,dealt);
            if(hits>0&&MonsterTraitRuntime.Has(source.activeTraitIds,WizardMouseCombatRules.KongjwiTraitId))
            {
                ApplyKongjwiGratefulHealing(source,hits);
            }
            if(hits>0&&MonsterTraitRuntime.Has(source.activeTraitIds,WizardMouseCombatRules.ByeoljwiTraitId))
            {
                float refractRadius=TileSize*WizardMouseCombatRules.SupernovaRefractionRadiusTiles;
                Unit reflected=units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=source.team&&enemy!=primary&&
                    (Flat(enemy.model.transform.position)-center).sqrMagnitude<=refractRadius*refractRadius)
                    .OrderBy(enemy=>(Flat(enemy.model.transform.position)-center).sqrMagnitude).FirstOrDefault();
                if(reflected!=null)
                {
                    SpriteRenderer sorting=reflected.spriteAnimation==null
                        ?reflected.model.GetComponentInChildren<SpriteRenderer>():reflected.spriteAnimation.GetComponent<SpriteRenderer>();
                    var star=PixelStarProjectile.Play(meteor.transform,null,reflected.model.transform,sorting,color,false,()=>
                    {
                        if((battleEnding||generation!=combatGeneration)||!IsCombatActive(reflected))return;
                        float damage=ApplyMagicStarArrivalDamage(source,reflected,
                            source.damage*WizardMouseCombatRules.RefractionDamageRatio*damageScale,color);
                        source.skillHits++;source.skillDamage+=damage;
                        RecordSkillEvent(source,source.skillId+"_supernova_refraction",1,damage);
                    });
                    if(star!=null){star.name="Supernova Refraction Star";star.SetImpactEnabled(false);star.SetCombatOwner(source.model.transform);}
                }
            }
            source.currentAction="supernova_descent";
            finished=true;
        }
        finally
        {
            if(!finished&&meteor!=null)meteor.Cancel();
        }
    }


    private bool BeginAcrobaticBarrage(Unit unit,SkillMasterRow skill)
    {
        Unit target=unit.target;
        if(!IsCombatActive(target))return false;
        float range=TileSize*Mathf.Max(1f,skill.castRangeTiles)+
                    unit.collisionRadius+target.collisionRadius;
        if(!IsWithinCommittedSkillReach(unit,target,range))
            return false;
        unit.monkeyBarragePending=true;
        unit.monkeyBarrageTarget=target;
        unit.monkeyBarrageCenter=Flat(target.model.transform.position);
        unit.monkeyBarrageDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.monkeyBarrageRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="acrobatic_barrage_prepare";
        unit.velocity=Vector3.zero;
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(HasFamilyTranscendence(unit))
        {
            BeginMonkeyStorm(unit,target,skill);
            return true;
        }
        if(unit.spriteAnimation==null)
            StartReleasedSkill(unit,ResolveAcrobaticBarrage(unit,target,skill,1f,false,combatGeneration));
        return true;
    }

    private IEnumerator ResolveAcrobaticBarrage(
        Unit source,Unit initialTarget,SkillMasterRow skill,
        float effectScale,bool traitEcho,int generation)
    {
        if((battleEnding||generation!=combatGeneration)||!IsCombatActive(source)||skill==null)yield break;
        float damageScale=effectScale*
            (traitEcho?1f:source.monkeyBarrageDamageMultiplier);
        float radiusScale=traitEcho?1f:source.monkeyBarrageRadiusMultiplier;
        Vector3 mortarCenter=source.monkeyBarragePending?source.monkeyBarrageCenter:
            initialTarget!=null&&initialTarget.model!=null?Flat(initialTarget.model.transform.position):
            Flat(source.model.transform.position);
        source.monkeyBarragePending=false;
        source.monkeyBarrageTarget=null;
        source.monkeyBarrageDamageMultiplier=1f;
        source.monkeyBarrageRadiusMultiplier=1f;
        source.attackMovementLockTimer=Mathf.Max(
            source.attackMovementLockTimer,
            MonkeyCombatRules.ProjectileInterval*(MonkeyCombatRules.ProjectileCount-1)+.08f);
        bool precise=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,MonkeyCombatRules.ChiwooTraitId);
        bool poison=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,MonkeyCombatRules.TotoTraitId);
        bool cloud=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,MonkeyCombatRules.UnoTraitId);
        bool powder=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,MonkeyCombatRules.MakaTraitId);
        bool kingFruit=!traitEcho&&HasRank3(source,MonkeyRank3Rules.MountainCollapse);
        float range=TileSize*Mathf.Max(1f,skill.castRangeTiles);
        Unit target=initialTarget;
        if(!traitEcho&&HasRank3(source,MonkeyRank3Rules.FiveOrbJuggling))
        {
            yield return ResolveMonkeyMortar(source,mortarCenter,damageScale,radiusScale,generation);
            yield break;
        }
        if(!traitEcho&&HasRank3(source,MonkeyRank3Rules.MyriadReturn))
        {
            yield return ResolveMonkeyReturningFruit(source,target,damageScale,generation);
            yield break;
        }
        source.attackMovementLockTimer=Mathf.Max(
            source.attackMovementLockTimer,MonkeyCombatRules.BarrageReleaseDuration+.18f);
        Unit previous=null;
        int consecutiveHits=0;
        int hits=0;
        float dealt=0f;
        int pendingProjectiles=0;
        for(int index=0;index<MonkeyCombatRules.ProjectileCount;index++)
        {
            if((battleEnding||generation!=combatGeneration))break;
            if(!IsCombatActive(target))
                target=SelectMonkeyBarrageTarget(source,range);
            if(target==null)break;
            consecutiveHits=target==previous?consecutiveHits+1:0;
            bool last=index==MonkeyCombatRules.ProjectileCount-1;
            if(last&&kingFruit)
            {
                yield return ResolveMonkeyKingFruit(source,target,damageScale,radiusScale,
                    consecutiveHits,generation,(count,damage)=>{hits+=count;dealt+=damage;});
                break;
            }
            bool empowered=last&&powder;
            float raw=MonkeyCombatRules.ProjectileDamage(
                source.damage,skill.damageMultiplier,consecutiveHits,precise,empowered)*
                damageScale;
            float radius=last?TileSize*(powder
                ?MonkeyCombatRules.PowderExplosionRadiusTiles
                :skill.radiusTiles)*radiusScale:0f;
            Color projectileColor=poison
                ?(last?new Color(0.62f,0.12f,0.82f):new Color(0.34f,0.88f,0.16f))
                :last
                    ?powder
                        ?new Color(0.92f,0.08f,0.025f)
                        :cloud
                            ?new Color(0.72f,0.92f,1f)
                            :new Color(1f,0.67f,0.18f)
                    :new Color(0.82f,0.72f,0.36f);
            if(precise)
                projectileColor=Color.Lerp(
                    projectileColor,new Color(1f,0.88f,0.18f),
                    Mathf.Clamp01(consecutiveHits*0.22f));
            Unit shotTarget=target;
            bool shotLast=last;
            int shotCombo=consecutiveHits;
            float shotRaw=raw;
            float shotRadius=radius;
            pendingProjectiles++;
            Action arrive=()=>
            {
                pendingProjectiles--;
                if((battleEnding||generation!=combatGeneration)||
                   shotTarget==null||shotTarget.model==null)return;
                Vector3 impact=Flat(shotTarget.model.transform.position);
                if(shotLast||IsCombatActive(shotTarget))
                    PlayMonkeySound(source,shotLast?MonkeySound.Finish:MonkeySound.Hit,impact,traitEcho?.65f:1f
                        ,secondary:!shotLast
                    );
                if(IsCombatActive(shotTarget))
                {
                    dealt+=ApplySkillDamage(source,shotTarget,shotRaw,false);
                    hits++;
                    if(poison)dealt+=ApplyMonkeyPoisonFruit(source,shotTarget,damageScale);
                    shotTarget.spriteAnimation?.PlayImpactRecoil(
                        impact-Flat(source.model.transform.position),shotLast?.12f:.045f);
                }
                if(precise&&shotCombo>=MonkeyCombatRules.ProjectileCount-1)
                    PlayTraitBurst(shotTarget,new Color(1f,0.82f,0.12f),true);
                if(!shotLast)return;
                if(!traitEcho)combatCameraDirector?.ReportMonkeyFruitImpact();
                List<Unit> nearby=units.Where(enemy=>IsCombatActive(enemy)&&
                    enemy.team!=source.team&&enemy!=shotTarget&&
                    Vector3.Distance(impact,Flat(enemy.model.transform.position))<=shotRadius)
                    .ToList();
                for(int i=0;i<nearby.Count;i++)
                {
                    Unit enemy=nearby[i];
                    dealt+=ApplySkillDamage(source,enemy,shotRaw,false);
                    hits++;
                    SpriteRenderer hitRenderer=enemy.spriteAnimation==null?null:
                        enemy.spriteAnimation.GetComponent<SpriteRenderer>();
                    PixelCombatEffect.PlayMonkeyFruitPop(
                        hitRenderer==null?enemy.model.transform.position+Vector3.up*.35f:
                            hitRenderer.bounds.center,hitRenderer,projectileColor,false
                            ,secondary:true
                        );
                    enemy.spriteAnimation?.PlayImpactRecoil(
                        Flat(enemy.model.transform.position)-impact,.1f);
                    if(poison)
                        dealt+=ApplyMonkeyPoisonFruit(source,enemy,damageScale);
                }
                if(cloud)
                {
                    List<Unit> bounces=units.Where(enemy=>IsCombatActive(enemy)&&
                            enemy.team!=source.team&&enemy!=shotTarget&&
                            Vector3.Distance(impact,
                                Flat(enemy.model.transform.position))<=
                            TileSize*MonkeyCombatRules.CloudBounceRadiusTiles)
                        .OrderBy(enemy=>Vector3.Distance(
                            impact,Flat(enemy.model.transform.position)))
                        .Take(MonkeyCombatRules.CloudBounceCount).ToList();
                    for(int i=0;i<bounces.Count;i++)
                    {
                        Unit bounceTarget=bounces[i];
                        pendingProjectiles++;
                        Action bounceArrive=() =>
                        {
                            pendingProjectiles--;
                            if((battleEnding||generation!=combatGeneration)||
                               !IsCombatActive(bounceTarget))return;
                            PlayMonkeySound(source,MonkeySound.Hit,Rank3Center(bounceTarget),.6f
                                ,secondary:true
                            );
                            dealt+=ApplySkillDamage(source,bounceTarget,shotRaw,false);
                            hits++;
                        };
                        PixelStarProjectile bounceProjectile=
                            EmitMonkeyCloudBounce(source,shotTarget,bounceTarget,bounceArrive);
                        if(bounceProjectile==null)bounceArrive();
                    }
                }
            };
            PixelStarProjectile projectile=EmitMonkeyBean(
                source,shotTarget,projectileColor,last,radius,arrive);
            PlayMonkeySound(source,MonkeySound.Throw,Rank3Center(source),last?1f:.7f
                ,secondary:!last
            );
            if(precise&&projectile!=null)
                projectile.MultiplyVisualScale(1f+consecutiveHits*0.07f);
            float nextThrow=index==MonkeyCombatRules.ProjectileCount-2?
                MonkeyCombatRules.FinalThrowInterval:MonkeyCombatRules.ProjectileInterval;
            if(!traitEcho)source.spriteAnimation?.PlayMonkeyThrowFollowThrough(
                last?.18f:nextThrow,last,
                shotTarget.model.transform.position-source.model.transform.position);
            if(projectile==null)arrive();
            previous=target;
            if(index<MonkeyCombatRules.ProjectileCount-1)
                yield return SkillWait(source,nextThrow/CombatStatFormula.CombatAnimationRate);
        }
        float projectileWait=1f;
        while(!battleEnding&&pendingProjectiles>0&&projectileWait>0f&&generation==combatGeneration)
        {
            projectileWait-=CombatSkillClock.Delta;
            yield return null;
        }
        if(!traitEcho&&(kingFruit||precise||poison||cloud||powder)&&hits>0)
            source.traitActivations++;
        source.skillHits+=hits;
        source.skillDamage+=dealt;
        source.currentAction="acrobatic_barrage";
        RecordSkillEvent(source,kingFruit?MonkeyRank3Rules.MountainCollapse:
            skill.id+(traitEcho?"_echo":""),hits,dealt);
    }

    private Unit SelectMonkeyBarrageTarget(Unit source,float range)
    {
        return units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=source.team&&
                Vector3.Distance(Flat(source.model.transform.position),
                    Flat(enemy.model.transform.position))<=
                range+source.collisionRadius+enemy.collisionRadius)
            .OrderBy(enemy=>Vector3.Distance(
                Flat(source.model.transform.position),Flat(enemy.model.transform.position)))
            .FirstOrDefault();
    }

    private float ApplyMonkeyPoisonFruit(Unit source,Unit target,float damageScale=1f)
    {
        if(!IsCombatActive(target))return 0f;
        CombatStatusEffect poison=target.combatStatuses.ApplyStacks(
            CombatStatusKind.VenomFruit,MonkeyCombatRules.PoisonStackDuration,
            1,MonkeyCombatRules.PoisonStacksToBurst,source,0f,0f,true);
        target.reaction?.PlayTintHit(new Color(0.38f,0.92f,0.16f));
        if(poison.stacks<MonkeyCombatRules.PoisonStacksToBurst)return 0f;
        target.combatStatuses.Remove(CombatStatusKind.VenomFruit);
        SpriteRenderer renderer=target.spriteAnimation==null
            ?target.model.GetComponentInChildren<SpriteRenderer>()
            :target.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelStarProjectile.PlayBeanImpact(
            renderer==null?target.model.transform.position+Vector3.up*0.45f
                :renderer.bounds.center,
            renderer,new Color(0.48f,0.9f,0.12f),true,0.6f);
        PixelCombatEffect.PlayPoisonBurst(
            target.spriteAnimation==null
                ?target.model.transform:target.spriteAnimation.transform,
            renderer);
        return ApplySkillDamage(
            source,target,MonkeyCombatRules.PoisonBurstDamage(source.damage)*damageScale,false);
    }

    private static PixelStarProjectile EmitMonkeyCloudBounce(
        Unit owner,Unit from,Unit to,Action onArrive)
    {
        if(from==null||to==null||from.model==null||to.model==null)return null;
        SpriteRenderer fromRenderer=from.spriteAnimation==null
            ?from.model.GetComponentInChildren<SpriteRenderer>()
            :from.spriteAnimation.GetComponent<SpriteRenderer>();
        SpriteRenderer toRenderer=to.spriteAnimation==null
            ?to.model.GetComponentInChildren<SpriteRenderer>()
            :to.spriteAnimation.GetComponent<SpriteRenderer>();
        var projectile=PixelStarProjectile.PlayCloudBean(
            from.spriteAnimation==null?from.model.transform:from.spriteAnimation.transform,
            fromRenderer,
            to.spriteAnimation==null?to.model.transform:to.spriteAnimation.transform,
            toRenderer,onArrive);
        projectile?.SetCombatOwner(owner.model.transform);return projectile;
    }

    private bool BeginCrossScytheWind(Unit unit,SkillMasterRow skill)
    {
        Unit target=unit.target;
        if(!IsCombatActive(target))return false;
        bool extended=MonsterTraitRuntime.Has(
            unit.activeTraitIds,MantisCombatRules.SantiusTraitId);
        float range=TileSize*MantisCombatRules.RangeTiles(
                        skill.castRangeTiles,extended)+
                    unit.collisionRadius+target.collisionRadius;
        if(unit.rank3MantisReaper)range=MantisReaperCastRange(unit);
        if(!IsWithinCommittedSkillReach(unit,target,range))
            return false;
        unit.mantisScythePending=true;
        unit.mantisScytheTarget=target;
        unit.mantisScytheDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.mantisScytheRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="cross_scythe_wind_prepare";
        if(!unit.rank3MantisReaper)PixelCombatEffect.PlayMantisWindup(Rank3Renderer(unit));
        unit.velocity=Vector3.zero;
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(unit.spriteAnimation==null)
            StartReleasedSkill(unit,ResolveCrossScytheWind(unit,target,skill,1f,false,combatGeneration));
        return true;
    }

    private IEnumerator ResolveCrossScytheWind(
        Unit source,Unit initialTarget,SkillMasterRow skill,
        float effectScale,bool traitEcho,int generation,bool nectisRecast=false)
    {
        if((battleEnding||generation!=combatGeneration)||!IsCombatActive(source)||skill==null)yield break;
        float damageScale=effectScale*
            (traitEcho?1f:source.mantisScytheDamageMultiplier);
        float radiusScale=traitEcho?1f:source.mantisScytheRadiusMultiplier;
        source.mantisScythePending=false;
        source.mantisScytheTarget=null;
        source.mantisScytheDamageMultiplier=1f;
        source.mantisScytheRadiusMultiplier=1f;
        source.attackMovementLockTimer=Mathf.Max(
            source.attackMovementLockTimer,MantisCombatRules.WaveInterval+0.08f);
        bool precise=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,MantisCombatRules.MantiusTraitId);
        bool pollen=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,MantisCombatRules.FlotisTraitId);
        bool extended=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,MantisCombatRules.SantiusTraitId);
        bool reaper=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,MantisCombatRules.NectisTraitId);
        float rangeTiles=MantisCombatRules.RangeTiles(
            skill.castRangeTiles,extended);
        Unit target=IsCombatActive(initialTarget)
            ?initialTarget:SelectMantisScytheTarget(source,rangeTiles);
        if(target==null)yield break;
        if(!traitEcho&&TryResolveMantisRank3(
               source,target,skill,damageScale,radiusScale,generation))
            yield break;
        Vector3 origin=Flat(source.model.transform.position);
        Vector3 forward=Flat(target.model.transform.position)-origin;
        if(forward.sqrMagnitude<0.001f)forward=Flat(source.model.transform.forward);
        if(forward.sqrMagnitude<0.001f)forward=Vector3.forward;
        forward.Normalize();
        float length=TileSize*rangeTiles+target.collisionRadius;
        float halfWidth=TileSize*MantisCombatRules.WidthTiles(
            skill.radiusTiles,extended)*radiusScale;
        var hitMasks=new Dictionary<Unit,int>();
        var winds=new List<PixelStarProjectile>();
        System.Func<bool> valid=()=>ReleasedSkillValid(source,generation);
        int hits=0;
        int doubleHits=0;
        float dealt=0f;
        bool killed=false;
        bool hasReaperOrigin=false;
        Vector3 reaperOrigin=Vector3.zero;
        Action completeReaperCamera=!traitEcho&&!source.rank3MantisReaper&&
            MonsterTraitRuntime.Has(source.activeTraitIds,MantisRank3Rules.ReaperEmergence)
                ?HoldSkillCameraEffect(source):null;
        try
        {
        try
        {
            for(int wave=0;wave<MantisCombatRules.WaveCount;wave++)
            {
                if(!valid())yield break;
                int waveIndex=wave;
                var waveHits=new HashSet<Unit>();
                Vector3 direction=Quaternion.AngleAxis(
                    wave==0?-MantisCombatRules.WaveAngle:MantisCombatRules.WaveAngle,
                    Vector3.up)*forward;
                SpriteRenderer sourceRenderer=source.spriteAnimation==null
                    ?null:source.spriteAnimation.GetComponent<SpriteRenderer>();
                Color windColor=wave==0
                    ?new Color(0.38f,0.94f,0.3f):new Color(0.78f,1f,0.38f);
                if(extended)
                    windColor=wave==0
                        ?new Color(0.92f,0.58f,0.12f):new Color(1f,0.78f,0.22f);
                if(precise&&wave==1)windColor=new Color(1f,0.9f,0.62f);
                if(nectisRecast)
                    windColor=wave==0
                        ?new Color(0.38f,0.06f,0.58f):new Color(0.72f,0.16f,0.9f);
                float windScale=halfWidth/Mathf.Max(0.01f,TileSize*skill.radiusTiles);
                if(precise&&wave==1)windScale*=1.18f;
                System.Action<float,float> sweep=(from,to)=>
                {
                    if(!valid())return;
                    List<Unit> victims=units.Where(enemy=>IsCombatTargetable(enemy)&&!waveHits.Contains(enemy)&&
                            enemy.team!=source.team&&
                            Vector3.Dot(Flat(enemy.model.transform.position)-origin,direction)+enemy.collisionRadius>=from*length&&
                            Vector3.Dot(Flat(enemy.model.transform.position)-origin,direction)-enemy.collisionRadius<=to*length&&
                            IsPointInsideForwardSkillLine(
                                origin,direction,Flat(enemy.model.transform.position),length,
                                halfWidth+enemy.collisionRadius))
                        .ToList();
                    float ratio=waveIndex==0||skill.secondaryDamageMultiplier<=0f
                        ?skill.damageMultiplier:skill.secondaryDamageMultiplier;
                    for(int i=0;i<victims.Count;i++)
                    {
                        Unit enemy=victims[i];
                        waveHits.Add(enemy);
                        int previousMask=hitMasks.TryGetValue(enemy,out int mask)?mask:0;
                        int currentMask=previousMask|(1<<waveIndex);
                        hitMasks[enemy]=currentMask;
                        bool doubled=currentMask==3&&previousMask!=3;
                        SpriteRenderer enemyRenderer=enemy.spriteAnimation==null
                            ?enemy.model.GetComponentInChildren<SpriteRenderer>()
                            :enemy.spriteAnimation.GetComponent<SpriteRenderer>();
                        Transform enemyAnchor=enemy.spriteAnimation==null
                            ?enemy.model.transform:enemy.spriteAnimation.transform;
                        float raw=MantisCombatRules.HitDamage(
                            source.damage,ratio,waveIndex,precise)*damageScale;
                        float applied=ApplySkillDamage(source,enemy,raw,false);
                        dealt+=applied;
                        hits++;
                        if(applied>0f)
                        {
                            PixelCombatEffect.PlayMantisCutImpact(enemyAnchor,enemyRenderer,windColor,doubled);
                            enemy.spriteAnimation?.PlayImpactRecoil(direction,doubled?.065f:.04f);
                            PlayMantisSound(source,MantisSound.Hit,Flat(enemy.model.transform.position),traitEcho?.65f:1f);
                        }
                        if(doubled)
                        {
                            doubleHits++;
                            if(IsCombatActive(enemy))
                            {
                                enemy.combatStatuses.ApplyStacks(
                                    CombatStatusKind.Bleed,skill.statusDurationSeconds,1,1,
                                    source,MantisCombatRules.BleedTickDamage(source.damage),
                                    MantisCombatRules.BleedTickInterval);
                                if(pollen)
                                {
                                    float pollenDuration=HostileStatusDuration(
                                        enemy,MantisCombatRules.PollenDuration);
                                    enemy.combatStatuses.ApplyTimed(
                                        CombatStatusKind.HallucinatoryPollen,
                                        pollenDuration,source);
                                    PixelCombatEffect.PlayMantisHallucinatoryPollen(
                                        enemyAnchor,enemyRenderer,pollenDuration);
                                    PlayTraitBurst(enemy,new Color(0.9f,0.26f,0.88f),false);
                                }
                            }
                        }
                        if(applied>0f&&!IsCombatActive(enemy))
                        {
                            killed=true;
                            if(reaper&&!hasReaperOrigin)
                            {
                                reaperOrigin=enemyRenderer==null
                                    ?enemy.model.transform.position+Vector3.up*0.4f
                                    :enemyRenderer.bounds.center;
                                hasReaperOrigin=true;
                            }
                        }
                    }
                };
                var wind=PixelStarProjectile.PlayScytheWind(
                    source.spriteAnimation==null?source.model.transform:source.spriteAnimation.transform,
                    sourceRenderer,origin+direction*length,windColor,windScale,origin,halfWidth,wave==1,sweep,valid);
                if(wind!=null)
                {
                    winds.Add(wind);
                    PlayMantisSound(source,MantisSound.Launch,Rank3Center(source),traitEcho?.65f:1f);
                }
                if(sourceRenderer!=null)
                {
                    var slash=PixelCombatEffect.PlayMantisScytheSlash(sourceRenderer.transform,sourceRenderer,
                        2f,wave==1,1.12f,windColor);
                    source.spriteAnimation?.PlayImpactRecoil(direction,wave==0?.06f:-.06f);
                }
                if(extended)
                    PixelCombatEffect.PlayMantisSandTrail(origin,origin+direction*length,halfWidth,sourceRenderer);
                if(wave<MantisCombatRules.WaveCount-1)
                    yield return SkillWait(source,MantisCombatRules.WaveInterval);
            }
            while(!battleEnding&&winds.Any(wind=>wind!=null))
            {
                if(!valid())yield break;
                yield return null;
            }
        }
        finally
        {
            foreach(var wind in winds)if(wind!=null)wind.Cancel();
        }
        if(!valid())yield break;
        if(!traitEcho&&((precise&&doubleHits>0)||(pollen&&doubleHits>0)||
           (extended&&hits>0)||(reaper&&killed)))
            source.traitActivations++;
        source.skillHits+=hits;
        source.skillDamage+=dealt;
        source.currentAction="cross_scythe_wind";
        RecordSkillEvent(source,skill.id+(traitEcho?"_echo":""),hits,dealt);
        if(!traitEcho&&MonsterTraitRuntime.Has(
               source.activeTraitIds,MantisRank3Rules.ReaperEmergence)&&
           !source.rank3MantisReaper)
        {
            ActivateMantisReaperWithCameraCompletion(source,completeReaperCamera);
            completeReaperCamera=null;
        }
        if(reaper&&killed)
        {
            Unit recastTarget=SelectMantisScytheTarget(
                source,skill.castRangeTiles);
            if(recastTarget!=null)
            {
                SpriteRenderer recastRenderer=recastTarget.spriteAnimation==null
                    ?recastTarget.model.GetComponentInChildren<SpriteRenderer>()
                    :recastTarget.spriteAnimation.GetComponent<SpriteRenderer>();
                Vector3 recastCenter=recastRenderer==null
                    ?recastTarget.model.transform.position+Vector3.up*0.4f
                    :recastRenderer.bounds.center;
                if(hasReaperOrigin)
                    PixelCombatEffect.PlayMantisSoulThread(
                        reaperOrigin,recastCenter,recastRenderer);
                yield return SkillWait(source,MantisCombatRules.WaveInterval);
                yield return ResolveCrossScytheWind(
                    source,recastTarget,skill,
                    MantisCombatRules.RecastDamageMultiplier,true,generation,true);
            }
        }
        }
        finally
        {
            completeReaperCamera?.Invoke();
        }
    }

    private Unit SelectMantisScytheTarget(Unit source,float rangeTiles)
    {
        float range=TileSize*Mathf.Max(0f,rangeTiles);
        return units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=source.team&&
                Vector3.Distance(
                    Flat(source.model.transform.position),
                    Flat(enemy.model.transform.position))<=
                range+source.collisionRadius+enemy.collisionRadius)
            .OrderBy(enemy=>Vector3.Distance(
                Flat(source.model.transform.position),Flat(enemy.model.transform.position)))
            .FirstOrDefault();
    }

    private bool BeginSporeColony(Unit unit,SkillMasterRow skill)
    {
        Unit target=unit.target;
        if(!IsCombatTargetable(target))return false;
        float range=TileSize*Mathf.Max(0f,skill.castRangeTiles)+
                    unit.collisionRadius+target.collisionRadius;
        if(!IsWithinCommittedSkillReach(unit,target,range))
            return false;
        unit.mushroomColonyPending=true;
        unit.mushroomColonyTarget=target;
        unit.mushroomColonyDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.mushroomColonyRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="spore_colony_prepare";
        unit.velocity=Vector3.zero;
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(unit.spriteAnimation==null)
            StartReleasedSkill(unit,ResolveSporeColony(unit,target,skill,1f,false,combatGeneration));
        return true;
    }

    private IEnumerator ResolveSporeColony(
        Unit source,Unit initialTarget,SkillMasterRow skill,
        float effectScale,bool traitEcho,int generation)
    {
        if((battleEnding||generation!=combatGeneration)||!IsCombatActive(source)||skill==null)yield break;
        float damageScale=effectScale*
            (traitEcho?1f:source.mushroomColonyDamageMultiplier);
        float radiusScale=traitEcho?1f:source.mushroomColonyRadiusMultiplier;
        source.mushroomColonyPending=false;
        source.mushroomColonyTarget=null;
        source.mushroomColonyDamageMultiplier=1f;
        source.mushroomColonyRadiusMultiplier=1f;
        Unit target=IsCombatTargetable(initialTarget)
            ?initialTarget:SelectSporeColonyTarget(source,skill.castRangeTiles);
        if(target==null)yield break;
        if(!traitEcho&&TryResolveMushroomRank3(
               source,target,skill,damageScale,radiusScale,generation))
            yield break;

        Color sporeColor=MushroomGasColor(source,traitEcho);
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?null:source.spriteAnimation.GetComponent<SpriteRenderer>();
        SpriteRenderer targetRenderer=target.spriteAnimation==null
            ?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
        Transform sourceAnchor=source.spriteAnimation==null
            ?source.model.transform:source.spriteAnimation.transform;
        Transform targetAnchor=target.spriteAnimation==null
            ?target.model.transform:target.spriteAnimation.transform;
        Vector3 lastCenter=Flat(target.model.transform.position);
        bool initialArrived=false;
        PixelStarProjectile initialSpore=PixelStarProjectile.PlaySporeShot(
            sourceAnchor,sourceRenderer,targetAnchor,targetRenderer,
            sporeColor,()=>initialArrived=true);
        PlayMushroomSound(source,MushroomSound.Launch,sourceAnchor.position,traitEcho?.6f:1f);
        if(initialSpore==null)initialArrived=true;
        float travelWait=0.8f;
        while(!battleEnding&&!initialArrived&&travelWait>0f&&generation==combatGeneration)
        {
            if(paused){yield return null;continue;}
            travelWait-=CombatSkillClock.Delta;
            yield return null;
        }
        if((battleEnding||generation!=combatGeneration))yield break;

        Vector3 center=target.model==null?lastCenter:Flat(target.model.transform.position);
        if(!traitEcho&&HasRank3(source,MushroomRank3Rules.ParasiticCrown))
            CreateMushroomCrown(source,target,center,damageScale,radiusScale,generation);
        else CreateMushroomGas(source,center,skill,damageScale,radiusScale,traitEcho,generation);
    }

    private Unit SelectSporeColonyTarget(Unit source,float rangeTiles)
    {
        float range=TileSize*Mathf.Max(0f,rangeTiles);
        return units.Where(enemy=>IsCombatTargetable(enemy)&&enemy.team!=source.team&&
                Vector3.Distance(
                    Flat(source.model.transform.position),
                    Flat(enemy.model.transform.position))<=
                range+source.collisionRadius+enemy.collisionRadius)
            .OrderBy(enemy=>Vector3.Distance(
                Flat(source.model.transform.position),Flat(enemy.model.transform.position)))
            .FirstOrDefault();
    }

    private IEnumerator ResolveChildMushroom(
        Unit source,Vector3 center,float radius,float damage,
        float delay,int generation)
    {
        Color color=new Color(0.94f,0.68f,0.24f);
        PixelGroundCastTelegraph marker=PixelCombatEffect.PlayMushroomChildCharge(
            center,radius,delay,skillRadiusMarkerMaterial,null);
        yield return new WaitForSeconds(Mathf.Max(0.05f,delay));
        if(marker!=null)marker.Impact();
        if((battleEnding||generation!=combatGeneration))yield break;
        int hits=0;
        float dealt=0f;
        for(int i=0;i<units.Count;i++)
        {
            Unit enemy=units[i];
            if(!IsCombatActive(enemy)||enemy.team==source.team||
               Vector3.Distance(center,Flat(enemy.model.transform.position))>
               radius+enemy.collisionRadius)
                continue;
            dealt+=ApplySkillDamage(source,enemy,damage,false);
            hits++;
        }
        source.skillHits+=hits;
        source.skillDamage+=dealt;
        PixelStarProjectile.PlaySporeExplosion(center,null,color,radius);
        PlayMushroomSound(source,MushroomSound.Resonance,center,.6f);
        RecordSkillEvent(source,source.skillId+"_child",hits,dealt);
    }

    private bool BeginEarthCharge(Unit unit,SkillMasterRow skill)
    {
        if(unit==null||skill==null||!IsCombatActive(unit)||
           !IsCombatActive(unit.target))return false;
        Unit target=unit.target;
        if(HasFamilyTranscendence(unit))
        {
            StartMammothExpulsion(unit,target);
            if(unit.mammothExpulsion==null)return false;
            unit.skillTimer=unit.skillCooldownDuration;unit.skillUses++;
            ApplyPostSkillItemEffects(unit);
            RecordSkillEvent(unit,"trait_transcend_mammoth_ark_of_earth_start",0,0f);
            return true;
        }
        Vector3 start=Flat(unit.model.transform.position);
        Vector3 offset=Flat(target.model.transform.position)-start;
        bool toss=HasRank3(unit,MammothRank3Rules.MountainToss);
        bool brace=HasRank3(unit,MammothRank3Rules.MountainBrace);
        float maximum=TileSize*(toss?MammothRank3Rules.TossRangeTiles:brace?MammothRank3Rules.BraceSweepTiles*unit.skillTraitRadiusMultiplier:MammothCombatRules.MaximumChargeDistanceTiles);
        if(!IsWithinCommittedSkillReach(unit,target,maximum+(brace?0f:unit.collisionRadius)+target.collisionRadius))
            return false;
        Vector3 direction=offset.sqrMagnitude<0.001f
            ?Flat(unit.model.transform.forward):offset.normalized;
        if(direction.sqrMagnitude<0.001f)direction=Vector3.forward;
        Vector3 desired=toss||brace?start+direction*maximum:MammothCombatRules.ChargeEnd(start,direction,TileSize);
        Vector3 end=toss||brace?desired:ResolveFreePosition(desired,unit.collisionRadius);
        if(!toss&&!brace&&(!HasClearPathSegment(start,end,unit.collisionRadius)||
           Vector3.Distance(desired,end)>0.08f))
        {
            if(CommittedSkillTarget(unit)!=target)
            {
                unit.skillTimer=0.3f;
                return false;
            }
            float clear=0f,blocked=1f;end=start;
            for(int i=0;i<12;i++)
            {
                float progress=(clear+blocked)*.5f;
                Vector3 candidate=Vector3.Lerp(start,desired,progress);
                Vector3 resolved=ResolveFreePosition(candidate,unit.collisionRadius);
                if(Vector3.Distance(candidate,resolved)<=.001f&&
                   HasClearPathSegment(start,resolved,unit.collisionRadius))
                {clear=progress;end=resolved;}
                else blocked=progress;
            }
        }

        unit.mammothChargePending=true;
        unit.mammothChargeTarget=target;
        unit.mammothChargeStart=start;
        unit.mammothChargeEnd=end;
        unit.mammothChargeDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.mammothChargeRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction=brace?"mountain_brace_prepare":toss?"mountain_toss_prepare":"earth_charge_prepare";
        unit.velocity=Vector3.zero;
        
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        RotateUnit(unit,direction,1f);
        float windup=unit.spriteAnimation==null?0f:
            unit.spriteAnimation.SkillAttackHitTime/
            Mathf.Max(0.01f,SpriteSkillAttackPlaybackSpeed(unit));
        unit.attackMovementLockTimer=Mathf.Max(
            unit.attackMovementLockTimer,brace?MammothRank3Rules.BraceEnd:toss?MammothRank3Rules.TossCastEnd:HasRank3(unit,MammothRank3Rules.WallRush)?MammothRank3Rules.WallRushEnd:HasMammothRank3(unit)?windup+Mathf.Max(0.08f,skill.durationSeconds):MammothCombatRules.EndTime);
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(unit.spriteAnimation==null)
        {
            if(brace)StartMammothBrace(unit,combatGeneration);
            else if(toss)StartMammothToss(unit,combatGeneration);
            else if(HasRank3(unit,MammothRank3Rules.WallRush)||!HasMammothRank3(unit))StartMammothCharge(unit,combatGeneration);
            else StartCombatCoroutine(unit,ResolveEarthCharge(unit,target,skill,1f,false,combatGeneration));
        }
        return true;
    }

    private IEnumerator ResolveEarthCharge(
        Unit source,Unit target,SkillMasterRow skill,
        float effectScale,bool traitEcho,int generation)
    {
        if(source==null||skill==null)yield break;
        Vector3 start;
        Vector3 end;
        float damageMultiplier=1f;
        float radiusMultiplier=1f;
        if(traitEcho)
        {
            if(!IsCombatActive(source)||!IsCombatActive(target))yield break;
            start=Flat(source.model.transform.position);
            Vector3 offset=Flat(target.model.transform.position)-start;
            Vector3 direction=offset.sqrMagnitude<0.001f
                ?Flat(source.model.transform.forward):offset.normalized;
            Vector3 desired=MammothCombatRules.ChargeEnd(start,direction,TileSize);
            end=ResolveFreePosition(desired,source.collisionRadius);
            if(!HasClearPathSegment(start,end,source.collisionRadius))end=start;
        }
        else
        {
            start=source.mammothChargeStart;
            end=source.mammothChargeEnd;
            damageMultiplier=source.mammothChargeDamageMultiplier;
            radiusMultiplier=source.mammothChargeRadiusMultiplier;
            source.mammothChargePending=false;
            source.mammothChargeTarget=null;
            source.mammothChargeDamageMultiplier=1f;
            source.mammothChargeRadiusMultiplier=1f;
        }
        if((battleEnding||generation!=combatGeneration)||!IsCombatActive(source))yield break;
        int positionRevision=source.positionRevision;

        Vector3 path=end-start;
        float pathLength=path.magnitude;
        Vector3 forward=pathLength>0.001f?path/pathLength:
            Flat(source.model.transform.forward).normalized;
        bool steelTusk=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,MammothCombatRules.IrontuskTraitId);
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        if(!traitEcho&&pathLength>0.001f)
        {
            float duration=Mathf.Max(0.08f,skill.durationSeconds);
            if(steelTusk)
                PixelCombatEffect.PlayMammothTuskRam(
                    source.spriteAnimation==null
                        ?source.model.transform:source.spriteAnimation.transform,
                    sourceRenderer,1f,sourceRenderer!=null&&sourceRenderer.flipX,
                    new Color(0.72f,0.9f,1f),1.32f);
            GameObject guide=PixelCombatEffect.PlayMammothChargeGuide(
                start,end,TileSize*0.48f,skillRadiusMarkerMaterial,sourceRenderer);
            source.combatStatuses.DebuffImmune=true;
            try
            {
                float elapsed=0f;
                while(!battleEnding&&elapsed<duration)
                {
                    if((battleEnding||generation!=combatGeneration)||!IsCombatActive(source)||
                       source.positionRevision!=positionRevision)yield break;
                    elapsed+=CombatSkillClock.Delta*CombatStatFormula.CombatAnimationRate;
                    float progress=Mathf.Clamp01(elapsed/duration);
                    Vector3 ground=Vector3.Lerp(start,end,
                        1f-Mathf.Pow(1f-progress,2f));
                    source.model.transform.position=
                        ground+Vector3.up*source.visualHeightOffset;
                    source.ring.transform.position=ground+Vector3.up*0.025f;
                    RotateUnit(source,forward,CombatSkillClock.Delta*2f);
                    yield return null;
                }
                source.model.transform.position=end+Vector3.up*source.visualHeightOffset;
                source.ring.transform.position=end+Vector3.up*0.025f;
                source.lastGroundPosition=end;
                source.currentTile=NearestGridCoordinate(end);
                if(elapsed>=duration&&generation==combatGeneration&&source.positionRevision==positionRevision&&!battleEnding)
                    BeginSkillInertia(source,end-start,duration);
            }
            finally
            {
                source.combatStatuses.DebuffImmune=false;
                if(guide!=null&&!CombatEffectEndFade.IsFading(guide.transform))Destroy(guide);
            }
        }

        HashSet<Unit> uniqueHits=new HashSet<Unit>();
        int hits=0;
        float dealt=0f;
        float defense=steelTusk?CurrentDefense(source):0f;
        float scale=effectScale*damageMultiplier;
        if(pathLength>0.001f)
        {
            List<Unit> pathVictims=units.Where(enemy=>
                IsCombatActive(enemy)&&enemy.team!=source.team&&
                IsPointInsideForwardSkillLine(
                    start,forward,Flat(enemy.model.transform.position),
                    pathLength,TileSize*0.48f+enemy.collisionRadius)).ToList();
            for(int i=0;i<pathVictims.Count;i++)
            {
                Unit enemy=pathVictims[i];
                dealt+=ApplySkillDamage(source,enemy,
                    MammothCombatRules.Damage(
                        SkillPower(source),skill.damageMultiplier,defense,steelTusk)*scale,
                    false);
                if(steelTusk)PlayMammothSteelTuskImpact(enemy);
                hits++;
                uniqueHits.Add(enemy);
                if(IsCombatActive(enemy))
                {
                    DisplaceUnit(enemy,forward,
                        TileSize*MammothCombatRules.KnockbackDistanceTiles);
                    enemy.combatStatuses.ApplyTimed(
                        CombatStatusKind.Knockdown,
                        HostileStatusDuration(enemy,skill.statusDurationSeconds),source);
                }
            }
        }

        float radius=TileSize*skill.radiusTiles*radiusMultiplier;
        List<Unit> landingVictims=units.Where(enemy=>
            IsCombatActive(enemy)&&enemy.team!=source.team&&
            Vector3.Distance(end,Flat(enemy.model.transform.position))<=
                radius+enemy.collisionRadius).ToList();
        for(int i=0;i<landingVictims.Count;i++)
        {
            Unit enemy=landingVictims[i];
            dealt+=ApplySkillDamage(source,enemy,
                MammothCombatRules.Damage(
                    SkillPower(source),skill.secondaryDamageMultiplier,
                    defense,steelTusk&&!uniqueHits.Contains(enemy))*scale,false);
            if(steelTusk)PlayMammothSteelTuskImpact(enemy);
            hits++;
            uniqueHits.Add(enemy);
            if(IsCombatActive(enemy))
                enemy.combatStatuses.ApplyTimed(
                    CombatStatusKind.Knockdown,
                    HostileStatusDuration(enemy,skill.statusDurationSeconds),source);
        }

        if(!traitEcho)ApplyMammothChargeTraits(source,uniqueHits,start,end);

        source.skillHits+=hits;
        source.skillDamage+=dealt;
        source.currentAction="earth_charge";
        source.velocity=Vector3.zero;
        SetMoving(source,false);
        CreateJaguarPathEffect(
            start,end,new Color(0.64f,0.48f,0.28f),0.24f);
        CreateSkillPulseAt(end,new Color(0.78f,0.58f,0.3f),
            Mathf.Max(0.7f,skill.radiusTiles));
        PlayMammothSound(source,MammothSound.Collision,end,traitEcho?.55f:1f);
        RecordSkillEvent(source,skill.id+(traitEcho?"_echo":""),hits,dealt);
    }

    private void ApplyMammothChargeTraits(Unit source,HashSet<Unit> uniqueHits,Vector3 start,Vector3 end)
    {
        int generation=combatGeneration;
        SpriteRenderer sourceRenderer=Rank3Renderer(source);
        if(uniqueHits.Count>0&&MonsterTraitRuntime.Has(
               source.activeTraitIds,MammothCombatRules.KogasonTraitId))
        {
            source.combatStatuses.ApplyShield(
                MammothCombatRules.KogasonShieldDuration,
                SkillSupportAmount(source,MammothCombatRules.KogasonShield(
                    source.maxHp,uniqueHits.Count)),source);
            PixelCombatEffect.PlayMammothStoneShieldBurst(
                Flat(source.model.transform.position),TileSize*0.62f,sourceRenderer);
            source.traitActivations++;
        }
        if(Vector3.Distance(start,end)>.001f&&MonsterTraitRuntime.Has(
               source.activeTraitIds,MammothCombatRules.SeolgasonTraitId))
        {
            StartReleasedSkill(source,ResolveMammothIceTrail(source,start,end,generation));
            source.traitActivations++;
        }
        if(Vector3.Distance(start,end)>.001f&&MonsterTraitRuntime.Has(
               source.activeTraitIds,MammothCombatRules.GaiasonTraitId))
        {
            StartReleasedSkill(source,ResolveMammothAncestorPath(source,start,end,generation));
            source.traitActivations++;
        }
        if(HasRank3(source,MammothCombatRules.IrontuskTraitId)&&uniqueHits.Count>0)source.traitActivations++;

    }

    private IEnumerator ResolveMammothIceTrail(
        Unit source,Vector3 start,Vector3 end,int generation)
    {
        Vector3 path=end-start;
        float length=path.magnitude;
        if(length<0.001f)yield break;
        Vector3 forward=path/length;
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        GameObject marker=CreateMammothTrailMarker(start,end,sourceRenderer);
        float remaining=MammothCombatRules.GlacierTrailDuration;
        WaitForSeconds interval=new WaitForSeconds(0.2f);
        while(!battleEnding&&remaining>0f&&generation==combatGeneration)
        {
            for(int i=0;i<units.Count;i++)
            {
                Unit enemy=units[i];
                if(!IsCombatActive(enemy)||enemy.team==source.team||
                   !IsPointInsideForwardSkillLine(
                       start,forward,Flat(enemy.model.transform.position),length,
                       TileSize*0.55f+enemy.collisionRadius))continue;
                enemy.mammothSlowRatio=Mathf.Max(
                    enemy.mammothSlowRatio,MammothCombatRules.GlacierSlowRatio);
                enemy.mammothSlowTimer=Mathf.Max(
                    enemy.mammothSlowTimer,
                    HostileStatusDuration(
                        enemy,MammothCombatRules.GlacierSlowRefreshDuration));
            }
            remaining-=0.2f;
            yield return interval;
        }
        if(marker!=null&&!CombatEffectEndFade.IsFading(marker.transform))Destroy(marker);
    }

    private IEnumerator ResolveMammothAncestorPath(
        Unit source,Vector3 start,Vector3 end,int generation)
    {
        Vector3 path=end-start;
        float length=path.magnitude;
        if(length<0.001f)yield break;
        Vector3 forward=path/length;
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        GameObject marker=PixelCombatEffect.PlayMammothAncestorTrail(
            start,end,TileSize*1.1f,MammothCombatRules.AncestorBuffDuration,
            sourceRenderer);
        HashSet<Unit> recipients=new HashSet<Unit>();
        float remaining=MammothCombatRules.AncestorBuffDuration;
        WaitForSeconds interval=new WaitForSeconds(0.1f);
        while(!battleEnding&&remaining>0f&&generation==combatGeneration)
        {
            for(int i=0;i<units.Count;i++)
            {
                Unit ally=units[i];
                if(recipients.Contains(ally)||!IsCombatActive(ally)||
                   ally.team!=source.team||!IsPointInsideForwardSkillLine(
                       start,forward,Flat(ally.model.transform.position),length,
                       TileSize*0.55f+ally.collisionRadius))continue;
                recipients.Add(ally);
                ally.combatStatuses.ApplyShield(
                    MammothCombatRules.AncestorBuffDuration,
                    SkillSupportAmount(source,
                        MammothCombatRules.AncestorShield(source.maxHp)),source);
                ally.mammothHasteRatio=Mathf.Max(
                    ally.mammothHasteRatio,MammothCombatRules.AncestorMoveSpeedBonus);
                ally.mammothHasteTimer=GateHaetaeBenefit(ally,Mathf.Max(
                    ally.mammothHasteTimer,MammothCombatRules.AncestorBuffDuration));
                SpriteRenderer allyRenderer=ally.spriteAnimation==null
                    ?ally.model.GetComponentInChildren<SpriteRenderer>()
                    :ally.spriteAnimation.GetComponent<SpriteRenderer>();
                PixelCombatEffect.PlayKingpaRoyalAura(
                    ally.spriteAnimation==null
                        ?ally.model.transform:ally.spriteAnimation.transform,
                    allyRenderer,MammothCombatRules.AncestorBuffDuration,
                    new Color(0.28f,1f,0.42f),new Color(1f,0.82f,0.18f),
                    "Gaiason Ancestor Aura");
            }
            remaining-=0.1f;
            yield return interval;
        }
        if(marker!=null&&!CombatEffectEndFade.IsFading(marker.transform))Destroy(marker);
    }

    private GameObject CreateMammothTrailMarker(
        Vector3 start,Vector3 end,SpriteRenderer sortingReference)
    {
        return PixelCombatEffect.PlayMammothGlacierTrail(
            start,end,TileSize*1.1f,MammothCombatRules.GlacierTrailDuration,
            sortingReference);
    }

    private static void PlayMammothSteelTuskImpact(Unit target)
    {
        SpriteRenderer renderer=target.spriteAnimation==null
            ?target.model.GetComponentInChildren<SpriteRenderer>()
            :target.spriteAnimation.GetComponent<SpriteRenderer>();
        Vector3 position=renderer==null
            ?target.model.transform.position+Vector3.up*0.4f:renderer.bounds.center;
        PixelStarProjectile.PlayImpact(
            position,renderer,new Color(0.72f,0.9f,1f),true);
    }

    private Unit SelectMagicStarTarget(
        Unit source,float range,HashSet<Unit> hitTargets,bool focused)
    {
        return SelectPlannedMagicStarTarget(source,range,hitTargets,focused,null);
    }

    private List<Unit> CaptureMagicStarTargets(Unit source,float range)
    {
        List<Unit> committed=IsCommittingFocusedSkill(source)?CommittedSkillTargets(source):null;
        IEnumerable<Unit> candidates=committed??units;
        return candidates.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=source.team&&
            (committed!=null||Vector3.Distance(Flat(source.model.transform.position),
                Flat(enemy.model.transform.position))<=
             range+source.collisionRadius+enemy.collisionRadius)).ToList();
    }

    private Unit SelectPlannedMagicStarTarget(
        Unit source,float range,HashSet<Unit> hitTargets,bool focused,List<Unit> plannedTargets)
    {
        List<Unit> candidates=(plannedTargets??units).Where(enemy=>IsCombatActive(enemy)&&
                enemy.team!=source.team&&
                (plannedTargets!=null||Vector3.Distance(Flat(source.model.transform.position),
                    Flat(enemy.model.transform.position))<=
                range+source.collisionRadius+enemy.collisionRadius)).ToList();
        if(focused)
            return candidates.OrderBy(enemy=>enemy.hp/Mathf.Max(1f,enemy.maxHp))
                .ThenBy(enemy=>Vector3.Distance(
                    Flat(source.model.transform.position),
                    Flat(enemy.model.transform.position))).FirstOrDefault();
        Unit current=candidates.FirstOrDefault(enemy=>
            enemy==source.target&&!hitTargets.Contains(enemy));
        if(current!=null)return current;
        Unit fresh=candidates.Where(enemy=>!hitTargets.Contains(enemy))
            .OrderBy(enemy=>Vector3.Distance(
                Flat(source.model.transform.position),
                Flat(enemy.model.transform.position))).FirstOrDefault();
        return fresh??candidates.OrderBy(enemy=>Vector3.Distance(
            Flat(source.model.transform.position),
            Flat(enemy.model.transform.position))).FirstOrDefault();
    }

    private List<Unit> SelectMilkyWayFragmentTargets(
        Unit source,Unit original,Vector3 center,float range)
    {
        return units.Where(enemy=>IsCombatActive(enemy)&&
                enemy.team!=source.team&&enemy!=original&&
                Vector3.Distance(center,Flat(enemy.model.transform.position))<=
                range+enemy.collisionRadius)
            .OrderBy(enemy=>(center-Flat(enemy.model.transform.position)).sqrMagnitude)
            .Take(WizardMouseCombatRules.MilkyWayFragmentCount).ToList();
    }

    private bool ApplyStackingFrost(
        Unit source,Unit target,float duration,int stacksToFreeze,float freezeDuration)
    {
        if(!IsCombatActive(target))return false;
        CombatStatusEffect frost=target.combatStatuses.ApplyStacks(
            CombatStatusKind.ComboChilled,duration,
            1,stacksToFreeze,source,0f,0f,true);
        if(frost.stacks<stacksToFreeze)return false;
        target.combatStatuses.Remove(CombatStatusKind.ComboChilled);
        float appliedFreezeDuration=HostileStatusDuration(target,freezeDuration);
        target.combatStatuses.ApplyTimed(
            CombatStatusKind.Freeze,appliedFreezeDuration,source);
        PlayFreezeVisual(target,appliedFreezeDuration);
        return true;
    }

    private void HandleCombatStatusApplied(Unit target,CombatStatusEffect effect)
    {
        if(effect==null||effect.remaining<=0f||effect.stacks<=0)return;
        if(effect.kind==CombatStatusKind.Fear&&IsCombatActive(target))BeginFear(target);
        if(effect.kind==CombatStatusKind.Root&&IsCombatActive(target)&&SpiderSilkBound(target))
            BeginSpiderSilkBind(target);
        if(effect.kind==CombatStatusKind.Freeze&&IsCombatActive(target))
            PlayFreezeVisual(target,effect.remaining);
        if(effect.kind==CombatStatusKind.Silence&&IsCombatActive(target))
            AddCombatFloatText(target,"침묵",new Color(0.78f,0.7f,1f),true);
        if(effect.kind==CombatStatusKind.Root&&effect.magnitude>0f&&IsCombatActive(target)&&
           (target.fangLockDebuffEffect==null||
            !target.fangLockDebuffEffect.IsFangLockBinding(target.combatStatuses)))
        {
            SpriteRenderer renderer=target.spriteAnimation==null
                ?target.model.GetComponentInChildren<SpriteRenderer>()
                :target.spriteAnimation.GetComponent<SpriteRenderer>();
            target.fangLockDebuffEffect=PixelCombatEffect.PlaySabertoothFangBinding(
                renderer==null?target.model.transform:renderer.transform,renderer,target.combatStatuses);
            AddCombatFloatText(target,"공속 -"+
                Mathf.RoundToInt(effect.magnitude*100f)+"%",new Color(0.72f,0.9f,1f),true);
        }
    }

    private static void PlayFreezeVisual(Unit target,float duration)
    {
        if(target==null||target.model==null||!target.combatStatuses.Has(CombatStatusKind.Freeze))return;
        target.spriteAnimation?.SetFrozen(true);
        if(target.spriteAnimation==null&&target.animator!=null)target.animator.speed=0f;
        SpriteRenderer renderer=target.spriteAnimation==null
            ?target.model.GetComponentInChildren<SpriteRenderer>()
            :target.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelCombatEffect.PlayFreezeOverlay(
            target.spriteAnimation==null
                ?target.model.transform:target.spriteAnimation.transform,
            renderer,duration,target.combatStatuses);
        target.reaction?.PlayTintHit(new Color(0.62f,0.9f,1f));
    }

    private PixelStarProjectile EmitMagicStar(
        Unit source,Unit target,Color color,bool critical=false,Action onArrive=null)
    {
        if(source==null||target==null||source.model==null||target.model==null)return null;
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?null:source.spriteAnimation.GetComponent<SpriteRenderer>();
        SpriteRenderer targetRenderer=target.spriteAnimation==null
            ?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
        return PixelStarProjectile.Play(
            source.spriteAnimation==null?source.model.transform:source.spriteAnimation.transform,
            sourceRenderer,
            target.spriteAnimation==null?target.model.transform:target.spriteAnimation.transform,
            targetRenderer,color,critical,onArrive);
    }

    private void LaunchMilkyWayFragment(
        Unit source,Unit impactSource,Unit target,int fragmentIndex,bool frost,float rawDamage,int generation,
        Action<Unit,float> onHit,Action onFinished)
    {
        Color color=frost?new Color(0.38f,0.84f,1f):new Color(0.62f,0.64f,1f);
        Action resolve=() =>
        {
            if(generation==combatGeneration&&
               IsCombatActive(target))
            {
                SpriteRenderer renderer=target.spriteAnimation==null
                    ?target.model.GetComponentInChildren<SpriteRenderer>()
                    :target.spriteAnimation.GetComponent<SpriteRenderer>();
                Vector3 position=renderer==null?target.model.transform.position+Vector3.up*0.35f:renderer.bounds.center;
                float damage=ApplySkillDamage(source,target,rawDamage,false);
                PixelStarProjectile.PlayMilkyWayImpact(position,renderer,color,source.lastSkillHitCritical);
                PlayWizardSound(source,WizardSound.Hit,position,.55f);
                target.reaction?.PlayTintHit(Color.Lerp(color,Color.white,0.7f));
                if(frost&&IsCombatActive(target))
                    ApplyStackingFrost(source,target,WizardMouseCombatRules.FrostDuration,
                        WizardMouseCombatRules.FrostStacksToFreeze,WizardMouseCombatRules.FreezeDuration);
                onHit?.Invoke(target,damage);
            }
            onFinished?.Invoke();
        };
        PixelStarProjectile fragment=EmitMagicStar(
            impactSource,target,color,false,resolve);
        if(fragment==null)
        {
            onFinished?.Invoke();
            return;
        }
        fragment.name="Milky Way Fragment Star";
        fragment.OnDeflected=onFinished;
        fragment.SetCombatOwner(source.model.transform);
        fragment.SetImpactEnabled(false);
        fragment.SetMilkyWayArc(fragmentIndex);
    }

