    private bool UseGiraffeHighHeadSlam(Unit unit,SkillMasterRow skill)
    {
        if(unit==null||skill==null||!IsCombatActive(unit)||!IsCombatActive(unit.target))return false;
        Vector3 origin=Flat(unit.model.transform.position);
        Vector3 targetPoint=Flat(unit.target.model.transform.position);
        if(!IsWithinCommittedSkillReach(unit,unit.target,AttackDistance(unit,unit.target)+0.15f))
        {
            unit.skillTimer=0.25f;
            return false;
        }
        float radius=TileSize*Mathf.Max(0f,skill.radiusTiles)*unit.skillTraitRadiusMultiplier;
        if(CountActiveEnemiesInRadius(unit.team,targetPoint,radius)<=0)
        {
            unit.skillTimer=0.3f;
            return false;
        }

        bool empowered=false;
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,GiraffeCombatRules.ToyrafTraitId))
            empowered=GiraffeCombatRules.AdvanceAndConsumeEmpowerment(
                ref unit.giraffeBlocks);
        unit.giraffeSlamming=true;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="high_head_slam";
        unit.velocity=Vector3.zero;
        
        ClearRoute(unit);
        SetMoving(unit,false);
        ApplyPostSkillItemEffects(unit);
        if(unit.neckStrike!=null)unit.neckStrike.CancelAndRestore();
        Action<Vector3> impact=point=>ResolveGiraffeHighSlamImpact(
            unit,skill,Flat(point),1f,false,true,empowered);
        if(unit.highHeadSlam!=null)
            unit.highHeadSlam.Play(targetPoint+Vector3.up*0.2f,impact);
        else
            impact(targetPoint);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        return true;
    }

    private void ResolveGiraffeHighSlamImpact(
        Unit unit,SkillMasterRow skill,Vector3 origin,float effectScale,bool traitEcho,
        bool applyIntrinsic,bool empowered)
    {
        if(unit==null||skill==null||!IsCombatActive(unit))return;
        unit.giraffeSlamming=false;
        float radiusMultiplier=empowered?GiraffeCombatRules.EmpoweredRadiusMultiplier:1f;
        float damageMultiplier=empowered?GiraffeCombatRules.EmpoweredDamageMultiplier:1f;
        float radius=TileSize*Mathf.Max(0f,skill.radiusTiles)*
                     unit.skillTraitRadiusMultiplier*radiusMultiplier;
        List<Vector3> centers=TraitSkillCenters(unit,origin,radius);
        float effectiveRadius=centers.Count>1?radius*0.55f:radius;
        List<Unit> victims=units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=unit.team&&
            centers.Any(center=>Vector3.Distance(center,
                Flat(enemy.model.transform.position))<=effectiveRadius)).ToList();
        int hits=0;float dealt=0f;
        for(int i=0;i<victims.Count;i++)
        {
            Unit enemy=victims[i];
            if(!IsCombatActive(enemy))continue;
            bool secondary=enemy!=unit.target;
            Vector3 nearestCenter=centers.OrderBy(center=>Vector3.Distance(center,
                Flat(enemy.model.transform.position))).First();
            dealt+=ApplySkillFormulaDamage(unit,enemy,skill,secondary,0,
                effectScale*damageMultiplier*TraitAreaEffectScale(unit,nearestCenter,
                    Flat(enemy.model.transform.position),effectiveRadius),!traitEcho);
            if(IsCombatActive(enemy))
            {
                enemy.giraffeStunTimer=Mathf.Max(
                    enemy.giraffeStunTimer,HostileStatusDuration(enemy,
                        skill.statusDurationSeconds>0f?skill.statusDurationSeconds:
                        GiraffeCombatRules.StunDuration)*ConcertDurationScale(unit));
            }
            hits++;
        }
        unit.skillHits+=hits;unit.skillDamage+=dealt;
        unit.currentAction="high_head_slam_impact";
        CreateSkillPulseAt(origin,empowered
            ?new Color(1f,0.78f,0.18f):new Color(0.92f,0.64f,0.12f),
            radius/TileSize*1.25f);
        RecordSkillEvent(unit,skill.id+(traitEcho?"_echo":"_impact"),hits,dealt);
        if(!applyIntrinsic||hits<=0)return;

        if(MonsterTraitRuntime.Has(unit.activeTraitIds,GiraffeCombatRules.GiriniTraitId))
        {
            unit.skillTimer=GiraffeCombatRules.CooldownAfterHits(unit.skillTimer,hits);
            unit.traitActivations++;
        }
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,GiraffeCombatRules.GeriJacksonTraitId))
        {
            Vector3 away=Flat(unit.model.transform.position)-origin;
            if(away.sqrMagnitude<0.001f)away=-Flat(unit.model.transform.forward);
            DisplaceUnit(unit,away,
                TileSize*GiraffeCombatRules.MoonwalkDistanceTiles,false);
            unit.giraffeDanceAttackSpeedTimer=GateHaetaeBenefit(unit,GiraffeCombatRules.MoonwalkBuffDuration);
            unit.traitActivations++;
        }
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,GiraffeCombatRules.SerapiTraitId))
        {
            StartReleasedSkill(unit,ResolveSerapiSoulAfterimage(unit,skill,origin,radius,combatGeneration));
            unit.traitActivations++;
        }
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,GiraffeCombatRules.ToyrafTraitId))
            unit.traitActivations++;
    }

    private IEnumerator ResolveSerapiSoulAfterimage(
        Unit source,SkillMasterRow skill,Vector3 origin,float radius,int generation)
    {
        yield return new WaitForSeconds(GiraffeCombatRules.SoulAfterimageDelay);
        if(generation!=combatGeneration)yield break;
        int hits=0;float dealt=0f;
        for(int i=0;i<units.Count;i++)
        {
            Unit enemy=units[i];
            if(!IsCombatActive(enemy)||enemy.team==source.team||
               Vector3.Distance(origin,Flat(enemy.model.transform.position))>radius)continue;
            dealt+=ApplySkillDamage(source,enemy,
                source.damage*skill.damageMultiplier*GiraffeCombatRules.SoulAfterimageDamageRatio,
                false);
            hits++;
        }
        source.skillHits+=hits;source.skillDamage+=dealt;
        CreateSkillPulseAt(origin,new Color(0.52f,0.88f,1f,0.8f),radius/TileSize*1.15f);
        RecordSkillEvent(source,skill.id+"_soul_afterimage",hits,dealt);
    }

    private bool BeginSpiderCaptureWeb(Unit unit,SkillMasterRow skill)
    {
        if(unit==null||skill==null||!IsCombatActive(unit)||!IsCombatActive(unit.target))
            return false;
        Vector3 origin=Flat(unit.model.transform.position);
        Vector3 targetPoint=Flat(unit.target.model.transform.position);
        float maximumRange=TileSize*Mathf.Max(1f,skill.castRangeTiles)+
                           unit.collisionRadius+unit.target.collisionRadius;
        if(!IsWithinCommittedSkillReach(unit,unit.target,maximumRange))return false;

        unit.spiderWebPending=true;
        unit.spiderWebPrimaryTarget=unit.target;
        unit.spiderWebTarget=targetPoint;
        unit.spiderWebDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.spiderWebRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.attackMovementLockTimer=Mathf.Max(unit.attackMovementLockTimer,0.72f);
        unit.currentAction="giant_capture_web_prepare";
        // Arm the domain before an animation-free first hit can defeat a target.
        TriggerFamilyTranscendenceSkill(unit);
        unit.velocity=Vector3.zero;
        StopBeforeAttack(unit);
        
        ClearRoute(unit);
        SetMoving(unit,false);
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(unit.spriteAnimation==null)
            LaunchSpiderCaptureWeb(unit,skill,1f,false,combatGeneration);
        return true;
    }

    private void LaunchSpiderCaptureWeb(Unit unit,SkillMasterRow skill,
        float effectScale,bool traitEcho,int generation)
    {
        if(generation!=combatGeneration||unit==null||unit.model==null||skill==null||
           !IsCombatActive(unit))return;
        if(!traitEcho&&HasFamilyTranscendence(unit)&&IsSpiderFamily(unit))
        {
            if(!SilkQueenCinematicPending(unit))ReleaseSilkQueenCocoons(unit);
            return;
        }
        SpriteRenderer sourceRenderer=unit.spriteAnimation==null
            ?null:unit.spriteAnimation.GetComponent<SpriteRenderer>();
        if(!traitEcho&&unit.spiderWebCharge!=null)unit.spiderWebCharge.Cancel();
        // Flight owns its cast snapshot: an echo or a later cast cannot move this net.
        Vector3 target=unit.spiderWebTarget;
        float damageMultiplier=traitEcho?1f:unit.spiderWebDamageMultiplier;
        float radiusMultiplier=traitEcho?1f:unit.spiderWebRadiusMultiplier;
        int cast=unit.skillUses;
        bool heavenly=!traitEcho&&HasRank3(unit,ArachneRank3Rules.HeavenlyNet);
        Action land=()=>ResolveSpiderCaptureWeb(unit,skill,effectScale,traitEcho,generation,
            target,damageMultiplier,radiusMultiplier,cast);
        if(!traitEcho&&(HasRank3(unit,ArachneRank3Rules.CocoonFuneral)||
                       HasRank3(unit,ArachneRank3Rules.EightfoldWeb))){land();return;}
        if(mlEpisodeActive)
        {
            if(!DeflectGriffinProjectile(unit.team,unit.model.transform.position+Vector3.up*.5f,target,null))land();
            return;
        }
        PlaySpiderSound(unit,SpiderSound.Launch,unit.model.transform.position);
        PixelSpiderCaptureNet.Throw(sourceRenderer,
            sourceRenderer==null?unit.model.transform.position+Vector3.up*.5f:sourceRenderer.bounds.center,
            target,TileSize*(heavenly?ArachneRank3Rules.HeavenlyRadiusTiles:Mathf.Max(.1f,skill.radiusTiles))*radiusMultiplier,SpiderSilkColor(unit),
            ()=>ReleasedSkillValid(unit,generation),land,heavenly,
            ()=>PlaySpiderSound(unit,SpiderSound.Spread,target));
    }

    private bool ResolveSpiderCaptureWeb(Unit unit,SkillMasterRow skill,
        float effectScale,bool traitEcho,int generation,Vector3 targetPoint,
        float damageMultiplier,float radiusMultiplier,int cast)
    {
        if(generation!=combatGeneration||unit==null||skill==null)
            return false;
        Vector3 origin=Flat(unit.model.transform.position);
        if(!traitEcho&&unit.skillUses==cast)
        {
            unit.spiderWebPending=false;
            unit.spiderWebDamageMultiplier=1f;
            unit.spiderWebRadiusMultiplier=1f;
        }
        if(!traitEcho&&TryResolveArachneRank3(
               unit,skill,targetPoint,effectScale*damageMultiplier,
               radiusMultiplier,generation))return true;
        float radius=TileSize*Mathf.Max(0.1f,skill.radiusTiles)*radiusMultiplier;
        List<Vector3> webCenters=TraitSkillCenters(unit,targetPoint,radius);
        float webRadius=webCenters.Count>1?radius*0.55f:radius;
        bool webWall=MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_skill_web_wall");
        Vector3 wallDirection=targetPoint-origin;
        if(wallDirection.sqrMagnitude<0.001f)wallDirection=Vector3.forward;
        Vector3 wallAxis=Vector3.Cross(Vector3.up,wallDirection.normalized);
        List<Unit> victims=units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=unit.team&&
            (webWall?IsPointInsideForwardSkillLine(targetPoint-wallAxis*radius,wallAxis,
                 Flat(enemy.model.transform.position),radius*2f,TileSize*0.28f+enemy.collisionRadius):
             webCenters.Any(center=>Vector3.Distance(center,
                 Flat(enemy.model.transform.position))<=webRadius))).ToList();

        int hits=0;float dealt=0f;
        for(int i=0;i<victims.Count;i++)
        {
            Unit enemy=victims[i];
            Vector3 effectCenter=webCenters.OrderBy(center=>Vector3.Distance(center,
                Flat(enemy.model.transform.position))).First();
            float compressed=MonsterTraitRuntime.Has(unit.activeTraitIds,
                "trait_skill_time_compression")?1.4f:1f;
            dealt+=ApplySkillFormulaDamage(unit,enemy,skill,false,0,
                effectScale*damageMultiplier*compressed*
                TraitAreaEffectScale(unit,effectCenter,
                    Flat(enemy.model.transform.position),webRadius),!traitEcho);
            if(!mlEpisodeActive&&enemy.spriteAnimation!=null)
                PixelSpiderCaptureNet.Hit(enemy.spriteAnimation.GetComponent<SpriteRenderer>(),SpiderSilkColor(unit));
            hits++;
        }

        float duration=Mathf.Max(0.2f,skill.durationSeconds*effectScale*
            (MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_skill_time_compression")?0.6f:1f));
        if(webWall)
            CreateSpiderWebZone(unit,targetPoint,radius,duration,!traitEcho);
        else foreach(Vector3 center in webCenters)
            CreateSpiderWebZone(unit,center,webRadius,duration,!traitEcho);
        unit.skillHits+=hits;
        unit.skillDamage+=dealt;
        unit.currentAction="giant_capture_web";
        StopBeforeAttack(unit);
        RecordSkillEvent(unit,skill.id+(traitEcho?"_echo":"_cast"),hits,dealt);
        return true;
    }

    private void UpdateCombatStatuses(
        Unit unit,float dt,bool pauseNonControlHarmful=false,
        bool pauseShield=false)
    {
        periodicStatusUnit=unit;
        unit.combatStatuses.Tick(
            dt,periodicStatusTick,pauseNonControlHarmful,pauseShield);
        periodicStatusUnit=null;
        UpdateMoraleVeil(unit);
        CombatStatusEffect poison=unit.combatStatuses.Get(CombatStatusKind.Poison);
        if(poison!=null&&!IsCombatActive(poison.source as Unit))
            unit.combatStatuses.Remove(CombatStatusKind.Poison);
        CombatStatusEffect bleed=unit.combatStatuses.Get(CombatStatusKind.Bleed);
        if(bleed!=null&&!IsCombatActive(bleed.source as Unit))
            unit.combatStatuses.Remove(CombatStatusKind.Bleed);
        CombatStatusEffect burning=
            unit.combatStatuses.Get(CombatStatusKind.Burning);
        if(burning!=null&&burning.magnitude>0f&&
           !IsCombatActive(burning.source as Unit))
            unit.combatStatuses.Remove(CombatStatusKind.Burning);
    }

    private void HandlePeriodicStatusTick(CombatStatusEffect effect)
    {
        Unit unit=periodicStatusUnit;
        if(unit==null||
           effect.kind!=CombatStatusKind.Poison&&
           effect.kind!=CombatStatusKind.Bleed&&
           effect.kind!=CombatStatusKind.Burning)return;
        Unit source=effect.source as Unit;
        if(!IsCombatActive(source)||!IsCombatActive(unit))return;
        float damage=effect.magnitude*(effect.kind==CombatStatusKind.Poison
            ?Mathf.Max(1,effect.stacks):1);
        if(damage<=0f)return;
        ApplyDamageComponents(source,unit,damage,false,false,false,false,
            0f,0f,1f,false,false,false,0f,effect.regionDamageScaled);
        PlayPeriodicStatusDamageEffect(unit,effect.kind);
    }

    private static void PlayPeriodicStatusDamageEffect(
        Unit target,CombatStatusKind kind)
    {
        if(target==null||target.model==null)return;
        SpriteRenderer renderer=target.spriteAnimation==null
            ?target.model.GetComponentInChildren<SpriteRenderer>()
            :target.spriteAnimation.GetComponent<SpriteRenderer>();
        Transform anchor=target.spriteAnimation==null
            ?target.model.transform:target.spriteAnimation.transform;
        if(kind==CombatStatusKind.Poison)
        {
            PixelCombatEffect.PlayPoisonBurst(target.model.transform,renderer);
            target.reaction?.PlayTintHit(new Color(0.3f,1f,0.18f));
        }
        else if(kind==CombatStatusKind.Bleed)
            PixelCombatEffect.PlayBleedBurst(anchor,renderer);
        else if(kind==CombatStatusKind.Burning)
        {
            ParticleSystem flame=PixelCombatEffect.PlayNinjaFlameAfterimage(
                Flat(target.model.transform.position),.42f,renderer);
            if(flame!=null)flame.name="Burning Tick Burst";
            target.reaction?.PlayTintHit(new Color(1f,.28f,.04f));
        }
    }

    private void UpdateMoraleVeil(Unit unit)
    {
        if(unit==null||!MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_combo_morale_veil"))return;
        CombatStatusEffect shield=unit.combatStatuses.Get(CombatStatusKind.Shield);
        Unit provider=shield==null?null:shield.source as Unit;
        bool allied=provider!=null&&provider!=unit&&provider.team==unit.team;
        if(allied&&shield.magnitude>unit.traitState.observedAlliedShield+0.01f)
        {
            unit.traitState.observedAlliedShield=shield.magnitude;
            unit.traitState.observedShieldSource=provider;
            unit.combatStatuses.ApplyTimed(CombatStatusKind.ComboRally,
                Mathf.Max(1f,shield.remaining),provider,0.2f);
            RecordComboActivation(unit,unit,"trait_combo_morale_veil",0f);
            return;
        }
        if(shield!=null||unit.traitState.observedAlliedShield<=0f)return;
        unit.traitState.observedAlliedShield=0f;
        unit.traitState.observedShieldSource=null;
        Vector3 center=Flat(unit.model.transform.position);
        foreach(Unit ally in units)
            if(ally!=unit&&IsCombatActive(ally)&&ally.team==unit.team&&
               Vector3.Distance(center,Flat(ally.model.transform.position))<=TileSize*1.5f)
                ally.combatStatuses.ApplyTimed(CombatStatusKind.ComboRally,3f,unit,0.1f);
    }

    private float SpiderMovementMultiplier(Unit unit)
    {
        float slow=0f;
        Vector3 position=Flat(unit.model.transform.position);
        for(int i=0;i<spiderWebZones.Count;i++)
        {
            SpiderWebZone zone=spiderWebZones[i];
            if(zone.source==null||zone.source.team==unit.team||zone.remaining<=0f)continue;
            if(Vector3.Distance(position,zone.center)<=zone.radius)
                slow=Mathf.Max(slow,SpiderCombatRules.SlowRatio(zone.freezingSilk));
        }
        return Mathf.Clamp01(1f-slow);
    }

    private int SpiderToxicStacks(Unit target)
    {
        int stacks=0;
        for(int i=0;i<spiderWebZones.Count;i++)
        {
            SpiderWebZone zone=spiderWebZones[i];
            if(zone.remaining<=0f||!zone.toxicPrank)continue;
            if(zone.toxicStacks.TryGetValue(target,out int current))
                stacks=Mathf.Max(stacks,current);
        }
        return stacks;
    }

    private SpiderWebZone CreateSpiderWebZone(Unit source,Vector3 center,float radius,float duration,
        bool applyIntrinsic)
    {
        bool preciseKnot=applyIntrinsic&&MonsterTraitRuntime.Has(
            source.activeTraitIds,SpiderCombatRules.AraneaTraitId);
        bool desertSilk=applyIntrinsic&&MonsterTraitRuntime.Has(
            source.activeTraitIds,SpiderCombatRules.SilantiTraitId);
        bool toxicPrank=applyIntrinsic&&MonsterTraitRuntime.Has(
            source.activeTraitIds,SpiderCombatRules.RagonTraitId);
        bool freezingSilk=applyIntrinsic&&MonsterTraitRuntime.Has(
            source.activeTraitIds,SpiderCombatRules.IcearachneTraitId);
        Color color=freezingSilk
            ?new Color(0.45f,0.86f,1f)
            :toxicPrank
                ?new Color(1f,0.52f,0.9f)
                :desertSilk
                    ?new Color(0.92f,0.78f,0.48f):new Color(0.88f,0.92f,0.96f);
        GameObject root=CreateSpiderWebVisual(source,center,radius,color);
        var zone=new SpiderWebZone
        {
            source=source,center=center,radius=radius,remaining=duration,
            tickTimer=0f,preciseKnot=preciseKnot,desertSilk=desertSilk,
            toxicPrank=toxicPrank,freezingSilk=freezingSilk,
            root=root,material=null
        };
        spiderWebZones.Add(zone);return zone;
    }

    private void ResolveHeavenlyCaptureNet(Unit source,Vector3 center,float scale,float radiusScale)
    {
        float radius=TileSize*ArachneRank3Rules.HeavenlyRadiusTiles*radiusScale;
        SpiderWebZone zone=CreateSpiderWebZone(source,center,radius,ArachneRank3Rules.HeavenlyDuration,true);
        zone.heavenly=true;zone.damageScale=scale;zone.captureRemaining=ArachneRank3Rules.HeavenlyPullDuration;
        if(zone.root!=null)zone.root.GetComponent<PixelSpiderCaptureNet>().GatherHeavenly();
        PlaySpiderSound(source,SpiderSound.Pull,center);
        int hits=0;float dealt=0f;
        foreach(Unit enemy in units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=source.team&&
                    Vector3.Distance(center,Flat(enemy.model.transform.position))<=radius).ToArray())
        {
            dealt+=Rank3Hit(source,enemy,ArachneRank3Rules.HeavenlyOpenRatio*scale);hits++;
            if(!IsCombatActive(enemy))continue;
            if(!mlEpisodeActive&&Rank3Renderer(enemy)!=null)PixelSpiderCaptureNet.Hit(Rank3Renderer(enemy),SpiderSilkColor(source));
            Vector3 inward=center-Flat(enemy.model.transform.position);
            float distance=Mathf.Min(inward.magnitude,TileSize*(zone.preciseKnot?
                ArachneRank3Rules.HeavenlyPrecisePullTiles:ArachneRank3Rules.HeavenlyPullTiles));
            if(DisplaceUnit(enemy,inward,distance,spiderCapturePull:true))
            {
                enemy.displacementDuration=ArachneRank3Rules.HeavenlyPullDuration;
                enemy.attackMovementLockTimer=Mathf.Max(enemy.attackMovementLockTimer,ArachneRank3Rules.HeavenlyPullDuration);
            }
            zone.captureTargets[enemy]=enemy.positionRevision;
            UpdateSpiderSilkBinding(zone,enemy,.01f);
        }
        source.currentAction="heavenly_net_gather";source.traitActivations++;
        RecordSkillEvent(source,ArachneRank3Rules.HeavenlyNet+"_land",hits,dealt);
    }

    private void UpdateHeavenlyCapture(SpiderWebZone zone,float dt)
    {
        zone.captureRemaining=Mathf.Max(0f,zone.captureRemaining-dt);
        foreach(KeyValuePair<Unit,int> capture in zone.captureTargets)
        {
            Unit enemy=capture.Key;
            if(zone.controlledEnemies.Contains(enemy))continue;
            if(!IsCombatActive(enemy)||Vector3.Distance(zone.center,Flat(enemy.model.transform.position))>zone.radius)
            {
                if(zone.bindings.TryGetValue(enemy,out PixelSpiderSilkBind loose)&&loose!=null)loose.Stop();
                zone.bindings.Remove(enemy);
                if(zone.captureRemaining<=0f)zone.controlledEnemies.Add(enemy);
                continue;
            }
            PixelSpiderSilkBind silk=UpdateSpiderSilkBinding(zone,enemy,SpiderCombatRules.RequiredStayDuration*
                (1f-zone.captureRemaining/ArachneRank3Rules.HeavenlyPullDuration));
            if(zone.captureRemaining>0f)continue;
            // Zones tick before units; wait for the last pull frame before freezing the body.
            if(enemy.displacing&&enemy.positionRevision==capture.Value)continue;
            zone.controlledEnemies.Add(enemy);
            CombatStatusKind kind=zone.freezingSilk?CombatStatusKind.Freeze:CombatStatusKind.Root;
            float duration=zone.freezingSilk?SpiderCombatRules.FreezingSilkDuration:SpiderCombatRules.RootDuration(zone.preciseKnot);
            zone.source.traitActivations++;
            CombatStatusEffect status=enemy.combatStatuses.ApplyTimed(kind,HostileStatusDuration(enemy,duration),zone.source);
            if(status.remaining>0f&&status.stacks>0)
            {
                silk?.Tighten();
                PlaySpiderSound(zone.source,SpiderSound.Bind,enemy.model.transform.position);
                if(zone.freezingSilk)PlayFreezeVisual(enemy,status.remaining);
            }
        }
    }

    private void HeavenlyNetDamage(SpiderWebZone zone,List<Unit> inside,float ratio,bool final)
    {
        PlaySpiderSound(zone.source,final?SpiderSound.NetBreak:SpiderSound.Pull,zone.center,final?1f:.45f);
        int hits=0;float dealt=0f;
        foreach(Unit enemy in inside)
        {
            if(!IsCombatActive(enemy))continue;
            dealt+=Rank3GroundHit(zone.source,enemy,ratio*zone.damageScale);hits++;
            if(!mlEpisodeActive&&Rank3Renderer(enemy)!=null)
                PixelSpiderCaptureNet.Hit(Rank3Renderer(enemy),SpiderSilkColor(zone.source),final);
        }
        if(!final&&zone.root!=null)zone.root.GetComponent<PixelSpiderCaptureNet>()?.Pulse();
        RecordSkillEvent(zone.source,ArachneRank3Rules.HeavenlyNet+(final?"_break":"_tighten"),hits,dealt);
    }

    private GameObject CreateSpiderWebVisual(
        Unit source,Vector3 center,float radius,Color color)
    {
        if(mlEpisodeActive)return null;
        SpriteRenderer sortingReference=source==null||source.spriteAnimation==null
            ?null:source.spriteAnimation.GetComponent<SpriteRenderer>();
        return PixelSpiderCaptureNet.Ground(sortingReference,center,radius,color);
    }

    private static Color SpiderSilkColor(Unit source)=>
        source?.spiritConcertOwner!=null?PixelSpiritConcert.Color:
        MonsterTraitRuntime.Has(source.activeTraitIds,SpiderCombatRules.IcearachneTraitId)?new Color(.45f,.86f,1f):
        MonsterTraitRuntime.Has(source.activeTraitIds,SpiderCombatRules.RagonTraitId)?new Color(1f,.52f,.9f):
        MonsterTraitRuntime.Has(source.activeTraitIds,SpiderCombatRules.SilantiTraitId)?new Color(.92f,.78f,.48f):
        new Color(.88f,.92f,.96f);

    private static bool SpiderSilkBound(Unit unit)=>
        unit!=null&&IsSpiderFamily(unit.combatStatuses.Get(CombatStatusKind.Root)?.source as Unit);

    private void BeginSpiderSilkBind(Unit unit)
    {
        // Stop the victim's actions; an external throw or the web's inward pull can still finish.
        if(!unit.displacing&&unit.preyDraggedBy==null)InterruptPositionalAction(unit);
        if(unit.fangLockTarget!=null)FinishFangLock(unit,false);
        unit.highHeadSlam?.CancelAndRestore();unit.neckStrike?.CancelAndRestore();
        unit.giraffeSlamming=false;unit.bearSpiritPending=false;unit.bearAvatarRoarPending=false;
        if(unit.bearResolveTimer<=0f)unit.bearSpiritFx?.Cancel();
        ClearRoute(unit);unit.hexStepping=false;
        unit.currentAction="silk_bound";StopUnitMovement(unit);
        unit.spriteAnimation?.StopForSilkBinding();
        if(unit.spriteAnimation==null&&unit.animator!=null)unit.animator.speed=0f;
        if(!mlEpisodeActive)AddCombatFloatText(unit,"속박",SpiderSilkColor(unit.combatStatuses.Get(CombatStatusKind.Root).source as Unit),true);
    }

    private PixelSpiderSilkBind UpdateSpiderSilkBinding(SpiderWebZone zone,Unit enemy,float stay)
    {
        if(mlEpisodeActive||enemy.spriteAnimation==null)return null;
        if(!zone.bindings.TryGetValue(enemy,out PixelSpiderSilkBind silk)||silk==null)
        {
            int generation=combatGeneration;
            silk=PixelSpiderSilkBind.Play(enemy.spriteAnimation.GetComponent<SpriteRenderer>(),SpiderSilkColor(zone.source),()=>
            {
                if(this==null||generation!=combatGeneration||!IsCombatActive(enemy))return false;
                if(!zone.controlledEnemies.Contains(enemy))return zone.remaining>0f&&
                    Vector3.Distance(zone.center,Flat(enemy.model.transform.position))<=zone.radius;
                CombatStatusEffect status=enemy.combatStatuses.Get(zone.freezingSilk?CombatStatusKind.Freeze:CombatStatusKind.Root);
                return status!=null&&status.remaining>0f&&status.source==zone.source;
            });
            zone.bindings[enemy]=silk;
        }
        silk?.SetProgress(stay/SpiderCombatRules.RequiredStayDuration);
        return silk;
    }

    private void PlaySpiderPullTether(Unit target,Vector3 center)
    {
        if(mlEpisodeActive||target==null||target.model==null)return;
        GameObject root=new GameObject("Spider Pull Tether");
        LineRenderer line=root.AddComponent<LineRenderer>();
        line.sharedMaterial=skillRadiusMarkerMaterial;
        line.useWorldSpace=true;
        line.positionCount=3;
        line.startWidth=0.055f;
        line.endWidth=0.025f;
        line.numCapVertices=2;
        line.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;
        line.receiveShadows=false;
        line.startColor=new Color(0.82f,0.96f,1f,0.88f);
        line.endColor=new Color(0.5f,0.82f,1f,0.25f);
        Vector3 start=target.model.transform.position+Vector3.up*0.42f;
        Vector3 end=center+Vector3.up*0.1f;
        line.SetPosition(0,start);
        line.SetPosition(1,(start+end)*0.5f+Vector3.up*0.12f);
        line.SetPosition(2,end);
        PlayTraitBurst(target,new Color(0.82f,0.96f,1f),false);
        Destroy(root,0.32f);
    }

    private void UpdateSpiderWebZones(float dt)
    {
        for(int index=spiderWebZones.Count-1;index>=0;index--)
        {
            SpiderWebZone zone=spiderWebZones[index];
            if(zone.heavenly&&zone.source==null)
            {
                DestroySpiderWebZone(zone);spiderWebZones.RemoveAt(index);continue;
            }
            float activeDelta=Mathf.Min(Mathf.Max(0f,dt),zone.remaining);
            zone.remaining=Mathf.Max(0f,zone.remaining-dt);
            List<Unit> inside=units.Where(enemy=>IsCombatActive(enemy)&&
                zone.source!=null&&enemy.team!=zone.source.team&&
                Vector3.Distance(zone.center,
                    Flat(enemy.model.transform.position))<=zone.radius).ToList();
            if(zone.heavenly)UpdateHeavenlyCapture(zone,activeDelta);
            for(int i=0;!zone.heavenly&&i<inside.Count;i++)
            {
                Unit enemy=inside[i];
                float stay=zone.stayTimes.TryGetValue(enemy,out float current)
                    ?current+activeDelta:activeDelta;
                zone.stayTimes[enemy]=stay;
                if(zone.controlledEnemies.Contains(enemy))continue;
                PixelSpiderSilkBind silk=UpdateSpiderSilkBinding(zone,enemy,stay);
                if(stay<SpiderCombatRules.RequiredStayDuration)continue;
                zone.controlledEnemies.Add(enemy);
                if(zone.freezingSilk)
                {
                    float freezeDuration=HostileStatusDuration(enemy,
                        SpiderCombatRules.FreezingSilkDuration);
                    enemy.combatStatuses.ApplyTimed(
                        CombatStatusKind.Freeze,freezeDuration,zone.source);
                    PlayFreezeVisual(enemy,freezeDuration);
                }
                else
                {
                    enemy.combatStatuses.ApplyTimed(
                        CombatStatusKind.Root,
                        HostileStatusDuration(enemy,
                            SpiderCombatRules.RootDuration(zone.preciseKnot)),zone.source);
                    if(zone.preciseKnot)
                    {
                        PlaySpiderPullTether(enemy,zone.center);
                        DisplaceUnit(enemy,zone.center-
                            Flat(enemy.model.transform.position),
                            TileSize*SpiderCombatRules.PreciseKnotPullDistanceTiles);
                    }
                }
                CombatStatusEffect control=enemy.combatStatuses.Get(zone.freezingSilk?CombatStatusKind.Freeze:CombatStatusKind.Root);
                if(control!=null&&control.remaining>0f&&control.source==zone.source)
                {
                    silk?.Tighten();
                    PlaySpiderSound(zone.source,SpiderSound.Bind,enemy.model.transform.position);
                }
                if(zone.preciseKnot||zone.freezingSilk)
                    zone.source.traitActivations++;
            }
            foreach(Unit tracked in zone.stayTimes.Keys.ToArray())
                if(!inside.Contains(tracked)&&!zone.controlledEnemies.Contains(tracked))
                {
                    zone.stayTimes[tracked]=0f;
                    if(zone.bindings.TryGetValue(tracked,out PixelSpiderSilkBind silk)&&silk!=null)silk.Stop();
                    zone.bindings.Remove(tracked);
                }

            zone.tickTimer+=activeDelta;
            while(zone.tickTimer>=SpiderCombatRules.TraitTickInterval)
            {
                zone.tickTimer-=SpiderCombatRules.TraitTickInterval;
                if(zone.heavenly)HeavenlyNetDamage(zone,inside,ArachneRank3Rules.HeavenlyTickRatio,false);
                ResolveSpiderWebTraitTick(zone,inside);
            }
            if(zone.remaining>0f)continue;
            if(zone.heavenly)HeavenlyNetDamage(zone,inside,ArachneRank3Rules.HeavenlyFinalRatio,true);
            DestroySpiderWebZone(zone);
            spiderWebZones.RemoveAt(index);
        }
    }

    private void ResolveSpiderWebTraitTick(SpiderWebZone zone,List<Unit> inside)
    {
        if(zone==null||inside.Count==0)return;
        int hits=0;float dealt=0f;
        for(int i=0;i<inside.Count;i++)
        {
            Unit enemy=inside[i];
            if(!IsCombatActive(enemy))continue;
            if(zone.desertSilk)
            {
                dealt+=ApplyGroundSkillDamage(zone.source,enemy,
                    SpiderCombatRules.DesertSilkDamage(zone.source.damage)*zone.damageScale,false);
                enemy.reaction?.PlayTintHit(new Color(1f,0.78f,0.32f));
                PlayTraitBurst(enemy,new Color(0.96f,0.72f,0.24f),false);
                hits++;
            }
            if(!zone.toxicPrank)continue;
            int stacks=zone.toxicStacks.TryGetValue(enemy,out int current)
                ?current+1:1;
            if(stacks>=SpiderCombatRules.ToxicPrankStacks)
            {
                dealt+=ApplyGroundSkillDamage(zone.source,enemy,
                    SpiderCombatRules.ToxicPrankDamage(zone.source.damage)*zone.damageScale,false);
                hits++;
                stacks=0;
                PlayPeriodicStatusDamageEffect(enemy,CombatStatusKind.Poison);
                PlayTraitBurst(enemy,new Color(0.72f,0.12f,0.82f),true);
            }
            zone.toxicStacks[enemy]=stacks;
        }
        zone.source.skillHits+=hits;
        zone.source.skillDamage+=dealt;
        if(hits>0)zone.source.traitActivations++;
        if(hits>0)RecordSkillEvent(
            zone.source,zone.source.skillId+"_web_tick",hits,dealt);
    }

    private void ClearSpiderWebZones()
    {
        foreach(PixelEightfoldWeb web in eightfoldWebs)if(web!=null)web.Cancel();
        eightfoldWebs.Clear();
        foreach(PixelSpiderSilkBind cocoon in funeralCocoons)if(cocoon!=null)cocoon.Cancel();
        funeralCocoons.Clear();
        for(int i=0;i<spiderWebZones.Count;i++)DestroySpiderWebZone(spiderWebZones[i],true);
        spiderWebZones.Clear();
        for(int i=0;i<rank3SpiderWebVisuals.Count;i++)
            if(rank3SpiderWebVisuals[i]!=null)Destroy(rank3SpiderWebVisuals[i]);
        rank3SpiderWebVisuals.Clear();
    }

    private static void DestroySpiderWebZone(SpiderWebZone zone,bool immediate=false)
    {
        if(zone==null)return;
        foreach(PixelSpiderSilkBind silk in zone.bindings.Values)
            if(silk!=null){if(immediate)silk.Cancel();else if(!silk.Bound)silk.Stop();}
        if(zone.root!=null)
        {
            PixelSpiderCaptureNet net=zone.root.GetComponent<PixelSpiderCaptureNet>();
            if(net!=null){if(immediate)net.Cancel();else net.Break();}
            else Destroy(zone.root);
        }
        if(zone.material!=null)Destroy(zone.material);
    }

    private bool DisplaceUnit(
        Unit unit,Vector3 direction,float distance,bool interruptAction=true,bool allowInPlace=false,bool spiderCapturePull=false,bool crowdPush=false)
    {
        if(!IsCombatActive(unit)||direction.sqrMagnitude<0.001f||distance<=0f)return false;
        // Voluntary repositioning (recoil, pursuit) is not hostile control.
        if(interruptAction&&PreyDisplacementImmune(unit))return false;
        Vector3 start=Flat(unit.model.transform.position);
        Vector3 desired=start+Flat(direction).normalized*distance;
        // Capture crowds move together; resolve bodies during movement, not against their starting positions.
        Vector3 resolved=spiderCapturePull||crowdPush?ResolveFreePosition(desired,unit.collisionRadius):ResolveUnitMovement(unit,start,desired);
        float resolvedDistance=Vector3.Distance(start,resolved);
        if(resolvedDistance<0.08f&&!allowInPlace)return false;
        if(interruptAction)InterruptPositionalAction(unit);
        ClearRoute(unit);
        
        unit.hexStepping=false;
        unit.hexStepTarget=unit.currentTile;
        unit.velocity=Vector3.zero;
        unit.frogHopping=false;
        unit.frogHopProgress=0f;
        unit.displacing=true;
        unit.spiderCapturePull=spiderCapturePull;
        unit.displacementStart=start;
        unit.displacementEnd=resolved;
        unit.displacementProgress=0f;
        unit.displacementArcHeight=0f;
        unit.displacementCheckUnits=spiderCapturePull||crowdPush;
        unit.displacementSlam=false;
        unit.displacementDuration=Mathf.Clamp(
            resolvedDistance/(TileSize*4f),0.14f,0.3f);
        unit.attackMovementLockTimer=Mathf.Max(
            unit.attackMovementLockTimer,
            unit.displacementDuration+DisplacementRecoveryDuration);
        unit.currentAction="displaced";
        unit.moving=false;
        SetMoving(unit,false);
        return true;
    }

    private static void InterruptPositionalAction(Unit unit)
    {
        unit.wolfStampede?.owner?.CancelWolfStampedeFor(unit);
        unit.wizardCygnusShower?.owner?.CancelWizardCygnusShowerFor(unit);
        InterruptCrocodileAbyssDive(unit);
        InterruptFrogGrandSlam(unit);
        if(unit.sabertoothDevour!=null)unit.sabertoothDevour.owner.EndSabertoothDevour(unit);
        ClearUnitInertia(unit);
        EndHaetaeBellowPush(unit);
        InterruptWyvernBreath(unit.wyvernBreath);
        InterruptHaetaeRoar(unit.haetaeRoar);
        EndGriffinHunt(unit);
        if(unit.griffinHeldBy!=null&&unit.griffinHeldBy.griffinHunt!=null)
            ReleaseGriffinHuntVictim(unit.griffinHeldBy,unit.griffinHeldBy.griffinHunt);
        ReleaseBeetleOverturnPassenger(unit);
        ReleaseBeetleGravityVictim(unit);
        if(unit.beetleFlippedBy!=null&&unit.beetleFlippedBy.beetleFlip!=null)
            ReleaseBeetleVictim(unit.beetleFlippedBy,unit.beetleFlippedBy.beetleFlip);
        unit.tyrannoMawPulledBy=null;
        unit.tyrannoPushedBy=null;
        unit.spiderCapturePull=false;
        unit.wizardBarragePending=false;
        unit.wizardBarrageTargets=null;
        if(unit.wizardBarrageFan!=null&&!CombatEffectEndFade.IsFading(unit.wizardBarrageFan))Destroy(unit.wizardBarrageFan.gameObject);
        unit.wizardBarrageFan=null;
        unit.crocodilePreyFlying=false;
        unit.spriteBillboard?.SetRollPose(0f,Vector3.zero,Vector3.zero);
        unit.crocodileBiteLockTimer=0f;
        unit.crocodileRollTarget=null;
        unit.spriteAnimation?.SetSkillPoseScale(Vector3.one);
        unit.positionRevision++;
        if(unit.spriteAnimation!=null)
            unit.spriteAnimation.InterruptCurrentAction();
        unit.tongueWhip?.Cancel();
        unit.tongueHarpoonTarget=null;
        if((unit.displacementArcHeight>0f||unit.griffinSkyfalling)&&unit.model!=null)
            unit.model.transform.position=Flat(unit.model.transform.position)+
                Vector3.up*unit.visualHeightOffset;
        unit.displacementArcHeight=0f;
        unit.displacementSlam=false;
        unit.frogHopping=false;
        unit.frogHopProgress=0f;
        unit.leaping=false;
        unit.leapTarget=null;
        unit.griffinSkyfalling=false;
        unit.griffinSkyfallPending=false;
        unit.griffinSkyfallTarget=null;
        unit.griffinSkyfallProgress=0f;
        unit.griffinDiveFx?.Cancel();unit.griffinDiveFx=null;
        unit.shadowSlashing=false;
        unit.shadowSlashProgress=0f;
        unit.shadowSlashTarget=null;
        unit.shadowSlashVictims.Clear();
        unit.wolfHuntPending=false;
        unit.wolfHuntTarget=null;
        CancelWolfHuntAfterimages(unit);
        unit.ninjaHuntPending=false;
        unit.ninjaHuntTarget=null;
        unit.mammothChargePending=false;
        unit.mammothChargeTarget=null;
    }

    private void UpdateDisplacement(Unit unit,float dt)
    {
        float previousProgress=unit.displacementProgress;
        bool pressurePush=unit.haetaeBellowPushedBy!=null;
        unit.displacementProgress=Mathf.Clamp01(
            unit.displacementProgress+dt/Mathf.Max(0.01f,unit.displacementDuration));
        Vector3 intended=EvaluateDisplacementPosition(
            unit.displacementStart,unit.displacementEnd,unit.displacementProgress);
        if(pressurePush)intended=Vector3.Lerp(unit.displacementStart,unit.displacementEnd,
            HaetaeRank3Rules.BellowPushProgress(unit.displacementProgress));
        Vector3 ground=ResolveFreePosition(intended,unit.collisionRadius);
        if(unit.crocodilePreyFlying)
        {
            Vector3 previous=Flat(unit.model.transform.position);
            float earliest=1f;
            bool collided=false;
            for(int i=0;i<units.Count;i++)
            {
                Unit other=units[i];
                if(other==unit||!IsCombatActive(other)||other.team!=unit.team)continue;
                if(!CrocodileCombatRules.TryPreyCannonContact(previous,ground,
                       other.model.transform.position,unit.collisionRadius+other.collisionRadius,
                       out float fraction)||fraction>earliest)continue;
                earliest=fraction;collided=true;
            }
            if(collided)
            {
                ground=Vector3.Lerp(previous,ground,earliest);
                unit.displacementProgress=1f;
            }
        }
        if(unit.spiderCapturePull)
        {
            Vector3 previous=Flat(unit.model.transform.position),movement=ground-previous;
            float clearFraction=1f;
            foreach(Unit other in units)
            {
                if(other==unit||!IsCombatActive(other))continue;
                Vector3 center=Flat(other.model.transform.position),offset=previous-center;
                float clearance=unit.collisionRadius+other.collisionRadius+UnitMovementClearance+.005f;
                // Touching a body behind us must not prevent moving away from it.
                if(offset.sqrMagnitude<=clearance*clearance&&Vector3.Dot(offset,movement)>=0f)continue;
                if(CrocodileCombatRules.TryPreyCannonContact(previous,ground,center,clearance,out float contact))
                    clearFraction=Mathf.Min(clearFraction,contact);
            }
            ground=Vector3.Lerp(previous,ground,clearFraction);
        }
        else if(unit.displacementCheckUnits)
        {
            Vector3 previous=Flat(unit.model.transform.position);
            Vector3 step=intended-EvaluateDisplacementPosition(
                unit.displacementStart,unit.displacementEnd,previousProgress);
            if(pressurePush)step=intended-Vector3.Lerp(unit.displacementStart,unit.displacementEnd,
                HaetaeRank3Rules.BellowPushProgress(previousProgress));
            ground=ResolveUnitMovement(unit,previous,previous+step);
        }
        unit.lastGroundPosition=ground;
        unit.currentTile=NearestGridCoordinate(ground);
        float arc=unit.displacementSlam
            ?FrogCombatRules.SlamArcHeight(unit.displacementProgress)
            :Mathf.Sin(unit.displacementProgress*Mathf.PI)*unit.displacementArcHeight;
        unit.model.transform.position=ground+Vector3.up*(unit.visualHeightOffset+arc);
        unit.ring.transform.position=ground+Vector3.up*0.025f;
        unit.velocity=Vector3.zero;
        unit.moving=false;
        SetMoving(unit,false);
        if(unit.displacementProgress<1f)return;
        unit.crocodilePreyFlying=false;
        unit.displacing=false;
        unit.spiderCapturePull=false;
        unit.displacementArcHeight=0f;
        unit.model.transform.position=ground+Vector3.up*unit.visualHeightOffset;
        unit.displacementStart=ground;
        unit.displacementEnd=ground;
        unit.decisionTimer=0f;
        unit.repathTimer=0f;
        if(pressurePush)
        {
            Unit source=unit.haetaeBellowPushedBy;EndHaetaeBellowPush(unit);
            Rank3Knockdown(source,unit,HaetaeRank3Rules.BellowKnockdown);
        }
    }

    private static Vector3 EvaluateDisplacementPosition(
        Vector3 start,Vector3 end,float progress)
    {
        float t=Mathf.Clamp01(progress);
        t=t*t*(3f-2f*t);
        return Vector3.LerpUnclamped(start,end,t);
    }

    private bool BeginBeetleSkyFlip(Unit unit,SkillMasterRow skill)
    {
        if(HasFamilyTranscendence(unit))return BeginBeetleImperialHorn(unit,skill);
        Unit target=unit.target;
        if(!IsCombatActive(target))return false;
        float range=TileSize*Mathf.Max(1f,skill.castRangeTiles)+
                    unit.collisionRadius+target.collisionRadius;
        if(!IsWithinCommittedSkillReach(unit,target,range))
            return false;
        unit.beetleSkyFlipPending=true;
        unit.beetleSkyFlipTarget=target;
        unit.beetleSkyFlipDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.beetleSkyFlipRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="beetle_sky_flip_prepare";
        PlayBeetleSound(unit,BeetleSound.Prepare,unit.model.transform.position,.8f);
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        if(MonsterTraitRuntime.Has(
               unit.activeTraitIds,BeetleCombatRules.AtlagonTraitId))
        {
            unit.familyDamageReductionRatio=Mathf.Max(
                unit.familyDamageReductionRatio,
                BeetleCombatRules.FortressDamageReduction);
            unit.familyDamageReductionTimer=GateHaetaeBenefit(unit,Mathf.Max(
                unit.familyDamageReductionTimer,BeetleCombatRules.FortressDuration));
            SpriteRenderer renderer=unit.spriteAnimation==null
                ?unit.model.GetComponentInChildren<SpriteRenderer>()
                :unit.spriteAnimation.GetComponent<SpriteRenderer>();
            PixelCombatEffect.PlayBeetleFortressAura(
                unit.spriteAnimation==null
                    ?unit.model.transform:unit.spriteAnimation.transform,
                renderer,BeetleCombatRules.FortressDuration);
        }
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(unit.spriteAnimation==null)
        {
            if(!HasBeetleRank3(unit))StartBeetleFlip(unit,target,skill,combatGeneration);
            else StartCombatCoroutine(unit,ResolveBeetleSkyFlip(unit,target,skill,1f,false,combatGeneration));
        }
        return true;
    }

    private IEnumerator ResolveBeetleSkyFlip(
        Unit source,Unit target,SkillMasterRow skill,
        float effectScale,bool traitEcho,int generation)
    {
        if(generation!=combatGeneration||!IsCombatActive(source)||
           !IsCombatActive(target)||skill==null)
            yield break;
        float damageScale=effectScale*
            (traitEcho?1f:source.beetleSkyFlipDamageMultiplier);
        float radiusScale=traitEcho?1f:source.beetleSkyFlipRadiusMultiplier;
        if(!traitEcho)
        {
            source.beetleSkyFlipPending=false;
            source.beetleSkyFlipTarget=null;
            source.beetleSkyFlipDamageMultiplier=1f;
            source.beetleSkyFlipRadiusMultiplier=1f;
        }
        if(!traitEcho&&TryResolveBeetleRank3(
               source,target,skill,damageScale,radiusScale,generation))yield break;
        Vector3 landing=Flat(target.model.transform.position);
        float dealt=ApplySkillFormulaDamage(
            source,target,skill,false,0,damageScale,!traitEcho);
        PlayBeetleSound(source,BeetleSound.Flip,landing,traitEcho?.55f:1f);
        int hits=1;
        float airborne=HostileStatusDuration(
            target,Mathf.Max(.1f,skill.statusDurationSeconds));
        target.combatStatuses.ApplyTimed(
            CombatStatusKind.Airborne,airborne,source,airborne);

        dealt+=BeetleLightningDamage(source,target,landing,damageScale,traitEcho,out int lightningHits);
        hits+=lightningHits;
        yield return new WaitForSeconds(Mathf.Max(.1f,skill.statusDurationSeconds));
        if(generation!=combatGeneration||!IsCombatActive(source))yield break;

        dealt+=BeetleLandingDamage(source,landing,skill,damageScale,radiusScale,traitEcho,out int landingHits);
        PlayBeetleSound(source,BeetleSound.Land,landing,traitEcho?.55f:1f);
        hits+=landingHits;
        source.skillHits+=hits;
        source.skillDamage+=dealt;
        source.currentAction="beetle_sky_flip";
        RecordSkillEvent(source,skill.id+(traitEcho?"_echo":"_slam"),hits,dealt);
    }

    private float BeetleLightningDamage(Unit source,Unit target,Vector3 landing,float damageScale,
        bool traitEcho,out int hits)
    {
        hits=0;float dealt=0;
        bool lightning=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,BeetleCombatRules.NoepungTraitId);
        if(lightning)
        {
            List<Unit> chain=units.Where(enemy=>IsCombatActive(enemy)&&
                    enemy.team!=source.team&&enemy!=target)
                .OrderBy(enemy=>Vector3.Distance(
                    landing,Flat(enemy.model.transform.position)))
                .Take(BeetleCombatRules.LightningChainTargets).ToList();
            chain.Insert(0,target);
            SpriteRenderer targetRenderer;
            Vector3 lightningOrigin=BeetleEffectCenter(target,out targetRenderer)+
                                    Vector3.up*3.1f;
            for(int i=0;i<chain.Count;i++)
            {
                if(!IsCombatActive(chain[i]))continue;
                SpriteRenderer chainRenderer;
                Vector3 chainCenter=BeetleEffectCenter(
                    chain[i],out chainRenderer);
                if(!mlEpisodeActive)
                {
                PixelCombatEffect.PlayBeetleLightningArc(
                    lightningOrigin,chainCenter,chainRenderer);
                if(i==0)
                    PixelCombatEffect.PlayBeetleThunderImpact(
                        chainCenter,TileSize*0.55f,chainRenderer);
                PixelStarProjectile.PlayImpact(
                    chainCenter,chainRenderer,new Color(0.42f,0.86f,1f),true,
                    false,i==0?1.8f:1.3f);
                }
                dealt+=ApplySkillDamage(source,chain[i],
                    BeetleCombatRules.Damage(
                        SkillPower(source),BeetleCombatRules.LightningDamageRatio)*
                    damageScale,false);
                hits++;
                lightningOrigin=chainCenter;
            }
            if(hits>0&&!mlEpisodeActive)
                PlayCombatSound(source,CombatSoundCue.Impact,landing,.35f,authoredSound:PixelHaetaeThunder.ImpactClip);
            source.traitActivations++;
        }
        return dealt;
    }

    private float BeetleLandingDamage(Unit source,Vector3 landing,SkillMasterRow skill,
        float damageScale,float radiusScale,bool traitEcho,out int hits,Unit crushTarget=null)
    {
        hits=0;float dealt=0;
        float radius=TileSize*Mathf.Max(.1f,skill.radiusTiles)*radiusScale;
        List<Unit> victims=units.Where(enemy=>IsCombatActive(enemy)&&
                enemy.team!=source.team&&
                Vector3.Distance(landing,Flat(enemy.model.transform.position))<=
                radius+enemy.collisionRadius)
            .ToList();
        bool horn=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,BeetleCombatRules.JangpungTraitId);
        bool sun=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,BeetleCombatRules.SolarbeetleTraitId);
        for(int i=0;i<victims.Count;i++)
        {
            Unit enemy=victims[i];
            float areaScale=damageScale*TraitAreaEffectScale(
                source,landing,Flat(enemy.model.transform.position),radius);
            // The primary takes the crush instead of the splash, once through the normal skill-hit path.
            dealt+=enemy==crushTarget
                ?ApplySkillDamage(source,enemy,SkillPower(source)*BeetleFlipRules.CrushPrimaryRatio*areaScale,!traitEcho)
                :ApplySkillFormulaDamage(source,enemy,skill,true,0,areaScale,!traitEcho);
            if(horn)
                dealt+=ApplySkillDamage(source,enemy,
                    BeetleCombatRules.Damage(
                        SkillPower(source),BeetleCombatRules.HornDamageRatio)*
                    damageScale,false);
            if(sun&&IsCombatActive(enemy)&&!enemy.combatStatuses.RejectHarmfulEffect())
            {
                ApplyDefenseShred(source,enemy,BeetleCombatRules.SunHornShredRatio,
                    BeetleCombatRules.SunHornDuration);
                enemy.familyResistanceShredRatio=Mathf.Max(
                    enemy.familyResistanceShredRatio,
                    BeetleCombatRules.SunHornShredRatio);
                enemy.familyResistanceShredTimer=Mathf.Max(
                    enemy.familyResistanceShredTimer,
                    BeetleCombatRules.SunHornDuration);
                enemy.reaction?.PlayTintHit(new Color(1f,0.48f,0.04f));
            }
            if(!mlEpisodeActive)
            {
                source.beetleFlip?.effect?.Hit(Rank3Center(enemy),source.beetleFlip.time,false);
                enemy.reaction?.PlayTintHit(sun?new Color(1f,.64f,.2f):new Color(1f,.87f,.6f));
            }
            hits++;
        }
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        if(!mlEpisodeActive&&source.beetleFlip==null&&horn&&victims.Count>0)
        {
            PixelCombatEffect.PlayBeetleHornDebris(
                landing,radius,sourceRenderer);
        }
        if(!mlEpisodeActive&&sun&&victims.Count>0)
            PixelCombatEffect.PlayBeetleSolarBurst(
                landing,radius,sourceRenderer);
        if(!traitEcho&&(horn||sun)&&victims.Count>0)source.traitActivations++;
        return dealt;
    }

    private static Vector3 BeetleEffectCenter(
        Unit unit,out SpriteRenderer renderer)
    {
        renderer=unit.spriteAnimation==null
            ?unit.model.GetComponentInChildren<SpriteRenderer>()
            :unit.spriteAnimation.GetComponent<SpriteRenderer>();
        return renderer==null
            ?unit.model.transform.position+Vector3.up*0.42f:renderer.bounds.center;
    }

    private bool BeginSpiritSanctuary(Unit unit,SkillMasterRow skill)
    {
        unit.spiritSanctuaryPending=true;
        unit.spiritSanctuaryDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.spiritSanctuaryRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="spirit_sanctuary_prepare";
        PlaySpiritDeerSound(unit,SpiritDeerSound.Prepare,unit.model.transform.position,.85f);
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(unit.spriteAnimation==null)
            StartReleasedSkill(unit,ResolveSpiritSanctuary(unit,skill,1f,false,combatGeneration));
        return true;
    }

    private IEnumerator ResolveSpiritSanctuary(
        Unit source,SkillMasterRow skill,float effectScale,
        bool traitEcho,int generation)
    {
        if(generation!=combatGeneration||!IsCombatActive(source)||skill==null)
            yield break;
        float damageScale=effectScale*
            (traitEcho?1f:source.spiritSanctuaryDamageMultiplier);
        float radiusScale=traitEcho?1f:source.spiritSanctuaryRadiusMultiplier;
        if(!traitEcho)
        {
            source.spiritSanctuaryPending=false;
            source.spiritSanctuaryDamageMultiplier=1f;
            source.spiritSanctuaryRadiusMultiplier=1f;
        }
        bool rank3Sanctuary=!traitEcho&&(
            HasRank3(source,SpiritDeerRank3Rules.LifeTithe)||
            HasRank3(source,SpiritDeerRank3Rules.InviolableSanctuary)||
            HasRank3(source,SpiritDeerRank3Rules.MyriadConcert));
        float targetRadius=TileSize*SpiritDeerCombatRules.ClampSanctuaryRadiusTiles(
            rank3Sanctuary?SpiritDeerRank3Rules.RadiusTiles:
                skill.radiusTiles*radiusScale);
        Unit anchor=SelectSpiritSanctuaryAnchor(source,
            TileSize*Mathf.Max(1f,skill.castRangeTiles),targetRadius);
        Vector3 center=Flat((anchor??source).model.transform.position);
        float radius=TileSize*SpiritDeerCombatRules.ClampSanctuaryRadiusTiles(
            skill.radiusTiles*radiusScale);
        PlaySpiritDeerSound(source,SpiritDeerSound.Spread,center,traitEcho?.55f:1f);
        if(!traitEcho&&TryResolveSpiritDeerRank3(
               source,skill,center,damageScale,generation))
            yield break;
        bool holy=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,SpiritDeerCombatRules.HolydeerTraitId);
        bool moon=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,SpiritDeerCombatRules.LunadeerTraitId);
        bool forest=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,SpiritDeerCombatRules.ForestdeerTraitId);
        bool eclipse=!traitEcho&&MonsterTraitRuntime.Has(
            source.activeTraitIds,SpiritDeerCombatRules.EclipsedeerTraitId);
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        Color sanctuaryColor=holy?new Color(1f,.82f,.28f)
            :moon?new Color(.42f,.58f,1f)
            :forest?new Color(.3f,1f,.36f)
            :eclipse?new Color(.48f,.12f,.68f)
            :new Color(.48f,1f,.76f);
        PixelSpiritBlessing sanctuary=mlEpisodeActive?null:PixelSpiritBlessing.Sanctuary(
            center,radius,skill.durationSeconds,sanctuaryColor,sourceRenderer,()=>battleElapsed,
            ()=>generation==combatGeneration&&!battleEnding);
        if(traitEcho)
        {
            source.currentAction="spirit_sanctuary_echo";
            RecordSkillEvent(source,skill.id+"_echo",0,0f);yield break;
        }
        HashSet<Unit> blessed=new HashSet<Unit>(),cursed=new HashSet<Unit>();
        float start=battleElapsed,elapsed=0f;
        while(elapsed<skill.durationSeconds)
        {
            if(generation!=combatGeneration)
            {sanctuary?.Cancel();yield break;}
            if(paused){yield return null;continue;}
            elapsed=battleElapsed-start;if(elapsed>=skill.durationSeconds)break;
            float revealed=radius*PixelSpiritBlessing.SpreadAt(elapsed);
            foreach(Unit ally in units.Where(ally=>IsCombatActive(ally)&&
                        !ally.augmentShadowClone&&ally.team==source.team&&
                        Vector3.Distance(center,Flat(ally.model.transform.position))<=revealed+ally.collisionRadius))
                if(blessed.Add(ally))ApplySpiritDeerSanctuaryBlessing(source,ally,damageScale);
            if(eclipse)
                foreach(Unit enemy in units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=source.team&&
                            Vector3.Distance(center,Flat(enemy.model.transform.position))<=revealed+enemy.collisionRadius))
                    if(cursed.Add(enemy))ApplySpiritDeerEclipseCurse(source,enemy);
            yield return null;
        }
        if(blessed.Count>0&&(holy||moon||forest||eclipse))source.traitActivations++;
        source.currentAction="spirit_sanctuary";RecordSkillEvent(source,skill.id,0,0f);
    }

    private static Color SpiritDeerTint(Unit source)
    {
        if(source.spiritConcertOwner!=null)return PixelSpiritConcert.Color;
        string id=source.definition.monsterId;
        return id=="holydeer"?new Color(1f,.79f,.27f):id=="lunadeer"?new Color(.48f,.70f,1f):
            id=="eclipsedeer"?new Color(.74f,.38f,1f):new Color(.40f,1f,.55f);
    }

    private Unit SelectSpiritSanctuaryAnchor(
        Unit source,float castRange,float sanctuaryRadius)
    {
        List<Unit> friendly=units.Where(ally=>IsCombatActive(ally)&&
            ally.team==source.team&&!ally.augmentShadowClone).ToList();
        List<Unit> allies=friendly.Where(ally=>ally!=source&&
                Vector3.Distance(Flat(source.model.transform.position),
                    Flat(ally.model.transform.position))<=castRange+ally.collisionRadius)
            .OrderBy(ally=>ally.id).ToList();
        if(allies.Count==0)return source.spiritSanctuaryLastAnchor=source;
        List<Unit> enemies=units.Where(enemy=>IsCombatActive(enemy)&&
            enemy.team!=source.team&&!enemy.augmentShadowClone).ToList();
        PersonalityTargetStyle style=(source.personalityPolicy??
            PersonalityCombatPolicy.Balanced()).targetStyle;
        Unit previous=source.spiritSanctuaryLastAnchor;
        Unit selected;
        switch(style)
        {
            case PersonalityTargetStyle.Persistent:
                selected=allies.Contains(previous)?previous:
                    allies.OrderBy(SpiritSanctuaryHealthRatio).First();
                break;
            case PersonalityTargetStyle.LowestHealth:
                selected=allies.OrderBy(SpiritSanctuaryHealthRatio).First();
                break;
            case PersonalityTargetStyle.Strongest:
                selected=allies.OrderByDescending(ally=>ally.expeditionRank)
                    .ThenByDescending(ally=>ally.maxHp).ThenBy(ally=>ally.id).First();
                break;
            case PersonalityTargetStyle.Vengeful:
                selected=allies.OrderByDescending(ally=>ally.damageTaken)
                    .ThenBy(SpiritSanctuaryHealthRatio).ThenBy(ally=>ally.id).First();
                break;
            case PersonalityTargetStyle.Rotating:
                List<Unit> alternatives=allies.Where(ally=>ally!=previous).ToList();
                if(alternatives.Count==0)alternatives=allies;
                int seed=source.ownedInstance==null?source.id:
                    source.ownedInstance.personalitySeed;
                int index=(int)((uint)(seed+source.skillUses*397)%
                    (uint)alternatives.Count);
                selected=alternatives[index];
                break;
            case PersonalityTargetStyle.Cooperative:
                selected=allies.OrderByDescending(ally=>friendly.Count(other=>
                        Vector3.Distance(Flat(ally.model.transform.position),
                            Flat(other.model.transform.position))<=sanctuaryRadius))
                    .ThenBy(SpiritSanctuaryHealthRatio).ThenBy(ally=>ally.id).First();
                break;
            case PersonalityTargetStyle.Independent:
                selected=allies.OrderBy(ally=>friendly.Count(other=>other!=ally&&
                        Vector3.Distance(Flat(ally.model.transform.position),
                            Flat(other.model.transform.position))<=sanctuaryRadius))
                    .ThenBy(SpiritSanctuaryHealthRatio).ThenBy(ally=>ally.id).First();
                break;
            case PersonalityTargetStyle.Protective:
                selected=allies.OrderByDescending(ally=>enemies.Count(enemy=>
                        enemy.target==ally))
                    .ThenBy(SpiritSanctuaryHealthRatio).ThenBy(ally=>ally.id).First();
                break;
            case PersonalityTargetStyle.Opportunistic:
                selected=allies.OrderByDescending(ally=>enemies.Count(enemy=>
                        SpiritSanctuaryEnemyIsVulnerable(enemy)&&
                        Vector3.Distance(Flat(ally.model.transform.position),
                            Flat(enemy.model.transform.position))<=sanctuaryRadius))
                    .ThenBy(SpiritSanctuaryHealthRatio).ThenBy(ally=>ally.id).First();
                break;
            case PersonalityTargetStyle.Impulsive:
                selected=allies.Where(ally=>ally.hp<ally.maxHp)
                    .OrderBy(ally=>Vector3.Distance(
                        Flat(source.model.transform.position),
                        Flat(ally.model.transform.position))).ThenBy(ally=>ally.id)
                    .FirstOrDefault()??allies.OrderBy(ally=>Vector3.Distance(
                        Flat(source.model.transform.position),
                        Flat(ally.model.transform.position))).First();
                break;
            case PersonalityTargetStyle.Cautious:
                IEnumerable<Unit> safePool=string.Equals(
                        source.personalityPolicy?.personalityId,"timid",
                        StringComparison.Ordinal)
                    ?allies:allies.Where(ally=>ally.hp<ally.maxHp);
                if(!safePool.Any())safePool=allies;
                selected=safePool.OrderByDescending(ally=>
                        SpiritSanctuaryNearestEnemyDistance(ally,enemies))
                    .ThenBy(SpiritSanctuaryHealthRatio).ThenBy(ally=>ally.id).First();
                break;
            case PersonalityTargetStyle.Cluster:
                selected=allies.OrderByDescending(ally=>enemies.Count(enemy=>
                        Vector3.Distance(Flat(ally.model.transform.position),
                            Flat(enemy.model.transform.position))<=sanctuaryRadius))
                    .ThenBy(ally=>SpiritSanctuaryNearestEnemyDistance(ally,enemies))
                    .ThenBy(ally=>ally.id).First();
                break;
            case PersonalityTargetStyle.Eccentric:
                int mode=Mathf.Abs(source.skillUses-1)%4;
                selected=mode==0?allies.OrderBy(ally=>Vector3.Distance(
                        Flat(source.model.transform.position),Flat(ally.model.transform.position))).First()
                    :mode==1?allies.OrderBy(SpiritSanctuaryHealthRatio).First()
                    :mode==2?allies.OrderByDescending(ally=>friendly.Count(other=>
                            Vector3.Distance(Flat(ally.model.transform.position),
                                Flat(other.model.transform.position))<=sanctuaryRadius))
                        .ThenBy(ally=>ally.id).First()
                    :allies.OrderBy(ally=>
                            SpiritSanctuaryNearestEnemyDistance(ally,enemies))
                        .ThenBy(ally=>ally.id).First();
                break;
            default:
                selected=allies.OrderBy(SpiritSanctuaryHealthRatio).First();
                break;
        }
        if(allies.Count>1)
        {
            int seed=MonsterInstanceGenerator.StableSeed("sanctuary_"+
                (source.ownedInstance==null?source.id:source.ownedInstance.personalitySeed)+"_"+
                source.skillUses+"_"+combatGeneration);
            var random=new System.Random(seed);
            if(random.NextDouble()>=SpiritDeerCombatRules.PersonalityTargetChance)
            {
                List<Unit> alternatives=allies.Where(ally=>ally!=selected).ToList();
                selected=alternatives[random.Next(alternatives.Count)];
            }
        }
        source.spiritSanctuaryLastAnchor=selected;
        return source.spiritSanctuaryLastAnchor;
    }

    private static float SpiritSanctuaryHealthRatio(Unit unit)
    {
        return unit.hp/Mathf.Max(1f,unit.maxHp);
    }

    private static float SpiritSanctuaryNearestEnemyDistance(
        Unit ally,List<Unit> enemies)
    {
        return enemies.Count==0?float.MaxValue:enemies.Min(enemy=>
            Vector3.Distance(Flat(ally.model.transform.position),
                Flat(enemy.model.transform.position)));
    }

    private static bool SpiritSanctuaryEnemyIsVulnerable(Unit enemy)
    {
        return enemy.itemDefenseShredTimer>0f||enemy.familyResistanceShredTimer>0f||
               enemy.combatStatuses.Has(CombatStatusKind.Poison)||
               enemy.combatStatuses.Has(CombatStatusKind.Burning)||
               enemy.combatStatuses.Has(CombatStatusKind.Bleed)||
               enemy.combatStatuses.Has(CombatStatusKind.Freeze)||
               enemy.combatStatuses.Has(CombatStatusKind.Knockdown)||
               enemy.combatStatuses.Has(CombatStatusKind.Root);
    }

    private void ApplySpiritDeerSanctuaryBlessing(
        Unit source,Unit ally,float healingScale)
    {
        bool holy=MonsterTraitRuntime.Has(
            source.activeTraitIds,SpiritDeerCombatRules.HolydeerTraitId);
        bool moon=MonsterTraitRuntime.Has(
            source.activeTraitIds,SpiritDeerCombatRules.LunadeerTraitId);
        bool forest=MonsterTraitRuntime.Has(
            source.activeTraitIds,SpiritDeerCombatRules.ForestdeerTraitId);
        bool eclipse=MonsterTraitRuntime.Has(
            source.activeTraitIds,SpiritDeerCombatRules.EclipsedeerTraitId);
        float healing=holy?SpiritDeerCombatRules.HolyHealing(source.maxHp)
            :moon?SpiritDeerCombatRules.MoonHealing(
                source.damage,ally.maxHp-ally.hp)
            :forest?SpiritDeerCombatRules.ForestHealing(source.maxHp)
            :eclipse?SpiritDeerCombatRules.EclipseHealing(source.damage)
            :SpiritDeerCombatRules.ForestHealing(source.maxHp);
        int cleansed=CleanseAllHarmfulEffects(ally);
        Heal(ally,SkillSupportAmount(
            source,healing*Mathf.Max(0f,healingScale)));

        SpriteRenderer allyRenderer;
        Transform allyAnchor=SpiritDeerEffectAnchor(ally,out allyRenderer);
        if(cleansed>0)
            AddCombatFloatText(ally,"정화",new Color(1f,.88f,.42f),true);
        if(holy)
        {
            ally.combatStatuses.ApplyShield(
                SpiritDeerCombatRules.HolyShieldDuration,
                SkillSupportAmount(
                    source,SpiritDeerCombatRules.HolyShield(source.maxHp)),source);
            ally.combatStatuses.ApplyDebuffImmunity(
                SpiritDeerCombatRules.HolyDebuffImmunityDuration*ConcertDurationScale(source));
        }
        else if(forest)
        {
            ally.familyAttackSpeedBonus=Mathf.Max(
                ally.familyAttackSpeedBonus,SpiritDeerCombatRules.ForestHaste*Rank2BuffMultiplier(source));
            ally.familyAttackSpeedTimer=GateHaetaeBenefit(ally,Mathf.Max(
                ally.familyAttackSpeedTimer,SpiritDeerCombatRules.ForestBuffDuration*ConcertDurationScale(source)));
            ally.familyMoveSpeedBonus=Mathf.Max(
                ally.familyMoveSpeedBonus,SpiritDeerCombatRules.ForestHaste*Rank2BuffMultiplier(source));
            ally.familyMoveSpeedTimer=GateHaetaeBenefit(ally,Mathf.Max(
                ally.familyMoveSpeedTimer,SpiritDeerCombatRules.ForestBuffDuration*ConcertDurationScale(source)));
        }
        if(!mlEpisodeActive)
        {
            int generation=combatGeneration;
            PixelSpiritBlessing.Bless(allyRenderer,holy?0:forest?2:1,SpiritDeerTint(source),
                holy?SpiritDeerCombatRules.HolyShieldDuration:forest?SpiritDeerCombatRules.ForestBuffDuration:.8f,
                ()=>battleElapsed,()=>generation==combatGeneration&&IsCombatActive(ally)&&
                    (!holy||ally.combatStatuses.Has(CombatStatusKind.Shield))&&
                    (!forest||ally.familyAttackSpeedTimer>0f||ally.familyMoveSpeedTimer>0f));
            PlaySpiritDeerSound(source,SpiritDeerSound.Bless,ally.model.transform.position);
            if(holy)AddCombatFloatText(ally,GameLocalization.TextByKey(
                "combat.sanctuary_shield","성역 보호"),new Color(1f,.85f,.4f),false);
            else if(forest)AddCombatFloatText(ally,GameLocalization.Format("combat.forest_haste", "가속 +{0}%", Mathf.RoundToInt(100f*SpiritDeerCombatRules.ForestHaste*Rank2BuffMultiplier(source))),new Color(.5f,1f,.65f),false);
        }
    }

    private void ApplySpiritDeerEclipseCurse(Unit source,Unit enemy)
    {
        if(enemy.combatStatuses.DebuffImmune)return;
        enemy.familyHealingReductionRatio=Mathf.Max(
            enemy.familyHealingReductionRatio,
            SpiritDeerCombatRules.EclipseHealingReduction);
        enemy.familyHealingReductionTimer=Mathf.Max(
            enemy.familyHealingReductionTimer,
            SpiritDeerCombatRules.EclipseDebuffDuration*ConcertDurationScale(source));
        enemy.familyResistanceShredRatio=Mathf.Max(
            enemy.familyResistanceShredRatio,
            SpiritDeerCombatRules.EclipseResistanceShred);
        enemy.familyResistanceShredTimer=Mathf.Max(
            enemy.familyResistanceShredTimer,
            SpiritDeerCombatRules.EclipseDebuffDuration*ConcertDurationScale(source));
        SpriteRenderer enemyRenderer;
        Transform enemyAnchor=SpiritDeerEffectAnchor(enemy,out enemyRenderer);
        if(!mlEpisodeActive)
        {
            int generation=combatGeneration;
            PixelSpiritBlessing.Bless(enemyRenderer,3,SpiritDeerTint(source),SpiritDeerCombatRules.EclipseDebuffDuration,
                ()=>battleElapsed,()=>generation==combatGeneration&&IsCombatActive(enemy)&&
                    (enemy.familyHealingReductionTimer>0f||enemy.familyResistanceShredTimer>0f));
        }
        enemy.reaction?.PlayTintHit(new Color(.54f,.12f,.72f));
    }

    private static Transform SpiritDeerEffectAnchor(
        Unit unit,out SpriteRenderer renderer)
    {
        Transform anchor=unit.spriteAnimation==null
            ?unit.model.transform:unit.spriteAnimation.transform;
        renderer=unit.spriteAnimation==null
            ?unit.model.GetComponentInChildren<SpriteRenderer>()
            :unit.spriteAnimation.GetComponent<SpriteRenderer>();
        return anchor;
    }

    private bool BeginWyvernBreath(Unit unit,SkillMasterRow skill)
    {
        if(HasFamilyTranscendence(unit))return BeginWyvernHeavenBreath(unit,skill);
        Unit target=unit.target;
        if(!IsCombatActive(target))return false;
        float range=HasWyvernRank3(unit)?SkillActivationDistance(unit,target,skill):
            TileSize*Mathf.Max(1f,skill.castRangeTiles)+unit.collisionRadius+target.collisionRadius;
        if(!IsWithinCommittedSkillReach(unit,target,range))
            return false;
        unit.wyvernBreathPending=true;
        unit.wyvernBreathTarget=target;
        unit.wyvernBreathDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.wyvernBreathRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="wyvern_breath_prepare";
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        StartWyvernBreath(unit,target,skill,1f,false,combatGeneration);
        return true;
    }

    private bool PlayWyvernBreath(
        Unit source,Unit target,SkillMasterRow skill,float effectScale,
        bool traitEcho,int generation)
    {
        if(generation!=combatGeneration||!IsCombatActive(source)||!IsCombatActive(target)||skill==null)return false;
        return ResolveWyvernBreath(source,target,skill,effectScale,traitEcho,generation);
    }

    private bool ResolveWyvernBreath(
        Unit source,Unit target,SkillMasterRow skill,float effectScale,
        bool traitEcho,int generation)
        =>StartWyvernBreath(source,target,skill,effectScale,traitEcho,generation);

    private IEnumerator ResolveWyvernFireLine(
        Unit source,Vector3 origin,Vector3 forward,float length,float width,
        float damageScale,int generation)
    {
        int ticks=Mathf.RoundToInt(
            WyvernCombatRules.DotDuration/WyvernCombatRules.TickInterval);
        for(int tick=0;tick<ticks;tick++)
        {
            yield return new WaitForSeconds(WyvernCombatRules.TickInterval);
            if(generation!=combatGeneration)yield break;
            int hits=0;
            float dealt=0f;
            foreach(Unit enemy in units.Where(enemy=>IsCombatActive(enemy)&&
                        enemy.team!=source.team&&IsPointInsideForwardSkillLine(
                            origin,forward,Flat(enemy.model.transform.position),
                            length,width+enemy.collisionRadius)))
            {
                dealt+=ApplyGroundSkillDamage(source,enemy,
                    WyvernCombatRules.Damage(
                        source.damage,WyvernCombatRules.FireTickRatio)*
                    damageScale,false);
                hits++;
            }
            source.skillHits+=hits;
            source.skillDamage+=dealt;
            CreateSkillPulseAt(
                origin+forward*length*.5f,new Color(1f,.34f,.08f),
                Mathf.Max(.8f,length/TileSize*.4f));
            RecordSkillEvent(source,source.skillId+"_fire",hits,dealt);
        }
    }

    private int CleanseAllHarmfulEffects(Unit unit)
    {
        if(unit==null)return 0;
        int cleansed=unit.combatStatuses.RemoveAllHarmful();
        return cleansed+CleanseTimedHarmfulEffects(unit,true);
    }

