        {
            if(!apply)return 1;
            unit.corruptStatusResistanceReductionTimer=0f;
            unit.corruptStatusResistanceReduction=0f;
            cleansed++;
        }
        if(!apply)return 0;
        if(unit.familyHealingReductionTimer<=0f&&
           unit.familyRecoveryShieldReductionTimer<=0f&&
           unit.ninjaHealingReductionTimer<=0f&&
           unit.griffinHealingReductionTimer<=0f&&
