    private bool BeginGriffinSkyfall(Unit unit,SkillMasterRow skill)
    {
        if(unit==null||skill==null||!IsCombatActive(unit))return false;
        Unit plannedTarget=GriffinDiveTarget(unit,skill);
        if(plannedTarget==null)
        {
            unit.skillTimer=0.3f;
            return false;
        }
        unit.griffinSkyfallPending=true;
        unit.griffinSkyfallTarget=plannedTarget;
        unit.griffinSkyfallDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.griffinSkyfallRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="griffin_skyfall";
        unit.velocity=Vector3.zero;
        unit.hexStepping=false;
        
        ClearRoute(unit);
        ApplyPostSkillItemEffects(unit);
        SetMoving(unit,false);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(unit.spriteAnimation==null)
            StartGriffinSkyDive(unit,skill,combatGeneration);
        return true;
    }

    private void StartGriffinSkyDive(Unit unit,SkillMasterRow skill,int generation)
    {
        if(generation!=combatGeneration||!IsCombatActive(unit)||skill==null)return;
        unit.griffinSkyfallPending=false;
        Unit prey=unit.griffinSkyfallTarget;
        unit.griffinSkyfallTarget=null;
        if(!IsCombatTargetable(prey)||HasRank3(unit,GriffinRank3Rules.RaptorHunt)&&
           prey.griffinHeldBy!=null&&prey.griffinHeldBy!=unit)
            prey=GriffinDiveTarget(unit,skill);
        if(prey==null)return;
        if(HasRank3(unit,GriffinRank3Rules.RaptorHunt))
        {StartGriffinHunt(unit,prey,generation);return;}
        unit.griffinSkyfalling=true;
        unit.griffinSkyfallProgress=0f;
        unit.rank3GriffinLaunch=Flat(unit.model.transform.position);
        unit.griffinSkyfallOrigin=GriffinLanding(unit,prey);
        bool typhoon=HasRank3(unit,GriffinRank3Rules.TyphoonDive);
        unit.griffinSkyfallLiftHeight=typhoon
            ?GriffinCombatRules.TyphoonLiftHeight(unit.rank3GriffinLaunch,Camera.main)
            :GriffinCombatRules.SkyDiveLiftHeight;
        unit.target=prey;
        unit.spriteBillboard?.SetFacingDirection(Flat(prey.model.transform.position)-unit.rank3GriffinLaunch,true);
        SpriteRenderer renderer=unit.spriteAnimation==null
            ?unit.model.GetComponentInChildren<SpriteRenderer>()
            :unit.spriteAnimation.GetComponent<SpriteRenderer>();
        float radius=TileSize*(typhoon?GriffinRank3Rules.TyphoonRadiusTiles:Mathf.Max(0f,skill.radiusTiles))*
                     unit.griffinSkyfallRadiusMultiplier;
        if(!mlEpisodeActive)
        {
            unit.griffinDiveFx?.Cancel();
            unit.griffinDiveFx=PixelGriffinDive.Create(renderer,unit.rank3GriffinLaunch,unit.griffinSkyfallOrigin,
                radius,Mathf.Max(.1f,skill.durationSeconds),GriffinDiveTint(unit),CaptureSkillTime(unit),
                ()=>generation==combatGeneration&&IsCombatActive(unit),typhoon);
            if(unit.griffinDiveFx!=null)unit.griffinDiveFx.transform.SetParent(transform,true);
        }
    }

    private static float GriffinSkyDiveDescentDuration(Unit unit)
    {
        return GriffinCombatRules.SkyDiveDescentDuration;
    }

    private static float GriffinSkyDiveTotalDuration(Unit unit,SkillMasterRow skill)
    {
        if(HasRank3(unit,GriffinRank3Rules.RaptorHunt))return GriffinHuntRules.End;
        float ascent=skill==null?GriffinCombatRules.SkyfallDuration:
            Mathf.Max(0.1f,skill.durationSeconds);
        return ascent+GriffinSkyDiveDescentDuration(unit);
    }

    private void UpdateGriffinSkyfall(Unit unit,float dt)
    {
        if(unit.griffinHunt!=null){UpdateGriffinHunt(unit,dt);return;}
        SkillMasterRow skill=GameMasterData.Skill(unit.skillId);
        float ascentDuration=skill==null?GriffinCombatRules.SkyfallDuration:
            Mathf.Max(0.1f,skill.durationSeconds);
        float descentDuration=GriffinSkyDiveDescentDuration(unit);
        float duration=ascentDuration+descentDuration;
        float previousElapsed=unit.griffinSkyfallProgress*duration;
        unit.griffinSkyfallProgress=Mathf.Min(
            1f,unit.griffinSkyfallProgress+dt/duration);
        if(unit.griffinSkyfallProgress>=.99999f)unit.griffinSkyfallProgress=1f;
        float elapsed=unit.griffinSkyfallProgress*duration;
        bool typhoon=HasRank3(unit,GriffinRank3Rules.TyphoonDive);
        if(previousElapsed<GriffinCombatRules.SkyDiveWindup&&elapsed>=GriffinCombatRules.SkyDiveWindup)
            PlayGriffinSound(unit,typhoon?GriffinSound.TyphoonRise:GriffinSound.Rise,unit.rank3GriffinLaunch,.85f);
        if(previousElapsed<ascentDuration&&elapsed>=ascentDuration)
            PlayGriffinSound(unit,GriffinSound.Dive,unit.griffinSkyfallOrigin,.8f);
        float lift=typhoon?GriffinCombatRules.TyphoonLift(elapsed,ascentDuration,unit.griffinSkyfallLiftHeight):
            GriffinCombatRules.SkyDiveLift(elapsed,ascentDuration,descentDuration);
        float glide=GriffinCombatRules.GlideProgress(elapsed,ascentDuration);
        Vector3 ground=Vector3.Lerp(unit.rank3GriffinLaunch,unit.griffinSkyfallOrigin,glide);
        unit.model.transform.position=ground+Vector3.up*(unit.visualHeightOffset+lift);
        unit.lastGroundPosition=ground;
        unit.griffinDiveFx?.Pose(elapsed);
        Vector3 pose=elapsed<GriffinCombatRules.SkyDiveWindup
            ?Vector3.Lerp(Vector3.one,new Vector3(1.1f,.86f,1f),elapsed/GriffinCombatRules.SkyDiveWindup)
            :Vector3.Lerp(new Vector3(1.06f,1.04f,1f),new Vector3(1.1f,.94f,1f),glide);
        if(typhoon)pose=elapsed<GriffinCombatRules.SkyDiveWindup
            ?Vector3.Lerp(Vector3.one,new Vector3(1.16f,.74f,1f),elapsed/GriffinCombatRules.SkyDiveWindup)
            :Vector3.Lerp(new Vector3(.92f,1.18f,1f),new Vector3(1.18f,.86f,1f),glide);
        unit.spriteAnimation?.SetSkillPoseScale(pose);
        float facing=Rank3Renderer(unit)!=null&&Rank3Renderer(unit).flipX?-1f:1f;
        unit.spriteBillboard?.SetRollPose(-facing*12f*Mathf.Sin(glide*Mathf.PI),Vector3.zero,Vector3.zero);
        unit.ring.transform.position=ground+Vector3.up*0.025f;
        unit.velocity=Vector3.zero;
        SetMoving(unit,false);
        if(unit.griffinSkyfallProgress<1f)return;

        unit.model.transform.position=ground+Vector3.up*unit.visualHeightOffset;
        unit.lastGroundPosition=ground;
        unit.currentTile=NearestGridCoordinate(ground);
        unit.griffinSkyfalling=false;
        unit.griffinSkyfallProgress=0f;
        unit.hexStepTarget=unit.currentTile;
        unit.spriteBillboard?.SetRollPose(0f,Vector3.zero,Vector3.zero);
        unit.spriteAnimation?.SetSkillPoseScale(Vector3.one);
        unit.spriteAnimation?.HoldSkillAttackHitFrame(typhoon?.14f:.08f);
        unit.griffinDiveFx?.Land();unit.griffinDiveFx=null;
        if(!mlEpisodeActive)
        {
            if(typhoon)combatCameraDirector?.ReportGroundSlam(true);
            else combatCameraDirector?.ReportGriffinLanding();
        }
        SpriteRenderer renderer=unit.spriteAnimation==null
            ?unit.model.GetComponentInChildren<SpriteRenderer>()
            :unit.spriteAnimation.GetComponent<SpriteRenderer>();
        if(unit.griffinSkyDiveTelegraph!=null)
            unit.griffinSkyDiveTelegraph.Impact();
        unit.griffinSkyDiveTelegraph=null;
        float radius=TileSize*Mathf.Max(0f,skill.radiusTiles)*
                     unit.griffinSkyfallRadiusMultiplier;
        if(!mlEpisodeActive)PixelCombatEffect.PlayGriffinFeatherImpact(unit.model.transform,renderer);
        float previousDamageMultiplier=unit.skillTraitDamageMultiplier;
        float previousRadiusMultiplier=unit.skillTraitRadiusMultiplier;
        unit.skillTraitDamageMultiplier=unit.griffinSkyfallDamageMultiplier;
        unit.skillTraitRadiusMultiplier=unit.griffinSkyfallRadiusMultiplier;
        ResolveGriffinSkyfallImpact(unit,skill,ground,1f,false,true);
        unit.skillTraitDamageMultiplier=previousDamageMultiplier;
        unit.skillTraitRadiusMultiplier=previousRadiusMultiplier;
        unit.griffinSkyfallDamageMultiplier=1f;
        unit.griffinSkyfallRadiusMultiplier=1f;
        BeginSkillInertia(unit,ground-unit.rank3GriffinLaunch,Mathf.Max(.04f,duration-GriffinCombatRules.SkyDiveWindup));
    }

    private void ResolveGriffinSkyfallImpact(Unit unit,SkillMasterRow skill,Vector3 origin,
        float effectScale,bool traitEcho,bool applyIntrinsic)
    {
        if(unit==null||skill==null||!IsCombatActive(unit))return;
        SpriteRenderer renderer=unit.spriteAnimation==null
            ?unit.model.GetComponentInChildren<SpriteRenderer>()
            :unit.spriteAnimation.GetComponent<SpriteRenderer>();
        bool typhoon=!traitEcho&&HasRank3(unit,GriffinRank3Rules.TyphoonDive);
        float radius=TileSize*(typhoon?GriffinRank3Rules.TyphoonRadiusTiles:Mathf.Max(0f,skill.radiusTiles))*unit.skillTraitRadiusMultiplier;
        List<Unit> victims=units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=unit.team&&
            IsInsideTraitArea(unit,origin,Flat(enemy.model.transform.position),radius)).ToList();
        int hits=0;float dealt=0f;
        for(int i=0;i<victims.Count;i++)
        {
            Unit enemy=victims[i];
            if(!IsCombatActive(enemy))continue;
            float hitScale=effectScale*TraitAreaEffectScale(unit,origin,Flat(enemy.model.transform.position),radius);
            dealt+=typhoon?ApplySkillDamage(unit,enemy,SkillPower(unit)*GriffinRank3Rules.TyphoonRatio*hitScale):
                ApplySkillFormulaDamage(unit,enemy,skill,false,0,hitScale,!traitEcho);
            if(!mlEpisodeActive&&enemy.model!=null)
            {
                var hit=PixelCombatEffect.PlayTyrannoTremorHit(enemy.model.transform,Rank3Renderer(enemy));
                hit.name="Griffin Talon Hit";
            }
            if(IsCombatActive(enemy)&&!enemy.griffinSkyfalling)
            {
                Vector3 direction=Flat(enemy.model.transform.position)-origin;
                DisplaceUnit(
                    enemy,direction,TileSize*GriffinCombatRules.KnockbackDistanceTiles);
                enemy.combatStatuses.ApplyTimed(
                    CombatStatusKind.Knockdown,
                    HostileStatusDuration(
                        enemy,Mathf.Max(.1f,skill.statusDurationSeconds)),unit);
            }
            hits++;
        }
        unit.skillHits+=hits;
        unit.skillDamage+=dealt;
        unit.currentAction="griffin_skyfall_land";
        PlayGriffinSound(unit,typhoon?GriffinSound.TyphoonLand:GriffinSound.Land,origin,traitEcho?.55f:1f);
        if(typhoon)unit.traitActivations++;
        RecordSkillEvent(unit,typhoon?GriffinRank3Rules.TyphoonDive:skill.id+(traitEcho?"_echo":"_land"),hits,dealt);
        if(!traitEcho)GrantGriffinRoyal(unit);
        if(!applyIntrinsic||hits<=0)return;
        ApplyGriffinSkyfallIntrinsic(unit,origin,victims,radius,effectScale,renderer);
    }

    private void ApplyGriffinSkyfallIntrinsic(Unit unit,Vector3 origin,List<Unit> victims,
        float radius,float effectScale,SpriteRenderer renderer)
    {
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,GriffinCombatRules.PoneTraitId))
        {
            PixelCombatEffect.PlayGriffinEagleClaw(
                unit.spriteAnimation==null
                    ?unit.model.transform:unit.spriteAnimation.transform,
                renderer,1f,false,1.7f);
            PixelCombatEffect.PlayGriffinFeatherImpact(
                unit.spriteAnimation==null
                    ?unit.model.transform:unit.spriteAnimation.transform,
                renderer);
            float centerRadius=TileSize*GriffinCombatRules.RoyalClawRadiusTiles;
            foreach(Unit enemy in victims.Where(enemy=>IsCombatActive(enemy)&&
                        Vector3.Distance(origin,Flat(enemy.model.transform.position))<=
                        centerRadius+enemy.collisionRadius))
            {
                float extra=ApplySkillDamage(
                    unit,enemy,GriffinCombatRules.RoyalClawDamage(unit.damage)*
                    effectScale,false);
                unit.skillDamage+=extra;
                unit.skillHits++;
            }
            unit.traitActivations++;
        }
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,GriffinCombatRules.GriponasTraitId))
        {
            PixelCombatEffect.PlaySpiritSanctuary(
                origin,radius,GriffinCombatRules.HellfireDuration,
                new Color(0.5f,0.025f,0.012f),renderer,
                "Griphonas Hellgate");
            PixelCombatEffect.PlayNinjaFlameAfterimage(origin,radius,renderer);
            StartReleasedSkill(unit,ResolveGriffinHellfire(unit,origin,radius,combatGeneration));
            unit.traitActivations++;
        }
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,GriffinCombatRules.HoloponasTraitId))
        {
            if(renderer!=null)
            {
                Vector3 landing=renderer.transform.position;
                Sprite hologramSprite=unit.spriteAnimation==null
                    ?renderer.sprite
                    :unit.spriteAnimation.GetSkillAttackFrame(
                        GriffinCombatRules.SkyDiveAscentFrames-2);
                PixelCombatEffect.PlayWolfHuntAfterimage(
                    renderer,landing+Vector3.up*GriffinCombatRules.SkyDiveLiftHeight,
                    landing,
                    new Color(0.24f,0.9f,1f,0.72f),
                    GriffinCombatRules.AfterimageDelay,
                    "Holoponas Hologram Afterimage",
                    GriffinCombatRules.AfterimageDelay-
                    GriffinCombatRules.SkyDiveDescentDuration,
                    hologramSprite);
            }
            StartReleasedSkill(unit,ResolveGriffinAfterimage(unit,origin,radius,combatGeneration));
            unit.traitActivations++;
        }
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,GriffinCombatRules.EntPoneTraitId))
        {
            foreach(Unit ally in units.Where(ally=>IsCombatActive(ally)&&
                        ally.team==unit.team&&
                        Vector3.Distance(origin,Flat(ally.model.transform.position))<=
                        radius+ally.collisionRadius))
            {
                ally.combatStatuses.ApplyShield(
                    GriffinCombatRules.ShieldDuration,
                    SkillSupportAmount(
                        unit,GriffinCombatRules.Shield(unit.maxHp)),unit);
                SpriteRenderer allyRenderer=ally.spriteAnimation==null
                    ?ally.model.GetComponentInChildren<SpriteRenderer>()
                    :ally.spriteAnimation.GetComponent<SpriteRenderer>();
                PixelStarProjectile.PlaySpiritLeafImpact(
                    allyRenderer==null
                        ?ally.model.transform.position+Vector3.up*0.5f
                        :allyRenderer.bounds.center,
                    allyRenderer,new Color(0.3f,0.94f,0.42f),
                    "Entpone Ancient Tree Embrace",
                    0.7f,1.25f,-0.04f,0.18f,2f,20);
            }
            unit.traitActivations++;
        }
    }

    private IEnumerator ResolveGriffinHellfire(
        Unit source,Vector3 origin,float radius,int generation)
    {
        float elapsed=0f;
        while(elapsed<GriffinCombatRules.HellfireDuration)
        {
            yield return new WaitForSeconds(GriffinCombatRules.HellfireTickInterval);
            elapsed+=GriffinCombatRules.HellfireTickInterval;
            if(generation!=combatGeneration)yield break;
            int hits=0;float dealt=0f;
            for(int i=0;i<units.Count;i++)
            {
                Unit enemy=units[i];
                if(!IsCombatActive(enemy)||enemy.team==source.team||
                   Vector3.Distance(origin,Flat(enemy.model.transform.position))>radius)continue;
                dealt+=ApplyGroundSkillDamage(source,enemy,
                    GriffinCombatRules.HellfireDamage(source.damage),false);
                hits++;
            }
            source.skillHits+=hits;
            source.skillDamage+=dealt;
            SpriteRenderer renderer=source.spriteAnimation==null
                ?source.model.GetComponentInChildren<SpriteRenderer>()
                :source.spriteAnimation.GetComponent<SpriteRenderer>();
            PixelCombatEffect.PlayNinjaFlameAfterimage(origin,radius,renderer);
            CreateSkillPulseAt(origin,new Color(0.78f,0.12f,0.03f),radius/TileSize);
            RecordSkillEvent(source,source.skillId+"_hellfire",hits,dealt);
        }
    }

    private IEnumerator ResolveGriffinAfterimage(
        Unit source,Vector3 origin,float radius,int generation)
    {
        yield return new WaitForSeconds(GriffinCombatRules.AfterimageDelay);
        if(generation!=combatGeneration)yield break;
        int hits=0;float dealt=0f;
        for(int i=0;i<units.Count;i++)
        {
            Unit enemy=units[i];
            if(!IsCombatActive(enemy)||enemy.team==source.team||
               Vector3.Distance(origin,Flat(enemy.model.transform.position))>radius)continue;
            dealt+=ApplySkillDamage(source,enemy,
                GriffinCombatRules.AfterimageDamage(
                    source.damage,SkillValue(
                        source.skillId,row=>row.damageMultiplier,1.7f)),false);
            hits++;
        }
        source.skillHits+=hits;
        source.skillDamage+=dealt;
        SpriteRenderer renderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelCombatEffect.PlayGriffinSkyDiveImpact(origin,radius*1.15f,renderer);
        PlayGriffinSound(source,GriffinSound.Land,origin,.55f);
        PixelStarProjectile.PlayImpact(
            origin+Vector3.up*0.08f,renderer,
            new Color(0.58f,0.96f,1f),true,false,2.2f);
        CreateSkillPulseAt(origin,new Color(0.24f,0.86f,1f,0.8f),radius/TileSize);
        RecordSkillEvent(source,source.skillId+"_afterimage",hits,dealt);
    }

    private bool BeginShadowSlash(Unit unit,SkillMasterRow skill)
    {
        Unit victim=unit.target;
        if(!IsCombatActive(victim))return false;
        Vector3 start=Flat(unit.model.transform.position);
        Vector3 targetPosition=Flat(victim.model.transform.position);
        Vector3 forward=targetPosition-start;
        if(forward.sqrMagnitude<0.001f)forward=Flat(unit.model.transform.forward);
        if(forward.sqrMagnitude<0.001f)forward=Vector3.forward;
        forward.Normalize();
        if(!TryResolveShadowSlashLanding(unit,victim,start,forward,out Vector3 landing))
        {
            unit.skillTimer=0.4f;
            return false;
        }

        float length=Vector3.Distance(start,landing);
        float halfWidth=TileSize*Mathf.Max(0.2f,skill.radiusTiles)*
                        unit.skillTraitRadiusMultiplier;
        unit.shadowSlashVictims.Clear();
        bool radial=MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_skill_radial_deploy");
        bool branched=MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_skill_branch_path");
        for(int i=0;i<units.Count;i++)
        {
            Unit enemy=units[i];
            if(!IsCombatActive(enemy)||enemy.team==unit.team)continue;
            Vector3 point=Flat(enemy.model.transform.position);
            bool inside=radial
                ?Vector3.Distance(landing,point)<=TileSize*1.5f*unit.skillTraitRadiusMultiplier
                :IsPointInsideForwardSkillLine(start,forward,point,length,
                    halfWidth+enemy.collisionRadius)||
                 (branched&&(IsPointInsideForwardSkillLine(start,
                       Quaternion.AngleAxis(28f,Vector3.up)*forward,point,length,
                       halfWidth+enemy.collisionRadius)||
                    IsPointInsideForwardSkillLine(start,
                       Quaternion.AngleAxis(-28f,Vector3.up)*forward,point,length,
                       halfWidth+enemy.collisionRadius)));
            if(enemy!=victim&&!inside)continue;
            unit.shadowSlashVictims.Add(enemy);
        }
        if(!unit.shadowSlashVictims.Contains(victim))unit.shadowSlashVictims.Add(victim);

        unit.shadowSlashing=true;
        unit.shadowSlashProgress=0f;
        unit.shadowSlashStart=start;
        unit.shadowSlashPathEnd=landing;
        unit.shadowSlashEnd=MonsterTraitRuntime.Has(unit.activeTraitIds,
            "trait_skill_remote_projection")?start:landing;
        unit.shadowSlashTarget=victim;
        unit.shadowSlashTraitDamageMultiplier=unit.skillTraitDamageMultiplier;
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,JaguarCombatRules.BumiTraitId))
            ApplyJaguarHuntMark(unit,victim);
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="shadow_slash";
        unit.velocity=Vector3.zero;
        
        ApplyPostSkillItemEffects(unit);
        SetMoving(unit,false);
        CreateJaguarPathEffect(start,landing,new Color(0.25f,0.12f,0.38f),0.22f);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        return true;
    }

    private bool BeginShadowHunt(Unit unit,SkillMasterRow skill)
    {
        if(HasFamilyTranscendence(unit)&&IsNinjaCatFamily(unit))return BeginNinjaSpacetime(unit,skill);
        if(unit==null||skill==null||!IsCombatActive(unit))return false;
        Vector3 start=Flat(unit.model.transform.position);
        Unit victim=CommittedSkillTarget(unit)??ShadowHuntCastTarget(unit,skill);
        if(victim==null)return false;

        Vector3 forward=Flat(victim.model.transform.position)-start;
        if(forward.sqrMagnitude<0.001f)forward=Flat(unit.model.transform.forward);
        if(forward.sqrMagnitude<0.001f)forward=Vector3.forward;
        forward.Normalize();
        if(!TryResolveShadowSlashLanding(unit,victim,start,forward,out Vector3 landing))
        {
            unit.skillTimer=0.4f;
            return false;
        }

        SetTarget(unit,victim);
        unit.ninjaHuntPending=true;
        unit.ninjaHuntTarget=victim;
        unit.ninjaHuntStart=start;
        unit.ninjaHuntLanding=landing;
        unit.ninjaHuntDamageMultiplier=unit.skillTraitDamageMultiplier;
        unit.skillTimer=unit.skillCooldownDuration;
        unit.skillUses++;
        unit.currentAction="shadow_hunt_prepare";
        unit.velocity=Vector3.zero;
        
        StopBeforeAttack(unit);
        SetMoving(unit,false);
        ApplyPostSkillItemEffects(unit);
        RecordSkillEvent(unit,skill.id+"_start",0,0f);
        if(unit.spriteAnimation==null)
            ResolveShadowHunt(unit,skill,1f,false,combatGeneration);
        return true;
    }

    private void ResolveShadowHunt(Unit source,SkillMasterRow skill,
        float effectScale,bool traitEcho,int generation)
    {
        Unit target=source==null?null:source.ninjaHuntTarget;
        if(source!=null)
        {
            source.ninjaHuntPending=false;
            source.ninjaHuntTarget=null;
        }
        if(generation!=combatGeneration||!IsCombatActive(source)||
           !IsCombatActive(target)||skill==null)return;

        if(!traitEcho&&TryResolveNinjaCatRank3(
               source,target,skill,effectScale*source.ninjaHuntDamageMultiplier,
               generation))
        {
            source.ninjaHuntDamageMultiplier=1f;
            return;
        }

        Vector3 start=source.ninjaHuntStart;
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?null:source.spriteAnimation.GetComponent<SpriteRenderer>();
        if(source.spriteAnimation==null)
        {
            source.ninjaHuntTarget=target;
            VanishShadowHunt(source);
            ArriveShadowHunt(source);
            source.ninjaHuntTarget=null;
        }
        Vector3 landing=Flat(source.model.transform.position);

        bool impaired=IsMovementImpaired(target);
        SpriteRenderer targetRenderer=target.spriteAnimation==null
            ?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
        PlayShadowHuntCut(source,target,false);
        PlayNinjaSound(source,NinjaSound.Slash,target.model.transform.position);
        float dealt=ApplySkillFormulaDamage(
            source,target,skill,false,0,
            effectScale*source.ninjaHuntDamageMultiplier,!traitEcho);
        int hits=dealt>0f?1:0;
        source.ninjaEmpoweredBasicAttacks=
            NinjaCatCombatRules.EmpoweredBasicAttackCount;

        if(!traitEcho)PrepareNinjaOpeningStrike(source);
        if(!traitEcho&&MonsterTraitRuntime.Has(
               source.activeTraitIds,NinjaCatCombatRules.SeolmyoTraitId)&&
           IsCombatActive(target))
        {
            bool freezeVisualPlayed=false;
            for(int stack=0;stack<NinjaCatCombatRules.FrostStacks;stack++)
                freezeVisualPlayed|=ApplyStackingFrost(
                    source,target,NinjaCatCombatRules.FrostDuration,
                    NinjaCatCombatRules.FrostStacksToFreeze,
                    NinjaCatCombatRules.FreezeDuration);
            if(impaired&&IsCombatActive(target))
            {
                float freezeDuration=HostileStatusDuration(
                    target,NinjaCatCombatRules.FreezeDuration);
                target.combatStatuses.ApplyTimed(CombatStatusKind.Freeze,
                    freezeDuration,source);
                if(!freezeVisualPlayed)PlayFreezeVisual(target,freezeDuration);
            }
            source.traitActivations++;
        }
        if(!traitEcho&&MonsterTraitRuntime.Has(
               source.activeTraitIds,NinjaCatCombatRules.SundongiTraitId)&&
           IsCombatActive(target)&&!target.combatStatuses.RejectHarmfulEffect())
        {
            target.combatStatuses.ApplyStacks(
                CombatStatusKind.Poison,NinjaCatCombatRules.PoisonDuration,1,
                CombatStatusState.MaximumPoisonStacks,
                source,NinjaCatCombatRules.PoisonTickDamage(source.damage),
                NinjaCatCombatRules.PoisonTickInterval,true);
            target.ninjaHealingReductionTimer=Mathf.Max(
                target.ninjaHealingReductionTimer,NinjaCatCombatRules.PoisonDuration);
            PixelCombatEffect.PlayNinjaPoisonMist(
                target.spriteAnimation==null
                    ?target.model.transform:target.spriteAnimation.transform,
                targetRenderer,NinjaCatCombatRules.PoisonDuration);
            source.traitActivations++;
        }
        if(!traitEcho&&MonsterTraitRuntime.Has(
               source.activeTraitIds,NinjaCatCombatRules.HongryeonTraitId))
        {
            dealt+=ApplyNinjaAfterimage(source,start);
            dealt+=ApplyNinjaAfterimage(source,landing);
            source.traitActivations++;
        }

        source.skillHits+=hits;
        source.skillDamage+=dealt;
        source.ninjaHuntDamageMultiplier=1f;
        source.currentAction="shadow_hunt";
        RotateUnit(source,target.model.transform.position-source.model.transform.position,1f);
        CreateJaguarPathEffect(start,landing,new Color(0.75f,0.18f,0.85f),0.2f);
        CreateSkillPulse(source,new Color(0.82f,0.22f,0.9f),0.8f);
        RecordSkillEvent(source,skill.id+"_land",hits,dealt);
    }

    private float ApplyNinjaAfterimage(Unit source,Vector3 origin)
    {
        float dealt=0f;
        float radius=TileSize*NinjaCatCombatRules.AfterimageRadiusTiles;
        foreach(Unit enemy in units)
        {
            if(!IsCombatActive(enemy)||enemy.team==source.team||
               Vector3.Distance(origin,Flat(enemy.model.transform.position))>radius)continue;
            dealt+=ApplySkillDamage(
                source,enemy,NinjaCatCombatRules.AfterimageDamage(source.damage),false);
            source.skillHits++;
        }
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?null:source.spriteAnimation.GetComponent<SpriteRenderer>();
        if(!mlEpisodeActive)PixelNinjaSubstitution.PlayFlameAfterimage(
            origin+Vector3.up*source.visualHeightOffset,sourceRenderer);
        return dealt;
    }

    private void ResolveShadowHuntEcho(Unit source,Unit target,SkillMasterRow skill)
    {
        if(!IsCombatActive(source)||!IsCombatActive(target)||skill==null)return;
        PlayNinjaSound(source,NinjaSound.Slash,target.model.transform.position,.6f);
        float dealt=ApplySkillFormulaDamage(source,target,skill,false,0,0.5f,false);
        source.skillDamage+=dealt;
        source.skillHits++;
        CreateSkillPulse(target,new Color(0.72f,0.25f,0.9f),0.65f);
        RecordSkillEvent(source,skill.id+"_echo",1,dealt);
    }

    private static bool IsMovementImpaired(Unit target)
    {
        return target!=null&&(
            target.combatStatuses.Has(CombatStatusKind.Root)||
            target.combatStatuses.Has(CombatStatusKind.Freeze)||
            target.combatStatuses.Has(CombatStatusKind.Knockdown)||
            target.combatStatuses.Has(CombatStatusKind.StickySilk)||
            target.crocodileImmobilizedTimer>0f||
            target.griffinRootTimer>0f||
            target.raptorSlowTimer>0f||
            target.frogSlowTimer>0f||
            target.kingKongSlowTimer>0f||
            target.mammothSlowTimer>0f);
    }

    private bool TryResolveShadowSlashLanding(
        Unit unit,Unit target,Vector3 start,Vector3 forward,out Vector3 landing)
    {
        Vector3 targetPosition=Flat(target.model.transform.position);
        float distance=unit.collisionRadius+target.collisionRadius+0.5f;
        float[] angles={0f,25f,-25f,50f,-50f,80f,-80f,110f,-110f,145f,-145f,180f};
        for(int i=0;i<angles.Length;i++)
        {
            Vector3 direction=Quaternion.AngleAxis(angles[i],Vector3.up)*forward;
            Vector3 candidate=targetPosition+direction*distance;
            Vector3 resolved=ResolveFreePosition(candidate,unit.collisionRadius);
            if(Vector3.Distance(candidate,resolved)>0.08f||
               !IsOpenAttackPosition(unit,target,candidate)||
               !HasClearPathSegment(start,candidate,unit.collisionRadius*0.55f))continue;
            landing=candidate;
            return true;
        }
        bool accepted=CommittedSkillTarget(unit)==target||
            unit.ninjaHuntPending&&unit.ninjaHuntTarget==target;
        if(!accepted){landing=start;return false;}
        Vector3 current=Flat(unit.model.transform.position);
        Vector3 previous=unit.ninjaHuntLanding;
        if(unit.ninjaHuntPending&&unit.ninjaHuntTarget==target&&
           IsOpenAttackPosition(unit,null,previous)&&
           HasClearPathSegment(current,previous,unit.collisionRadius*.55f))
            landing=previous;
        else landing=current;
        // Keep the accepted strike without moving its body into a blocked or occupied landing.
        return true;
    }

    private void UpdateShadowSlash(Unit unit,float dt)
    {
        SkillMasterRow skill=GameMasterData.Skill(unit.skillId);
        float duration=skill==null?0.22f:Mathf.Max(0.08f,skill.durationSeconds);
        unit.shadowSlashProgress=Mathf.Min(1f,unit.shadowSlashProgress+dt/duration);
        float eased=1f-Mathf.Pow(1f-unit.shadowSlashProgress,3f);
        Vector3 ground=Vector3.Lerp(unit.shadowSlashStart,unit.shadowSlashEnd,eased);
        float lift=Mathf.Sin(unit.shadowSlashProgress*Mathf.PI)*0.24f;
        unit.model.transform.position=ground+Vector3.up*(unit.visualHeightOffset+lift);
        unit.ring.transform.position=ground+Vector3.up*0.025f;
        RotateUnit(unit,unit.shadowSlashEnd-unit.shadowSlashStart,dt*2f);
        if(unit.shadowSlashProgress<1f)return;

        unit.lastGroundPosition=ground;
        unit.currentTile=NearestGridCoordinate(ground);
        float originalDamage=unit.damage*(skill==null?1.45f:skill.damageMultiplier)*
                             unit.shadowSlashTraitDamageMultiplier;
        List<Unit> victims=unit.shadowSlashVictims.ToList();
        int hits=0;float dealt=0f;
        for(int i=0;i<victims.Count;i++)
        {
            Unit enemy=victims[i];
            if(!IsCombatActive(enemy)||enemy.team==unit.team)continue;
            float pathScale=1f;
            if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_skill_branch_path"))
            {
                Vector3 path=unit.shadowSlashPathEnd-unit.shadowSlashStart;
                float pathLength=path.magnitude;
                float width=TileSize*Mathf.Max(0.2f,skill.radiusTiles)*
                            unit.skillTraitRadiusMultiplier+enemy.collisionRadius;
                if(pathLength>0.001f&&!IsPointInsideForwardSkillLine(unit.shadowSlashStart,
                    path/pathLength,Flat(enemy.model.transform.position),pathLength,width))pathScale=0.6f;
            }
            dealt+=skill==null
                ?ApplySkillDamage(unit,enemy,originalDamage*pathScale)
                :ApplySkillFormulaDamage(unit,enemy,skill,
                    enemy!=unit.shadowSlashTarget,0,
                    unit.shadowSlashTraitDamageMultiplier*pathScale);
            hits++;
            if(IsCombatActive(enemy)&&MonsterTraitRuntime.Has(
                unit.activeTraitIds,JaguarCombatRules.SuntigerTraitId))
                ApplySolarMark(unit,enemy);
        }

        if(MonsterTraitRuntime.Has(unit.activeTraitIds,JaguarCombatRules.StonetoraTraitId))
            ApplyRockHide(unit,hits);
        if(hits>0&&MonsterTraitRuntime.Has(
            unit.activeTraitIds,JaguarCombatRules.MuntashaTraitId))
            StartReleasedSkill(unit,ResolveEclipseAfterimage(unit,skill,victims,unit.shadowSlashStart,unit.shadowSlashPathEnd,
                combatGeneration));

        unit.skillHits+=hits;
        unit.skillDamage+=dealt;
        unit.shadowSlashing=false;
        unit.shadowSlashProgress=0f;
        unit.shadowSlashTarget=null;
        unit.shadowSlashVictims.Clear();
        unit.shadowSlashTraitDamageMultiplier=1f;
        CreateSkillPulse(unit,new Color(0.42f,0.15f,0.62f),0.85f);
        RecordSkillEvent(unit,unit.skillId+"_land",hits,dealt);
        BeginSkillInertia(unit,unit.shadowSlashEnd-unit.shadowSlashStart,duration);
    }

    private void UseShadowSlashEcho(Unit unit,Unit target,SkillMasterRow skill)
    {
        if(!IsCombatActive(unit)||!IsCombatActive(target))return;
        Vector3 start=Flat(unit.model.transform.position);
        Vector3 end=Flat(target.model.transform.position);
        Vector3 forward=(end-start).normalized;
        float length=Vector3.Distance(start,end)+TileSize*0.65f;
        float halfWidth=TileSize*Mathf.Max(0.2f,skill.radiusTiles);
        int hits=0;float dealt=0f;
        for(int i=0;i<units.Count;i++)
        {
            Unit enemy=units[i];
            if(!IsCombatActive(enemy)||enemy.team==unit.team||
               !IsPointInsideForwardSkillLine(start,forward,
                   Flat(enemy.model.transform.position),length,
                   halfWidth+enemy.collisionRadius))continue;
            dealt+=ApplySkillDamage(unit,enemy,unit.damage*skill.damageMultiplier*0.5f,false);
            hits++;
        }
        unit.skillHits+=hits;unit.skillDamage+=dealt;
        CreateJaguarPathEffect(start,start+forward*length,new Color(0.5f,0.28f,0.72f),0.16f);
        RecordSkillEvent(unit,skill.id+"_echo",hits,dealt);
    }

    private void ApplyJaguarHuntMark(Unit source,Unit target)
    {
        ClearJaguarHuntMark(source);
        source.jaguarMarkedTarget=target;
        source.jaguarMarkTimer=JaguarCombatRules.HuntMarkDuration;
    }

    private void ClearJaguarHuntMark(Unit source)
    {
        if(source==null)return;
        if(source.jaguarMarkMaterial!=null)Destroy(source.jaguarMarkMaterial);
        source.jaguarMarkMaterial=null;
        source.jaguarMarkedTarget=null;
        source.jaguarMarkTimer=0f;
    }

    private void ApplyRockHide(Unit unit,int hits)
    {
        float shield=unit.maxHp*JaguarCombatRules.RockShieldRatio(hits);
        if(shield<=0f)return;
        unit.itemShield=GateHaetaeBenefit(unit,Mathf.Max(unit.itemShield,shield*GuardianShieldMultiplier(unit)),CombatBenefitKind.Shield);
        unit.itemShieldTimer=Mathf.Max(unit.itemShieldTimer,JaguarCombatRules.RockShieldDuration);
        unit.traitActivations++;
        CreateSkillPulse(unit,new Color(0.46f,0.42f,0.34f),1.05f);
    }

    private IEnumerator ResolveEclipseAfterimage(Unit source,SkillMasterRow skill,
        List<Unit> victims,Vector3 start,Vector3 end,int generation)
    {
        yield return new WaitForSeconds(JaguarCombatRules.EclipseDelay);
        if(generation!=combatGeneration||!battleStarted||battleEnding)
            yield break;
        int hits=0;float dealt=0f;
        for(int i=0;i<victims.Count;i++)
        {
            Unit enemy=victims[i];
            if(!IsCombatActive(enemy)||enemy.team==source.team)continue;
            dealt+=ApplySkillFormulaDamage(source,enemy,skill,false,0,
                JaguarCombatRules.EclipseDamageRatio,false);
            hits++;
        }
        source.skillHits+=hits;source.skillDamage+=dealt;source.traitActivations++;
        CreateJaguarPathEffect(start,end,new Color(0.42f,0.28f,0.78f),0.2f);
        RecordSkillEvent(source,source.skillId+"_eclipse",hits,dealt);
    }

    private void ApplySolarMark(Unit source,Unit target)
    {
        if(target.combatStatuses.RejectHarmfulEffect())return;
        float totalDamage=JaguarCombatRules.SolarBurnDamage(source.damage);
        int ticks=Mathf.Max(1,Mathf.RoundToInt(
            JaguarCombatRules.SolarBurnDuration/JaguarCombatRules.SolarBurnTickInterval));
        target.solarBurnSource=source;
        target.solarBurnTimer=JaguarCombatRules.SolarBurnDuration;
        target.solarBurnTickTimer=JaguarCombatRules.SolarBurnTickInterval;
        target.solarBurnTickDamage=totalDamage/ticks;
        source.traitActivations++;
    }

    private void UpdateJaguarStates(Unit unit,float dt,bool pauseHarmful=false)
    {
        if(unit.jaguarMarkTimer>0f)
        {
            unit.jaguarMarkTimer=Mathf.Max(0f,unit.jaguarMarkTimer-dt);
            if(unit.jaguarMarkTimer<=0f||!IsCombatActive(unit.jaguarMarkedTarget))
                ClearJaguarHuntMark(unit);
        }
        if(unit.solarBurnTimer<=0f||unit.solarBurnSource==null)return;
        unit.solarBurnTickTimer-=dt;
        while(unit.solarBurnTickTimer<=0f&&unit.solarBurnTimer>0f&&IsCombatActive(unit))
        {
            unit.solarBurnTickTimer+=JaguarCombatRules.SolarBurnTickInterval;
            ApplyDamage(unit.solarBurnSource,unit,unit.solarBurnTickDamage,true,false,false);
        }
        if(!pauseHarmful)
            unit.solarBurnTimer=Mathf.Max(0f,unit.solarBurnTimer-dt);
        if(unit.solarBurnTimer<=0f||!IsCombatActive(unit))
        {
            unit.solarBurnSource=null;
            unit.solarBurnTimer=0f;
            unit.solarBurnTickTimer=0f;
            unit.solarBurnTickDamage=0f;
        }
    }

    private void CreateJaguarPathEffect(Vector3 start,Vector3 end,Color color,float size)
    {
    }

    private void CreateSkillPulse(Unit unit,Color color,float scale)
    {
        CreateSkillPulseAt(Flat(unit.model.transform.position),color,scale);
    }

    private void CreateSkillPulseAt(Vector3 position,Color color,float scale)
    {
    }

    private void RecordSkillEvent(Unit unit,string skill,int hits,float damage)
    {
        if(telemetryEpisodeStarted&&!telemetryEpisodeEnded&&telemetry!=null)
            telemetry.RecordSkill(battleElapsed,unit.id,skill,hits,damage);
    }

    private void UpdateCombatStalemateRecovery()
    {
        if(battleElapsed<nextStalemateRecoveryAt||
           battleElapsed-lastCombatProgressAt<StalemateRecoveryDelay)return;
        stalemateRecoveryCount++;
        nextStalemateRecoveryAt=battleElapsed+StalemateRecoveryDelay;
        List<Unit> active=units.Where(IsCombatActive).ToList();
        for(int i=0;i<active.Count;i++)
        {
            Unit unit=active[i];
            ReleaseAttackSlot(unit);
            ClearRoute(unit);
            unit.detourTimer=0f;
            unit.detourTarget=null;
            unit.repathTimer=0f;
            unit.blockedTimer=BlockedDecisionDelay;
            unit.decisionTimer=0f;
            unit.rangedRetreating=false;
            unit.rangedRetreatDistanceRemaining=0f;
            Unit nearest=active.Where(other=>other.team!=unit.team)
                .OrderBy(other=>Vector3.Distance(
                    Flat(unit.model.transform.position),
                    Flat(other.model.transform.position)))
                .ThenBy(other=>other.id).FirstOrDefault();
            if(nearest==null)continue;
            SetTarget(unit,nearest);
            BuildPursuitRoute(unit,nearest);
            if(stalemateRecoveryCount>=2)
            {
                Vector3 toward=Flat(nearest.model.transform.position-
                                    unit.model.transform.position);
                if(toward.sqrMagnitude>0.001f)
                    DisplaceUnit(unit,toward,TileSize*0.32f);
            }
        }
        Debug.Log("[Combat Recovery] No damage for "+
            StalemateRecoveryDelay.ToString("0")+"s. Rebuilt targets/routes (pass "+
            stalemateRecoveryCount+").");
    }

    private void ReconsiderBlockedTarget(Unit unit,bool routeBlocked)
    {
        if(unit.forcedTarget!=null&&unit.forcedTargetTimer>0f)
        {
            if(routeBlocked&&unit.repathTimer<=0f&&
               !ShouldKeepNavigationRoute(
                   unit.detourTarget==unit.target,unit.routeIndex,unit.route.Count))
            {
                BuildPursuitRoute(unit,unit.forcedTarget);
            }
            return;
        }
        if(!routeBlocked)return;
        if(ShouldKeepNavigationRoute(
               unit.detourTarget==unit.target,unit.routeIndex,unit.route.Count))return;
        if(unit.blockedTimer>=BlockedDecisionDelay)
        {
            if(unit.repathTimer>0f)return;
            bool foundRoute=BuildPursuitRoute(unit,unit.target);
            if(foundRoute)
            {
                unit.blockedTimer=0f;
                return;
            }
            return;
        }
        if(unit.repathTimer<=0f)
        {
            BuildPursuitRoute(unit,unit.target);
        }
    }

    private bool BuildPursuitRoute(Unit unit,Unit target)
    {
        return !IsRangedUnit(unit)&&!IsPersonalityPositioning(unit)&&unit.personalityRetreatTimer<=0f
            ?BuildClosestMeleeRoute(unit,target):BuildRoute(unit,target);
    }

    private Vector3 GetNavigationDirection(Unit unit,Vector3 directToTarget,bool routeBlocked)
    {
        bool melee=!IsRangedUnit(unit);
        if(!routeBlocked&&!ShouldKeepNavigationRoute(
               unit.detourTarget==unit.target,unit.routeIndex,unit.route.Count))
        {
            ClearRoute(unit);
            unit.detourTimer=0f;unit.detourTarget=null;unit.repathTimer=0f;
            return directToTarget;
        }
        if(melee&&!IsPersonalityPositioning(unit)&&unit.personalityRetreatTimer<=0f&&
           unit.repathTimer<=0f&&unit.detourTarget==unit.target&&unit.route.Count>0&&
           IsCombatTargetable(unit.target)&&MeleePursuitRouteNeedsRefresh(unit))
            BuildPursuitRoute(unit,unit.target);
        if(ShouldKeepNavigationRoute(
               unit.detourTarget==unit.target,unit.routeIndex,unit.route.Count))
        {
            Vector3 detourPosition=Flat(unit.model.transform.position);
            while(unit.routeIndex<unit.route.Count&&Vector3.Distance(detourPosition,unit.route[unit.routeIndex])<=
                  (melee||unit.routeIndex==unit.route.Count-1?.05f:TileSize*.32f))unit.routeIndex++;
            if(unit.routeIndex<unit.route.Count)
            {
                if(melee)
                    for(int next=unit.route.Count-1;next>unit.routeIndex;next--)
                        if(MeleeSlotSegmentClear(unit,unit.target,detourPosition,unit.route[next]))
                        {unit.routeIndex=next;break;}
                Vector3 waypoint=unit.route[unit.routeIndex];
                if(!melee?HasClearNavigationSegment(unit,detourPosition,waypoint):
                   MeleeSlotSegmentClear(unit,unit.target,detourPosition,waypoint))
                {
                    unit.currentAction="reroute";
                    return waypoint-detourPosition;
                }
            }
            ClearRoute(unit);
            unit.detourTimer=0f;unit.detourTarget=null;unit.repathTimer=0f;
        }
        if((unit.route.Count==0||unit.routeIndex>=unit.route.Count)&&unit.repathTimer<=0f)
            BuildPursuitRoute(unit,unit.target);
        Vector3 position=Flat(unit.model.transform.position);
        while(unit.routeIndex<unit.route.Count&&Vector3.Distance(position,unit.route[unit.routeIndex])<=
              (melee||unit.routeIndex==unit.route.Count-1?.05f:TileSize*.32f))unit.routeIndex++;
        if(unit.routeIndex<unit.route.Count)
        {
            if(melee)
                for(int next=unit.route.Count-1;next>unit.routeIndex;next--)
                    if(MeleeSlotSegmentClear(unit,unit.target,position,unit.route[next]))
                    {unit.routeIndex=next;break;}
            unit.currentAction="reroute";
            return unit.route[unit.routeIndex]-position;
        }
        unit.currentAction="path_wait";
        return Vector3.zero;
    }

    public static bool ShouldKeepNavigationRoute(
        bool targetMatches,int routeIndex,int routeCount)
    {
        return targetMatches&&routeIndex>=0&&routeIndex<routeCount;
    }

    public static bool ShouldWaitForOpenPath(
        bool routeBlocked,int routeIndex,int routeCount)
    {
        return routeBlocked&&(routeIndex<0||routeIndex>=routeCount);
    }

    private void ClearRoute(Unit unit)
    {
        unit.route.Clear();unit.routeIndex=0;
    }

    private Vector3 CalculateTacticalMovement(Unit unit,Vector3 toTarget,float distance,float moveSpeed)
    {
        if(toTarget.sqrMagnitude<.00000001f)return Vector3.zero;
        Vector3 forward=toTarget.normalized;
        if(IsPersonalityPositioning(unit))
        {
            unit.currentAction=unit.personalityPolicy.personalityId=="protective"
                ?"personality_guard":"personality_advance";
            return (unit.personalityMovePosition-Flat(unit.model.transform.position)).normalized*moveSpeed;
        }
        if(ShouldRetreatForPersonality(unit,unit.target))
        {
            unit.currentAction="personality_timid_retreat";
            Unit anchor=unit.personalityRetreatAnchor;
            if(IsCombatActive(anchor))
            {
                Vector3 towardAlly=Flat(anchor.model.transform.position)-
                                   Flat(unit.model.transform.position);
                if(towardAlly.sqrMagnitude>0.001f)
                    return towardAlly.normalized*moveSpeed;
            }
            return Vector3.zero;
        }
        if(ShouldRepositionRanged(unit,unit.target,distance,AttackDistance(unit,unit.target)))
        {
            unit.currentAction="personality_reposition";
            return -forward*moveSpeed;
        }
        // Follow the current pursuit/route direction after leaps and displacements.
        // Steering back to the deployment row can trigger the no-retreat guard forever.
        unit.currentAction="personality_pursue";
        return forward*moveSpeed;
    }

    private bool ShouldRetreatForPersonality(Unit unit,Unit target)
    {
        if(!IsCombatActive(unit)||!IsCombatActive(target))return false;
        if(HasPreyFocus(unit)||HasActiveTaunt(unit)||IsAttackMovementLocked(unit)||
           unit.griffinRootTimer>0f||unit.combatStatuses.Has(CombatStatusKind.Root))
        {StopTimidRetreat(unit);return false;}
        PersonalityCombatPolicy policy=unit.personalityPolicy??PersonalityCombatPolicy.Balanced();
        if(!policy.timidRetreat)return false;

        Vector3 position=Flat(unit.model.transform.position);
        bool mutualDuel=target.target==unit&&Vector3.Distance(position,Flat(target.model.transform.position))<=
            AttackDistance(target,unit)+TileSize;
        int attackers=0;
        bool hasNearbySupport=false;
        for(int i=0;i<units.Count;i++)
        {
            Unit other=units[i];
            if(!IsCombatActive(other))continue;
            if(other.team!=unit.team)
            {
                if(other.target==unit&&Vector3.Distance(position,Flat(other.model.transform.position))<=
                   AttackDistance(other,unit)+TileSize)attackers++;
            }
            else if(!hasNearbySupport&&other!=unit&&
                    Vector3.Distance(position,Flat(other.model.transform.position))<=
                    TileSize*TimidSupportRadiusTiles)hasNearbySupport=true;
        }
        Unit anchor=IsCombatActive(unit.personalityRetreatAnchor)
            ?unit.personalityRetreatAnchor:FindNearestTimidAlly(unit);
        bool hasPath=HasTimidRetreatStep(unit,anchor);

        if(unit.personalityRetreatTimer>0f)
        {
            if(hasPath&&Vector3.Distance(position,Flat(anchor.model.transform.position))>TileSize)
            {
                unit.personalityRetreatAnchor=anchor;
                return true;
            }
            StopTimidRetreat(unit);
            return false;
        }
        if(!PersonalityCombatPolicy.ShouldTimidRetreat(
               mutualDuel,hasNearbySupport,anchor!=null,hasPath,
               unit.personalityRetreatCooldown<=0f&&unit.targetLockTimer<=0f,
               attackers,unit.hp<=unit.maxHp*.4f))return false;
        unit.personalityRetreatAnchor=anchor;
        unit.personalityRetreatTimer=TimidRetreatDuration;
        unit.personalityRetreatCooldown=TimidRetreatCooldown;
        unit.personalityMoveTimer=0f;
        ReleaseAttackSlot(unit);ClearRoute(unit);
        ShowPersonalityCue(unit);
        return true;
    }

    private Unit FindNearestTimidAlly(Unit unit)
    {
        Unit nearest=null;
        Vector3 position=Flat(unit.model.transform.position);
        for(int i=0;i<units.Count;i++)
        {
            Unit ally=units[i];
            if(ally==unit||!IsCombatActive(ally)||ally.team!=unit.team||
               Vector3.Distance(Flat(unit.model.transform.position),Flat(ally.model.transform.position))>TileSize*4f||
               !HasTimidRetreatStep(unit,ally))continue;
            if(nearest!=null&&!IsPreferredNearestTarget(
                   position,ally.model.transform.position,ally.id,
                   nearest.model.transform.position,nearest.id))continue;
            nearest=ally;
        }
        return nearest;
    }

    private bool HasTimidRetreatStep(Unit unit,Unit anchor)
    {
        if(!IsCombatActive(anchor))return false;
        Vector3 position=Flat(unit.model.transform.position);
        Vector3 toward=Flat(anchor.model.transform.position)-position;
        if(toward.sqrMagnitude<0.001f)return false;
        Vector3 retreat=ResolveFreePosition(
            position+toward.normalized*TileSize*0.42f,CombatBodyRadius(unit));
        return Vector3.Distance(position,retreat)>=TileSize*0.08f&&
               (!IsCombatActive(unit.target)||Vector3.Distance(retreat,Flat(unit.target.model.transform.position))>
                   Vector3.Distance(position,Flat(unit.target.model.transform.position))+TileSize*.05f)&&
               IsNavigationCoordinate(NearestGridCoordinate(retreat))&&
               HasClearPathSegment(position,retreat,CombatBodyRadius(unit)*0.8f)&&
               !HasUnitBlockingPath(unit,retreat);
    }

    private static void StopTimidRetreat(Unit unit)
    {
        unit.personalityRetreatTimer=0f;
        unit.personalityRetreatAnchor=null;
    }

    private bool ShouldRepositionRanged(Unit unit,Unit target)
    {
        if(!IsCombatActive(unit)||!IsCombatActive(target))return false;
        float distance=Vector3.Distance(
            Flat(unit.model.transform.position),Flat(target.model.transform.position));
        return ShouldRepositionRanged(unit,target,distance,AttackDistance(unit,target));
    }

    private bool ShouldRepositionRanged(
        Unit unit,Unit target,float distance,float attackDistance)
    {
        if(unit!=null&&unit.rangedRetreating)CompleteRangedRetreat(unit);
        return false;
    }

    private Unit FindMostThreatenedAlly(Unit guardian)
    {
        Unit best=null;float bestScore=float.MaxValue;
        for(int i=0;i<units.Count;i++)
        {
            Unit ally=units[i];
            if(!IsCombatActive(ally)||ally.team!=guardian.team||ally==guardian)continue;
            float hpRatio=ally.hp/Mathf.Max(1f,ally.maxHp);
            float enemyDistance=NearestUnitDistance(ally,ally.team,false);
            float score=hpRatio*4f+enemyDistance;
            if(score<bestScore){bestScore=score;best=ally;}
        }
        return best;
    }

    private void ReleaseAttackSlot(Unit unit)
    {
        unit.reservedAttackTarget=null;unit.reservedAttackSlot=-1;
    }

    public static float AttackSlotDistance(
        float attackDistance,float sourceRadius,float targetRadius)
    {
        return Mathf.Max(
            Mathf.Max(0f,sourceRadius)+Mathf.Max(0f,targetRadius)+0.54f+MeleeReadabilitySpacing,
            Mathf.Max(0f,attackDistance)-0.08f);
    }

    public static float AttackSlotDistanceForRing(
        float attackDistance,float sourceRadius,float targetRadius,int ring)
    {
        float inner=Mathf.Max(0f,sourceRadius)+Mathf.Max(0f,targetRadius)+0.54f+MeleeReadabilitySpacing;
        float outer=AttackSlotDistance(attackDistance,sourceRadius,targetRadius);
        return ring<=0?Mathf.Lerp(inner,outer,0.5f):outer;
    }

    private bool HasClearRoute(Unit source,Unit target)
    {
        if(source==null||target==null||source.model==null||target.model==null)return false;
        if(UsesHiddenHexCombat)return true;
        return HasClearPath(source,Flat(target.model.transform.position));
    }

    private bool HasClearPath(Unit source,Vector3 destination)
    {
        if(source==null||source.model==null)return false;
        Vector3 start=Flat(source.model.transform.position);
        return HasClearPathSegment(start,Flat(destination),CombatBodyRadius(source))&&
               !IsHostileIceWallBlocking(source,start,Flat(destination));
    }

    private bool HasClearPathSegment(Vector3 from,Vector3 to,float collisionRadius)
    {
        float extent=TileHalfExtent+collisionRadius;
        if(navigationQueryActive)
        {
            for(int i=0;i<navigationObstacles.Count;i++)
                if(SegmentIntersectsSquare(from,to,navigationObstacles[i].world,extent))return false;
            return true;
        }
        foreach(Tile tile in tiles.Values)
            if(!tile.walkable&&SegmentIntersectsSquare(from,to,tile.world,extent))return false;
        return true;
    }

    private bool HasUnitBlockingPath(Unit source,Vector3 destination)
    {
        return HasUnitBlockingSegment(source,Flat(source.model.transform.position),Flat(destination));
    }

    private bool HasUnitBlockingSegment(Unit source,Vector3 from,Vector3 to)
    {
        Vector3 segment=to-from;
        float lengthSquared=segment.sqrMagnitude;
        if(lengthSquared<0.00000001f)return false;
        bool snapshot=navigationQueryActive;
        int count=snapshot?navigationBodies.Count:units.Count;
        for(int i=0;i<count;i++)
        {
            Unit other=snapshot?navigationBodies[i].unit:units[i];
            if(other==source||other==source.target||!snapshot&&!IsCombatActive(other))continue;
            Vector3 otherPosition=snapshot?navigationBodies[i].position:Flat(other.model.transform.position);
            float t=Mathf.Clamp01(Vector3.Dot(otherPosition-from,segment)/lengthSquared);
            Vector3 closest=from+segment*t;
            float clearance=BodyClearance(source,other,UnitMovementClearance);
            // A short arrival step still hits neighbours; only an outward escape may start inside their spacing.
            if((from-otherPosition).sqrMagnitude<clearance*clearance&&
               Vector3.Dot(from-otherPosition,segment)>=0f)continue;
            if((otherPosition-closest).sqrMagnitude<clearance*clearance)return true;
        }
        return false;
    }

    private bool HasClearNavigationSegment(Unit unit,Vector3 from,Vector3 to)
    {
        return HasClearPathSegment(from,to,CombatBodyRadius(unit))&&
               !HasUnitBlockingSegment(unit,from,to)&&!IsHostileIceWallBlocking(unit,from,to);
    }

    private static bool SegmentIntersectsSquare(Vector3 from,Vector3 to,Vector3 center,float extent)
    {
        Vector3 direction=to-from;
        float min=0f,max=1f;
        if(!ClipSegmentAxis(from.x-center.x,direction.x,-extent,extent,ref min,ref max))return false;
        return ClipSegmentAxis(from.z-center.z,direction.z,-extent,extent,ref min,ref max);
    }

    private static bool ClipSegmentAxis(float start,float direction,float minimum,float maximum,ref float enter,ref float exit)
    {
        if(Mathf.Abs(direction)<0.0001f)return start>=minimum&&start<=maximum;
        float a=(minimum-start)/direction,b=(maximum-start)/direction;
        if(a>b){float swap=a;a=b;b=swap;}
        enter=Mathf.Max(enter,a);exit=Mathf.Min(exit,b);
        return enter<=exit;
    }

    private bool BuildRoute(Unit unit,Unit target)
    {
        ClearRoute(unit);unit.repathTimer=0.12f;
        if(target==null||target.model==null)return false;
        Vector2Int start=NearestWalkableCoordinate(NearestGridCoordinate(unit.model.transform.position));
        Vector2Int goal=NearestWalkableCoordinate(NearestGridCoordinate(target.model.transform.position));
        if(TryFindGridRoute(
               unit,start,goal,out List<Vector3> result,out _,out _))
        {
            result=SimplifyRoute(unit,Flat(unit.model.transform.position),result);
            unit.route.AddRange(result);unit.routeIndex=0;
            if(result.Count>0)
            {
                unit.detourTimer=3f;unit.detourTarget=target;unit.currentAction="reroute";
            }
            return true;
        }
        return false;
    }

    private bool IsOpenAttackPosition(Unit unit,Unit target,Vector3 position)
    {
        Vector3 resolved=ResolveFreePosition(position,CombatBodyRadius(unit));
        if(Vector3.Distance(resolved,position)>0.08f)return false;
        for(int i=0;i<units.Count;i++)
        {
            Unit other=units[i];
            if(other==unit||other==target||!IsCombatActive(other))continue;
            float minimum=BodyClearance(unit,other,AttackSlotBodyClearance);
            if(Vector3.Distance(position,Flat(other.model.transform.position))<minimum)return false;
        }
        return true;
    }

    private float PositionCrowdPenalty(Unit unit,Unit target,Vector3 position)
    {
        float penalty=0f;
        for(int i=0;i<units.Count;i++)
        {
            Unit other=units[i];
            if(other==unit||other==target||!IsCombatActive(other))continue;
            float distance=Vector3.Distance(position,Flat(other.model.transform.position));
            if(distance<TileSize*2.2f)penalty+=(TileSize*2.2f-distance)/TileSize*2.5f;
        }
        return penalty;
    }

    private List<Vector3> SimplifyRoute(Unit unit,Vector3 start,List<Vector3> route)
    {
        if(route==null||route.Count<2)return route??new List<Vector3>();
        List<Vector3> simplified=new List<Vector3>();
        Vector3 anchor=Flat(start);
        int index=0;
        while(index<route.Count)
        {
            int furthest=index;
            for(int candidate=route.Count-1;candidate>=index;candidate--)
            {
                if(!HasClearNavigationSegment(unit,anchor,Flat(route[candidate])))continue;
                furthest=candidate;
                break;
            }
            simplified.Add(route[furthest]);
            anchor=Flat(route[furthest]);
            index=furthest+1;
        }
        return simplified;
    }

    private static float RouteDistance(Vector3 start,List<Vector3> route)
    {
        float distance=0f;
        Vector3 previous=Flat(start);
        for(int i=0;i<route.Count;i++)
        {
            Vector3 next=Flat(route[i]);
            distance+=Vector3.Distance(previous,next);
            previous=next;
        }
        return distance;
    }

    // Queries run synchronously; clear scratch buffers per query and keep returned routes independent.
    private readonly List<Vector2Int> navigationOpen=new List<Vector2Int>();
    private readonly HashSet<Vector2Int> navigationClosed=new HashSet<Vector2Int>();
    private readonly Dictionary<Vector2Int,Vector2Int> navigationPrevious=new Dictionary<Vector2Int,Vector2Int>();
    private readonly Dictionary<Vector2Int,float> navigationCost=new Dictionary<Vector2Int,float>();
    private readonly Dictionary<Vector2Int,Vector3> navigationPositions=new Dictionary<Vector2Int,Vector3>();
    private readonly Dictionary<Vector2Int,bool> navigationOccupied=new Dictionary<Vector2Int,bool>();
    private readonly List<Vector2Int> navigationReversed=new List<Vector2Int>();
    private readonly List<Tile> navigationObstacles=new List<Tile>();
    private struct NavigationBody
    {
        public Unit unit;
        public Vector3 position;
    }
    private readonly List<NavigationBody> navigationBodies=new List<NavigationBody>();
    private bool navigationQueryActive;
    private static readonly Vector2Int[] NavigationDirections=
    {
        Vector2Int.right,Vector2Int.left,Vector2Int.up,Vector2Int.down,
        new Vector2Int(1,1),new Vector2Int(1,-1),new Vector2Int(-1,1),new Vector2Int(-1,-1)
    };

    private Vector3 CachedNavigationWorld(Unit unit,Vector2Int coordinate)
    {
        if(!navigationPositions.TryGetValue(coordinate,out Vector3 position))
        {
            if(navigationObstacles.Count==0)
            {
                position=GridWorld(coordinate,false);
                float radius=CombatBodyRadius(unit);
                position.x=Mathf.Clamp(position.x,combatBounds.min.x+radius,combatBounds.max.x-radius);
                position.z=Mathf.Clamp(position.z,combatBounds.min.z+radius,combatBounds.max.z-radius);
            }
            else position=NavigationWorld(unit,coordinate);
            navigationPositions[coordinate]=position;
        }
        return position;
    }

    private bool TryFindGridRoute(
        Unit unit,Vector2Int start,Vector2Int goal,out List<Vector3> result,
        out float resultCost,out bool reachedGoal,Unit blockingTarget=null,
        IReadOnlyList<Vector2Int> alternativeGoals=null,Vector3? finalPosition=null)
    {
        result=new List<Vector3>();resultCost=0f;
        bool melee=blockingTarget!=null;
        reachedGoal=!melee&&start==goal;
        if(reachedGoal)return true;
        bool previousQuery=BeginNavigationQuery();
        try
        {
            var open=navigationOpen;open.Clear();open.Add(start);
            var closed=navigationClosed;closed.Clear();
            var cameFrom=navigationPrevious;cameFrom.Clear();
            var cost=navigationCost;cost.Clear();cost[start]=0f;
            navigationPositions.Clear();navigationOccupied.Clear();
            // Melee routes start at the moving body's real position, not an offset grid-cell center.
            if(blockingTarget!=null)navigationPositions[start]=Flat(unit.model.transform.position);
            Vector2Int closest=start;
            Vector3 goalPosition=CachedNavigationWorld(unit,goal);
            float closestDistance=(CachedNavigationWorld(unit,start)-goalPosition).sqrMagnitude;
            float closestCost=0f;
            float lanePenalty=IsFlankingUnit(unit)?0.05f:LaneNavigationPenalty;
            int preferredGoal=int.MaxValue;
            float bestGoalCost=float.PositiveInfinity;
            while(open.Count>0)
            {
                int bestIndex=0;float bestScore=float.MaxValue;
                for(int i=0;i<open.Count;i++)
                {
                    Vector2Int node=open[i];
                    float score=cost[node]+(melee
                        ?MeleeNavigationHeuristic(unit,node,goal,alternativeGoals,finalPosition)
                        :OctileDistance(node,goal));
                    if(score<bestScore){bestScore=score;bestIndex=i;}
                }
                if(melee&&reachedGoal&&bestScore>=bestGoalCost)break;
                Vector2Int current=open[bestIndex];open.RemoveAt(bestIndex);
                Vector3 currentPosition=CachedNavigationWorld(unit,current);
                float currentDistance=(currentPosition-goalPosition).sqrMagnitude;
                if(!reachedGoal&&IsCloserNavigationPoint(
                       currentDistance,cost[current],closestDistance,closestCost))
                {
                    closest=current;closestDistance=currentDistance;
                    closestCost=cost[current];
                }
                int goalIndex=alternativeGoals==null?(current==goal?0:-1):
                    IndexOfNavigationGoal(alternativeGoals,current);
                if(goalIndex>=0&&melee)
                {
                    float total=cost[current]+(finalPosition.HasValue
                        ?Vector3.Distance(currentPosition,Flat(finalPosition.Value)):0f);
                    if(total<bestGoalCost&&(!finalPosition.HasValue||
                       MeleeSlotSegmentClear(unit,blockingTarget,currentPosition,Flat(finalPosition.Value))))
                    {
                        reachedGoal=true;bestGoalCost=total;closest=current;
                    }
                }
                else if(goalIndex>=0&&goalIndex<preferredGoal)
                {
                    reachedGoal=true;
                    preferredGoal=goalIndex;closest=current;
                    if(goalIndex==0)break;
                }
                closed.Add(current);
                for(int i=0;i<NavigationDirections.Length;i++)
                {
                    Vector2Int next=current+NavigationDirections[i];
                    if(!IsNavigationCoordinate(next)||closed.Contains(next))continue;
                    if(next!=goal&&(alternativeGoals==null||
                       IndexOfNavigationGoal(alternativeGoals,next)<0)&&
                       IsTemporarilyOccupied(unit,next))continue;
                    Vector2Int direction=next-current;
                    bool diagonal=direction.x!=0&&direction.y!=0;
                    if(diagonal)
                    {
                        Vector2Int horizontal=current+new Vector2Int(direction.x,0);
                        Vector2Int vertical=current+new Vector2Int(0,direction.y);
                        if(!CanTraverseDiagonal(
                               IsNavigationCoordinate(horizontal),
                               IsNavigationCoordinate(vertical)))continue;
                    }
                    if(blockingTarget!=null
                        ?!MeleeSlotSegmentClear(unit,blockingTarget,currentPosition,CachedNavigationWorld(unit,next))
                        :!HasClearNavigationSegment(unit,currentPosition,CachedNavigationWorld(unit,next)))continue;
                    float nextCost=cost[current]+(melee
                        ?Vector3.Distance(currentPosition,CachedNavigationWorld(unit,next))
                        :(diagonal?1.4142f:1f)+Mathf.Abs(next.y-unit.initialTile.y)*lanePenalty);
                    if(cost.TryGetValue(next,out float existing)&&existing<=nextCost)continue;
                    cost[next]=nextCost;cameFrom[next]=current;
                    if(!open.Contains(next))open.Add(next);
                }
            }
            if(closest==start)
            {if(reachedGoal&&melee)resultCost=bestGoalCost;return reachedGoal;}
            var reversed=navigationReversed;reversed.Clear();
            Vector2Int step=closest;
            while(step!=start){reversed.Add(step);step=cameFrom[step];}
            reversed.Reverse();
            for(int i=0;i<reversed.Count;i++)
                result.Add(CachedNavigationWorld(unit,reversed[i]));
            resultCost=melee&&reachedGoal?bestGoalCost:cost[closest];
            return result.Count>0;
        }
        finally{navigationQueryActive=previousQuery;}
    }

    private float MeleeNavigationHeuristic(Unit unit,Vector2Int coordinate,Vector2Int goal,
        IReadOnlyList<Vector2Int> alternatives,Vector3? finalPosition)
    {
        Vector3 position=CachedNavigationWorld(unit,coordinate);
        if(finalPosition.HasValue)return Vector3.Distance(position,Flat(finalPosition.Value));
        float nearest=Vector3.Distance(position,CachedNavigationWorld(unit,goal));
        if(alternatives!=null)
            for(int i=0;i<alternatives.Count;i++)
                nearest=Mathf.Min(nearest,Vector3.Distance(position,CachedNavigationWorld(unit,alternatives[i])));
        return nearest;
    }

    private bool BeginNavigationQuery()
    {
        bool previous=navigationQueryActive;
        if(!previous)
        {
            navigationObstacles.Clear();
            foreach(Tile tile in tiles.Values)if(!tile.walkable)navigationObstacles.Add(tile);
            navigationBodies.Clear();
            foreach(Unit unit in units)
                if(IsCombatActive(unit))navigationBodies.Add(new NavigationBody
                    {unit=unit,position=Flat(unit.model.transform.position)});
        }
        navigationQueryActive=true;
        return previous;
    }

    private static int IndexOfNavigationGoal(IReadOnlyList<Vector2Int> goals,Vector2Int coordinate)
    {
        for(int i=0;i<goals.Count;i++)if(goals[i]==coordinate)return i;
        return -1;
    }

    public static bool IsCloserNavigationPoint(
        float candidateDistance,float candidateCost,
        float bestDistance,float bestCost)
    {
        return candidateDistance<bestDistance-0.0001f||
               Mathf.Abs(candidateDistance-bestDistance)<=0.0001f&&
               candidateCost<bestCost;
    }

    public static bool CanTraverseDiagonal(
        bool horizontalWalkable,bool verticalWalkable)
    {
        return horizontalWalkable&&verticalWalkable;
    }

    private bool IsTemporarilyOccupied(Unit source,Vector2Int coordinate)
    {
        if(navigationOccupied.TryGetValue(coordinate,out bool occupied))return occupied;
        Vector3 position=CachedNavigationWorld(source,coordinate);
        bool snapshot=navigationQueryActive;
        int count=snapshot?navigationBodies.Count:units.Count;
        for(int i=0;i<count;i++)
        {
            Unit other=snapshot?navigationBodies[i].unit:units[i];
            if(other==source||other==source.target||!snapshot&&!IsCombatActive(other))continue;
            float clearance=BodyClearance(source,other,UnitMovementClearance);
            Vector3 otherPosition=snapshot?navigationBodies[i].position:Flat(other.model.transform.position);
            if((otherPosition-position).sqrMagnitude<clearance*clearance)
            {navigationOccupied[coordinate]=true;return true;}
        }
        navigationOccupied[coordinate]=false;
        return false;
    }

    private static float OctileDistance(Vector2Int from,Vector2Int to)
    {
        int dx=Mathf.Abs(from.x-to.x);
        int dy=Mathf.Abs(from.y-to.y);
        int diagonal=Mathf.Min(dx,dy);
        int straight=Mathf.Max(dx,dy)-diagonal;
        return diagonal*1.4142f+straight;
    }

    private bool IsWalkableCoordinate(Vector2Int coordinate)
    {
        return tiles.TryGetValue(coordinate,out Tile tile)&&tile.walkable;
    }

    private bool IsNavigationCoordinate(Vector2Int coordinate)
    {
        if(tiles.TryGetValue(coordinate,out Tile tile)&&!tile.bench)
            return tile.walkable;
        return UsesHexDeployment&&
               NavigationPointInsideBounds(GridWorld(coordinate,false),combatBounds);
    }

    public static bool NavigationPointInsideBounds(Vector3 point,Bounds bounds)
    {
        const float epsilon=0.001f;
        return point.x>=bounds.min.x-epsilon&&point.x<=bounds.max.x+epsilon&&
               point.z>=bounds.min.z-epsilon&&point.z<=bounds.max.z+epsilon;
    }

    private Vector3 NavigationWorld(Unit unit,Vector2Int coordinate)
    {
        return ResolveFreePosition(GridWorld(coordinate,false),CombatBodyRadius(unit));
    }

    private Vector2Int NearestWalkableCoordinate(Vector2Int origin)
    {
        if(IsWalkableCoordinate(origin))return origin;
        Vector2Int best=origin;float bestDistance=float.MaxValue;
        foreach(Tile tile in tiles.Values)
        {
            if(!tile.walkable)continue;
            float distance=(tile.coordinate-origin).sqrMagnitude;
            if(distance<bestDistance){bestDistance=distance;best=tile.coordinate;}
        }
        return best;
    }

    private static float CombatBodyRadius(Unit unit)
    {
        // Authored damage radii stay separate from persistent rank/form enlargement.
        return unit.collisionRadius*unit.combatBodyScale;
    }

    private static float BodyClearance(Unit unit,Unit other,float opposingPadding)
    {
        return CombatBodyRadius(unit)+CombatBodyRadius(other)+
            (unit.team==other.team?AllyBodyClearance:opposingPadding)*
            ((unit.combatBodyScale+other.combatBodyScale)*.5f);
    }

    private Vector3 CalculateSeparation(Unit unit,float moveSpeed)
    {
        Vector3 result=Vector3.zero;
        Vector3 position=Flat(unit.model.transform.position);
        for(int i=0;i<units.Count;i++)
        {
            Unit other=units[i];
            if(other==unit||!IsCombatActive(other)||other.monkeyNimbus!=null||other.beetleOverturnedBy!=null&&other.beetleOverturnedBy.flying)continue;
            Vector3 away=position-Flat(other.model.transform.position);
            float distance=away.magnitude;
            float desired=BodyClearance(unit,other,.2f);
            if(distance>=desired)continue;
            if(distance<0.001f)away=new Vector3(UnityEngine.Random.value-0.5f,0f,UnityEngine.Random.value-0.5f).normalized;
            else away/=distance;
            result+=away*((desired-distance)/desired)*moveSpeed*1.75f;
        }
        return result;
    }

    private Vector3 CalculateObstacleAvoidance(Unit unit,float moveSpeed)
    {
        Vector3 result=Vector3.zero;
        Vector3 position=Flat(unit.model.transform.position);
        foreach(Tile tile in tiles.Values)
        {
            if(tile.walkable)continue;
            Vector3 away=position-tile.world;away.y=0f;
            float distance=away.magnitude;
            float desired=TileHalfExtent+CombatBodyRadius(unit)+0.55f;
            if(distance>=desired)continue;
            if(distance<0.001f)away=Vector3.right;else away/=distance;
            result+=away*((desired-distance)/desired)*moveSpeed*2.2f;
        }
        return result;
    }

    private Vector3 ResolveFreePosition(Vector3 position,float radius)
    {
        position.x=Mathf.Clamp(position.x,combatBounds.min.x+radius,combatBounds.max.x-radius);
        position.z=Mathf.Clamp(position.z,combatBounds.min.z+radius,combatBounds.max.z-radius);
        if(navigationQueryActive)
            for(int i=0;i<navigationObstacles.Count;i++)
                position=ResolveObstaclePosition(position,radius,navigationObstacles[i]);
        else
            foreach(Tile tile in tiles.Values)
                if(!tile.walkable)position=ResolveObstaclePosition(position,radius,tile);
        return position;
    }

    private static Vector3 ResolveObstaclePosition(Vector3 position,float radius,Tile tile)
    {
        Vector3 delta=position-tile.world;delta.y=0f;
        float extent=TileHalfExtent+radius;
        if(Mathf.Abs(delta.x)>=extent||Mathf.Abs(delta.z)>=extent)return position;
        float pushX=extent-Mathf.Abs(delta.x),pushZ=extent-Mathf.Abs(delta.z);
        if(pushX<pushZ)position.x+=Mathf.Sign(Mathf.Abs(delta.x)<0.001f?1f:delta.x)*pushX;
        else position.z+=Mathf.Sign(Mathf.Abs(delta.z)<0.001f?1f:delta.z)*pushZ;
        return position;
    }

    private void EnsureCombatUnitInsideArena(Unit unit)
    {
        Vector3 current=Flat(unit.model.transform.position);
        Vector3 inside=ResolveFreePosition(current,CombatBodyRadius(unit));
        if(Vector3.Distance(current,inside)<=0.001f)return;
        unit.model.transform.position=inside+Vector3.up*unit.visualHeightOffset;
        unit.ring.transform.position=inside+Vector3.up*0.025f;
        unit.lastGroundPosition=inside;
        unit.currentTile=NearestGridCoordinate(inside);
        unit.velocity=Vector3.zero;
        unit.frogHopping=false;
        unit.frogHopProgress=0f;
        unit.frogRestTimer=0f;
        unit.moving=false;
        ClearRoute(unit);
        SetMoving(unit,false);
    }

    private Vector3 ResolveUnitMovement(Unit unit,Vector3 previous,Vector3 proposed)
    {
        return ResolveBodyMovement(unit,previous,proposed,true);
    }

    private Vector3 ResolveBodyMovement(Unit unit,Vector3 previous,Vector3 proposed,bool spacing)
    {
        proposed=ResolveFrictionlessFreePosition(
            previous,proposed-previous,CombatBodyRadius(unit));
        for(int pass=0;pass<2;pass++)
        for(int i=0;i<units.Count;i++)
        {
            Unit other=units[i];
            if(other==unit||!IsCombatActive(other)||other.monkeyNimbus!=null)continue;
            Vector3 otherGround=Flat(other.model.transform.position);
            float minimum=spacing?BodyClearance(unit,other,UnitMovementClearance):
                CombatBodyRadius(unit)+CombatBodyRadius(other);
            Vector3 proposedDelta=proposed-otherGround;
            if(proposedDelta.sqrMagnitude>=minimum*minimum)continue;

            Vector3 previousDelta=previous-otherGround;
            Vector3 normal=previousDelta.sqrMagnitude>0.0001f?previousDelta.normalized:
                new Vector3(((unit.id+other.id)&1)==0?1f:-1f,0f,((unit.id-other.id)&1)==0?0.35f:-0.35f).normalized;
            Vector3 movement=proposed-previous;
            float previousDistance=previousDelta.magnitude;
            if(previousDistance<minimum)
            {
                movement=FrictionlessSlide(movement,normal);
                float correction=Mathf.Min(minimum-previousDistance,TileSize*0.08f);
                proposed=ResolveFrictionlessFreePosition(
                    previous,movement+normal*correction,CombatBodyRadius(unit));
                continue;
            }
            movement=FrictionlessSlide(movement,normal);
            Vector3 slid=ResolveFrictionlessFreePosition(
                previous,movement,CombatBodyRadius(unit));
            if((slid-otherGround).sqrMagnitude<minimum*minimum)slid=previous;
            proposed=slid;
        }
        // Sliding around the last body must not put us inside an earlier one.
        return IntroducesBodyOverlap(unit,previous,proposed,!spacing)?previous:proposed;
    }

    private Vector3 ResolveFrictionlessFreePosition(
        Vector3 previous,Vector3 movement,float radius)
    {
        Vector3 resolved=ResolveFreePosition(previous+movement,radius);
        Vector3 allowed=resolved-previous;
        if(allowed.sqrMagnitude>=movement.sqrMagnitude||
           allowed.sqrMagnitude<0.000001f||Vector3.Dot(allowed,movement)<=0f)
            return resolved;
        return ResolveFreePosition(
            previous+allowed.normalized*movement.magnitude,radius);
    }

    public static Vector3 FrictionlessSlide(
        Vector3 movement,Vector3 collisionNormal)
    {
        float inward=Vector3.Dot(movement,collisionNormal);
        if(inward>=0f)return movement;
        Vector3 tangent=movement-collisionNormal*inward;
        return tangent.sqrMagnitude<0.000001f
            ?Vector3.zero
            :tangent.normalized*movement.magnitude;
    }

    private Unit SelectTarget(Unit source,bool requireClearRoute=false,Unit excluded=null)
    {
        Unit nearest=SelectNearestTarget(source,requireClearRoute,excluded);
        if(nearest==null)return null;
        PersonalityCombatPolicy policy=
            source.personalityPolicy??PersonalityCombatPolicy.Balanced();
        if(policy.targetStyle!=PersonalityTargetStyle.Cooperative)return nearest;

        Vector3 sourcePosition=Flat(source.model.transform.position);
        float nearestDistance=Vector3.Distance(
            sourcePosition,Flat(nearest.model.transform.position));
        Unit preferred=nearest;
        int preferredSignal=PersonalityTargetSignal(source,nearest,policy.targetStyle);
        for(int i=0;i<units.Count;i++)
        {
            Unit candidate=units[i];
            if(!IsCombatTargetable(candidate)||candidate.crocodilePreyFlying||candidate.team==source.team||
               candidate==excluded)continue;
            if(requireClearRoute&&!HasClearRoute(source,candidate))continue;
            float candidateDistance=Vector3.Distance(
                sourcePosition,Flat(candidate.model.transform.position));
            if(!PersonalityCombatPolicy.IsWithinLocalTargetWindow(
                   nearestDistance,candidateDistance,
                   TileSize*PersonalityTargetWindowTiles))continue;
            int signal=PersonalityTargetSignal(source,candidate,policy.targetStyle);
            if(signal<preferredSignal||signal==preferredSignal&&
               !IsPreferredNearestTarget(
                   sourcePosition,candidate.model.transform.position,candidate.id,
                   preferred.model.transform.position,preferred.id))continue;
            preferred=candidate;
            preferredSignal=signal;
        }
        return preferred;
    }

    private Unit SelectNearestTarget(
        Unit source,bool requireClearRoute=false,Unit excluded=null)
    {
        Unit best=null;
        for(int i=0;i<units.Count;i++)
        {
            Unit candidate=units[i];if(!IsCombatTargetable(candidate)||candidate.crocodilePreyFlying||candidate.team==source.team||candidate==excluded)continue;
            if(requireClearRoute&&!HasClearRoute(source,candidate))continue;
            if(best!=null&&!IsPreferredNearestTarget(
                   source.model.transform.position,
                   candidate.model.transform.position,candidate.id,
                   best.model.transform.position,best.id))continue;
            best=candidate;
        }
        return best;
    }

    private int PersonalityTargetSignal(
        Unit source,Unit candidate,PersonalityTargetStyle targetStyle)
    {
        if(targetStyle==PersonalityTargetStyle.Cooperative)
            return units.Count(ally=>ally!=source&&IsCombatActive(ally)&&
                ally.team==source.team&&ally.target==candidate);
        return units.Count(enemy=>IsCombatActive(enemy)&&enemy.team!=source.team&&
            Vector3.Distance(Flat(enemy.model.transform.position),
                Flat(candidate.model.transform.position))<=TileSize*1.5f);
    }

    private bool IsLocalPersonalityTarget(Unit source,Unit candidate)
    {
        if(!IsCombatActive(source)||!IsCombatTargetable(candidate)||candidate.crocodilePreyFlying||
           source.team==candidate.team)return false;
        Unit nearest=SelectNearestTarget(source);
        if(nearest==null)return false;
        Vector3 position=Flat(source.model.transform.position);
        return PersonalityCombatPolicy.IsWithinLocalTargetWindow(
            Vector3.Distance(position,Flat(nearest.model.transform.position)),
            Vector3.Distance(position,Flat(candidate.model.transform.position)),
            TileSize*PersonalityTargetWindowTiles);
    }

    public static bool IsPreferredNearestTarget(
        Vector3 source,Vector3 candidate,int candidateId,
        Vector3 currentBest,int currentBestId)
    {
        source.y=0f;candidate.y=0f;currentBest.y=0f;
        float candidateDistance=(candidate-source).sqrMagnitude;
        float bestDistance=(currentBest-source).sqrMagnitude;
        return candidateDistance<bestDistance-0.0001f||
               Mathf.Abs(candidateDistance-bestDistance)<=0.0001f&&
               candidateId<currentBestId;
    }

    private float TargetScore(Unit source,Unit candidate)
    {
        if(source==null||candidate==null||source.model==null||candidate.model==null)
            return 100000f;
        if(candidate.corruptUntargetable)return 100000f;
        PersonalityCombatPolicy policy=source.personalityPolicy??PersonalityCombatPolicy.Balanced();
        float distance=Vector3.Distance(Flat(source.model.transform.position),Flat(candidate.model.transform.position));
        float hpRatio=candidate.hp/Mathf.Max(1f,candidate.maxHp);
        float weakWeight=policy.weakTargetWeight;
        float strongWeight=policy.strongTargetWeight;
        float disabledBonus=policy.disabledTargetBonus;
        float clusterBonus=policy.clusterOpportunityBonus;
        if(policy.targetStyle==PersonalityTargetStyle.Eccentric)
        {
            weakWeight=source.eccentricCriterion==1?14f:0.5f;
            strongWeight=source.eccentricCriterion==2?8f:0f;
            disabledBonus=source.eccentricCriterion==3?12f:0f;
            clusterBonus=source.eccentricCriterion==3?5f:0f;
        }
        float score=distance*policy.distanceWeight+hpRatio*weakWeight;
        score+=FrontlineAggroScore(
            candidate.initialTile.x,candidate.team==Team.Player,ActiveColumns);
        score-=candidate.maxHp/Mathf.Max(1f,source.maxHp)*strongWeight;
        score-=((int)candidate.expeditionRank-1)*strongWeight*0.8f;
        if(candidate==source.personalityRevengeTarget||
           candidate==source.recentAttacker&&source.threatTimer>0f)
            score-=policy.retaliationBonus;
        if(candidate==source.target)score-=policy.targetPersistenceBonus;
        int alliedFocus=units.Count(other=>other!=source&&IsCombatActive(other)&&
            other.team==source.team&&other.target==candidate);
        score+=FocusGroupScoreAdjustment(alliedFocus,policy.focusFireBonus);
        if(alliedFocus==0)score-=policy.unfocusedTargetBonus;
        int cluster=units.Count(other=>IsCombatActive(other)&&other.team!=source.team&&
            Vector3.Distance(Flat(other.model.transform.position),
                Flat(candidate.model.transform.position))<=TileSize*1.15f);
        score-=Mathf.Max(0,cluster-1)*clusterBonus;
        bool disabled=candidate.combatStatuses.Has(CombatStatusKind.StickySilk)||
                      candidate.combatStatuses.Has(CombatStatusKind.Poison)||
                      candidate.combatStatuses.Has(CombatStatusKind.Root)||
                      candidate.combatStatuses.Has(CombatStatusKind.Freeze)||
                      candidate.combatStatuses.Has(CombatStatusKind.Knockdown)||
                      candidate.itemDefenseShredTimer>0f;
        if(disabled)score-=disabledBonus;
        if(IsCombatActive(candidate.target)&&candidate.target.team==source.team&&
           candidate.target!=source)
        {
            float allyHpRatio=candidate.target.hp/Mathf.Max(1f,candidate.target.maxHp);
            score-=(1f-allyHpRatio)*policy.protectAllyBonus;
        }
        return score;
    }

    private void HandlePersonalityDamageReaction(
        Unit attacker,Unit damaged,float applied,float accumulatedDamage)
    {
        if(applied<=0f||!IsCombatActive(attacker)||!IsCombatActive(damaged)||
           attacker.team==damaged.team)return;

        PersonalityCombatPolicy damagedPolicy=
            damaged.personalityPolicy??PersonalityCombatPolicy.Balanced();
        bool canChooseTarget=CanQueuePersonalityReaction(damaged);
        if(canChooseTarget&&damaged.target!=attacker&&
           string.Equals(damagedPolicy.personalityId,"vengeful",
               StringComparison.OrdinalIgnoreCase)&&
           PersonalityCombatPolicy.ShouldVengefulRetarget(
               applied,accumulatedDamage,damaged.maxHp,
               damaged.personalityReconsiderTimer<=0f)&&
           IsLocalPersonalityTarget(damaged,attacker))
        {
            QueuePersonalityTarget(damaged,attacker);
        }

        if(!PersonalityCombatPolicy.ShouldProtectiveIntercept(
               damaged.hp,damaged.maxHp,true))return;
        Unit protector=null;
        Vector3 damagedPosition=Flat(damaged.model.transform.position);
        for(int i=0;i<units.Count;i++)
        {
            Unit candidate=units[i];
            if(candidate==damaged||!IsCombatActive(candidate)||
               candidate.team!=damaged.team||!CanQueuePersonalityReaction(candidate)||
               candidate.personalityPendingTarget!=null&&candidate.personalityPendingTimer>0f||
               candidate.personalityPolicy==null||
               !string.Equals(candidate.personalityPolicy.personalityId,"protective",
                   StringComparison.OrdinalIgnoreCase)||
               Vector3.Distance(damagedPosition,
                   Flat(candidate.model.transform.position))>TileSize*4f||
               !IsNearbyPersonalityAlternative(candidate,attacker)||
               candidate.target==attacker&&!TryFindPersonalityAttackPosition(candidate,attacker,damaged,out _))continue;
            if(protector!=null&&!IsPreferredNearestTarget(
                   damagedPosition,candidate.model.transform.position,candidate.id,
                   protector.model.transform.position,protector.id))continue;
            protector=candidate;
        }
        if(protector==null)return;
        QueuePersonalityTarget(protector,attacker,damaged);
    }

    private void TryRotateFickleTarget(Unit source,Unit struckTarget)
    {
        if(!IsCombatActive(source)||source.personalityPolicy==null||
           !string.Equals(source.personalityPolicy.personalityId,"fickle",
               StringComparison.OrdinalIgnoreCase)||
           !source.personalityPolicy.ShouldRotateAfterBasicAttack(
               source.basicAttackCount)||
           source.personalityLastRotationAttack==source.basicAttackCount)return;
        source.personalityLastRotationAttack=source.basicAttackCount;
        if(!CanQueuePersonalityReaction(source))return;

        Unit next=null;
        for(int i=0;i<units.Count;i++)
        {
            Unit candidate=units[i];
            if(candidate==struckTarget||!IsCombatTargetable(candidate)||
               candidate.team==source.team||
               !IsNearbyPersonalityAlternative(source,candidate))continue;
            if(next!=null&&!IsPreferredNearestTarget(
                   source.model.transform.position,candidate.model.transform.position,
                   candidate.id,next.model.transform.position,next.id))continue;
            next=candidate;
        }
        if(next!=null)QueuePersonalityTarget(source,next);
    }

    private void Attack(Unit source,Unit target)
    {
        if(battleEnding)return;
        if(MantisOffenseSuspended(source))return;
        if(source.combatStatuses.Has(CombatStatusKind.Fear)||SpiderSilkBound(source)||source.bearAvatarRoarPending)return;
        if(source.silkPuppet){AttackSilkPuppet(source,target);return;}
        RotateUnit(
            source,
            target.model.transform.position-source.model.transform.position,
            1f);
        source.basicAttackCount++;
        if(CombatReadabilityPresentation.Adjusted)source.readabilityBiteEffect=null;
        int readabilityAttackStyle=ReadabilityBasicAttackStyle(source);
        if(!IsRangedUnit(source)&&!ReadabilityUsesMeleeSwing(readabilityAttackStyle))
            PlayCombatSound(source,CombatSoundCue.Attack,source.model.transform.position);
        if(source.growthPursuitTarget==target)source.growthPursuitHits++;
        else{source.growthPursuitTarget=target;source.growthPursuitHits=0;}
        if(IsRangedUnit(source))source.rangedAttacksSinceRetreat++;
        ApplyBasicAttackBuildUp(source);
        float currentAttackInterval=CurrentAttackInterval(source);
        bool burstReload=MonsterTraitRuntime.Has(source.activeTraitIds,"trait_burst_reload");
        if(burstReload)
            currentAttackInterval*=source.basicAttackCount%3==0?1.5f:0.25f;
        float spriteAttackPlaybackSpeed=
            SpriteBasicAttackPlaybackSpeed(source,currentAttackInterval);
        float spriteAttackDuration=source.spriteAnimation!=null
            ?source.spriteAnimation.BasicAttackDuration/
             spriteAttackPlaybackSpeed
            :0f;
        source.attackMovementLockTimer=Mathf.Max(source.attackMovementLockTimer,
            Mathf.Max(
                Mathf.Min(0.5f,Mathf.Max(0.2f,currentAttackInterval*0.7f)),
                spriteAttackDuration));
        if(RagingHundredStrikesActive(source))
        {
            float firstHitTime=source.spriteAnimation==null?0f:
                source.spriteAnimation.BasicAttackHitTime/
                Mathf.Max(0.01f,spriteAttackPlaybackSpeed);
            source.attackMovementLockTimer=Mathf.Max(
                source.attackMovementLockTimer,
                firstHitTime+BearCombatRules.RagingThirdHitTime+BearCombatRules.RagingRecoveryDuration);
        }
        if(skillExecutor==null)ConfigureSkillExecutor();
        bool modified=skillExecutor.TryExecute(source.skillId,MonsterSkillTrigger.BasicAttackPrepare,
            new SkillExecutionContext{source=source,target=target,attackInterval=currentAttackInterval});
        if(!modified)source.cooldown=currentAttackInterval;
        float attackDamage=source.damage*(1f+source.itemAttackDamageRamp+
            ConsumeBasicAttackBonus(source));
        bool apexBite=RaptorApexPredatorActive(source);
        if(apexBite)
            attackDamage*=1f+ExpeditionAugmentRuntime.TranscendenceParam(
                "raptor_apex_basic_damage_bonus",
                RaptorCombatRules.ApexPredatorBasicDamageBonus);
        bool ninjaOpening=source.ninjaOpeningStrikeReady;
        if(!ninjaOpening&&source.ninjaEmpoweredBasicAttacks>0)
        {
            attackDamage=NinjaCatCombatRules.EmpoweredBasicDamage(attackDamage,true);
            source.ninjaEmpoweredBasicAttacks--;
        }
        bool wolfChasing=source.wolfChaseTimer>0f&&target==source.wolfChaseTarget;
        attackDamage=WolfCombatRules.ChaseBasicDamage(
            attackDamage,wolfChasing,source.wolfChaseEnhanced);
        if(wolfChasing)EmitWolfChaseTrail(source);
        if(burstReload)attackDamage*=0.55f;
        float criticalChance=source.itemModifiers.criticalChance;
        bool critical=source.counterGuaranteedCritical||UnityEngine.Random.value<
            CombatStatFormula.CriticalChance(criticalChance);
        source.lastBasicAttackCritical=critical;
        source.counterGuaranteedCritical=false;
        if(critical)
            attackDamage*=CombatStatFormula.CriticalDamageMultiplier(
                criticalChance,source.itemModifiers.criticalDamageBonus);
        if(ninjaOpening)
        {
            BeginNinjaOpeningAttack(source,target,attackDamage,critical,spriteAttackPlaybackSpeed);
            return;
        }
        if(RagingHundredStrikesActive(source))
        {
            int generation=combatGeneration;
            float comboDamage=attackDamage;
            Unit comboTarget=target;
            if(source.spriteAnimation!=null)
                source.spriteAnimation.PlayBearRagingAttack(spriteAttackPlaybackSpeed,strike=>
                {
                    comboTarget=ResolveBearRagingStrike(source,comboTarget,comboDamage,critical,strike,generation);
                    return comboTarget!=null;
                });
            else StartCombatCoroutine(source,PlayBearRagingHundredStrikes(source,target,comboDamage,critical,generation));
            return;
        }
        if(source.rank3MantisReaper)
        {
            StartMantisReaperBasic(source,target,attackDamage,critical,spriteAttackPlaybackSpeed);
            return;
        }
        if(BeetleSweepActive(source))
        {
            BeginBeetleSweepAttack(source,target,attackDamage,critical,spriteAttackPlaybackSpeed);
            return;
        }
        if(source.spriteAnimation!=null)
        {
            int generation=combatGeneration;
            float delayedDamage=attackDamage;
            if(IsRaptorFamily(source)||IsWolfFamily(source)||
               IsHaetaeFamily(source))
                StartCombatCoroutine(source,PlayRaptorBiteEffect(
                    source,
                    target,
                    spriteAttackPlaybackSpeed,
                    generation,apexBite));
            else if(IsSabertoothFamily(source))
                StartCombatCoroutine(source,PlaySabertoothClawEffect(
                    source,
                    target,
                    spriteAttackPlaybackSpeed,
                    generation));
            else if(IsCrocodileFamily(source))
                StartCombatCoroutine(source,PlayCrocodileTailStrikeEffect(
                    source,
                    target,
                    spriteAttackPlaybackSpeed,
                    generation));
            else if(IsKingKongFamily(source))
                StartCombatCoroutine(source,PlayKingKongHeavyPunchEffect(
                    source,
                    target,
                    spriteAttackPlaybackSpeed,
                    generation));
            else if(IsBearFamily(source)&&!RagingHundredStrikesActive(source))
                StartCombatCoroutine(source,PlayBearPawSwipeEffect(
                    source,target,spriteAttackPlaybackSpeed,generation));
            else if(IsNinjaCatFamily(source))
                StartCombatCoroutine(source,PlayNinjaKunaiSlashEffect(
                    source,target,spriteAttackPlaybackSpeed,generation));
            else if(IsTyrannoFamily(source))
                StartCombatCoroutine(source,PlayTyrannoKingJawBiteEffect(
                    source,target,spriteAttackPlaybackSpeed,generation));
            else if(IsMantisFamily(source))
                StartCombatCoroutine(source,PlayMantisScytheSlashEffect(
                    source,target,spriteAttackPlaybackSpeed,generation));
            else if(IsMammothFamily(source))
                StartCombatCoroutine(source,PlayMammothTuskRamEffect(
                    source,target,spriteAttackPlaybackSpeed,generation));
            else if(IsBeetleFamily(source))
                StartCombatCoroutine(source,PlayBeetleHornAttackEffect(
                    source,target,spriteAttackPlaybackSpeed,generation,true));
            else if(IsGriffinFamily(source)&&!GriffinRoyalReady(source))
                StartCombatCoroutine(source,PlayGriffinEagleClawEffect(
                    source,target,spriteAttackPlaybackSpeed,generation));
            source.spriteAnimation.PlayBasicAttack(
                spriteAttackPlaybackSpeed,
                ()=>
                {
                    if(generation!=combatGeneration||
                       !IsCombatActive(source)||
                       !IsCombatActive(target))
                        return;
                    BeginBasicAttackImpact(
                        source,
                        target,
                        delayedDamage,
                        critical,
                        spriteAttackPlaybackSpeed);
                });
            TrackReadabilityMeleeAttack(source,target);
            PrepareGriffinRoyalWing(source,spriteAttackPlaybackSpeed);
            PrepareWyvernBolt(source,target);
            if(source.wolfEclipseTimer>0f&&source.spriteAnimation.CurrentMotionName=="Attack")
            {
                var renderer=target.spriteAnimation==null?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
                source.wolfEclipseLeft?.StrikeCompanion(renderer,
                    WolfCombatRules.EclipseHitDelay,spriteAttackPlaybackSpeed);
                source.wolfEclipseRight?.StrikeCompanion(renderer,
                    WolfCombatRules.EclipseHitDelay*2f,spriteAttackPlaybackSpeed);
            }
            return;
        }
        BeginBasicAttackImpact(source,target,attackDamage,critical);
    }

    private IEnumerator PlayRaptorBiteEffect(
        Unit source,
        Unit target,
        float playbackSpeed,
        int generation,bool apex)
    {
        int attackSequence=source.basicAttackCount;
        float hitTime=source.spriteAnimation.BasicAttackHitTime/
                      Mathf.Max(0.01f,playbackSpeed);
        float delay=PixelCombatEffect.RaptorBiteLeadTime(hitTime,playbackSpeed,apex);
        if(delay>0f)yield return new WaitForSeconds(delay);
        if(generation!=combatGeneration||
           !IsCombatActive(source)||
           !IsCombatActive(target))
            yield break;
        if(CombatReadabilityPresentation.Adjusted&&delay>0f&&
           (source.basicAttackCount!=attackSequence||!source.spriteAnimation.HasPendingBasicAttackHit))yield break;
        SpriteRenderer targetRenderer=target.spriteAnimation==null
            ?null
            :target.spriteAnimation.GetComponent<SpriteRenderer>();
        var effect=PixelCombatEffect.PlayRaptorBite(
            target.spriteAnimation==null
                ?target.model.transform
                :target.spriteAnimation.transform,
            targetRenderer,
            playbackSpeed,apex);
        if(CombatReadabilityPresentation.Adjusted&&!apex)
        {
            source.readabilityBiteEffect=effect;
            source.readabilityBiteVersion=effect==null?0:effect.ReadabilityBiteVersion;
        }
    }

