    private IEnumerator PlayBearPawSwipeEffect(
        Unit source,Unit target,float playbackSpeed,int generation)
    {
        int revision=source.positionRevision;
        float hitTime=source.spriteAnimation.BasicAttackHitTime/
                      Mathf.Max(0.01f,playbackSpeed);
        float delay=PixelCombatEffect.BearPawSwipeLeadTime(hitTime,playbackSpeed);
        if(delay>0f)yield return new WaitForSeconds(delay);
        if(generation!=combatGeneration||!IsCombatActive(source)||
           !IsCombatActive(target))yield break;
        SpriteRenderer sourceRenderer=source.spriteAnimation.GetComponent<SpriteRenderer>();
        SpriteRenderer targetRenderer=target.spriteAnimation==null
            ?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
        if(source.bearResolveTimer>0f&&source.positionRevision==revision&&
           source.spriteAnimation.CurrentMotionName=="Attack")
            PlayBearSound(source,BearSound.Swipe,source.model.transform.position);
        if(source.bearResolveTimer>0f&&!MountainColossusActive(source))source.bearSpiritFx?.PlayAttackEcho();
        if(MountainColossusActive(source))
        {
            PixelCombatEffect.PlayBearMountainCrescent(sourceRenderer,
                targetRenderer!=null?targetRenderer.bounds.center:target.model.transform.position,
                playbackSpeed);
            yield break;
        }
        PixelCombatEffect.PlayBearPawSwipe(
            target.spriteAnimation==null
                ?target.model.transform:target.spriteAnimation.transform,
            targetRenderer,playbackSpeed,sourceRenderer!=null&&sourceRenderer.flipX,
            source.bearResolveTimer>0f);
    }

    private IEnumerator PlayBearRagingHundredStrikes(
        Unit source,Unit target,float attackDamage,bool critical,int generation)
    {
        // Non-sprite fallback uses the same contacts and target/proc rules.
        for(int strike=0;strike<BearCombatRules.RagingStrikeCount;strike++)
        {
            if(strike>0)
                yield return new WaitForSeconds(strike==1?BearCombatRules.RagingSecondHitTime:
                    BearCombatRules.RagingThirdHitTime-BearCombatRules.RagingSecondHitTime);
            target=ResolveBearRagingStrike(source,target,attackDamage,critical,strike,generation);
            if(target==null)yield break;
        }
    }

    private Unit ResolveBearRagingStrike(
        Unit source,Unit target,float attackDamage,bool critical,int strikeIndex,int generation)
    {
        if(generation!=combatGeneration||!IsCombatActive(source)||source.giraffeStunTimer>0f||
           source.combatStatuses.Has(CombatStatusKind.Freeze)||
           source.combatStatuses.Has(CombatStatusKind.Fear)||source.displacing)return null;
        if(!IsCombatTargetable(target))
        {
            target=null;
            foreach(Unit candidate in units)
            {
                if(candidate.team==source.team||!IsCombatTargetable(candidate)||candidate.crocodilePreyFlying||
                   Vector3.Distance(Flat(source.model.transform.position),Flat(candidate.model.transform.position))>
                       AttackDistance(source,candidate)||!HasClearAttackLine(source,candidate))continue;
                if(target==null||IsPreferredNearestTarget(source.model.transform.position,
                       candidate.model.transform.position,candidate.id,target.model.transform.position,target.id))
                    target=candidate;
            }
            if(target==null)return null;
            SetTarget(source,target);
        }
        if(Vector3.Distance(Flat(source.model.transform.position),Flat(target.model.transform.position))>
           AttackDistance(source,target)||!HasClearAttackLine(source,target))return null;
        StopUnitMovement(source);
        Vector3 impactCenter=Flat(target.model.transform.position);
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?source.model.GetComponentInChildren<SpriteRenderer>()
            :source.spriteAnimation.GetComponent<SpriteRenderer>();
        SpriteRenderer targetRenderer=target.spriteAnimation==null
            ?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
        Transform impactAnchor=target.spriteAnimation==null
            ?target.model.transform:target.spriteAnimation.transform;
        if(sourceRenderer!=null)
        {
            Camera camera=Camera.main;
            Vector3 right=camera!=null?camera.transform.right:Vector3.right;
            sourceRenderer.flipX=Vector3.Dot(target.model.transform.position-source.model.transform.position,right)<0f;
        }
        source.bearSpiritFx?.PlayAttackEcho(strikeIndex,
            targetRenderer!=null?targetRenderer.bounds.center:impactAnchor.position);
        PixelCombatEffect.PlayBearRagingStrike(
            impactAnchor,targetRenderer,strikeIndex,sourceRenderer!=null&&sourceRenderer.flipX);
        target.reaction?.PlayTintHit(strikeIndex==2?new Color(1f,.95f,.7f):new Color(1f,.72f,.18f));
        PlayBearSound(source,strikeIndex==BearCombatRules.RagingStrikeCount-1
            ?BearSound.Finisher:BearSound.Strike,impactCenter,critical?1.15f:1f);
        bool attackScaling=UsesAttackSkillScaling(source);
        float damage=attackScaling?BearCombatRules.RagingStrikeDamage(attackDamage,strikeIndex):
            SpeciesSkillScaling.RagingBasicShare(attackDamage,strikeIndex);
        float added=attackScaling?0f:SpeciesSkillScaling.RagingSkillShare(SkillPower(source),strikeIndex);
        if(strikeIndex==0)
        {
            source.skillTimer=CombatStatFormula.CooldownAfterBasicAttack(source.skillTimer,source.skillCooldownDuration);
            if(critical)ApplyCriticalItemEffects(source,target);
            ResolveBasicAttackImpact(source,target,damage);
            source.traitActivations++;
        }
        else ApplyDamageComponents(source,target,damage,false,true,false,true,0f,0f,1f,false,false,false,added);
        if(strikeIndex==BearCombatRules.RagingStrikeCount-1&&IsCombatActive(source))
        {
            ApplyBearBasicCleave(source,target,impactCenter,true);
            if(IsCombatActive(target)&&!target.combatStatuses.ControlImmune)
            {
                target.giraffeStunTimer=Mathf.Max(target.giraffeStunTimer,
                    HostileStatusDuration(target,BearCombatRules.RagingFinisherStaggerDuration));
                InterruptPositionalAction(target);
                target.spriteAnimation?.InterruptCurrentAction();
                StopUnitMovement(target);
            }
        }
        // Apply recoil after stagger interruption, which restores the previous action's visual offsets.
        target.spriteAnimation?.PlayImpactRecoil(target.model.transform.position-source.model.transform.position,
            strikeIndex==2?.14f:.045f);
        return target;
    }

