    private IEnumerator PlayBeetleHornAttackEffect(
        Unit source,Unit target,float playbackSpeed,int generation,bool basicAttack)
    {
        float hitTime=(basicAttack?source.spriteAnimation.BasicAttackHitTime:
            source.spriteAnimation.SkillAttackHitTime)/Mathf.Max(0.01f,playbackSpeed);
        float delay=basicAttack
            ?PixelCombatEffect.BeetleHornThrustLeadTime(hitTime,playbackSpeed)
            :PixelCombatEffect.BeetleHornUppercutLeadTime(hitTime,playbackSpeed);
        if(delay>0f)yield return new WaitForSeconds(delay);
        if(generation!=combatGeneration||!IsCombatActive(source)||
           !IsCombatActive(target))yield break;
        SpriteRenderer sourceRenderer=source.spriteAnimation.GetComponent<SpriteRenderer>();
        SpriteRenderer targetRenderer=target.spriteAnimation==null
            ?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
        Transform targetAnchor=target.spriteAnimation==null
            ?target.model.transform:target.spriteAnimation.transform;
        bool flipX=sourceRenderer!=null&&sourceRenderer.flipX;
        if(basicAttack)
            PixelCombatEffect.PlayBeetleHornThrust(
                targetAnchor,targetRenderer,playbackSpeed,flipX);
        else
            PixelCombatEffect.PlayBeetleHornUppercut(
                targetAnchor,targetRenderer,playbackSpeed,flipX,1.2f);
        if(!basicAttack)yield break;
        yield return new WaitForSeconds(
            PixelCombatEffect.BeetleHornThrustImpactFrame/
            (PixelCombatEffect.BeetleHornThrustFramesPerSecond*
             Mathf.Max(0.01f,playbackSpeed)));
        if(generation==combatGeneration&&targetAnchor!=null)
            PixelCombatEffect.PlayBeetleHornImpact(targetAnchor,targetRenderer);
    }

    private IEnumerator PlayGriffinEagleClawEffect(
        Unit source,Unit target,float playbackSpeed,int generation)
    {
        float hitTime=source.spriteAnimation.BasicAttackHitTime/
                      Mathf.Max(0.01f,playbackSpeed);
        float delay=PixelCombatEffect.GriffinEagleClawLeadTime(
            hitTime,playbackSpeed);
        if(delay>0f)yield return new WaitForSeconds(delay);
        if(generation!=combatGeneration||!IsCombatActive(source)||
           !IsCombatActive(target))yield break;
        SpriteRenderer sourceRenderer=source.spriteAnimation.GetComponent<SpriteRenderer>();
        SpriteRenderer targetRenderer=target.spriteAnimation==null
            ?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
        Transform targetAnchor=target.spriteAnimation==null
            ?target.model.transform:target.spriteAnimation.transform;
        PixelCombatEffect.PlayGriffinEagleClaw(
            targetAnchor,targetRenderer,playbackSpeed,
            sourceRenderer!=null&&sourceRenderer.flipX);
        yield return new WaitForSeconds(
            PixelCombatEffect.GriffinEagleClawImpactFrame/
            (PixelCombatEffect.GriffinEagleClawFramesPerSecond*
             Mathf.Max(0.01f,playbackSpeed)));
        if(generation==combatGeneration&&targetAnchor!=null)
            PixelCombatEffect.PlayGriffinFeatherImpact(targetAnchor,targetRenderer);
    }


    private void BeginBasicAttackImpact(
        Unit source,
        Unit target,
        float attackDamage,
        bool critical,
        float playbackSpeed=1f)
    {
        if(!IsCombatActive(source)||!IsCombatActive(target)||SpiderSilkBound(source))return;
        if(UsesHiddenHexCombat&&BasicAttackHexRange(source.attackRange)<3&&
           !IsImmediatelyAttackable(source,target))return;
        if(IsRangedUnit(source))
            PlayCombatSound(source,CombatSoundCue.Attack,source.model.transform.position);
        source.skillTimer=CombatStatFormula.CooldownAfterBasicAttack(
            source.skillTimer,source.skillCooldownDuration);
        if(critical&&!IsWyvernFamily(source))ApplyCriticalItemEffects(source,target);
        if(source.tongueWhip!=null)
        {
            float delayedDamage=attackDamage;
            PlayReadabilityLaunch(source,target);
            source.tongueWhip.Play(
                target.spriteAnimation==null
                    ?target.model.transform:target.spriteAnimation.transform,
                ()=>ResolveBasicAttackImpact(source,target,delayedDamage),
                false,
                playbackSpeed);
            return;
        }
        if(source.neckStrike!=null)
        {
            if(source.highHeadSlam!=null)source.highHeadSlam.CancelAndRestore();
            source.giraffeSlamming=false;
            float delayedDamage=attackDamage;
            source.neckStrike.Play(target.model.transform,
                (start,end)=>ResolveGiraffeBasicAttackImpact(
                    source,target,delayedDamage,start,end));
            return;
        }
        if(IsSpiderFamily(source))
        {
            StartCombatCoroutine(source,PlaySpiderSilkBasicAttack(
                source,target,attackDamage,combatGeneration));
            return;
        }
        if(IsMonkeyFamily(source))
        {
            int generation=combatGeneration;
            bool impactCritical=critical;
            PixelStarProjectile projectile=EmitMonkeyStone(
                source,target,
                ()=>
                {
                    if(generation!=combatGeneration||
                       !IsCombatActive(target))return;
                    bool latestCritical=source.lastBasicAttackCritical;
                    source.lastBasicAttackCritical=impactCritical;
                    ResolveBasicAttackImpact(source,target,attackDamage);
                    source.lastBasicAttackCritical=latestCritical;
                });
            projectile?.UseReadabilityBodyAnchors(Rank3Renderer(source));
            if(projectile!=null){PlayReadabilityLaunch(source,target);return;}
        }
        if(IsWizardMouseFamily(source))
        {
            int generation=combatGeneration;
            bool impactCritical=critical;
            PixelStarProjectile projectile=EmitMagicStar(
                source,target,new Color(0.72f,0.48f,1f),critical,
                ()=>
                {
                    if(generation!=combatGeneration||
                       !IsCombatActive(target))return;
                    bool latestCritical=source.lastBasicAttackCritical;
                    source.lastBasicAttackCritical=impactCritical;
                    ResolveBasicAttackImpact(source,target,attackDamage);
                    source.lastBasicAttackCritical=latestCritical;
                });
            projectile?.UseReadabilityBodyAnchors(Rank3Renderer(source));
            if(projectile!=null)PlayReadabilityLaunch(source,target);
            if(projectile!=null)return;
        }
        if(IsMushroomFamily(source))
        {
            int generation=combatGeneration;
            bool impactCritical=critical;
            PixelStarProjectile projectile=EmitMushroomSpore(
                source,target,
                () =>
                {
                    if(generation!=combatGeneration||
                       !IsCombatActive(target))return;
                    bool latestCritical=source.lastBasicAttackCritical;
                    source.lastBasicAttackCritical=impactCritical;
                    ResolveBasicAttackImpact(source,target,attackDamage);
                    source.lastBasicAttackCritical=latestCritical;
                });
            projectile?.UseReadabilityBodyAnchors(Rank3Renderer(source));
            if(projectile!=null){PlayReadabilityLaunch(source,target);return;}
        }
        if(IsSpiritDeerFamily(source))
        {
            int generation=combatGeneration;
            bool impactCritical=critical;
            PixelStarProjectile projectile=EmitSpiritLight(
                source,target,
                () =>
                {
                    if(generation!=combatGeneration||
                       !IsCombatActive(target))return;
                    bool latestCritical=source.lastBasicAttackCritical;
                    source.lastBasicAttackCritical=impactCritical;
                    ResolveBasicAttackImpact(source,target,attackDamage);
                    source.lastBasicAttackCritical=latestCritical;
                });
            projectile?.UseReadabilityBodyAnchors(Rank3Renderer(source));
            if(projectile!=null){PlayReadabilityLaunch(source,target);return;}
        }
        if(IsWyvernFamily(source))
        {
            BeginWyvernBolt(source,target,attackDamage,critical);
            return;
        }
        ResolveBasicAttackImpact(source,target,attackDamage);
    }

    private static float SpriteBasicAttackPlaybackSpeed(
        Unit source,
        float currentAttackInterval)
    {
        if(source==null)return 1f;
        float authoredInterval=source.definition!=null
            ?source.definition.attackInterval
            :source.attackInterval;
        return Mathf.Clamp(
            Mathf.Max(0.05f,authoredInterval)/
            Mathf.Max(0.05f,currentAttackInterval),
            0.25f*CombatStatFormula.CombatAttackRate,
            4f*CombatStatFormula.CombatAttackRate);
    }

    private IEnumerator PlaySpiderSilkBasicAttack(
        Unit source,Unit target,float attackDamage,int generation)
    {
        if(!IsCombatActive(source)||!IsCombatActive(target))yield break;
        SpriteRenderer sourceRenderer=source.spriteAnimation==null
            ?null:source.spriteAnimation.GetComponent<SpriteRenderer>();
        SpriteRenderer targetRenderer=target.spriteAnimation==null
            ?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
        bool impactCritical=source.lastBasicAttackCritical;
        Transform sourceAnchor=source.spriteAnimation==null
            ?source.model.transform:source.spriteAnimation.transform;
        Transform targetAnchor=target.spriteAnimation==null
            ?target.model.transform:target.spriteAnimation.transform;
        PixelStarProjectile projectile=PixelStarProjectile.PlaySilkNeedle(
            sourceAnchor,sourceRenderer,targetAnchor,targetRenderer,
            new Color(0.72f,0.96f,1f),impactCritical,
            () =>
            {
                if(!ReleasedSkillValid(source,generation)||!IsCombatActive(target))return;
                bool latestCritical=source.lastBasicAttackCritical;
                source.lastBasicAttackCritical=impactCritical;
                ResolveBasicAttackImpact(source,target,attackDamage);
                source.lastBasicAttackCritical=latestCritical;
            });
        if(projectile!=null){PlayReadabilityLaunch(source,target);yield break;}
        yield return new WaitForSeconds(0.16f);
        if(ReleasedSkillValid(source,generation)&&IsCombatActive(target))
            ResolveBasicAttackImpact(source,target,attackDamage);
    }

