    private void ResolveGiraffeBasicAttackImpact(
        Unit source,Unit target,float attackDamage,Vector3 start,Vector3 end)
    {
        ResolveBasicAttackImpact(source,target,attackDamage);
        Vector3 flatStart=Flat(start),flatEnd=Flat(end);
        Vector3 segment=flatEnd-flatStart;
        float lengthSquared=segment.sqrMagnitude;
        if(lengthSquared<0.001f)return;
        for(int i=0;i<units.Count;i++)
        {
            Unit candidate=units[i];
            if(candidate==target||candidate.team==source.team||!IsCombatActive(candidate))continue;
            Vector3 point=Flat(candidate.model.transform.position);
            float t=Mathf.Clamp01(Vector3.Dot(point-flatStart,segment)/lengthSquared);
            if(t<=0.02f||t>=0.98f)continue;
            Vector3 closest=flatStart+segment*t;
            float hitRadius=candidate.collisionRadius+0.32f;
            if((point-closest).sqrMagnitude>hitRadius*hitRadius)continue;
            ApplyDamage(source,candidate,attackDamage*0.35f,false,false);
        }
    }

    private static void ConsumeRangedRetreatDistance(Unit unit,float movedDistance)
    {
        if(!unit.rangedRetreating||movedDistance<=0f)return;
        unit.rangedRetreatDistanceRemaining-=movedDistance;
        if(unit.rangedRetreatDistanceRemaining<=0f)CompleteRangedRetreat(unit);
    }

    private static void CompleteRangedRetreat(Unit unit)
    {
        unit.rangedRetreating=false;
        unit.rangedRetreatDistanceRemaining=0f;
        unit.rangedAttacksSinceRetreat=0;
    }

    private void ResolveBasicAttackImpact(Unit source,Unit target,float attackDamage)
    {
        if(source.combatStatuses.Has(CombatStatusKind.Fear)&&!IsRangedUnit(source))return;
        if(CombatReadabilityPresentation.Adjusted)
        {
            source.readabilityBiteEffect?.AlignReadabilityBiteContact(source.readabilityBiteVersion);
            source.readabilityBiteEffect=null;
        }
        if(source.silkPuppet)
        {
            if(IsCombatActive(source)&&source.hp>0f)
                ApplyDamage(source,target,attackDamage,false,true,false);
            return;
        }
        if(source.lastBasicAttackCritical&&target!=null)
        {
            SpriteRenderer targetRenderer=target.spriteAnimation==null
                ?null
                :target.spriteAnimation.GetComponent<SpriteRenderer>();
            PixelCombatEffect.PlayCritical(
                target.spriteAnimation==null
                    ?target.model.transform
                    :target.spriteAnimation.transform,
                targetRenderer);
        }
        if(RaptorApexPredatorActive(source)&&IsCombatActive(target))
        {
            target.spriteAnimation?.PlayImpactRecoil(
                target.model.transform.position-source.model.transform.position,0.16f);
            float previousCooldown=source.skillTimer;
            source.skillTimer=Mathf.Max(0f,source.skillTimer-
                ExpeditionAugmentRuntime.TranscendenceParam(
                    "raptor_apex_cooldown_reduction",
                    RaptorCombatRules.ApexPredatorCooldownReduction));
            if(source.skillTimer<previousCooldown)source.raptorApexCooldownFlash=0.18f;
            source.traitActivations++;
        }
        HandleFamilyTranscendenceBasicAttack(source,target,attackDamage);
        if(ResolveRank3BasicAttack(source,target,attackDamage))
        {
            return;
        }
        bool recentlyHitByAlly=target!=null&&target.recentAttacker!=null&&
            target.recentAttacker!=source&&target.recentAttacker.team==source.team&&target.threatTimer>0f;
        BasicAttackTraitResult traitResult=MonsterTraitRuntime.ResolveBasicAttack(
            source.activeTraitIds,source.traitState,target==null?"":target.stableId,
            IsRangedUnit(source),recentlyHitByAlly,source.damage,OffensiveMaxHealth(source),
            source.defense,source.statusResistance,target==null?0f:target.hp);
        Unit traitSplashTarget=traitResult.splashDamage>0f
            ?FindTraitSplashTarget(source,target,traitResult.piercingSplash):null;
        bool primaryWasAlive=IsCombatActive(target);
        float targetHpBefore=primaryWasAlive?target.hp:0f;
        if(MonsterTraitRuntime.Has(source.activeTraitIds,"trait_cross_hunt")&&target!=null)
            target.combatStatuses.ApplyTimed(CombatStatusKind.Marked,4f,source);
        bool fightingSpirit=source.bearResolveTimer>0f;
        bool mountainColossus=MountainColossusActive(source);
        float ironKumaDamage=fightingSpirit&&MonsterTraitRuntime.Has(
            source.activeTraitIds,BearCombatRules.IronKumaTraitId)
            ?BearCombatRules.IronKumaDamage(CurrentDefense(source)):0f;
        bool feeding=source.tyrannoFeedingReady;
        source.tyrannoFeedingReady=false;
        if(feeding)source.combatEffectIcons.Hide(CombatEffectIconKind.AttackUp);
        float finalPrimaryDamage=attackDamage*
                                 (mountainColossus
                                     ?BearCombatRules.MountainPrimaryDamageRatio:1f)*
                                 (1f+traitResult.bonusPrimaryDamage)+
                                 traitResult.bonusFlatDamage+ironKumaDamage;
        if(feeding)
            finalPrimaryDamage+=TyrannoCombatRules.FeedingBonusDamage(source.damage);
        float nonAttackDamage=0f;
        if(!UsesAttackSkillScaling(source))
        {
            finalPrimaryDamage=attackDamage*(1f+traitResult.bonusPrimaryDamage)+traitResult.bonusFlatDamage;
            nonAttackDamage=ironKumaDamage;
            if(mountainColossus)nonAttackDamage+=SkillPower(source)*
                (BearCombatRules.MountainPrimaryDamageRatio-1f)*(1f+traitResult.bonusPrimaryDamage);
            if(fightingSpirit)nonAttackDamage+=SkillPower(source)*BearCombatRules.ResolveAttackDamageBonus*BearResolveStrength(source);
            if(feeding)nonAttackDamage+=TyrannoCombatRules.FeedingBonusDamage(SkillPower(source));
        }
        if(mountainColossus&&primaryWasAlive)
            PlayBearSound(source,BearSound.MountainHit,target.model.transform.position,
                source.lastBasicAttackCritical?1.15f:1f);
        ApplyDamageComponents(source,target,finalPrimaryDamage,false,true,true,true,0f,0f,
            traitResult.barrierBreaker?2f:1f,false,false,false,nonAttackDamage);
        if(primaryWasAlive&&IsCombatTargetable(target)&&source.wolfEclipseTimer>0f)
            StartCombatCoroutine(source,ResolveWolfEclipseFollowup(source,target,combatGeneration));
        if(mountainColossus&&target!=null&&target.hp<targetHpBefore)
        {
            source.bearSpiritFx?.PlayAttackEcho();
            PlayBearMountainHit(source,target);
        }
        if(ironKumaDamage>0f)
        {
            target.reaction?.PlayTintHit(new Color(0.68f,0.86f,1f));
            PlayTraitBurst(target,new Color(0.48f,0.76f,1f),true);
            PlayTraitBurst(target,new Color(1f,0.98f,0.84f),true);
        }
        if(feeding)
        {
            target.reaction?.PlayTintHit(new Color(1f,0.22f,0.04f));
            PlayTraitBurst(target,new Color(1f,0.16f,0.02f),true);
            Heal(source,TyrannoCombatRules.FeedingHealing(source.maxHp));
            Transform healAnchor=source.spriteAnimation==null
                ?source.model.transform:source.spriteAnimation.transform;
            SpriteRenderer healRenderer=source.spriteAnimation==null
                ?source.model.GetComponentInChildren<SpriteRenderer>()
                :source.spriteAnimation.GetComponent<SpriteRenderer>();
            PixelCombatEffect.PlayHealingBurst(healAnchor,healRenderer);
            source.traitActivations++;
        }
        if(fightingSpirit)
        {
            ApplyBearFightingSpiritBasicAttack(source,target);
            if(ironKumaDamage>0f)source.traitActivations++;
        }
        if(IsCombatActive(target))TriggerBasicAttackTeamTraits(source,target);
        if(IsCombatActive(traitSplashTarget))
            ApplyDamage(source,traitSplashTarget,attackDamage*traitResult.splashDamage,false,false);
        if(traitResult.chainConduction)ApplyChainConduction(source,target,attackDamage);
        if(traitResult.targetSkillDelay>0f&&IsCombatActive(target))
            target.skillTimer+=traitResult.targetSkillDelay;
        if(traitResult.gravityKnot)ApplyGravityKnot(source,target);
        source.traitActivations+=traitResult.activations;
        if(traitResult.skillCooldownReduction>0f)
            source.skillTimer=Mathf.Max(0f,source.skillTimer-traitResult.skillCooldownReduction);
        if(primaryWasAlive&&!IsCombatActive(target))
        {
            if(traitResult.overkillTransfer)
                ApplyOverkillTransfer(source,target,Mathf.Max(0f,finalPrimaryDamage-targetHpBefore));
            MonsterTraitRuntime.RecordBasicAttackKill(source.activeTraitIds,source.traitState);
            ApplyCrossHuntExecution(source,target);
        }
        if(traitResult.switchTarget)SwitchCrossHuntTarget(source,target);
        if(skillExecutor==null)ConfigureSkillExecutor();
        skillExecutor.TryExecute(source.skillId,MonsterSkillTrigger.BasicAttackImpact,
            new SkillExecutionContext{source=source,target=target,attackDamage=attackDamage});
        HandleCorruptionBasicAttack(source,target,attackDamage);
    }

    private void ApplyBearFightingSpiritBasicAttack(Unit source,Unit primaryTarget)
    {
        if(MonsterTraitRuntime.Has(source.activeTraitIds,BearCombatRules.WoongiTraitId))
        {
            source.bearResolveTimer=Mathf.Min(
                source.bearResolveTimer+BearCombatRules.WoongiExtensionPerHit,
                source.bearResolveTotalDuration+BearCombatRules.WoongiMaximumExtension);
            Heal(source,BearCombatRules.WoongiHealing(source.maxHp));
            PlayTraitBurst(source,new Color(0.38f,1f,0.5f),false);
            source.traitActivations++;
        }
        if(MonsterTraitRuntime.Has(source.activeTraitIds,BearCombatRules.BerberTraitId))
        {
            int previousStacks=source.bearFrenzyStacks;
            source.bearFrenzyStacks=Mathf.Min(
                BearCombatRules.BerberMaximumStacks,source.bearFrenzyStacks+1);
            if(source.bearFrenzyStacks>previousStacks)
            {
                PlayTraitBurst(source,new Color(1f,0.12f,0.04f),
                    source.bearFrenzyStacks==BearCombatRules.BerberMaximumStacks);
            }
            source.traitActivations++;
        }
        if(primaryTarget==null||primaryTarget.model==null)return;
        // Species benefits belong to the action; Raging's splash belongs to its finisher.
        if(RagingHundredStrikesActive(source))return;
        if(MountainColossusActive(source))
        {
            Vector3 origin=Flat(source.model.transform.position);
            Vector3 forward=Flat(primaryTarget.model.transform.position)-origin;
            if(forward.sqrMagnitude<0.001f)forward=Flat(source.facingDirection);
            float ironDamage=MonsterTraitRuntime.Has(
                    source.activeTraitIds,BearCombatRules.IronKumaTraitId)
                ?BearCombatRules.IronKumaDamage(CurrentDefense(source)):0f;
            for(int i=0;i<units.Count;i++)
            {
                Unit enemy=units[i];
                if(enemy==primaryTarget||enemy.team==source.team||
                   !IsCombatActive(enemy))continue;
                Vector3 direction=Flat(enemy.model.transform.position)-origin;
                if(direction.magnitude>AttackDistance(source,enemy)||
                   !BearCombatRules.IsInsideMountainAttackArc(forward,direction))
                    continue;
                float applied=ApplyDamage(source,enemy,
                    SkillPower(source)*BearCombatRules.MountainSecondaryDamageRatio+
                    ironDamage,!UsesAttackSkillScaling(source),false,false);
                if(applied>0f)PlayBearMountainHit(source,enemy);
            }
            return;
        }
        Vector3 center=Flat(primaryTarget.model.transform.position);
        ApplyBearBasicCleave(source,primaryTarget,center);
    }

    private static void PlayBearMountainHit(Unit source,Unit target)
    {
        if(target==null||target.model==null)return;
        var renderer=target.spriteAnimation==null?null:target.spriteAnimation.GetComponent<SpriteRenderer>();
        PixelCombatEffect.PlayBearCleaveHit(target.spriteAnimation==null?
            target.model.transform:target.spriteAnimation.transform,renderer,true);
        target.reaction?.PlayTintHit(Color.white);
        target.spriteAnimation?.PlayImpactRecoil(target.model.transform.position-source.model.transform.position,.07f);
    }

    private void ApplyBearBasicCleave(
        Unit source,Unit primaryTarget,Vector3 center,bool pawImpact=false)
    {
        foreach(Unit enemy in units)
        {
            if(enemy==primaryTarget||enemy.team==source.team||!IsCombatActive(enemy)||
               Vector3.Distance(center,Flat(enemy.model.transform.position))>TileSize)
                continue;
            float applied=ApplyDamage(source,enemy,
                SkillPower(source)*BearCombatRules.BasicCleaveDamageRatio,
                !UsesAttackSkillScaling(source),false,false);
            if(applied<=0f)continue;
            SpriteRenderer renderer=enemy.spriteAnimation==null?null:enemy.spriteAnimation.GetComponent<SpriteRenderer>();
            Transform anchor=enemy.spriteAnimation==null?enemy.model.transform:enemy.spriteAnimation.transform;
            if(pawImpact)PixelCombatEffect.PlayBearRagingStrike(anchor,renderer,0,false);
            else PixelCombatEffect.PlayBearCleaveHit(anchor,renderer);
            enemy.reaction?.PlayTintHit(new Color(1f,.78f,.28f));
            enemy.spriteAnimation?.PlayImpactRecoil(enemy.model.transform.position-source.model.transform.position,.045f);
        }
    }


    private void ApplyChainConduction(Unit source,Unit primary,float attackDamage)
    {
        if(source==null||primary==null)return;
        List<Unit> targets=units.Where(enemy=>enemy!=primary&&IsCombatActive(enemy)&&
                enemy.team!=source.team)
            .OrderBy(enemy=>Vector3.Distance(Flat(primary.model.transform.position),
                Flat(enemy.model.transform.position))).Take(2).ToList();
        if(targets.Count>0)ApplyDamage(source,targets[0],attackDamage*0.55f,false,false);
        if(targets.Count>1)ApplyDamage(source,targets[1],attackDamage*0.3f,false,false);
        for(int i=0;i<targets.Count;i++)
            targets[i].combatStatuses.ApplyTimed(CombatStatusKind.Marked,3f,source);
    }

    private void ApplyOverkillTransfer(Unit source,Unit defeated,float overkill)
    {
        if(overkill<=0f||source==null||defeated==null)return;
        Unit next=units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=source.team)
            .OrderBy(enemy=>Vector3.Distance(Flat(defeated.model.transform.position),
                Flat(enemy.model.transform.position))).FirstOrDefault();
        if(next==null)return;
        float hpBefore=next.hp;
        ApplyDamage(source,next,overkill,false,false);
        if(!IsCombatActive(next)&&overkill>hpBefore)
        {
            Unit chained=units.Where(enemy=>IsCombatActive(enemy)&&enemy.team!=source.team)
                .OrderBy(enemy=>Vector3.Distance(Flat(next.model.transform.position),
                    Flat(enemy.model.transform.position))).FirstOrDefault();
            if(chained!=null)ApplyDamage(source,chained,overkill-hpBefore,false,false);
        }
    }

    private void ApplyGravityKnot(Unit source,Unit primary)
    {
        if(source==null||primary==null||primary.model==null)return;
        Vector3 center=Flat(primary.model.transform.position);
        for(int i=0;i<units.Count;i++)
        {
            Unit enemy=units[i];
            if(enemy==primary||!IsCombatActive(enemy)||enemy.team==source.team)continue;
            Vector3 delta=center-Flat(enemy.model.transform.position);
            if(delta.magnitude>TileSize*1.5f||delta.sqrMagnitude<0.001f)continue;
            DisplaceUnit(enemy,delta,TileSize*0.5f);
            enemy.combatStatuses.ApplyTimed(CombatStatusKind.Displaced,2f,source);
        }
    }

    private void ApplyCrossHuntExecution(Unit source,Unit defeated)
    {
        if(source==null||defeated==null||
           !MonsterTraitRuntime.Has(source.activeTraitIds,"trait_cross_hunt"))return;
        string other=string.Equals(source.traitState.crossHuntFirstTargetId,defeated.stableId,
            StringComparison.Ordinal)?source.traitState.crossHuntSecondTargetId:
            source.traitState.crossHuntFirstTargetId;
        Unit target=units.FirstOrDefault(unit=>IsCombatActive(unit)&&unit.team!=source.team&&
            string.Equals(unit.stableId,other,StringComparison.Ordinal));
        if(target!=null)ApplyDamage(source,target,source.damage*1.5f,false,true,false);
        source.traitState.crossHuntFirstTargetId="";
        source.traitState.crossHuntSecondTargetId="";
    }

    private void SwitchCrossHuntTarget(Unit source,Unit previous)
    {
        if(source==null)return;
        Unit next=units.Where(enemy=>enemy!=previous&&IsCombatActive(enemy)&&enemy.team!=source.team&&
                Vector3.Distance(Flat(source.model.transform.position),Flat(enemy.model.transform.position))<=
                AttackDistance(source,enemy)+TileSize*0.1f)
            .OrderBy(enemy=>TargetScore(source,enemy)).FirstOrDefault();
        if(next!=null)SetTarget(source,next);
    }

    private Unit FindTraitSplashTarget(Unit source,Unit primary,bool piercing)
    {
        if(source==null||primary==null||source.model==null||primary.model==null)return null;
        Vector3 sourcePosition=Flat(source.model.transform.position);
        Vector3 primaryPosition=Flat(primary.model.transform.position);
        Vector3 attackDirection=(primaryPosition-sourcePosition).normalized;
        Unit best=null;
        float bestDistance=float.MaxValue;
        for(int i=0;i<units.Count;i++)
        {
            Unit candidate=units[i];
            if(candidate==primary||!IsCombatActive(candidate)||candidate.team==source.team)continue;
            Vector3 candidatePosition=Flat(candidate.model.transform.position);
            float distance=Vector3.Distance(primaryPosition,candidatePosition);
            if(piercing)
            {
                Vector3 behind=candidatePosition-primaryPosition;
                float forward=Vector3.Dot(behind,attackDirection);
                float lateral=(behind-attackDirection*forward).magnitude;
                if(forward<=0f||forward>TileSize*2.5f||lateral>TileSize*0.55f)continue;
            }
            else if(distance>TileSize*1.15f)continue;
            if(distance>=bestDistance)continue;
            bestDistance=distance;
            best=candidate;
        }
        return best;
    }

    private void TriggerBasicAttackTeamTraits(Unit attacker,Unit target)
    {
        for(int i=0;i<units.Count;i++)
        {
            Unit ally=units[i];
            if(ally==attacker||!IsCombatActive(ally)||ally.team!=attacker.team)continue;
            if(ally.target==target&&MonsterTraitRuntime.TryTriggerAssistSignal(
                ally.activeTraitIds,ally.traitState))
            {
                ApplyDamage(ally,target,ally.damage*0.25f,false,false,false);
                ally.traitActivations++;
            }
            if(IsCombatActive(target)&&MonsterTraitRuntime.TryConsumeSharedMark(
                ally.activeTraitIds,ally.traitState,target.stableId))
            {
                ApplyDamage(ally,target,ally.damage*0.3f,true,false,false);
                ally.traitActivations++;
            }
        }
    }

    private bool ApplyFocusChain(SkillExecutionContext context,SkillMasterRow skill)
    {
        Unit source=context.source;
        int maxStacks=Mathf.Max(1,skill.maxStacks);
        if(source.focusTarget==context.target)source.focusStacks=Mathf.Min(maxStacks,source.focusStacks+1);
        else
        {
            source.focusTarget=context.target;source.focusStacks=1;source.skillUses++;
            ApplyPostSkillItemEffects(source);
        }
        source.cooldown=context.attackInterval/(1f+source.focusStacks*skill.stackBonus);
        source.skillHits++;
        RecordSkillEvent(source,source.skillId,source.focusStacks,0f);
        return true;
    }

    private bool ApplyClusterBasicSplash(SkillExecutionContext context,SkillMasterRow skill)
    {
        Unit source=context.source;
        Unit target=context.target;
        if(!IsCombatActive(target))return false;
        for(int i=0;i<units.Count;i++)
        {
            Unit splash=units[i];
            if(!IsCombatActive(splash)||splash.team==source.team||splash==target)continue;
            if(Vector3.Distance(Flat(splash.model.transform.position),Flat(target.model.transform.position))<=TileSize*1.15f)
                ApplyDamage(source,splash,source.damage*0.5f,false,false);
        }
        return true;
    }

    // Scope covers nested on-hit effects too; reflected damage cannot start another reflection.
    private int reflectedDamageDepth;

    private float ApplyReflectedDamage(Unit source,Unit target,float damage,bool asTrueDamage=false)
    {
        reflectedDamageDepth++;
        try
        {
            return ApplyDamage(source,target,asTrueDamage?0f:damage,
                false,false,false,false,0f,asTrueDamage?damage:0f);
        }
        finally { reflectedDamageDepth--; }
    }

    private float ApplyDamage(Unit source,Unit target,float damage,bool fromSkill=false,
        bool isBasicAttack=false,bool triggerTeamTraits=true,bool allowBearReflection=true,
        float defenseIgnoreRatio=0f,float trueDamage=0f,float shieldDamageMultiplier=1f,
        bool bypassShields=false,bool unscaledTrueDamage=false,bool markSabertoothPrey=false)
    {
        return ApplyDamageComponents(source,target,damage,fromSkill,isBasicAttack,triggerTeamTraits,
            allowBearReflection,defenseIgnoreRatio,trueDamage,shieldDamageMultiplier,
            bypassShields,unscaledTrueDamage,markSabertoothPrey,0f);
    }

    private bool damageBypassesProjectileWalls;

    // Resolve the ordinary attack and its stat-scaled addition as one hit/proc.
    private float ApplyDamageComponents(Unit source,Unit target,float damage,bool fromSkill,
        bool isBasicAttack,bool triggerTeamTraits,bool allowBearReflection,
        float defenseIgnoreRatio,float trueDamage,float shieldDamageMultiplier,
        bool bypassShields,bool unscaledTrueDamage,bool markSabertoothPrey,float nonAttackDamage,
        bool regionDamageScaled=false,bool skillImpact=false,bool allowHitSlide=true,
        bool bypassProjectileWalls=false)
    {
        if(battleEnding)return 0f;
        bool previousWallBypass=damageBypassesProjectileWalls;
        damageBypassesProjectileWalls=bypassProjectileWalls;
        try
        {
        float preventedBefore=target==null?0f:target.preventedDamage;
        Vector3 basicImpactPoint=(isBasicAttack||mushroomCrowns.Count>0||mushroomPropagations.Count>0)&&target!=null&&target.model!=null
            ?Flat(target.model.transform.position):Vector3.zero;
        float applied=ResolveDamage(source,target,damage,fromSkill,isBasicAttack,triggerTeamTraits,
            allowBearReflection,defenseIgnoreRatio,trueDamage,shieldDamageMultiplier,
            bypassShields,unscaledTrueDamage,markSabertoothPrey,nonAttackDamage,regionDamageScaled,skillImpact,allowHitSlide);
        if(applied>0f&&target!=null&&target.alive)target.mycokingFx?.Hit();
        if(target!=null&&!target.alive)
        {
            BeginMantisHatchWhenBroodGone(target.mantisBroodOwner);
            NotifyMushroomPropagationDeath(target,basicImpactPoint);
            NotifyMushroomCrownDeath(target,basicImpactPoint);
        }
        if(isBasicAttack&&!fromSkill&&
           (applied>0f||target!=null&&target.preventedDamage>preventedBefore))
            TriggerMushroomResonance(source,target,basicImpactPoint);
        return applied;
        }
        finally {damageBypassesProjectileWalls=previousWallBypass;}
    }

    private float ResolveDamage(Unit source,Unit target,float damage,bool fromSkill,
        bool isBasicAttack,bool triggerTeamTraits,bool allowBearReflection,
        float defenseIgnoreRatio,float trueDamage,float shieldDamageMultiplier,
        bool bypassShields,bool unscaledTrueDamage,bool markSabertoothPrey,float nonAttackDamage,
        bool regionDamageScaled,bool skillImpact,bool allowHitSlide)
    {
        if(source?.spiritConcertOwner!=null)
        {damage*=source.spiritConcertScale;trueDamage*=source.spiritConcertScale;nonAttackDamage*=source.spiritConcertScale;triggerTeamTraits=false;allowBearReflection=false;}
        if(target?.spiritConcertOwner!=null)return 0f;
        if(target!=null&&target.mantisMolt!=null||MantisOffenseSuspended(source)&&source!=target&&!fromSkill)return 0f;
        bool mammothExecution=target!=null&&target.mammothExpelled;
        bool mammothSharedHit=mammothSharedDamageDepth>0;
        if(!damageBypassesProjectileWalls&&!mammothExecution&&!mammothSharedHit&&
           IsRank3ProjectileBlocked(source,target,fromSkill,isBasicAttack))return 0f;
        if(!IsCombatActive(target)||
           target.ninjaUntargetableTimer>0f||target.ninjaCrossActive||
           target.griffinSkyfalling||target.monkeyNimbus!=null)return 0f;
        bool attackScaled=!fromSkill||UsesAttackSkillScaling(source);
        if(attackScaled&&source!=null&&source.rank3AttackBonusTimer>0f)
            damage*=1f+source.rank3AttackBonusRatio;
        if(target.augmentReturnTimer>0f||
           target.augmentReturnInvulnerabilityTimer>0f)return 0f;
        if(attackScaled)damage*=Mathf.Max(.01f,1f+CurrentFrogStolenBuff(source,FrogStolenBuffKind.AttackDamage));
        if(attackScaled&&source!=null&&source.kingKongWeakTimer>0f)
            damage*=1f-KingKongCombatRules.LilasAttackReduction;
        if(attackScaled&&source!=null&&source.familyAttackReductionTimer>0f)
            damage*=1f-Mathf.Clamp01(source.familyAttackReductionRatio);
        if(source!=null&&source.bearResolveTimer>0f&&UsesAttackSkillScaling(source))
        {
            float multiplier=1f+
                BearCombatRules.ResolveAttackDamageBonus*BearResolveStrength(source);
            damage*=multiplier;
        }
        damage+=Mathf.Max(0f,nonAttackDamage);
        if(source!=null&&target!=null)
        {
            float healthRatio=target.hp/Mathf.Max(1f,target.maxHp);
            if(MonsterTraitRuntime.Has(source.activeTraitIds,"trait_rank2_opening")&&healthRatio>=0.7f)
            damage*=1.3f;
            if(MonsterTraitRuntime.Has(source.activeTraitIds,"trait_rank2_finisher")&&healthRatio<=0.3f)
            damage*=1.35f;
            bool suppressed=target.combatStatuses.Has(CombatStatusKind.Airborne)||
                target.combatStatuses.Has(CombatStatusKind.Knockdown)||
                target.combatStatuses.Has(CombatStatusKind.Root)||
                target.combatStatuses.Has(CombatStatusKind.Displaced);
            if(suppressed&&MonsterTraitRuntime.Has(source.activeTraitIds,"trait_rank2_suppression"))
            damage*=1.35f;
            bool exposed=target.combatStatuses.Has(CombatStatusKind.ComboWeakened)||
                         target.combatStatuses.Has(CombatStatusKind.Marked)||
                         target.itemDefenseShredTimer>0f||
                         target.combatStatuses.Has(CombatStatusKind.ArmorBroken);
            if(exposed&&MonsterTraitRuntime.Has(source.activeTraitIds,"trait_rank2_weakness"))
            {
                damage*=1.35f;
                defenseIgnoreRatio=Mathf.Max(defenseIgnoreRatio,0.15f);
            }
            bool elemental=target.combatStatuses.Has(CombatStatusKind.ComboChilled)||
                target.combatStatuses.Has(CombatStatusKind.Poison)||
                target.combatStatuses.Has(CombatStatusKind.Burning)||
                target.combatStatuses.Has(CombatStatusKind.ComboBurning)||
                target.combatStatuses.Has(CombatStatusKind.Bleed)||
                target.combatStatuses.Has(CombatStatusKind.Freeze);
            if(fromSkill&&elemental&&MonsterTraitRuntime.Has(source.activeTraitIds,"trait_rank2_elemental"))
            damage*=1.35f;
            CombatStatusEffect rally=source.combatStatuses.Get(CombatStatusKind.ComboRally);
            if(rally!=null)
            {
                float rallyMultiplier=1f+Mathf.Max(0f,rally.magnitude);
                damage*=rallyMultiplier;
            }
        }
        if(target!=null&&target.hp<=target.maxHp*0.4f&&
           MonsterTraitRuntime.Has(target.activeTraitIds,"trait_rank2_crisis"))
            damage*=0.75f;
        float requestedDamage=Mathf.Max(0f,damage)+Mathf.Max(0f,trueDamage);
        target.recentAttacker=source;target.threatTimer=1.35f;
        bool hasForcedTarget=IsCombatActive(target.forcedTarget)&&target.forcedTargetTimer>0f;
        bool hasCurrentTarget=IsCombatActive(target.target);
        if(!hasForcedTarget&&!hasCurrentTarget)
        {
            Unit nearest=SelectTarget(target,true)??SelectTarget(target);
            if(nearest!=null)
            {
                SetTarget(target,nearest);
                target.blockedTimer=0f;
                target.decisionTimer=DecisionInterval;
            }
        }
        Vector3 impact=target.model.transform.position-source.model.transform.position;impact.y=0f;
        bool killedMarkedPrecheck=source.jaguarMarkTimer>0f&&
            source.jaguarMarkedTarget==target&&
            MonsterTraitRuntime.Has(source.activeTraitIds,JaguarCombatRules.BumiTraitId);
        float outgoingDamageMultiplier=JaguarCombatRules.MarkedDamageMultiplier(
            killedMarkedPrecheck,source.shadowSlashing)*
            OutgoingGrowthDamageMultiplier(source,target,isBasicAttack)*
            CombatStatFormula.BattleOvertimeDamageMultiplier(battleElapsed)*
            (regionDamageScaled?1f:source.regionDamageMultiplier);
        float physicalTakenMultiplier=target.damageTakenMultiplier*
            Mathf.Max(0f,1f-target.itemDamageReduction);
        if(target.corruptIncomingDamageAmpTimer>0f)
            physicalTakenMultiplier*=1f+target.corruptIncomingDamageAmp;
        CombatGrowthCardModifiers targetGrowth=GrowthModifiers(target.team);
        if(target.hp<=target.maxHp*0.4f)
            physicalTakenMultiplier*=targetGrowth.lowHealthDamageTakenMultiplier;
        if(target.growthStatusRecoveryGuardTimer>0f)
            physicalTakenMultiplier*=targetGrowth.statusRecoveryDamageTakenMultiplier;
        outgoingDamageMultiplier*=1f+
            EffectSum(source,"AllDamageAmplification",row=>row.effectParam1);
        outgoingDamageMultiplier*=Mathf.Max(0f,1f-TwilightShroudReduction(source));
        if(source.itemRandomAttackMode)
            outgoingDamageMultiplier*=1f+
                EffectSum(source,"RandomBattleMode",row=>row.effectParam1);
        if(isBasicAttack)
        {
            outgoingDamageMultiplier*=source.augmentBasicDamageMultiplier;
            physicalTakenMultiplier*=Mathf.Max(0f,1f-
                EffectSum(target,"BasicAttackDamageReduction",row=>row.effectParam1));
        }
        if(source.augmentClimaxTimer>0f)
            outgoingDamageMultiplier*=1f+ExpeditionAugmentRuntime.ProtagonistParam(
                "climax_damage_bonus",0.30f);
        if(target.augmentClimaxTimer>0f)
            physicalTakenMultiplier*=Mathf.Max(0f,1f-
                ExpeditionAugmentRuntime.ProtagonistParam(
                    "climax_damage_reduction",0.30f));
        float highHealthReduction=EffectSum(target,"HighHealthDamageReduction",row=>
            target.hp>target.maxHp*row.effectParam3?row.effectParam2:row.effectParam1);
        physicalTakenMultiplier*=Mathf.Max(0f,1f-highHealthReduction);
        DamagePacket physicalPacket=DamagePacket.Physical(
            damage,fromSkill?DamageSourceId.Skill:DamageSourceId.BasicAttack,
            fromSkill?DamageTags.Attack:DamageTags.Attack|DamageTags.Basic);
        physicalPacket.trueDamage=Mathf.Max(0f,trueDamage);
        physicalPacket=physicalPacket.Scaled(outgoingDamageMultiplier);
        // This amount already comes from resolved HP loss, so do not amplify it again.
        if(unscaledTrueDamage||reflectedDamageDepth>0)
            physicalPacket.trueDamage=Mathf.Max(0f,trueDamage);
        physicalPacket.physical*=Mathf.Max(0f,physicalTakenMultiplier);
        physicalPacket.armorPenetration=Mathf.Clamp01(defenseIgnoreRatio);
        float physicalDamage=physicalPacket.physical;
        float fixedDamage=physicalPacket.trueDamage;
        DamageResult resolvedDamage=CombatDamageResolver.Resolve(physicalPacket,
            new CombatDefense{armor=CurrentDefense(target),moreDamageTakenMultiplier=1f});
        float mitigatedPhysical=resolvedDamage.physical;
        fixedDamage=resolvedDamage.trueDamage;
        if(physicalDamage>mitigatedPhysical)
            target.preventedDamage+=physicalDamage-mitigatedPhysical;
        float resolveReduction=target.bearResolveTimer>0f
            ?target.bearResolveDamageReduction*BearResolveStrength(target):0f;
        float bearDamageMultiplier=1f-Mathf.Clamp01(resolveReduction);
        if(bearDamageMultiplier<1f)
        {
            float reduced=mitigatedPhysical*(1f-bearDamageMultiplier);
            target.preventedDamage+=reduced;mitigatedPhysical-=reduced;
        }
        if(target.crocodileToughHideTimer>0f)
        {
            float reduced=mitigatedPhysical*CrocodileCombatRules.ToughScalesDamageReduction;
            target.preventedDamage+=reduced;mitigatedPhysical-=reduced;
        }
        if(target.guardTimer>0f)
        {
            float reduced=mitigatedPhysical*0.35f;
            target.preventedDamage+=reduced;mitigatedPhysical-=reduced;
        }
        if(target.corruptDamageReduction>0f)
        {
            float reduced=mitigatedPhysical*Mathf.Clamp01(target.corruptDamageReduction);
            target.preventedDamage+=reduced;mitigatedPhysical-=reduced;
        }
        bool oppressionProtected=HaetaeOppressionAffects(target,true);
        if(oppressionProtected||target.familyDamageReductionTimer>0f||(TyrannoExtinctionCharging(target)||TyrannoMarchProtected(target)||TyrannoMawProtected(target)))
        {
            float reduction=Mathf.Max(target.familyDamageReductionTimer>0f?target.familyDamageReductionRatio:0f,
                (TyrannoExtinctionCharging(target)||TyrannoMarchProtected(target)||TyrannoMawProtected(target))?TyrannoRank3Rules.ChargeReduction:0f);
            if(oppressionProtected)reduction=Mathf.Max(reduction,HaetaeRank3Rules.OppressionProtection);
            float reduced=mitigatedPhysical*Mathf.Clamp01(reduction);
            target.preventedDamage+=reduced;mitigatedPhysical-=reduced;
        }
        float frogReduction=mitigatedPhysical*Mathf.Clamp01(
            CurrentFrogStolenBuff(target,FrogStolenBuffKind.DamageReduction));
        target.preventedDamage+=frogReduction;mitigatedPhysical-=frogReduction;
        if(!mammothSharedHit&&target.team==Team.Player&&battleElapsed<=6f&&
           PermanentResearchSystem.Unlocked(
               playerProfile,PermanentResearchSystem.FrontlinePreparation))
        {
            float ratio=Mathf.Clamp01(PermanentResearchSystem.Value(
                playerProfile,PermanentResearchSystem.FrontlinePreparation));
            float prevented=(mitigatedPhysical+fixedDamage)*ratio;
            mitigatedPhysical*=1f-ratio;
            fixedDamage*=1f-ratio;
            target.preventedDamage+=prevented;
        }
        damage=mitigatedPhysical+fixedDamage;
        float mammothBraceContactDamage=damage;
        float damageBeforeShield=damage;
        if(!bypassShields)
        {
            shieldDamageMultiplier=Mathf.Max(1f,shieldDamageMultiplier);
            if(target.crocodileShield>0f)
            {
                float absorbed=Mathf.Min(target.crocodileShield,damage*shieldDamageMultiplier);
                float blocked=absorbed/shieldDamageMultiplier;
                target.crocodileShield-=absorbed;target.preventedDamage+=blocked;damage-=blocked;
            }
            if(target.griffinShield>0f)
            {
                float absorbed=Mathf.Min(target.griffinShield,damage*shieldDamageMultiplier);
                float blocked=absorbed/shieldDamageMultiplier;
                target.griffinShield-=absorbed;target.preventedDamage+=blocked;damage-=blocked;
            }
            if(target.raptorShield>0f)
            {
                float absorbed=Mathf.Min(target.raptorShield,damage*shieldDamageMultiplier);
                float blocked=absorbed/shieldDamageMultiplier;
                target.raptorShield-=absorbed;target.preventedDamage+=blocked;damage-=blocked;
            }
            if(target.kingKongShield>0f)
            {
                float absorbed=Mathf.Min(target.kingKongShield,damage*shieldDamageMultiplier);
                float blocked=absorbed/shieldDamageMultiplier;
                target.kingKongShield-=absorbed;target.preventedDamage+=blocked;damage-=blocked;
            }
            if(target.bearMountainShield>0f)
            {
                float absorbed=Mathf.Min(target.bearMountainShield,damage*shieldDamageMultiplier);
                float blocked=absorbed/shieldDamageMultiplier;
                target.bearMountainShield-=absorbed;target.preventedDamage+=blocked;damage-=blocked;
            }
            if(target.spiritLifeShield>0f)
            {
                float absorbed=Mathf.Min(target.spiritLifeShield,damage*shieldDamageMultiplier);
                float blocked=absorbed/shieldDamageMultiplier;
                target.spiritLifeShield-=absorbed;target.preventedDamage+=blocked;damage-=blocked;
            }
            float statusShieldAbsorbed=
                target.combatStatuses.AbsorbShield(damage*shieldDamageMultiplier);
            if(statusShieldAbsorbed>0f)
            {
                float blocked=statusShieldAbsorbed/shieldDamageMultiplier;
                target.preventedDamage+=blocked;
                damage-=blocked;
            }
            ApplyLowHealthShield(target,damage);
            if(target.itemShield>0f)
            {
                float absorbed=Mathf.Min(target.itemShield,damage*shieldDamageMultiplier);
                float blocked=absorbed/shieldDamageMultiplier;
                target.itemShield-=absorbed;target.preventedDamage+=blocked;damage-=blocked;
            }
        }
        if(damage<damageBeforeShield)ShowUnitShieldHit(source,target);
        if(!mammothExecution&&IsSpiritSanctuaryProtected(target))
        {
            float capped=SpiritDeerRank3Rules.CapHitDamage(
                damage,target.maxHp,SpiritDeerRank3Rules.InviolableHitCap);
            if(capped<damage)
            {
                float blocked=damage-capped;
                target.preventedDamage+=blocked;
                damage=capped;
                ShowSpiritGuardHit(source,target,blocked);
            }
        }
        if(!mammothExecution&&!mammothSharedHit)damage=ShareMammothBraceDamage(source,target,damage,fromSkill);
        if(!IsCombatActive(target))return 0f;
        if(mammothExecution)damage=target.hp;
        float applied=Mathf.Min(target.hp,damage);
        PlayDamageSound(source,target,isBasicAttack,fromSkill,applied);
        if(applied>0f)
        {
            float previousRatio=target.hp/Mathf.Max(1f,target.maxHp);
            target.damageTrailRatio=DamageTrailRatio(previousRatio,target.damageTrailRatio,
                Time.time-target.damageTrailStartedAt);
            // Repeated hits continue the drain instead of pinning the trail at full health.
            target.damageTrailStartedAt=Time.time-(target.damageTrailRatio>previousRatio+.001f?.12f:0f);
        }
        target.hp=Mathf.Max(0f,target.hp-applied);
        NotifyMammothBraceHit(source,target,applied,mammothBraceContactDamage);
        if(applied>0f&&target.hp>0f)
            target.skillTimer=CombatStatFormula.CooldownAfterDamageTaken(
                target.skillTimer,target.skillCooldownDuration,
                applied,target.maxHp);
        bool critical=!unscaledTrueDamage&&source!=null&&
            (fromSkill?source.lastSkillCritical:
             isBasicAttack&&source.lastBasicAttackCritical);
        // Direct skill contact is independent of whether this hit may trigger trait chains.
        bool contact=isBasicAttack||fromSkill&&(triggerTeamTraits||skillImpact);
        if(applied>0f&&source!=null)
        {
            Vector3 sourcePosition=Flat(source.model.transform.position);
            Vector3 targetPosition=Flat(target.model.transform.position);
            combatCameraDirector?.ReportDamage(
                source.stableId,source.team==Team.Player,
                sourcePosition,targetPosition,applied);
            float impactStrength=
                critical&&applied>=target.maxHp*.12f ? .68f : .14f;
            layeredBattleEnvironment?.Pulse(
                targetPosition,impactStrength,targetPosition-sourcePosition);
            if(fromSkill&&contact&&critical&&applied>=target.maxHp*0.12f)
                combatCameraDirector?.ReportStrongCritical(
                    source.stableId,source.team==Team.Player,
                    sourcePosition,targetPosition);
        }
        if(applied>0f)
            AddCombatFloatText(
                target,
                Mathf.CeilToInt(applied)+(critical?"!":""),
                fromSkill
                    ?critical
                        ?new Color(1f,0.42f,0.92f)
                        :new Color(0.42f,0.92f,1f)
                    :critical
                        ?new Color(1f,0.78f,0.18f)
                        :new Color(1f,0.92f,0.88f),
                critical,combatResult:true,damageImpact:contact);
        else if(requestedDamage>0f)
            AddCombatFloatText(
                target,"BLOCK",new Color(0.35f,0.82f,1f),false,combatResult:true);
        if(applied>0f)ApplyOnHitItemEffects(target,isBasicAttack);
        if(applied>0f)
        {
            float drain=EffectSum(source,"Omnivamp",row=>row.effectParam1)+
                        EffectSum(source,"BloodTalisman",row=>row.effectParam1);
            if(!source.itemRandomAttackMode||
               CorruptionEffect(source,"CorruptChosenFate")!=null)
                drain+=EffectSum(source,"RandomBattleMode",row=>row.effectParam2);
            Heal(source,applied*drain);
            if(isBasicAttack&&!fromSkill)ApplySpiritLifeReturn(source,target,applied);
        }
        source.damageDealt+=applied;target.damageTaken+=applied;
        if(source.spiritConcertOwner!=null)
        {
            source.spiritConcertOwner.damageDealt+=applied;
            if(fromSkill&&applied>0f){source.spiritConcertOwner.skillDamage+=applied;source.spiritConcertOwner.skillHits++;}
        }
        ApplyBloodReflux(source,target,applied);
        if(applied>0f)
        {
            lastCombatProgressAt=battleElapsed;
            nextStalemateRecoveryAt=battleElapsed+StalemateRecoveryDelay;
            stalemateRecoveryCount=0;
        }
        if(applied>0f)
            HandleCorruptionDamageTaken(source,target,applied,fromSkill,isBasicAttack,
                allowBearReflection&&reflectedDamageDepth==0);
        if(applied>0f&&isBasicAttack)
            AddProtagonistGauge(source,ExpeditionAugmentRuntime.ProtagonistParam(
                "basic_hit_gain",4f));
        if(applied>0f&&target.augmentProtagonistHitGainCooldown<=0f&&
           AddProtagonistGauge(target,ExpeditionAugmentRuntime.ProtagonistParam(
               "hit_received_gain",3f)))
            target.augmentProtagonistHitGainCooldown=
                ExpeditionAugmentRuntime.ProtagonistParam("hit_gain_icd",0.5f);
        if(applied>0f&&source!=target)
        {
            float accumulated=0f;
            target.personalityDamageByAttacker.TryGetValue(source,out accumulated);
            target.personalityDamageByAttacker[source]=accumulated+applied;
            // Same damage-descending/id-ascending selection without sorting per hit.
            Unit revenge=null;
            float highestDamage=float.NegativeInfinity;
            foreach(var pair in target.personalityDamageByAttacker)
            {
                if(!IsCombatActive(pair.Key))continue;
                if(revenge!=null&&(pair.Value<highestDamage||
                    pair.Value==highestDamage&&pair.Key.id>=revenge.id))continue;
                revenge=pair.Key;
                highestDamage=pair.Value;
            }
            target.personalityRevengeTarget=revenge;
            HandlePersonalityDamageReaction(
                source,target,applied,target.personalityDamageByAttacker[source]);
            if(isBasicAttack)TryRotateFickleTarget(source,target);
        }
        if(applied>0f&&triggerTeamTraits)
        {
            ApplyAdditionalTraitCombos(source,target,fromSkill,isBasicAttack);
            if(!target.alive)return applied;
            TriggerProtectiveCounters(target,source);
        }
        if(telemetryEpisodeStarted&&!telemetryEpisodeEnded)
            telemetry.RecordDamage(battleElapsed,source.id,target.id,applied,target.hp/Mathf.Max(1f,target.maxHp));
        if(applied>0f&&target.reaction!=null)
        {
            bool strong=contact&&(critical||fromSkill&&applied>=target.maxHp*.12f);
            if(CombatReadabilityPresentation.RefinedSkills&&isBasicAttack&&!fromSkill)
                target.reaction.PlayBasicHitFeedback(impact,strong);
            else if(CombatReadabilityPresentation.Local&&
                    fromSkill&&contact&&!readabilityGroundImpact)
                target.reaction.PlaySkillHitFeedback(impact,strong);
            else
            target.reaction.PlayHit(impact,strong,contact);
        }
        if(applied>0f&&fromSkill&&contact&&allowHitSlide)BeginHitSlide(source,target,critical,fromSkill);
        if(target.hp>0f)return applied;
        if(!mammothExecution&&TryBeginMantisDeathMolt(target,source))return applied;
        ExpeditionAugmentCombatModifiers targetAugments=target.team==Team.Player
            ?ExpeditionAugmentRuntime.CombatModifiers(
                expeditionRun,target.stableId,expeditionRun.wave)
            :new ExpeditionAugmentCombatModifiers();
        if(!mammothExecution&&target.mantisMolt==null&&targetAugments.returnMarked&&!target.augmentReturnUsed)
        {
            target.augmentReturnUsed=true;
            target.hp=1f;
            target.augmentReturnTimer=Mathf.Max(0.1f,targetAugments.returnDelay);
            target.currentAction="return_mark";
            target.velocity=Vector3.zero;
            StopBeforeAttack(target);
            ReleaseAttackSlot(target);
            for(int i=0;i<units.Count;i++)
                if(units[i]!=target&&units[i].target==target)
                    SetTarget(units[i],null);
            target.reaction?.PlayReturnMark(target.augmentReturnTimer);
            if(target.ring!=null)target.ring.SetActive(false);
            AddCombatFloatText(
                target,"회귀",new Color(0.42f,0.82f,1f),true);
            return applied;
        }
        bool shadowDeath=target.augmentShadowClone;
        if(!mammothExecution&&!shadowDeath)TryHarvestSilkPuppet(target);
        if(!shadowDeath&&source!=null)
        {
            Vector3 killerPosition=Flat(source.model.transform.position);
            Vector3 defeatedPosition=Flat(target.model.transform.position);
            if(mammothExecution)combatCameraDirector?.ReportExpulsion(target.stableId);
            else combatCameraDirector?.ReportDeath(
                    source.stableId,source.team==Team.Player,
                    target.stableId,target.team==Team.Enemy,
                    killerPosition,defeatedPosition);
            layeredBattleEnvironment?.Pulse(
                defeatedPosition,1f,defeatedPosition-killerPosition);
        }
        bool allowDeathTriggers=!shadowDeath&&!source.augmentShadowClone;
        // A marked enemy's death rewards its living hunter even when an allied clone lands the kill.
        if(allowDeathTriggers)
        {
            source.kills++;
            if(source.augmentTranscended&&IsRaptorFamily(source)&&
               source.raptorApexPredatorTimer>0f)
                source.raptorApexPredatorTimer+=
                    ExpeditionAugmentRuntime.TranscendenceParam(
                        "raptor_apex_kill_extension",
                        RaptorCombatRules.ApexPredatorKillExtension);
            HandleCorruptionKill(source,target);
            HandleFamilyTranscendenceDeath(source,target);
            Unit protagonist=units.FirstOrDefault(unit=>IsCombatActive(unit)&&
                unit.team==Team.Player&&ExpeditionAugmentRuntime.Targets(
                    ExpeditionAugmentRuntime.Selection(
                        expeditionRun,ExpeditionAugmentRuntime.Protagonist),
                    unit.stableId));
            if(protagonist==source||protagonist!=null&&
               target.personalityDamageByAttacker.ContainsKey(protagonist))
                AddProtagonistGauge(protagonist,
                    ExpeditionAugmentRuntime.ProtagonistParam(
                        "kill_assist_gain",10f));
        }
        Unit deathMarkSource=target.crocodileDeathMarkTimer>0f
            ?target.crocodileDeathMarkSource:null;
        if(allowDeathTriggers&&IsCombatActive(deathMarkSource)&&MonsterTraitRuntime.Has(
            deathMarkSource.activeTraitIds,CrocodileCombatRules.TarvilTraitId))
        {
            deathMarkSource.skillTimer=CrocodileCombatRules.CooldownAfterMarkedDeath(
                deathMarkSource.skillTimer);
            deathMarkSource.traitActivations++;
            PlayTraitBurst(target,new Color(0.7f,0.12f,0.88f),true);
            PlayTraitBurst(deathMarkSource,new Color(0.48f,0.08f,0.62f),false);
        }
        Unit sporeMarkSource=target.mushroomSporeMarkTimer>0f
            ?target.mushroomSporeMarkSource:null;
        if(allowDeathTriggers&&sporeMarkSource!=null&&MonsterTraitRuntime.Has(
           sporeMarkSource.activeTraitIds,MushroomCombatRules.KingmoreTraitId))
        {
            Vector3 childPosition=Flat(target.model.transform.position);
            float childDamage=target.mushroomSporeChildDamage;
            float childRadius=target.mushroomSporeChildRadius;
            float childDelay=target.mushroomSporeChildDelay;
            target.mushroomSporeMarkSource=null;
            target.mushroomSporeMarkTimer=0f;
            sporeMarkSource.traitActivations++;
            PlayTraitBurst(target,new Color(1f,0.68f,0.18f),true);
            StartReleasedSkill(sporeMarkSource,ResolveChildMushroom(sporeMarkSource,childPosition,childRadius,childDamage,
                childDelay,combatGeneration));
        }
        if(allowDeathTriggers&&killedMarkedPrecheck)
        {
            source.skillTimer=JaguarCombatRules.CooldownAfterMarkedKill(source.skillTimer);
            source.traitActivations++;
            ClearJaguarHuntMark(source);
        }
        if(allowDeathTriggers)
        {
            Heal(source,EffectSum(source,"KillHeal",row=>row.effectParam1)*source.maxHp);
            ApplyGrowthCardKillEffects(source,target);
        }
        if(source.team==Team.Player&&target.team==Team.Enemy&&!target.silkPuppet&&target.mantisBroodOwner==null&&
           !IsMushroomDeathBloom(target))
            RollAndShowEnemyLoot(target);
        bool captured=source.team==Team.Player&&target==captureTarget&&
                      ResolveCaptureTargetDefeat(target);
        bool frozenDeath=!mammothExecution&&!captured&&!shadowDeath&&
                         target.combatStatuses.Has(CombatStatusKind.Freeze);
        bool deathSoundPending=!captured&&!shadowDeath;
        Vector3 deathSoundPosition=target.model.transform.position;
        if(target.team==Team.Player&&!shadowDeath)
        {
            ApplyGrowthCardAllyDeathEffects(target);
            playerDeathsThisWave++;
            Unit hero=units.FirstOrDefault(unit=>IsCombatActive(unit)&&
                unit.team==Team.Player&&ExpeditionAugmentRuntime.Targets(
                    ExpeditionAugmentRuntime.Selection(
                        expeditionRun,ExpeditionAugmentRuntime.Protagonist),
                    unit.stableId));
            AddProtagonistGauge(hero,ExpeditionAugmentRuntime.ProtagonistParam(
                "ally_final_death_gain",25f));
            ApplyLegacyInheritance(target);
        }
        if(frozenDeath)
        {
            SpriteRenderer frozenRenderer=target.spriteAnimation==null
                ?target.model.GetComponentInChildren<SpriteRenderer>()
                :target.spriteAnimation.GetComponent<SpriteRenderer>();
            TrackWaveDeathParticles(PixelCombatEffect.PlayFreezeDeathShatter(
                target.spriteAnimation==null
                    ?target.model.transform:target.spriteAnimation.transform,
                frozenRenderer));
        }
        // A giraffe can be defeated during its neck extension. Restore the authored
        // rig before the pooled ragdoll copies the live pose, otherwise the stretched
        // neck scale and attack rotation become the ragdoll's starting pose.
        if(target.neckStrike!=null)target.neckStrike.CancelAndRestore();
        if(target.highHeadSlam!=null)target.highHeadSlam.CancelAndRestore();
        target.giraffeSlamming=false;
        EndBearMountainColossus(target);
        EndMonkeyNimbus(target);
        StopWyvernBreathsOnDeath(target);
        InterruptHaetaeRoar(target.haetaeRoar);
        EndHaetaeBellowPush(target);
        target.bearKingRoarActive=false;
        target.bearKingRoarEnding=false;
        target.bearResolveTimer=0f;
        target.bearFrenzyStacks=0;
        target.bearSpiritPending=false;
        PixelCombatEffect.StopBearSpiritAura(target.bearSpiritParticles);
        target.bearSpiritParticles=null;
        target.bearSpiritFx?.Cancel();
        target.bearSpiritFx=null;
        PixelCombatEffect.StopBearSpiritAura(target.returnMarkAura);
        target.returnMarkAura=null;
        PixelCombatEffect.StopBearSpiritAura(target.legacyInheritanceAura);
        target.legacyInheritanceAura=null;
        target.wolfEclipseTimer=0f;
        DeactivateWolfEclipseClones(target);
        bool mantisCocoonDeath=target.mantisMolt!=null;
        CleanupMantisDeathMolt(target,true);
        CleanupRank3Unit(target);
        ResetDeathRollPose(target);
        target.crocodilePreyFlying=false;
        target.alive=false;
        ReleaseMammothRicochet(target);
        InterruptCrocodileAbyssDive(target);
        InterruptFrogGrandSlam(target);
        target.tongueWhip?.Cancel();
        target.tongueHarpoonTarget=null;
        if(target.fangLockTarget!=null)FinishFangLock(target,false);
        if(target.preyDraggedBy!=null)FinishPreyDrag(target.preyDraggedBy,false);
        target.preyFocusTarget=null;
        target.preyFocusTimer=0f;
        target.preyFocusPending=false;
        for(int i=0;i<units.Count;i++)
            if(units[i].preyFocusTarget==target)
            {
                units[i].preyFocusTarget=null;
                units[i].preyFocusTimer=0f;
                units[i].preyFocusPending=false;
                SetTarget(units[i],null);
            }
        target.raptorApexPredatorTimer=0f;
        target.raptorApexCooldownFlash=0f;
        target.raptorApexWings?.Clear();
        target.combatStatuses.Clear();
        target.solarBurnSource=null;
        target.solarBurnTimer=0f;
        target.solarBurnTickTimer=0f;
        target.solarBurnTickDamage=0f;
        ReleaseAttackSlot(target);
        for(int i=0;i<units.Count;i++)
            if(units[i].reservedAttackTarget==target)ReleaseAttackSlot(units[i]);
        occupancy.Remove(target.currentTile);
        target.velocity=Vector3.zero;target.moving=false;
        if(target.outline!=null)target.outline.SetOutlined(false);
        target.ring.SetActive(false);SetMoving(target,false);
        if(!captured)TryBeginMushroomDeathBloom(target);
        if(mammothExecution)target.model.SetActive(false);
        else if(captured)BeginCaptureDeparture(target,impact);
        else if(frozenDeath)target.model.SetActive(false);
        else if(target.silkPuppet)
        {
            if(target.silkPuppetFx!=null)target.silkPuppetFx.Depart();
            target.model.SetActive(false);
        }
        else if(target.silkHarvested||mantisCocoonDeath)target.model.SetActive(false);
        else if(target.mantisBroodOwner!=null)
        {
            if(target.spriteAnimation!=null)target.spriteAnimation.PlayDeath();
            else target.model.SetActive(false);
        }
        else if(target.rank3MycokingSummon)target.model.SetActive(false);
        else if(shadowDeath)
        {
            SpriteRenderer shadowRenderer=target.spriteAnimation==null
                ?target.model.GetComponentInChildren<SpriteRenderer>()
                :target.spriteAnimation.GetComponent<SpriteRenderer>();
            TrackWaveDeathParticles(PixelCombatEffect.PlayNinjaVanishBurst(
                target.spriteAnimation==null
                    ?target.model.transform:target.spriteAnimation.transform,
                shadowRenderer));
            target.model.SetActive(false);
        }
        else if(target.reaction!=null)
        {
            int deathGeneration=combatGeneration;
            target.reaction.PlayDeath(impact,()=>
            {
                if(this!=null&&(deathGeneration==combatGeneration||
                   deathGeneration+1==combatGeneration&&battleEnding&&waveOutcomeStage==WaveOutcomeStage.Death))
                    PlayCombatSound(target,CombatSoundCue.Death,deathSoundPosition,1.15f);
            });
            deathSoundPending=false;
        }
        else if(target.spriteAnimation!=null)target.spriteAnimation.PlayDeath();
        else target.model.SetActive(false);
        if(deathSoundPending)PlayCombatSound(target,CombatSoundCue.Death,deathSoundPosition,1.15f);
        if(triggerTeamTraits&&allowDeathTriggers)TriggerPackHunt(source,target);
        return applied;
    }

    private void ApplyAdditionalTraitCombos(Unit source,Unit target,bool fromSkill,bool isBasicAttack)
    {
        if(source==null||target==null)return;
        if(fromSkill&&MonsterTraitRuntime.Has(source.activeTraitIds,"trait_combo_antigravity")&&
           (StatusFromOtherAlly(source,target,CombatStatusKind.Displaced)!=null||
            StatusFromOtherAlly(source,target,CombatStatusKind.Airborne)!=null||
            StatusFromOtherAlly(source,target,CombatStatusKind.Knockdown)!=null))
        {
            float comboDamage=ApplyDamage(source,target,source.damage*0.4f,true,false,false);
            target.combatStatuses.ApplyTimed(
                CombatStatusKind.Airborne,HostileStatusDuration(target,0.7f),source,0.7f);
            RecordComboActivation(source,target,"trait_combo_antigravity",comboDamage);
        }
        if(MonsterTraitRuntime.Has(source.activeTraitIds,"trait_combo_fall_shatter")&&
           StatusFromOtherAlly(source,target,CombatStatusKind.Airborne)!=null)
        {
            target.combatStatuses.Remove(CombatStatusKind.Airborne);
            float comboDamage=ApplyTraitAreaDamage(source,Flat(target.model.transform.position),
                TileSize*1.2f,source.damage*0.6f,null);
            target.combatStatuses.ApplyTimed(
                CombatStatusKind.Knockdown,HostileStatusDuration(target,0.8f),source);
            target.combatStatuses.ApplyTimed(CombatStatusKind.ComboWeakened,4f,source);
            RecordComboActivation(source,target,"trait_combo_fall_shatter",comboDamage);
        }
        if(MonsterTraitRuntime.Has(source.activeTraitIds,"trait_combo_frost_shackle")&&
           StatusFromOtherAlly(source,target,CombatStatusKind.Root)!=null)
        {
            CombatStatusEffect chill=target.combatStatuses.ApplyStacks(
                CombatStatusKind.ComboChilled,4f,2,3,source,0f,0f,true);
            float comboDamage=0f;
            if(chill.stacks>=3)
            {
                target.combatStatuses.Remove(CombatStatusKind.ComboChilled);
                target.combatStatuses.ApplyTimed(
                    CombatStatusKind.Freeze,HostileStatusDuration(target,1.2f),source);
                comboDamage=ApplyDamage(source,target,source.damage*0.5f,true,false,false);
            }
            RecordComboActivation(source,target,"trait_combo_frost_shackle",comboDamage);
        }
        CombatStatusEffect alliedBleed=StatusFromOtherAlly(source,target,CombatStatusKind.Bleed);
        if(alliedBleed!=null&&MonsterTraitRuntime.Has(
               source.activeTraitIds,"trait_combo_venom_mutation"))
        {
            target.combatStatuses.ConsumeStacks(CombatStatusKind.Bleed,1);
            target.combatStatuses.ApplyStacks(CombatStatusKind.Poison,5f,2,
                CombatStatusState.MaximumPoisonStacks,source,
                source.damage*0.08f,1f,true);
            float comboDamage=ApplyDamage(source,target,source.damage*0.08f,false,false,false);
            RecordComboActivation(source,target,"trait_combo_venom_mutation",comboDamage);
        }
        CombatStatusEffect alliedPoison=StatusFromOtherAlly(source,target,CombatStatusKind.Poison);
        if(alliedPoison!=null&&MonsterTraitRuntime.Has(
               source.activeTraitIds,"trait_combo_chemical_ignition"))
        {
            target.combatStatuses.ConsumeStacks(CombatStatusKind.Poison,1);
            Vector3 center=Flat(target.model.transform.position);
            float comboDamage=ApplyTraitAreaDamage(
                source,center,TileSize*1.5f,source.damage*0.8f,null);
            foreach(Unit enemy in units)
                if(IsCombatActive(enemy)&&enemy.team!=source.team&&
                   Vector3.Distance(center,Flat(enemy.model.transform.position))<=TileSize*1.5f)
                    enemy.combatStatuses.ApplyTimed(CombatStatusKind.ComboBurning,4f,source);
            RecordComboActivation(source,target,"trait_combo_chemical_ignition",comboDamage);
        }
        bool exposed=target.combatStatuses.Has(CombatStatusKind.Marked)||
                     target.combatStatuses.Has(CombatStatusKind.ComboWeakened);
        if(isBasicAttack&&exposed&&MonsterTraitRuntime.Has(
               source.activeTraitIds,"trait_combo_open_wound"))
        {
            if(!string.Equals(source.traitState.openWoundTargetId,target.stableId,
                   StringComparison.Ordinal))
            {
                source.traitState.openWoundTargetId=target.stableId;
                source.traitState.openWoundHits=0;
            }
            source.traitState.openWoundHits++;
            if(source.traitState.openWoundHits>=3)
            {
                source.traitState.openWoundHits=0;
                float comboDamage=ApplyDamage(
                    source,target,source.damage*0.7f,false,false,false);
                target.combatStatuses.ApplyStacks(CombatStatusKind.Bleed,5f,1,3,source,
                    source.damage*0.08f,1f,true);
                RecordComboActivation(source,target,"trait_combo_open_wound",comboDamage);
            }
        }
    }

    private static CombatStatusEffect StatusFromOtherAlly(
        Unit source,Unit target,CombatStatusKind kind)
    {
        CombatStatusEffect effect=target==null?null:target.combatStatuses.Get(kind);
        Unit provider=effect==null?null:effect.source as Unit;
        return provider!=null&&provider!=source&&provider.team==source.team?effect:null;
    }

    private void TriggerProtectiveCounters(Unit damagedAlly,Unit attacker)
    {
        if(!IsCombatActive(attacker))return;
        Vector3 allyPosition=Flat(damagedAlly.model.transform.position);
        for(int i=0;i<units.Count;i++)
        {
            Unit protector=units[i];
            if(protector==damagedAlly||!IsCombatActive(protector)||protector.team!=damagedAlly.team)continue;
            if(Vector3.Distance(allyPosition,Flat(protector.model.transform.position))>TileSize*1.35f)continue;
            if(!MonsterTraitRuntime.TryTriggerProtectiveCounter(
                protector.activeTraitIds,protector.traitState))continue;
            ApplyDamage(protector,attacker,protector.damage*0.3f,false,false,false);
            protector.traitActivations++;
            if(!IsCombatActive(attacker))break;
        }
    }

    private void ApplyLegacyInheritance(Unit defeated)
    {
        ExpeditionAugmentSelectionSave inheritance=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.LegacyInheritance);
        if(inheritance==null||inheritance.triggered||defeated==null||
           defeated.team!=Team.Player)return;
        AugmentMasterRow master=GameMasterData.Augment(
            ExpeditionAugmentRuntime.LegacyInheritance);
        int itemLimit=Mathf.Max(1,Mathf.RoundToInt(master==null?3f:
            master.NumericParam("virtual_slot_limit",3f)));
        ExpeditionMonsterStateSave state=ExpeditionItemSystem.MonsterState(
            expeditionRun,defeated.stableId);
        if(state==null)return;
        List<ExpeditionItemInstanceSave> completed=state.itemInstanceIds
            .Select(id=>ExpeditionItemSystem.ItemInstance(expeditionRun,id))
            .Where(item=>item!=null&&GameMasterData.Item(item.itemId)?.IsCompleted==true)
            .Take(itemLimit).ToList();
        if(completed.Count==0)return;
        Unit recipient=units.Where(unit=>IsCombatActive(unit)&&unit.team==Team.Player&&
                unit!=defeated&&!unit.augmentShadowClone&&
                ExpeditionItemSystem.MonsterState(
                    expeditionRun,unit.stableId)?.temporary!=true)
            .OrderBy(unit=>Vector3.Distance(
                Flat(unit.model.transform.position),Flat(defeated.model.transform.position)))
            .ThenBy(unit=>unit.hp/Mathf.Max(1f,unit.maxHp))
            .FirstOrDefault();
        if(recipient==null)return;

        ExpeditionMonsterStateSave inheritedState=new ExpeditionMonsterStateSave();
        inheritedState.itemInstanceIds.AddRange(
            completed.Select(item=>item.instanceId));
        CombatItemModifiers inherited=ExpeditionItemSystem.Aggregate(
            expeditionRun,inheritedState);
        CombatGrowthCardModifiers growth=GrowthModifiers(recipient.team);
        ExpeditionAugmentCombatModifiers augments=
            ExpeditionAugmentRuntime.CombatModifiers(
                expeditionRun,recipient.stableId,expeditionRun.wave);

        float attackFactor=Mathf.Max(0.01f,1f+growth.attackDamageBonus+
            recipient.itemModifiers.attackDamageBonus+augments.attackDamageBonus);
        recipient.damage*=Mathf.Max(0.01f,
            attackFactor+inherited.attackDamageBonus)/attackFactor;
        float healthFactor=Mathf.Max(0.01f,1f+growth.maxHealthBonus+
            recipient.itemModifiers.maxHealthBonus+augments.maxHealthBonus);
        float previousMaxHealth=recipient.maxHp;
        recipient.maxHp*=Mathf.Max(0.01f,
            healthFactor+inherited.maxHealthBonus)/healthFactor;
        recipient.hp=Mathf.Min(recipient.maxHp,
            recipient.hp+recipient.maxHp-previousMaxHealth);
        recipient.defense+=inherited.defenseBonus;
        recipient.statusResistance+=inherited.statusResistanceBonus;
        float speedFactor=Mathf.Max(0.01f,1f+growth.attackSpeedBonus+
            recipient.itemModifiers.attackSpeedBonus+augments.attackSpeedBonus);
        recipient.attackInterval*=speedFactor/Mathf.Max(
            0.01f,speedFactor+inherited.attackSpeedBonus);
        float oldDamageFactor=Mathf.Max(
            0f,1f-recipient.itemModifiers.damageReductionBonus);
        float newDamageFactor=Mathf.Max(0f,oldDamageFactor-
            inherited.damageReductionBonus);
        if(oldDamageFactor>0.001f)
            recipient.damageTakenMultiplier*=newDamageFactor/oldDamageFactor;

        float oldCooldown=recipient.skillCooldownDuration;
        float newCooldown=CombatStatFormula.Cooldown(
            BaseSkillCooldown(recipient.skillId),
            growth.cooldownRecoverySpeed+
            recipient.itemModifiers.skillCooldownReductionBonus+
            inherited.skillCooldownReductionBonus,
            augments.skillCooldownMultiplier);
        if(augments.minimumSkillCooldown>0f)
            newCooldown=Mathf.Max(newCooldown,augments.minimumSkillCooldown);
        if(oldCooldown>0.001f)
            recipient.skillTimer*=newCooldown/oldCooldown;
        recipient.skillCooldownDuration=newCooldown;

        recipient.itemModifiers.attackDamageBonus+=inherited.attackDamageBonus;
        recipient.itemModifiers.attackSpeedBonus+=inherited.attackSpeedBonus;
        recipient.itemModifiers.maxHealthBonus+=inherited.maxHealthBonus;
        recipient.itemModifiers.damageReductionBonus+=inherited.damageReductionBonus;
        recipient.itemModifiers.criticalChance+=inherited.criticalChance;
        recipient.itemModifiers.criticalDamageBonus+=inherited.criticalDamageBonus;
        recipient.itemModifiers.skillPowerBonus+=inherited.skillPowerBonus;
        recipient.itemModifiers.defenseBonus+=inherited.defenseBonus;
        recipient.itemModifiers.statusResistanceBonus+=inherited.statusResistanceBonus;
        recipient.itemModifiers.skillCooldownReductionBonus+=
            inherited.skillCooldownReductionBonus;
        recipient.itemModifiers.specialEffects.AddRange(inherited.specialEffects);
        recipient.itemModifiers.transformedEffects.AddRange(
            inherited.transformedEffects);
        foreach(ItemMasterRow item in inherited.specialEffects)
            ApplyBattleStartItemEffect(recipient,item);
        foreach(ItemTransformMasterRow row in inherited.transformedEffects)
            ApplyBattleStartCorruptionEffect(recipient,row);

        inheritance.triggered=true;
        inheritance.runtimeState=recipient.stableId;
        StartCombatCoroutine(defeated,PlayLegacyInheritanceTransfer(
            defeated,recipient,completed,combatGeneration));
    }

    private IEnumerator PlayLegacyInheritanceTransfer(
        Unit defeated,Unit recipient,List<ExpeditionItemInstanceSave> items,
        int generation)
    {
        Transform sourceAnchor=defeated.spriteAnimation==null
            ?defeated.model.transform:defeated.spriteAnimation.transform;
        SpriteRenderer sourceRenderer=defeated.spriteAnimation==null
            ?defeated.model.GetComponentInChildren<SpriteRenderer>()
            :defeated.spriteAnimation.GetComponent<SpriteRenderer>();
        Transform targetAnchor=recipient.spriteAnimation==null
            ?recipient.model.transform:recipient.spriteAnimation.transform;
        SpriteRenderer targetRenderer=recipient.spriteAnimation==null
            ?recipient.model.GetComponentInChildren<SpriteRenderer>()
            :recipient.spriteAnimation.GetComponent<SpriteRenderer>();
        for(int index=0;index<items.Count;index++)
        {
            if(generation!=combatGeneration||!IsCombatActive(recipient))
                yield break;
            bool final=index==items.Count-1;
            PixelStarProjectile projectile=PixelStarProjectile.PlaySpiritLight(
                sourceAnchor,sourceRenderer,targetAnchor,targetRenderer,
                LegacyItemColor(items[index]),
                final?(Action)(()=>StartLegacyInheritanceAura(recipient)):null);
            if(projectile==null&&final)StartLegacyInheritanceAura(recipient);
            if(!final)yield return new WaitForSeconds(0.07f);
        }
    }

    private static Color LegacyItemColor(ExpeditionItemInstanceSave item)
    {
        if(item.transformState==ExpeditionItemTransformState.Radiant)
            return new Color(1f,0.82f,0.2f,0.96f);
        if(item.transformState==ExpeditionItemTransformState.Overcharged)
            return new Color(0.28f,0.88f,1f,0.94f);
        if(item.transformState==ExpeditionItemTransformState.CorruptedGreatSuccess||
           item.transformState==ExpeditionItemTransformState.CorruptedSuccess||
           item.transformState==ExpeditionItemTransformState.CorruptedFailure)
            return new Color(0.76f,0.22f,1f,0.94f);
        int hueSeed=MonsterInstanceGenerator.StableSeed(item.itemId)&int.MaxValue;
        Color color=Color.HSVToRGB((hueSeed%360)/360f,0.68f,1f);
        color.a=0.94f;
        return color;
    }

    private void StartLegacyInheritanceAura(Unit recipient)
    {
        if(!IsCombatActive(recipient))return;
        PixelCombatEffect.StopBearSpiritAura(recipient.legacyInheritanceAura);
        Transform anchor=recipient.spriteAnimation==null
            ?recipient.model.transform:recipient.spriteAnimation.transform;
        SpriteRenderer renderer=recipient.spriteAnimation==null
            ?recipient.model.GetComponentInChildren<SpriteRenderer>()
            :recipient.spriteAnimation.GetComponent<SpriteRenderer>();
        recipient.legacyInheritanceAura=
            PixelCombatEffect.PlayBearSpiritAura(anchor,renderer);
        if(recipient.legacyInheritanceAura!=null)
        {
            recipient.legacyInheritanceAura.name="Legacy Inheritance Pixel Aura";
            ParticleSystem.MainModule main=recipient.legacyInheritanceAura.main;
            main.startLifetime=new ParticleSystem.MinMaxCurve(0.7f,1.15f);
            main.startSize=new ParticleSystem.MinMaxCurve(0.05f,0.1f);
            main.startColor=new ParticleSystem.MinMaxGradient(
                new Color(1f,0.72f,0.16f,0.88f),
                new Color(0.72f,0.28f,1f,0.9f));
            ParticleSystem.EmissionModule emission=
                recipient.legacyInheritanceAura.emission;
            emission.rateOverTime=8f;
        }
        CreateSkillPulse(recipient,new Color(0.86f,0.52f,1f),1.05f);
    }

    private void TriggerPackHunt(Unit killer,Unit defeated)
    {
        for(int i=0;i<units.Count;i++)
        {
            Unit hunter=units[i];
            if(hunter==killer||!IsCombatActive(hunter)||hunter.team!=killer.team||hunter.target!=defeated||
               !MonsterTraitRuntime.Has(hunter.activeTraitIds,"trait_pack_hunt"))continue;
            Unit next=SelectFinisherTarget(hunter);
            if(next==null)continue;
            SetTarget(hunter,next);
            hunter.packHuntSpeedTimer=GateHaetaeBenefit(hunter,1.5f);
            hunter.decisionTimer=0f;
            hunter.traitActivations++;
        }
    }

    private bool ResolveCaptureTargetDefeat(Unit target)
    {
        if(expeditionRun==null||pendingCapture.resolved||
           expeditionRun.captureAttemptedWave==expeditionRun.wave)
            return false;
        CaptureNetDefinition net=CaptureNetCatalog.Get(
            pendingCapture.captureNetItemId);
        if(net==null)return false;
        expeditionRun.captureAttemptedWave=expeditionRun.wave;
        expeditionRun.captureAttemptSequence++;
        expeditionRun.selectedCaptureEnemyInstanceId="";
        expeditionRun.selectedCaptureNetItemId="";
        if(!CaptureNetInventory.TryConsume(
               playerProfile,net.itemId,out string consumeError))
        {
            pendingCapture.Clear();
            captureTarget=null;
            captureUiMessage=consumeError;
            SaveExpeditionCheckpoint(
                ExpeditionRunCheckpoint.Preparation,false);
            return false;
        }
        string instanceId="player_capture_"+target.definition.monsterId+"_"+
                          DateTime.UtcNow.ToString("yyyyMMddHHmmssfff")+"_"+
                          Guid.NewGuid().ToString("N").Substring(0,6);
        int rollSeed=MonsterInstanceGenerator.StableSeed(
            expeditionRun.runId+"_capture_"+expeditionRun.wave+"_"+
            expeditionRun.captureAttemptSequence+"_"+target.stableId+"_"+
            net.itemId);
        float roll=(float)new System.Random(rollSeed).NextDouble();
        bool succeeded=pendingCapture.ResolveDefeat(
            target.ownedInstance,target.definition,
            EffectiveCaptureChance(net),roll,instanceId,
            expeditionRun.difficulty);
        OwnedMonsterSave captured=succeeded?CommitPendingCapture():null;
        capturePresentationMonster=captured;
        if(!succeeded)pendingCapture.Clear();
        capturePresentationTarget=target;
        capturePresentationSucceeded=succeeded;
        capturePresentationResolving=false;
        captureUiMessage="포획 판정 대기 · 전투 종료 후 확인";
        captureTarget=null;
        if(captured!=null)
        {
            if(!expeditionRun.capturedMonsterInstanceIds.Contains(
                   captured.instanceId))
                expeditionRun.capturedMonsterInstanceIds.Add(
                    captured.instanceId);
            GameFlowController.Instance.Run.RegisterCapturedMonster(
                captured.instanceId);
        }
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,false);
        return true;
    }

    private void BeginCaptureDeparture(Unit target,Vector3 impact)
    {
        if(target==null||target.model==null)return;
        capturePresentationOriginalScale=target.model.transform.localScale;
        capturePresentationImpact=impact;
        capturePresentationStartedAt=Time.time;
        if(target.reaction!=null)target.reaction.PlayCaptureHold();
        else if(target.spriteAnimation!=null)
            target.spriteAnimation.SetStruggling(true);
        if(target.captureDeparture!=null)StopCoroutine(target.captureDeparture);
        target.captureDeparture=StartCoroutine(PlayCaptureDeparture(target));
    }

    private IEnumerator PlayCaptureDeparture(Unit target)
    {
        const float riseDuration=0.65f;
        Transform model=target.model.transform;
        Vector3 startPosition=model.position;
        Vector3 startScale=model.localScale;
        float elapsed=0f;
        while(elapsed<riseDuration&&model!=null)
        {
            elapsed+=Time.deltaTime;
            float ratio=Mathf.Clamp01(elapsed/riseDuration);
            float eased=1f-(1f-ratio)*(1f-ratio);
            model.position=Vector3.Lerp(startPosition,CaptureWaitingPoint(target),eased);
            model.localScale=startScale;
            yield return null;
        }
        float hoverStarted=Time.time;
        while(model!=null&&capturePresentationTarget==target&&
              !capturePresentationResolving)
        {
            model.position=CaptureWaitingPoint(target)+Vector3.up*
                (Mathf.Sin((Time.time-hoverStarted)*4.8f)*0.08f);
            model.localScale=startScale;
            yield return null;
        }
        target.captureDeparture=null;
    }

    private void BeginCaptureOutcomePresentation()
    {
        if(capturePresentationTarget==null||capturePresentationResolving)return;
        capturePresentationResolving=true;
        ResetAllOutlines();
        if(capturePresentationTarget.captureDeparture!=null)
        {
            StopCoroutine(capturePresentationTarget.captureDeparture);
            capturePresentationTarget.captureDeparture=null;
        }
        capturePresentationRoutine=StartCoroutine(
            PlayCaptureOutcomePresentation());
    }

    private IEnumerator PlayCaptureOutcomePresentation()
    {
        Unit target=capturePresentationTarget;
        if(target==null||target.model==null)
        {
            capturePresentationRoutine=null;
            ClearCapturePresentation();
            yield break;
        }
        yield return PlayCaptureFocus(target);
        if(target.model==null)
        {
            capturePresentationRoutine=null;
            ClearCapturePresentation();
            yield break;
        }
        if(capturePresentationSucceeded)
        {
            yield return PlayCaptureParcel(target);
            target.reaction?.FinishCapturedDeath();
            if(target.model!=null)target.model.SetActive(false);
        }
        yield return PlayCaptureResult(target);
        if(capturePresentationShade!=null)
        {
            SpriteRenderer shade=capturePresentationShade.GetComponent<SpriteRenderer>();
            for(float elapsed=0f;elapsed<0.25f;elapsed+=Time.deltaTime)
            {
                if(shade==null)break;
                shade.color=new Color(0f,0f,0f,1f-Mathf.Clamp01(elapsed/0.25f));
                yield return null;
            }
        }
        capturePresentationRoutine=null;
        ClearCapturePresentation();
    }

    private IEnumerator PlayCaptureResult(Unit target)
    {
        capturePresentationResultStartedAt=Time.unscaledTime;
        captureResultSkipAt=-1f;captureRevealSoundMask=0;
        captureUiMessage=capturePresentationSucceeded
            ?GameLocalization.TextByKey("battle.capture_success","포획 성공")
            :GameLocalization.TextByKey("capture.failure","포획 실패");
        if(capturePresentationSucceeded)
            GameAudio.PlayCapture(GameAudio.CaptureCue.Success);
        else
        {
            if(target.reaction!=null)
                target.reaction.ResolveCaptureFailure(
                    capturePresentationImpact,
                    ()=>GameAudio.PlayCapture(GameAudio.CaptureCue.Failure));
            else if(target.spriteAnimation!=null)
            {
                target.spriteAnimation.SetStruggling(false);
                target.spriteAnimation.PlayDeath();
                GameAudio.PlayCapture(GameAudio.CaptureCue.Failure);
            }
            else
            {
                target.model.SetActive(false);
                GameAudio.PlayCapture(GameAudio.CaptureCue.Failure);
            }
        }
        if(capturePresentationSucceeded&&capturePresentationMonster!=null)
        {
            while(captureResultSkipAt<0f
                ?Time.unscaledTime-capturePresentationResultStartedAt<MonsterAcquisitionReveal.ReadyAt+.42f
                :Time.unscaledTime-captureResultSkipAt<.42f)
            {
                UpdateCaptureAcquisitionAudio(Time.unscaledTime-capturePresentationResultStartedAt);
                yield return null;
            }
        }
        else yield return new WaitForSeconds(1.2f);
    }

    private void UpdateCaptureAcquisitionAudio(float age)
    {
        if(capturePresentationMonster==null)return;
        bool tick=false;int newest=0;
        for(int stat=0;stat<MonsterAcquisitionReveal.StatCount;stat++)
            if(age>=MonsterAcquisitionReveal.StatAt(stat)&&
               (captureRevealSoundMask&(1<<stat))==0)
            {captureRevealSoundMask|=1<<stat;tick=true;newest=stat;}
        if(tick)GameAudio.PlayChest(GameAudio.ChestCue.Stat,false,newest,
            MonsterAcquisitionReveal.StatQualityTier(capturePresentationMonster,newest));
        const int stamp=1<<MonsterAcquisitionReveal.StatCount;
        if(age>=MonsterAcquisitionReveal.StampAt&&(captureRevealSoundMask&stamp)==0)
        {
            captureRevealSoundMask|=stamp;
            GameAudio.PlayChest(GameAudio.ChestCue.Reveal,capturePresentationMonster.isShiny,0,
                ChestRewardPresentation.QualityTier(capturePresentationMonster));
        }
    }

    private Vector3 CaptureWaitingPoint(Unit target)
    {
        Bounds bounds=combatBounds.size.x>0f?combatBounds:mapBounds;
        Camera camera=mainCamera==null?Camera.main:mainCamera;
        if(camera==null)return new Vector3(bounds.center.x,4.5f,bounds.max.z);
        float depth=Mathf.Max(camera.nearClipPlane+1f,
            camera.WorldToViewportPoint(bounds.center).z);
        SpriteRenderer renderer=target.spriteAnimation==null
            ?target.model.GetComponentInChildren<SpriteRenderer>()
            :target.spriteAnimation.GetComponent<SpriteRenderer>();
        Vector3 offset=Vector3.zero;
        float halfHeight=0f;
        if(renderer!=null)
        {
            offset=renderer.bounds.center-target.model.transform.position;
            Vector3 up=camera.transform.up;
            Vector3 extent=renderer.bounds.extents;
            float height=Vector3.Distance(
                camera.ViewportToWorldPoint(new Vector3(.5f,0f,depth)),
                camera.ViewportToWorldPoint(new Vector3(.5f,1f,depth)));
            halfHeight=(Mathf.Abs(up.x)*extent.x+Mathf.Abs(up.y)*extent.y+
                Mathf.Abs(up.z)*extent.z)/height;
        }
        // Keep the silhouette above the painted platform, with headroom for hovering.
        float y=Mathf.Min(.9f+halfHeight,.98f-halfHeight);
        return camera.ViewportToWorldPoint(new Vector3(.5f,y,depth))-offset;
    }

    private IEnumerator PlayCaptureFocus(Unit target)
    {
        Transform model=target.model.transform;
        SpriteRenderer targetRenderer=target.spriteAnimation==null
            ?target.model.GetComponentInChildren<SpriteRenderer>()
            :target.spriteAnimation.GetComponent<SpriteRenderer>();
        capturePresentationTargetRenderer=targetRenderer;
        if(targetRenderer!=null)
        {
            capturePresentationTargetSortingOrder=targetRenderer.sortingOrder;
            targetRenderer.sortingOrder=CaptureFocusSortingOrder+4;
        }
        capturePresentationShade=CreateCaptureFocusShade(targetRenderer);
        SpriteRenderer shade=capturePresentationShade==null?null:
            capturePresentationShade.GetComponent<SpriteRenderer>();
        for(float elapsed=0f;elapsed<0.24f;elapsed+=Time.deltaTime)
        {
            if(shade!=null)shade.color=new Color(0f,0f,0f,
                Mathf.SmoothStep(0f,1f,elapsed/0.24f));
            yield return null;
        }
        if(shade!=null)shade.color=Color.black;
        Vector3 start=model.position;
        Vector3 scale=model.localScale;
        Vector3 focus=CaptureParcelCenter()+Vector3.up*2.2f;
        for(float elapsed=0f;elapsed<0.48f&&model!=null;elapsed+=Time.deltaTime)
        {
            float t=Mathf.SmoothStep(0f,1f,elapsed/0.48f);
            model.position=Vector3.Lerp(start,focus,t);
            model.localScale=Vector3.Lerp(scale,scale*2f,t);
            yield return null;
        }
        if(model==null)yield break;
        model.position=focus;model.localScale=scale*2f;
        for(int beat=0;beat<CaptureHeartbeatBeats.Length&&model!=null;beat++)
        {
            float strength=Mathf.Lerp(0.7f,1f,beat/(float)(CaptureHeartbeatBeats.Length-1));
            GameAudio.PlayCapture(GameAudio.CaptureCue.Beat,strength);
            float duration=CaptureHeartbeatBeats[beat];
            for(float elapsed=0f;elapsed<duration&&model!=null;elapsed+=Time.deltaTime)
            {
                UpdateCaptureHeartbeat(targetRenderer,elapsed,duration,strength);
                yield return null;
            }
            UpdateCaptureHeartbeat(targetRenderer,duration,duration,strength);
        }
        if(model!=null)model.position=focus;
    }

    private void UpdateCaptureHeartbeat(SpriteRenderer source,float elapsed,float duration,float strength)
    {
        if(source==null||source.sprite==null)return;
        if(captureHeartbeatRoot==null)
        {
            captureHeartbeatRoot=new GameObject("Capture Heartbeat Echoes");
            captureHeartbeatRoot.transform.SetParent(transform,true);
            captureHeartbeatEchoes=new SpriteRenderer[2];
            for(int i=0;i<captureHeartbeatEchoes.Length;i++)
            {
                var echo=Rank3CombatFx.Ghost("Capture Silhouette Pulse",source,
                    source.transform.position,Color.clear,1f,1f);
                echo.GetComponent<Rank3FxLifetime>().enabled=false;
                echo.transform.SetParent(captureHeartbeatRoot.transform,true);
                echo.sortingOrder=source.sortingOrder-2-i;
                captureHeartbeatEchoes[i]=echo;
            }
        }
        for(int i=0;i<captureHeartbeatEchoes.Length;i++)
        {
            SpriteRenderer echo=captureHeartbeatEchoes[i];
            if(elapsed<=0f)
            {
                echo.sprite=source.sprite;
                echo.flipX=source.flipX;echo.flipY=source.flipY;
                echo.transform.rotation=source.transform.rotation;
            }
            float delay=i*Mathf.Min(0.075f,duration*0.18f);
            float t=Mathf.Clamp01((elapsed-delay)/Mathf.Min(0.36f,duration-delay));
            float expansion=1f+(0.65f+0.25f*strength)*(1f-(1f-t)*(1f-t));
            echo.transform.localScale=source.transform.lossyScale*expansion;
            // Expand around the visible silhouette center, not the sprite's foot pivot.
            echo.transform.position+=source.bounds.center-echo.bounds.center;
            echo.color=new Color(1f,1f,1f,
                elapsed<delay?0f:(i==0?0.42f:0.28f)*strength*(1f-t)*(1f-t));
        }
    }

    private IEnumerator PlayCaptureParcel(Unit target)
    {
        Transform model=target.model.transform;
        SpriteRenderer targetRenderer=capturePresentationTargetRenderer;
        GameObject parcelObject=new GameObject("Pixel Capture Parcel");
        parcelObject.transform.SetParent(transform,true);
        capturePresentationVisual=parcelObject;
        SpriteRenderer parcel=parcelObject.AddComponent<SpriteRenderer>();
        Sprite[] frames=CaptureParcelFrames;
        if(frames.Length<3)
        {
            Destroy(parcelObject);
            capturePresentationVisual=null;
            model.gameObject.SetActive(false);
            yield break;
        }
        parcel.sprite=frames[0];
        GameObject frontObject=new GameObject("Parcel Front Wall");
        frontObject.transform.SetParent(parcelObject.transform,false);
        SpriteRenderer front=frontObject.AddComponent<SpriteRenderer>();
        front.sprite=CaptureParcelOpenFront;
        if(targetRenderer!=null)
        {
            parcel.sortingLayerID=targetRenderer.sortingLayerID;
            parcel.sortingOrder=CaptureFocusSortingOrder+2;
            front.sortingLayerID=targetRenderer.sortingLayerID;
            front.sortingOrder=CaptureFocusSortingOrder+6;
            parcelObject.transform.rotation=targetRenderer.transform.rotation;
        }
        else
        {
            parcel.sortingOrder=CaptureFocusSortingOrder+2;
            front.sortingOrder=CaptureFocusSortingOrder+6;
        }
        float targetWidth=targetRenderer==null
            ?1.6f:Mathf.Max(0.8f,targetRenderer.bounds.size.x);
        float parcelScale=Mathf.Clamp(
            targetWidth*2.35f/frames[0].bounds.size.x,0.58f,3.1f);
        Vector3 fullScale=Vector3.one*parcelScale;
        Vector3 parcelCenter=CaptureParcelCenter();
        parcelObject.transform.position=parcelCenter;
        parcelObject.transform.localScale=Vector3.zero;
        float elapsed=0f;
        const float appearDuration=0.3f;
        while(elapsed<appearDuration&&model!=null)
        {
            elapsed+=Time.deltaTime;
            float ratio=Mathf.Clamp01(elapsed/appearDuration);
            parcelObject.transform.localScale=fullScale*
                BombBrickUiTheme.EaseOutBack(ratio,0.55f);
            yield return null;
        }
        yield return new WaitForSeconds(0.14f);

        Vector3 monsterScale=model.localScale;
        Vector3 presentationScale=monsterScale;
        Vector3 aboveParcel=model.position;

        Vector3 monsterEnd=parcelCenter+Vector3.up*0.08f;
        elapsed=0f;
        const float dropDuration=0.44f;
        while(elapsed<dropDuration&&model!=null)
        {
            elapsed+=Time.deltaTime;
            float ratio=Mathf.Clamp01(elapsed/dropDuration);
            float fall=ratio*ratio;
            model.position=Vector3.Lerp(aboveParcel,monsterEnd,fall);
            float scaleStep=Mathf.Floor(Mathf.Clamp01(
                (fall-0.35f)/0.65f)*4f)/4f;
            model.localScale=Vector3.Lerp(
                presentationScale,presentationScale*0.42f,scaleStep);
            yield return null;
        }
        if(model==null)
        {
            Destroy(parcelObject);
            capturePresentationVisual=null;
            yield break;
        }

        parcel.sortingOrder=CaptureFocusSortingOrder+6;
        front.enabled=false;
        parcel.sprite=frames[1];
        yield return new WaitForSeconds(0.18f);
        parcel.sprite=frames[2];
        model.gameObject.SetActive(false);

        elapsed=0f;
        const float sealBounceDuration=0.26f;
        while(elapsed<sealBounceDuration)
        {
            elapsed+=Time.deltaTime;
            float ratio=Mathf.Clamp01(elapsed/sealBounceDuration);
            float pulse=Mathf.Sin(ratio*Mathf.PI);
            parcelObject.transform.localScale=new Vector3(
                fullScale.x*(1f+0.09f*pulse),
                fullScale.y*(1f-0.13f*pulse),
                fullScale.z);
            yield return null;
        }
        yield return new WaitForSeconds(0.12f);

        Vector3 launchStart=parcelObject.transform.position;
        Vector3 launchEnd=CaptureParcelScreenTopExit(launchStart);
        elapsed=0f;
        const float launchDuration=0.95f;
        while(elapsed<launchDuration)
        {
            elapsed+=Time.deltaTime;
            float ratio=Mathf.Clamp01(elapsed/launchDuration);
            float eased=ratio*ratio;
            parcelObject.transform.position=Vector3.Lerp(
                launchStart,launchEnd,eased);
            parcelObject.transform.localScale=fullScale;
            yield return null;
        }
        Destroy(parcelObject);
        capturePresentationVisual=null;
    }

    private GameObject CreateCaptureFocusShade(SpriteRenderer targetRenderer)
    {
        Camera camera=mainCamera==null?Camera.main:mainCamera;
        if(camera==null)return null;
        GameObject shadeObject=new GameObject("Capture Focus Shade");
        shadeObject.transform.SetParent(transform,true);
        SpriteRenderer shade=shadeObject.AddComponent<SpriteRenderer>();
        shade.sprite=CaptureFocusShadeSprite;
        shade.color=Color.clear;
        if(targetRenderer!=null)shade.sortingLayerID=targetRenderer.sortingLayerID;
        shade.sortingOrder=CaptureFocusSortingOrder;
        float distance=Mathf.Max(camera.nearClipPlane+0.1f,1f);
        float height=camera.orthographic
            ?camera.orthographicSize*2f
            :2f*distance*Mathf.Tan(camera.fieldOfView*Mathf.Deg2Rad*0.5f);
        shadeObject.transform.position=camera.transform.position+
                                       camera.transform.forward*distance;
        shadeObject.transform.rotation=camera.transform.rotation;
        shadeObject.transform.localScale=new Vector3(
            height*camera.aspect*1.1f,height*1.1f,1f);
        return shadeObject;
    }

    private Vector3 CaptureParcelCenter()
    {
        Camera camera=mainCamera==null?Camera.main:mainCamera;
        if(camera!=null)
        {
            Ray ray=camera.ViewportPointToRay(
                new Vector3(0.5f,0.48f,0f));
            Plane ground=new Plane(Vector3.up,Vector3.zero);
            if(ground.Raycast(ray,out float distance))
                return ray.GetPoint(distance)+Vector3.up*0.9f;
        }
        return new Vector3(mapBounds.center.x,0.9f,mapBounds.center.z);
    }

    private Vector3 CaptureParcelScreenTopExit(Vector3 start)
    {
        Camera camera=mainCamera==null?Camera.main:mainCamera;
        if(camera==null)return start+Vector3.up*14f;
        Vector3 screen=camera.WorldToScreenPoint(start);
        screen.y=Screen.height+320f;
        return camera.ScreenToWorldPoint(screen);
    }

    private static Sprite[] CaptureParcelFrames
    {
        get
        {
            if(captureParcelFrames!=null)return captureParcelFrames;
            Texture2D sheet=Resources.Load<Texture2D>(
                "CombatEffects/Capture/capture_parcel_sheet");
            if(sheet==null)return Array.Empty<Sprite>();
            int frameWidth=sheet.width/3;
            captureParcelFrames=new Sprite[3];
            for(int frame=0;frame<captureParcelFrames.Length;frame++)
            {
                Sprite sprite=Sprite.Create(
                    sheet,new Rect(frame*frameWidth,0f,frameWidth,sheet.height),
                    new Vector2(0.5f,0.5f),128f);
                sprite.name="Capture Parcel "+frame;
                sprite.hideFlags=HideFlags.HideAndDontSave;
                captureParcelFrames[frame]=sprite;
            }
            return captureParcelFrames;
        }
    }

    private static Sprite CaptureParcelOpenFront
    {
        get
        {
            if(captureParcelOpenFront!=null)return captureParcelOpenFront;
            Texture2D sheet=Resources.Load<Texture2D>(
                "CombatEffects/Capture/capture_parcel_sheet");
            if(sheet==null)return null;
            int frameWidth=sheet.width/3;
            int frontHeight=Mathf.RoundToInt(sheet.height*0.58f);
            captureParcelOpenFront=Sprite.Create(
                sheet,new Rect(0f,0f,frameWidth,frontHeight),
                new Vector2(0.5f,sheet.height*0.5f/frontHeight),128f);
            captureParcelOpenFront.name="Capture Parcel Front Wall";
            captureParcelOpenFront.hideFlags=HideFlags.HideAndDontSave;
            return captureParcelOpenFront;
        }
    }

    private static Sprite CaptureFocusShadeSprite
    {
        get
        {
            if(captureFocusShadeSprite!=null)return captureFocusShadeSprite;
            Texture2D texture=new Texture2D(1,1,TextureFormat.RGBA32,false)
            {
                filterMode=FilterMode.Point,
                wrapMode=TextureWrapMode.Clamp,
                hideFlags=HideFlags.HideAndDontSave
            };
            texture.SetPixel(0,0,Color.white);
            texture.Apply(false,true);
            captureFocusShadeSprite=Sprite.Create(
                texture,new Rect(0f,0f,1f,1f),new Vector2(0.5f,0.5f),1f);
            captureFocusShadeSprite.name="Capture Focus Shade";
            captureFocusShadeSprite.hideFlags=HideFlags.HideAndDontSave;
            return captureFocusShadeSprite;
        }
    }

    private void ClearCapturePresentation()
    {
        if(captureHeartbeatRoot!=null)
        {
            if(Application.isPlaying)Destroy(captureHeartbeatRoot);
            else DestroyImmediate(captureHeartbeatRoot);
        }
        captureHeartbeatRoot=null;
        captureHeartbeatEchoes=null;
        if(capturePresentationTarget!=null&&capturePresentationTarget.model!=null&&
           capturePresentationOriginalScale!=Vector3.zero)
            capturePresentationTarget.model.transform.localScale=capturePresentationOriginalScale;
        capturePresentationOriginalScale=Vector3.zero;
        if(capturePresentationTargetRenderer!=null)
            capturePresentationTargetRenderer.sortingOrder=
                capturePresentationTargetSortingOrder;
        capturePresentationTargetRenderer=null;
        if(capturePresentationShade!=null)
        {
            Destroy(capturePresentationShade);
            capturePresentationShade=null;
        }
        capturePresentationTarget=null;
        capturePresentationMonster=null;captureResultSkipAt=-1f;captureRevealSoundMask=0;
        capturePresentationSucceeded=false;
        capturePresentationResolving=false;
        capturePresentationImpact=Vector3.zero;
        capturePresentationStartedAt=-1f;
        capturePresentationResultStartedAt=-1f;
    }

    private void CancelCapturePresentation()
    {
        if(capturePresentationRoutine!=null)
        {
            StopCoroutine(capturePresentationRoutine);
            capturePresentationRoutine=null;
        }
        if(capturePresentationTarget!=null&&
           capturePresentationTarget.captureDeparture!=null)
        {
            StopCoroutine(capturePresentationTarget.captureDeparture);
            capturePresentationTarget.captureDeparture=null;
        }
        if(capturePresentationVisual!=null)
        {
            Destroy(capturePresentationVisual);
            capturePresentationVisual=null;
        }
        ClearCapturePresentation();
    }

    private float CurrentAttackInterval(Unit unit)
    {
        float interval=unit.attackInterval;
        float bonus=unit.itemPermanentAttackSpeedBonus+
            (unit.itemAttackSpeedTimer>0f?unit.itemAttackSpeedBonus:0f)+
            (unit.itemPostSkillAttackSpeedTimer>0f
                ?unit.itemPostSkillAttackSpeedBonus:0f)+
            (unit.itemStatusRecoveryAttackSpeedTimer>0f
                ?unit.itemStatusRecoveryAttackSpeedBonus:0f);
        float slow=HaetaeOppressionAffects(unit,false)?HaetaeRank3Rules.OppressionSlow:0f;
        for(int i=unit.growthKillHasteExpirations.Count-1;i>=0;i--)
            if(unit.growthKillHasteExpirations[i]<=battleElapsed)
                unit.growthKillHasteExpirations.RemoveAt(i);
        bonus+=unit.growthKillHasteExpirations.Count*
            GrowthModifiers(unit.team).killTeamAttackSpeedBonus;
        if(unit.bearResolveTimer>0f)
            bonus+=unit.bearResolveAttackSpeedBonus*BearResolveStrength(unit);
        if(unit.bearResolveTimer>0f&&!unit.combatStatuses.BenefitsBlocked)
            bonus+=BearCombatRules.BerberAttackSpeed(unit.bearFrenzyStacks);
        if(unit.frogRoyalAttackSpeedTimer>0f)bonus+=FrogCombatRules.RoyalAttackSpeedBonus*unit.frogRoyalBuffScale;
        bonus+=CurrentFrogStolenBuff(unit,FrogStolenBuffKind.AttackSpeed);
        if(unit.giraffeDanceAttackSpeedTimer>0f)bonus+=GiraffeCombatRules.MoonwalkAttackSpeedBonus;
        if(unit.kingKongRallyTimer>0f)bonus+=KingKongCombatRules.RallyAttackSpeedBonus;
        if(unit.familyAttackSpeedTimer>0f)bonus+=unit.familyAttackSpeedBonus;
        if(unit.rank3AttackSpeedBonusTimer>0f)
            bonus+=unit.rank3AttackSpeedBonusRatio;
        if(unit.kingKongSlowTimer>0f)
            slow=CombatStatFormula.Strongest(slow,KingKongCombatRules.GlacialSlowRatio);
        if(unit.combatStatuses.Has(CombatStatusKind.HallucinatoryPollen))
            slow=CombatStatFormula.Strongest(slow,MantisCombatRules.PollenAttackSpeedSlow);
        CombatStatusEffect intimidation=unit.combatStatuses.Get(CombatStatusKind.AttackSpeedDown);
        if(intimidation!=null)slow=CombatStatFormula.Strongest(slow,intimidation.magnitude);
        CombatStatusEffect fangLock=unit.combatStatuses.Get(CombatStatusKind.Root);
        if(fangLock!=null)slow=CombatStatFormula.Strongest(slow,fangLock.magnitude);
        if(unit.team==Team.Player&&unit.hp<=unit.maxHp*0.4f)
            bonus+=GrowthModifiers(unit.team).lowHealthAttackSpeedBonus;
        if(unit.augmentClimaxTimer>0f)
            bonus+=ExpeditionAugmentRuntime.ProtagonistParam(
                "climax_attack_speed",0.20f);
        if(unit.augmentTranscended&&IsRaptorFamily(unit)&&
           unit.raptorApexPredatorTimer>0f)
            bonus+=ExpeditionAugmentRuntime.TranscendenceParam(
                "raptor_apex_attack_speed_bonus",
                RaptorCombatRules.ApexPredatorAttackSpeedBonus);
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_rank2_pursuit")&&
           unit.traitState.sameTargetHits>=3)bonus+=0.15f;
        CombatStatusEffect rally=unit.combatStatuses.Get(CombatStatusKind.ComboRally);
        if(rally!=null)bonus+=Mathf.Max(0f,rally.magnitude);
        return CombatStatFormula.AttackInterval(interval,bonus,slow);
    }

    private static float BearResolveStrength(Unit unit)
    {
        return unit.combatStatuses.BenefitsBlocked?0f:1f;
    }

    private float HostileStatusDuration(Unit target,float baseDuration)
    {
        if(target!=null&&target.combatStatuses.RejectHarmfulEffect())return 0f;
        if(target!=null&&target.itemOpeningImmunityTimer>0f)return 0f;
        Unit source=target==null?null:target.recentAttacker;
        if(source!=null&&MonsterTraitRuntime.Has(source.activeTraitIds,"trait_rank2_suppression")&&
           (target.combatStatuses.Has(CombatStatusKind.Airborne)||
            target.combatStatuses.Has(CombatStatusKind.Knockdown)||
            target.combatStatuses.Has(CombatStatusKind.Root)||
            target.combatStatuses.Has(CombatStatusKind.Displaced)))baseDuration*=1.2f;
        if(source!=null&&MonsterTraitRuntime.Has(source.activeTraitIds,"trait_rank2_elemental")&&
           (target.combatStatuses.Has(CombatStatusKind.ComboChilled)||
            target.combatStatuses.Has(CombatStatusKind.Poison)||
            target.combatStatuses.Has(CombatStatusKind.Burning)||
            target.combatStatuses.Has(CombatStatusKind.ComboBurning)||
            target.combatStatuses.Has(CombatStatusKind.Bleed)||
            target.combatStatuses.Has(CombatStatusKind.Freeze)))baseDuration*=1.25f;
        float duration=CombatStatusResistance.Apply(
            baseDuration,target==null?0f:CurrentStatusResistance(target));
        if(target!=null)
            duration*=Mathf.Clamp(target.augmentHarmfulDurationMultiplier,0f,1f);
        if(target!=null&&duration<baseDuration&&
           GrowthModifiers(target.team).statusRecoveryDamageTakenMultiplier<1f)
            target.growthStatusRecoveryGuardTimer=GateHaetaeBenefit(target,5f);
        return duration;
    }

    private float CurrentDefense(Unit unit)
    {
        if(unit==null)return 0f;
        float value=unit.defense+unit.itemDefenseRamp+
            (unit.itemTemporaryStatTimer>0f?unit.itemTemporaryDefenseBonus:0f)+
            (unit.itemPostSkillStatTimer>0f?unit.itemPostSkillDefenseBonus:0f)+
            (unit.itemTwilightStatTimer>0f?unit.itemTwilightDefenseBonus:0f);
        value+=Mathf.Max(0f,CurrentFrogStolenBuff(unit,FrogStolenBuffKind.Defense));
        value*=1f+CurrentFrogStolenBuff(unit,FrogStolenBuffKind.DefenseRatio);
        if(unit.fangLockTimer>0f&&MonsterTraitRuntime.Has(
               unit.activeTraitIds,SabertoothCombatRules.TerakanTraitId))
            value*=1f+SabertoothCombatRules.StoneDefenseBonus;
        if(unit.bearResolveTimer>0f&&!unit.combatStatuses.BenefitsBlocked&&MonsterTraitRuntime.Has(
               unit.activeTraitIds,BearCombatRules.IronKumaTraitId))
            value*=1f+BearCombatRules.IronKumaDefenseBonus;
        if(unit.rank3DefenseBonusTimer>0f)
            value*=1f+unit.rank3DefenseBonusRatio;
        int targeting=units.Count(enemy=>IsCombatActive(enemy)&&enemy.team!=unit.team&&enemy.target==unit);
        value+=targeting*EffectSum(unit,"TargetingEnemyDefenseResistance",row=>row.effectParam1);
        float shred=CombatStatFormula.Strongest(
            unit.itemDefenseShredRatio,unit.familyResistanceShredRatio);
        CombatStatusEffect broken=unit.combatStatuses.Get(CombatStatusKind.ArmorBroken);
        if(broken!=null)shred=CombatStatFormula.Strongest(shred,broken.magnitude);
        return Mathf.Max(0f,value*(1f-Mathf.Clamp01(shred)));
    }

    private float CurrentStatusResistance(Unit unit)
    {
        if(unit==null)return 0f;
        int targeting=units.Count(enemy=>IsCombatActive(enemy)&&enemy.team!=unit.team&&enemy.target==unit);
        float value=unit.statusResistance+unit.itemResistanceRamp+
            (unit.itemTemporaryStatTimer>0f?unit.itemTemporaryResistanceBonus:0f)+
            (unit.itemPostSkillStatTimer>0f?unit.itemPostSkillResistanceBonus:0f)+
            (unit.itemTwilightStatTimer>0f?unit.itemTwilightResistanceBonus:0f)+
            targeting*EffectSum(unit,"TargetingEnemyDefenseResistance",row=>row.effectParam2);
        value+=CurrentFrogStolenBuff(unit,FrogStolenBuffKind.Resistance);
        value*=1f+CurrentFrogStolenBuff(unit,FrogStolenBuffKind.ResistanceRatio);
        if(unit.frogRoyalAttackSpeedTimer>0f)
            value*=1f+FrogCombatRules.RoyalResistanceBonus*unit.frogRoyalBuffScale;
        float flatReduction=0f;
        foreach(Unit enemy in units)
        {
            if(!IsCombatActive(enemy)||enemy.team==unit.team)continue;
            float distance=Vector3.Distance(
                Flat(enemy.model.transform.position),Flat(unit.model.transform.position));
            foreach(ItemMasterRow item in enemy.itemModifiers.specialEffects)
                if(item.specialEffect=="NearbyStatusResistanceReduction"&&
                   distance<=TileSize*Mathf.Max(0f,item.effectParam1))
                    flatReduction=CombatStatFormula.Strongest(
                        flatReduction,item.effectParam2);
        }
        if(unit.corruptStatusResistanceReductionTimer>0f)
            flatReduction=CombatStatFormula.Strongest(
                flatReduction,unit.corruptStatusResistanceReduction);
        if(unit.combatStatuses.DebuffImmune)flatReduction=0f;
        value-=flatReduction;
        float shred=0f;
        if(unit.tyrannoResistanceShredTimer>0f)
            shred=CombatStatFormula.Strongest(shred,unit.tyrannoResistanceShredRatio);
        if(unit.familyResistanceShredTimer>0f)
            shred=CombatStatFormula.Strongest(shred,unit.familyResistanceShredRatio);
        value*=1f-Mathf.Clamp01(shred);
        if(MonsterTraitRuntime.Has(unit.activeTraitIds,"trait_rank2_crisis")&&
           unit.hp<=unit.maxHp*0.4f)value+=20f;
        return Mathf.Max(0f,value);
    }

    private float ApplySkillDamage(Unit source,Unit target,float damage,bool triggerTraits=true)
    {
        return ApplySkillDamage(source,target,
            new SkillDamageFormulaResult(damage,0f,0f),triggerTraits);
    }

    private float ApplyGroundSkillDamage(Unit source,Unit target,float damage,bool triggerTraits=true)
    {
        bool previous=readabilityGroundImpact;
        readabilityGroundImpact=true;
        try
        {
        return ApplySkillDamage(source,target,
            new SkillDamageFormulaResult(damage,0f,0f),triggerTraits,allowHitSlide:false,bypassProjectileWalls:true);
        }
        finally {readabilityGroundImpact=previous;}
    }

    private float ApplySkillFormulaDamage(Unit source,Unit target,SkillMasterRow skill,
        bool secondary=false,int consumedStacks=0,float effectScale=1f,bool triggerTraits=true)
    {
        if(source==null||target==null||skill==null)return 0f;
        SkillDamageFormulaResult formula=SkillDamageFormulaResolver.Resolve(
            skill,SkillPower(source),OffensiveMaxHealth(source),target.hp,target.maxHp,secondary,consumedStacks);
        float scale=Mathf.Max(0f,effectScale);
        return ApplySkillDamage(source,target,new SkillDamageFormulaResult(
            formula.physicalDamage*scale,formula.trueDamage*scale,
            formula.defenseIgnoreRatio),triggerTraits);
    }

    private float ApplySkillDamage(Unit source,Unit target,
        SkillDamageFormulaResult formula,bool triggerTraits=true,
        float shieldDamageMultiplier=1f,bool markSabertoothPrey=false,bool triggerTeamTraits=true,
        bool applyTraitMultiplier=true,bool allowHitSlide=true,bool bypassProjectileWalls=false)
    {
        bool previousSkillCritical=source.lastSkillCritical;
        source.lastSkillCritical=false;
        source.lastSkillHitCritical=false;
        float physicalDamage=formula.physicalDamage;
        float trueDamage=formula.trueDamage;
        float skillMultiplier=(applyTraitMultiplier?Mathf.Max(0.01f,source.skillTraitDamageMultiplier):1f)*
                              (1f+source.itemModifiers.skillPowerBonus+source.itemSkillPowerRamp+
                                  GrowthModifiers(source.team).skillPowerBonus)*
                              source.augmentSkillPowerMultiplier;
        physicalDamage*=skillMultiplier;
        trueDamage*=skillMultiplier;
        float criticalChance=source.itemModifiers.criticalChance;
        if(HasEffect(source,"SkillCritical")&&UnityEngine.Random.value<
           CombatStatFormula.CriticalChance(criticalChance))
        {
            source.lastSkillCritical=true;
            source.lastSkillHitCritical=true;
            float criticalMultiplier=CombatStatFormula.CriticalDamageMultiplier(
                criticalChance,source.itemModifiers.criticalDamageBonus);
            physicalDamage*=criticalMultiplier;
            trueDamage*=criticalMultiplier;
            ApplyCriticalItemEffects(source,target);
        }
        float traitBaseDamage=physicalDamage+trueDamage;
        Vector3 impactPosition=target==null||target.model==null?Vector3.zero:Flat(target.model.transform.position);
        bool wasAlive=IsCombatActive(target);
        float dealt=ApplyDamageComponents(source,target,physicalDamage,true,false,triggerTeamTraits,true,
            formula.defenseIgnoreRatio,trueDamage,shieldDamageMultiplier,
            false,false,markSabertoothPrey,0f,skillImpact:true,allowHitSlide:allowHitSlide,
            bypassProjectileWalls:bypassProjectileWalls);
        source.lastSkillCritical|=previousSkillCritical;
        if(dealt>0f&&IsCombatActive(target))
        {
            foreach(ItemMasterRow item in source.itemModifiers.specialEffects)
                if(item.specialEffect=="SkillPlague")
                    ApplyItemBurn(source,target,item.effectParam1,item.effectParam2,item.effectParam3);
        }
        if(!triggerTraits||!wasAlive||dealt<=0f)return dealt;

        if(MonsterTraitRuntime.RecordSkillHit(source.activeTraitIds,source.traitState,
            target==null?"":target.stableId))source.traitActivations++;

        MonsterCombatTag tags=MonsterTraitCatalog.ResolveTags(source.definition);
        MonsterTraitRuntime.RecordShareableMark(source.activeTraitIds,source.traitState,
            target==null?"":target.stableId,(tags&MonsterCombatTag.StatusOrMarkSkill)!=0);
        bool killedTarget=!IsCombatActive(target);
        SkillHitTraitResult traits=MonsterTraitRuntime.ResolveSkillHit(source.activeTraitIds,
            (tags&MonsterCombatTag.SingleTargetSkill)!=0,
            (tags&MonsterCombatTag.MovementSkill)!=0,
            (tags&MonsterCombatTag.StatusOrMarkSkill)!=0,
            killedTarget);
        source.traitActivations+=traits.activations;

        float directSecondary=traits.splitDamage+traits.spreadingDamage+traits.killChainDamage;
        if(directSecondary>0f)
        {
            int count=Mathf.Max(1,traits.secondaryTargets);
            foreach(Unit secondary in units.Where(candidate=>candidate!=target&&
                         IsCombatActive(candidate)&&candidate.team!=source.team&&
                         Vector3.Distance(impactPosition,Flat(candidate.model.transform.position))<
                         TileSize*3f)
                     .OrderBy(candidate=>Vector3.Distance(
                         impactPosition,Flat(candidate.model.transform.position))).Take(count))
                ApplyTraitSkillDamage(source,secondary,traitBaseDamage*directSecondary);
        }
        if(traits.afterimageDamage>0f)
            ApplyTraitAreaDamage(source,impactPosition,TileSize*1.15f,
                traitBaseDamage*traits.afterimageDamage,target);
        if(traits.delayedAreaDamage>0f)
            StartReleasedSkill(source,DelayedTraitAreaDamage(source,impactPosition,TileSize*1.1f,
                traitBaseDamage*traits.delayedAreaDamage,target,combatGeneration));
        return dealt;
    }

    private Unit FindNearestEnemyToPoint(Unit source,Unit excluded,Vector3 origin,float maximumDistance)
    {
        Unit best=null;
        float bestDistance=maximumDistance;
        for(int i=0;i<units.Count;i++)
        {
            Unit candidate=units[i];
            if(candidate==excluded||!IsCombatActive(candidate)||candidate.team==source.team)continue;
            float distance=Vector3.Distance(origin,Flat(candidate.model.transform.position));
            if(distance>=bestDistance)continue;
            bestDistance=distance;
            best=candidate;
        }
        return best;
    }

    private float ApplyTraitSkillDamage(Unit source,Unit target,float damage)
    {
        if(!IsCombatActive(target)||damage<=0f)return 0f;
        float dealt=ApplyDamage(source,target,damage,true,false,false);
        source.skillDamage+=dealt;
        return dealt;
    }

    private float ApplyTraitAreaDamage(Unit source,Vector3 origin,float radius,float damage,Unit excluded)
    {
        float total=0f;
        for(int i=0;i<units.Count;i++)
        {
            Unit enemy=units[i];
            if(enemy==excluded||!IsCombatActive(enemy)||enemy.team==source.team)continue;
            if(Vector3.Distance(origin,Flat(enemy.model.transform.position))>radius)continue;
            total+=ApplyTraitSkillDamage(source,enemy,damage);
        }
        return total;
    }

    private void RecordComboActivation(
        Unit source,Unit target,string traitId,float bonusDamage)
    {
        if(source==null)return;
        source.traitActivations++;
        source.comboActivations++;
        source.comboBonusDamage+=Mathf.Max(0f,bonusDamage);
        source.shownTraitActivations=source.traitActivations;
        Unit anchor=target!=null&&target.model!=null?target:source;
        Color color=new Color(0.3f,0.88f,1f,1f);
        AddCombatFloatText(anchor,MonsterTraitRuntime.ComboShortName(traitId),color,true);
    }

    private IEnumerator DelayedTraitAreaDamage(Unit source,Vector3 origin,float radius,float damage,Unit excluded,int generation)
    {
        yield return new WaitForSeconds(0.35f);
        if(!battleStarted||!ReleasedSkillValid(source,generation))yield break;
        ApplyTraitAreaDamage(source,origin,radius,damage,excluded);
        if(IsCombatActive(source))CreateSkillPulse(source,new Color(1f,0.72f,0.18f),0.72f);
    }

    private void ApplyBasicAttackBuildUp(Unit unit)
    {
        foreach(ItemMasterRow item in unit.itemModifiers.specialEffects)
        {
            if(item.specialEffect=="BasicAttackDamageReductionStack")
            {
                unit.itemDamageReduction+=item.effectParam1;
                unit.itemDamageReduction=Mathf.Min(unit.itemDamageReduction,item.effectParam2);
            }
            else if(item.specialEffect=="BasicAttackSpeedRamp")
                unit.itemPermanentAttackSpeedBonus+=item.effectParam1;
            else if(item.specialEffect=="BasicAttackDamageRamp")
                unit.itemAttackDamageRamp+=item.effectParam1;
            else if(item.specialEffect=="BasicCooldownReduction")
                unit.skillTimer=Mathf.Max(0f,unit.skillTimer-item.effectParam1);
        }
    }

    private float ConsumeBasicAttackBonus(Unit unit)
    {
        float bonus=unit.counterBonusDamage+unit.postSkillBasicDamage;
        unit.counterBonusDamage=0f;unit.postSkillBasicDamage=0f;
        foreach(ItemMasterRow item in unit.itemModifiers.specialEffects)
            if(item.specialEffect=="EveryNthBasicBonusDamage"&&item.effectParam1>0f&&
               unit.basicAttackCount%Mathf.RoundToInt(item.effectParam1)==0)
                bonus+=item.effectParam2;
        foreach(ItemMasterRow item in unit.itemModifiers.specialEffects)
            if(item.specialEffect=="EveryNthBasicHeal"&&item.effectParam1>0f&&
               unit.basicAttackCount%Mathf.RoundToInt(item.effectParam1)==0)
                Heal(unit,unit.maxHp*item.effectParam2);
        return bonus;
    }

    private void ApplyCriticalItemEffects(Unit unit,Unit target=null)
    {
        Heal(unit,EffectSum(unit,"CritHeal",row=>row.effectParam1)*unit.maxHp);
        if(IsCombatActive(target))
        {
            float shred=EffectMax(unit,"CriticalDefenseShred",row=>row.effectParam1);
            if(shred>0f&&!target.combatStatuses.RejectHarmfulEffect())
            {
                ApplyDefenseShred(unit,target,shred,
                    EffectMax(unit,"CriticalDefenseShred",row=>row.effectParam2));
            }
        }
        float attackSpeed=0f;float duration=0f;
        foreach(ItemMasterRow item in unit.itemModifiers.specialEffects)
        {
            if(item.specialEffect!="CritAttackSpeed")continue;
            attackSpeed+=item.effectParam1*Mathf.Max(1f,item.effectParam2);
            duration=Mathf.Max(duration,item.effectParam3);
        }
        if(attackSpeed<=0f)return;
        unit.itemAttackSpeedBonus+=attackSpeed;
        unit.itemAttackSpeedTimer=GateHaetaeBenefit(unit,Mathf.Max(unit.itemAttackSpeedTimer,duration));
    }

    private void ApplyPostSkillItemEffects(Unit unit)
    {
        unit.postSkillBasicDamage=Mathf.Max(unit.postSkillBasicDamage,
            EffectSum(unit,"PostSkillBasicDamage",row=>row.effectParam1));
        float postSkillAttackSpeed=
            EffectSum(unit,"PostSkillAttackSpeed",row=>row.effectParam1);
        if(postSkillAttackSpeed>0f)
        {
            unit.itemPostSkillAttackSpeedBonus=postSkillAttackSpeed;
            unit.itemPostSkillAttackSpeedTimer=GateHaetaeBenefit(unit,Mathf.Max(
                unit.itemPostSkillAttackSpeedTimer,
                EffectMax(unit,"PostSkillAttackSpeed",row=>row.effectParam2)));
        }
        float postSkillDefense=
            EffectSum(unit,"PostSkillDefenseResistance",row=>row.effectParam1);
        float postSkillResistance=
            EffectSum(unit,"PostSkillDefenseResistance",row=>row.effectParam2);
        if(postSkillDefense>0f||postSkillResistance>0f)
        {
            unit.itemPostSkillDefenseBonus=postSkillDefense;
            unit.itemPostSkillResistanceBonus=postSkillResistance;
            unit.itemPostSkillStatTimer=GateHaetaeBenefit(unit,Mathf.Max(
                unit.itemPostSkillStatTimer,
                EffectMax(unit,"PostSkillDefenseResistance",row=>row.effectParam3)));
        }
        foreach(ItemMasterRow item in unit.itemModifiers.specialEffects)
        {
            if(item.specialEffect=="PostSkillShield")
            {
                unit.itemShield=GateHaetaeBenefit(unit,unit.itemShield+unit.maxHp*item.effectParam1*GuardianShieldMultiplier(unit),CombatBenefitKind.Shield);
                unit.itemShieldTimer=Mathf.Max(unit.itemShieldTimer,item.effectParam2);
            }
            else if(item.specialEffect=="SkillPowerRamp")
                unit.itemSkillPowerRamp+=item.effectParam1;
        }
        ApplyGrowthCardSkillUseEffects(unit);
    }

    private void ApplyGrowthCardSkillUseEffects(Unit source)
    {
        if(source==null||source.team!=Team.Player||battleElapsed<growthSkillCycleNextTime)return;
        float ratio=GrowthModifiers(source.team).skillCycleHealRatio;
        if(ratio<=0f)return;
        Unit ally=units.Where(other=>IsCombatActive(other)&&
                !other.augmentShadowClone&&other.team==source.team)
            .OrderBy(other=>other.hp/Mathf.Max(1f,other.maxHp)).FirstOrDefault();
        if(ally==null)return;
        Heal(ally,ally.maxHp*ratio);
        growthSkillCycleNextTime=battleElapsed+2f;
    }

    private void ApplyLowHealthShield(Unit unit,float incomingDamage)
    {
        float nextHp=unit.hp-incomingDamage;
        float shield=0f;float duration=0f;
        foreach(ItemMasterRow item in unit.itemModifiers.specialEffects)
        {
            if(item.specialEffect=="LowHealthShield"&&!unit.lowHealthShieldUsed&&
               nextHp<=unit.maxHp*item.effectParam1)
            {
                unit.lowHealthShieldUsed=true;
                shield+=unit.maxHp*item.effectParam2;
                duration=Mathf.Max(duration,item.effectParam3);
            }
            else if(item.specialEffect=="BloodTalisman"&&!unit.itemBloodShieldUsed&&
               nextHp<=unit.maxHp*item.effectParam2)
            {
                unit.itemBloodShieldUsed=true;
                shield+=unit.maxHp*item.effectParam3;
                duration=Mathf.Max(duration,5f);
            }
            else if(item.specialEffect=="GuardianHourglass"&&!unit.itemGuardianUsed&&
                    nextHp<=unit.maxHp*item.effectParam1)
            {
                unit.itemGuardianUsed=true;
                shield+=unit.maxHp*item.effectParam2;
                duration=Mathf.Max(duration,5f);
                unit.skillTimer*=1f-Mathf.Clamp01(item.effectParam3);
                ItemTransformMasterRow great=CorruptionEffect(unit,
                    "CorruptAllyRewind");
                if(great!=null)
                {
                    float radius=great.GreatParam("radius_tiles",2f);
                    float allyShield=unit.maxHp*great.GreatParam(
                        "ally_shield_caster_max_health_ratio",.1f);
                    float allyDuration=great.GreatParam("shield_duration",5f);
                    float cooldownReduction=Mathf.Clamp01(great.GreatParam(
                        "ally_remaining_cooldown_reduction",.15f));
                    foreach(Unit ally in CorruptAllies(unit,radius,false))
                    {
                        ally.itemShield=GateHaetaeBenefit(ally,ally.itemShield+allyShield*GuardianShieldMultiplier(unit),CombatBenefitKind.Shield);
                        ally.itemShieldTimer=Mathf.Max(
                            ally.itemShieldTimer,allyDuration);
                        ally.skillTimer*=1f-cooldownReduction;
                    }
                    RecordCorruption(unit,great);
                    CreateSkillPulse(unit,new Color(.55f,.88f,1f),radius);
                }
            }
        }
        if(shield>0f){unit.itemShield=GateHaetaeBenefit(unit,unit.itemShield+shield*GuardianShieldMultiplier(unit),CombatBenefitKind.Shield);unit.itemShieldTimer=Mathf.Max(unit.itemShieldTimer,duration);}
    }

    private void ApplyOnHitItemEffects(Unit unit,bool isBasicAttack)
    {
        if(isBasicAttack)unit.itemHitsTaken++;
        foreach(ItemMasterRow item in unit.itemModifiers.specialEffects)
        {
            if(item.specialEffect=="CombatCarapaceRamp")
            {
                unit.itemPermanentAttackSpeedBonus+=item.effectParam1;
                unit.itemDefenseRamp+=item.effectParam2;
            }
            else if(isBasicAttack&&item.specialEffect=="CounterGuaranteedCrit"&&
                    item.effectParam1>0f&&
                    unit.itemHitsTaken%Mathf.Max(1,Mathf.RoundToInt(item.effectParam1))==0)
                unit.counterGuaranteedCritical=true;
        }
        if(unit.counterCooldown<=0f)
        {
            float vengeance=EffectSum(unit,"CounterBasicDamage",row=>row.effectParam1);
            if(vengeance>0f)
            {
                unit.counterBonusDamage+=vengeance;
                unit.counterCooldown=Mathf.Max(unit.counterCooldown,
                    EffectMax(unit,"CounterBasicDamage",row=>row.effectParam2));
            }
        }
        if(unit.hitCooldownReductionGate<=0f)
        {
            float reduction=EffectSum(unit,"HitCooldownReduction",row=>row.effectParam1);
            if(reduction>0f)
            {
                unit.skillTimer=Mathf.Max(0f,unit.skillTimer-reduction);
                unit.hitCooldownReductionGate=Mathf.Max(0.01f,
                    EffectMax(unit,"HitCooldownReduction",row=>row.effectParam2));
            }
        }
    }

    private void UpdateItemPeriodicEffects(
        Unit unit,float dt,bool pauseHarmful=false)
    {
        if(unit==null||unit.itemModifiers==null)return;
        unit.itemPeriodicSelfHealTimer-=dt;
        unit.itemTimedSkillPowerTimer-=dt;
        unit.itemPeriodicAllyHealTimer-=dt;
        unit.itemSunTimer-=dt;

        if(HasEffect(unit,"PeriodicSelfHeal")&&unit.itemPeriodicSelfHealTimer<=0f)
        {
            Heal(unit,unit.maxHp*
                EffectSum(unit,"PeriodicSelfHeal",row=>row.effectParam1));
            unit.itemPeriodicSelfHealTimer=Mathf.Max(.1f,
                EffectMax(unit,"PeriodicSelfHeal",row=>row.effectParam2));
        }
        if(HasEffect(unit,"TimedSkillPowerRamp")&&unit.itemTimedSkillPowerTimer<=0f)
        {
            unit.itemSkillPowerRamp+=
                EffectSum(unit,"TimedSkillPowerRamp",row=>row.effectParam1);
            unit.itemTimedSkillPowerTimer=Mathf.Max(.1f,
                EffectMax(unit,"TimedSkillPowerRamp",row=>row.effectParam2));
        }
        if(HasEffect(unit,"PeriodicAllyHeal")&&unit.itemPeriodicAllyHealTimer<=0f)
        {
            float range=TileSize*Mathf.Max(1f,
                EffectMax(unit,"PeriodicAllyHeal",row=>row.effectParam3));
            Unit ally=null;
            float lowestRatio=0f;
            Vector3 origin=Flat(unit.model.transform.position);
            for(int i=0;i<units.Count;i++)
            {
                Unit other=units[i];
                if(!IsCombatActive(other)||other.team!=unit.team||other.augmentShadowClone||
                   !(Vector3.Distance(origin,Flat(other.model.transform.position))<=range))continue;
                float ratio=other.hp/Mathf.Max(1f,other.maxHp);
                if(ally!=null&&Comparer<float>.Default.Compare(ratio,lowestRatio)>=0)continue;
                ally=other;lowestRatio=ratio;
            }
            if(ally!=null)Heal(ally,ally.maxHp*
                EffectSum(unit,"PeriodicAllyHeal",row=>row.effectParam1));
            unit.itemPeriodicAllyHealTimer=Mathf.Max(.1f,
                EffectMax(unit,"PeriodicAllyHeal",row=>row.effectParam2));
        }
        if(HasEffect(unit,"SunCarapace")&&unit.itemSunTimer<=0f)
        {
            Unit enemy=null;
            float nearestDistance=0f;
            Vector3 origin=Flat(unit.model.transform.position);
            for(int i=0;i<units.Count;i++)
            {
                Unit other=units[i];
                if(!IsCombatActive(other)||other.team==unit.team)continue;
                float distance=Vector3.Distance(origin,Flat(other.model.transform.position));
                if(!(distance<=TileSize*2f)||enemy!=null&&
                   Comparer<float>.Default.Compare(distance,nearestDistance)>=0)continue;
                enemy=other;nearestDistance=distance;
            }
            if(enemy!=null)ApplyItemBurn(unit,enemy,
                EffectSum(unit,"SunCarapace",row=>row.effectParam1),
                EffectMax(unit,"SunCarapace",row=>row.effectParam2),
                EffectMax(unit,"SunCarapace",row=>row.effectParam3));
            unit.itemSunTimer=2f;
        }

        if(unit.itemOpeningImmunityTimer>0f&&HasEffect(unit,"OpeningStatusImmunity"))
        {
            unit.itemOpeningAttackSpeedTick-=dt;
            if(unit.itemOpeningAttackSpeedTick<=0f)
            {
                unit.itemPermanentAttackSpeedBonus+=EffectSum(unit,"OpeningStatusImmunity",row=>row.effectParam2);
                unit.itemOpeningAttackSpeedTick=Mathf.Max(.1f,
                    EffectMax(unit,"OpeningStatusImmunity",row=>row.effectParam3));
            }
        }
        if(unit.itemBurnTimer>0f)
        {
            if(!pauseHarmful)
                unit.itemBurnTimer=Mathf.Max(0f,unit.itemBurnTimer-dt);
            unit.itemBurnTickTimer-=dt;
            if(unit.itemBurnTickTimer<=0f&&IsCombatActive(unit.itemBurnSource))
            {
                unit.itemBurnTickTimer=1f;
                ApplyDamage(unit.itemBurnSource,unit,unit.maxHp*unit.itemBurnRatio,
                    true,false,false,false,1f,0f);
            }
            if(unit.itemBurnTimer<=0f)
            {unit.itemBurnSource=null;unit.itemBurnRatio=0f;unit.itemHealingReduction=0f;}
        }
        if(HasEffect(unit,"CrownCarapace")&&!unit.itemCrownEmpowered&&unit.itemShield<=0f)
        {
            unit.itemCrownEmpowered=true;
            unit.itemSkillPowerRamp+=EffectSum(unit,"CrownCarapace",row=>row.effectParam3);
        }
    }

    private void ApplyBattleStartItemEffects(Unit unit)
    {
        foreach(ItemMasterRow item in unit.itemModifiers.specialEffects)
            ApplyBattleStartItemEffect(unit,item);
        foreach(ItemTransformMasterRow row in unit.itemModifiers.transformedEffects)
            ApplyBattleStartCorruptionEffect(unit,row);
        float openingShield=GrowthModifiers(unit.team).openingShieldRatio;
        if(openingShield>0f)
        {
            unit.itemShield=GateHaetaeBenefit(unit,unit.itemShield+unit.maxHp*openingShield,CombatBenefitKind.Shield);
            unit.itemShieldTimer=Mathf.Max(unit.itemShieldTimer,8f);
        }
    }

    private void ApplyBattleStartItemEffect(Unit unit,ItemMasterRow item)
    {
        if(unit==null||item==null)return;
        if(item.specialEffect=="FirstSkillCooldownReduction")
            unit.skillTimer*=1f-Mathf.Clamp01(item.effectParam1);
        else if(item.specialEffect=="PeriodicSelfHeal")
            unit.itemPeriodicSelfHealTimer=Mathf.Max(
                unit.itemPeriodicSelfHealTimer,item.effectParam2);
        else if(item.specialEffect=="TimedSkillPowerRamp")
            unit.itemTimedSkillPowerTimer=Mathf.Max(
                unit.itemTimedSkillPowerTimer,item.effectParam2);
        else if(item.specialEffect=="PeriodicAllyHeal")
            unit.itemPeriodicAllyHealTimer=Mathf.Max(
                unit.itemPeriodicAllyHealTimer,item.effectParam2);
        else if(item.specialEffect=="SunCarapace")
            unit.itemSunTimer=Mathf.Max(unit.itemSunTimer,2f);
        else if(item.specialEffect=="CrownCarapace")
        {
            unit.itemShield=GateHaetaeBenefit(unit,unit.itemShield+unit.maxHp*item.effectParam1*GuardianShieldMultiplier(unit),CombatBenefitKind.Shield);
            unit.itemShieldTimer=Mathf.Max(unit.itemShieldTimer,item.effectParam2);
        }
        else if(item.specialEffect=="OpeningStatusImmunity")
        {
            unit.itemOpeningImmunityTimer=GateHaetaeBenefit(unit,Mathf.Max(
                unit.itemOpeningImmunityTimer,item.effectParam1));
            unit.itemOpeningAttackSpeedTick=Mathf.Max(.1f,item.effectParam3);
        }
        else if(item.specialEffect=="RandomBattleMode")
            unit.itemRandomAttackMode=UnityEngine.Random.value<.5f;
        else if(item.specialEffect=="TwilightShroud")
        {
            unit.itemTwilightDefenseBonus+=item.effectParam2;
            unit.itemTwilightResistanceBonus+=item.effectParam3;
            unit.itemTwilightStatTimer=GateHaetaeBenefit(unit,Mathf.Max(unit.itemTwilightStatTimer,10f));
        }
    }

    private float TwilightShroudReduction(Unit source)
    {
        if(source==null||source.model==null)return 0f;
        float reduction=0f;
        foreach(Unit enemy in units)
            if(IsCombatActive(enemy)&&enemy.team!=source.team&&enemy.model!=null&&
               Vector3.Distance(Flat(enemy.model.transform.position),
                   Flat(source.model.transform.position))<=TileSize*2f)
                reduction=CombatStatFormula.Strongest(reduction,
                    EffectMax(enemy,"TwilightShroud",row=>row.effectParam1));
        return reduction;
    }

    private void ApplyItemBurn(Unit source,Unit target,float ratio,float duration,float healingReduction)
    {
        if(source==null||target==null||target.combatStatuses.RejectHarmfulEffect())return;
        target.itemBurnSource=source;
        target.itemBurnRatio=Mathf.Max(target.itemBurnRatio,ratio);
        target.itemBurnTimer=Mathf.Max(target.itemBurnTimer,duration);
        target.itemBurnTickTimer=Mathf.Min(target.itemBurnTickTimer<=0f?1f:target.itemBurnTickTimer,1f);
        target.itemHealingReduction=Mathf.Max(target.itemHealingReduction,healingReduction);
    }

    private ItemTransformMasterRow CorruptionEffect(Unit unit,string effectId)
    {
        if(unit==null||unit.itemModifiers==null)return null;
        foreach(var row in unit.itemModifiers.transformedEffects)
            if(row!=null&&string.Equals(row.corruptionGreatEffectId,effectId,
                StringComparison.OrdinalIgnoreCase))return row;
        return null;
    }

    private void RecordCorruption(Unit owner,ItemTransformMasterRow row)
    {
        if(row==null)return;
        CorruptionGreatSuccessDiagnostics.Record(row.corruptionGreatEffectId);
        if(owner==null||owner.model==null||corruptionDiagnosticRunning)return;
        string timerKey="feedback_"+row.corruptionGreatEffectId;
        if(!CorruptReady(owner,timerKey))return;
        SetCorruptTimer(owner,timerKey,.85f);
        CorruptionFeedbackStyle style=
            CorruptionGreatSuccessPresentation.Style(row.corruptionGreatEffectId);
        CreateSkillPulse(owner,style.color,style.pulseScale);
    }


    private static int CorruptCounter(Unit unit,string key)
    {
        int value;
        return unit.corruptCounters.TryGetValue(key,out value)?value:0;
    }

    private static int AddCorruptCounter(Unit unit,string key,int amount=1)
    {
        int value=CorruptCounter(unit,key)+amount;
        unit.corruptCounters[key]=value;
        return value;
    }

    private static float CorruptValue(Unit unit,string key,float fallback=0f)
    {
        float value;
        return unit.corruptValues.TryGetValue(key,out value)?value:fallback;
    }

    private static bool CorruptReady(Unit unit,string key)
    {
        float value;
        return !unit.corruptTimers.TryGetValue(key,out value)||value<=0f;
    }

    private static void SetCorruptTimer(Unit unit,string key,float value)
    {
        unit.corruptTimers[key]=Mathf.Max(0f,value);
    }

    private List<Unit> CorruptEnemies(Unit source,float radiusTiles=999f,Unit exclude=null)
    {
        if(source==null||source.model==null)return new List<Unit>();
        Vector3 origin=Flat(source.model.transform.position);
        float radius=TileSize*Mathf.Max(0f,radiusTiles);
        return units.Where(unit=>unit!=exclude&&IsCombatActive(unit)&&unit.team!=source.team&&
                Vector3.Distance(origin,Flat(unit.model.transform.position))<=radius)
            .OrderBy(unit=>Vector3.Distance(origin,Flat(unit.model.transform.position)))
            .ToList();
    }

    private List<Unit> CorruptAllies(Unit source,float radiusTiles=999f,bool includeSelf=true)
    {
        if(source==null||source.model==null)return new List<Unit>();
        Vector3 origin=Flat(source.model.transform.position);
        float radius=TileSize*Mathf.Max(0f,radiusTiles);
        return units.Where(unit=>(includeSelf||unit!=source)&&IsCombatActive(unit)&&
                !unit.augmentShadowClone&&
                unit.team==source.team&&
                Vector3.Distance(origin,Flat(unit.model.transform.position))<=radius)
            .OrderBy(unit=>unit.hp/Mathf.Max(1f,unit.maxHp)).ToList();
    }

    private void ApplyBattleStartCorruptionEffect(
        Unit unit,ItemTransformMasterRow row)
    {
        if(unit==null||row==null||!CorruptionGreatSuccessRules.Supports(
            row.corruptionGreatEffectId))return;
        string effect=row.corruptionGreatEffectId;
        if(effect=="CorruptSpiritCircuit")
            SetCorruptTimer(unit,effect,row.GreatParam("interval",4f));
        else if(effect=="CorruptHealthEqualize")
            SetCorruptTimer(unit,effect,row.GreatParam("interval",6f));
        else if(effect=="CorruptStoredSupernova")
            SetCorruptTimer(unit,effect,row.GreatParam("interval",4f));
        else if(effect=="CorruptPurificationStorm")
            unit.combatStatuses.harmfulDurationMultiplier=Mathf.Clamp01(
                row.GreatParam("harmful_duration_multiplier",.5f));
        else if(effect=="CorruptChosenFate")
        {
            unit.itemRandomAttackMode=true;
            RecordCorruption(unit,row);
            CreateSkillPulse(unit,new Color(.82f,.38f,1f),.75f);
        }
        else if(effect=="CorruptDamageLink")
        {
            Unit ally=CorruptAllies(unit,999f,false).OrderBy(other=>
                Vector3.Distance(Flat(unit.model.transform.position),
                    Flat(other.model.transform.position))).FirstOrDefault();
            if(ally!=null)
            {
                unit.corruptDamageLinkTarget=ally;
                unit.corruptDamageLinkRatio=Mathf.Clamp01(
                    row.GreatParam("damage_share_ratio",.5f));
                float bonus=row.GreatParam("defense_resistance_bonus",20f);
                unit.itemTemporaryDefenseBonus+=bonus;
                unit.itemTemporaryResistanceBonus+=bonus;
                unit.itemTemporaryStatTimer=GateHaetaeBenefit(unit,999f);
                RecordCorruption(unit,row);
            }
        }
    }

    private void UpdateCorruptionGreatSuccessEffects(Unit unit,float dt)
    {
        if(unit==null||unit.itemModifiers==null)return;
        corruptTimerKeys.Clear();
        corruptTimerKeys.AddRange(unit.corruptTimers.Keys);
        for(int i=0;i<corruptTimerKeys.Count;i++)
            unit.corruptTimers[corruptTimerKeys[i]]=Mathf.Max(0f,
                unit.corruptTimers[corruptTimerKeys[i]]-dt);
        unit.corruptIncomingDamageAmpTimer=Mathf.Max(0f,
            unit.corruptIncomingDamageAmpTimer-dt);
        if(unit.corruptIncomingDamageAmpTimer<=0f)unit.corruptIncomingDamageAmp=0f;
        unit.corruptStatusResistanceReductionTimer=Mathf.Max(0f,
            unit.corruptStatusResistanceReductionTimer-dt);
        if(unit.corruptStatusResistanceReductionTimer<=0f)
            unit.corruptStatusResistanceReduction=0f;
        unit.corruptMirrorTimer=Mathf.Max(0f,unit.corruptMirrorTimer-dt);

        ItemTransformMasterRow spirit=CorruptionEffect(unit,"CorruptSpiritCircuit");
        if(spirit!=null&&CorruptReady(unit,"CorruptSpiritCircuit"))
        {
            List<Unit> allies=CorruptAllies(unit).Take(Mathf.Max(1,
                spirit.GreatParamInt("ally_targets",2))).ToList();
            float ratio=allies.Count<=1?spirit.GreatParam("solo_heal_ratio",.06f):
                spirit.GreatParam("heal_ratio",.04f);
            foreach(Unit ally in allies)Heal(ally,ally.maxHp*ratio);
            RecordCorruption(unit,spirit);
            SetCorruptTimer(unit,"CorruptSpiritCircuit",
                spirit.GreatParam("interval",4f));
            CreateSkillPulse(unit,new Color(.3f,1f,.72f),.8f);
        }

        ItemTransformMasterRow equalize=CorruptionEffect(unit,"CorruptHealthEqualize");
        if(equalize!=null&&CorruptReady(unit,"CorruptHealthEqualize"))
        {
            Unit ally=CorruptAllies(unit).FirstOrDefault();
            if(ally!=null)
            {
                float average=(unit.hp/Mathf.Max(1f,unit.maxHp)+
                               ally.hp/Mathf.Max(1f,ally.maxHp))*.5f;
                unit.hp+=GateHaetaeBenefit(unit,Mathf.Min(unit.maxHp,unit.maxHp*average)-unit.hp,CombatBenefitKind.Healing);
                ally.hp+=GateHaetaeBenefit(ally,Mathf.Min(ally.maxHp,ally.maxHp*average)-ally.hp,CombatBenefitKind.Healing);
                float heal=equalize.GreatParam("post_equalize_heal_ratio",.04f);
                Heal(unit,unit.maxHp*heal);Heal(ally,ally.maxHp*heal);
                RecordCorruption(unit,equalize);
            }
            SetCorruptTimer(unit,"CorruptHealthEqualize",
                equalize.GreatParam("interval",6f));
        }

        ItemTransformMasterRow supernova=CorruptionEffect(unit,"CorruptStoredSupernova");
        if(supernova!=null&&CorruptReady(unit,"CorruptStoredSupernova"))
        {
            float stored=CorruptValue(unit,"supernova_stored");
            if(stored>0f)
            {
                float radius=supernova.GreatParam("radius_tiles",2f);
                foreach(Unit enemy in CorruptEnemies(unit,radius))
                    ApplyDamage(unit,enemy,stored,false,false,false,false,0f,0f);
                unit.itemShield=GateHaetaeBenefit(unit,unit.itemShield+stored*supernova.GreatParam(
                    "shield_from_stored_ratio",.5f)*GuardianShieldMultiplier(unit),CombatBenefitKind.Shield);
                unit.itemShieldTimer=Mathf.Max(unit.itemShieldTimer,4f);
                unit.corruptValues["supernova_stored"]=0f;
                RecordCorruption(unit,supernova);
                CreateSkillPulse(unit,new Color(1f,.65f,.16f),radius);
            }
            SetCorruptTimer(unit,"CorruptStoredSupernova",
                supernova.GreatParam("interval",4f));
        }

        ItemTransformMasterRow grand=CorruptionEffect(unit,"CorruptGrandSpellTimer");
        if(grand!=null)
        {
            bool idle=unit.skillTimer>0f&&!unit.moving;
            float elapsed=CorruptValue(unit,"grand_idle");
            unit.corruptValues["grand_idle"]=idle?elapsed+dt:0f;
            if(elapsed+dt>=grand.GreatParam("idle_seconds_required",4f))
            {
                unit.corruptValues["grand_ready"]=1f;
                RecordCorruption(unit,grand);
            }
        }

        ItemTransformMasterRow royal=CorruptionEffect(unit,"CorruptRoyalFortress");
        if(royal!=null&&CorruptCounter(unit,"royal_uses")<
            royal.GreatParamInt("uses_per_wave",1))
        {
            int targeting=0;
            for(int i=0;i<units.Count;i++)
            {
                Unit enemy=units[i];
                if(IsCombatActive(enemy)&&enemy.team!=unit.team&&enemy.target==unit)targeting++;
            }
            if(targeting>=royal.GreatParamInt("min_enemies",3))
            {
                float duration=royal.GreatParam("duration",6f);
                float bonus=royal.GreatParam("defense_resistance_bonus",30f);
                unit.itemTemporaryDefenseBonus+=bonus;
                unit.itemTemporaryResistanceBonus+=bonus;
                unit.itemTemporaryStatTimer=GateHaetaeBenefit(unit,Mathf.Max(unit.itemTemporaryStatTimer,duration));
                unit.corruptReflectionRatio=royal.GreatParam(
                    "damage_reflect_ratio",.2f);
                SetCorruptTimer(unit,"royal_reflect",duration);
                AddCorruptCounter(unit,"royal_uses");
                RecordCorruption(unit,royal);
            }
        }
        if(CorruptReady(unit,"royal_reflect"))unit.corruptReflectionRatio=0f;

        ItemTransformMasterRow twilight=CorruptionEffect(unit,"CorruptTwilightDecoy");
        if(twilight!=null&&CorruptCounter(unit,"twilight_uses")<
            twilight.GreatParamInt("uses_per_wave",1))
        {
            int targeting=0;
            for(int i=0;i<units.Count;i++)
            {
                Unit enemy=units[i];
                if(IsCombatActive(enemy)&&enemy.team!=unit.team&&enemy.target==unit)targeting++;
            }
            if(targeting>=twilight.GreatParamInt("targeting_enemy_threshold",3))
            {
                unit.corruptUntargetable=true;
                SetCorruptTimer(unit,"twilight_untargetable",
                    twilight.GreatParam("untargetable_duration",1.5f));
                unit.itemShield=GateHaetaeBenefit(unit,unit.itemShield+unit.maxHp*twilight.GreatParam(
                    "decoy_health_ratio",.35f)*GuardianShieldMultiplier(unit),CombatBenefitKind.Shield);
                unit.itemShieldTimer=Mathf.Max(unit.itemShieldTimer,
                    twilight.GreatParam("decoy_duration",4f));
                for(int i=0;i<units.Count;i++)
                {
                    Unit enemy=units[i];
                    if(IsCombatActive(enemy)&&enemy.team!=unit.team&&enemy.target==unit)SetTarget(enemy,null);
                }
                AddCorruptCounter(unit,"twilight_uses");
                RecordCorruption(unit,twilight);
            }
        }
        if(unit.corruptUntargetable&&CorruptReady(unit,"twilight_untargetable"))
            unit.corruptUntargetable=false;
    }

    private void HandleCorruptionBasicAttack(Unit source,Unit target,float attackDamage)
    {
        if(source==null||source.itemModifiers==null)return;
        ItemTransformMasterRow row=CorruptionEffect(source,"CorruptDevourMark");
        if(row!=null&&IsCombatActive(target)&&CorruptReady(source,"devour_icd"))
        {
            string key="devour_"+target.id;
            int stacks=AddCorruptCounter(source,key);
            SetCorruptTimer(source,"devour_icd",row.GreatParam("stack_icd",.5f));
            if(stacks>=row.GreatParamInt("stack_required",4))
            {
                source.corruptCounters[key]=0;
                ApplyDamage(source,target,source.damage*row.GreatParam(
                    "burst_attack_ratio",1.2f),false,false,false,false);
                if(!target.combatStatuses.RejectHarmfulEffect())
                {
                    target.corruptIncomingDamageAmp=Mathf.Max(target.corruptIncomingDamageAmp,
                        row.GreatParam("target_damage_amp",.12f));
                    target.corruptIncomingDamageAmpTimer=Mathf.Max(
                        target.corruptIncomingDamageAmpTimer,row.GreatParam("amp_duration",5f));
                }
                RecordCorruption(source,row);
            }
        }

        row=CorruptionEffect(source,"CorruptStormSplit");
        if(row!=null&&AddCorruptCounter(source,"storm_attacks")>=
            row.GreatParamInt("trigger_attacks",4))
        {
            source.corruptCounters["storm_attacks"]=0;
            List<Unit> extras=CorruptEnemies(source,999f,target).Take(
                row.GreatParamInt("extra_targets",2)).ToList();
            if(extras.Count==0&&IsCombatActive(target))
                ApplyDamage(source,target,attackDamage*row.GreatParam(
                    "single_target_extra_ratio",.35f),false,false,false,false);
            foreach(Unit enemy in extras)ApplyDamage(source,enemy,
                attackDamage*row.GreatParam("secondary_damage_ratio",.7f),
                false,false,false,false);
            RecordCorruption(source,row);
        }

        row=CorruptionEffect(source,"CorruptCriticalShards");
        if(row!=null&&source.lastBasicAttackCritical)
        {
            List<Unit> extras=CorruptEnemies(source,999f,target).Take(
                row.GreatParamInt("shard_count",2)).ToList();
            if(extras.Count==0&&IsCombatActive(target))
                ApplyDamage(source,target,attackDamage*row.GreatParam(
                    "single_target_extra_ratio",.35f),false,false,false,false);
            foreach(Unit enemy in extras)ApplyDamage(source,enemy,attackDamage*
                row.GreatParam("shard_damage_ratio",.7f),false,false,false,false);
            RecordCorruption(source,row);
        }

        row=CorruptionEffect(source,"CorruptBerserkCycle");
        if(row!=null)
        {
            int count=AddCorruptCounter(source,"berserk_attacks");
            if(count>=row.GreatParamInt("rage_attacks",6))
            {
                source.corruptCounters["berserk_attacks"]=0;
                source.itemAttackSpeedBonus+=row.GreatParam("attack_speed_bonus",.5f);
                source.itemAttackSpeedTimer=GateHaetaeBenefit(source,Mathf.Max(source.itemAttackSpeedTimer,
                    row.GreatParam("frenzy_duration",5f)));
                RecordCorruption(source,row);
            }
            if(source.itemAttackSpeedTimer>0f)
                foreach(Unit enemy in CorruptEnemies(source,1.2f,target))
                    ApplyDamage(source,enemy,attackDamage*row.GreatParam(
                        "cleave_damage_ratio",.5f),false,false,false,false);
        }

        row=CorruptionEffect(source,"CorruptHuntMark");
        if(row!=null&&IsCombatActive(target))
        {
            Unit marked;
            source.corruptTargets.TryGetValue("hunt_mark",out marked);
            if(marked==target&&CorruptReady(source,"hunt_mark_duration"))
                source.corruptTargets.Remove("hunt_mark");
            if(!source.corruptTargets.ContainsKey("hunt_mark"))
            {
                source.corruptTargets["hunt_mark"]=target;
                SetCorruptTimer(source,"hunt_mark_duration",
                    row.GreatParam("mark_duration",5f));
                RecordCorruption(source,row);
            }
            else if(source.corruptTargets["hunt_mark"]==target)
                ApplyDamage(source,target,attackDamage*row.GreatParam(
                    "marked_basic_extra_ratio",.4f),false,false,false,false);
        }

        row=CorruptionEffect(source,"CorruptTimeMultiHit");
        if(row!=null&&AddCorruptCounter(source,"time_attacks")>=
            row.GreatParamInt("trigger_attacks",3))
        {
            source.corruptCounters["time_attacks"]=0;
            if(IsCombatActive(target))ApplyDamage(source,target,attackDamage*
                row.GreatParam("repeat_damage_ratio",.7f),false,false,false,false);
            source.skillTimer=Mathf.Max(0f,source.skillTimer-
                row.GreatParam("cooldown_seconds_reduction",1f));
            RecordCorruption(source,row);
        }

        row=CorruptionEffect(source,"CorruptVampireSwarm");
        if(row!=null&&AddCorruptCounter(source,"vampire_attacks")>=
            row.GreatParamInt("trigger_attacks",5))
        {
            source.corruptCounters["vampire_attacks"]=0;
            int bats=row.GreatParamInt("bat_count",3);
            List<Unit> enemies=CorruptEnemies(source);
            for(int i=0;i<bats&&enemies.Count>0;i++)
                ApplyDamage(source,enemies[i%enemies.Count],source.damage*
                    row.GreatParam("bat_attack_ratio",.35f),false,false,false,false);
            Heal(source,source.maxHp*row.GreatParam("heal_per_bat",.02f)*bats);
            RecordCorruption(source,row);
        }

        row=CorruptionEffect(source,"CorruptCriticalStormZone");
        if(row!=null&&source.lastBasicAttackCritical&&IsCombatActive(target))
        {
            RecordCorruption(source,row);
            StartReleasedSkill(source,CorruptStormZone(source,target,row));
        }

        row=CorruptionEffect(source,"CorruptBloodStar");
        if(row!=null&&source.lastBasicAttackCritical&&
           AddCorruptCounter(source,"blood_shards")>=
            row.GreatParamInt("shards_required",5))
        {
            source.corruptCounters["blood_shards"]=0;
            float radius=row.GreatParam("radius_tiles",2f);
            foreach(Unit enemy in CorruptEnemies(source,radius))
                ApplyDamage(source,enemy,source.damage*row.GreatParam(
                    "burst_attack_ratio",.8f),false,false,false,false);
            foreach(Unit ally in CorruptAllies(source,radius))
                Heal(ally,ally.maxHp*row.GreatParam(
                    "ally_heal_max_health_ratio",.05f));
            RecordCorruption(source,row);
        }
    }

    private IEnumerator CorruptStormZone(Unit source,Unit target,
        ItemTransformMasterRow row)
    {
        int generation=combatGeneration;
        float remaining=row.GreatParam("zone_duration",3f);
        float interval=Mathf.Max(.1f,row.GreatParam("tick_interval",.75f));
        Vector3 center=target==null||target.model==null?Flat(source.model.transform.position):
            Flat(target.model.transform.position);
        while(remaining>0f&&ReleasedSkillValid(source,generation))
        {
            yield return SkillWait(source,interval);
            if(!ReleasedSkillValid(source,generation))yield break;
            foreach(Unit enemy in units.Where(enemy=>IsCombatActive(enemy)&&
                enemy.team!=source.team&&Vector3.Distance(center,
                    Flat(enemy.model.transform.position))<=TileSize*1.3f))
            {
                ApplyDamage(source,enemy,source.damage*row.GreatParam(
                    "tick_attack_ratio",.25f),false,false,false,false);
                if(!enemy.combatStatuses.RejectHarmfulEffect())
                {
                    ApplyDefenseShred(source,enemy,row.GreatParam("defense_shred_per_tick",5f)/
                        Mathf.Max(1f,CurrentDefense(enemy)),row.GreatParam("shred_duration",5f));
                }
            }
            remaining-=interval;
        }
    }

    private void HandleCorruptionSkillUse(Unit source)
    {
        if(source==null||source.itemModifiers==null)return;
        ItemTransformMasterRow row=CorruptionEffect(source,"CorruptPersonalRewind");
        if(row!=null&&CorruptCounter(source,"opening_time_surge_uses")<
           row.GreatParamInt("uses_per_wave",1))
        {
            float reduction=Mathf.Clamp01(row.GreatParam(
                "ally_remaining_cooldown_reduction",.2f));
            foreach(Unit ally in CorruptAllies(source))
                ally.skillTimer*=1f-reduction;
            AddCorruptCounter(source,"opening_time_surge_uses");
            RecordCorruption(source,row);
            CreateSkillPulse(source,new Color(.25f,.8f,1f),.85f);
        }

        row=CorruptionEffect(source,"CorruptSkillEcho");
        if(row!=null&&AddCorruptCounter(source,"skill_echo_casts")>=
            row.GreatParamInt("trigger_casts",3))
        {
            source.corruptCounters["skill_echo_casts"]=0;
            StartCombatCoroutine(source,CorruptRepeatSkill(source,source.target,
                row.GreatParam("echo_delay",.6f),
                row.GreatParam("echo_magnitude_ratio",.6f)));
            RecordCorruption(source,row);
        }

        row=CorruptionEffect(source,"CorruptBloodBlade");
        if(row!=null)
        {
            float stored=CorruptValue(source,"bloodblade_overheal");
            if(stored>0f&&IsCombatActive(source.target))
            {
                ApplyDamage(source,source.target,0f,true,false,false,false,1f,stored);
                source.corruptValues["bloodblade_overheal"]=0f;
                RecordCorruption(source,row);
            }
        }

        row=CorruptionEffect(source,"CorruptMagicTurbine");
        if(row!=null&&IsCombatActive(source.target))
        {
            List<Unit> extras=CorruptEnemies(source,999f,source.target).Take(
                row.GreatParamInt("extra_targets",1)).ToList();
            float ratio=extras.Count==0?row.GreatParam(
                "single_target_extra_ratio",.25f):
                row.GreatParam("secondary_damage_ratio",.45f);
            if(extras.Count==0)ApplyDamage(source,source.target,source.damage*ratio,
                true,false,false,false);
            else foreach(Unit enemy in extras)ApplyDamage(source,enemy,
                source.damage*ratio,true,false,false,false);
            RecordCorruption(source,row);
        }

        row=CorruptionEffect(source,"CorruptSkillCritFracture");
        if(row!=null&&source.lastSkillCritical&&IsCombatActive(source.target))
        {
            int count=row.GreatParamInt("echo_count",2);
            for(int i=1;i<=count;i++)StartCombatCoroutine(source,CorruptDelayedDamage(
                source,source.target,row.GreatParam("echo_delay",.4f)*i,
                source.damage*row.GreatParam("echo_damage_ratio",.5f)));
            RecordCorruption(source,row);
        }

        row=CorruptionEffect(source,"CorruptStatusEcho");
        if(row!=null&&IsCombatActive(source.target))
        {
            CombatStatusKind[] copyable={CombatStatusKind.Poison,CombatStatusKind.Root,
                CombatStatusKind.Freeze,CombatStatusKind.StickySilk};
            foreach(CombatStatusKind kind in copyable)
            {
                CombatStatusEffect effect=source.target.combatStatuses.Get(kind);
                if(effect==null)continue;
                foreach(Unit enemy in CorruptEnemies(source,
                    row.GreatParam("radius_tiles",2f),source.target).Take(
                        row.GreatParamInt("extra_targets",2)))
                {
                    float duration=effect.remaining*
                        row.GreatParam("copied_duration_ratio",.7f);
                    if(kind==CombatStatusKind.Poison)
                        enemy.combatStatuses.ApplyStacks(
                            kind,duration,effect.stacks,
                            CombatStatusState.MaximumPoisonStacks,source,
                            effect.magnitude,effect.tickInterval,true);
                    else
                        enemy.combatStatuses.ApplyTimed(
                            kind,duration,source,effect.magnitude);
                    if(!enemy.combatStatuses.RejectHarmfulEffect())
                    {
                        enemy.corruptStatusResistanceReduction=Mathf.Max(
                            enemy.corruptStatusResistanceReduction,row.GreatParam(
                                "status_resistance_reduction",20f));
                        enemy.corruptStatusResistanceReductionTimer=Mathf.Max(
                            enemy.corruptStatusResistanceReductionTimer,row.GreatParam(
                                "reduction_duration",5f));
                    }
                }
                RecordCorruption(source,row);
                break;
            }
        }

        row=CorruptionEffect(source,"CorruptLivingPlague");
        if(row!=null&&IsCombatActive(source.target))
        {
            ApplyCorruptPlague(source,source.target,row);
            RecordCorruption(source,row);
        }

        row=CorruptionEffect(source,"CorruptInfiniteCycle");
        if(row!=null)
        {
            float radius=row.GreatParam("radius_tiles",2f);
            foreach(Unit ally in CorruptAllies(source,radius))
            {
                ally.itemTemporaryDefenseBonus+=row.GreatParam(
                    "defense_resistance_bonus",15f);
                ally.itemTemporaryResistanceBonus+=row.GreatParam(
                    "defense_resistance_bonus",15f);
                ally.itemTemporaryStatTimer=GateHaetaeBenefit(ally,Mathf.Max(ally.itemTemporaryStatTimer,
                    row.GreatParam("duration",5f)));
                ally.itemShield=GateHaetaeBenefit(ally,ally.itemShield+ally.maxHp*row.GreatParam(
                    "shield_max_health_ratio",.05f)*GuardianShieldMultiplier(source),CombatBenefitKind.Shield);
                ally.itemShieldTimer=Mathf.Max(ally.itemShieldTimer,
                    row.GreatParam("duration",5f));
                ally.skillTimer*=1f-Mathf.Clamp01(row.GreatParam(
                    "remaining_cooldown_reduction",.15f));
            }
            RecordCorruption(source,row);
        }

        row=CorruptionEffect(source,"CorruptLiberationWave");
        if(row!=null&&CorruptCounter(source,"liberation_uses")<
            row.GreatParamInt("uses_per_wave",1))
        {
            float radius=row.GreatParam("radius_tiles",2f);
            foreach(Unit ally in CorruptAllies(source,radius))
            {
                ally.combatStatuses.Clear();
                ally.itemOpeningImmunityTimer=GateHaetaeBenefit(ally,Mathf.Max(
                    ally.itemOpeningImmunityTimer,row.GreatParam(
                        "ally_immunity_duration",2f)));
            }
            foreach(Unit enemy in CorruptEnemies(source,radius))
                ApplyDamage(source,enemy,source.damage*row.GreatParam(
                    "burst_attack_ratio",.8f),true,false,false,false);
            AddCorruptCounter(source,"liberation_uses");
            RecordCorruption(source,row);
        }
    }

    private void PrepareCorruptionSkillUse(Unit source)
    {
        ItemTransformMasterRow row=CorruptionEffect(source,"CorruptGrandSpellTimer");
        if(row==null||CorruptValue(source,"grand_ready")<=0f)return;
        source.corruptValues["grand_ready"]=0f;
        source.corruptValues["grand_idle"]=0f;
        source.skillTraitDamageMultiplier*=1f+
            row.GreatParam("skill_magnitude_bonus",.45f);
        source.skillTraitRadiusMultiplier*=1f+
            row.GreatParam("skill_area_bonus",.3f);
        RecordCorruption(source,row);
        CreateSkillPulse(source,new Color(.72f,.3f,1f),1.1f);
    }

    private IEnumerator CorruptRepeatSkill(Unit source,Unit target,float delay,float ratio)
    {
        int generation=combatGeneration;
        yield return new WaitForSeconds(Mathf.Max(.05f,delay));
        while(true)
        {
            if(generation!=combatGeneration||battleEnding||!battleStarted||!IsCombatActive(source))yield break;
            if(!paused&&!GameFrontend.BlocksGameplay&&
               !HasSkillCastPresentation(source)&&!CommonSkillActionActive(source)&&
               !source.displacing&&!source.frogHopping&&
               !source.combatStatuses.Has(CombatStatusKind.Silence)&&
               !source.combatStatuses.Has(CombatStatusKind.Fear)&&
               (source.spriteAnimation==null||!source.spriteAnimation.IsActionLocked))break;
            yield return null;
        }
        if(!IsCombatActive(target))target=SelectTarget(source);
        if(!IsCombatActive(target))yield break;
        if(mlEpisodeActive||source.spiritConcertOwner!=null||source.augmentShadowClone||
           source.mantisBroodOwner!=null||source.spriteAnimation==null)
            ExecuteRepeatedSkillFocus(new PendingSkillFocus{
                unit=source,repeatTarget=target,repeatRatio=Mathf.Max(0f,ratio)});
        else QueueRepeatedSkillFocus(source,target,Mathf.Max(0f,ratio));
    }

    private IEnumerator CorruptDelayedDamage(Unit source,Unit target,float delay,float damage)
    {
        yield return new WaitForSeconds(Mathf.Max(.05f,delay));
        if(IsCombatActive(source)&&IsCombatActive(target))
            ApplyDamage(source,target,damage,true,false,false,false);
    }

    private void ApplyCorruptPlague(Unit source,Unit target,ItemTransformMasterRow row)
    {
        float duration=row.GreatParam("duration",4f);
        float tick=row.GreatParam("tick_interval",1f);
        target.combatStatuses.ApplyStacks(CombatStatusKind.Poison,duration,1,
            CombatStatusState.MaximumPoisonStacks,
            source,target.maxHp*row.GreatParam("max_health_damage_ratio",.015f),
            tick,true);
        StartCombatCoroutine(source,CorruptPlagueSpread(source,target,row));
    }

    private IEnumerator CorruptPlagueSpread(Unit source,Unit target,
        ItemTransformMasterRow row)
    {
        yield return new WaitForSeconds(row.GreatParam("spread_delay",2f));
        if(!IsCombatActive(source)||target==null||target.model==null)yield break;
        foreach(Unit enemy in units.Where(enemy=>enemy!=target&&IsCombatActive(enemy)&&
            enemy.team!=source.team).OrderBy(enemy=>Vector3.Distance(
                Flat(target.model.transform.position),Flat(enemy.model.transform.position)))
            .Take(row.GreatParamInt("spread_targets",2)))
            enemy.combatStatuses.ApplyStacks(CombatStatusKind.Poison,
                row.GreatParam("duration",4f),1,
                CombatStatusState.MaximumPoisonStacks,source,enemy.maxHp*
                row.GreatParam("max_health_damage_ratio",.015f),
                row.GreatParam("tick_interval",1f),true);
    }

    private void HandleCorruptionDamageTaken(Unit source,Unit target,float applied,
        bool fromSkill,bool isBasicAttack,bool allowReactive)
    {
        if(target==null||applied<=0f)return;
        ItemTransformMasterRow row=CorruptionEffect(target,"CorruptShellBurst");
        if(row!=null&&AddCorruptCounter(target,"shell_hits")>=
            row.GreatParamInt("hits_required",5))
        {
            target.corruptCounters["shell_hits"]=0;
            target.itemShield=GateHaetaeBenefit(target,target.itemShield+target.maxHp*row.GreatParam(
                "shield_max_health_ratio",.15f),CombatBenefitKind.Shield);
            target.itemShieldTimer=Mathf.Max(target.itemShieldTimer,
                row.GreatParam("shield_duration",4f));
            if(IsCombatActive(source))
            {
                ApplyDamage(target,source,target.damage*row.GreatParam(
                    "burst_attack_ratio",.8f),false,false,false,false);
                if(!source.combatStatuses.ControlImmune)
                    source.giraffeStunTimer=Mathf.Max(source.giraffeStunTimer,
                        HostileStatusDuration(
                            source,row.GreatParam("stun_duration",.8f)));
            }
            RecordCorruption(target,row);
        }

        row=CorruptionEffect(target,"CorruptGiantAwakening");
        if(row!=null&&target.hp>0f&&target.hp/Mathf.Max(1f,target.maxHp)<=
           row.GreatParam("health_trigger",.5f)&&
           CorruptCounter(target,"giant_uses")<
           row.GreatParamInt("uses_per_wave",1))
        {
            float oldMax=target.maxHp;
            target.maxHp*=1f+row.GreatParam("max_health_bonus",.2f);
            target.hp+=target.maxHp-oldMax;
            target.damage*=1f+row.GreatParam("attack_bonus",.15f);
            if(target.model!=null)
            {
                float scale=1f+row.GreatParam("model_scale_bonus",.15f);
                target.model.transform.localScale*=scale;
                target.combatBodyScale*=scale;
                CacheMeleeReadabilityBody(target);
                target.targetRing?.SetRadius(Mathf.Max(.3f,CombatBodyRadius(target)*1.15f));
            }
            AddCorruptCounter(target,"giant_uses");
            RecordCorruption(target,row);
        }

        row=CorruptionEffect(target,"CorruptStoredRetaliation");
        if(row!=null)
        {
            target.corruptValues["retaliation_stored"]=
                CorruptValue(target,"retaliation_stored")+applied*
                row.GreatParam("stored_damage_ratio",.4f);
            if(AddCorruptCounter(target,"retaliation_hits")>=
               row.GreatParamInt("hits_required",4))
            {
                target.corruptCounters["retaliation_hits"]=0;
                target.counterBonusDamage+=CorruptValue(target,"retaliation_stored");
                target.corruptValues["retaliation_stored"]=0f;
                target.counterGuaranteedCritical=row.GreatParamBool(
                    "next_basic_guaranteed_crit",true);
                RecordCorruption(target,row);
            }
        }

        row=CorruptionEffect(target,"CorruptBloodMoon");
        if(row!=null&&target.hp>0f&&target.hp/Mathf.Max(1f,target.maxHp)<=
           row.GreatParam("health_trigger",.4f)&&CorruptReady(target,"bloodmoon_cd"))
        {
            float duration=row.GreatParam("duration",6f);
            target.corruptValues["bloodmoon_vamp"]=row.GreatParam("omnivamp",.25f);
            SetCorruptTimer(target,"bloodmoon_active",duration);
            SetCorruptTimer(target,"bloodmoon_cd",duration+4f);
            RecordCorruption(target,row);
        }
        if(IsCombatActive(source))
        {
            float bloodVamp=CorruptValue(source,"bloodmoon_vamp");
            if(bloodVamp>0f&& !CorruptReady(source,"bloodmoon_active"))
            {
                float healed=applied*bloodVamp;
                Heal(source,healed);
                ItemTransformMasterRow bloodMoon=CorruptionEffect(source,
                    "CorruptBloodMoon");
                if(bloodMoon!=null)
                {
                    List<Unit> allies=CorruptAllies(source,999f,false).Take(
                        bloodMoon.GreatParamInt("ally_targets",2)).ToList();
                    foreach(Unit ally in allies)Heal(ally,healed*
                        bloodMoon.GreatParam("heal_share_ratio",.4f));
                }
            }
            ItemTransformMasterRow bloodBlade=CorruptionEffect(source,
                "CorruptBloodBlade");
            if(bloodBlade!=null)
            {
                float heal=applied*bloodBlade.GreatParam("damage_heal_ratio",.08f);
                float missing=Mathf.Max(0f,source.maxHp-source.hp);
                Heal(source,heal);
                if(bloodBlade.GreatParamBool("store_overheal",true)&&heal>missing)
                    source.corruptValues["bloodblade_overheal"]=
                        CorruptValue(source,"bloodblade_overheal")+heal-missing;
                RecordCorruption(source,bloodBlade);
            }
        }

        row=CorruptionEffect(target,"CorruptAdaptiveShell");
        if(row!=null&&AddCorruptCounter(target,"adaptive_hits")>=
            row.GreatParamInt("hits_required",5))
        {
            target.corruptCounters["adaptive_hits"]=0;
            float duration=row.GreatParam("buff_duration",4f);
            target.itemShield=GateHaetaeBenefit(target,target.itemShield+target.maxHp*row.GreatParam(
                "shield_max_health_ratio",.1f),CombatBenefitKind.Shield);
            target.itemShieldTimer=Mathf.Max(target.itemShieldTimer,duration);
            target.itemAttackSpeedBonus+=row.GreatParam("attack_speed_bonus",.3f);
            target.itemAttackSpeedTimer=GateHaetaeBenefit(target,Mathf.Max(target.itemAttackSpeedTimer,duration));
            if(row.GreatParamBool("cleanse",true))target.combatStatuses.Clear();
            RecordCorruption(target,row);
        }

        row=CorruptionEffect(target,"CorruptStoredSupernova");
        if(row!=null)target.corruptValues["supernova_stored"]=
            CorruptValue(target,"supernova_stored")+applied*
            row.GreatParam("stored_damage_ratio",.3f);

        if(!allowReactive)return;
        if(IsCombatActive(source)&&target.corruptReflectionRatio>0f)
            ApplyReflectedDamage(target,source,applied*target.corruptReflectionRatio);
        if(IsCombatActive(source)&&IsCombatActive(target.corruptDamageLinkTarget)&&
           target.corruptDamageLinkRatio>0f)
            ApplyReflectedDamage(target,target.corruptDamageLinkTarget,
                applied*target.corruptDamageLinkRatio);

        row=CorruptionEffect(target,"CorruptDamageMirror");
        if(row!=null&&target.hp>0f&&target.hp/Mathf.Max(1f,target.maxHp)<=
           row.GreatParam("health_threshold",.5f)&&target.corruptMirrorTimer<=0f)
        {
            target.corruptMirrorTimer=row.GreatParam("internal_cooldown",2f);
            float reduction=applied*row.GreatParam("damage_reduction_ratio",.5f);
            target.hp=Mathf.Min(target.maxHp,target.hp+reduction);
            target.preventedDamage+=reduction;
            if(IsCombatActive(source))ApplyReflectedDamage(target,source,applied*
                row.GreatParam("reflected_damage_ratio",.5f));
            RecordCorruption(target,row);
        }

        row=CorruptionEffect(source,"CorruptExecutionSentence");
        if(row!=null&&IsCombatActive(target)&&target.hp/Mathf.Max(1f,target.maxHp)<=
           row.GreatParam("health_threshold",.35f))
        {
            string key="execution_"+target.id;
            if(CorruptReady(source,key))
            {
                ApplyDamage(source,target,0f,true,false,false,false,1f,
                    (target.maxHp-target.hp)*row.GreatParam(
                        "missing_health_damage_ratio",.2f));
                SetCorruptTimer(source,key,row.GreatParam(
                    "per_target_cooldown",5f));
                RecordCorruption(source,row);
            }
        }

    }

    private void HandleCorruptionKill(Unit source,Unit defeated)
    {
        if(source==null)return;
        ItemTransformMasterRow row=CorruptionEffect(source,"CorruptPredatorGrowth");
        if(row!=null)
        {
            float oldMax=source.maxHp;
            source.maxHp*=1f+row.GreatParam("max_health_per_kill",.08f);
            source.hp=Mathf.Min(source.maxHp,source.hp+(source.maxHp-oldMax)+
                GateHaetaeBenefit(source,source.maxHp*row.GreatParam("kill_heal_ratio",.12f),CombatBenefitKind.Healing));
            Unit next=CorruptEnemies(source).OrderBy(enemy=>enemy.hp).FirstOrDefault();
            if(next!=null)SetTarget(source,next);
            RecordCorruption(source,row);
        }
        row=CorruptionEffect(source,"CorruptHuntMark");
        Unit marked;
        if(row!=null&&source.corruptTargets.TryGetValue("hunt_mark",out marked)&&
           marked==defeated)
        {
            source.skillTimer*=1f-Mathf.Clamp01(row.GreatParam(
                "takedown_remaining_cooldown_reduction",.5f));
            source.corruptTargets.Remove("hunt_mark");
        }
    }

    private void HandleCorruptionStatusRecovery(Unit unit)
    {
        ItemTransformMasterRow row=CorruptionEffect(unit,
            "CorruptPurificationStorm");
        if(row==null||!CorruptReady(unit,"purification_cd"))return;
        float radius=row.GreatParam("radius_tiles",2f);
        Unit cleansed=null;
        foreach(Unit ally in CorruptAllies(unit,radius,false))
        {
            if(!ally.combatStatuses.RemoveOneHarmful())continue;
            cleansed=ally;
            break;
        }
        if(cleansed==null)return;
        SetCorruptTimer(unit,"purification_cd",
            row.GreatParam("internal_cooldown",8f));
        RecordCorruption(unit,row);
        CreateSkillPulse(cleansed,new Color(.65f,1f,.88f),.7f);
    }

    private static bool HasEffect(Unit unit,string effect)
    {
        foreach(var item in unit.itemModifiers.specialEffects)
            if(item.specialEffect==effect)return true;
        return false;
    }

    private static float EffectSum(Unit unit,string effect,Func<ItemMasterRow,float> selector)
    {
        double sum=0d;
        foreach(var item in unit.itemModifiers.specialEffects)
            if(item.specialEffect==effect)sum+=selector(item);
        return (float)sum;
    }

    private static float EffectMax(Unit unit,string effect,Func<ItemMasterRow,float> selector)
    {
        float maximum=float.NaN;
        bool found=false;
        foreach(var item in unit.itemModifiers.specialEffects)
        {
            if(item.specialEffect!=effect)continue;
            float value=selector(item);
            if(float.IsNaN(maximum)||value>maximum)maximum=value;
            found=true;
        }
        return found?maximum:0f;
    }

    // Return overflow after healing modifiers so conversion cannot bypass healing reduction.
    private float Heal(Unit unit,float amount)
    {
        if(unit==null||unit.augmentShadowClone)return 0f;
        if(amount>0f&&unit.combatStatuses.RejectBenefit(CombatBenefitKind.Healing))return 0f;
        float reduction=0f;
        if(unit.crocodileDeathMarkTimer>0f)
            reduction=CombatStatFormula.Strongest(
                reduction,CrocodileCombatRules.UnderworldHealingReduction);
        if(unit.ninjaHealingReductionTimer>0f)
            reduction=CombatStatFormula.Strongest(
                reduction,NinjaCatCombatRules.HealingReduction);
        if(unit.itemBurnTimer>0f)
            reduction=CombatStatFormula.Strongest(reduction,unit.itemHealingReduction);
        if(unit.familyHealingReductionTimer>0f)
            reduction=CombatStatFormula.Strongest(reduction,unit.familyHealingReductionRatio);
        if(unit.familyRecoveryShieldReductionTimer>0f)
            reduction=CombatStatFormula.Strongest(
                reduction,unit.familyRecoveryShieldReductionRatio);
        amount*=1f-Mathf.Clamp01(reduction);
        if(unit.team==Team.Player)
            amount*=PermanentResearchSystem.RecoveryMultiplier(playerProfile);
        if(amount<=0f||!unit.alive)return 0f;
        float before=unit.hp;
        float overflow=Mathf.Max(0f,amount-(unit.maxHp-before));
        unit.hp=Mathf.Min(unit.maxHp,unit.hp+amount);
        float restored=unit.hp-before;
        if(restored>0.01f)
        {
            unit.healingReceived+=restored;
            AddCombatFloatText(
                unit,"+"+Mathf.CeilToInt(restored),
                new Color(0.34f,1f,0.52f),false,combatResult:true);
        }
        return overflow;
    }

    private static float SkillSupportAmount(Unit source,float amount)
    {
        return amount*Mathf.Max(
            0f,source==null?1f:source.augmentSkillPowerMultiplier*source.spiritConcertScale)*
            (source!=null&&MonsterTraitRuntime.Has(source.activeTraitIds,"trait_rank2_technique")?1.3f:1f);
    }

    private static float GuardianShieldMultiplier(Unit source)=>source!=null&&
        MonsterTraitRuntime.Has(source.activeTraitIds,"trait_rank2_guardian")?1.4f:1f;

    private static float Rank2BuffMultiplier(Unit source)
    {
        if(source==null)return 1f;
        return (MonsterTraitRuntime.Has(source.activeTraitIds,"trait_rank2_guardian")?1.3f:1f)*
            (MonsterTraitRuntime.Has(source.activeTraitIds,"trait_rank2_technique")?1.3f:1f);
    }

    private void BeginWaveLootAttempt()
    {
        pendingWaveLoot.Clear();
        firstTutorialItemDropsSpawned=0;
        ClearLootVisuals();
        ClearSpiderWebZones();
        ClearSpiritGuardSanctuaries();
        ClearSpiritConcertEchoes();
        ClearMammothBoulders();
        ClearMushroomGasZones();
        ClearMushroomCrowns();
        waveLootAttempt++;
        waveDropRandom=new System.Random(MonsterInstanceGenerator.StableSeed(
            expeditionRun.runId+"_wave_"+expeditionRun.wave+"_loot_attempt_"+waveLootAttempt));
        itemUiMessage="";
    }

    private void RollAndShowEnemyLoot(Unit defeated)
    {
        if(waveDropRandom==null||defeated==null||defeated.model==null)return;
        List<EnemyDropRoll> drops=ExpeditionDropSystem.RollEnemyDrops(
            expeditionRun.wave,defeated.expeditionRank,
            defeated.equippedEnemyItems,waveDropRandom);
        ExpeditionAugmentSelectionSave blessing=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.FickleBlessing);
        if(blessing!=null&&ExpeditionAugmentRuntime.BlessingMode(
            blessing,expeditionRun.wave)==1)
        {
            AugmentMasterRow master=GameMasterData.Augment(
                ExpeditionAugmentRuntime.FickleBlessing);
            float currencyMultiplier=master==null?1.60f:
                master.NumericParam("gold_currency_multiplier",1.60f);
            float duplicateChance=master==null?0.50f:
                master.NumericParam("gold_item_duplicate_chance",0.50f);
            foreach(EnemyDropRoll currency in drops.Where(drop=>
                drop.rewardType=="ExpeditionCurrency"))
                currency.amount=Mathf.Min(
                    ExpeditionDropSystem.MaximumCurrencyPerDrop,
                    Mathf.CeilToInt(currency.amount*currencyMultiplier));
            List<EnemyDropRoll> equipment=drops.Where(drop=>
                drop.rewardType=="Equipment").ToList();
            foreach(EnemyDropRoll item in equipment)
                if(waveDropRandom.NextDouble()<duplicateChance)
                    drops.Add(new EnemyDropRoll
                    {rewardType=item.rewardType,itemId=item.itemId,amount=1});
        }
        if(ShouldGuaranteeFirstTutorialItemDrop(
               playerProfile==null?-1:
                   playerProfile.firstExpeditionCaptureGuideStep,
               expeditionRun.wave,firstTutorialItemDropsSpawned))
        {
            drops.RemoveAll(drop=>drop.rewardType=="Equipment");
            ItemMasterRow item=ExpeditionItemSystem.RollBasicItem(waveDropRandom);
            if(item!=null)
            {
                drops.Add(new EnemyDropRoll
                    {rewardType="Equipment",itemId=item.id,amount=1});
                firstTutorialItemDropsSpawned++;
            }
        }
        Vector3 defeatedPosition=defeated.model.transform.position;
        for(int i=0;i<drops.Count;i++)
        {
            EnemyDropRoll drop=drops[i];
            ExpeditionDropSystem.Add(pendingWaveLoot,drop);
            SpawnLootVisual(drop,defeatedPosition);
        }
    }

    public static bool ShouldGuaranteeFirstTutorialItemDrop(
        int tutorialStep,int wave,int itemDropsSpawned)
    {
        return tutorialStep==4&&wave==1&&itemDropsSpawned>=0&&
               itemDropsSpawned<2;
    }

    private void SpawnLootVisual(EnemyDropRoll drop,Vector3 position)
    {
        bool equipment=drop.rewardType=="Equipment";
        GameObject root=new GameObject("Pending Loot - "+drop.rewardType);
        Vector3 anchor=FindOpenLootAnchor(position);
        root.transform.position=anchor;
        SpriteRenderer renderer=root.AddComponent<SpriteRenderer>();
        renderer.sprite=LootPixelSprite(equipment);
        renderer.sortingOrder=0;
        root.AddComponent<SpriteMonsterBillboard>();

        GameObject textObject=new GameObject("Loot Label");
        textObject.transform.position=anchor+Vector3.up*0.52f;
        TextMesh label=textObject.AddComponent<TextMesh>();
        label.text=LootLabel(drop);
        label.anchor=TextAnchor.LowerCenter;
        label.alignment=TextAlignment.Center;
        label.fontSize=48;
        label.characterSize=0.075f;
        label.color=Color.white;
        lootVisuals.Add(new LootVisual
        {
            root=root,
            label=label,
            anchor=anchor,
            phase=(float)waveDropRandom.NextDouble()*Mathf.PI*2f
        });
    }

    private Vector3 FindOpenLootAnchor(Vector3 position)
    {
        Vector3 origin=Flat(position)+Vector3.up*0.35f;
        int sequence=lootVisuals.Count;
        for(int attempt=0;attempt<24;attempt++)
        {
            float angle=(sequence+attempt)*137.5f*Mathf.Deg2Rad;
            float radius=0.72f+(attempt/8)*0.24f;
            Vector3 candidate=origin+new Vector3(
                Mathf.Cos(angle)*radius,0f,Mathf.Sin(angle)*radius);
            if(lootVisuals.All(visual=>visual==null||
                (Flat(visual.anchor)-Flat(candidate)).sqrMagnitude>=0.9f*0.9f))
                return candidate;
        }
        return origin+Vector3.right*(0.72f+sequence*0.18f);
    }

    private void UpdateLootVisuals()
    {
        float time=Time.time;
        for(int i=lootVisuals.Count-1;i>=0;i--)
        {
            LootVisual visual=lootVisuals[i];
            if(visual==null||visual.root==null){lootVisuals.RemoveAt(i);continue;}
            visual.root.transform.position=visual.anchor+
                Vector3.up*(Mathf.Sin(time*2.4f+visual.phase)*0.08f);
            if(visual.label!=null&&mainCamera!=null)
            {
                visual.label.transform.position=visual.root.transform.position+Vector3.up*0.52f;
                visual.label.transform.rotation=mainCamera.transform.rotation;
            }
        }
    }

    private void CommitWaveLoot()
    {
        string summary=pendingWaveLoot.Summary();
        waveLootReviewItemIds.Clear();
        waveLootReviewItemIds.AddRange(pendingWaveLoot.itemIds);
        waveLootReviewGold=pendingWaveLoot.expeditionCurrency;
        waveLootReviewGoldStart=expeditionRun.expeditionCurrency;
        ExpeditionDropSystem.Commit(expeditionRun,pendingWaveLoot);
        Debug.Assert(expeditionRun.expeditionCurrency==
                     waveLootReviewGoldStart+waveLootReviewGold,
            "Wave loot gold must match the animated settlement count.");
        ClearLootVisuals();
        waveDropRandom=null;
        itemUiMessage="Wave 전리품 획득 · "+summary;
    }

    private void DiscardWaveLoot()
    {
        bool hadLoot=!pendingWaveLoot.IsEmpty;
        waveLootReviewItemIds.Clear();
        waveLootReviewGold=0;
        waveLootReviewGoldStart=expeditionRun==null
            ?0:expeditionRun.expeditionCurrency;
        ExpeditionDropSystem.Discard(pendingWaveLoot);
        ClearLootVisuals();
        waveDropRandom=null;
        itemUiMessage=hadLoot?"Wave 실패 · 전리품은 획득되지 않았습니다.":"";
    }

    private void ClearLootVisuals()
    {
        foreach(LootVisual visual in lootVisuals)
        {
            if(visual==null)continue;
            if(visual.label!=null)Destroy(visual.label.gameObject);
            if(visual.root!=null)Destroy(visual.root);
        }
        lootVisuals.Clear();
    }

    private static Sprite LootPixelSprite(bool equipment)
    {
        if(equipment)
        {
            if(itemLootPixelSprite==null)
                itemLootPixelSprite=CreateLootPixelSprite(new[]{
                    "...DDD...","..DLLLD..",".DLLLLLD.","DBBLLLCCD",
                    ".DBBLCCD.","..DBCCD..","...DCD..."
                },"Pixel Loot Cube");
            return itemLootPixelSprite;
        }
        if(goldLootPixelSprite==null)
            goldLootPixelSprite=CreateLootPixelSprite(new[]{
                ".........","...DDD...","..DHHHD..",".DGGGGGD.",
                ".DGOOGGD.","..DGGGD..","...DDD..."
            },"Pixel Loot Gold");
        return goldLootPixelSprite;
    }

    private static Sprite CreateLootPixelSprite(string[] rows,string name)
    {
        int height=rows.Length;
        int width=rows[0].Length;
        Texture2D texture=new Texture2D(width,height,TextureFormat.RGBA32,false)
        {
            name=name,
            filterMode=FilterMode.Point,
            wrapMode=TextureWrapMode.Clamp
        };
        Color32[] pixels=new Color32[width*height];
        for(int y=0;y<height;y++)
        for(int x=0;x<width;x++)
            pixels[y*width+x]=LootPixelColor(rows[height-1-y][x]);
        texture.SetPixels32(pixels);
        texture.Apply(false,true);
        return Sprite.Create(texture,new Rect(0f,0f,width,height),
            new Vector2(0.5f,0.5f),14f,0,SpriteMeshType.FullRect);
    }

    private static Color32 LootPixelColor(char code)
    {
        switch(code)
        {
            case 'D':return new Color32(55,38,33,255);
            case 'H':return new Color32(255,241,139,255);
            case 'G':return new Color32(247,190,37,255);
            case 'O':return new Color32(219,112,28,255);
            case 'L':return new Color32(100,195,238,255);
            case 'B':return new Color32(62,162,218,255);
            case 'C':return new Color32(29,91,151,255);
            default:return new Color32(0,0,0,0);
        }
    }

    private static string LootLabel(EnemyDropRoll drop)
    {
        if(drop.rewardType=="Equipment")
        {
            ItemMasterRow item=GameMasterData.Item(drop.itemId);
            return GameLocalization.Text(item==null?"아이템":item.displayName);
        }
        if(drop.rewardType=="ExpeditionCurrency")return GameLocalization.Format(
            "battle.loot_gold_drop","골드 +{0}",drop.amount);
        return GameLocalization.Text(drop.rewardType)+" +"+drop.amount;
    }

    private float OutgoingGrowthDamageMultiplier(Unit source,Unit target,bool isBasicAttack)
    {
        if(source.team!=Team.Player)return 1f;
        CombatGrowthCardModifiers growth=GrowthModifiers(source.team);
        return CombatGrowthCardCombatRules.OutgoingDamageMultiplier(
            growth,playerDeathsThisWave,AlliesTargeting(source.team,target),
            target==null?1f:target.hp/Mathf.Max(1f,target.maxHp),battleElapsed,
            isBasicAttack&&source.growthPursuitTarget==target?source.growthPursuitHits:0);
    }

    private int AlliesTargeting(Team team,Unit target)
    {
        int attackers=0;
        for(int i=0;i<units.Count;i++)
        {
            Unit ally=units[i];
            if(!IsCombatActive(ally)||ally.team!=team||ally.target!=target)continue;
            attackers++;
        }
        return attackers;
    }

    private void ApplyGrowthCardKillEffects(Unit source,Unit defeated)
    {
        if(source.team!=Team.Player||defeated.team==source.team)return;
        CombatGrowthCardModifiers growth=GrowthModifiers(source.team);
        for(int i=0;i<units.Count;i++)
        {
            Unit ally=units[i];
            if(!IsCombatActive(ally)||ally.augmentShadowClone||
               ally.team!=source.team)continue;
            if(growth.teamKillMissingHealthHealRatio>0f)
                Heal(ally,(ally.maxHp-ally.hp)*growth.teamKillMissingHealthHealRatio);
            if(growth.killTeamAttackSpeedBonus>0f)
                if(!ally.combatStatuses.RejectBenefit())ally.growthKillHasteExpirations.Add(battleElapsed+5f);
        }
    }

    private void ApplyGrowthCardAllyDeathEffects(Unit defeated)
    {
        CombatGrowthCardModifiers growth=GrowthModifiers(defeated.team);
        if(growth.deathShieldRatio<=0f)return;
        for(int i=0;i<units.Count;i++)
        {
            Unit ally=units[i];
            if(ally==defeated||!IsCombatActive(ally)||ally.team!=defeated.team)continue;
            ally.itemShield=GateHaetaeBenefit(ally,ally.itemShield+ally.maxHp*growth.deathShieldRatio,CombatBenefitKind.Shield);
            ally.itemShieldTimer=Mathf.Max(ally.itemShieldTimer,999f);
        }
    }

    private void RotateUnit(Unit unit,Vector3 direction,float dt)
    {
        direction.y=0f;if(direction.sqrMagnitude<0.001f)return;
        direction.Normalize();
        if(unit.spriteBillboard!=null)
            unit.spriteBillboard.SetFacingDirection(direction);
        if(unit.turnAnticipation!=null)
        {
            if(unit.facingDirection.sqrMagnitude<0.001f)
                unit.facingDirection=Flat(unit.model.transform.forward).normalized;
            if(Vector3.Angle(unit.facingDirection,direction)>=2.5f)
            {
                Quaternion current=Quaternion.LookRotation(unit.facingDirection,Vector3.up);
                Quaternion target=Quaternion.LookRotation(direction,Vector3.up);
                unit.facingDirection=(Quaternion.Slerp(
                    current,target,1f-Mathf.Exp(-10f*dt))*Vector3.forward).normalized;
            }
            direction=unit.facingDirection;
            unit.turnAnticipation.SetDesiredDirection(direction);
        }
        // Sprite units also need their combat facing updated for rear-position calculations.
        unit.facingDirection=direction;
        Quaternion desired=Quaternion.LookRotation(direction,Vector3.up);
        unit.model.transform.rotation=Quaternion.Slerp(unit.model.transform.rotation,desired,1f-Mathf.Exp(-6.2f*dt));
    }

    private void SetMoving(Unit unit,bool moving)
    {
        if(unit.combatStatuses.Has(CombatStatusKind.Freeze))return;
        // Keep Run continuous across attack recovery while the body still has momentum.
        moving|=unit.inertiaVelocity.sqrMagnitude>.000001f&&
            unit.inertiaGeneration==combatGeneration&&unit.inertiaPositionRevision==unit.positionRevision&&
            !InertiaBlocked(unit);
        if(unit.spriteAnimation!=null)
            unit.spriteAnimation.SetMoving(moving);
        if(unit.animator==null||!unit.animator.enabled)return;
        unit.animator.SetBool("Moving",moving);
        if(moving&&unit.animator.speed<0.5f)unit.animator.speed=1f;
    }

    private static bool IsUnitMoving(Unit unit)
    {
        return unit.displacing||unit.frogHopping||unit.moving||
               unit.velocity.sqrMagnitude>0.04f;
    }

    private static bool IsMovingTarget(Unit unit)
    {
        return IsCombatActive(unit)&&(unit.displacing||unit.frogHopping||unit.moving);
    }

    private static bool IsAttackMovementLocked(Unit unit)
    {
        return unit.attackMovementLockTimer>0f||
               unit.spriteAnimation!=null&&unit.spriteAnimation.IsActionLocked||
               (unit.tongueWhip!=null&&unit.tongueWhip.IsPlaying);
    }

    private void StopUnitMovement(Unit unit)
    {
        ClearUnitInertia(unit);
        unit.velocity=Vector3.zero;
        unit.moving=false;
        SetMoving(unit,false);
    }

    private void StopBeforeAttack(Unit unit)
    {
        StopUnitMovement(unit);
    }

    private void CheckBattleResult()
    {
        if(battleEnding)return;
        FlushMushroomDeathBlooms();
        bool allies=units.Any(unit=>IsCombatActive(unit)&&
                                      !unit.silkPuppet&&
                                      (!unit.rank3MycokingSummon||IsMushroomDeathBloom(unit))&&
                                      unit.team==Team.Player);
        bool enemies=units.Any(unit=>IsCombatActive(unit)&&
                                       !unit.silkPuppet&&
                                       (!unit.rank3MycokingSummon||IsMushroomDeathBloom(unit))&&
                                       unit.team==Team.Enemy);
        if(allies&&enemies)
        {
            // Final valid ticks resolve before expiry; a last-tick reversal keeps its living flower.
            ExpireMushroomDeathBlooms();
            allies=units.Any(unit=>IsCombatActive(unit)&&!unit.silkPuppet&&
                (!unit.rank3MycokingSummon||IsMushroomDeathBloom(unit))&&unit.team==Team.Player);
            enemies=units.Any(unit=>IsCombatActive(unit)&&!unit.silkPuppet&&
                (!unit.rank3MycokingSummon||IsMushroomDeathBloom(unit))&&unit.team==Team.Enemy);
            if(allies&&enemies)return;
        }
        CancelCommonSkillFocus();
        EndTelemetryEpisode(allies?Team.Player:Team.Enemy);
        pendingResult=allies?"아군 승리":"적군 승리";
        battleEnding=true;
        ClearGriffinCrosswinds();
        GameAudio.FinishCombatLoops();
        PreserveBattleEffects();
        combatGeneration++;
        foreach(var unit in units)
        {
            EndMonkeyNimbus(unit);
            StopSabertoothDragSound(unit);
        }
        for(int i=0;i<units.Count;i++)
            if(units[i].silkPuppet)DeactivateRank3Special(units[i]);
        foreach(var state in familyTranscendenceStates.Values)
            if(state.silkDomain!=null){state.silkDomain.Break();state.silkDomain=null;}
        paused=false;
        ClearSpiderWebZonesAfterBattle();
        ClearMammothBoulders();
        ClearMushroomGasZones();
        ClearMushroomCrowns();
        SetSelectedUnit(null);
        ResetAllOutlines();
        for(int i=0;i<units.Count;i++)
        {
            EndBattleUnitAction(units[i]);
        }
        BeginWaveOutcomePresentation();
        UpdateBattleEnding(0f);
    }

    private void UpdateBattleEnding(float dt)
    {
        for(int i=0;i<units.Count;i++)
            if(IsCombatActive(units[i]))units[i].raptorApexWings?.Tick(dt);
        if(capturePresentationTarget!=null&&!capturePresentationResolving&&
           Time.time-capturePresentationStartedAt>=0.72f)
            BeginCaptureOutcomePresentation();
        UpdateWaveOutcomePresentation(dt);
    }

    private void UpdateWaveOutcomePresentation(float dt)
    {
        if(waveOutcomeStage==WaveOutcomeStage.Death)
        {
            if(!DeathPresentationPending())BeginWaveOutcomeMessage();
            return;
        }
        waveOutcomeTimer=Mathf.Max(0f,waveOutcomeTimer-dt);
        if(waveOutcomeTimer>0f)return;
        if(waveOutcomeStage==WaveOutcomeStage.LootReview)
        {
            CompleteWaveLootReview();
            return;
        }
        // Capture confirmation is independent of skill visuals and keeps its existing presentation.
        if(capturePresentationTarget!=null)return;
        FinalizeWaveOutcome();
    }

    private void FinalizeWaveOutcome()
    {
        combatCameraDirector?.EndBattle();
        ResetFamilyTranscendenceStates();
        foreach(Unit unit in units)
        {
            if(unit.fangLockTarget!=null)FinishFangLock(unit,false);
            unit.combatStatuses.Remove(CombatStatusKind.Silence);
            unit.combatStatuses.Remove(CombatStatusKind.ArmorBroken);
            if(SabertoothCombatRules.HasFangLockDebuff(unit.combatStatuses))
                unit.combatStatuses.Remove(CombatStatusKind.Root);
            unit.raptorApexPredatorTimer=0f;
            unit.raptorApexCooldownFlash=0f;
            unit.raptorApexWings?.Clear();
        }
        battleEnding=false;
        battleStarted=false;
        paused=false;
        waveOutcomeStage=WaveOutcomeStage.None;
        waveOutcomeTimer=0f;
        resultText=pendingResult;
        pendingResult="";
        bool waveCleared=resultText=="아군 승리";
        if(!mlEpisodeActive)GameAudio.SetBattlePhase(false);
#if UNITY_EDITOR
        if(balanceTestRunning)
        {
            DiscardWaveLoot();
            DiscardPendingCapture("");
            CompleteBalanceTestTrial(waveCleared);
            return;
        }
#endif
        if(CombatEffectTestConfiguration.Active)
        {
            DiscardWaveLoot();
            DiscardPendingCapture("");
            return;
        }
        if(mlEpisodeActive)
        {
            AutoBattleMlOutcome outcome=BuildMlOutcome(waveCleared);
            DiscardWaveLoot();
            DiscardPendingCapture("");
            resultText="";
            pendingResult="";
            battleStarted=false;
            mlEpisodeActive=false;
            Action<AutoBattleMlOutcome> completed=mlEpisodeCompleted;
            if(completed!=null)completed(outcome);
            return;
        }
#if UNITY_EDITOR
        if(comboQaRunning)
        {
            DiscardWaveLoot();
            DiscardPendingCapture("");
            StopComboQa("전투가 먼저 종료되어 중단됨",true);
            return;
        }
        if(rosterQaRunning)
        {
            DiscardWaveLoot();
            DiscardPendingCapture("");
            CompleteRosterQaBattle(waveCleared);
            return;
        }
#endif
        CaptureWaveCombatContribution(waveCleared);
        ExpeditionBattleIncome battleIncome=
            ExpeditionDropSystem.ResolveBattleIncome(
                expeditionRun,waveCleared);
        if(waveCleared)
        {
            pendingWaveLoot.expeditionCurrency+=battleIncome.Total;
            ExpeditionDropSystem.ApplyWaveClearGuarantees(
                expeditionRun,pendingWaveLoot,waveDropRandom??new System.Random(
                    MonsterInstanceGenerator.StableSeed(
                        expeditionRun.runId+"_clear_reward_"+expeditionRun.wave)));
            CommitWaveLoot();
            CommitPendingCapture();
            expeditionRun.lastCompletedWave=Mathf.Max(
                expeditionRun.lastCompletedWave,expeditionRun.wave);
            int previousDeploymentLimit=MaxDeploymentCount;
            ExpeditionAugmentRuntime.ProcessWaveCleared(
                expeditionRun,expeditionRun.wave,
                MonsterInstanceGenerator.StableSeed(
                    expeditionRun.runId+"_augment_clear_"+expeditionRun.wave));
            additionalDeploymentSlots=Mathf.Max(
                0,expeditionRun.maxDeploymentCount-BaseDeploymentLimit);
            NotifyDeploymentLimitIncrease(previousDeploymentLimit);
        }
        else
        {
            DiscardWaveLoot();
            expeditionRun.expeditionCurrency+=battleIncome.Total;
            itemUiMessage="전투 수입 · 기본 "+battleIncome.baseIncome+
                " · 이자 "+battleIncome.interestIncome+
                " · 연속 "+battleIncome.streakIncome;
            DiscardPendingCapture(
                pendingCapture.IsReady?"Wave 패배로 포획 결과가 무효가 되었습니다.":"");
        }
        if(waveCleared&&expeditionRun.wave<ExpeditionWaveCount)
        {
            resultText="";
            expeditionRun.checkpoint=ExpeditionRunCheckpoint.GrowthShop;
            BeginWaveLootReview(true,"");
        }
        else if(waveCleared&&expeditionRun.wave>=ExpeditionWaveCount)
        {
            CompleteExpeditionPersistence(true);
        }
        else if(resultText=="적군 승리")
        {
            expeditionRun.lives=Mathf.Max(0,expeditionRun.lives-1);
            bool blessingTriggered=ExpeditionAugmentRuntime.TryGrantLastBlessingReward(
                expeditionRun,out int blessingGold,out ItemMasterRow blessingItem);
            expeditionFailed=expeditionRun.lives<=0;
            resultText=expeditionFailed
                ?"탐험 실패 - 목숨을 모두 잃었습니다"
                :"Wave "+expeditionRun.wave+" 패배 - 목숨 "+expeditionRun.lives+" / "+
                 Mathf.Max(StartingExpeditionLives,expeditionRun.maximumLives);
            if(blessingTriggered)
                resultText+="\n최후의 축복 · 골드 "+blessingGold+
                    (blessingItem==null?"":" · "+blessingItem.displayName);
            if(expeditionFailed)CompleteExpeditionPersistence(false);
            else SaveExpeditionCheckpoint(
                ExpeditionRunCheckpoint.Preparation,false);
        }
    }

    private void BeginWaveLootReview(bool growthAfter,string postReviewResult)
    {
        waveLootReviewGrowthAfter=growthAfter;
        wavePostLootResultText=postReviewResult??"";
        battleEnding=true;
        waveOutcomeStage=WaveOutcomeStage.LootReview;
        waveOutcomeTimer=WaveLootReviewDuration;
    }

    private void CompleteWaveLootReview()
    {
        battleEnding=false;
        waveOutcomeStage=WaveOutcomeStage.None;
        waveOutcomeTimer=0f;
        if(waveLootReviewGrowthAfter)
        {
            resultText="아군 승리";
            AdvanceToNextWave();
        }
        else resultText=wavePostLootResultText;
        waveLootReviewGrowthAfter=false;
        wavePostLootResultText="";
        waveLootReviewGoldStart=expeditionRun==null
            ?0:expeditionRun.expeditionCurrency;
    }

    private AutoBattleMlOutcome BuildMlOutcome(bool won)
    {
        List<Unit> players=units.Where(unit=>unit.team==Team.Player&&!unit.inStorage).ToList();
        List<Unit> enemies=units.Where(unit=>unit.team==Team.Enemy).ToList();
        float playerHpMaximum=players.Sum(unit=>Mathf.Max(0f,unit.maxHp));
        float enemyHpMaximum=enemies.Sum(unit=>Mathf.Max(0f,unit.maxHp));
        return new AutoBattleMlOutcome
        {
            won=won,battleSeconds=battleElapsed,playerDeaths=playerDeathsThisWave,
            playerSurvivors=players.Count(IsCombatActive),
            enemySurvivors=enemies.Count(IsCombatActive),
            survivingPlayerHpRatio=playerHpMaximum<=0f?0f:
                players.Sum(unit=>Mathf.Max(0f,unit.hp))/playerHpMaximum,
            enemyRemainingHpRatio=enemyHpMaximum<=0f?0f:
                enemies.Sum(unit=>Mathf.Max(0f,unit.hp))/enemyHpMaximum
        };
    }

    private void CaptureWaveCombatContribution(bool won)
    {
        if(expeditionRun==null)return;
        WaveCombatContribution snapshot=BuildLiveCombatContribution();
        snapshot.live=false;
        snapshot.won=won;
        combatContributionHistory.RemoveAll(
            item=>item!=null&&item.wave==snapshot.wave);
        combatContributionHistory.Add(snapshot);
        combatContributionHistory.Sort((left,right)=>left.wave.CompareTo(right.wave));
        combatDataSelectedWave=snapshot.wave;
        cachedCombatContributionHistoryCount=-1;
    }

    private WaveCombatContribution BuildLiveCombatContribution()
    {
        WaveCombatContribution snapshot=new WaveCombatContribution
        {
            wave=expeditionRun==null?1:expeditionRun.wave,
            live=battleStarted||battleEnding
        };
        PopulateCombatContribution(snapshot);
        return snapshot;
    }

    private void PopulateCombatContribution(WaveCombatContribution snapshot,bool preparing=false)
    {
        snapshot.wave=expeditionRun==null?1:expeditionRun.wave;
        snapshot.live=battleStarted||battleEnding;
        snapshot.preparing=preparing;
        PopulateCombatContributionTeam(snapshot.allies,Team.Player,preparing);
        PopulateCombatContributionTeam(snapshot.enemies,Team.Enemy,preparing);
    }

    private void PopulateCombatContributionTeam(
        List<CombatContributionEntry> entries,Team team,bool preparing)
    {
        combatContributionUnitsScratch.Clear();
        for(int i=0;i<units.Count;i++)
        {
            Unit candidate=units[i];
            if(candidate!=null&&candidate.team==team&&!candidate.inStorage&&
               !candidate.augmentShadowClone)
                combatContributionUnitsScratch.Add(candidate);
        }
        if(preparing)combatContributionUnitsScratch.Sort((left,right)=>left.id.CompareTo(right.id));
        else combatContributionUnitsScratch.Sort(CombatContributionUnitComparison);
        int count=Mathf.Min(8,combatContributionUnitsScratch.Count);
        while(entries.Count<count)
            entries.Add(new CombatContributionEntry());
        if(entries.Count>count)
            entries.RemoveRange(count,entries.Count-count);
        for(int i=0;i<count;i++)
        {
            Unit unit=combatContributionUnitsScratch[i];
            CombatContributionEntry entry=entries[i];
            entry.stableId=unit.stableId;
            entry.definition=unit.definition;
            entry.displayName=unit.displayName;
            entry.damageDealt=preparing?0f:unit.damageDealt;
            entry.damageTaken=preparing?0f:unit.damageTaken;
            entry.healingReceived=preparing?0f:unit.healingReceived;
            entry.comboActivations=preparing?0:unit.comboActivations;
            entry.comboBonusDamage=preparing?0f:unit.comboBonusDamage;
            entry.survived=preparing||unit.alive;
        }
    }

    private static int CompareCombatContributionUnits(Unit left,Unit right)
    {
        int damage=right.damageDealt.CompareTo(left.damageDealt);
        return damage!=0?damage:left.id.CompareTo(right.id);
    }

    private bool GrowthCardDraftVisible=>false;
    private bool GrowthShopVisible=>growthShopVisible;
    private bool CompletedItemChoiceVisible=>completedItemChoiceIds.Count==3;
    private bool ReserveReinforcementChoiceVisible=>
        reserveReinforcementChoiceIds.Count==3;
    private bool AugmentDraftReady=>string.IsNullOrWhiteSpace(environmentPreviewRegionId)&&
        expeditionRun!=null&&
        expeditionRun.augmentDraftWave==expeditionRun.wave&&
        expeditionRun.augmentDraftIds!=null&&
        expeditionRun.augmentDraftIds.Count==ExpeditionAugmentSystem.ChoiceCount;
    private bool AugmentDraftVisible=>
        AugmentDraftReady&&!augmentDraftIntroductionActive;

    private void PrepareCompletedItemChoice(
        string sourceAugmentId,string targetMonsterInstanceId,int seed)
    {
        List<ItemMasterRow> pool=GameMasterData.Database.items.Where(item=>
            item!=null&&item.enabled&&item.IsCompleted&&
            item.itemPoolId=="default_equipment").OrderBy(item=>
                MonsterInstanceGenerator.StableSeed(seed+"_"+item.id)).ToList();
        if(pool.Count<3)return;
        completedItemChoiceIds.Clear();
        completedItemChoiceIds.AddRange(pool.Take(3).Select(item=>item.id));
        completedItemChoiceSource=sourceAugmentId;
        completedItemChoiceTarget=targetMonsterInstanceId??"";
        completedItemChoiceRerollCount=0;
        completedItemChoiceRevealStartedAt=Time.unscaledTime;
        completedItemChoiceCommittedId="";
        completedItemChoiceCommitStartedAt=-1f;
    }

    private void SelectCompletedItemChoice(string itemId)
    {
        bool radiant=completedItemChoiceSource==ExpeditionAugmentRuntime.DoubleSupply;
        ExpeditionItemInstanceSave item=radiant
            ?ExpeditionItemSystem.CreateRadiantCompletedItem(expeditionRun,itemId)
            :ExpeditionItemSystem.CreateItem(expeditionRun,itemId,true);
        string itemName=ExpeditionItemTransformSystem.DisplayName(item);
        completedItemChoiceIds.Clear();
        completedItemChoiceSource="";
        completedItemChoiceTarget="";
        completedItemChoiceRerollCount=0;
        completedItemChoiceRevealStartedAt=-1f;
        completedItemChoiceCommittedId="";
        completedItemChoiceCommitStartedAt=-1f;
        itemUiMessage=itemName+"을 탐험 가방에 보관했습니다.";
        RefreshAllPlayerItemStats();
        ContinueWavePreparationFlow();
    }

    private void CommitCompletedItemChoice(string itemId)
    {
        if(string.IsNullOrEmpty(itemId)||
           !string.IsNullOrEmpty(completedItemChoiceCommittedId))return;
        completedItemChoiceCommittedId=itemId;
        completedItemChoiceCommitStartedAt=Time.unscaledTime;
        StartCoroutine(CompleteItemChoiceAfterCeremony(itemId));
    }

    private int CompletedItemChoiceRerollCost()
    {
        int initial=Mathf.Max(0,GameMasterData.ExpeditionInt("completed_item_reroll_initial_cost",3));
        int step=Mathf.Max(0,GameMasterData.ExpeditionInt("completed_item_reroll_cost_step",1));
        int baseCost=initial+completedItemChoiceRerollCount*step;
        return Mathf.Max(0,baseCost-
            PermanentResearchSystem.LootRerollDiscount(playerProfile));
    }

    private void RerollCompletedItemChoice()
    {
        if(!CompletedItemChoiceVisible||
           !string.IsNullOrEmpty(completedItemChoiceCommittedId))return;
        int cost=CompletedItemChoiceRerollCost();
        if(expeditionRun.expeditionCurrency<cost)
        {
            itemUiMessage=GameLocalization.TextByKey(
                "research.loot.not_enough_gold","전리품 감정에 필요한 골드가 부족합니다.");
            return;
        }
        string source=completedItemChoiceSource;
        string target=completedItemChoiceTarget;
        int nextCount=completedItemChoiceRerollCount+1;
        expeditionRun.expeditionCurrency-=cost;
        int seed=MonsterInstanceGenerator.StableSeed(
            expeditionRun.runId+"_loot_appraisal_"+expeditionRun.wave+"_"+nextCount);
        PrepareCompletedItemChoice(source,target,seed);
        completedItemChoiceRerollCount=nextCount;
        itemUiMessage=GameLocalization.Format(
            "research.loot.rerolled","전리품 재감정 · 골드 -{0}",cost);
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,false);
    }

    private IEnumerator CompleteItemChoiceAfterCeremony(string itemId)
    {
        while(completedItemChoiceCommittedId==itemId&&
              Time.unscaledTime-completedItemChoiceCommitStartedAt<
              CompletedItemChoiceCommitDuration)
            yield return null;
        while(GameFrontend.HasPendingSave)yield return null;
        if(completedItemChoiceCommittedId==itemId)SelectCompletedItemChoice(itemId);
    }

    private void DrawCompletedItemChoicePanel()
    {
        bool radiant=completedItemChoiceSource==
            ExpeditionAugmentRuntime.DoubleSupply;
        BombBrickUiTheme.DrawModalBackdrop();
        Rect safe=UiLayout.safeArea;
        Rect panel=BombBrickUiLayout.ClampRect(
            new Rect(safe.center.x-460f,safe.center.y-250f,920f,500f),safe);
        BombBrickUiTheme.DrawPanel(panel,true);
        Color accent=radiant?new Color(1f,0.78f,0.22f):BombBrickUiTheme.Orange;
        BombBrickUiTheme.Fill(new Rect(panel.x,panel.y,panel.width,4f),
            accent);
        GUI.Label(new Rect(panel.x+24f,panel.y+22f,panel.width-48f,18f),
            radiant?"찬란한 보급":"생명 담보",
            BombBrickUiTheme.CaptionStyle(10,TextAnchor.MiddleCenter));
        GUI.Label(new Rect(panel.x+24f,panel.y+39f,panel.width-48f,34f),
            radiant?"이중 보급":"생명 저당",
            BombBrickUiTheme.DisplayStyle(25));
        GUI.Label(new Rect(panel.x+24f,panel.y+73f,panel.width-48f,22f),
            radiant
                ?"찬란한 완성 아이템 3개 중 하나를 선택하세요 · 탐험 가방으로 지급"
                :"완성 아이템을 하나 선택하세요",
            BombBrickUiTheme.CaptionStyle(12,TextAnchor.MiddleCenter));
        int rerollCost=CompletedItemChoiceRerollCost();
        bool canReroll=string.IsNullOrEmpty(completedItemChoiceCommittedId)&&
            expeditionRun.expeditionCurrency>=rerollCost;
        if(BombBrickUiTheme.Button(
               new Rect(panel.xMax-194f,panel.y+68f,168f,31f),
               GameLocalization.Format(
                   "research.loot.reroll","재감정 · 골드 {0}",rerollCost),
               canReroll,false))
            RerollCompletedItemChoice();
        float elapsed=completedItemChoiceRevealStartedAt<0f?1f:
            Time.unscaledTime-completedItemChoiceRevealStartedAt;
        for(int i=0;i<completedItemChoiceIds.Count;i++)
        {
            ItemMasterRow baseItem=GameMasterData.Item(completedItemChoiceIds[i]);
            if(baseItem==null)continue;
            ItemMasterRow item=radiant
                ?ExpeditionItemTransformSystem.ResolveEffectiveMaster(
                    new ExpeditionItemInstanceSave{itemId=baseItem.id,
                        transformState=ExpeditionItemTransformState.Radiant})
                :baseItem;
            float reveal=BombBrickUiTheme.EaseOutCubic(
                Mathf.Clamp01((elapsed-i*0.08f)/0.30f));
            Rect card=new Rect(panel.x+26f+i*296f,
                panel.y+116f+(1f-reveal)*28f,276f,342f);
            bool selected=completedItemChoiceCommittedId==baseItem.id;
            float commit=selected?Mathf.Clamp01(
                (Time.unscaledTime-completedItemChoiceCommitStartedAt)/
                CompletedItemChoiceCommitDuration):0f;
            if(selected)card=new Rect(card.x-commit*5f,card.y-commit*5f,
                card.width+commit*10f,card.height+commit*10f);
            bool locked=!string.IsNullOrEmpty(completedItemChoiceCommittedId);
            bool hovered=!locked&&reveal>=0.98f&&
                card.Contains(Event.current.mousePosition);
            Color previous=GUI.color;
            float alpha=reveal*(locked&&!selected?1f-commit*0.78f:1f);
            GUI.color=new Color(1f,1f,1f,alpha);
            BombBrickUiTheme.DrawCard(card,accent,selected,hovered);
            if(selected)BombBrickUiTheme.Frame(card,
                Color.Lerp(accent,Color.white,0.52f),2f+commit*2f);
            Rect iconRect=new Rect(card.center.x-58f,card.y+25f,116f,116f);
            DrawItemIcon(iconRect,item,1);
            if(radiant)DrawRadiantItemFrame(iconRect);
            else BombBrickUiTheme.Badge(
                new Rect(card.center.x-38f,card.y+151f,76f,22f),
                "완성",accent);
            GUI.Label(new Rect(card.x+16f,card.y+183f,card.width-32f,28f),
                item.displayName,
                BombBrickUiTheme.TitleStyle(17,TextAnchor.MiddleCenter));
            GUI.Label(new Rect(card.x+20f,card.y+218f,card.width-40f,48f),
                CompactItemStats(item),
                BombBrickUiTheme.BodyStyle(13,TextAnchor.MiddleCenter));
            GUI.Label(new Rect(card.x+20f,card.y+266f,card.width-40f,34f),
                ItemSpecialEffectTooltip(item),
                BombBrickUiTheme.CaptionStyle(10,TextAnchor.MiddleCenter));
            GUI.Label(new Rect(card.x+26f,card.yMax-42f,card.width-52f,26f),
                selected?"보관함으로 이동 중":"카드 전체를 클릭하여 선택",
                BombBrickUiTheme.CaptionStyle(11,TextAnchor.MiddleCenter));
            if(hovered&&GUI.Button(card,string.Empty,
                   BombBrickUiTheme.ClearButtonStyle()))
                CommitCompletedItemChoice(baseItem.id);
            GUI.color=previous;
        }
    }

    private void PrepareReserveReinforcementChoice(int seed)
    {
        ExpeditionAugmentSelectionSave selection=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.ReserveReinforcement);
        if(selection==null||!string.IsNullOrEmpty(selection.runtimeState))return;
        List<string> stored=string.IsNullOrEmpty(selection.targetItemInstanceId)
            ?new List<string>()
            :selection.targetItemInstanceId.Split('|')
                .Where(id=>monsterDatabase.Get(id)!=null).Distinct().Take(3).ToList();
        if(stored.Count<3)
        {
            stored=monsterDatabase.monsters.Where(definition=>
                    definition!=null&&definition.enabled&&
                    !string.IsNullOrWhiteSpace(definition.resourcePath)&&
                    Resources.Load<GameObject>(definition.resourcePath)!=null)
                .OrderBy(definition=>MonsterInstanceGenerator.StableSeed(
                    seed+"_reserve_candidate_"+definition.monsterId))
                .Select(definition=>definition.monsterId)
                .Distinct().Take(3).ToList();
            selection.targetItemInstanceId=string.Join("|",stored);
        }
        reserveReinforcementChoiceIds.Clear();
        reserveReinforcementChoiceIds.AddRange(stored);
        reserveReinforcementRevealStartedAt=Time.unscaledTime;
        reserveReinforcementCommittedId="";
        reserveReinforcementCommitStartedAt=-1f;
    }

    private ExpeditionMonsterStateSave BuildReserveReinforcementState(
        MonsterDefinition definition,ExpeditionAugmentSelectionSave selection)
    {
        int growth=ExpeditionAugmentRuntime.ReserveReinforcementGrowth(
            selection.acquiredWave);
        ExpeditionMonsterStateSave state=new ExpeditionMonsterStateSave
        {
            instanceId="augment_reserve_"+expeditionRun.runId+"_"+definition.monsterId,
            monsterId=definition.monsterId,
            growthTotal=growth,
            rank=ExpeditionGrowthSystem.RankForGrowth(definition.monsterId,growth),
            temporary=true,
            sourceAugmentId=ExpeditionAugmentRuntime.ReserveReinforcement
        };
        int traitSeed=MonsterInstanceGenerator.StableSeed(
            selection.deterministicSeed+"_reserve_traits_"+definition.monsterId);
        ExpeditionTraitProgression.AssignPreviewTraits(
            state,definition,new System.Random(traitSeed),
            expeditionRun.monsters.Select(item=>monsterDatabase.Get(item.monsterId))
                .Where(item=>item!=null).Concat(new[]{definition}));
        return state;
    }

    private void CommitReserveReinforcementChoice(string monsterId)
    {
        if(string.IsNullOrEmpty(monsterId)||
           !reserveReinforcementChoiceIds.Contains(monsterId)||
           !string.IsNullOrEmpty(reserveReinforcementCommittedId))return;
        reserveReinforcementCommittedId=monsterId;
        reserveReinforcementCommitStartedAt=Time.unscaledTime;
        StartCoroutine(CompleteReserveReinforcementChoice(monsterId));
    }

    private IEnumerator CompleteReserveReinforcementChoice(string monsterId)
    {
        while(reserveReinforcementCommittedId==monsterId&&
              Time.unscaledTime-reserveReinforcementCommitStartedAt<
              ReserveReinforcementCommitDuration)
            yield return null;
        while(GameFrontend.HasPendingSave)yield return null;
        if(reserveReinforcementCommittedId==monsterId)
            SelectReserveReinforcementChoice(monsterId);
    }

    private void SelectReserveReinforcementChoice(string monsterId)
    {
        if(!TrySpawnReserveReinforcement(monsterId))
        {
            reserveReinforcementCommittedId="";
            reserveReinforcementCommitStartedAt=-1f;
            return;
        }
        ExpeditionAugmentSelectionSave selection=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.ReserveReinforcement);
        if(selection!=null)
        {
            selection.runtimeState=monsterId;
            selection.targetItemInstanceId="";
        }
        reserveReinforcementChoiceIds.Clear();
        reserveReinforcementRevealStartedAt=-1f;
        reserveReinforcementCommittedId="";
        reserveReinforcementCommitStartedAt=-1f;
        SaveExpeditionCheckpoint(ExpeditionRunCheckpoint.Preparation,true);
        ContinueWavePreparationFlow();
    }

    private void DrawReserveReinforcementChoicePanel()
    {
        ExpeditionAugmentSelectionSave selection=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.ReserveReinforcement);
        if(selection==null)return;
        BombBrickUiTheme.DrawModalBackdrop();
        Rect safe=UiLayout.safeArea;
        Rect panel=BombBrickUiLayout.ClampRect(
            new Rect(safe.center.x-460f,safe.center.y-250f,920f,500f),safe);
        Color accent=BombBrickUiTheme.Cyan;
        BombBrickUiTheme.DrawPanel(panel,true);
        BombBrickUiTheme.Fill(new Rect(panel.x,panel.y,panel.width,4f),accent);
        GUI.Label(new Rect(panel.x+24f,panel.y+22f,panel.width-48f,18f),
            "예비 지원",BombBrickUiTheme.CaptionStyle(
                10,TextAnchor.MiddleCenter));
        GUI.Label(new Rect(panel.x+24f,panel.y+39f,panel.width-48f,34f),
            "예비 병력 투입",BombBrickUiTheme.DisplayStyle(25));
        int growth=ExpeditionAugmentRuntime.ReserveReinforcementGrowth(
            selection.acquiredWave);
        GUI.Label(new Rect(panel.x+24f,panel.y+73f,panel.width-48f,22f),
            "탐험 종료까지 함께할 지원 병력 선택 · 성장 +"+growth,
            BombBrickUiTheme.CaptionStyle(12,TextAnchor.MiddleCenter));

        float elapsed=reserveReinforcementRevealStartedAt<0f?1f:
            Time.unscaledTime-reserveReinforcementRevealStartedAt;
        for(int i=0;i<reserveReinforcementChoiceIds.Count;i++)
        {
            string monsterId=reserveReinforcementChoiceIds[i];
            MonsterDefinition definition=monsterDatabase.Get(monsterId);
            if(definition==null)continue;
            ExpeditionMonsterStateSave preview=
                BuildReserveReinforcementState(definition,selection);
            OwnedMonsterSave owned=PlayerProfileStore.CreateMonster(
                definition,preview.instanceId,false);
            float reveal=BombBrickUiTheme.EaseOutCubic(
                Mathf.Clamp01((elapsed-i*0.08f)/0.30f));
            Rect card=new Rect(panel.x+26f+i*296f,
                panel.y+116f+(1f-reveal)*28f,276f,342f);
            bool selected=reserveReinforcementCommittedId==monsterId;
            float commit=selected?Mathf.Clamp01(
                (Time.unscaledTime-reserveReinforcementCommitStartedAt)/
                ReserveReinforcementCommitDuration):0f;
            if(selected)card=new Rect(card.x-commit*5f,card.y-commit*5f,
                card.width+commit*10f,card.height+commit*10f);
            bool locked=!string.IsNullOrEmpty(reserveReinforcementCommittedId);
            bool hovered=!locked&&reveal>=0.98f&&
                card.Contains(Event.current.mousePosition);
            Color previous=GUI.color;
            GUI.color=new Color(1f,1f,1f,
                reveal*(locked&&!selected?1f-commit*0.78f:1f));
            BombBrickUiTheme.DrawCard(card,accent,selected,hovered);
            if(selected)
            {
                BombBrickUiTheme.Frame(card,Color.Lerp(accent,Color.white,0.5f),
                    2f+commit*2f);
                for(int pixel=0;pixel<10;pixel++)
                {
                    float angle=pixel*Mathf.PI*0.2f+commit*Mathf.PI;
                    float radius=card.width*(0.36f+commit*0.18f);
                    float size=3f+commit*4f;
                    BombBrickUiTheme.Fill(new Rect(
                        card.center.x+Mathf.Cos(angle)*radius-size*0.5f,
                        card.center.y+Mathf.Sin(angle)*radius*0.82f-size*0.5f,
                        size,size),new Color(accent.r,accent.g,accent.b,1f-commit));
                }
            }
            Rect portrait=new Rect(card.center.x-58f,card.y+24f,116f,116f);
            BombBrickUiTheme.Fill(portrait,BombBrickUiTheme.Backdrop);
            BombBrickUiTheme.Frame(portrait,accent,1f);
            DrawPortrait(new Rect(portrait.x+3f,portrait.y+3f,
