            GUI.Label(new Rect(card.x+16f,card.y+178f,card.width-32f,22f),
                new string('★',Mathf.Max(1,(int)preview.rank))+"  ·  "+
                HunterShopSystem.FamilyDisplayName(definition.familyId)+" 계열",
                BombBrickUiTheme.BodyStyle(12,TextAnchor.MiddleCenter));
            MonsterGrowthMasterRow growthMaster=GameMasterData.MonsterGrowth(monsterId);
            GUI.Label(new Rect(card.x+16f,card.y+202f,card.width-32f,20f),
                (growthMaster==null?"균형 성장":growthMaster.growthRole)+"  ·  "+
                MonsterInstanceGenerator.PersonalityDisplayName(owned.personalityId),
                BombBrickUiTheme.CaptionStyle(10,TextAnchor.MiddleCenter));
            GUI.Label(new Rect(card.x+18f,card.y+232f,card.width-36f,24f),
                "2★ "+TraitName(preview.rank2TraitId),
                BombBrickUiTheme.BodyStyle(11,TextAnchor.MiddleCenter));
            GUI.Label(new Rect(card.x+18f,card.y+258f,card.width-36f,24f),
                "3★ "+TraitName(preview.rank3TraitId),
                BombBrickUiTheme.BodyStyle(11,TextAnchor.MiddleCenter));
            GUI.Label(new Rect(card.x+26f,card.yMax-42f,card.width-52f,26f),
                selected?"대기석으로 소환 중":"카드 전체를 클릭하여 선택",
                BombBrickUiTheme.CaptionStyle(11,TextAnchor.MiddleCenter));
            if(hovered&&GUI.Button(card,string.Empty,
                   BombBrickUiTheme.ClearButtonStyle()))
                CommitReserveReinforcementChoice(monsterId);
            GUI.color=previous;
        }
    }

    private void EnsureAugmentDraft()
    {
        if(expeditionRun==null||!ExpeditionAugmentSystem.IsOfferWave(expeditionRun.wave)||
           expeditionRun.augments.Any(value=>value!=null&&
               value.acquiredWave==expeditionRun.wave))return;
        augmentDraftSequence++;
        int seed=MonsterInstanceGenerator.StableSeed(
            expeditionRun.runId+"_augment_"+expeditionRun.wave+"_"+augmentDraftSequence);
        ExpeditionAugmentSystem.CreateOrRestoreDraft(expeditionRun,seed);
        pendingAugmentId="";
        pendingAugmentMonsterId="";
        augmentChoiceCommittedId="";
        augmentChoiceCommittedMonsterId="";
        augmentChoiceCommitStartedAt=-1f;
        augmentUiMessage="";
        BeginAugmentDraftIntroduction();
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.AugmentDraft,true);
    }

    private void RerollAugmentDraft()
    {
        if(!AugmentDraftVisible||expeditionRun.augmentRerollsRemaining<=0)return;
        augmentDraftSequence++;
        int seed=MonsterInstanceGenerator.StableSeed(
            expeditionRun.runId+"_augment_reroll_"+expeditionRun.wave+"_"+
            augmentDraftSequence);
        ExpeditionAugmentSystem.CreateOrRestoreDraft(expeditionRun,seed,true);
        pendingAugmentId="";
        pendingAugmentMonsterId="";
        augmentChoiceCommittedId="";
        augmentChoiceCommittedMonsterId="";
        augmentChoiceCommitStartedAt=-1f;
        augmentUiMessage="증강 후보를 새로 제시했습니다.";
        augmentDraftRevealStartedAt=Time.unscaledTime;
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.AugmentDraft,true);
    }

    private void BeginAugmentSelection(string augmentId)
    {
        if(!string.IsNullOrEmpty(augmentChoiceCommittedId))return;
        AugmentMasterRow master=GameMasterData.Augment(augmentId);
        if(master==null)return;
        bool needsMonster=master.selectionMode.IndexOf(
            "Monster",StringComparison.OrdinalIgnoreCase)>=0;
        if(needsMonster)
        {
            pendingAugmentId=augmentId;
            pendingAugmentMonsterId="";
            SetSelectedUnit(null);
            inspectedUnit=null;
            augmentUiMessage="적용할 탐험 몬스터를 선택하세요.";
            augmentDraftRevealStartedAt=Time.unscaledTime;
            return;
        }
        CommitAugmentSelection(augmentId,"");
    }

    private void CommitAugmentSelection(
        string augmentId,string monsterInstanceId)
    {
        if(string.IsNullOrEmpty(augmentId)||
           !string.IsNullOrEmpty(augmentChoiceCommittedId))return;
        augmentChoiceCommittedId=augmentId;
        augmentChoiceCommittedMonsterId=monsterInstanceId??"";
        augmentChoiceCommitStartedAt=Time.unscaledTime;
        augmentUiMessage="증강 각인 중";
        StartCoroutine(CompleteAugmentSelectionAfterCeremony());
    }

    private IEnumerator CompleteAugmentSelectionAfterCeremony()
    {
        string augmentId=augmentChoiceCommittedId;
        string monsterId=augmentChoiceCommittedMonsterId;
        while(augmentChoiceCommittedId==augmentId&&
              Time.unscaledTime-augmentChoiceCommitStartedAt<
              AugmentChoiceCommitDuration)
            yield return null;
        if(augmentChoiceCommittedId!=augmentId)yield break;
        augmentChoiceCommittedId="";
        augmentChoiceCommittedMonsterId="";
        augmentChoiceCommitStartedAt=-1f;
        CompleteAugmentSelection(augmentId,monsterId);
    }

    private void CompleteAugmentSelection(string augmentId,string monsterInstanceId)
    {
        int previousDeploymentLimit=MaxDeploymentCount;
        expeditionRun.augmentChoiceSequence++;
        int seed=MonsterInstanceGenerator.StableSeed(
            expeditionRun.runId+"_augment_choice_"+expeditionRun.wave+"_"+
            expeditionRun.augmentChoiceSequence+"_"+augmentId);
        if(!ExpeditionAugmentSystem.TrySelect(
            expeditionRun,augmentId,monsterInstanceId,"",seed,out string error))
        {
            augmentUiMessage=error;
            return;
        }
        AugmentMasterRow selected=GameMasterData.Augment(augmentId);
        augmentUiMessage=(selected==null?augmentId:selected.displayName)+" 획득";
        if(augmentId==ExpeditionAugmentRuntime.LifeExpansion)
            lifeExpansionFeedbackStartedAt=Time.unscaledTime;
        ExpeditionAugmentSelectionSave acquired=ExpeditionAugmentRuntime.Selection(
            expeditionRun,augmentId);
        if(augmentId==ExpeditionAugmentRuntime.AutoDeployment&&
           acquired!=null&&acquired.counter>0)
            augmentUiMessage+=" · 배치 확장 비용 "+acquired.counter+"골드 환불";
        pendingAugmentId="";
        pendingAugmentMonsterId="";
        augmentChoiceCommittedId="";
        augmentChoiceCommittedMonsterId="";
        augmentChoiceCommitStartedAt=-1f;
        augmentDraftIntroductionActive=false;
        augmentDraftIntroductionElapsed=0f;
        augmentDraftRevealStartedAt=-1f;
        SetSelectedUnit(null);
        inspectedUnit=null;
        ApplyAugmentAcquisitionToScene(augmentId,seed);
        NotifyDeploymentLimitIncrease(previousDeploymentLimit);
        RefreshAllPlayerItemStats();
        if(augmentId==ExpeditionAugmentRuntime.GiantSigil)
            EnforceDeploymentLimit(monsterInstanceId);
        PrepareWaveAugmentState();
        if(!CompletedItemChoiceVisible&&!ReserveReinforcementChoiceVisible)
            ContinueWavePreparationFlow();
    }

    private void ApplyAugmentAcquisitionToScene(string augmentId,int seed)
    {
        if(augmentId==ExpeditionAugmentRuntime.PandoraWorkshop)
            ApplyPandoraWaveStart(expeditionRun.wave-1);
        else if(augmentId==ExpeditionAugmentRuntime.ReserveReinforcement)
        {
            PrepareReserveReinforcementChoice(seed);
            SaveExpeditionCheckpoint(ExpeditionRunCheckpoint.AugmentDraft,true);
        }
        else if(augmentId==ExpeditionAugmentRuntime.DoubleSupply||
                augmentId==ExpeditionAugmentRuntime.LifeMortgage)
        {
            ExpeditionAugmentSelectionSave selection=ExpeditionAugmentRuntime.Selection(
                expeditionRun,augmentId);
            PrepareCompletedItemChoice(
                augmentId,selection==null?"":selection.targetMonsterInstanceId,seed);
        }
        additionalDeploymentSlots=Mathf.Max(
            0,expeditionRun.maxDeploymentCount-BaseDeploymentLimit);
    }

    private void EnforceDeploymentLimit(string preferredDeployedMonsterId)
    {
        int movedCount=0;
        while(CurrentDeploymentCount>MaxDeploymentCount)
        {
            Unit candidate=units
                .Where(unit=>unit.team==Team.Player&&!unit.inStorage)
                .OrderBy(unit=>string.Equals(
                    unit.stableId,preferredDeployedMonsterId,
                    StringComparison.Ordinal)?1:0)
                .ThenByDescending(unit=>unit.currentTile.y)
                .ThenByDescending(unit=>unit.currentTile.x)
                .FirstOrDefault();
            if(candidate==null||!MoveUnitToBench(candidate,-1,true))break;
            candidate.initialTile=candidate.currentTile;
            movedCount++;
        }
        if(movedCount>0)
            augmentUiMessage+=" · 배치 한도 초과로 "+movedCount+
                "개체를 대기석으로 이동";
    }

    private bool TrySpawnReserveReinforcement(string monsterId)
    {
        if(units.Count(unit=>unit.team==Team.Player&&!unit.augmentShadowClone)>=BenchSlotCount)
        {
            augmentUiMessage="예비 병력 대기석이 가득 찼습니다.";
            return false;
        }
        MonsterDefinition definition=monsterDatabase.Get(monsterId);
        ExpeditionAugmentSelectionSave selection=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.ReserveReinforcement);
        if(definition==null||selection==null)return false;
        int benchSlot=FindAvailableBenchSlot(null,RosterSize);
        if(benchSlot<0)return false;
        ExpeditionMonsterStateSave state=
            BuildReserveReinforcementState(definition,selection);
        OwnedMonsterSave owned=PlayerProfileStore.CreateMonster(
            definition,state.instanceId,false);
        state.benchSlot=benchSlot;
        expeditionRun.monsters.Add(state);
        Unit joined=SpawnUnit(
            definition,Team.Player,BenchCoordinate(benchSlot),owned,true);
        if(joined!=null)
        {
            CreateSkillPulse(joined,new Color(0.22f,0.92f,1f),1.1f);
            PlayTraitBurst(joined,new Color(0.32f,0.88f,1f),true);
        }
        augmentUiMessage="예비 병력 투입 · "+definition.displayName+
            " 성장 +"+state.growthTotal+" 합류";
        return true;
    }

    private void DrawAugmentDraftPanel()
    {
        if(!string.IsNullOrEmpty(pendingAugmentId))
        {
            DrawAugmentMonsterTargetScreen();
            return;
        }
        Rect safe=UiLayout.safeArea;

        if(augmentDraftRevealStartedAt<0f)
            augmentDraftRevealStartedAt=Time.unscaledTime;
        float revealElapsed=Time.unscaledTime-augmentDraftRevealStartedAt;
        float panelReveal=BombBrickUiTheme.EaseOutCubic(
            Mathf.Clamp01(revealElapsed/0.36f));
        Color backdrop=BombBrickUiTheme.Backdrop;
        backdrop.a*=panelReveal;
        BombBrickUiTheme.Fill(
            new Rect(0f,0f,BombBrickUiLayout.Width,BombBrickUiLayout.Height),backdrop);
        bool revealComplete=revealElapsed>=1.48f;
        float gap=Mathf.Clamp(safe.width*0.018f,16f,24f);
        float margin=Mathf.Clamp(safe.width*0.045f,30f,70f);
        float cardWidth=Mathf.Min(302f,(safe.width-margin*2f-gap*2f)/3f);
        float cardHeight=Mathf.Min(386f,safe.height-210f);
        cardHeight=Mathf.Max(318f,cardHeight);
        float totalWidth=cardWidth*expeditionRun.augmentDraftIds.Count+
                         gap*(expeditionRun.augmentDraftIds.Count-1);
        float startX=safe.center.x-totalWidth*0.5f;
        float blockHeight=68f+cardHeight+52f;
        float cardY=safe.center.y-blockHeight*0.5f+68f;
        cardY=Mathf.Clamp(cardY,safe.y+76f,
            safe.yMax-cardHeight-50f);
        Color previousHeaderColor=GUI.color;
        GUI.color=new Color(1f,1f,1f,panelReveal);
        GUI.Label(new Rect(safe.x+20f,cardY-66f,safe.width-40f,18f),
            "W "+expeditionRun.wave+" · 탐험 각인",
            BombBrickUiTheme.CaptionStyle(10,TextAnchor.MiddleCenter));
        GUI.Label(new Rect(safe.x+20f,cardY-50f,safe.width-40f,34f),
            "탐험 법칙 각인",BombBrickUiTheme.DisplayStyle(25));
        GUI.color=previousHeaderColor;

        Vector2 nexus=new Vector2(safe.center.x,cardY+82f);
        float ritualPulse=0.5f+0.5f*Mathf.Sin(Time.unscaledTime*2.8f);
        DrawGuiRing(nexus,48f+ritualPulse*5f,
            new Color(BombBrickUiTheme.Violet.r,
                BombBrickUiTheme.Violet.g,BombBrickUiTheme.Violet.b,
                0.16f*panelReveal),
            1.4f,28);
        DrawGuiRing(nexus,76f+ritualPulse*8f,
            new Color(BombBrickUiTheme.Cyan.r,
                BombBrickUiTheme.Cyan.g,BombBrickUiTheme.Cyan.b,
                0.1f*panelReveal),
            1f,32);
        DrawGuiDiamond(nexus,6f+ritualPulse*2f,
            new Color(0.72f,0.83f,1f,0.32f*panelReveal));

        for(int i=0;i<expeditionRun.augmentDraftIds.Count;i++)
        {
            string id=expeditionRun.augmentDraftIds[i];
            AugmentMasterRow row=GameMasterData.Augment(id);
            if(row==null)continue;
            Rect card=new Rect(startX+i*(cardWidth+gap),cardY,cardWidth,cardHeight);
            if(DrawAugmentChoiceCard(card,row,i,revealElapsed,revealComplete))
                BeginAugmentSelection(id);
        }

        float footerY=Mathf.Min(safe.yMax-48f,cardY+cardHeight+22f);
        bool canReroll=expeditionRun.augmentRerollsRemaining>0&&
                       revealComplete&&string.IsNullOrEmpty(pendingAugmentId)&&
                       string.IsNullOrEmpty(augmentChoiceCommittedId)&&
                       !FirstExpeditionBattleTutorialActive;
        Rect rerollRect=new Rect(safe.center.x-142f,footerY,284f,34f);
        if(BombBrickUiTheme.Button(rerollRect,
            expeditionRun.augmentRerollsRemaining>0
                ?"선택지 새로고침  ·  무료":"무료 새로고침 사용 완료",
            canReroll,false))
            RerollAugmentDraft();
        if(!string.IsNullOrEmpty(augmentUiMessage))
            GUI.Label(new Rect(safe.x+20f,safe.yMax-27f,safe.width-40f,20f),
                augmentUiMessage,
                BombBrickUiTheme.CaptionStyle(12,TextAnchor.MiddleCenter));
        if(FirstAugmentGuideVisible)
            DrawFirstBattleTutorialFocus(
                new Rect(startX-8f,cardY-8f,totalWidth+16f,cardHeight+16f),
                "증강 하나를 선택하세요.",BombBrickUiTheme.Violet);
    }

    private bool DrawAugmentChoiceCard(Rect baseRect,AugmentMasterRow row,int index,
        float revealElapsed,bool revealComplete)
    {
        float delay=index*0.16f;
        float enterT=Mathf.Clamp01((revealElapsed-delay)/0.78f);
        if(enterT<=0f)return false;
        float settleT=BombBrickUiTheme.EaseOutBack(enterT,0.35f);
        float plateT=BombBrickUiTheme.EaseOutCubic(
            Mathf.Clamp01((revealElapsed-0.18f-delay)/0.68f));
        baseRect.y+=(1f-BombBrickUiTheme.EaseOutCubic(enterT))*44f;
        string lockedId=!string.IsNullOrEmpty(augmentChoiceCommittedId)
            ?augmentChoiceCommittedId:pendingAugmentId;
        bool selected=lockedId==row.id;
        bool interactionLocked=!string.IsNullOrEmpty(augmentChoiceCommittedId)||
            (!string.IsNullOrEmpty(pendingAugmentId)&&!selected);
        bool hovered=revealComplete&&!interactionLocked&&
            baseRect.Contains(Event.current.mousePosition);
        Color accent=AugmentCategoryColor(row.category);
        Vector2 finalIconCenter=new Vector2(baseRect.center.x,baseRect.y+74f);
        Vector2 iconCenter=finalIconCenter+
            new Vector2(0f,(1f-settleT)*34f);
        if(hovered)iconCenter.y-=7f;

        float dimAlpha=interactionLocked&&!selected?0.26f:1f;
        Color previousColor=GUI.color;
        GUI.color=new Color(1f,1f,1f,dimAlpha);
        if(plateT>0f)
        {
            Rect plate=new Rect(baseRect.x,baseRect.y+120f,
                baseRect.width,(baseRect.height-120f)*plateT);
            BombBrickUiTheme.DrawCard(plate,accent,selected,hovered);
        }

        float iconSize=Mathf.Lerp(74f,128f,settleT);
        if(hovered)iconSize+=8f;
        Rect iconRect=new Rect(iconCenter.x-iconSize*0.5f,
            iconCenter.y-iconSize*0.5f,iconSize,iconSize);
        DrawAugmentIcon(iconRect,row,accent,selected||hovered);
        DrawGuiRing(iconCenter,iconSize*0.55f+
            Mathf.Sin(Time.unscaledTime*3.5f+index)*2.5f,
            new Color(accent.r,accent.g,accent.b,
                (selected?0.82f:0.36f)*dimAlpha),
            selected?2.4f:1.2f,24);

        if(!string.IsNullOrEmpty(augmentChoiceCommittedId)&&selected)
        {
            float commitT=Mathf.Clamp01(
                (Time.unscaledTime-augmentChoiceCommitStartedAt)/
                AugmentChoiceCommitDuration);
            DrawGuiRing(iconCenter,iconSize*0.58f+commitT*92f,
                new Color(accent.r,accent.g,accent.b,1f-commitT),
                3f-commitT*1.5f,28);
            DrawGuiRing(iconCenter,iconSize*0.48f+commitT*58f,
                new Color(1f,1f,1f,(1f-commitT)*0.72f),1.5f,24);
        }

        if(plateT>=0.1f)
        {
            bool lifeMortgage=row.id==ExpeditionAugmentRuntime.LifeMortgage;
            bool lifeExpansion=row.id==ExpeditionAugmentRuntime.LifeExpansion;
            bool showsLifePreview=lifeMortgage||lifeExpansion;
            string category=AugmentCategoryLabel(row.category);
            float badgeWidth=Mathf.Clamp(category.Length*12f+22f,76f,132f);
            BombBrickUiTheme.Badge(
                new Rect(baseRect.center.x-badgeWidth*0.5f,
                    baseRect.y+133f,badgeWidth,23f),category,accent);
            GUI.Label(new Rect(baseRect.x+16f,baseRect.y+164f,
                baseRect.width-32f,32f),row.displayName,
                BombBrickUiTheme.TitleStyle(20,TextAnchor.MiddleCenter));
            GUI.Label(new Rect(baseRect.x+18f,baseRect.y+204f,
                baseRect.width-36f,baseRect.height-(showsLifePreview?292f:272f)),
                row.effectSummary,
                BombBrickUiTheme.BodyStyle(13,TextAnchor.UpperCenter));
            if(showsLifePreview&&expeditionRun!=null)
            {
                string lifePreview;
                if(lifeMortgage)
                {
                    int lifeCost=Mathf.Max(1,Mathf.RoundToInt(
                        row.NumericParam("life_cost",1f)));
                    lifePreview="목숨 "+expeditionRun.lives+" → "+
                        Mathf.Max(1,expeditionRun.lives-lifeCost);
                }
                else
                {
                    int maximumLives=Mathf.Max(expeditionRun.maximumLives,
                        Mathf.RoundToInt(row.NumericParam("max_lives",5f)));
                    int lifeGain=Mathf.Max(0,Mathf.RoundToInt(
                        row.NumericParam("life_gain",2f)));
                    lifePreview="목숨 "+expeditionRun.lives+"/"+
                        expeditionRun.maximumLives+" → "+
                        Mathf.Min(maximumLives,expeditionRun.lives+lifeGain)+"/"+
                        maximumLives;
                }
                BombBrickUiTheme.Badge(new Rect(baseRect.center.x-55f,
                    baseRect.yMax-80f,110f,24f),lifePreview,
                    BombBrickUiTheme.Red);
            }
        }

        GUI.color=new Color(1f,1f,1f,dimAlpha*plateT);
        BombBrickUiTheme.Fill(new Rect(baseRect.x+16f,baseRect.yMax-46f,
            baseRect.width-32f,1f),
            new Color(0.25f,0.3f,0.39f,0.72f*plateT));
        string mode=!string.IsNullOrEmpty(augmentChoiceCommittedId)&&selected
            ?"탐험 규칙 각인 중"
            :(selected?"대상 지정 중":
                AugmentSelectionModeLabel(row.selectionMode));
        GUIStyle modeStyle=BombBrickUiTheme.CaptionStyle(12,TextAnchor.MiddleLeft);
        BombBrickUiTheme.Label(new Rect(baseRect.x+16f,baseRect.yMax-37f,
            baseRect.width-32f,22f),mode,modeStyle,
            selected?BombBrickUiTheme.Lime:BombBrickUiTheme.TextSecondary);
        GUI.color=previousColor;

        if(!revealComplete||interactionLocked)return false;
        GUIStyle clickStyle=BombBrickUiTheme.ClearButtonStyle();
        return GUI.Button(baseRect,string.Empty,clickStyle);
    }

    private void DrawAugmentMonsterTargetScreen()
    {
        List<Unit> roster=units.Where(unit=>unit.team==Team.Player&&
            !unit.augmentShadowClone)
            .OrderBy(unit=>unit.inStorage?1:0)
            .Take(BenchSlotCount).ToList();
        Rect safe=UiLayout.safeArea;
        Rect details=OwnedMonsterDetailsRect;
        BombBrickUiTheme.Fill(new Rect(0f,0f,BombBrickUiLayout.Width,BombBrickUiLayout.Height),
            new Color(0.01f,0.015f,0.025f,0.74f));

        if(augmentDraftRevealStartedAt<0f)
            augmentDraftRevealStartedAt=Time.unscaledTime;
        float reveal=BombBrickUiTheme.EaseOutCubic(Mathf.Clamp01(
            (Time.unscaledTime-augmentDraftRevealStartedAt)/0.28f));
        Rect panel=BombBrickUiLayout.AugmentTargetPanel(
            safe,details,roster.Count,out int columns);
        panel.y+=(1f-reveal)*24f;
        panel=BombBrickUiLayout.ClampRect(panel,safe,12f);
        BombBrickUiTheme.DrawPanel(panel,true);
        BombBrickUiTheme.Fill(new Rect(panel.x,panel.y,5f,panel.height),
            BombBrickUiTheme.Cyan);

        AugmentMasterRow augment=GameMasterData.Augment(pendingAugmentId);
        string augmentName=augment==null?pendingAugmentId:augment.displayName;
        GUI.Label(new Rect(panel.x+20f,panel.y+12f,panel.width-128f,16f),
            "증강 대상 지정",BombBrickUiTheme.CaptionStyle(10));
        GUI.Label(new Rect(panel.x+20f,panel.y+29f,panel.width-128f,29f),
            augmentName,BombBrickUiTheme.TitleStyle(22));
        GUI.Label(new Rect(panel.x+20f,panel.y+59f,panel.width-40f,28f),
            "아군을 선택하면 오른쪽에서 능력치와 특성을 확인할 수 있습니다.",
            BombBrickUiTheme.BodyStyle(12));
        bool committing=!string.IsNullOrEmpty(augmentChoiceCommittedId);
        if(BombBrickUiTheme.Button(
            new Rect(panel.xMax-102f,panel.y+14f,82f,32f),"뒤로",!committing,false))
        {
            pendingAugmentId="";
            pendingAugmentMonsterId="";
            augmentUiMessage="";
            augmentDraftRevealStartedAt=Time.unscaledTime;
            SetSelectedUnit(null);
            inspectedUnit=null;
            return;
        }

        int rows=Mathf.Max(1,Mathf.CeilToInt(roster.Count/(float)columns));
        float gap=8f;
        float gridY=panel.y+98f;
        float footerHeight=58f;
        float cardWidth=(panel.width-36f-gap*(columns-1))/columns;
        float cardHeight=Mathf.Clamp(
            (panel.yMax-footerHeight-gridY-gap*(rows-1))/rows,84f,122f);
        for(int i=0;i<roster.Count;i++)
        {
            Unit unit=roster[i];
            int column=i%columns;
            int row=i/columns;
            int itemsInRow=Mathf.Min(columns,roster.Count-row*columns);
            float rowWidth=itemsInRow*cardWidth+Mathf.Max(0,itemsInRow-1)*gap;
            float rowStart=panel.center.x-rowWidth*0.5f;
            Rect choice=new Rect(
                rowStart+column*(cardWidth+gap),gridY+row*(cardHeight+gap),
                cardWidth,cardHeight);
            bool valid=ExpeditionAugmentSystem.CanTargetMonster(
                expeditionRun,pendingAugmentId,unit.stableId);
            bool selected=string.Equals(
                pendingAugmentMonsterId,unit.stableId,StringComparison.Ordinal);
            bool hovered=valid&&!committing&&choice.Contains(Event.current.mousePosition);
            BombBrickUiTheme.Fill(choice,selected
                ?new Color(0.04f,0.28f,0.32f,0.98f)
                :hovered?BombBrickUiTheme.SurfaceHover:BombBrickUiTheme.Surface);
            BombBrickUiTheme.Frame(choice,selected?BombBrickUiTheme.Cyan:
                hovered?BombBrickUiTheme.Lime:
                valid?BombBrickUiTheme.Border:BombBrickUiTheme.Red,
                selected?3f:hovered?2f:1f);
            Color previous=GUI.color;
            if(!valid)GUI.color=new Color(1f,1f,1f,0.38f);
            float portraitSize=Mathf.Min(
                choice.width-14f,Mathf.Max(34f,choice.height-43f));
            DrawPortrait(new Rect(
                    choice.center.x-portraitSize*0.5f,choice.y+5f,
                    portraitSize,portraitSize),
                unit.definition,unit.ownedInstance);
            GUI.Label(new Rect(choice.x+4f,choice.yMax-36f,choice.width-8f,18f),
                valid?ShortText(unit.displayName,10):"선택 불가",
                BombBrickUiTheme.TitleStyle(12,TextAnchor.MiddleCenter));
            ExpeditionMonsterStateSave state=ExpeditionItemSystem.MonsterState(
                expeditionRun,unit.stableId);
            GUI.Label(new Rect(choice.x+4f,choice.yMax-19f,choice.width-8f,15f),
                new string('★',DisplayStarCount(state))+" · "+
                (state==null?0:state.growthTotal)+"/"+
                ExpeditionGrowthSystem.MaximumGrowth,
                BombBrickUiTheme.CaptionStyle(9,TextAnchor.MiddleCenter));
            GUI.color=previous;
            if(valid&&!committing&&
               GUI.Button(choice,string.Empty,BombBrickUiTheme.ClearButtonStyle()))
            {
                pendingAugmentMonsterId=unit.stableId;
                inspectedUnit=unit;
                SetSelectedUnit(unit);
                augmentUiMessage=unit.displayName+" 선택 · 정보 확인 후 확정하세요.";
            }
        }

        Unit target=roster.FirstOrDefault(unit=>string.Equals(
            unit.stableId,pendingAugmentMonsterId,StringComparison.Ordinal));
        bool canConfirm=!committing&&target!=null&&
            ExpeditionAugmentSystem.CanTargetMonster(
                expeditionRun,pendingAugmentId,pendingAugmentMonsterId);
        float footerY=panel.yMax-46f;
        GUI.Label(new Rect(panel.x+20f,footerY,panel.width-204f,32f),
            target==null?"적용할 아군을 선택하세요.":
                target.displayName+"에게 "+augmentName+" 적용",
            BombBrickUiTheme.BodyStyle(12,TextAnchor.MiddleLeft));
        if(BombBrickUiTheme.Button(
            new Rect(panel.xMax-178f,footerY,158f,34f),
            committing?"적용 중":target==null?"대상 선택 필요":"선택 확정",
            canConfirm,true))
            CommitAugmentSelection(pendingAugmentId,pendingAugmentMonsterId);

        if(inspectedUnit!=null&&inspectedUnit.team==Team.Player)
            DrawOwnedMonsterDetails();
        else
        {
            BombBrickUiTheme.DrawPanel(details,true);
            BombBrickUiTheme.Fill(new Rect(details.x,details.y,4f,details.height),
                BombBrickUiTheme.Cyan);
            GUI.Label(new Rect(details.x+20f,details.y+22f,details.width-40f,18f),
                "선택한 아군 정보",BombBrickUiTheme.CaptionStyle(10));
            GUI.Label(new Rect(details.x+20f,details.center.y-28f,
                details.width-40f,56f),"아군 카드를 선택하세요",
                BombBrickUiTheme.TitleStyle(19,TextAnchor.MiddleCenter));
        }
    }

    private static Color AugmentCategoryColor(string category)
    {
        if(string.Equals(category,"MonsterGrowth",StringComparison.OrdinalIgnoreCase))
            return BombBrickUiTheme.Orange;
        if(string.Equals(category,"SkillRule",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"Summon",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"DeathRule",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"CycleRule",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"SpecialItem",StringComparison.OrdinalIgnoreCase))
            return BombBrickUiTheme.Violet;
        if(string.Equals(category,"Economy",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"EconomyRule",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"Mission",StringComparison.OrdinalIgnoreCase))
            return BombBrickUiTheme.Lime;
        if(category!=null&&category.IndexOf(
            "Item",StringComparison.OrdinalIgnoreCase)>=0)
            return new Color(0.95f,0.54f,0.25f);
        if(string.Equals(category,"Formation",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"Placement",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"CombatRule",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"Roster",StringComparison.OrdinalIgnoreCase))
            return BombBrickUiTheme.Cyan;
        if(string.Equals(category,"RiskReward",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"LifeRule",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"Comeback",StringComparison.OrdinalIgnoreCase))
            return BombBrickUiTheme.Red;
        return new Color(0.4f,0.66f,0.94f);
    }

