            return "몬스터 성장";
        if(string.Equals(category,"SkillRule",StringComparison.OrdinalIgnoreCase))
            return "스킬 규칙";
        if(string.Equals(category,"Economy",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"EconomyRule",StringComparison.OrdinalIgnoreCase))
            return "탐험 경제";
        if(category!=null&&category.IndexOf(
            "Item",StringComparison.OrdinalIgnoreCase)>=0)
            return "아이템 규칙";
        if(string.Equals(category,"Formation",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"Placement",StringComparison.OrdinalIgnoreCase))
            return "배치 전술";
        if(string.Equals(category,"Roster",StringComparison.OrdinalIgnoreCase))
            return "탐험대";
        if(string.Equals(category,"RiskReward",StringComparison.OrdinalIgnoreCase))
            return "위험 거래";
        if(string.Equals(category,"LifeRule",StringComparison.OrdinalIgnoreCase)||
           string.Equals(category,"Comeback",StringComparison.OrdinalIgnoreCase))
            return "생명 규칙";
        if(string.Equals(category,"Summon",StringComparison.OrdinalIgnoreCase))
            return "소환 규칙";
        if(string.Equals(category,"DeathRule",StringComparison.OrdinalIgnoreCase))
            return "사망 규칙";
        if(string.Equals(category,"CombatRule",StringComparison.OrdinalIgnoreCase))
            return "전투 규칙";
        return "특수 규칙";
    }

    private static string AugmentSelectionModeLabel(string mode)
    {
        if(string.IsNullOrEmpty(mode))return "즉시 적용";
        if(mode.IndexOf("Choice",StringComparison.OrdinalIgnoreCase)>=0)
            return "아이템 선택";
        if(mode.IndexOf("Grant",StringComparison.OrdinalIgnoreCase)>=0)
            return "특수 아이템 지급";
        if(mode.IndexOf("Monster",StringComparison.OrdinalIgnoreCase)>=0)
            return "몬스터 지정";
        if(mode.IndexOf("Item",StringComparison.OrdinalIgnoreCase)>=0)
            return "아이템 지정";
        return "즉시 적용";
    }

    private void GenerateGrowthCardDraft()
    {
        ResetGrowthCardDrag();
        growthCardDraft.Clear();
        growthCardDraftRerolled=false;
        growthCardDraftSequence++;
        int seed=MonsterInstanceGenerator.StableSeed(
            expeditionRun.runId+"_"+expeditionRun.wave+"_"+growthCardDraftSequence);
        growthCardDraft.AddRange(CombatGrowthCardDraftService.CreateDraft(expeditionRun.wave,seed));
        BeginGrowthCardReveal();
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.GrowthReward,false);
    }

    private void OpenGrowthShop(bool reopen=false)
    {
        if(expeditionRun==null||battleStarted||resultText.Length>0)return;
        ExpeditionGrowthSystem.PrepareWave(expeditionRun);
        if(expeditionRun.growthShopCompletedWave==expeditionRun.wave&&!reopen)
        {
            growthShopVisible=false;
            ContinueWavePreparationFlow();
            return;
        }
        growthShopVisible=true;
        growthShopClosing=false;
        growthShopTransitionStartedAt=Time.unscaledTime;
        GameAudio.Play(GameAudio.Cue.SlideOpen);
        growthShopCardsRevealStartedAt=Time.unscaledTime;
        growthShopRerollFeedbackStartedAt=-1f;
        growthShopSelectedMonsterIds.Clear();
        growthShopFeedbackMonsterId="";
        growthShopFeedbackStartedAt=-1f;
        shopVisible=false;
        ClearPreparationSelection();
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.GrowthShop,true);
    }

    private void PurchaseGrowth(string monsterInstanceId)
    {
        ExpeditionMonsterStateSave state=expeditionRun.monsters.FirstOrDefault(value=>
            value!=null&&value.instanceId==monsterInstanceId);
        if(state==null)return;
        bool wasTranscended=state.transcended;
        string activatedTraitId=ExpeditionTraitProgression.NextTraitId(state);
        if(!ExpeditionGrowthSystem.TryPurchase(
            expeditionRun,monsterInstanceId,out int amount,
            out ExpeditionMonsterRank previousRank,out string error))
        {
            itemUiMessage=error;
            ShowItemActionFeedback(error);
            return;
        }

        Unit unit=units.FirstOrDefault(value=>value!=null&&
            value.team==Team.Player&&value.stableId==monsterInstanceId);
        if(unit!=null)
            RefreshUnitFromOwnedData(unit,unit.definition,unit.ownedInstance);
        growthShopFeedbackMonsterId=monsterInstanceId;
        growthShopFeedbackAmount=amount;
        growthShopFeedbackStartedAt=Time.unscaledTime;
        string monsterName=unit==null
            ?GameLocalization.TextByKey("common.monster","몬스터")
            :GameLocalization.Text(unit.displayName);
        itemUiMessage=monsterName+" "+GameLocalization.Format(
            "growth.feedback","성장 +{0}",amount)+" · "+
            state.growthTotal+" / "+ExpeditionGrowthSystem.MaximumGrowth;
        if(state.rank>previousRank)
        {
            MonsterTraitDefinition trait=MonsterTraitCatalog.Get(activatedTraitId);
            itemUiMessage+=" · "+GameLocalization.Format(
                "growth.preview_rank","{0} 달성",
                new string('★',(int)state.rank));
            if(trait!=null)
                itemUiMessage+=" · "+GameLocalization.Format(
                    "growth.trait_activated","{0} 활성화",
                    GameLocalization.Text(trait.displayName));
            ShowGrowthRankUp(unit,state.rank);
        }
        if(!wasTranscended&&state.transcended)
        {
            string transcendenceName=unit==null||unit.definition==null
                ?string.Empty
                :IsRaptorFamily(unit)?"정점 포식자":
                    FamilyTranscendenceRules.DisplayName(unit.definition.familyId);
            itemUiMessage+=" · ★★★★ "+GameLocalization.TextByKey(
                "status.transcend","초월")+
                (string.IsNullOrEmpty(transcendenceName)
                    ?string.Empty:" · "+GameLocalization.Text(
                        transcendenceName));
        }
        ShowItemActionFeedback(itemUiMessage);
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.GrowthShop,true);
    }

    private void RerollGrowthShop()
    {
        int rerollCost=ExpeditionGrowthSystem.RerollCostFor(
            expeditionRun,playerProfile);
        if(!ExpeditionGrowthSystem.TryReroll(
               expeditionRun,growthShopSelectedMonsterIds,playerProfile,
               out string error))
        {
            itemUiMessage=error;
            ShowItemActionFeedback(error);
            return;
        }
        HashSet<string> candidates=new HashSet<string>(
            expeditionRun.growthShopCandidateMonsterIds,StringComparer.Ordinal);
        growthShopSelectedMonsterIds.RemoveAll(id=>!candidates.Contains(id));
        growthShopCardsRevealStartedAt=Time.unscaledTime;
        growthShopRerollFeedbackStartedAt=Time.unscaledTime;
        growthShopFeedbackMonsterId="";
        growthShopFeedbackStartedAt=-1f;
        itemUiMessage="미선택 성장 후보 리롤 · 골드 -"+
            rerollCost;
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.GrowthShop,true);
    }

    private void PurchaseSelectedGrowth()
    {
        if(growthShopSelectedMonsterIds.Count==0)
        {
            CompleteGrowthShop();
            return;
        }
        List<string> selected=growthShopSelectedMonsterIds.ToList();
        bool valid=selected.All(id=>expeditionRun.monsters.Any(value=>
            value!=null&&value.instanceId==id&&
            value.growthTotal<ExpeditionGrowthSystem.MaximumGrowth&&
            !expeditionRun.growthShopPurchasedMonsterIds.Contains(id)));
        if(!valid)return;
        int totalCost=ExpeditionGrowthSystem.SelectionCost(expeditionRun,selected);
        if(expeditionRun.expeditionCurrency<totalCost)
        {
            itemUiMessage="선택한 성장에 필요한 골드가 부족합니다.";
            return;
        }
        bool tutorialPurchase=FirstGrowthShopGuideVisible;
        foreach(string id in selected)PurchaseGrowth(id);
        growthShopSelectedMonsterIds.Clear();
        if(tutorialPurchase)CompleteGrowthShop();
    }

    private void CompleteGrowthShop()
    {
        if(growthShopClosing)return;
        if(FirstGrowthShopGuideVisible&&
           !ExpeditionGrowthSystem.CanCompleteShop(expeditionRun))
        {
            itemUiMessage="무료 성장을 먼저 선택하세요.";
            return;
        }
        expeditionRun.growthShopCompletedWave=expeditionRun.wave;
        growthShopSelectedMonsterIds.Clear();
        growthShopClosing=true;
        growthShopTransitionStartedAt=Time.unscaledTime;
        GameAudio.Play(GameAudio.Cue.SlideClose);
        StartCoroutine(CompleteGrowthShopCloseTransition());
    }

    private IEnumerator CompleteGrowthShopCloseTransition()
    {
        float startedAt=growthShopTransitionStartedAt;
        while(growthShopClosing&&growthShopTransitionStartedAt==startedAt&&
              Time.unscaledTime-startedAt<GrowthShopCloseDuration)
            yield return null;
        while(GameFrontend.HasPendingSave)yield return null;
        while(GameFrontend.HasPendingSave)yield return null;
        if(!growthShopClosing||growthShopTransitionStartedAt!=startedAt)yield break;
        growthShopClosing=false;
        growthShopVisible=false;
        growthShopTransitionStartedAt=-1f;
        growthShopCardsRevealStartedAt=-1f;
        growthShopRerollFeedbackStartedAt=-1f;
        growthShopFeedbackMonsterId="";
        growthShopFeedbackStartedAt=-1f;
        ContinueWavePreparationFlow();
    }

    private void ContinueWavePreparationFlow()
    {
        if(expeditionRun==null||battleStarted||wavePreparationAcrossFrames)return;
        if(CombatEffectTestConfiguration.Active||
           !string.IsNullOrWhiteSpace(environmentPreviewRegionId))
        {
            if(!waveArrivalActive&&!waveIntroActive)BeginWaveArrival();
            return;
        }
        if(waveArrivalElapsed<WaveArrivalDuration)
        {
            if(ShouldSkipWaveIntro())
                waveArrivalElapsed=WaveArrivalDuration;
            else
            {
                if(!waveArrivalActive&&!waveIntroActive)BeginWaveArrival();
                return;
            }
        }
        EnsureAugmentDraft();
        if(AugmentDraftReady)return;
        if(expeditionRun.growthShopCompletedWave!=expeditionRun.wave)
        {
            OpenGrowthShop();
            return;
        }
        if(TryBeginFirstItemGuide())return;
        if(TryBeginFirstCaptureGuide())return;
        if(FirstExpeditionBattleTutorialStep>=2&&
           FirstExpeditionBattleTutorialStep<8)return;
        if(ExpeditionShopSystem.IsShopWave(expeditionRun.wave)&&
           expeditionRun.shopWave!=expeditionRun.wave)
        {
            Debug.Assert(waveArrivalElapsed>=WaveArrivalDuration,
                "Wave arrival must finish before the item shop opens.");
            OpenShop();
            return;
        }
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,true);
    }

    private void RerollGrowthCardDraft()
    {
        int rerollCost=GrowthCardRerollCost;
        if(!GrowthCardDraftVisible||growthCardDraftRerolled||expeditionRun.expeditionCurrency<rerollCost)return;
        ResetGrowthCardDrag();
        expeditionRun.expeditionCurrency-=rerollCost;
        growthCardDraftRerolled=true;
        growthCardDraftSequence++;
        int seed=MonsterInstanceGenerator.StableSeed(
            expeditionRun.runId+"_"+expeditionRun.wave+"_reroll_"+growthCardDraftSequence);
        growthCardDraft.Clear();
        growthCardDraft.AddRange(CombatGrowthCardDraftService.CreateDraft(expeditionRun.wave,seed));
        BeginGrowthCardReveal();
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.GrowthReward,false);
    }

    private void SelectGrowthCard(int index)
    {
        if(index<0||index>=growthCardDraft.Count)return;
        ResetGrowthCardDrag();
        growthCardRevealStartedAt=-1f;
        CombatGrowthCardDraftEntry selected=growthCardDraft[index];
        expeditionRun.growthCards.Add(new CombatGrowthCardSelectionSave
        {
            cardId=selected.cardId,
            rarity=selected.rarity
        });
        growthCardDraft.Clear();
        AdvanceToNextWave();
    }

    private void AdvanceToNextWave()
    {
        if(wavePreparationAcrossFrames)return;
        int completedWave=expeditionRun.wave;
        expeditionRun.wave=Mathf.Min(ExpeditionWaveCount,expeditionRun.wave+1);
        if(expeditionRun.wave>completedWave)
            ApplyPandoraWaveStart(completedWave);
        PreparePlayerWave(true,()=>
        {if(expeditionRun.wave>completedWave)ContinueWavePreparationFlow();});
    }

    private void ApplyPandoraWaveStart(int completedWave)
    {
        if(ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.PandoraWorkshop)==null)return;
        List<string> transformedItemIds=new List<string>();
        ExpeditionItemInstanceSave granted=
            ExpeditionAugmentRuntime.ProcessPandoraWorkshopWaveEntered(
                expeditionRun,completedWave,
                MonsterInstanceGenerator.StableSeed(
                    expeditionRun.runId+"_pandora_enter_"+expeditionRun.wave),
                transformedItemIds);
        if(transformedItemIds.Count==0&&granted==null)return;
        pandoraTransitionItemIds.Clear();
        pandoraTransitionItemIds.UnionWith(transformedItemIds);
        pandoraGrantedItemInstanceId=granted==null?"":granted.instanceId;
        pandoraTransitionStartedAt=-1f;
    }

    private void RetryCurrentWave()
    {
        if(wavePreparationAcrossFrames||expeditionFailed||expeditionRun.lives<=0)return;
        PreparePlayerWave(false,()=>SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,true));
    }

    private void PrepareNextWave(bool generateNewLayout)
    {
        var preparation=PrepareNextWaveRoutine(generateNewLayout);
        try{while(preparation.MoveNext()){}}
        finally{(preparation as IDisposable)?.Dispose();}
    }

    private IEnumerator PrepareNextWaveRoutine(bool generateNewLayout)
    {
        CancelCommonSkillFocus();
        StopFamilyRank4CinematicAudio();raptorCinematicStage?.Hide();
        foreach(Unit unit in units)ClearUnitInertia(unit);
        CombatEffectEndPlayback.Clear(gameObject.scene);
        FrogTongueWhip.ClearBattleEndTails(gameObject.scene);
        ClearBattleEffects();
        combatDataSelectedWave=combatContributionHistory.LastOrDefault()?.wave??expeditionRun.wave;
        nextCombatContributionRefreshAt=0f;
        combatCameraDirector?.EndBattle();
        combatGeneration++;
        meadowAmbientParticles?.ClearImpacts();
        GameAudio.SetBattlePhase(false);
        CancelCapturePresentation();
        RestoreMapIntroductionObjects();
        ResetFamilyTranscendenceStates();
        waveIntroActive=false;
        waveIntroElapsed=0f;
        waveArrivalActive=false;
        waveArrivalElapsed=generateNewLayout?0f:WaveArrivalDuration;
        augmentDraftIntroductionActive=false;
