    private void PrepareWaveAugmentState()
    {
        ExpeditionAugmentSelectionSave legacy=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.LegacyInheritance);
        if(legacy!=null)legacy.triggered=false;
        ExpeditionAugmentSelectionSave twin=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.TwinCommand);
        if(twin!=null&&(twin.runtimeWave!=expeditionRun.wave||
           string.IsNullOrEmpty(twin.targetItemInstanceId)))
        {
            List<Vector2Int> candidates=PlayerDeploymentCoordinates();
            System.Random random=new System.Random(MonsterInstanceGenerator.StableSeed(
                expeditionRun.runId+"_twin_tiles_"+expeditionRun.wave));
            for(int i=candidates.Count-1;i>0;i--)
            {
                int swap=random.Next(i+1);
                Vector2Int value=candidates[i];
                candidates[i]=candidates[swap];
                candidates[swap]=value;
            }
            twin.runtimeWave=expeditionRun.wave;
            twin.runtimeState="";
            twin.targetItemInstanceId=string.Join("|",candidates.Take(2)
                .Select(tile=>tile.x+","+tile.y));
        }
        RefreshAllTileVisuals();
    }

    private void RemoveAugmentClones()
    {
        List<Unit> clones=units.Where(unit=>unit.augmentShadowClone).ToList();
        for(int i=0;i<clones.Count;i++)RemoveUnitFromRoster(clones[i]);
    }

    private void BindTwinCommandUnits()
    {
        twinCommandPulseSourceId="";
        twinCommandPulseTargetId="";
        twinCommandPulseStartedAt=-1f;
        combinedCastPulseCommanderId="";
        combinedCastPulseContributorIds.Clear();
        combinedCastPulseStartedAt=-1f;
        ExpeditionAugmentSelectionSave twin=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.TwinCommand);
        if(twin==null||string.IsNullOrEmpty(twin.targetItemInstanceId))return;
        List<string> linked=new List<string>();
        foreach(string token in twin.targetItemInstanceId.Split('|'))
        {
            string[] values=token.Split(',');
            if(values.Length!=2||!int.TryParse(values[0],out int x)||
               !int.TryParse(values[1],out int y))continue;
            Unit unit=UnitAt(new Vector2Int(x,y));
            if(unit!=null&&unit.team==Team.Player&&!unit.inStorage)
                linked.Add(unit.stableId);
        }
        linked=linked.Distinct().Take(2).ToList();
        twin.runtimeState=string.Join("|",linked);
        if(linked.Count<2)return;
        AugmentMasterRow master=GameMasterData.Augment(
            ExpeditionAugmentRuntime.TwinCommand);
        float openingCharge=master==null?0.30f:
            master.NumericParam("initial_skill_charge",0.30f);
        foreach(Unit unit in units.Where(value=>value.team==Team.Player&&
                     linked.Contains(value.stableId)))
            unit.skillTimer=ExpeditionAugmentRuntime.ReduceRemainingCooldown(
                unit.skillTimer,openingCharge);
    }

    private void SpawnAugmentShadowClone()
    {
        ExpeditionAugmentSelectionSave shadow=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.ShadowClone);
        Unit source=shadow==null?null:units.FirstOrDefault(unit=>
            unit.team==Team.Player&&!unit.inStorage&&!unit.augmentShadowClone&&
            unit.stableId==shadow.targetMonsterInstanceId);
        if(source==null||source.ownedInstance==null)return;
        List<Vector2Int> freeTiles=PlayerDeploymentCoordinates()
            .Where(tile=>tile!=source.currentTile&&
                         !units.Any(other=>other!=source&&
                             IsCombatActive(other)&&!other.inStorage&&
                             other.currentTile==tile)&&
                         CanOccupySpawn(tile,Vector2Int.one))
            .OrderBy(tile=>Vector3.SqrMagnitude(
                GridWorld(tile)-GridWorld(source.currentTile)))
            .ThenBy(tile=>tile.y).ThenBy(tile=>tile.x).ToList();
        if(freeTiles.Count==0)return;
        Vector2Int spawn=freeTiles[0];
        AugmentMasterRow master=GameMasterData.Augment(
            ExpeditionAugmentRuntime.ShadowClone);
        float coreRatio=master==null?0.50f:
            master.NumericParam("health_attack_def_res_ratio",0.50f);
        float speedRatio=master==null?1f:
            master.NumericParam("attack_speed_move_range_ratio",1f);
        float modelScale=master==null?0.85f:
            master.NumericParam("model_scale",0.85f);
        ExpeditionMonsterStateSave sourceState=ExpeditionItemSystem.MonsterState(
            expeditionRun,source.stableId);
        ExpeditionMonsterRank sourceRank=sourceState==null
            ?ExpeditionMonsterRank.Rank1:sourceState.rank;
        ExpeditionGrowthBonuses growth=ExpeditionGrowthSystem.Bonuses(
            sourceState,source.ownedInstance,sourceRank);
        OwnedMonsterSave cloneOwned=PlayerProfileStore.CreateMonster(
            source.definition,"shadow_clone_"+expeditionRun.wave+"_"+source.stableId,
            false);
        cloneOwned.personalityId=source.ownedInstance.personalityId;
        cloneOwned.isShiny=source.ownedInstance.isShiny;
        Unit clone=SpawnUnit(source.definition,Team.Player,spawn,cloneOwned,false);
        clone.augmentShadowClone=true;
        clone.augmentCloneSourceId=source.stableId;
        clone.deploymentSlots=master==null?0:
            Mathf.RoundToInt(master.NumericParam("deployment_cost",0f));
        clone.skillId="";
        clone.activeTraitIds.Clear();
        clone.itemModifiers=new CombatItemModifiers();
        clone.damageTakenMultiplier=1f;
        clone.augmentBasicDamageMultiplier=1f;
        clone.augmentSkillPowerMultiplier=1f;
        clone.augmentSkillAreaMultiplier=1f;
        clone.maxHp=CombatStatFormula.BattleHealth(
            (source.definition.maxHp*Mathf.Max(
                 0.01f,source.ownedInstance.hpMultiplier)+growth.maxHealth)*coreRatio);
        clone.hp=clone.maxHp;
        clone.damage=(source.definition.attackDamage*Mathf.Max(
            0.01f,source.ownedInstance.damageMultiplier)+growth.attackDamage)*coreRatio;
        clone.defense=CombatStatFormula.BattleDefense(Mathf.Max(
            0f,(source.definition.defense*Mathf.Max(
                0.01f,source.ownedInstance.defenseMultiplier)+growth.defense)*coreRatio));
        clone.statusResistance=Mathf.Max(0f,
            (source.definition.statusResistance*Mathf.Max(
                 0.01f,source.ownedInstance.statusResistanceMultiplier)+
             growth.statusResistance)*coreRatio);
        float attackSpeedScore=100f/Mathf.Max(
            0.01f,source.definition.attackInterval)*Mathf.Max(
            0.01f,source.ownedInstance.attackSpeedMultiplier)+growth.attackSpeedScore;
        clone.attackInterval=CombatStatFormula.BattleAttackInterval(
            100f/Mathf.Max(0.01f,attackSpeedScore*speedRatio))*
            CombatAttackIntervalScale;
        clone.speedTilesPerSecond=source.definition.moveSpeedTilesPerSecond*Mathf.Max(
            0.01f,source.ownedInstance.moveSpeedMultiplier)*speedRatio*
            CombatMovementSpeedScale;
        clone.attackRange=Mathf.Max(1,Mathf.RoundToInt(
            source.definition.attackRange*speedRatio));
        ApplyRankVisualScale(
            clone,null,ExpeditionMonsterRank.Rank1,modelScale);

        Transform anchor=clone.spriteAnimation==null
            ?clone.model.transform:clone.spriteAnimation.transform;
        SpriteRenderer renderer=clone.spriteAnimation==null
            ?clone.model.GetComponentInChildren<SpriteRenderer>()
            :clone.spriteAnimation.GetComponent<SpriteRenderer>();
        if(renderer!=null)renderer.color=new Color(0.62f,0.36f,0.86f,0.76f);
        clone.reaction?.SetStatusTint(new Color(0.42f,0.16f,0.72f),0.72f);
        PixelCombatEffect.PlayNinjaVanishBurst(anchor,renderer);
        clone.bearSpiritParticles=PixelCombatEffect.PlayBearSpiritAura(anchor,renderer);
        if(clone.bearSpiritParticles==null)return;
        clone.bearSpiritParticles.name="Shadow Clone Pixel Aura";
        ParticleSystem.MainModule main=clone.bearSpiritParticles.main;
        main.startLifetime=new ParticleSystem.MinMaxCurve(0.7f,1.15f);
        main.startSize=new ParticleSystem.MinMaxCurve(0.05f,0.1f);
        main.startColor=new ParticleSystem.MinMaxGradient(
            new Color(0.34f,0.08f,0.58f,0.72f),
            new Color(0.72f,0.28f,1f,0.9f));
        ParticleSystem.EmissionModule emission=clone.bearSpiritParticles.emission;
        emission.rateOverTime=7f;
    }

    private void ApplyBattleStartAugments()
    {
        List<Unit> players=units.Where(unit=>IsCombatActive(unit)&&
            unit.team==Team.Player&&!unit.augmentShadowClone).ToList();
        ExpeditionAugmentSelectionSave blessing=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.FickleBlessing);
        if(blessing!=null)
        {
            Color color=FickleBlessingColor(ExpeditionAugmentRuntime.BlessingMode(
                blessing,expeditionRun.wave));
            foreach(Unit unit in players)PlayTraitBurst(unit,color,false);
        }
    }

    private bool IsTwinCommandTile(Vector2Int coordinate)
    {
        ExpeditionAugmentSelectionSave twin=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.TwinCommand);
        if(twin==null||twin.runtimeWave!=expeditionRun.wave||
           string.IsNullOrEmpty(twin.targetItemInstanceId))return false;
        return twin.targetItemInstanceId.Split('|').Any(token=>
            token==coordinate.x+","+coordinate.y);
    }

    private OwnedMonsterSave CommitPendingCapture()
    {
        if(!pendingCapture.IsReady)return null;
        OwnedMonsterSave captured=pendingCapture.capturedMonster;
        profileStore.AddGeneratedMonster(playerProfile,monsterDatabase,captured,false);
        pendingCapture.Clear();
        return captured;
    }

    private void DiscardPendingCapture(string message)
    {
        pendingCapture.Clear();
        if(!string.IsNullOrWhiteSpace(message))captureUiMessage=message;
    }

    private Unit UnitAt(Vector2Int coordinate)
    {
        occupancy.TryGetValue(coordinate,out Unit unit);return unit;
    }

    private Vector3 GridWorld(Vector2Int coordinate,bool placeOnBench=true)
    {
        return RawGridWorld(coordinate,placeOnBench)+mapOffset+
               DeploymentTileOffset(coordinate);
    }

    public static Vector3 CenteredGridWorld(Vector2Int coordinate)
    {
        if(UsesPointyHexTileArena)
            return RawGridWorld(coordinate)-IsoArenaCenter();
        Vector3 first=RawGridWorld(Vector2Int.zero);
        int centeredRows=UsesHexDeployment?HexDeploymentRows:ActiveRows;
        Vector3 last=RawGridWorld(new Vector2Int(ActiveColumns-1,centeredRows-1));
        return RawGridWorld(coordinate)-(first+last)*0.5f+
               DeploymentTileOffset(coordinate);
    }

    private static Vector3 DeploymentTileOffset(Vector2Int coordinate)=>
        UsesHexDeployment
            ?Vector3.forward*(coordinate.y==BenchRow
                ?BenchTileOffsetZ:BattleTileOffsetZ)
            :Vector3.zero;

    public static Bounds CenteredArenaBounds()
    {
        if(UsesHexDeployment)
            return new Bounds(
                Vector3.zero,
                new Vector3(
                    (ActiveColumns-0.5f)*ActiveTileSize*
                    ActiveHexSpacingScale+ActiveTileSize,
                    0.2f,
                    (HexDeploymentRows-1)*
                    ActiveTileSize*HexRowSpacing*
                    ActiveHexSpacingScale+ActiveTileSize*HexRowSpacing));
        return new Bounds(
            Vector3.zero,
            new Vector3(
                ActiveColumns*ActiveTileSize,0.2f,
                ActiveRows*ActiveTileSize*(UsesHexDeployment?HexRowSpacing:1f)));
    }

    private static Vector3 RawGridWorld(
        Vector2Int coordinate,bool placeOnBench=true)
    {
        if(!UsesHexDeployment)
            return new Vector3(coordinate.x*TileSize,0f,coordinate.y*TileSize);
        if(UsesPointyHexTileArena)
        {
            if(placeOnBench&&coordinate.y==BenchRow)
            {
                float center=(BenchSlotCount-1)*0.5f;
                float tileWidth=ActiveTileSize*IsoTileVisualWidthFactor;
                float mapCenter=IsoArenaCenter().x;
                return new Vector3(
                    mapCenter+(coordinate.x-center)*tileWidth,
                    0f,-ActiveTileSize*1.5f);
            }
            float halfWidth=ActiveTileSize*IsoTileVisualWidthFactor*0.5f;
            float halfDepth=ActiveTileSize*IsoTileDiagonalDepthFactor;
            return new Vector3(
                (coordinate.x-coordinate.y)*halfWidth,
                0f,(coordinate.x+coordinate.y)*halfDepth);
        }
        Vector3 world=new Vector3(
            (coordinate.x+((coordinate.y&1)==0?0f:0.5f))*ActiveTileSize*
            ActiveHexSpacingScale,
            0f,coordinate.y*ActiveTileSize*HexRowSpacing*
            ActiveHexSpacingScale);
        if(placeOnBench&&coordinate.y==BenchRow)
        {
            world.x+=ActiveTileSize*ActiveHexSpacingScale*0.25f;
            world.z-=ActiveTileSize;
        }
        return world;
    }

    private static Vector3 IsoArenaCenter()
    {
        float halfWidth=ActiveTileSize*IsoTileVisualWidthFactor*0.5f;
        float halfDepth=ActiveTileSize*IsoTileDiagonalDepthFactor;
        return new Vector3(
            (IsoTestColumns-IsoTestRows)*halfWidth*0.5f,
            0f,(IsoTestColumns+IsoTestRows-2)*halfDepth*0.5f);
    }

    public static int HexDistance(Vector2Int first,Vector2Int second)
    {
        Vector2Int a=OddRowToAxial(first);
        Vector2Int b=OddRowToAxial(second);
        int dq=a.x-b.x,dr=a.y-b.y;
        return (Mathf.Abs(dq)+Mathf.Abs(dr)+Mathf.Abs(dq+dr))/2;
    }

    private static Vector3 DeploymentFacing(Team team)=>
        team==Team.Player?Vector3.right:Vector3.left;

    private static Vector2Int OddRowToAxial(Vector2Int coordinate)
    {
        return new Vector2Int(
            coordinate.x-(coordinate.y-(coordinate.y&1))/2,
            coordinate.y);
    }

    private void SetTileColor(Tile tile,Color color)
    {
        tile.renderer.GetPropertyBlock(tileBlock);
        tileBlock.SetColor(BaseColor,color);tileBlock.SetColor(ColorProperty,color);
        tile.renderer.SetPropertyBlock(tileBlock);
    }

    private static Vector3 Flat(Vector3 value){value.y=0f;return value;}

    private static float NormalizeModel(GameObject model,float targetHeight,float tileFill)
    {
        Bounds bounds;
        if(!TryCalculateModelLocalBounds(model,out bounds))return 0f;
        float scale=targetHeight/Mathf.Max(0.001f,bounds.size.y);
        float maximumGroundSpan=TileSize*tileFill;
        float currentGroundSpan=Mathf.Max(bounds.size.x,bounds.size.z);
        if(currentGroundSpan*scale>maximumGroundSpan)
            scale=maximumGroundSpan/Mathf.Max(0.001f,currentGroundSpan);
        model.transform.localScale*=scale;
        return -bounds.min.y*Mathf.Abs(model.transform.localScale.y)+0.03f;
    }

    private static bool TryCalculateModelLocalBounds(GameObject model,out Bounds bounds)
    {
        bounds=new Bounds();
        bool found=false;
        Matrix4x4 worldToModel=model.transform.worldToLocalMatrix;
        Renderer[] renderers=model.GetComponentsInChildren<Renderer>(true);
        for(int i=0;i<renderers.Length;i++)
        {
            Bounds localBounds;
            MeshFilter meshFilter=renderers[i].GetComponent<MeshFilter>();
            SkinnedMeshRenderer skinned=renderers[i] as SkinnedMeshRenderer;
            if(meshFilter!=null&&meshFilter.sharedMesh!=null)localBounds=meshFilter.sharedMesh.bounds;
            else if(skinned!=null)localBounds=skinned.localBounds;
            else if(renderers[i] is SpriteRenderer spriteRenderer&&
                    spriteRenderer.sprite!=null)
                localBounds=spriteRenderer.sprite.bounds;
            else continue;
            Matrix4x4 toModel=worldToModel*renderers[i].transform.localToWorldMatrix;
            Vector3 center=localBounds.center;
            Vector3 extents=localBounds.extents;
            for(int x=-1;x<=1;x+=2)
            for(int y=-1;y<=1;y+=2)
            for(int z=-1;z<=1;z+=2)
            {
                Vector3 point=toModel.MultiplyPoint3x4(
                    center+Vector3.Scale(extents,new Vector3(x,y,z)));
                if(found)bounds.Encapsulate(point);
                else {bounds=new Bounds(point,Vector3.zero);found=true;}
            }
        }
        return found;
    }

    private static void GroundEvaluatedModel(GameObject model,Vector3 ground,ref float groundOffset)
    {
        Renderer[] renderers=model.GetComponentsInChildren<Renderer>(true);
        if(renderers.Length==0)return;
        Bounds bounds=renderers[0].bounds;
        for(int i=1;i<renderers.Length;i++)bounds.Encapsulate(renderers[i].bounds);
        float correction=ground.y+0.03f-bounds.min.y;
        groundOffset+=correction;
        model.transform.position+=Vector3.up*correction;
    }

