        {
            DrawItemTooltip();
            DrawSpecialItemTooltip();
            DrawAugmentTooltip();
            DrawMonsterAbilityTooltip();
        }
        if(waveIntroActive)DrawBattleStartCue();
        DrawDeploymentExpansionFeedback();
        DrawFirstExpeditionBattleTutorialGuide();
    }

    private void DrawPreparationPanel()
    {
