            "탐험 준비",BombBrickUiTheme.TitleStyle(20));
        BombBrickUiTheme.Badge(
            new Rect(top.x+180f,top.y+23f,76f,34f),
            "W "+expeditionRun.wave,BombBrickUiTheme.Cyan);

        float metricX=top.x+268f;
        DrawCompactRunMetric(new Rect(metricX,top.y+10f,140f,60f),
            "life","목숨",expeditionRun.lives+" / "+
            Mathf.Max(StartingExpeditionLives,expeditionRun.maximumLives),
            BombBrickUiTheme.Red);
        DrawCompactRunMetric(new Rect(metricX+148f,top.y+10f,156f,60f),
            "deployment","배치",CurrentDeploymentCount+" / "+MaxDeploymentCount,
            BombBrickUiTheme.Lime);
        DrawCompactRunMetric(PreparationGoldMetricRect,
            "gold",GameLocalization.Format(
                "battle.gold_interest","골드 · 이자 +{0}",
                ExpeditionDropSystem.InterestIncome(
                    expeditionRun.expeditionCurrency)),
            expeditionRun.expeditionCurrency.ToString(),
            BombBrickUiTheme.Orange);

        bool canStart=!battleStarted&&!waveIntroActive&&!waveArrivalActive&&
            !battleEnding&&!expeditionFailed&&resultText.Length==0&&
            CurrentDeploymentCount>0&&
            !shopVisible&&!GrowthShopVisible&&!AugmentDraftVisible&&
            !CompletedItemChoiceVisible&&!ReserveReinforcementChoiceVisible&&
            (!FirstExpeditionBattleTutorialActive||FirstBattleStartGuideVisible);
        Rect startButton=BattleStartButtonRect;
        bool canOpenShop=!battleStarted&&!waveIntroActive&&!waveArrivalActive&&
            !battleEnding&&!expeditionFailed&&resultText.Length==0&&
            !shopVisible&&!GrowthShopVisible&&!AugmentDraftVisible&&
            !CompletedItemChoiceVisible&&!ReserveReinforcementChoiceVisible&&
            ExpeditionShopSystem.IsShopWave(expeditionRun.wave)&&
            expeditionRun.shopWave==expeditionRun.wave;
        canOpenShop&=!FirstExpeditionBattleTutorialActive;
        if(canOpenShop)
        {
            Rect shopButton=ItemShopButtonRect;
            if(BombBrickUiTheme.Button(shopButton,"",true,false))
                OpenShop(true);
            DrawSystemIcon(new Rect(
                    shopButton.center.x-16f,shopButton.center.y-16f,32f,32f),
                "shop",BombBrickUiTheme.Orange,false);
        }
        if(BombBrickUiTheme.Button(
            startButton,"전투 시작",canStart,true,20))
            StartCurrentBattle();

        DrawNextEncounterPanel();
    }

