    private void DrawCombatHud()
    {
        Rect top=UiLayout.topBar;
        Rect status=new Rect(top.x,top.y,
            Mathf.Min(816f,top.width),top.height);
        BombBrickUiTheme.DrawPanel(status,true);
        BombBrickUiTheme.Fill(
            new Rect(status.x,status.y,4f,status.height),BombBrickUiTheme.Orange);
        GUI.Label(new Rect(top.x+16f,top.y+22f,148f,36f),
            paused?"일시 정지":"전투 진행",
            BombBrickUiTheme.TitleStyle(20));
        BombBrickUiTheme.Badge(
            new Rect(top.x+180f,top.y+23f,76f,34f),
            "W "+expeditionRun.wave,BombBrickUiTheme.Orange);

        int allies=units.Count(unit=>IsCombatActive(unit)&&
            unit.team==Team.Player&&!unit.inStorage);
        int enemies=units.Count(unit=>IsCombatActive(unit)&&
            unit.team==Team.Enemy);
        float metricX=top.x+268f;
        DrawCompactRunMetric(new Rect(metricX,top.y+10f,140f,60f),
            "deployment","아군",allies.ToString(),
            BombBrickUiTheme.Cyan);
        DrawCompactRunMetric(new Rect(metricX+148f,top.y+10f,156f,60f),
            "augment","적군",enemies.ToString(),
            BombBrickUiTheme.Red);
        DrawCompactRunMetric(new Rect(metricX+312f,top.y+10f,220f,60f),
            "time","시간",GameLocalization.Format(
                "battle.seconds","{0}초",battleElapsed.ToString("0.0")),
            BombBrickUiTheme.Orange);
    }

    private void DrawCompactRunMetric(
        Rect rect,string iconId,string label,string value,Color accent)
    {
        float started=iconId=="life"?lifeExpansionFeedbackStartedAt:
            iconId=="deployment"?deploymentExpansionFeedbackStartedAt:-1f;
        float duration=iconId=="deployment"?DeploymentExpansionFeedbackDuration:LifeExpansionFeedbackDuration;
        float elapsed=Time.unscaledTime-started;
        float progress=started>=0f&&elapsed>=0f&&elapsed<duration
            ?Mathf.Clamp01(elapsed/duration):-1f;
        float expansion=progress<0f||CombatFlashPresentation.Reduced?0f:Mathf.Sin(progress*Mathf.PI)*6f;
        float flash=progress<0f?0f:(1f-progress)*
            (0.72f+0.28f*Mathf.Abs(Mathf.Sin(progress*Mathf.PI*6f)))*CombatFlashPresentation.AccentScale;
        rect=new Rect(rect.x-expansion,rect.y-expansion,
            rect.width+expansion*2f,rect.height+expansion*2f);
        BombBrickUiTheme.Fill(rect,Color.Lerp(BombBrickUiTheme.Surface,
            iconId=="deployment"?new Color(.12f,.24f,.06f,1f):new Color(0.42f,0.06f,0.08f,1f),flash));
        BombBrickUiTheme.Frame(rect,Color.Lerp(
            BombBrickUiTheme.Border,accent,flash),1f+flash*2f);
        Rect iconRect=new Rect(rect.x+10f,rect.center.y-12f,24f,24f);
        if(iconId=="time")
        {
            BombBrickUiTheme.Frame(iconRect,accent,1f);
            BombBrickUiTheme.Fill(new Rect(
                iconRect.center.x,iconRect.y+4f,1f,6f),accent);
            BombBrickUiTheme.Fill(new Rect(
                iconRect.center.x,iconRect.center.y,5f,1f),accent);
        }
        else DrawSystemIcon(iconRect,iconId,accent,false);
        GUI.Label(new Rect(rect.x+44f,rect.y+6f,rect.width-56f,20f),
            label,BombBrickUiTheme.CaptionStyle(12));
        GUI.Label(new Rect(rect.x+44f,rect.y+29f,rect.width-56f,25f),
            value,BombBrickUiTheme.TitleStyle(18));
    }

    private void DrawNextEncounterPanel()
    {
        Rect panel=UiLayout.runHud;
        BombBrickUiTheme.DrawPanel(panel,true);
        BombBrickUiTheme.Fill(new Rect(panel.x,panel.y,4f,panel.height),
            BombBrickUiTheme.Red);
        GUI.Label(new Rect(panel.x+14f,panel.y+8f,126f,24f),
            "다음 교전",BombBrickUiTheme.TitleStyle(16));

        WaveScalingMasterRow scaling=CurrentWaveScaling();
        BombBrickUiTheme.Badge(
            new Rect(panel.xMax-104f,panel.y+7f,92f,24f),
            GameLocalization.Text(scaling.threatLabel),BombBrickUiTheme.Red);
        float difficultyHealth=ExpeditionDifficultyRules.HealthMultiplier(
            expeditionRun.difficulty);

        float statWidth=(panel.width-30f)/2f;
        DrawEncounterStat(new Rect(panel.x+12f,panel.y+39f,statWidth,38f),
            "적",scaling.enemyCount.ToString(),"개체",BombBrickUiTheme.Red);
        DrawEncounterStat(new Rect(panel.x+18f+statWidth,panel.y+39f,statWidth,38f),
            "체력","×"+(scaling.hpMultiplier*difficultyHealth).ToString("0.00"),"",
            BombBrickUiTheme.Cyan);

        BombBrickUiTheme.Fill(new Rect(panel.x+12f,panel.y+85f,3f,14f),
            BombBrickUiTheme.Violet);
        GUI.Label(new Rect(panel.x+20f,panel.y+82f,panel.width-32f,20f),
            RegionRuleHudLabel(),BombBrickUiTheme.CaptionStyle(9));
        GUI.Label(new Rect(panel.x+12f,panel.y+101f,panel.width-24f,14f),
            HunterRegionCatalog.RegionAffinityDescription(expeditionRun.regionId),
            BombBrickUiTheme.CaptionStyle(9));

        int cost=ExpeditionDeploymentSystem.NextUpgradeCost(MaxDeploymentCount);
        bool automaticDeployment=ExpeditionAugmentRuntime.BlocksDeploymentPurchase(
            expeditionRun);
        bool expansionAvailable=
            MaxDeploymentCount<ExpeditionDeploymentSystem.MaximumLimit&&
            !automaticDeployment;
        bool canPurchase=expansionAvailable&&!battleStarted&&!battleEnding&&
            resultText.Length==0&&!shopVisible&&
            !GrowthShopVisible&&!AugmentDraftVisible&&
            !CompletedItemChoiceVisible&&!ReserveReinforcementChoiceVisible&&
            expeditionRun.expeditionCurrency>=cost;
        string expansionLabel=automaticDeployment?"자동 전개 진행 중":expansionAvailable
            ?GameLocalization.Format("battle.deployment_upgrade",
                "배치 한도 +1   ·   골드 {0}",cost)
            :"최대 배치 확장 완료";
        if(BombBrickUiTheme.Button(
            new Rect(panel.x+12f,panel.yMax-38f,panel.width-24f,28f),
            expansionLabel,canPurchase,false))
            BuyDeploymentExpansion();
