    private string RegionRuleHudLabel()
    {
        string difficulty=GameLocalization.Text(
            ExpeditionDifficultyRules.DisplayName(expeditionRun.difficulty))+" · ";
        switch(HunterRegionCatalog.Rule(expeditionRun.regionId))
        {
            case HunterRegionRule.PoisonFog:return difficulty+
                GameLocalization.TextByKey("battle.region_poison","환경 · 8초마다 독");
            case HunterRegionRule.CrimsonHeat:return difficulty+
                GameLocalization.TextByKey("battle.region_heat","환경 · 받는 피해 +15%");
            case HunterRegionRule.FrostWave:return difficulty+
                GameLocalization.TextByKey("battle.region_frost","환경 · 10초마다 냉기");
            case HunterRegionRule.SkyResonance:return difficulty+
                GameLocalization.TextByKey("battle.region_sky","환경 · 시작 스킬 +20%");
            default:return difficulty+
                GameLocalization.TextByKey("battle.region_none","환경 효과 없음");
        }
    }

