    private void DrawAugmentStatusHud()
    {
        if(expeditionRun==null||expeditionRun.augments==null||
           expeditionRun.augments.Count==0||AugmentDraftVisible)return;
        List<ExpeditionAugmentSelectionSave> selections=expeditionRun.augments
            .Where(value=>value!=null)
            .OrderBy(value=>value.acquiredWave).ToList();
        if(selections.Count==0)return;
        ExpeditionAugmentSelectionSave blessing=selections.FirstOrDefault(value=>
            value.augmentId==ExpeditionAugmentRuntime.FickleBlessing);
        int blessingMode=blessing==null?-1:
            ExpeditionAugmentRuntime.BlessingMode(blessing,expeditionRun.wave);
        float blessingHeight=blessing==null?0f:48f;
        Color panelAccent=blessing==null?BombBrickUiTheme.Violet:
            FickleBlessingColor(blessingMode);

        if(augmentHudLastCount!=selections.Count)
        {
            augmentHudLastCount=selections.Count;
            augmentHudAppearedAt=Time.realtimeSinceStartup;
        }
        Rect safe=UiLayout.safeArea;
        Rect encounter=UiLayout.runHud;
        int visibleRows=Mathf.Min(6,selections.Count);
        float height=(augmentHudExpanded?46f+visibleRows*36f:44f)+
            blessingHeight;
        float revealT=augmentHudAppearedAt<0f?1f:Mathf.Clamp01(
            (Time.realtimeSinceStartup-augmentHudAppearedAt)/0.52f);
        float reveal=BombBrickUiTheme.EaseOutBack(revealT,0.7f);
        float targetX=encounter.x;
        float targetY=encounter.yMax+BombBrickUiLayout.Gap;
        Rect panel=new Rect(
            Mathf.Lerp(safe.x-UiLayout.runHud.width-18f,targetX,reveal),
            targetY,
            UiLayout.runHud.width,height);
        BombBrickUiTheme.DrawPanel(panel,true);
        BombBrickUiTheme.Fill(new Rect(panel.x,panel.y,4f,panel.height),
            panelAccent);
        if(revealT<1f)
        {
            float pulse=1f-revealT;
            BombBrickUiTheme.Frame(panel,
                new Color(panelAccent.r,panelAccent.g,panelAccent.b,
                    0.35f+pulse*0.55f),
                1f+pulse*2f);
        }
        DrawSystemIcon(new Rect(panel.x+13f,panel.y+10f,24f,24f),
            "augment",panelAccent,false);
        GUI.Label(new Rect(panel.x+45f,panel.y+8f,154f,26f),
            GameLocalization.Format(
                "battle.owned_augments","보유 증강  {0}",selections.Count),
            BombBrickUiTheme.TitleStyle(14));
        if(BombBrickUiTheme.Button(
            new Rect(panel.xMax-42f,panel.y+8f,28f,26f),
            augmentHudExpanded?"−":"+",true,false))
            augmentHudExpanded=!augmentHudExpanded;

        if(!augmentHudExpanded)
        {
            float x=panel.x+200f;
            int iconCount=Mathf.Min(3,selections.Count);
            for(int i=0;i<iconCount;i++)
            {
                AugmentMasterRow master=GameMasterData.Augment(
                    selections[i].augmentId);
                if(master==null)continue;
                Rect icon=new Rect(x+i*31f,panel.y+10f,24f,24f);
                DrawAugmentIcon(icon,master,
                    AugmentCategoryColor(master.category),false);
                if(icon.Contains(Event.current.mousePosition))
                    hoveredAugmentTooltip=master;
            }
            if(blessing!=null)DrawFickleBlessingCycle(
                new Rect(panel.x+10f,panel.yMax-42f,panel.width-20f,36f),
                blessing);
            return;
        }

        BombBrickUiTheme.Fill(new Rect(panel.x+12f,panel.y+41f,
            panel.width-24f,1f),BombBrickUiTheme.Border);
        for(int i=0;i<visibleRows;i++)
        {
            ExpeditionAugmentSelectionSave selection=selections[i];
            AugmentMasterRow master=GameMasterData.Augment(selection.augmentId);
            if(master==null)continue;
            Rect row=new Rect(panel.x+10f,panel.y+45f+i*36f,
                panel.width-20f,30f);
            bool hovered=row.Contains(Event.current.mousePosition);
            if(hovered)BombBrickUiTheme.Fill(row,BombBrickUiTheme.SurfaceHover);
            DrawAugmentIcon(new Rect(row.x+4f,row.y+3f,24f,24f),
                master,AugmentCategoryColor(master.category),hovered);
            Unit target=string.IsNullOrEmpty(selection.targetMonsterInstanceId)
                ?null:units.FirstOrDefault(value=>value!=null&&
                    value.stableId==selection.targetMonsterInstanceId&&
                    !value.augmentShadowClone);
            string label=GameLocalization.Text(master.displayName);
            if(target!=null)label+=" · "+GameLocalization.Text(target.displayName);
            GUI.Label(new Rect(row.x+36f,row.y+2f,row.width-96f,25f),
                label,
                BombBrickUiTheme.BodyStyle(12,TextAnchor.MiddleLeft));
            BombBrickUiTheme.Badge(
                new Rect(row.xMax-52f,row.y+4f,46f,21f),
                "W"+selection.acquiredWave,
                AugmentCategoryColor(master.category));
            if(hovered)hoveredAugmentTooltip=master;
        }
        if(selections.Count>visibleRows)
            GUI.Label(new Rect(panel.x+12f,panel.yMax-18f,panel.width-24f,14f),
                GameLocalization.Format("augment.ui.more","외 {0}개",selections.Count-visibleRows),
                BombBrickUiTheme.CaptionStyle(9,TextAnchor.MiddleRight));
        if(blessing!=null)DrawFickleBlessingCycle(
            new Rect(panel.x+10f,panel.yMax-42f,panel.width-20f,36f),blessing);
    }

    private void DrawFickleBlessingCycle(
        Rect rect,ExpeditionAugmentSelectionSave blessing)
    {
        int current=ExpeditionAugmentRuntime.BlessingMode(
            blessing,expeditionRun.wave);
        int next=ExpeditionAugmentRuntime.BlessingMode(
            blessing,expeditionRun.wave+1);
        Color currentColor=FickleBlessingColor(current);
        Rect currentRect=new Rect(rect.x,rect.y,rect.width*0.64f,rect.height);
        Rect nextRect=new Rect(currentRect.xMax+4f,rect.y,
            rect.xMax-currentRect.xMax-4f,rect.height);
        BombBrickUiTheme.Fill(currentRect,new Color(
            currentColor.r*0.20f,currentColor.g*0.20f,
            currentColor.b*0.20f,0.98f));
        BombBrickUiTheme.Frame(currentRect,currentColor,2f);
        GUI.Label(new Rect(currentRect.x+9f,currentRect.y+2f,
            currentRect.width-18f,17f),GameLocalization.Format(
                "augment.fickle.current","현재 · {0}",GameLocalization.Text(FickleBlessingName(current))),
            BombBrickUiTheme.TitleStyle(11));
        GUI.Label(new Rect(currentRect.x+9f,currentRect.y+18f,
            currentRect.width-18f,14f),FickleBlessingEffect(current),
            BombBrickUiTheme.CaptionStyle(8));
        Color nextColor=FickleBlessingColor(next);
        BombBrickUiTheme.Fill(nextRect,BombBrickUiTheme.SurfaceRaised);
