    private void DrawTwinCommandConnection()
    {
        if(mainCamera==null||expeditionRun==null||
           !TryGetTwinCommandUnits(out Unit first,out Unit second))return;
        if(!TryGetUnitGuiRect(first,out Rect firstBounds)||
           !TryGetUnitGuiRect(second,out Rect secondBounds))return;
        Vector2 a=firstBounds.center;
        Vector2 b=secondBounds.center;
        float distance=Vector2.Distance(a,b);
        if(distance<12f)return;

        float time=Time.unscaledTime;
        float arcHeight=Mathf.Clamp(distance*0.08f,10f,28f);
        int tick=Mathf.FloorToInt(time*10f);
        for(int i=0;i<8;i++)
        {
            float travel=Mathf.Repeat(i/8f+tick*0.025f,1f);
            if((i&1)!=0)travel=1f-travel;
            Vector2 point=TwinLinkPoint(a,b,arcHeight,travel);
            Vector2 tangent=TwinLinkTangent(a,b,arcHeight,travel).normalized;
            Vector2 normal=new Vector2(-tangent.y,tangent.x);
            point+=normal*(((i*13+tick)%3)-1)*2f;
            DrawTwinPixel(point,4f,(i&1)==0
                ?new Color(1f,0.72f,0.18f,0.78f)
                :new Color(0.42f,0.9f,1f,0.72f));
        }

        float age=time-twinCommandPulseStartedAt;
        bool forward=twinCommandPulseSourceId==first.stableId&&
                     twinCommandPulseTargetId==second.stableId;
        bool backward=twinCommandPulseSourceId==second.stableId&&
                      twinCommandPulseTargetId==first.stableId;
        if(age<0f||age>0.55f||(!forward&&!backward))return;
        Vector2 source=forward?a:b;
        Vector2 target=forward?b:a;
        float travelProgress=Mathf.Clamp01(age/0.34f);
        for(int i=0;i<7;i++)
        {
            float travel=Mathf.Clamp01(travelProgress-i*0.045f);
            if(travel<=0f)continue;
            DrawTwinPixel(TwinLinkPoint(source,target,arcHeight,travel),
                i<2?6f:4f,i%3==0?Color.white:
                    new Color(1f,0.66f,0.12f,1f));
        }
        if(age<0.28f)return;
        float burst=Mathf.Clamp01((age-0.28f)/0.27f)*18f;
        for(int i=0;i<8;i++)
        {
            float angle=i*Mathf.PI*0.25f;
            Vector2 offset=new Vector2(Mathf.Cos(angle),Mathf.Sin(angle))*burst;
            DrawTwinPixel(target+offset,5f,
                i%2==0?new Color(1f,0.78f,0.22f,1f):
                    new Color(0.48f,0.92f,1f,1f));
        }
    }

    private void DrawCombinedCastPulse()
    {
        float age=Time.unscaledTime-combinedCastPulseStartedAt;
        if(age<0f||age>0.7f||combinedCastPulseContributorIds.Count==0)return;
        Unit commander=units.FirstOrDefault(unit=>IsCombatActive(unit)&&
            unit.stableId==combinedCastPulseCommanderId);
        if(commander==null||!TryGetUnitGuiRect(commander,out Rect commanderBounds))return;
        Vector2 destination=commanderBounds.center;
        float gather=Mathf.Clamp01(age/0.34f);
        for(int i=0;i<combinedCastPulseContributorIds.Count;i++)
        {
            Unit contributor=units.FirstOrDefault(unit=>IsCombatActive(unit)&&
                unit.stableId==combinedCastPulseContributorIds[i]);
            if(contributor==null||!TryGetUnitGuiRect(contributor,out Rect bounds))continue;
            Vector2 origin=bounds.center;
            Vector2 normal=new Vector2(-(destination-origin).y,(destination-origin).x).normalized;
            for(int pixel=0;pixel<5;pixel++)
            {
                float travel=Mathf.Clamp01(gather-pixel*0.055f);
                if(travel<=0f)continue;
                Vector2 point=Vector2.Lerp(origin,destination,travel)+
                    normal*Mathf.Sin((travel+pixel*0.21f)*Mathf.PI)*((pixel%3)-1)*5f;
                DrawTwinPixel(point,pixel==0?6f:4f,pixel%2==0
                    ?new Color(0.72f,0.48f,1f,1f)
                    :new Color(0.48f,0.92f,1f,0.95f));
            }
        }
        if(age<0.26f)return;
        float burst=Mathf.Clamp01((age-0.26f)/0.34f)*28f;
        for(int i=0;i<12;i++)
        {
            float angle=i*Mathf.PI/6f;
            Vector2 offset=new Vector2(Mathf.Cos(angle),Mathf.Sin(angle))*burst;
            DrawTwinPixel(destination+offset,i%3==0?6f:4f,i%2==0
                ?new Color(0.82f,0.58f,1f,1f)
                :new Color(0.48f,0.92f,1f,0.9f));
        }
    }

    private static void DrawTwinPixel(Vector2 center,float size,Color color)
    {
        center=new Vector2(Mathf.Round(center.x),Mathf.Round(center.y));
        BombBrickUiTheme.Fill(new Rect(
            center.x-size*0.5f,center.y-size*0.5f,size,size),color);
    }

    private static Vector2 TwinLinkPoint(
        Vector2 start,Vector2 end,float arcHeight,float t)
    {
        Vector2 control=(start+end)*0.5f+Vector2.up*-arcHeight;
        float inverse=1f-t;
        return inverse*inverse*start+2f*inverse*t*control+t*t*end;
    }

    private static Vector2 TwinLinkTangent(
        Vector2 start,Vector2 end,float arcHeight,float t)
    {
        Vector2 control=(start+end)*0.5f+Vector2.up*-arcHeight;
        return 2f*(1f-t)*(control-start)+2f*t*(end-control);
    }

    private static void DrawGuiGlowNode(Vector2 center,float radius,Color color)
    {
        BombBrickUiTheme.Fill(
            new Rect(center.x-radius*2f,center.y-radius*2f,radius*4f,radius*4f),
            new Color(color.r,color.g,color.b,color.a*0.08f));
        BombBrickUiTheme.Fill(
            new Rect(center.x-radius,center.y-radius,radius*2f,radius*2f),
            new Color(color.r,color.g,color.b,color.a*0.24f));
        DrawGuiDiamond(center,radius*0.72f,color);
