    private static void DrawGuiDiamond(Vector2 center,float radius,Color color)
    {
        Matrix4x4 previousMatrix=GUI.matrix;
        Color previousColor=GUI.color;
        GUIUtility.RotateAroundPivot(45f,center);
        GUI.color=color;
        GUI.DrawTexture(
            new Rect(center.x-radius,center.y-radius,radius*2f,radius*2f),
            Texture2D.whiteTexture);
        GUI.color=previousColor;
        GUI.matrix=previousMatrix;
    }

    private static void DrawGuiRing(
        Vector2 center,float radius,Color color,float width,int segments)
    {
        Vector2 previous=center+Vector2.right*radius;
        for(int i=1;i<=segments;i++)
        {
            float angle=i/(float)segments*Mathf.PI*2f;
            Vector2 point=center+
                new Vector2(Mathf.Cos(angle),Mathf.Sin(angle))*radius;
            DrawGuiLine(previous,point,color,width);
            previous=point;
        }
    }

    private bool TryGetTwinCommandUnits(out Unit first,out Unit second)
    {
        first=null;
        second=null;
        ExpeditionAugmentSelectionSave twin=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.TwinCommand);
        if(twin==null||twin.runtimeWave!=expeditionRun.wave)return false;

        List<Unit> linked=new List<Unit>();
        if(battleStarted&&!string.IsNullOrEmpty(twin.runtimeState))
        {
            string[] ids=twin.runtimeState.Split('|');
            for(int i=0;i<ids.Length;i++)
            {
                Unit unit=units.FirstOrDefault(value=>
                    IsCombatActive(value)&&value.team==Team.Player&&
                    value.stableId==ids[i]);
                if(unit!=null&&!linked.Contains(unit))linked.Add(unit);
            }
        }
        else if(!string.IsNullOrEmpty(twin.targetItemInstanceId))
        {
            foreach(string token in twin.targetItemInstanceId.Split('|'))
            {
                string[] values=token.Split(',');
                if(values.Length!=2||!int.TryParse(values[0],out int x)||
                   !int.TryParse(values[1],out int y))continue;
                Unit unit=UnitAt(new Vector2Int(x,y));
                if(unit!=null&&unit.team==Team.Player&&!unit.inStorage&&
                   !linked.Contains(unit))linked.Add(unit);
            }
        }
        if(linked.Count<2)return false;
        first=linked[0];
        second=linked[1];
        return first.model!=null&&second.model!=null;
    }

    private static void DrawGuiLine(
        Vector2 start,Vector2 end,Color color,float width)
    {
        Vector2 delta=end-start;
        float length=delta.magnitude;
        if(length<=0.01f)return;
        Matrix4x4 previousMatrix=GUI.matrix;
        Color previousColor=GUI.color;
        GUIUtility.RotateAroundPivot(
            Mathf.Atan2(delta.y,delta.x)*Mathf.Rad2Deg,start);
        GUI.color=color;
        GUI.DrawTexture(
            new Rect(start.x,start.y-width*0.5f,length,width),
            Texture2D.whiteTexture);
        GUI.color=previousColor;
        GUI.matrix=previousMatrix;
    }

