    private void DrawSystemIcon(
        Rect rect,string iconId,Color accent,bool framed=true)
    {
        if(framed)
        {
            BombBrickUiTheme.Fill(rect,BombBrickUiTheme.Surface);
            BombBrickUiTheme.Frame(rect,accent,1f);
        }
        if(!systemIconCache.TryGetValue(iconId,out Texture2D texture))
        {
            texture=GameResourceCache.GetTexture("UI/SystemIcons/"+iconId);
            systemIconCache[iconId]=texture;
        }
        if(texture!=null)
            GUI.DrawTexture(new Rect(rect.x+2f,rect.y+2f,rect.width-4f,rect.height-4f),
                texture,ScaleMode.ScaleToFit,false);
