    private void DrawAugmentIcon(
        Rect rect,AugmentMasterRow master,Color accent,bool emphasized)
    {
        if(master==null)return;
        BombBrickUiTheme.Fill(rect,BombBrickUiTheme.Surface);
        BombBrickUiTheme.Frame(rect,
            emphasized?Color.Lerp(accent,Color.white,0.22f):accent,
            emphasized?2f:1f);
        if(!augmentIconCache.TryGetValue(master.id,out Texture2D texture))
        {
            texture=GameResourceCache.GetTexture("UI/AugmentIcons/"+master.id);
            augmentIconCache[master.id]=texture;
        }
        Rect imageRect=new Rect(
            rect.x+3f,rect.y+3f,rect.width-6f,rect.height-6f);
        if(texture!=null)
            GUI.DrawTexture(imageRect,texture,ScaleMode.ScaleToFit,false);
        else
        {
            BombBrickUiTheme.Fill(imageRect,
                new Color(accent.r*0.16f,accent.g*0.16f,accent.b*0.16f,1f));
            DrawGuiDiamond(imageRect.center,
                Mathf.Min(imageRect.width,imageRect.height)*0.18f,accent);
        }
    }

