    private static void DrawIntroductionCue(
        float progress,string kicker,string title,string subtitle,
        Color accent,bool revealMap)
    {
        float fadeIn=Mathf.SmoothStep(
            0f,1f,Mathf.Clamp01(progress/0.22f));
        float fadeOut=1f-Mathf.SmoothStep(
            0f,1f,Mathf.Clamp01((progress-0.74f)/0.26f));
        float alpha=fadeIn*fadeOut;
        float shade=revealMap
            ?Mathf.Lerp(0.68f,0.08f,
                BombBrickUiTheme.EaseOutCubic(progress))
            :0.58f*alpha;
        BombBrickUiTheme.Fill(new Rect(0f,0f,BombBrickUiLayout.Width,BombBrickUiLayout.Height),
            new Color(0.008f,0.012f,0.022f,shade));

        float width=Mathf.Min(520f,BombBrickUiLayout.Width-48f);
        float y=BombBrickUiLayout.Height*0.42f;
        float scale=Mathf.Lerp(0.9f,1f,
            BombBrickUiTheme.EaseOutBack(
                Mathf.Clamp01(progress/0.42f),0.55f));
        Matrix4x4 previousMatrix=GUI.matrix;
        GUIUtility.ScaleAroundPivot(new Vector2(scale,scale),
            new Vector2(BombBrickUiLayout.Width*0.5f,y+56f));
        Color previous=GUI.color;
        GUI.color=new Color(1f,1f,1f,alpha);
        GUI.Label(new Rect((BombBrickUiLayout.Width-width)*0.5f,y-20f,width,20f),
            kicker,BombBrickUiTheme.CaptionStyle(
                11,TextAnchor.MiddleCenter));
        GUI.Label(new Rect((BombBrickUiLayout.Width-width)*0.5f,y+8f,width,52f),
            title,BombBrickUiTheme.DisplayStyle(38));
        GUI.Label(new Rect((BombBrickUiLayout.Width-width)*0.5f,y+66f,width,22f),
            subtitle,BombBrickUiTheme.CaptionStyle(
                12,TextAnchor.MiddleCenter));
        GUI.color=previous;
        Color lineColor=new Color(accent.r,accent.g,accent.b,alpha);
        BombBrickUiTheme.Fill(
            new Rect((BombBrickUiLayout.Width-width)*0.5f,y+1f,width,2f),lineColor);
        BombBrickUiTheme.Fill(
            new Rect((BombBrickUiLayout.Width-width)*0.5f,y+94f,width,2f),lineColor);
        GUI.matrix=previousMatrix;
    }

