    private static float BattleStartCueScale(float elapsed)
    {
        // Follow the three drum strikes in BattleEngage.wav.
        float opening=.28f*Mathf.Pow(1f-Mathf.Clamp01(elapsed/.075f),2f);
        float second=elapsed<.137f?0f:.06f*Mathf.Pow(1f-Mathf.Clamp01((elapsed-.137f)/.075f),2f);
        float final=elapsed<.312f?0f:.13f*Mathf.Pow(1f-Mathf.Clamp01((elapsed-.312f)/.09f),2f);
        return 1f+(opening+second+final)*CombatFlashPresentation.AccentScale;
    }

    private void DrawBattleStartCue()
    {
        float elapsed=Mathf.Max(0f,waveIntroElapsed);
        float fadeOut=Mathf.SmoothStep(0f,1f,Mathf.InverseLerp(.42f,BattleStartCueDuration,elapsed));
        float alpha=Mathf.Clamp01(elapsed/.025f)*(1f-fadeOut);
        BombBrickUiTheme.Fill(new Rect(0f,0f,BombBrickUiLayout.Width,BombBrickUiLayout.Height),
            new Color(.008f,.012f,.022f,.28f*alpha));

        float width=Mathf.Min(500f,BombBrickUiLayout.Width-64f);
        float enter=1f-Mathf.Pow(1f-Mathf.Clamp01(elapsed/.075f),3f);
        Vector2 center=new Vector2(BombBrickUiLayout.Width*.5f-36f*(1f-enter)+fadeOut*48f,
            BombBrickUiLayout.Height*.5f);
        float lineWidth=width*enter;
        Matrix4x4 previousMatrix=GUI.matrix;
        Color previous=GUI.color;
        float scale=BattleStartCueScale(elapsed);
        GUIUtility.ScaleAroundPivot(new Vector2(scale,scale),center);
        try
        {
            BombBrickUiTheme.Fill(new Rect(center.x-width*.5f-12f,center.y-40f,width+24f,80f),
                new Color(.008f,.01f,.014f,.82f*alpha));
            Color accent=BombBrickUiTheme.Orange;accent.a=alpha;
            BombBrickUiTheme.Fill(new Rect(center.x-lineWidth*.5f,center.y-42f,lineWidth,3f),accent);
            BombBrickUiTheme.Fill(new Rect(center.x-lineWidth*.5f,center.y+39f,lineWidth,3f),accent);
            Rect title=new Rect(center.x-width*.5f,center.y-34f,width,68f);
            GUI.color=new Color(.01f,.012f,.018f,alpha);
            GUI.Label(new Rect(title.x+3f,title.y+4f,title.width,title.height),"전투 시작",
                BombBrickUiTheme.DisplayStyle(46));
            GUI.color=new Color(1f,1f,1f,alpha);
            GUI.Label(title,"전투 시작",BombBrickUiTheme.DisplayStyle(46));
        }
        finally{GUI.color=previous;GUI.matrix=previousMatrix;}
    }

    private void DrawWaveOutcomeMessage()
    {
        bool won=pendingResult=="아군 승리";
        string message="WAVE "+expeditionRun.wave+(won?" 승리":" 패배");
        Color previous=GUI.color;
        GUI.color=new Color(0.01f,0.015f,0.025f,0.82f);
        GUI.DrawTexture(new Rect(0f,0f,BombBrickUiLayout.Width,BombBrickUiLayout.Height),Texture2D.whiteTexture);
        GUI.color=won?new Color(0.28f,0.9f,0.56f,1f):new Color(1f,0.32f,0.28f,1f);
