        {
            alignment=TextAnchor.MiddleCenter,
            fontSize=42,
            fontStyle=FontStyle.Bold
        };
        outcomeStyle.normal.textColor=Color.white;
        GUI.Box(
            new Rect(BombBrickUiLayout.Width*0.5f-260f,BombBrickUiLayout.Height*0.5f-64f,520f,128f),
            message,outcomeStyle);
        GUI.color=previous;
    }

    private void DrawWaveLootReview()
    {
        BombBrickUiTheme.DrawModalBackdrop();
        float elapsed=Mathf.Clamp(
            WaveLootReviewDuration-waveOutcomeTimer,0f,WaveLootReviewDuration);
        float progress=Mathf.Clamp01(elapsed/WaveLootReviewDuration);
        float reveal=BombBrickUiTheme.EaseOutBack(
            Mathf.Clamp01(elapsed/0.72f),0.72f);
        Rect safe=UiLayout.safeArea;
        float width=Mathf.Min(1080f,safe.width-48f);
        float height=Mathf.Min(500f,safe.height-48f);
        Rect panel=new Rect(
            safe.center.x-width*0.5f,
            safe.center.y-height*0.5f,
            width,height);
        float ceremonyPulse=0.5f+0.5f*
            Mathf.Sin(Time.unscaledTime*4.2f);
        DrawGuiRing(panel.center,90f+progress*270f,
            new Color(BombBrickUiTheme.Cyan.r,
                BombBrickUiTheme.Cyan.g,
                BombBrickUiTheme.Cyan.b,
                (1f-progress)*0.28f),2f,42);
        DrawGuiRing(panel.center,64f+ceremonyPulse*12f,
            new Color(BombBrickUiTheme.Lime.r,
                BombBrickUiTheme.Lime.g,
                BombBrickUiTheme.Lime.b,0.12f),1.5f,32);
        BombBrickUiTheme.DrawPanel(panel,true);
        BombBrickUiTheme.Fill(new Rect(panel.x,panel.y,panel.width,5f),
            BombBrickUiTheme.Lime);
        GUI.Label(new Rect(panel.x+24f,panel.y+28f,panel.width-48f,20f),
            "W "+expeditionRun.wave+" · 전리품",
            BombBrickUiTheme.CaptionStyle(12,TextAnchor.MiddleCenter));
        Matrix4x4 titleMatrix=GUI.matrix;
        float titleScale=Mathf.Lerp(0.84f,1f,reveal);
        GUIUtility.ScaleAroundPivot(
            new Vector2(titleScale,titleScale),
            new Vector2(panel.center.x,panel.y+88f));
        GUI.Label(new Rect(panel.x+24f,panel.y+51f,panel.width-48f,64f),
            "전리품 확보",BombBrickUiTheme.DisplayStyle(42));
        GUI.matrix=titleMatrix;
        float titleLineWidth=(panel.width-96f)*Mathf.Clamp01(progress/0.28f);
        BombBrickUiTheme.Fill(new Rect(
            panel.center.x-titleLineWidth*0.5f,panel.y+126f,
            titleLineWidth,2f),BombBrickUiTheme.Lime);

        List<KeyValuePair<string,int>> items=waveLootReviewItemIds
            .Where(id=>!string.IsNullOrWhiteSpace(id))
            .GroupBy(id=>id,StringComparer.Ordinal)
            .Select(group=>new KeyValuePair<string,int>(
                group.Key,group.Count())).Take(5).ToList();
        int rewardCount=items.Count+
            (waveLootReviewGold>0?1:0);
        int goldRewardIndex=items.Count;
        float goldTransfer=waveLootReviewGold>0
            ?WaveLootTransferProgress(elapsed,goldRewardIndex):0f;
        int displayedGold=waveLootReviewGoldStart+
            Mathf.RoundToInt(waveLootReviewGold*goldTransfer);
        float bagPulse=0f;
        for(int i=0;i<items.Count;i++)
        {
            float transfer=WaveLootTransferProgress(elapsed,i);
            bagPulse=Mathf.Max(bagPulse,
                Mathf.Sin(Mathf.Clamp01((transfer-0.72f)/0.28f)*Mathf.PI));
        }
        float goldPulse=Mathf.Sin(
            Mathf.Clamp01((goldTransfer-0.72f)/0.28f)*Mathf.PI);
        DrawLootSettlementDestinations(displayedGold,bagPulse,goldPulse);

        if(rewardCount==0)
        {
            DrawGuiCheck(new Vector2(panel.center.x,panel.y+235f),
                BombBrickUiTheme.TextSecondary,6f);
            GUI.Label(new Rect(panel.x+30f,panel.y+272f,panel.width-60f,30f),
                "이번 Wave에서 확보한 전리품이 없습니다.",
                BombBrickUiTheme.BodyStyle(17,TextAnchor.MiddleCenter));
        }
        else
        {
            const float gap=18f;
            float rewardWidth=Mathf.Clamp(
                (panel.width-96f-gap*(rewardCount-1))/
                Mathf.Max(1,rewardCount),92f,132f);
            float total=rewardCount*rewardWidth+
                Mathf.Max(0,rewardCount-1)*gap;
            float x=panel.center.x-total*0.5f;
            int rewardIndex=0;
            for(int i=0;i<items.Count;i++,rewardIndex++)
            {
                float delay=0.28f+rewardIndex*0.11f;
                float itemReveal=BombBrickUiTheme.EaseOutBack(
                    Mathf.Clamp01((elapsed-delay)/0.42f),0.82f);
                Rect reward=new Rect(
                    x+rewardIndex*(rewardWidth+gap),
                    panel.y+178f+(1f-itemReveal)*72f,
                    rewardWidth,rewardWidth);
                ItemMasterRow item=GameMasterData.Item(items[i].Key);
                Color accent=item==null?BombBrickUiTheme.Cyan:
                    (item.IsCompleted?BombBrickUiTheme.Orange:
                        BombBrickUiTheme.Cyan);
                float itemTransfer=WaveLootTransferProgress(elapsed,rewardIndex);
                Vector2 transferTarget=new Vector2(
                    ItemBarRect.x+29f+(i-(items.Count-1)*0.5f)*5f,
                    ItemBarRect.center.y);
                float arcHeight=Mathf.Clamp(
                    Vector2.Distance(reward.center,transferTarget)*0.22f,70f,180f);
                Vector2 movingCenter=TwinLinkPoint(
                    reward.center,transferTarget,arcHeight,itemTransfer);
                Rect movingReward=new Rect(
                    movingCenter.x-reward.width*0.5f,
                    movingCenter.y-reward.height*0.5f,
                    reward.width,reward.height);
                DrawLootRewardImpact(
                    reward,itemReveal*(1f-itemTransfer),accent);
                DrawLootTransferTrail(
                    reward.center,transferTarget,arcHeight,
                    itemTransfer,accent,rewardIndex);
                int itemCount=items[i].Value;
                DrawAtGuiScale(
                    itemReveal*WaveLootAbsorbScale(itemTransfer),
                    movingReward.center,()=>
                {
                    if(item!=null)DrawItemIcon(movingReward,item,itemCount);
                });
            }
            if(waveLootReviewGold>0)
            {
                float delay=0.28f+rewardIndex*0.11f;
                float itemReveal=BombBrickUiTheme.EaseOutBack(
                    Mathf.Clamp01((elapsed-delay)/0.42f),0.82f);
                Rect reward=new Rect(
                    x+rewardIndex*(rewardWidth+gap),
                    panel.y+178f+(1f-itemReveal)*72f,
                    rewardWidth,rewardWidth);
                Vector2 transferTarget=PreparationGoldMetricRect.center;
                float arcHeight=Mathf.Clamp(
                    Vector2.Distance(reward.center,transferTarget)*0.2f,70f,170f);
                Vector2 movingCenter=TwinLinkPoint(
                    reward.center,transferTarget,arcHeight,goldTransfer);
                Rect movingReward=new Rect(
                    movingCenter.x-reward.width*0.5f,
                    movingCenter.y-reward.height*0.5f,
                    reward.width,reward.height);
                DrawLootRewardImpact(
                    reward,itemReveal*(1f-goldTransfer),
                    BombBrickUiTheme.Orange);
                DrawLootTransferTrail(
                    reward.center,transferTarget,arcHeight,
                    goldTransfer,BombBrickUiTheme.Orange,rewardIndex);
                DrawAtGuiScale(
                    itemReveal*WaveLootAbsorbScale(goldTransfer),
                    movingReward.center,()=>
                {
                    BombBrickUiTheme.Fill(
                        movingReward,BombBrickUiTheme.Surface);
                    BombBrickUiTheme.Frame(
                        movingReward,BombBrickUiTheme.Orange,1f);
                    float iconSize=movingReward.width*0.58f;
                    DrawSystemIcon(new Rect(
                        movingReward.center.x-iconSize*0.5f,
                        movingReward.y+11f,
                        iconSize,iconSize),
                        "gold",BombBrickUiTheme.Orange,false);
                    BombBrickUiTheme.Badge(
                        new Rect(movingReward.center.x-34f,
                            movingReward.yMax-29f,68f,24f),
                        "+"+waveLootReviewGold,BombBrickUiTheme.Orange);
                });
                rewardIndex++;
            }
        }
        float lastTransferEnd=WaveLootTransferStart+
            Mathf.Max(0,rewardCount-1)*0.08f+WaveLootTransferDuration;
        float transferT=Mathf.Clamp01(
            (elapsed-WaveLootTransferStart)/
            Mathf.Max(0.01f,lastTransferEnd-WaveLootTransferStart));
        string transferLabel=elapsed<WaveLootTransferStart
            ?"획득 전리품 확인"
            :(elapsed<lastTransferEnd
                ?"보관함으로 이동 중":"전리품 정산 완료");
        GUI.Label(new Rect(panel.x+24f,panel.yMax-78f,panel.width-48f,26f),
            transferLabel,
            BombBrickUiTheme.CaptionStyle(14,TextAnchor.MiddleCenter));
        float transferWidth=(panel.width-56f)*reveal;
        BombBrickUiTheme.Fill(new Rect(
            panel.center.x-transferWidth*0.5f,panel.yMax-42f,
            transferWidth*transferT,4f),BombBrickUiTheme.Cyan);
    }

    private static float WaveLootTransferProgress(float elapsed,int index)
    {
        return Mathf.SmoothStep(0f,1f,Mathf.Clamp01(
            (elapsed-(WaveLootTransferStart+index*0.08f))/
            WaveLootTransferDuration));
    }

    private static float WaveLootAbsorbScale(float transfer)
    {
        if(transfer<0.76f)
            return Mathf.Lerp(1f,0.68f,transfer/0.76f);
        return Mathf.Lerp(0.68f,0f,(transfer-0.76f)/0.24f);
    }

    private static void DrawLootTransferTrail(
        Vector2 start,Vector2 end,float arcHeight,float transfer,
        Color color,int seed)
    {
        if(transfer<=0f||transfer>=1f)return;
        for(int i=0;i<7;i++)
        {
            float t=Mathf.Clamp01(transfer*1.22f-i*0.075f);
            if(t<=0f||t>=1f)continue;
            Vector2 point=TwinLinkPoint(start,end,arcHeight,t);
            float size=(i+seed)%2==0?4f:3f;
            BombBrickUiTheme.Fill(new Rect(
                    Mathf.Round(point.x-size*0.5f),
                    Mathf.Round(point.y-size*0.5f),size,size),
                new Color(color.r,color.g,color.b,(1f-t)*0.9f));
        }
    }

    private void DrawLootSettlementDestinations(
        int displayedGold,float bagPulse,float goldPulse)
    {
        Rect bag=ItemBarRect;
        BombBrickUiTheme.DrawPanel(bag,true);
        BombBrickUiTheme.Fill(new Rect(bag.x,bag.y,4f,bag.height),
            BombBrickUiTheme.Cyan);
        BombBrickUiTheme.Frame(bag,
            Color.Lerp(BombBrickUiTheme.Cyan,Color.white,bagPulse),2f);
        DrawSystemIcon(new Rect(bag.x+14f,bag.y+14f,30f,30f),
            "shop",BombBrickUiTheme.Cyan,false);
        GUI.Label(new Rect(bag.x+52f,bag.y+10f,86f,24f),
            "탐험 가방",BombBrickUiTheme.TitleStyle(13));
        GUI.Label(new Rect(bag.x+52f,bag.y+36f,86f,26f),
            "전리품 수납",BombBrickUiTheme.CaptionStyle(
                9,TextAnchor.UpperLeft));
        Rect viewport=ItemInventoryViewportRect;
        BombBrickUiTheme.Fill(viewport,BombBrickUiTheme.Surface);
        BombBrickUiTheme.Frame(viewport,BombBrickUiTheme.Border,1f);

        DrawCompactRunMetric(PreparationGoldMetricRect,
            "gold","골드",displayedGold.ToString(),
            BombBrickUiTheme.Orange);
        if(goldPulse>0f)
            BombBrickUiTheme.Frame(new Rect(
                    PreparationGoldMetricRect.x-goldPulse*4f,
                    PreparationGoldMetricRect.y-goldPulse*4f,
                    PreparationGoldMetricRect.width+goldPulse*8f,
                    PreparationGoldMetricRect.height+goldPulse*8f),
                Color.Lerp(BombBrickUiTheme.Orange,Color.white,goldPulse),2f);
    }

    private static void DrawAtGuiScale(float scale,Vector2 pivot,Action draw)
    {
        if(draw==null||float.IsNaN(scale)||float.IsInfinity(scale)||
           scale<=0.0001f)return;
        float safeScale=Mathf.Clamp(scale,0.001f,4f);
        Matrix4x4 previousMatrix=GUI.matrix;
        try
        {
            GUIUtility.ScaleAroundPivot(
                new Vector2(safeScale,safeScale),pivot);
            draw();
        }
        finally
        {
            GUI.matrix=previousMatrix;
        }
    }

    private static void DrawLootRewardImpact(
        Rect reward,float reveal,Color accent)
    {
        if(reveal<=0f)return;
        float impact=Mathf.Clamp01((reveal-0.72f)/0.28f);
        float alpha=(1f-impact)*0.58f;
        BombBrickUiTheme.Frame(new Rect(
            reward.x-8f-impact*18f,reward.y-8f-impact*18f,
            reward.width+16f+impact*36f,
            reward.height+16f+impact*36f),
            new Color(accent.r,accent.g,accent.b,alpha),2f);
        BombBrickUiTheme.Fill(new Rect(
            reward.center.x-2f,reward.yMax+8f,
            4f,Mathf.Max(0f,(1f-reveal)*52f)),
            new Color(accent.r,accent.g,accent.b,0.34f));
    }

    private void DrawExpeditionResultPanel()
    {
        bool failed=expeditionRun.status==ExpeditionRunStatus.Failed||
            resultText.Contains("패배");
        bool completed=expeditionRun.status==ExpeditionRunStatus.Completed||
            resultText.Contains("탐험 완료");
        Color accent=failed?BombBrickUiTheme.Red:
            (completed?BombBrickUiTheme.Lime:BombBrickUiTheme.Cyan);
        BombBrickUiTheme.Fill(new Rect(0f,0f,BombBrickUiLayout.Width,BombBrickUiLayout.Height),
            new Color(0.006f,0.009f,0.016f,0.72f));
        Rect safe=UiLayout.safeArea;
        float width=Mathf.Min(620f,safe.width-48f);
        bool productionFlow=GameFlowController.HasActiveExpeditionRequest;
        float height=failed&&!expeditionFailed?318f:
            (productionFlow?332f:282f);
        Rect panel=new Rect(
            safe.center.x-width*0.5f,
            safe.center.y-height*0.5f,
            width,height);
        BombBrickUiTheme.DrawPanel(panel,true);
        BombBrickUiTheme.Fill(new Rect(panel.x,panel.y,panel.width,4f),accent);
        GUI.Label(new Rect(panel.x+24f,panel.y+22f,panel.width-48f,18f),
            "W "+expeditionRun.wave+" · 탐험 결과",
            BombBrickUiTheme.CaptionStyle(10,TextAnchor.MiddleCenter));
        GUI.Label(new Rect(panel.x+24f,panel.y+48f,panel.width-48f,46f),
            completed?"탐험 완료":(failed?"전투 패배":"전투 결과"),
            BombBrickUiTheme.DisplayStyle(30));
        string resultLabel=GameLocalization.IsEnglish&&resultText.Contains("\n")
            ?string.Join("\n",resultText.Split('\n').Select(GameLocalization.Text))
            :resultText;
        GUI.Label(new Rect(panel.x+34f,panel.y+101f,panel.width-68f,26f),
            resultLabel,
            BombBrickUiTheme.BodyStyle(14,TextAnchor.MiddleCenter));

        Rect lifePanel=new Rect(panel.center.x-126f,panel.y+145f,252f,54f);
        BombBrickUiTheme.Fill(lifePanel,BombBrickUiTheme.Surface);
        BombBrickUiTheme.Frame(lifePanel,
            failed?BombBrickUiTheme.Red:BombBrickUiTheme.Border,1f);
        DrawSystemIcon(new Rect(lifePanel.x+18f,lifePanel.y+12f,30f,30f),
            "life",failed?BombBrickUiTheme.Red:BombBrickUiTheme.Lime,false);
        GUI.Label(new Rect(lifePanel.x+58f,lifePanel.y+5f,174f,18f),
            "남은 목숨",BombBrickUiTheme.CaptionStyle(10));
        GUI.Label(new Rect(lifePanel.x+58f,lifePanel.y+22f,174f,26f),
            expeditionRun.lives+" / "+
            Mathf.Max(StartingExpeditionLives,expeditionRun.maximumLives),
            BombBrickUiTheme.TitleStyle(18));

        if(failed&&!expeditionFailed)
        {
            GUI.Label(new Rect(panel.x+28f,panel.y+213f,panel.width-56f,20f),
                "전리품은 획득되지 않았으며 동일한 적·맵에서 다시 도전합니다.",
                BombBrickUiTheme.CaptionStyle(11,TextAnchor.MiddleCenter));
            if(BombBrickUiTheme.Button(
                new Rect(panel.center.x-132f,panel.yMax-61f,264f,40f),
                "같은 WAVE 재도전",true,true))
                RetryCurrentWave();
        }
        else
        {
            GUI.Label(new Rect(panel.x+28f,
                productionFlow?panel.y+215f:panel.yMax-58f,
                panel.width-56f,24f),
                completed?"모든 Wave를 돌파했습니다.":
                    "좌측 전투 데이터 탭에서 기록을 확인할 수 있습니다.",
                BombBrickUiTheme.CaptionStyle(12,TextAnchor.MiddleCenter));
            if(productionFlow&&BombBrickUiTheme.Button(
                new Rect(panel.center.x-132f,panel.yMax-62f,264f,40f),
                GameLocalization.TextByKey(
                    "result.confirm","탐험 결과 확인"),true,true))
            {
                GameFlowController.Instance.FinishExpedition(
                    completed,
                    expeditionRun.lastCompletedWave,
                    ExpeditionWaveCount,
                    expeditionRun.lives,
                    expeditionRun.expeditionCurrency);
            }
        }
    }

    private void DrawCaptureResult()
    {
        if(capturePresentationResultStartedAt<0f)return;
        float elapsed=Time.unscaledTime-capturePresentationResultStartedAt;
        if(capturePresentationSucceeded&&capturePresentationMonster!=null)
        {
            DrawCaptureAcquisitionCard(elapsed);
            return;
        }
        float pop=1f-Mathf.Clamp01(elapsed/0.18f);
        float alpha=capturePresentationShade==null?1f:
            capturePresentationShade.GetComponent<SpriteRenderer>().color.a;
        Color color=capturePresentationSucceeded
            ?new Color(0.34f,1f,0.78f,alpha):new Color(1f,0.55f,0.38f,alpha);
        Rect rect=new Rect(BombBrickUiLayout.Width*0.075f,
            BombBrickUiLayout.Height*0.65f-40f,
            BombBrickUiLayout.Width*0.85f,80f);
        BombBrickUiTheme.Label(rect,captureUiMessage,
            BombBrickUiTheme.TitleStyle(Mathf.RoundToInt(32f*(1f+0.18f*pop*pop)),
                TextAnchor.MiddleCenter),color);
    }

    private void DrawCaptureAcquisitionCard(float age)
    {
        OwnedMonsterSave owned=capturePresentationMonster;
        MonsterDefinition definition=monsterDatabase.Get(owned.monsterId);
        Rect card=new Rect(BombBrickUiLayout.Width*.5f-350f,BombBrickUiLayout.Height*.5f-274f,700f,548f);
        Color accent=owned.isShiny?BombBrickUiTheme.Lime:BombBrickUiTheme.Cyan;
        BombBrickUiTheme.DrawPanel(card,true);
        BombBrickUiTheme.Frame(card,accent,2f);
        GUI.Label(new Rect(card.x+20f,card.y+18f,card.width-40f,34f),captureUiMessage,
            BombBrickUiTheme.TitleStyle(25,TextAnchor.MiddleCenter));
        if(age>=MonsterAcquisitionReveal.PortraitAt)
        {
            float enter=BombBrickUiTheme.EaseOutCubic(Mathf.Clamp01((age-MonsterAcquisitionReveal.PortraitAt)/.28f));
            DrawPortrait(new Rect(card.center.x-80f,card.y+62f-(1f-enter)*28f,160f,160f),definition,owned);
        }
        if(age>=.3f)GUI.Label(new Rect(card.x+20f,card.y+235f,card.width-40f,30f),
            definition==null?owned.monsterId:definition.displayName,BombBrickUiTheme.TitleStyle(22,TextAnchor.MiddleCenter));
        MonsterAcquisitionReveal.DrawStats(new Rect(card.x+36f,card.y+286f,card.width-72f,120f),definition,owned,age,3,20);
        MonsterAcquisitionReveal.DrawGradeStamp(new Rect(card.center.x-170f,card.y+439f,340f,52f),owned,age,27);
        GUI.Label(new Rect(card.x+20f,card.yMax-38f,card.width-40f,24f),
            age>=MonsterAcquisitionReveal.ReadyAt?GameLocalization.Text("확인"):
                GameLocalization.TextByKey("reward.acquisition.capture_hint","클릭하여 결과 바로 보기"),
            BombBrickUiTheme.CaptionStyle(13,TextAnchor.MiddleCenter));
    }

    private void DrawCaptureStatus()
    {
        if(string.IsNullOrWhiteSpace(captureUiMessage))return;
        string text=captureUiMessage;
        Rect panel=UiLayout.captureStatus;
        Color previous=GUI.color;
        GUI.color=new Color(0.18f,0.65f,0.82f,0.96f);
