    private void DrawCaptureNetBar()
    {
        if(expeditionRun==null||playerProfile==null)return;
        Rect panel=CaptureNetBarRect;
        Event current=Event.current;
        bool used=expeditionRun.captureAttemptedWave==expeditionRun.wave;
        bool available=!battleStarted&&!battleEnding&&!used&&
                       (!FirstExpeditionBattleTutorialActive||
                        FirstCaptureGuideVisible);
        BombBrickUiTheme.DrawPanel(panel,true);
        BombBrickUiTheme.Fill(
            new Rect(panel.x,panel.y,4f,panel.height),
            BombBrickUiTheme.Cyan);
        GUI.Label(new Rect(panel.x+11f,panel.y+5f,132f,18f),
            "포획 그물",BombBrickUiTheme.TitleStyle(11));

        for(int index=0;index<CaptureNetCatalog.All.Count;index++)
        {
            CaptureNetDefinition net=CaptureNetCatalog.All[index];
            int count=profileStore.CaptureNetCount(playerProfile,net.itemId);
            Rect slot=CaptureNetSlotRect(index);
            bool selected=captureTarget!=null&&string.Equals(
                expeditionRun.selectedCaptureNetItemId,
                net.itemId,StringComparison.Ordinal);
            bool enabled=available&&count>0&&
                (!FirstCaptureGuideVisible||
                 net.itemId==CaptureNetCatalog.StandardId);
            Color accent=CaptureNetCatalog.GradeColor(net.grade);
            BombBrickUiTheme.Fill(slot,selected
                ?new Color(accent.r,accent.g,accent.b,0.20f)
                :BombBrickUiTheme.Surface);
            BombBrickUiTheme.Frame(slot,
                enabled||selected?accent:BombBrickUiTheme.Border,
                selected?2f:1f);
            Color previous=GUI.color;
            GUI.color=enabled||selected
                ?Color.white:new Color(1f,1f,1f,0.30f);
            DrawCaptureNetGlyph(
                new Rect(slot.x+7f,slot.y+3f,40f,40f),
                accent,false,net.itemId);
            GUI.color=previous;
            BombBrickUiTheme.Badge(
                new Rect(slot.xMax-21f,slot.y-5f,23f,17f),
                count.ToString(),accent);
            GUI.Label(new Rect(slot.x+2f,slot.yMax-17f,slot.width-4f,14f),
                Mathf.RoundToInt(net.SuccessChance*100f)+"%",
                BombBrickUiTheme.CaptionStyle(
                    9,TextAnchor.MiddleCenter));
            if(enabled&&current.type==EventType.MouseDown&&
               current.button==0&&slot.Contains(current.mousePosition))
            {
                draggedCaptureNetItemId=net.itemId;
                draggingCaptureNet=false;
                current.Use();
            }
        }

        Rect cancel=new Rect(panel.x+148f,panel.y+31f,74f,43f);
        bool canCancel=available&&captureTarget!=null&&
                       !FirstCaptureGuideVisible;
        if(BombBrickUiTheme.Button(
            cancel,"포획\n취소",canCancel,true))
        {
            ClearCaptureTarget();
            draggedCaptureNetItemId="";
            draggingCaptureNet=false;
        }

        if(current.type==EventType.MouseDrag&&current.button==0&&
           !string.IsNullOrEmpty(draggedCaptureNetItemId))
        {
            draggingCaptureNet=true;
            current.Use();
        }
        if(current.type==EventType.MouseUp&&current.button==0&&
           !string.IsNullOrEmpty(draggedCaptureNetItemId))
        {
            Unit target=draggingCaptureNet
                ?EnemyUnitAtGuiPoint(current.mousePosition):null;
            if(target!=null)
                SetCaptureTarget(target,draggedCaptureNetItemId);
            else if(draggingCaptureNet)
                captureUiMessage="야생 몬스터 위에 포획 그물을 놓아주세요.";
            draggedCaptureNetItemId="";
            draggingCaptureNet=false;
            RefreshUnitOutlines();
            current.Use();
        }

        if(!FirstCaptureGuideVisible)DrawCaptureNetDragPreview();
        RefreshUnitOutlines();
    }

    private void DrawCaptureNetDragPreview()
    {
        if(draggingCaptureNet&&!string.IsNullOrEmpty(draggedCaptureNetItemId))
        {
            CaptureNetDefinition net=CaptureNetCatalog.Get(
                draggedCaptureNetItemId);
            Vector2 pointer=Event.current.mousePosition;
            Rect token=BombBrickUiLayout.ClampRect(
                new Rect(pointer.x-25f,pointer.y-25f,50f,50f),
                UiLayout.safeArea,8f);
            Color accent=CaptureNetCatalog.GradeColor(net.grade);
            BombBrickUiTheme.Fill(token,
                new Color(0.02f,0.03f,0.05f,0.90f));
            BombBrickUiTheme.Frame(token,accent,2f);
            DrawCaptureNetGlyph(
                new Rect(token.x+5f,token.y+5f,40f,40f),
                accent,false,net.itemId);
            Unit target=EnemyUnitAtGuiPoint(pointer);
            DrawDragStatusBadge(
                pointer,target==null
                    ?GameLocalization.TextByKey(
                        "capture.place_on_wild","야생 몬스터에게 놓기")
                    :GameLocalization.Format(
                        "capture.target_selected","{0} 포획 지정",
                        GameLocalization.Text(target.displayName)),
                target!=null);
        }
    }

