    private void DrawFirstExpeditionBattleTutorialGuide()
    {
        if(FirstCaptureGuideVisible)
        {
            Rect slot=CaptureNetSlotRect(0);
            Rect focus=new Rect(slot.x-7f,slot.y-7f,slot.width+14f,slot.height+14f);
            if(draggingCaptureNet&&TryGetBattlefieldGuiRect(out Rect battlefield))
                focus=battlefield;
            DrawFirstBattleTutorialFocus(
                focus,
                "25% 그물을 적에게 드래그하세요.",BombBrickUiTheme.Cyan);
            DrawCaptureNetDragPreview();
            return;
        }
        if(FirstDeploymentGuideVisible)
        {
            Rect focus;
            string message;
            if(draggingUnit&&TryGetPlayerDeploymentGuiRect(out focus))
                message="파란 전투 타일에 놓으세요.";
            else if(TryGetBenchUnitsGuiRect(out focus))
                message="대기 몬스터를 전장으로 드래그하세요.";
            else return;
            DrawFirstBattleTutorialFocus(focus,message,BombBrickUiTheme.Lime);
            return;
        }
        if(FirstBattleStartGuideVisible)
        {
            DrawFirstBattleTutorialFocus(
                BattleStartButtonRect,
                "전투 시작 · Space 키로도 시작할 수 있습니다.",
                BombBrickUiTheme.Lime);
            return;
        }
        if(FirstItemCombineGuideVisible&&
           TryGetInventoryTutorialItemsRect(false,2,out Rect combineFocus))
        {
            if(draggingItem&&itemFusionPreviewRect.width>0f)
                combineFocus=UnionRect(combineFocus,itemFusionPreviewRect);
            DrawFirstBattleTutorialFocus(
                combineFocus,"아이템끼리 드래그해 합성하세요.",
                BombBrickUiTheme.Orange);
            return;
        }
        if(FirstItemEquipGuideVisible)
        {
            Rect focus;
            string message;
            if(draggingItem&&TryGetPlayerUnitsGuiRect(out focus))
                message="원하는 아군에게 놓아 장착하세요.";
            else if(TryGetInventoryTutorialItemsRect(true,1,out focus))
                message="완성 아이템을 아군에게 드래그하세요.";
            else return;
            DrawFirstBattleTutorialFocus(focus,message,BombBrickUiTheme.Lime);
            return;
        }
        if(FirstItemTransferGuideVisible)
        {
            Rect focus;
            string message;
            Unit owner=null;
            if(draggingItem)
            {
                TryFindEquippedSlot(draggedItemInstanceId,out owner,out _);
                if(!TryGetPlayerUnitsGuiRect(out focus,owner))return;
                message="다른 아군에게 놓아 옮기세요.";
            }
            else
            {
                if(!TryGetTutorialEquippedItemRect(out focus))return;
                message="전투 전엔 착용 아이템을 언제든 다른 아군에게 드래그할 수 있습니다.";
            }
            DrawFirstBattleTutorialFocus(focus,message,BombBrickUiTheme.Cyan);
        }
    }

    private bool TryGetTutorialEquippedItemRect(out Rect result)
    {
        result=new Rect();
        if(inspectedUnit==null||inspectedUnit.team!=Team.Player)return false;
        ExpeditionMonsterStateSave state=ExpeditionItemSystem.MonsterState(
            expeditionRun,inspectedUnit.stableId);
        if(state==null)return false;
        Rect row=SelectedUnitSlotRowRect(inspectedUnit);
        for(int slot=0;slot<state.itemInstanceIds.Count;slot++)
        {
            ExpeditionItemInstanceSave instance=ExpeditionItemSystem.ItemInstance(
                expeditionRun,state.itemInstanceIds[slot]);
            if(GameMasterData.Item(instance==null?"":instance.itemId)?.IsCompleted!=true)
                continue;
            Rect item=new Rect(row.x+slot*58f,row.y,52f,48f);
            result=new Rect(item.x-7f,item.y-7f,item.width+14f,item.height+14f);
            return true;
        }
        return false;
    }

    private bool TryGetInventoryTutorialItemsRect(
        bool completed,int required,out Rect result)
    {
        result=new Rect();
        bool found=false;
        int count=0;
        Rect viewport=ItemInventoryViewportRect;
        List<KeyValuePair<string,List<string>>> stacks=BuildInventoryItemStacks();
        for(int i=0;i<stacks.Count&&count<required;i++)
        {
            ItemMasterRow item=GameMasterData.Item(stacks[i].Key);
            if(item==null||item.IsCompleted!=completed)continue;
            Rect bounds=new Rect(
                viewport.x+4f+i*74f-itemBarScroll.x,
                viewport.y+3f,68f,54f);
            if(bounds.xMax<=viewport.x||bounds.x>=viewport.xMax)continue;
            bounds=Rect.MinMaxRect(
                Mathf.Max(bounds.xMin,viewport.x),bounds.yMin,
                Mathf.Min(bounds.xMax,viewport.xMax),bounds.yMax);
            result=found?UnionRect(result,bounds):bounds;
            found=true;
            count++;
        }
        if(found)result=new Rect(
            result.x-7f,result.y-7f,result.width+14f,result.height+14f);
        return count>=required;
    }

    private bool TryGetPlayerUnitsGuiRect(out Rect result,Unit excluded=null)
    {
        result=new Rect();
        bool found=false;
        foreach(Unit unit in units)
        {
            if(unit==null||unit==excluded||unit.team!=Team.Player||!unit.alive||
               !TryGetUnitGuiRect(unit,out Rect bounds))continue;
            result=found?UnionRect(result,bounds):bounds;
            found=true;
        }
        if(found)result=new Rect(
            result.x-12f,result.y-12f,result.width+24f,result.height+24f);
        return found;
    }

    private bool TryGetBenchUnitsGuiRect(out Rect result)
    {
        result=new Rect();
        bool found=false;
        foreach(Unit unit in units)
        {
            if(unit==null||unit.team!=Team.Player||!unit.alive||
               !unit.inStorage||!CanAffordDeployment(unit)||
               !TryGetUnitGuiRect(unit,out Rect bounds))continue;
            result=found?UnionRect(result,bounds):bounds;
            found=true;
        }
        if(found)result=new Rect(
            result.x-12f,result.y-12f,result.width+24f,result.height+24f);
        return found;
    }

    private bool TryGetBattlefieldGuiRect(out Rect result)
    {
        result=new Rect();
        if(mainCamera==null||tiles.Count==0)return false;
        Vector3 min=mapBounds.min,max=mapBounds.max;
        float minX=float.MaxValue,minY=float.MaxValue,maxX=float.MinValue,maxY=float.MinValue;
        // mapBounds includes both the combat field and the bench field.
        for(int x=0;x<2;x++)for(int z=0;z<2;z++)
        {
            Vector3 screen=mainCamera.WorldToScreenPoint(
                new Vector3(x==0?min.x:max.x,mapBounds.center.y,z==0?min.z:max.z));
            if(screen.z<=0f)continue;
            screen/=BombBrickUiLayout.Scale;
            float guiY=BombBrickUiLayout.Height-screen.y;
            minX=Mathf.Min(minX,screen.x);maxX=Mathf.Max(maxX,screen.x);
            minY=Mathf.Min(minY,guiY);maxY=Mathf.Max(maxY,guiY);
        }
        if(minX==float.MaxValue)return false;
        result=Rect.MinMaxRect(minX,minY,maxX,maxY);
        foreach(Unit unit in units)
            if(unit!=null&&unit.alive&&unit.model!=null&&unit.model.activeInHierarchy&&
               TryGetUnitGuiRect(unit,out Rect bounds))
                result=UnionRect(result,bounds);
        result=new Rect(result.x-12f,result.y-12f,result.width+24f,result.height+24f);
        return true;
    }

    private bool TryGetPlayerDeploymentGuiRect(out Rect result)
    {
        result=new Rect();
        if(mainCamera==null)return false;
        bool found=false;
        foreach(Tile tile in tiles.Values)
        {
            if(tile==null||tile.bench||tile.deploymentTeam!=Team.Player)continue;
            Vector3 screen=mainCamera.WorldToScreenPoint(tile.world);
            if(screen.z<=0f)continue;
            screen/=BombBrickUiLayout.Scale;
            Vector2 point=new Vector2(screen.x,BombBrickUiLayout.Height-screen.y);
            Rect bounds=new Rect(point.x-28f,point.y-20f,56f,40f);
            result=found?UnionRect(result,bounds):bounds;
            found=true;
        }
        return found;
    }

    private static Rect UnionRect(Rect left,Rect right)
    {
        return Rect.MinMaxRect(
            Mathf.Min(left.xMin,right.xMin),Mathf.Min(left.yMin,right.yMin),
            Mathf.Max(left.xMax,right.xMax),Mathf.Max(left.yMax,right.yMax));
    }

    private void DrawFirstBattleTutorialFocus(
        Rect target,string message,Color baseAccent)
    {
        if(firstCaptureGuideChangedAt<0f)
            firstCaptureGuideChangedAt=Time.unscaledTime;
        float reveal=BombBrickUiTheme.EaseOutCubic(Mathf.Clamp01(
            (Time.unscaledTime-firstCaptureGuideChangedAt)/0.22f));
        float blink=Mathf.PingPong(Time.unscaledTime*2.2f,1f);
        Color accent=Color.Lerp(
            baseAccent,Color.white,0.2f+blink*0.45f);
        DrawCaptureGuideShade(target,0.74f*reveal);
        BombBrickUiTheme.Frame(
            new Rect(target.x-3f,target.y-3f,
                target.width+6f,target.height+6f),
            new Color(accent.r,accent.g,accent.b,0.94f),3f);

        Rect safe=UiLayout.safeArea;
        float width=Mathf.Min(440f,safe.width-24f);
        float hintY=target.y-66f>=safe.y+8f
            ?target.y-66f:target.yMax+10f;
        Rect hint=new Rect(
            Mathf.Clamp(target.x,safe.x+8f,safe.xMax-width-8f),
            Mathf.Clamp(hintY,safe.y+8f,safe.yMax-60f),width,52f);
        BombBrickUiTheme.DrawPanel(hint,true);
        BombBrickUiTheme.Fill(
            new Rect(hint.x,hint.y,4f,hint.height),accent);
        GUI.Label(
            new Rect(hint.x+18f,hint.y+7f,hint.width-68f,hint.height-14f),
            message,
            BombBrickUiTheme.TitleStyle(14,TextAnchor.MiddleLeft));
        GUI.Label(
            new Rect(hint.xMax-48f,hint.y+7f,32f,hint.height-14f),
            "›",BombBrickUiTheme.TitleStyle(22,TextAnchor.MiddleCenter));
    }

    private static void DrawCaptureGuideShade(Rect target,float alpha)
    {
        Rect screen=new Rect(0f,0f,BombBrickUiLayout.Width,BombBrickUiLayout.Height);
        Rect hole=Rect.MinMaxRect(
            Mathf.Clamp(target.xMin,screen.xMin,screen.xMax),
            Mathf.Clamp(target.yMin,screen.yMin,screen.yMax),
            Mathf.Clamp(target.xMax,screen.xMin,screen.xMax),
            Mathf.Clamp(target.yMax,screen.yMin,screen.yMax));
        Color shade=new Color(0f,0f,0f,alpha);
        BombBrickUiTheme.Fill(
            new Rect(screen.x,screen.y,screen.width,
                Mathf.Max(0f,hole.yMin-screen.y)),shade);
        BombBrickUiTheme.Fill(
            new Rect(screen.x,hole.yMin,
                Mathf.Max(0f,hole.xMin-screen.x),hole.height),shade);
        BombBrickUiTheme.Fill(
            new Rect(hole.xMax,hole.yMin,
                Mathf.Max(0f,screen.xMax-hole.xMax),hole.height),shade);
        BombBrickUiTheme.Fill(
            new Rect(screen.x,hole.yMax,screen.width,
                Mathf.Max(0f,screen.yMax-hole.yMax)),shade);
    }

    private Unit EnemyUnitAtGuiPoint(Vector2 point)
    {
        Unit best=null;
        float bestDistance=float.MaxValue;
        foreach(Unit unit in units)
        {
            if(unit.team!=Team.Enemy||!unit.alive||unit.model==null||
               !unit.model.activeInHierarchy)continue;
            if(!TryGetUnitGuiRect(unit,out Rect rect)||
               !rect.Contains(point))continue;
            float distance=Vector2.Distance(point,rect.center);
            if(distance>=bestDistance)continue;
            bestDistance=distance;
            best=unit;
        }
        return best;
    }

