    private void DrawTraitTestPanel()
    {
        if(!traitTestPanelVisible)return;
        Rect panel=TraitTestPanelRect;
        GUI.Box(panel,"TRAIT TEST · Editor Only (F7)");
        float x=panel.x+12f;
        float y=panel.y+28f;
        float width=panel.width-24f;
        Unit target=inspectedUnit!=null&&inspectedUnit.team==Team.Player?inspectedUnit:null;
        GUI.Label(new Rect(x,y,width,22f),target==null
            ?"Select an allied monster during preparation."
            :"Target: "+target.displayName+" / "+target.definition.familyId);
        y+=26f;

        GUI.enabled=!battleStarted&&target!=null;
        if(GUI.Button(new Rect(x,y,112f,26f),
               (traitTestSelectedSlot==0?"▶ ":"")+"Test slot 1"))traitTestSelectedSlot=0;
        if(GUI.Button(new Rect(x+118f,y,112f,26f),
               (traitTestSelectedSlot==1?"▶ ":"")+"Test slot 2"))traitTestSelectedSlot=1;
        if(GUI.Button(new Rect(x+236f,y,108f,26f),"Clear slot"))ClearDebugTraitSlot(target);
        if(GUI.Button(new Rect(x+350f,y,126f,26f),"Clear both"))ClearAllDebugTraits(target);
        GUI.enabled=true;
        y+=31f;

        string first=target==null?"-":TraitName(target.debugTraitSlot1);
        string second=target==null?"-":TraitName(target.debugTraitSlot2);
        GUI.Label(new Rect(x,y,width,22f),"Slot 1: "+first+"    /    Slot 2: "+second);
        y+=23f;
        GUI.Label(new Rect(x,y,width,22f),traitTestMessage);
        y+=25f;

        Rect view=new Rect(x,y,width,panel.yMax-y-12f);
        List<MonsterTraitDefinition> compatible=target==null
            ?new List<MonsterTraitDefinition>()
            :MonsterTraitCatalog.All.Where(trait=>trait.IsCompatible(target.definition))
                .OrderBy(trait=>trait.id.StartsWith("trait_skill_",StringComparison.Ordinal)?1:0)
                .ThenBy(trait=>trait.displayName,StringComparer.Ordinal).ToList();
        float contentHeight=Mathf.Max(view.height-2f,compatible.Count*31f+4f);
        traitTestScroll=GUI.BeginScrollView(view,traitTestScroll,
            new Rect(0f,0f,width-18f,contentHeight));
        for(int i=0;i<compatible.Count;i++)
        {
            MonsterTraitDefinition trait=compatible[i];
            bool skill=trait.id.StartsWith("trait_skill_",StringComparison.Ordinal);
            string prefix=skill?"[SKILL] ":"[BASIC] ";
            bool assigned=target!=null&&(target.debugTraitSlot1==trait.id||
                                         target.debugTraitSlot2==trait.id);
            GUI.enabled=!battleStarted&&target!=null&&!assigned;
            if(GUI.Button(new Rect(2f,i*31f,width-24f,27f),
                   prefix+trait.displayName+(assigned?"  · assigned":"")))
                AssignDebugTrait(target,trait.id);
        }
        GUI.enabled=true;
        GUI.EndScrollView();
    }

    private void AssignDebugTrait(Unit target,string traitId)
    {
        if(target==null||battleStarted||!MonsterTraitCatalog.IsCompatible(traitId,target.definition))return;
        if(traitTestSelectedSlot==0)
        {
            target.debugTraitSlot1=traitId;
            if(target.debugTraitSlot2==traitId)target.debugTraitSlot2="";
        }
        else
        {
            target.debugTraitSlot2=traitId;
            if(target.debugTraitSlot1==traitId)target.debugTraitSlot1="";
        }
        RefreshDebugTraitTarget(target);
        traitTestMessage="Applied immediately: "+TraitName(traitId);
    }

    private void ClearDebugTraitSlot(Unit target)
    {
        if(target==null||battleStarted)return;
        if(traitTestSelectedSlot==0)target.debugTraitSlot1="";
        else target.debugTraitSlot2="";
        RefreshDebugTraitTarget(target);
        traitTestMessage="Selected test slot cleared.";
    }

    private void ClearAllDebugTraits(Unit target)
    {
        if(target==null||battleStarted)return;
        target.debugTraitSlot1="";
        target.debugTraitSlot2="";
        RefreshDebugTraitTarget(target);
        traitTestMessage="All test traits cleared.";
    }

    private void RefreshDebugTraitTarget(Unit target)
    {
        target.traitState.Reset();
        RefreshUnitFromOwnedData(target,target.definition,target.ownedInstance);
        SetSelectedUnit(null);
        inspectedUnit=target;
    }

