                 (balanceTestAllWaves?"All waves "+balanceTestWave+" / "+ExpeditionWaveCount+" · ":"")+
                 (balanceTestWaitingForRestart?"Preparing next trial...":"Battle simulation running...")
                :"Ready");
        y+=23f;
        GUI.Label(new Rect(x,y,306f,22f),
            string.IsNullOrEmpty(balanceReportPaths)?"Report: not generated":"Report: CSV + JSON saved");

        y+=27f;
        int qaPages=RosterQaPageCount(monsterDatabase);
        List<MonsterDefinition> qaBatch=RosterQaBatch(monsterDatabase,rosterQaPage);
        string qaRange=qaBatch.Count==0?"-":
            qaBatch.First().serialNumber+"-"+qaBatch.Last().serialNumber;
        GUI.Label(new Rect(x,y,96f,22f),"Roster QA");
        GUI.enabled=!balanceTestRunning&&!rosterQaRunning&&qaPages>0;
        if(GUI.Button(new Rect(x+82f,y,28f,22f),"<"))
            rosterQaPage=(rosterQaPage-1+qaPages)%qaPages;
        GUI.Label(new Rect(x+114f,y,72f,22f),qaRange);
        if(GUI.Button(new Rect(x+184f,y,28f,22f),">"))
            rosterQaPage=(rosterQaPage+1)%qaPages;
        if(GUI.Button(new Rect(x+218f,y,88f,22f),"Load batch"))
            ApplyRosterQaPage(rosterQaPage,false);

        y+=28f;
        if(!rosterQaRunning)
        {
            if(GUI.Button(new Rect(x,y,142f,26f),"Run 001-080"))
                StartRosterQaRun();
        }
        else
        {
            GUI.enabled=true;
            if(GUI.Button(new Rect(x,y,142f,26f),"Stop after battle"))
                rosterQaRunning=false;
        }
        GUI.enabled=true;
        GUI.Label(new Rect(x+150f,y,156f,26f),rosterQaMessage);

        y+=30f;
        GUI.enabled=!balanceTestRunning&&!rosterQaRunning;
        if(GUI.Button(new Rect(x,y,142f,26f),
               comboQaRunning?"Stop Combo QA":"Run Combo QA"))ToggleComboQa();
        GUI.enabled=true;
        GUI.Label(new Rect(x+150f,y,156f,26f),comboQaMessage);
    }

    [UnityEditor.MenuItem("BombBrick/QA/Toggle Combo Battle")]
    private static void ToggleComboQaFromMenu()
    {
        if(!Application.isPlaying)
        {
            Debug.LogWarning("[Combo QA] Play Mode에서 실행하세요.");
            return;
        }
        MonsterAutoBattlePrototype battle=FindObjectOfType<MonsterAutoBattlePrototype>();
        if(battle==null)Debug.LogWarning("[Combo QA] 전투 씬을 찾지 못했습니다.");
        else battle.ToggleComboQa();
    }

    private void ToggleComboQa()
    {
        if(comboQaRunning)StopComboQa("사용자 중단",true);
        else StartComboQa();
    }

    private void StartComboQa()
    {
        if(balanceTestRunning||rosterQaRunning||battleEnding||resultText.Length>0)
        {
            comboQaMessage="다른 테스트 또는 결과 화면 종료 필요";
            return;
        }
        if(!battleStarted)
        {
            List<string> selected=BattleReadyUnits().Take(2)
                .Select(unit=>unit.stableId).ToList();
            if(selected.Count<2)
            {
                comboQaMessage="배치 가능한 아군 2개체 필요";
                return;
            }
            ArrangePlayerFormationForNewWave(selected);
            SuppressSimulationIntermissions();
            waveIntroActive=false;
            BeginCurrentBattleImmediately();
        }
        List<Unit> allies=units.Where(unit=>IsCombatActive(unit)&&
            unit.team==Team.Player).OrderBy(unit=>unit.id).ToList();
        comboQaTarget=units.Where(unit=>IsCombatActive(unit)&&unit.team==Team.Enemy)
            .OrderBy(unit=>unit.id).FirstOrDefault();
        if(allies.Count<2||comboQaTarget==null)
        {
            comboQaMessage="활성 아군 2개체와 적 1개체 필요";
            return;
        }
        comboQaOwner=allies.FirstOrDefault(unit=>unit.skillCooldownDuration>0f)??allies[0];
        comboQaProvider=allies.First(unit=>unit!=comboQaOwner);
        comboQaRunning=true;
        comboQaIndex=0;
        comboQaPassed=0;
        comboQaOriginalTimeScale=Time.timeScale;
        Time.timeScale=4f;
        PrepareComboQaScenario();
        Debug.Log("[Combo QA] 8개 실제 전투 연계 시나리오 시작");
    }

    private void PrepareComboQaScenario()
    {
        string traitId=ComboQaTraitIds[comboQaIndex];
        comboQaOwner.activeTraitIds.RemoveAll(id=>id.StartsWith(
            "trait_combo_",StringComparison.Ordinal));
        comboQaOwner.activeTraitIds.Add(traitId);
        comboQaOwner.traitState.Reset();
        comboQaOwner.combatStatuses.Clear();
        comboQaTarget.combatStatuses.Clear();
        comboQaTarget.combatStatuses.ApplyTimed(
            CombatStatusKind.Root,30f,comboQaTarget);
        switch(traitId)
        {
            case "trait_combo_antigravity":
                comboQaTarget.combatStatuses.ApplyTimed(
                    CombatStatusKind.Displaced,30f,comboQaProvider);
                comboQaTarget.combatStatuses.ApplyTimed(
                    CombatStatusKind.Marked,30f,comboQaProvider);
                break;
            case "trait_combo_fall_shatter":
                comboQaTarget.combatStatuses.ApplyTimed(
                    CombatStatusKind.Airborne,30f,comboQaProvider,30f);
                break;
            case "trait_combo_frost_shackle":
                comboQaTarget.combatStatuses.ApplyTimed(
                    CombatStatusKind.Root,30f,comboQaProvider);
                break;
            case "trait_combo_venom_mutation":
                comboQaTarget.combatStatuses.ApplyStacks(
                    CombatStatusKind.Bleed,30f,2,3,comboQaProvider,0f,0f,true);
                break;
            case "trait_combo_chemical_ignition":
                comboQaTarget.combatStatuses.ApplyStacks(
                    CombatStatusKind.Poison,30f,3,
                    CombatStatusState.MaximumPoisonStacks,
                    comboQaProvider,0f,0f,true);
                break;
            case "trait_combo_open_wound":
                comboQaTarget.combatStatuses.ApplyTimed(
                    CombatStatusKind.Marked,30f,comboQaProvider);
                break;
            case "trait_combo_morale_veil":
                comboQaOwner.combatStatuses.ApplyShield(
                    30f,comboQaOwner.maxHp*0.2f,comboQaProvider);
                break;
            case "trait_combo_resolve_barrier":
                comboQaOwner.combatStatuses.ApplyTimed(
                    CombatStatusKind.ComboRally,30f,comboQaProvider,0.2f);
                comboQaTarget.combatStatuses.ApplyTimed(
                    CombatStatusKind.Marked,30f,comboQaProvider);
                break;
        }
        bool needsSkill=traitId=="trait_combo_antigravity"||
                        traitId=="trait_combo_resolve_barrier";
        comboQaOwner.cooldown=needsSkill?999f:0f;
        comboQaOwner.skillTimer=needsSkill?0f:999f;
        comboQaOwner.forcedTarget=comboQaTarget;
        comboQaOwner.forcedTargetTimer=30f;
        SetTarget(comboQaOwner,comboQaTarget);
        comboQaOwner.speedTilesPerSecond=Mathf.Max(6f,comboQaOwner.speedTilesPerSecond);
        comboQaOwner.attackInterval=Mathf.Min(0.35f,comboQaOwner.attackInterval);
        comboQaOwner.personalityPolicy=PersonalityCombatPolicy.FromId("bold");
        Vector3 start=GridWorld(new Vector2Int(
            ActivePlayerDeployStartColumn+ActivePlayerDeployColumns-1,
            ActivePlayerDeployStartRow+ActivePlayerDeployRows/2));
        start.y=comboQaOwner.visualHeightOffset;
        comboQaOwner.model.transform.position=start;
        comboQaOwner.ring.transform.position=Flat(start)+Vector3.up*0.018f;
        comboQaOwner.velocity=Vector3.zero;
        ClearRoute(comboQaOwner);
        comboQaTarget.maxHp=comboQaTarget.hp=100000f;
        comboQaTarget.defense=0f;
        comboQaTarget.statusResistance=0f;
        comboQaStartActivations=comboQaOwner.comboActivations;
        comboQaStartDamage=comboQaOwner.comboBonusDamage;
        comboQaTimer=0f;
        comboQaMessage=(comboQaIndex+1)+"/8 "+
                       MonsterTraitRuntime.ComboShortName(traitId);
    }

    private void UpdateComboQa()
    {
        if(!comboQaRunning)return;
        if(!battleStarted||battleEnding||!IsCombatActive(comboQaOwner)||
           !IsCombatActive(comboQaProvider)||!IsCombatActive(comboQaTarget))
        {
            StopComboQa("전투 상태 소실",true);
            return;
        }
        comboQaTimer+=Time.deltaTime;
        for(int i=0;i<units.Count;i++)
        {
            Unit unit=units[i];
            if(!IsCombatActive(unit))continue;
            unit.hp=Mathf.Max(unit.hp,Mathf.Min(unit.maxHp,10000f));
            if(unit==comboQaOwner)continue;
            unit.cooldown=999f;
            unit.skillTimer=999f;
            object rootSource=unit==comboQaTarget&&
                              ComboQaTraitIds[comboQaIndex]=="trait_combo_frost_shackle"
                ?comboQaProvider:(object)unit;
            unit.combatStatuses.ApplyTimed(CombatStatusKind.Root,30f,rootSource);
        }
        comboQaOwner.forcedTarget=comboQaTarget;
        comboQaOwner.forcedTargetTimer=30f;
        bool damaging=comboQaIndex<=5;
        bool triggered=comboQaOwner.comboActivations>comboQaStartActivations&&
                       (!damaging||comboQaOwner.comboBonusDamage>comboQaStartDamage);
        if(triggered)
        {
            CombatContributionEntry recorded=BuildLiveCombatContribution().allies
                .FirstOrDefault(entry=>entry.stableId==comboQaOwner.stableId);
            bool recordMatches=recorded!=null&&
                recorded.comboActivations==comboQaOwner.comboActivations&&
                Mathf.Approximately(recorded.comboBonusDamage,
                    comboQaOwner.comboBonusDamage);
            if(recordMatches)
            {
                comboQaPassed++;
                Debug.Log("[Combo QA] PASS "+
                    MonsterTraitRuntime.ComboShortName(ComboQaTraitIds[comboQaIndex])+
                    " / +"+(comboQaOwner.comboBonusDamage-comboQaStartDamage).ToString("0.0"));
            }
            else Debug.LogError("[Combo QA] FAIL 기록 불일치: "+ComboQaTraitIds[comboQaIndex]);
            comboQaIndex++;
            if(comboQaIndex>=ComboQaTraitIds.Length)
            {
                StopComboQa(comboQaPassed+"/8 통과",true);
                return;
            }
            PrepareComboQaScenario();
            return;
        }
        if(comboQaTimer<12f)return;
        Debug.LogError("[Combo QA] TIMEOUT "+ComboQaTraitIds[comboQaIndex]+
            " / action="+comboQaOwner.currentAction+
            " skill="+comboQaOwner.skillTimer.ToString("0.00")+
            " distance="+Vector3.Distance(
                Flat(comboQaOwner.model.transform.position),
                Flat(comboQaTarget.model.transform.position)).ToString("0.00"));
        comboQaIndex++;
        if(comboQaIndex>=ComboQaTraitIds.Length)
        {
            StopComboQa(comboQaPassed+"/8 통과",true);
            return;
        }
        PrepareComboQaScenario();
    }

    private void StopComboQa(string result,bool resetBattle)
    {
        comboQaRunning=false;
        Time.timeScale=comboQaOriginalTimeScale;
        comboQaMessage=result;
        Debug.Log("[Combo QA] 완료: "+result);
        comboQaOwner=null;
        comboQaProvider=null;
        comboQaTarget=null;
        if(resetBattle)PrepareNextWave(false);
    }

    private void StartRosterQaRun()
    {
        if(battleStarted||battleEnding||RosterQaPageCount(monsterDatabase)==0)
            return;
        rosterQaRunning=true;
        rosterQaPage=0;
        ApplyRosterQaPage(rosterQaPage,true);
    }

    private void ApplyRosterQaPage(int page,bool startBattle)
    {
        if(battleStarted||battleEnding||expeditionRun==null)return;
        List<MonsterDefinition> batch=RosterQaBatch(monsterDatabase,page);
        if(batch.Count==0)return;
        int pageCount=RosterQaPageCount(monsterDatabase);
        rosterQaPage=((page%pageCount)+pageCount)%pageCount;
        rosterQaMode=true;
        rosterQaWaitingForRestart=false;
        resultText="";
        pendingResult="";
        SetAdditionalDeploymentSlots(
            ExpeditionDeploymentSystem.MaximumLimit-BaseDeploymentLimit);

        List<Unit> players=units.Where(unit=>unit.team==Team.Player).ToList();
        for(int i=0;i<players.Count;i++)RemoveUnitFromRoster(players[i]);
        expeditionRun.monsters.Clear();
        expeditionRun.itemInstances.Clear();
        expeditionRun.inventoryItemInstanceIds.Clear();
        expeditionRun.growthCards.Clear();
        expeditionRun.augments.Clear();
        expeditionRun.specialItems.Clear();
        expeditionRun.wave=Mathf.Clamp(balanceTestWave,1,ExpeditionWaveCount);
        expeditionRun.lives=StartingExpeditionLives;
        expeditionRun.maximumLives=StartingExpeditionLives;
        expeditionFailed=false;

        List<string> deployed=new List<string>();
        for(int i=0;i<batch.Count;i++)
        {
            MonsterDefinition definition=batch[i];
            string instanceId="roster_qa_"+definition.serialNumber;
            OwnedMonsterSave owned=PlayerProfileStore.CreateMonster(
                definition,instanceId,false);
            owned.hpMultiplier=1f;
            owned.damageMultiplier=1f;
            owned.attackSpeedMultiplier=1f;
            owned.defenseMultiplier=1f;
            owned.statusResistanceMultiplier=1f;
            owned.moveSpeedMultiplier=1f;
            expeditionRun.monsters.Add(new ExpeditionMonsterStateSave
            {
                instanceId=instanceId,
                monsterId=definition.monsterId,
                rank=ExpeditionMonsterRank.Rank1,
                itemInstanceIds=new List<string>{"","",""},
                temporary=true
            });
            SpawnUnit(definition,Team.Player,BenchCoordinate(i),owned,true);
            deployed.Add(instanceId);
        }

        PrepareNextWave(true);
        SuppressSimulationIntermissions();
        ArrangePlayerFormationForNewWave(deployed);
        rosterQaMessage=batch.First().serialNumber+"-"+
            batch.Last().serialNumber+" loaded";
        Debug.Log("[Roster QA] "+rosterQaMessage+": "+
            string.Join(", ",batch.Select(definition=>definition.displayName)));
        if(startBattle)StartCurrentBattle();
    }

    private void CompleteRosterQaBattle(bool won)
    {
        rosterQaMessage=RosterQaBatch(monsterDatabase,rosterQaPage).First().serialNumber+
            " page "+(won?"WIN":"LOSS");
        Debug.Log("[Roster QA] "+rosterQaMessage+
            " / time "+battleElapsed.ToString("0.0")+"s");
        resultText="";
        pendingResult="";
        if(!rosterQaRunning)return;
        rosterQaPage++;
        if(rosterQaPage>=RosterQaPageCount(monsterDatabase))
        {
            rosterQaRunning=false;
            rosterQaMessage="001-080 complete";
            resultText="ROSTER QA COMPLETE";
            return;
        }
        rosterQaWaitingForRestart=true;
        rosterQaRestartTimer=1f;
    }

    private void UpdateRosterQa()
    {
        if(!rosterQaRunning||!rosterQaWaitingForRestart)return;
        rosterQaRestartTimer-=Time.unscaledDeltaTime;
        if(rosterQaRestartTimer>0f)return;
        rosterQaWaitingForRestart=false;
        ApplyRosterQaPage(rosterQaPage,true);
    }

    private void ApplyBalanceWavePreset(int wave)
    {
        if(battleStarted||battleEnding)return;
        balanceTestWave=Mathf.Clamp(wave,1,ExpeditionWaveCount);
        expeditionRun.wave=balanceTestWave;
        expeditionRun.lives=StartingExpeditionLives;
        expeditionFailed=false;
        growthCardDraft.Clear();
        AutoBattleHeuristicPolicy.ApplyGrowthShopProgression(
            expeditionRun,balanceTestWave,balanceTestBaseSeed);
        PrepareNextWave(true);
    }

    private void StartBalanceTest(bool allWaves,bool allRegions)
    {
        if(battleStarted||battleEnding)return;
        balanceTestOriginalRegionId=expeditionRun.regionId;
        balanceTestOriginalDifficulty=expeditionRun.difficulty;
        balanceTestAllRegions=allRegions;
        balanceTestAllWaves=allWaves||allRegions;
        balanceTestProductionRules=true;
        PrepareBalanceSimulationRoster();
        if(balanceTestAllRegions)
        {
            expeditionRun.regionId=HunterRegionCatalog.All[0].id;
            expeditionRun.difficulty=ExpeditionDifficulty.Beginner;
        }
        if(balanceTestAllWaves)balanceTestWave=1;
        ApplyBalanceWavePreset(balanceTestWave);
        balanceTestOriginalRunId=expeditionRun.runId;
        balanceStatistics.Reset();
        balanceReportPaths="";
        CreateBalanceReport();
        balanceTestRunning=true;
        balanceTestWaitingForRestart=false;
        if(mainCamera!=null)
        {
            balanceTestOriginalCullingMask=mainCamera.cullingMask;
            mainCamera.cullingMask=0;
        }
        balanceTestOriginalCaptureDeltaTime=Time.captureDeltaTime;
        Time.captureDeltaTime=1f/60f;
        Time.timeScale=BalanceTestTimeScale;
        BeginBalanceTestTrial(0);
    }

    private void PrepareBalanceSimulationRoster()
    {
        if(!CombatEffectTestConfiguration.Active)return;

        List<Unit> players=units.Where(unit=>unit.team==Team.Player).ToList();
        for(int i=0;i<players.Count;i++)RemoveUnitFromRoster(players[i]);
        expeditionRun.monsters.Clear();
        expeditionRun.itemInstances.Clear();
        expeditionRun.inventoryItemInstanceIds.Clear();
        expeditionRun.growthCards.Clear();
        expeditionRun.augments.Clear();
        expeditionRun.specialItems.Clear();
        SetAdditionalDeploymentSlots(0);

        string[] starterIds=
        {
            "velos","geomchi","golgaebi","ager",
            "kongjwi","woongi","aranea","holydeer"
        };
        for(int i=0;i<starterIds.Length;i++)
        {
            MonsterDefinition definition=RequireMonsterDefinition(starterIds[i]);
            string instanceId="balance_starter_"+definition.monsterId;
            OwnedMonsterSave owned=PlayerProfileStore.CreateMonster(
                definition,instanceId,false);
            expeditionRun.monsters.Add(new ExpeditionMonsterStateSave
            {
                instanceId=instanceId,
                monsterId=definition.monsterId,
                rank=ExpeditionMonsterRank.Rank1,
                itemInstanceIds=new List<string>{"","",""}
            });
            SpawnUnit(definition,Team.Player,BenchCoordinate(i),owned,true);
        }
    }

    private void CompleteBalanceTestTrial(bool won)
    {
        RecordBalanceTrial(won);
        balanceStatistics.Record(won,battleElapsed,playerDeathsThisWave);
        resultText="";
        pendingResult="";
        if(balanceStatistics.CompletedRuns>=balanceTestTargetRuns)
        {
            if(balanceTestAllWaves&&balanceTestWave<ExpeditionWaveCount)
            {
                WriteBalanceReport();
                balanceTestWave++;
                PrepareNextBalanceScenario();
                return;
            }
            if(balanceTestAllRegions)
            {
                IReadOnlyList<HunterRegionDefinition> regions=HunterRegionCatalog.All;
                int regionIndex=regions.ToList().FindIndex(region=>
                    string.Equals(region.id,expeditionRun.regionId,StringComparison.Ordinal));
                if(regionIndex>=0&&regionIndex<regions.Count-1)
                {
                    WriteBalanceReport();
                    expeditionRun.regionId=regions[regionIndex+1].id;
                    expeditionRun.difficulty=ExpeditionDifficulty.Beginner;
                    balanceTestWave=1;
                    PrepareNextBalanceScenario();
                    return;
                }
            }
            StopBalanceTest(true);
            PrepareNextWave(false);
            return;
        }
        balanceTestWaitingForRestart=true;
        balanceTestRestartTimer=0.2f;
    }

    private void UpdateBalanceTest()
    {
        if(!balanceTestRunning||!balanceTestWaitingForRestart)return;
        balanceTestRestartTimer-=Time.unscaledDeltaTime;
        if(balanceTestRestartTimer>0f)return;
        balanceTestWaitingForRestart=false;
        BeginBalanceTestTrial(balanceStatistics.CompletedRuns);
    }

    private void StopBalanceTest(bool writeReport=true)
    {
        if(writeReport)WriteBalanceReport();
        balanceTestRunning=false;
        balanceTestWaitingForRestart=false;
        balanceTestAllWaves=false;
        balanceTestAllRegions=false;
        if(!string.IsNullOrEmpty(balanceTestOriginalRegionId))
        {
            expeditionRun.regionId=balanceTestOriginalRegionId;
            expeditionRun.difficulty=balanceTestOriginalDifficulty;
            balanceTestOriginalRegionId="";
        }
        if(!string.IsNullOrEmpty(balanceTestOriginalRunId))
        {
            expeditionRun.runId=balanceTestOriginalRunId;
            balanceTestOriginalRunId="";
        }
        if(mainCamera!=null&&balanceTestOriginalCullingMask>=0)
            mainCamera.cullingMask=balanceTestOriginalCullingMask;
        balanceTestOriginalCullingMask=-1;
        Time.captureDeltaTime=balanceTestOriginalCaptureDeltaTime;
        balanceTestOriginalCaptureDeltaTime=0f;
        Time.timeScale=1f;
        balanceTestProductionRules=false;
    }

    private void PrepareNextBalanceScenario()
    {
        expeditionRun.wave=balanceTestWave;
        AutoBattleHeuristicPolicy.ApplyGrowthShopProgression(
            expeditionRun,balanceTestWave,balanceTestBaseSeed);
        balanceStatistics.Reset();
        CreateBalanceReport();
        balanceTestWaitingForRestart=true;
        balanceTestRestartTimer=0.2f;
    }

    private void CreateBalanceReport()
    {
        balanceReport=new AutoBattleBalanceReport
        {
            baseSeed=balanceTestBaseSeed,wave=balanceTestWave,
            requestedRuns=balanceTestTargetRuns,
            regionId=expeditionRun.regionId,
            difficulty=expeditionRun.difficulty.ToString(),
            rosterSignature=string.Join("|",units.Where(unit=>unit.team==Team.Player)
                .Select(unit=>unit.definition.monsterId).OrderBy(id=>id,StringComparer.Ordinal))
        };
    }

    private void WriteBalanceReport()
    {
        if(balanceReport==null||balanceReport.trials.Count==0)return;
        string paths=AutoBattleBalanceReportWriter.Write(balanceReport);
        balanceReportPaths=string.IsNullOrEmpty(balanceReportPaths)
            ?paths:balanceReportPaths+"|"+paths;
        Debug.Log("[Balance Simulation] CSV/JSON report saved: "+paths);
    }

    private void BeginBalanceTestTrial(int runIndex)
    {
        balanceTestTrialTimedOut=false;
        expeditionRun.lives=StartingExpeditionLives;
        expeditionFailed=false;
        balanceTestCurrentSeed=unchecked(balanceTestBaseSeed+runIndex*7919);
        UnityEngine.Random.InitState(balanceTestCurrentSeed);
        expeditionRun.runId="balance_seed_"+balanceTestBaseSeed+"_wave_"+
                         balanceTestWave+"_trial_"+runIndex;
        PrepareNextWave(true);
        SuppressSimulationIntermissions();
        ApplyBalanceHeuristicFormation(balanceTestCurrentSeed);
        StartCurrentBattle();
    }

    private void ApplyBalanceHeuristicFormation(int seed)
    {
        List<Unit> players=BattleReadyUnits();
        List<AutoBattleFormationCandidate> candidates=players.Select(unit=>
        {
            ExpeditionMonsterStateSave state=
                ExpeditionItemSystem.MonsterState(expeditionRun,unit.stableId);
            return new AutoBattleFormationCandidate
            {
                stableId=unit.stableId,maxHp=unit.maxHp,damage=unit.damage,
                attackInterval=unit.attackInterval,attackRange=unit.attackRange,
                rank=(int)(state==null?ExpeditionMonsterRank.Rank1:state.rank),
                traitCount=unit.activeTraitIds.Count
            };
        }).ToList();
        List<string> selected=AutoBattleHeuristicPolicy.SelectDeployment(
            candidates,MaxDeploymentCount,seed);
        ArrangePlayerFormationForNewWave(selected);

        List<Unit> deployed=players.Where(unit=>!unit.inStorage).ToList();
        for(int i=0;i<deployed.Count;i++)ReleaseUnitOccupancy(deployed[i]);
        List<Vector2Int> available=PlayerDeploymentCoordinates();
        int minimumColumn=available.Count==0?ActivePlayerDeployStartColumn:available.Min(tile=>tile.x);
        int maximumColumn=available.Count==0?ActivePlayerDeployStartColumn:available.Max(tile=>tile.x);
        deployed=deployed.OrderBy(unit=>unit.attackRange).ThenBy(unit=>unit.stableId,StringComparer.Ordinal).ToList();
        for(int i=0;i<deployed.Count;i++)
        {
            Unit unit=deployed[i];
            int preferredColumn=AutoBattleHeuristicPolicy.PreferredDeploymentRow(
                unit.attackRange,minimumColumn,maximumColumn);
            Vector2Int destination=available
                .Where(tile=>CanPlaceUnit(unit,tile,true))
                .OrderBy(tile=>Mathf.Abs(tile.x-preferredColumn))
                .ThenBy(tile=>Mathf.Abs(tile.y-(ActiveRows-1)*0.5f))
                .ThenBy(tile=>tile.y).FirstOrDefault();
            if(!CanPlaceUnit(unit,destination,true))continue;
            OccupyUnit(unit,destination);
            unit.initialTile=destination;
            ApplyDeploymentTransform(unit);
        }
    }

    private void RecordBalanceTrial(bool won)
    {
        if(balanceReport==null)return;
        int runIndex=balanceReport.trials.Count;
        List<Unit> deployedPlayers=units.Where(unit=>unit.team==Team.Player&&!unit.inStorage).ToList();
        int playerSurvivors=deployedPlayers.Count(IsCombatActive);
        int enemySurvivors=units.Count(unit=>unit.team==Team.Enemy&&IsCombatActive(unit));
        float survivingHpRatio=deployedPlayers.Count==0?0f:
            deployedPlayers.Sum(unit=>Mathf.Clamp01(unit.hp/Mathf.Max(1f,unit.maxHp)))/deployedPlayers.Count;
        balanceReport.trials.Add(new AutoBattleBalanceTrialRecord
        {
            runIndex=runIndex,wave=balanceTestWave,seed=balanceTestCurrentSeed,won=won,
            battleSeconds=battleElapsed,playerDeaths=playerDeathsThisWave,
            playerSurvivors=playerSurvivors,enemySurvivors=enemySurvivors,
            survivingPlayerHpRatio=survivingHpRatio,
            timedOut=balanceTestTrialTimedOut
        });
        for(int i=0;i<units.Count;i++)
        {
            Unit unit=units[i];
            bool deployed=unit.team==Team.Enemy||!unit.inStorage;
            bool unitWon=unit.team==Team.Player?won:!won;
            balanceReport.units.Add(new AutoBattleBalanceUnitRecord
            {
                runIndex=runIndex,wave=balanceTestWave,seed=balanceTestCurrentSeed,
                monsterId=unit.definition.monsterId,displayName=unit.definition.displayName,
                team=unit.team.ToString(),deployed=deployed,survived=deployed&&unit.alive,
                won=unitWon,attackRange=unit.attackRange,damageDealt=unit.damageDealt,
                damageTaken=unit.damageTaken,skillDamage=unit.skillDamage,
                preventedDamage=unit.preventedDamage,skillUses=unit.skillUses,
                skillHits=unit.skillHits,kills=unit.kills,
                traitActivations=unit.traitActivations
            });
        }
    }

    private void ResolveSimulationTimeout()
    {
        List<Unit> players=units.Where(unit=>unit.team==Team.Player&&!unit.inStorage).ToList();
        List<Unit> enemies=units.Where(unit=>unit.team==Team.Enemy).ToList();
        float playerMaximum=players.Sum(unit=>Mathf.Max(1f,unit.maxHp));
        float enemyMaximum=enemies.Sum(unit=>Mathf.Max(1f,unit.maxHp));
        float playerRatio=playerMaximum<=0f?0f:
            players.Sum(unit=>Mathf.Max(0f,unit.hp))/playerMaximum;
        float enemyRatio=enemyMaximum<=0f?0f:
            enemies.Sum(unit=>Mathf.Max(0f,unit.hp))/enemyMaximum;
        bool playerWon=playerRatio>enemyRatio;
        balanceTestTrialTimedOut=balanceTestRunning;
        Debug.LogWarning("[Simulation Watchdog] Wave "+expeditionRun.wave+
            " seed "+balanceTestCurrentSeed+" reached "+SimulationBattleTimeout+
            "s. Resolved by remaining HP ratio: player="+
            playerRatio.ToString("0.000")+", enemy="+enemyRatio.ToString("0.000"));
        ClearSpiderWebZones();
        ClearSpiritGuardSanctuaries();
        ClearSpiritConcertEchoes();
        ClearMammothBoulders();
        ClearMushroomGasZones();
        ClearMushroomCrowns();
        pendingResult=playerWon?"아군 승리":"적군 승리";
        battleEnding=true;
        FinalizeWaveOutcome();
    }
