    private void EquipInventoryItem(Unit target,string itemInstanceId)
    {
        if(target==null)return;
        ExpeditionMonsterStateSave state=ExpeditionItemSystem.MonsterState(expeditionRun,target.stableId);
        int slot=state==null?-1:state.itemInstanceIds.FindIndex(string.IsNullOrEmpty);
        if(slot<0){itemUiMessage="빈 슬롯이 없습니다. 먼저 아이템을 해제하세요.";return;}
        if(!ExpeditionItemSystem.Equip(
            expeditionRun,target.stableId,itemInstanceId,slot,out itemUiMessage))return;
        RefreshUnitFromOwnedData(target,target.definition,target.ownedInstance);
        RemoveMissingFusionSelections();
        itemUiMessage="슬롯 "+(slot+1)+"에 장착했습니다.";
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,true);
    }

    private void UnequipItemFromSelectedMonster(Unit target,int slot)
    {
        if(!ExpeditionItemSystem.Unequip(
            expeditionRun,target.stableId,slot,out itemUiMessage))return;
        RefreshUnitFromOwnedData(target,target.definition,target.ownedInstance);
        itemUiMessage="아이템을 인벤토리로 옮겼습니다.";
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,true);
    }

    private void SelectFusionIngredient(string itemInstanceId)
    {
        ExpeditionItemInstanceSave instance=ExpeditionItemSystem.ItemInstance(expeditionRun,itemInstanceId);
        ItemMasterRow item=instance==null?null:GameMasterData.Item(instance.itemId);
        if(item==null||!item.IsBase){itemUiMessage="기본 아이템만 조합 재료로 선택할 수 있습니다.";return;}
        if(firstFusionItemInstanceId==itemInstanceId)
        {
            firstFusionItemInstanceId="";itemUiMessage="첫 재료 선택을 해제했습니다.";return;
        }
        if(secondFusionItemInstanceId==itemInstanceId)
        {
            secondFusionItemInstanceId="";itemUiMessage="두 번째 재료 선택을 해제했습니다.";return;
        }
        if(string.IsNullOrEmpty(firstFusionItemInstanceId))firstFusionItemInstanceId=itemInstanceId;
        else secondFusionItemInstanceId=itemInstanceId;
        itemUiMessage="조합 결과를 미리 확인하세요.";
    }

    private void FuseSelectedItems()
    {
        if(!ExpeditionItemSystem.TryFuse(expeditionRun,
            firstFusionItemInstanceId,secondFusionItemInstanceId,
            out ExpeditionItemInstanceSave result,out itemUiMessage))return;
        ClearFusionSelection();
        ItemMasterRow resultMaster=GameMasterData.Item(result.itemId);
        itemUiMessage=(resultMaster==null?result.itemId:resultMaster.displayName)+" 조합 완료";
        RefreshAllPlayerItemStats();
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,true);
    }

    private void RefreshAllPlayerItemStats()
    {
        foreach(Unit unit in units)
            if(unit.team==Team.Player&&unit.ownedInstance!=null)
                RefreshUnitFromOwnedData(unit,unit.definition,unit.ownedInstance);
    }

    private void ClearFusionSelection()
    {
        firstFusionItemInstanceId="";secondFusionItemInstanceId="";
    }

    private void RemoveMissingFusionSelections()
    {
        if(ExpeditionItemSystem.ItemInstance(expeditionRun,firstFusionItemInstanceId)==null)
            firstFusionItemInstanceId="";
        if(ExpeditionItemSystem.ItemInstance(expeditionRun,secondFusionItemInstanceId)==null)
            secondFusionItemInstanceId="";
    }

    private void GrantDebugBasicItems()
    {
        foreach(ItemMasterRow item in GameMasterData.ItemsInPool("default_equipment"))
            ExpeditionItemSystem.CreateItem(expeditionRun,item.id);
        itemUiMessage="개발 확인용 기본 아이템 6종을 지급했습니다.";
    }

    private static string ItemKindName(ItemMasterRow item)
    {
        return item.IsBase?"기본":"완성";
    }

    private static string CompactItemStats(ItemMasterRow item)
    {
        List<string> values=new List<string>();
        if(item.attackDamageBonus!=0f)values.Add("공격 "+SignedPercent(item.attackDamageBonus));
        if(item.attackSpeedBonus!=0f)values.Add("공속 "+SignedPercent(item.attackSpeedBonus));
        if(item.maxHealthBonus!=0f)values.Add("체력 "+SignedPercent(item.maxHealthBonus));
        if(item.damageReductionBonus!=0f)values.Add("피감 "+SignedPercent(item.damageReductionBonus));
        if(item.criticalChance!=0f)values.Add("치명 "+SignedPercent(item.criticalChance));
        if(item.skillPowerBonus!=0f)values.Add("스킬 "+SignedPercent(item.skillPowerBonus));
        if(item.defenseBonus!=0f)values.Add("방어 +"+item.defenseBonus.ToString("0"));
        if(item.statusResistanceBonus!=0f)values.Add("저항 +"+item.statusResistanceBonus.ToString("0"));
        if(item.skillCooldownReductionBonus!=0f)values.Add("재사용 속도 "+SignedPercent(item.skillCooldownReductionBonus));
        return values.Count==0?"특수 효과":string.Join(", ",values);
    }

    private static string SignedPercent(float value)
    {
        return (value>=0f?"+":"")+(value*100f).ToString("0")+"%";
    }

