    private static void AddDebugTraitOverride(Unit unit,string traitId)
    {
        if(string.IsNullOrWhiteSpace(traitId)||
           !MonsterTraitCatalog.IsCompatible(traitId,unit.definition)||
           unit.activeTraitIds.Contains(traitId))return;
        unit.activeTraitIds.Add(traitId);
