    private bool IsPointerOverItemUi()
    {
        if(resultText.Length>0)return false;
        Vector2 point=BombBrickUiLayout.ScreenToGuiPoint(Input.mousePosition);
        return IsPointerOverItemUiAt(point);
    }

    private bool IsPointerOverItemUiAt(Vector2 point)
    {
        if(CombatEffectTestSceneController.PointerOverControls(point*BombBrickUiLayout.Scale))return true;
        if(GameFrontend.PointerOverMenu(point*BombBrickUiLayout.Scale))return true;
        if(inspectedUnit!=null&&OwnedMonsterDetailsRect.Contains(point))return true;
        if(battleStarted)return false;
#if UNITY_EDITOR
        if(traitTestPanelVisible&&TraitTestPanelRect.Contains(point))return true;
#endif
        if(ItemBarRect.Contains(point))return true;
        if(CanOpenGrowthShop&&
           (GrowthShopButtonRect.Contains(point)||
            GrowthShopTabRect.Contains(point)))return true;
        if(!string.IsNullOrEmpty(InventoryItemAt(
            point,BuildInventoryItemStacks(),"")))return true;
        if(CaptureNetBarRect.Contains(point))return true;
        if(IsPointerOverSpecialItemIcon(point))return true;
        return false;
    }

    private bool IsPointerOverSpecialItemIcon(Vector2 point)
    {
        if(expeditionRun==null||expeditionRun.specialItems==null)return false;
        List<ExpeditionSpecialItemSave> items=expeditionRun.specialItems
            .Where(value=>value!=null&&value.count>0).ToList();
        Rect bar=SpecialItemBarRect;
        const int columns=8;
        const float iconSize=52f;
        for(int i=0;i<items.Count;i++)
        {
            int column=i%columns;
            int row=i/columns;
            Rect button=new Rect(
                bar.x+104f+column*(iconSize+6f),
                bar.y+8f+row*(iconSize+6f),iconSize,iconSize);
            if(button.Contains(point))return true;
        }
        return false;
    }

    private void DrawSpecialItemBar(Event current)
    {
        if(expeditionRun.specialItems==null||expeditionRun.specialItems.Count==0)return;
        Rect bar=SpecialItemBarRect;
        BombBrickUiTheme.DrawPanel(bar,true);
        BombBrickUiTheme.Fill(new Rect(bar.x,bar.y,4f,bar.height),
            BombBrickUiTheme.Violet);
        GUI.Label(new Rect(bar.x+14f,bar.y+10f,84f,22f),
            "특수 도구",BombBrickUiTheme.TitleStyle(13));
        GUI.Label(new Rect(bar.x+14f,bar.y+34f,84f,18f),
            "사용 시 소모",BombBrickUiTheme.CaptionStyle(9));
        List<ExpeditionSpecialItemSave> items=expeditionRun.specialItems
            .Where(value=>value!=null&&value.count>0).ToList();
        const int columns=8;
        const float iconSize=52f;
        for(int i=0;i<items.Count;i++)
        {
            ExpeditionSpecialItemSave item=items[i];
            int column=i%columns;
            int row=i/columns;
            Rect button=new Rect(
                bar.x+104f+column*(iconSize+6f),
                bar.y+8f+row*(iconSize+6f),iconSize,iconSize);
            DrawSpecialItemIcon(button,item.itemId,item.count,
                !string.IsNullOrEmpty(item.boundMonsterInstanceId));
            if(draggingSpecialItem&&
               item.instanceId==draggedSpecialItemInstanceId)
            {
                BombBrickUiTheme.Fill(button,
                    new Color(0.01f,0.015f,0.025f,0.76f));
                BombBrickUiTheme.Frame(button,BombBrickUiTheme.Violet,2f);
            }
            if(current.type==EventType.MouseDown&&current.button==0&&
               button.Contains(current.mousePosition))
            {
                draggedSpecialItemInstanceId=item.instanceId;
                draggingSpecialItem=true;
                draggedItemInstanceId="";
                draggingItem=false;
                current.Use();
            }
        }
        if(draggingSpecialItem&&!string.IsNullOrEmpty(draggedSpecialItemInstanceId))
        {
            Vector2 mouse=current.mousePosition;
            if(current.type==EventType.MouseUp&&current.button==0)
            {
                CompleteSpecialItemDrop(mouse);
                current.Use();
            }
        }
    }

    private void DrawSpecialItemIcon(
        Rect rect,string itemId,int count,bool bound)
    {
        bool hovered=rect.Contains(Event.current.mousePosition);
        Color accent=BombBrickUiTheme.Violet;
        BombBrickUiTheme.Fill(rect,hovered?BombBrickUiTheme.SurfaceHover:
            BombBrickUiTheme.Surface);
        BombBrickUiTheme.Frame(rect,hovered?Color.Lerp(accent,Color.white,0.22f):
            new Color(accent.r,accent.g,accent.b,0.78f),hovered?2f:1f);
        if(!specialItemIconCache.TryGetValue(itemId,out Texture2D icon))
        {
            icon=Resources.Load<Texture2D>("UI/SpecialItemIcons/"+itemId);
            specialItemIconCache[itemId]=icon;
        }
        Rect imageRect=new Rect(rect.x+3f,rect.y+3f,rect.width-6f,rect.height-6f);
        if(icon!=null)GUI.DrawTexture(imageRect,icon,ScaleMode.ScaleToFit,false);
        if(count>1)
            BombBrickUiTheme.Badge(new Rect(rect.xMax-25f,rect.y-3f,26f,19f),
                "×"+count,accent);
        if(bound)
            BombBrickUiTheme.Fill(new Rect(rect.x+5f,rect.y+5f,7f,7f),
                BombBrickUiTheme.Lime);
        if(hovered)hoveredSpecialItemTooltipId=itemId;
    }

    private void DrawSpecialItemTooltip()
