        if(string.IsNullOrEmpty(hoveredSpecialItemTooltipId))return;
        string itemId=hoveredSpecialItemTooltipId;
        string title=SpecialItemName(itemId);
        string description=SpecialItemDescription(itemId);
        float width=310f;
        float height=118f;
        Vector2 pointer=Event.current.mousePosition;
        Rect panel=BombBrickUiLayout.PlacePopup(
            pointer,new Vector2(width,height),UiLayout.safeArea,18f);
