        BombBrickUiTheme.Fill(new Rect(panel.x,panel.y,4f,panel.height),accent);
        GUI.Label(new Rect(panel.x+16f,panel.y+14f,panel.width-32f,26f),
            title,BombBrickUiTheme.TitleStyle(18));
        BombBrickUiTheme.Fill(new Rect(panel.x+16f,panel.y+48f,panel.width-32f,1f),
            BombBrickUiTheme.Border);
        GUI.Label(new Rect(panel.x+16f,panel.y+58f,panel.width-32f,48f),
            description,BombBrickUiTheme.BodyStyle(12));
    }

    private static string SpecialItemDescription(string itemId)
    {
        return GameLocalization.Text(SpecialItemDescriptionKorean(itemId));
    }

    private static string SpecialItemDescriptionKorean(string itemId)
    {
        switch(itemId)
        {
            case "special_combined_cast_core":
                return "몬스터에게 적용하면 합동 시전의 중심 개체로 영구 지정됩니다.";
            case "special_return_mark":
                return "몬스터에게 적용하면 회귀 표식 효과가 영구 적용됩니다.";
            case "special_corruption_catalyst":
                return "완성 아이템을 타락시킵니다. 15% 대성공, 70% 강화, 15% 약화.";
            case "special_trait_recombobulator":
                return "성장 특성은 종별로 고정되어 재조합할 수 없습니다.";
            case "special_golden_dismantler":
                return "완성 아이템을 두 개의 기본 재료로 분해합니다.";
            default:
                return "탐험 준비 단계에서 드래그하여 사용하는 특수 아이템입니다.";
        }
    }

    private void CompleteSpecialItemDrop(Vector2 mouse)
    {
        ExpeditionSpecialItemSave special=expeditionRun.specialItems.FirstOrDefault(
            value=>value!=null&&value.instanceId==draggedSpecialItemInstanceId);
        draggedSpecialItemInstanceId="";
        draggingSpecialItem=false;
        if(special==null)return;

        Unit monster=PlayerUnitAtGuiPoint(mouse);
        if(special.itemId=="special_combined_cast_core")
        {
            if(monster==null)
            {
                itemUiMessage="몬스터 위에 드롭해야 합니다.";
                return;
            }
            if(!ExpeditionAugmentRuntime.TryApplyPermanentMonsterSpecialItem(
                expeditionRun,special.instanceId,monster.stableId,out itemUiMessage))
                return;
            itemUiMessage=monster.displayName+"에게 "+SpecialItemName(
                special.itemId)+" 영구 적용";
            ShowItemActionFeedback(itemUiMessage);
            RefreshAllPlayerItemStats();
            SaveExpeditionCheckpoint(
                ExpeditionRunCheckpoint.Preparation,true);
            return;
        }

        if(special.itemId=="special_trait_recombobulator")
        {
            if(monster==null||!TryRecombineTrait(monster,out itemUiMessage))return;
            ExpeditionAugmentRuntime.TryConsumeSpecialItemInstance(
                expeditionRun,special.instanceId,out _);
            ShowItemActionFeedback(itemUiMessage);
            SaveExpeditionCheckpoint(
                ExpeditionRunCheckpoint.Preparation,true);
            return;
        }

        List<KeyValuePair<string,List<string>>> stacks=BuildInventoryItemStacks();
        string itemInstanceId=ItemInstanceAtGuiPoint(mouse,stacks);
        if(string.IsNullOrEmpty(itemInstanceId))
        {
            itemUiMessage="완성 아이템 위에 드롭해야 합니다.";
            return;
        }

        bool applied=false;
        if(special.itemId=="special_corruption_catalyst")
        {
            augmentDraftSequence++;
            int seed=MonsterInstanceGenerator.StableSeed(
                expeditionRun.runId+"_corruption_"+augmentDraftSequence+"_"+itemInstanceId);
            applied=ExpeditionItemTransformSystem.TryApplyCorruption(
                expeditionRun,itemInstanceId,seed,out CorruptionRollOutcome outcome,
                out itemUiMessage);
            if(applied)itemUiMessage="타락 결과: "+CorruptionOutcomeName(outcome);
        }
        else if(special.itemId=="special_golden_dismantler")
        {
            applied=ExpeditionItemSystem.TryDismantle(
                expeditionRun,itemInstanceId,out _,out _,out itemUiMessage);
            if(applied)itemUiMessage="완성 아이템을 원래 재료로 분해했습니다.";
        }
        if(!applied)return;
        ExpeditionAugmentRuntime.TryConsumeSpecialItemInstance(
            expeditionRun,special.instanceId,out _);
        ShowItemActionFeedback(itemUiMessage);
        RefreshAllPlayerItemStats();
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,true);
    }

    private string ItemInstanceAtGuiPoint(
        Vector2 mouse,List<KeyValuePair<string,List<string>>> stacks)
    {
        Unit selected=inspectedUnit!=null&&inspectedUnit.team==Team.Player
            ?inspectedUnit:null;
        if(selected!=null)
        {
            ExpeditionMonsterStateSave state=ExpeditionItemSystem.MonsterState(
                expeditionRun,selected.stableId);
            Rect row=SelectedUnitSlotRowRect(selected);
            for(int slot=0;slot<ExpeditionItemSystem.MaxSlots;slot++)
                if(new Rect(row.x+slot*58f,row.y,52f,48f).Contains(mouse))
                    return state==null?"":state.itemInstanceIds[slot];
        }
        return InventoryItemAt(mouse,stacks,"");
    }

    private bool TryRecombineTrait(Unit target,out string message)
    {
        message="성장 특성은 종별로 고정되어 재조합할 수 없습니다.";
        return false;
    }

    private static string SpecialItemName(string itemId)
    {
        if(itemId=="special_combined_cast_core")return "합동 시전 코어";
        if(itemId=="special_return_mark")return "회귀 표식";
        if(itemId=="special_corruption_catalyst")return "타락 촉매";
        if(itemId=="special_trait_recombobulator")return "변이 재조합기";
        if(itemId=="special_golden_dismantler")return "황금 분해기";
        return itemId;
    }

    private static string CorruptionOutcomeName(CorruptionRollOutcome outcome)
    {
        if(outcome==CorruptionRollOutcome.GreatSuccess)return "대성공";
        if(outcome==CorruptionRollOutcome.Success)return "강화";
        if(outcome==CorruptionRollOutcome.Failure)return "약화";
        return "변화 없음";
    }

    private void DrawExpeditionItemBar()
    {
        Event current=Event.current;
        if(!FirstItemGuideVisible)DrawSpecialItemBar(current);
        Rect bar=ItemBarRect;
        BombBrickUiTheme.DrawPanel(bar,true);
        BombBrickUiTheme.Fill(new Rect(bar.x,bar.y,4f,bar.height),
            BombBrickUiTheme.Cyan);
        DrawSystemIcon(new Rect(bar.x+14f,bar.y+14f,30f,30f),
            "shop",BombBrickUiTheme.Cyan,false);
        GUI.Label(new Rect(bar.x+52f,bar.y+10f,164f,26f),
            "탐험 가방",BombBrickUiTheme.TitleStyle(13));
        GUI.Label(new Rect(bar.x+52f,bar.y+38f,164f,26f),
            "장착 · 합성",BombBrickUiTheme.CaptionStyle(
                9,TextAnchor.UpperLeft));
        float pandoraProgress=current.type==EventType.Repaint
            ?DrawPandoraBagFeedback(bar):1f;
        List<KeyValuePair<string,List<string>>> stacks=BuildInventoryItemStacks();
        float iconWidth=74f;
        Rect viewport=ItemInventoryViewportRect;
        float contentWidth=Mathf.Max(viewport.width,stacks.Count*iconWidth+8f);
        itemBarScroll=GUI.BeginScrollView(viewport,itemBarScroll,
            new Rect(0f,0f,contentWidth,viewport.height-2f),false,false);
        bool pressedItem=false;
        for(int i=0;i<stacks.Count;i++)
        {
            KeyValuePair<string,List<string>> stack=stacks[i];
            ItemMasterRow item=GameMasterData.Item(stack.Key);
            if(item==null)continue;
            bool tutorialEnabled=!FirstItemGuideVisible||
                FirstItemCombineGuideVisible&&item.IsBase||
                FirstItemEquipGuideVisible&&item.IsCompleted;
            Rect icon=new Rect(4f+i*iconWidth,3f,68f,54f);
            bool movingOriginal=draggingItem&&
                stack.Value.Contains(draggedItemInstanceId);
            if(movingOriginal)DrawEmptyItemSlot(icon);
            else
            {
                DrawItemIcon(icon,item,stack.Value.Count);
                ExpeditionItemInstanceSave displayed=
                    ExpeditionItemSystem.ItemInstance(expeditionRun,stack.Value[0]);
                if(displayed!=null&&displayed.temporary)
                    DrawTemporaryItemBadge(icon);
                if(displayed!=null&&displayed.transformState!=ExpeditionItemTransformState.None)
                {
                    if(displayed.transformState==ExpeditionItemTransformState.Radiant)
                        DrawRadiantItemFrame(icon);
                    if(icon.Contains(current.mousePosition))
                    {
                        hoveredItemTooltip=ExpeditionItemTransformSystem.ResolveEffectiveMaster(displayed);
                        hoveredItemTooltip.displayName=ExpeditionItemTransformSystem.DisplayName(displayed);
                    }
                }
                if(pandoraProgress<1f)
                    DrawPandoraTransitionFrame(icon,stack.Value,pandoraProgress);
            }
            if(!tutorialEnabled)
                BombBrickUiTheme.Fill(icon,new Color(0f,0f,0f,0.62f));
            if(current.type==EventType.MouseDown&&current.button==0&&icon.Contains(current.mousePosition))
            {
                if(tutorialEnabled)BeginItemDrag(stack.Value[0]);
                else itemUiMessage=FirstItemCombineGuideVisible
                    ?"기본 아이템 두 개를 먼저 합성하세요."
                    :"완성 아이템을 아군에게 장착하세요.";
                pressedItem=true;
                current.Use();
            }
        }
        GUI.EndScrollView();

        DrawDraggedItemOverlay(stacks);
        DrawDraggedSpecialItemOverlay();
        DrawItemDragTargetFeedback(stacks);

        if(current.type==EventType.MouseDown&&current.button==0&&
           bar.Contains(current.mousePosition)&&!pressedItem&&
           PlayerUnitAtGuiPoint(current.mousePosition)==null)
        {
            ClearPreparationSelection();
            current.Use();
        }
        if(current.type==EventType.MouseDrag&&current.button==0&&!string.IsNullOrEmpty(draggedItemInstanceId))
        {
            draggingItem=true;
            current.Use();
        }
        if(current.type==EventType.MouseUp&&current.button==0&&!string.IsNullOrEmpty(draggedItemInstanceId))
        {
            CompleteItemDrop(current.mousePosition,stacks);
            current.Use();
        }
        RefreshUnitOutlines();
        DrawItemActionFeedback();
        if(!FirstItemGuideVisible)DrawGrowthShopBagTab();
    }

    private void ShowItemActionFeedback(string message)
    {
        if(string.IsNullOrWhiteSpace(message))return;
        itemActionFeedback=message;
        itemActionFeedbackStartedAt=Time.unscaledTime;
    }

    private void DrawItemActionFeedback()
    {
        if(string.IsNullOrEmpty(itemActionFeedback)||
           itemActionFeedbackStartedAt<0f)return;
        float elapsed=Time.unscaledTime-itemActionFeedbackStartedAt;
        if(elapsed>=ItemActionFeedbackDuration)
        {
            itemActionFeedback="";
            itemActionFeedbackStartedAt=-1f;
            return;
        }
        float progress=Mathf.Clamp01(elapsed/ItemActionFeedbackDuration);
        float alpha=1f-Mathf.SmoothStep(0f,1f,
            Mathf.Clamp01((progress-0.62f)/0.38f));
        float scale=Mathf.Lerp(0.94f,1f,
            BombBrickUiTheme.EaseOutBack(Mathf.Clamp01(progress/0.24f),0.55f));
        Rect bar=ItemBarRect;
        Rect panel=BombBrickUiLayout.ClampRect(
            new Rect(bar.center.x-190f,bar.y-70f,380f,40f),
            UiLayout.safeArea,8f);
        Matrix4x4 previousMatrix=GUI.matrix;
        Color previousColor=GUI.color;
        GUIUtility.ScaleAroundPivot(new Vector2(scale,scale),panel.center);
        GUI.color=new Color(1f,1f,1f,alpha);
        BombBrickUiTheme.Fill(panel,
            new Color(BombBrickUiTheme.SurfaceRaised.r,
                BombBrickUiTheme.SurfaceRaised.g,
                BombBrickUiTheme.SurfaceRaised.b,0.98f*alpha));
        BombBrickUiTheme.Frame(panel,
            new Color(BombBrickUiTheme.Lime.r,
                BombBrickUiTheme.Lime.g,BombBrickUiTheme.Lime.b,alpha),1f);
        GUI.Label(panel,itemActionFeedback,
            BombBrickUiTheme.TitleStyle(13,TextAnchor.MiddleCenter));
        GUI.color=previousColor;
        GUI.matrix=previousMatrix;
    }

    private void DrawDraggedSpecialItemOverlay()
    {
        if(!draggingSpecialItem||
           string.IsNullOrEmpty(draggedSpecialItemInstanceId))return;
        ExpeditionSpecialItemSave dragged=expeditionRun.specialItems.FirstOrDefault(
            value=>value!=null&&value.instanceId==draggedSpecialItemInstanceId);
        if(dragged==null)return;
        Vector2 mouse=Event.current.mousePosition;
        const float iconSize=64f;
        Rect token=DragTokenRect(mouse,iconSize);
        DrawSpecialItemIcon(token,dragged.itemId,dragged.count,
            !string.IsNullOrEmpty(dragged.boundMonsterInstanceId));
        bool valid=IsValidSpecialItemDrop(dragged,mouse);
        BombBrickUiTheme.Frame(token,
            valid?BombBrickUiTheme.Lime:BombBrickUiTheme.Red,2f);
    }

    private void DrawItemDragTargetFeedback(
        List<KeyValuePair<string,List<string>>> stacks)
    {
        if(!draggingSpecialItem&&!draggingItem)return;
        Vector2 pointer=Event.current.mousePosition;
        string label="이동";
        bool valid=false;
        bool targetsMonster=false;

        if(draggingSpecialItem)
        {
            ExpeditionSpecialItemSave special=expeditionRun.specialItems.FirstOrDefault(
                value=>value!=null&&value.instanceId==draggedSpecialItemInstanceId);
            if(special==null)return;
            targetsMonster=SpecialItemTargetsMonster(special.itemId);
            valid=IsValidSpecialItemDrop(special,pointer);
            label=targetsMonster
                ?SpecialItemName(special.itemId)+" 적용"
                :"완성 아이템에 "+SpecialItemName(special.itemId)+" 사용";
        }
        else
        {
            Unit target=PlayerUnitAtGuiPoint(pointer);
            string targetId=InventoryItemAt(pointer,stacks,draggedItemInstanceId);
            ItemMasterRow preview=FusionPreviewAt(
                pointer,stacks,draggedItemInstanceId);
            targetsMonster=target!=null;
            if(target!=null)
            {
                Unit transferOwner=null;
                if(FirstItemTransferGuideVisible)
                    TryFindEquippedSlot(
                        draggedItemInstanceId,out transferOwner,out _);
                valid=!FirstItemCombineGuideVisible&&target!=transferOwner&&
                      HasAvailableItemSlot(target);
                label=FirstItemCombineGuideVisible
                    ?"먼저 아이템을 합성하세요."
                    :FirstItemTransferGuideVisible&&target==transferOwner
                        ?"다른 아군에게 옮기세요."
                    :valid?"아이템 장착":"슬롯이 가득 찼습니다";
            }
            else if(!string.IsNullOrEmpty(targetId))
            {
                valid=!FirstItemEquipGuideVisible&&
                      !FirstItemTransferGuideVisible&&preview!=null;
                label=FirstItemEquipGuideVisible||FirstItemTransferGuideVisible
                    ?"완성 아이템을 다른 아군에게 옮기세요."
                    :valid
                        ?(FirstItemCombineGuideVisible||FusionHoldProgress()>=1f
                            ?"놓아서 합성":"합성 준비 중")
                        :"조합 불가";
            }
            else if(ItemBarRect.Contains(pointer)&&
                    TryFindEquippedSlot(draggedItemInstanceId,out _,out _))
            {
                valid=!FirstItemTransferGuideVisible;
                label=FirstItemTransferGuideVisible
                    ?"다른 아군에게 직접 옮기세요."
                    :"탐험 가방으로 이동";
            }
            else
            {
                Unit selected=inspectedUnit!=null&&
                    inspectedUnit.team==Team.Player?inspectedUnit:null;
                if(selected!=null&&SelectedUnitSlotRowRect(selected)
                    .Contains(pointer))
                {
                    valid=true;
                    label="슬롯에 장착";
                }
            }
        }

        DrawDragStatusBadge(pointer,label,valid);
    }

    private void DrawDragStatusBadge(Vector2 pointer,string label,bool valid)
    {
        float width=Mathf.Clamp(72f+label.Length*8f,132f,310f);
        Rect badge=BombBrickUiLayout.PlacePopup(
            pointer+new Vector2(0f,38f),new Vector2(width,34f),
            UiLayout.safeArea,18f);
        Color accent=valid?BombBrickUiTheme.Lime:BombBrickUiTheme.Red;
        BombBrickUiTheme.Fill(badge,
            new Color(BombBrickUiTheme.SurfaceRaised.r,
                BombBrickUiTheme.SurfaceRaised.g,
                BombBrickUiTheme.SurfaceRaised.b,0.98f));
        BombBrickUiTheme.Frame(badge,accent,1f);
        GUI.Label(new Rect(badge.x+9f,badge.y+5f,24f,24f),
            valid?"✓":"×",
            BombBrickUiTheme.TitleStyle(16,TextAnchor.MiddleCenter));
        GUI.Label(new Rect(badge.x+37f,badge.y+5f,badge.width-46f,24f),
            label,BombBrickUiTheme.CaptionStyle(11,TextAnchor.MiddleLeft));
    }

    private Rect DragTokenRect(Vector2 pointer,float size)
    {
        return BombBrickUiLayout.ClampRect(
            new Rect(pointer.x-size*0.5f,pointer.y-size*0.5f,size,size),
            UiLayout.safeArea,8f);
    }

    private bool IsValidSpecialItemDrop(
        ExpeditionSpecialItemSave special,Vector2 pointer)
    {
        if(special==null)return false;
        if(SpecialItemTargetsMonster(special.itemId))
            return PlayerUnitAtGuiPoint(pointer)!=null;
        string instanceId=ItemInstanceAtGuiPoint(
            pointer,BuildInventoryItemStacks());
        ExpeditionItemInstanceSave instance=
            ExpeditionItemSystem.ItemInstance(expeditionRun,instanceId);
        ItemMasterRow item=instance==null?null:GameMasterData.Item(instance.itemId);
        return item!=null&&item.IsCompleted;
    }

    private static bool SpecialItemTargetsMonster(string itemId)
    {
        return itemId=="special_combined_cast_core"||
               itemId=="special_trait_recombobulator";
    }

    private bool HasAvailableItemSlot(Unit target)
    {
        ExpeditionMonsterStateSave state=target==null?null:
            ExpeditionItemSystem.MonsterState(expeditionRun,target.stableId);
        return state!=null&&state.itemInstanceIds.Any(string.IsNullOrEmpty);
    }

    private void OpenShop(bool fromPreparation=false)
    {
        if(battleStarted||resultText.Length>0||
           AugmentDraftVisible||GrowthShopVisible||
           shopVisible||!ExpeditionShopSystem.IsShopWave(expeditionRun.wave))return;
        shopRollSequence++;
        int seed=MonsterInstanceGenerator.StableSeed(
            expeditionRun.runId+"_wave_"+expeditionRun.wave+"_shop_"+shopRollSequence);
        ExpeditionShopSystem.EnsureStock(expeditionRun,seed);
        shopVisible=true;
        shopOpenedFromPreparation=fromPreparation;
        shopClosing=false;
        shopTransitionStartedAt=Time.unscaledTime;
        GameAudio.Play(GameAudio.Cue.SlideOpen);
        shopPurchaseFeedbackIndex=-1;
        shopPurchaseFeedbackStartedAt=-1f;
        shopPurchaseFeedbackItemId="";
        ClearPreparationSelection();
        SaveExpeditionCheckpoint(
            fromPreparation
                ?ExpeditionRunCheckpoint.Preparation
                :ExpeditionRunCheckpoint.Shop,true);
    }

    private void CloseShop()
    {
        if(shopClosing)return;
        shopClosing=true;
        shopTransitionStartedAt=Time.unscaledTime;
        GameAudio.Play(GameAudio.Cue.SlideClose);
        StartCoroutine(CompleteShopCloseTransition());
    }

    private IEnumerator CompleteShopCloseTransition()
    {
        float transitionStartedAt=shopTransitionStartedAt;
        while(shopClosing&&shopTransitionStartedAt==transitionStartedAt&&
              Time.unscaledTime-transitionStartedAt<ShopCloseTransitionDuration)
            yield return null;
        while(GameFrontend.HasPendingSave)yield return null;
        if(!shopClosing||shopTransitionStartedAt!=transitionStartedAt)yield break;
        bool continuePreparationFlow=!shopOpenedFromPreparation;
        shopClosing=false;
        shopTransitionStartedAt=-1f;
        shopOpenedFromPreparation=false;
        shopVisible=false;
        if(continuePreparationFlow)ContinueWavePreparationFlow();
        else SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,true);
    }

    private void RefreshShop()
    {
        shopPurchaseFeedbackIndex=-1;
        shopRollSequence++;
        int seed=MonsterInstanceGenerator.StableSeed(
            expeditionRun.runId+"_wave_"+expeditionRun.wave+"_shop_refresh_"+shopRollSequence);
        if(ExpeditionShopSystem.TryRefresh(
               expeditionRun,seed,playerProfile,out string error))
        {
            itemUiMessage="상점 진열을 새로고침했습니다.";
            SaveExpeditionCheckpoint(
                shopOpenedFromPreparation
                    ?ExpeditionRunCheckpoint.Preparation
                    :ExpeditionRunCheckpoint.Shop,true);
        }
        else itemUiMessage=error;
    }

    private void PurchaseShopItem(int index)
    {
        if(ExpeditionShopSystem.TryPurchase(
            expeditionRun,index,out ExpeditionItemInstanceSave purchased,out string error))
        {
            ItemMasterRow item=purchased==null?null:GameMasterData.Item(purchased.itemId);
            itemUiMessage="";
            shopPurchaseFeedbackIndex=index;
            shopPurchaseFeedbackStartedAt=Time.unscaledTime;
            shopPurchaseFeedbackItemId=item==null?"":item.id;
            SaveExpeditionCheckpoint(
                shopOpenedFromPreparation
                    ?ExpeditionRunCheckpoint.Preparation
                    :ExpeditionRunCheckpoint.Shop,true);
        }
        else
        {
            itemUiMessage=error;
            ShowItemActionFeedback(error);
        }
    }

    private void DrawShopPanel()
    {
        Rect safe=UiLayout.safeArea;
        float width=Mathf.Min(1100f,safe.width-32f);
        float height=Mathf.Min(548f,safe.height-32f);
        Rect panel=new Rect(safe.center.x-width*0.5f,safe.center.y-height*0.5f,
            width,height);

        float transitionAge=shopTransitionStartedAt<0f
            ?ShopOpenTransitionDuration
            :Mathf.Max(0f,Time.unscaledTime-shopTransitionStartedAt);
        float transitionDuration=shopClosing
            ?ShopCloseTransitionDuration:ShopOpenTransitionDuration;
        float rawTransition=Mathf.Clamp01(
            transitionAge/Mathf.Max(0.01f,transitionDuration));
        float panelProgress=shopClosing
            ?1f-rawTransition*rawTransition
            :BombBrickUiTheme.EaseOutCubic(rawTransition);
        float scaleProgress=shopClosing
            ?panelProgress
            :BombBrickUiTheme.EaseOutBack(rawTransition,0.55f);
        float panelScale=Mathf.LerpUnclamped(0.08f,1f,scaleProgress);
        Vector2 panelCenter=Vector2.Lerp(
            ItemShopButtonRect.center,panel.center,panelProgress);
        Color backdrop=BombBrickUiTheme.Backdrop;
        backdrop.a*=Mathf.Clamp01(panelProgress);
        BombBrickUiTheme.Fill(
            new Rect(0f,0f,BombBrickUiLayout.Width,BombBrickUiLayout.Height),backdrop);

        Matrix4x4 previousMatrix=GUI.matrix;
        bool previousEnabled=GUI.enabled;
        GUI.matrix=previousMatrix*Matrix4x4.TRS(
                new Vector3(panelCenter.x,panelCenter.y,0f),
                Quaternion.identity,new Vector3(panelScale,panelScale,1f))*
            Matrix4x4.TRS(
                new Vector3(-panel.center.x,-panel.center.y,0f),
                Quaternion.identity,Vector3.one);
        bool shopInteractive=!shopClosing&&rawTransition>=1f;
        GUI.enabled=previousEnabled&&shopInteractive;

        BombBrickUiTheme.DrawPanel(panel,true);
        BombBrickUiTheme.Fill(new Rect(panel.x,panel.y,panel.width,4f),
            BombBrickUiTheme.Orange);
        DrawSystemIcon(new Rect(panel.x+22f,panel.y+18f,42f,42f),
            "shop",BombBrickUiTheme.Orange,false);
        GUI.Label(new Rect(panel.x+76f,panel.y+13f,280f,34f),"탐험 상점",
            BombBrickUiTheme.TitleStyle(24));
        GUI.Label(new Rect(panel.x+76f,panel.y+45f,360f,18f),
            GameLocalization.Format(
                "shop.wave_title","W {0} · 아이템 상점",expeditionRun.wave),
            BombBrickUiTheme.CaptionStyle(10));

        Rect goldRect=new Rect(panel.xMax-210f,panel.y+17f,146f,42f);
        BombBrickUiTheme.Fill(goldRect,BombBrickUiTheme.Surface);
        float goldFeedbackAge=Time.unscaledTime-shopPurchaseFeedbackStartedAt;
        bool goldSpending=shopPurchaseFeedbackStartedAt>=0f&&
            goldFeedbackAge<ShopPurchaseFeedbackDuration;
        float goldPulse=goldSpending
            ?0.5f+0.5f*Mathf.Sin(goldFeedbackAge*22f):0f;
        BombBrickUiTheme.Frame(goldRect,
            goldSpending?Color.Lerp(BombBrickUiTheme.Orange,
                BombBrickUiTheme.Red,goldPulse):BombBrickUiTheme.Orange,
            goldSpending?2f:1f);
        DrawSystemIcon(new Rect(goldRect.x+8f,goldRect.y+6f,26f,26f),
            "gold",BombBrickUiTheme.Orange,false);
        GUI.Label(new Rect(goldRect.x+39f,goldRect.y+2f,goldRect.width-49f,34f),
            expeditionRun.expeditionCurrency.ToString(),
            BombBrickUiTheme.TitleStyle(19,TextAnchor.MiddleRight));
        if(shopPurchaseFeedbackStartedAt>=0f)
        {
            float feedbackAge=Time.unscaledTime-shopPurchaseFeedbackStartedAt;
            if(feedbackAge<ShopPurchaseFeedbackDuration)
            {
                float fade=1f-Mathf.Clamp01(
                    feedbackAge/ShopPurchaseFeedbackDuration);
                GUIStyle spentStyle=BombBrickUiTheme.TitleStyle(
                    13,TextAnchor.MiddleRight);
                BombBrickUiTheme.Label(new Rect(goldRect.x,goldRect.yMax+2f,
                    goldRect.width,20f),"-"+ExpeditionShopSystem.ItemCost,
                    spentStyle,new Color(
                    BombBrickUiTheme.Red.r,BombBrickUiTheme.Red.g,
                    BombBrickUiTheme.Red.b,fade));
            }
        }
        if(BombBrickUiTheme.Button(new Rect(panel.xMax-48f,panel.y+18f,30f,30f),
            "×",true,false))
        {
            CloseShop();
        }

        BombBrickUiTheme.Fill(new Rect(panel.x+22f,panel.y+78f,panel.width-44f,1f),
            BombBrickUiTheme.Border);
        int count=expeditionRun.shopItemIds==null?0:expeditionRun.shopItemIds.Count;
        float gap=14f;
        float cardsWidth=panel.width-44f;
        float cardWidth=(cardsWidth-gap*Mathf.Max(0,count-1))/Mathf.Max(1,count);
        float cardHeight=Mathf.Max(274f,panel.height-200f);
        float cardY=panel.y+96f;
        Rect[] cards=new Rect[count];
        for(int i=0;i<count;i++)
            cards[i]=new Rect(panel.x+22f+i*(cardWidth+gap),cardY,
                cardWidth,cardHeight);

        Event current=Event.current;

        for(int i=0;i<count;i++)
        {
            ItemMasterRow item=GameMasterData.Item(expeditionRun.shopItemIds[i]);
            Rect card=cards[i];
            bool hovered=cards[i].Contains(current.mousePosition);
            bool affordable=expeditionRun.expeditionCurrency>=
                ExpeditionShopSystem.ItemCost;
            float purchaseAge=Time.unscaledTime-shopPurchaseFeedbackStartedAt;
            bool purchaseFeedback=i==shopPurchaseFeedbackIndex&&
                shopPurchaseFeedbackStartedAt>=0f&&
                purchaseAge<ShopPurchaseFeedbackDuration;
            float purchasePulse=purchaseFeedback
                ?0.5f+0.5f*Mathf.Sin(purchaseAge*18f):0f;
            BombBrickUiTheme.DrawCard(card,
                purchaseFeedback
                    ?Color.Lerp(BombBrickUiTheme.Lime,Color.white,purchasePulse*0.2f)
                    :(item==null?BombBrickUiTheme.Border:
                        (affordable?BombBrickUiTheme.Orange:BombBrickUiTheme.Red)),
                false,hovered);
            if(item==null)
            {
                Vector2 stateCenter=new Vector2(card.center.x,card.y+99f);
                if(purchaseFeedback)
                {
                    ItemMasterRow purchasedMaster=
                        GameMasterData.Item(shopPurchaseFeedbackItemId);
                    float dissolve=1f-Mathf.Clamp01(
                        purchaseAge/ShopPurchaseFeedbackDuration);
                    float purchaseIconSize=Mathf.Lerp(54f,104f,dissolve);
                    Color previous=GUI.color;
                    GUI.color=new Color(1f,1f,1f,dissolve);
                    DrawItemIcon(new Rect(
                        stateCenter.x-purchaseIconSize*0.5f,
                        stateCenter.y-purchaseIconSize*0.5f,
                        purchaseIconSize,purchaseIconSize),
                        purchasedMaster,1);
                    GUI.color=previous;
                    DrawGuiRing(stateCenter,34f+(1f-dissolve)*52f,
                        new Color(BombBrickUiTheme.Orange.r,
                            BombBrickUiTheme.Orange.g,
                            BombBrickUiTheme.Orange.b,dissolve),
                        2.4f,24);
                }
                else
                {
                    DrawGuiRing(stateCenter,22f,
                        BombBrickUiTheme.TextSecondary,1.5f,20);
                    DrawGuiCheck(stateCenter,
                        BombBrickUiTheme.TextSecondary,2.5f);
                }
                continue;
            }
            int ownedCount=OwnedShopItemCount(item.id);
            BombBrickUiTheme.Badge(new Rect(card.x+10f,card.y+13f,70f,21f),
                item.IsCompleted?"완성 아이템":"기본 재료",
                item.IsCompleted?BombBrickUiTheme.Orange:BombBrickUiTheme.Cyan);
            if(ownedCount>0)
                BombBrickUiTheme.Badge(
                    new Rect(card.xMax-62f,card.y+13f,52f,21f),
                    GameLocalization.Format(
                        "common.owned_amount","보유 {0}",ownedCount),
                    BombBrickUiTheme.Violet);
            float iconSize=Mathf.Min(118f,card.width-32f);
            DrawItemIcon(new Rect(card.center.x-iconSize*0.5f,card.y+43f,
                iconSize,iconSize),item,1);
            GUI.Label(new Rect(card.x+10f,card.y+169f,card.width-20f,26f),
                item.displayName,
                BombBrickUiTheme.TitleStyle(14,TextAnchor.MiddleCenter));
            GUI.Label(new Rect(card.x+14f,card.y+201f,card.width-28f,48f),
                CompactItemStats(item),
                BombBrickUiTheme.BodyStyle(11,TextAnchor.MiddleCenter));
            Rect buy=new Rect(card.x+14f,card.yMax-58f,card.width-28f,36f);
            if(BombBrickUiTheme.Button(
                   buy,GameLocalization.Format(
                       "shop.buy_gold","구매 · 골드 {0}",
                       ExpeditionShopSystem.ItemCost),
                   affordable,true))
                PurchaseShopItem(i);
            if(!affordable)
            {
                BombBrickUiTheme.Fill(
                    new Rect(card.x+1f,card.y+1f,card.width-2f,card.height-2f),
                    new Color(0.015f,0.02f,0.032f,0.58f));
                BombBrickUiTheme.Badge(
                    new Rect(card.center.x-43f,card.center.y-11f,86f,22f),
                    "골드 부족",BombBrickUiTheme.Red);
            }
        }

        if(goldSpending&&shopPurchaseFeedbackIndex>=0&&
           shopPurchaseFeedbackIndex<cards.Length)
            DrawShopGoldSpendEffect(
                goldRect,cards[shopPurchaseFeedbackIndex],goldFeedbackAge);

        int refreshCost=ExpeditionShopSystem.RefreshCost(
            expeditionRun,playerProfile);
        bool canRefresh=expeditionRun.expeditionCurrency>=refreshCost;
        Rect refreshRect=new Rect(panel.center.x-144f,panel.yMax-57f,288f,38f);
        DrawSystemIcon(new Rect(refreshRect.x+10f,refreshRect.y+7f,24f,24f),
            "reroll",BombBrickUiTheme.Cyan,false);
        string refreshLabel=refreshCost==0
            ?GameLocalization.TextByKey(
                "shop.refresh_free","새로고침  ·  1회 무료")
            :GameLocalization.Format(
                "shop.refresh_gold","새로고침  ·  골드 {0}",refreshCost);
        if(BombBrickUiTheme.Button(refreshRect,refreshLabel,canRefresh,false))
            RefreshShop();
        BombBrickUiTheme.Badge(
            new Rect(panel.x+22f,panel.yMax-54f,132f,26f),
            expeditionRun.shopRefreshCount==0
                ?"무료 새로고침 가능"
                :GameLocalization.Format(
                    "shop.refresh_count","새로고침 {0}회",
                    expeditionRun.shopRefreshCount),
            expeditionRun.shopRefreshCount==0
                ?BombBrickUiTheme.Lime:BombBrickUiTheme.Cyan);
        if(!string.IsNullOrEmpty(itemUiMessage))
            GUI.Label(new Rect(panel.x+170f,panel.yMax-24f,
                panel.width-340f,18f),
                itemUiMessage,
                BombBrickUiTheme.CaptionStyle(11,TextAnchor.MiddleCenter));
        GUI.enabled=previousEnabled;
        GUI.matrix=previousMatrix;
    }

    private int OwnedShopItemCount(string itemId)
    {
        if(expeditionRun==null||expeditionRun.itemInstances==null||
           string.IsNullOrEmpty(itemId))return 0;
        return expeditionRun.itemInstances.Count(value=>
            value!=null&&value.itemId==itemId);
    }

    private static void DrawShopGoldSpendEffect(
        Rect goldRect,Rect purchasedCard,float age)
    {
        Vector2 start=goldRect.center;
        Vector2 end=new Vector2(purchasedCard.center.x,purchasedCard.y+99f);
        Vector2 control=(start+end)*0.5f+
            new Vector2(0f,-Mathf.Min(90f,Vector2.Distance(start,end)*0.18f));
        for(int i=0;i<7;i++)
        {
            float t=Mathf.Clamp01((age-i*0.045f)/0.56f);
            if(t<=0f||t>=1f)continue;
            float eased=BombBrickUiTheme.EaseOutCubic(t);
            float inverse=1f-eased;
            Vector2 point=inverse*inverse*start+
                2f*inverse*eased*control+eased*eased*end;
            float flicker=0.72f+0.28f*Mathf.Sin(age*25f+i*1.9f);
            DrawGuiGlowNode(point,3.2f+flicker,
                new Color(1f,0.68f,0.16f,0.94f));
        }
        float targetPulse=Mathf.Clamp01(age/0.5f);
        DrawGuiRing(end,18f+targetPulse*38f,
            new Color(1f,0.65f,0.12f,1f-targetPulse),2f,22);
    }

    private static void DrawGuiCheck(Vector2 center,Color color,float width)
    {
        DrawGuiLine(center+new Vector2(-9f,0f),
            center+new Vector2(-2f,7f),color,width);
        DrawGuiLine(center+new Vector2(-2f,7f),
            center+new Vector2(11f,-8f),color,width);
    }

    private void DrawShopPanelLegacy()
    {
        Color previous=GUI.color;
        GUI.color=new Color(0.01f,0.015f,0.025f,0.94f);
        GUI.DrawTexture(new Rect(0f,0f,BombBrickUiLayout.Width,BombBrickUiLayout.Height),Texture2D.whiteTexture);
        GUI.color=previous;

        float width=Mathf.Min(900f,BombBrickUiLayout.Width-30f);
        Rect panel=new Rect((BombBrickUiLayout.Width-width)*0.5f,(BombBrickUiLayout.Height-360f)*0.5f,width,360f);
        GUI.Box(panel,"아이템 상점");
        GUI.Label(new Rect(panel.x+18f,panel.y+30f,panel.width-36f,24f),
            "골드: "+expeditionRun.expeditionCurrency+
            "  ·  기본 아이템 가격: "+ExpeditionShopSystem.ItemCost);

        int count=expeditionRun.shopItemIds==null?0:expeditionRun.shopItemIds.Count;
        float gap=12f;
        float cardWidth=(panel.width-gap*(Mathf.Max(1,count)+1))/Mathf.Max(1,count);
        for(int i=0;i<count;i++)
        {
            string itemId=expeditionRun.shopItemIds[i];
            ItemMasterRow item=GameMasterData.Item(itemId);
            Rect card=new Rect(panel.x+gap+i*(cardWidth+gap),panel.y+64f,cardWidth,190f);
            GUI.Box(card,"");
            if(item==null)
            {
                GUI.Label(new Rect(card.x+8f,card.y+60f,card.width-16f,30f),
                    "판매 완료",new GUIStyle(GUI.skin.label){alignment=TextAnchor.MiddleCenter});
                continue;
            }
            DrawItemIcon(new Rect(card.center.x-54f,card.y+18f,108f,108f),item,1);
            GUI.enabled=expeditionRun.expeditionCurrency>=ExpeditionShopSystem.ItemCost;
            if(GUI.Button(new Rect(card.x+12f,card.yMax-44f,card.width-24f,30f),
                "구매 · "+ExpeditionShopSystem.ItemCost))PurchaseShopItem(i);
            GUI.enabled=true;
        }

        int refreshCost=ExpeditionShopSystem.RefreshCost(
            expeditionRun,playerProfile);
        GUI.enabled=expeditionRun.expeditionCurrency>=refreshCost;
        string refreshLabel=refreshCost==0
            ?"새로고침 · 1회 무료"
            :"새로고침 · 골드 "+refreshCost;
        if(GUI.Button(new Rect(panel.center.x-130f,panel.yMax-72f,260f,34f),refreshLabel))
            RefreshShop();
        GUI.enabled=true;
        if(GUI.Button(new Rect(panel.xMax-98f,panel.yMax-42f,80f,28f),"닫기"))
            CloseShop();
        if(!string.IsNullOrEmpty(itemUiMessage))
            GUI.Label(new Rect(panel.x+18f,panel.yMax-38f,panel.width-130f,24f),itemUiMessage);
    }

    private List<KeyValuePair<string,List<string>>> BuildInventoryItemStacks()
    {
        List<KeyValuePair<string,List<string>>> items=
            new List<KeyValuePair<string,List<string>>>();
        foreach(ExpeditionItemInstanceSave instance in
                 ExpeditionItemSystem.InventoryItems(expeditionRun))
        {
            items.Add(new KeyValuePair<string,List<string>>(
                instance.itemId,new List<string>{instance.instanceId}));
        }
        return items.OrderBy(pair=>GameMasterData.Item(pair.Key)?.IsCompleted==true?1:0)
            .ThenBy(pair=>GameMasterData.Item(pair.Key)?.displayName)
            .ThenBy(pair=>pair.Value[0],StringComparer.Ordinal)
            .ToList();
    }

    private void DrawItemIcon(Rect rect,ItemMasterRow item,int count)
    {
        if(item==null)return;
        bool hovered=rect.Contains(Event.current.mousePosition);
        Color accent=item.IsCompleted?BombBrickUiTheme.Orange:BombBrickUiTheme.Cyan;
        BombBrickUiTheme.Fill(rect,hovered?BombBrickUiTheme.SurfaceHover:
            BombBrickUiTheme.Surface);
        BombBrickUiTheme.Frame(rect,hovered?Color.Lerp(accent,Color.white,0.2f):
            new Color(accent.r,accent.g,accent.b,0.72f),hovered?2f:1f);

        Texture2D icon=ItemIconTexture(item);
        Rect imageRect=new Rect(rect.x+3f,rect.y+3f,rect.width-6f,rect.height-6f);
        if(icon!=null)GUI.DrawTexture(imageRect,icon,ScaleMode.ScaleToFit,false);
        else
        {
            BombBrickUiTheme.Fill(imageRect,new Color(0.04f,0.06f,0.1f,1f));
            GUI.Label(imageRect,"?",BombBrickUiTheme.TitleStyle(
                Mathf.Clamp(Mathf.RoundToInt(rect.height*0.42f),12,24),
                TextAnchor.MiddleCenter));
        }
        if(item.IsCompleted)
            BombBrickUiTheme.Fill(new Rect(rect.x+2f,rect.y+2f,3f,rect.height-4f),
                BombBrickUiTheme.Orange);
        if(count>1)
            BombBrickUiTheme.Badge(new Rect(rect.xMax-25f,rect.y-3f,26f,19f),
                "×"+count,accent);
        if(hovered)
        {
            hoveredItemTooltip=item;
            hoveredItemTooltipSource=rect;
        }
    }

