    private static void DrawRadiantItemFrame(Rect iconRect)
    {
        float shimmer=0.5f+0.5f*Mathf.Sin(Time.unscaledTime*4.5f);
        Color gold=Color.Lerp(new Color(1f,0.58f,0.08f),Color.white,
            0.18f+shimmer*0.24f);
        BombBrickUiTheme.Frame(iconRect,gold,3f);
        BombBrickUiTheme.Frame(new Rect(iconRect.x+4f,iconRect.y+4f,
            iconRect.width-8f,iconRect.height-8f),
            new Color(1f,0.82f,0.28f,0.72f),1f);
        float spark=3f+shimmer*2f;
        BombBrickUiTheme.Fill(new Rect(iconRect.x-2f,iconRect.y-2f,spark,spark),Color.white);
        BombBrickUiTheme.Fill(new Rect(iconRect.xMax-spark+2f,
            iconRect.yMax-spark+2f,spark,spark),gold);
    }

    private float DrawPandoraBagFeedback(Rect bar)
    {
        bool granted=!string.IsNullOrEmpty(pandoraGrantedItemInstanceId);
        if(!granted&&pandoraTransitionItemIds.Count==0)return 1f;
        // Start the feedback on the first frame where the bag is drawn.
        if(pandoraTransitionStartedAt<0f)
        {
            pandoraTransitionStartedAt=Time.unscaledTime;
            if(granted)GameAudio.Play(GameAudio.Cue.Reward);
        }
        float progress=(Time.unscaledTime-pandoraTransitionStartedAt)/
            PandoraTransitionDuration;
        if(progress>=1f)
        {
            pandoraTransitionItemIds.Clear();
            pandoraGrantedItemInstanceId="";
            return 1f;
        }
        float fade=1f-progress;
        if(granted)
            BombBrickUiTheme.Label(new Rect(bar.x+146f,bar.y+12f-8f*progress,36f,24f),
                "+1",BombBrickUiTheme.TitleStyle(15,TextAnchor.MiddleCenter),
                new Color(1f,0.82f,0.30f,fade));
        if(pandoraTransitionItemIds.Count>0)
            BombBrickUiTheme.Frame(new Rect(bar.x+10f,bar.y+10f,38f,38f),
                new Color(0.76f,0.46f,1f,fade),2f);
        return progress;
    }

    private void DrawPandoraTransitionFrame(
        Rect iconRect,List<string> instanceIds,float progress)
    {
        bool granted=instanceIds.Contains(pandoraGrantedItemInstanceId);
        float fade=1f-progress;
        if(instanceIds.Exists(pandoraTransitionItemIds.Contains))
        {
            Color violet=new Color(0.76f,0.46f,1f,fade);
            BombBrickUiTheme.Frame(iconRect,violet,2f+fade);
            float sweep=Mathf.Clamp01(progress/0.42f);
            BombBrickUiTheme.Fill(new Rect(iconRect.x+2f,
                iconRect.y+2f+(iconRect.height-9f)*sweep,iconRect.width-4f,5f),
                new Color(violet.r,violet.g,violet.b,(1f-sweep)*0.85f));
        }
        if(!granted)return;

        Color gold=new Color(1f,0.82f,0.30f,fade);
        BombBrickUiTheme.Frame(new Rect(iconRect.x+3f,iconRect.y+3f,
            iconRect.width-6f,iconRect.height-6f),gold,2f+2f*fade);
        float radius=Mathf.Lerp(10f,30f,BombBrickUiTheme.EaseOutCubic(progress));
        for(int i=0;i<6;i++)
        {
            float angle=i*Mathf.PI/3f;
            float size=2f+3f*fade;
            BombBrickUiTheme.Fill(new Rect(
                iconRect.center.x+Mathf.Cos(angle)*radius-size*0.5f,
                iconRect.center.y+Mathf.Sin(angle)*radius*0.62f-size*0.5f,
                size,size),gold);
        }
    }

    private static void DrawEmptyItemSlot(Rect rect)
    {
        BombBrickUiTheme.Fill(rect,BombBrickUiTheme.Surface);
        BombBrickUiTheme.Frame(rect,BombBrickUiTheme.Border,1f);
        BombBrickUiTheme.Fill(new Rect(
            rect.center.x-2f,rect.center.y-2f,4f,4f),
            BombBrickUiTheme.TextSecondary);
    }

    private Texture2D ItemIconTexture(ItemMasterRow item)
    {
        if(item==null||string.IsNullOrWhiteSpace(item.id))return null;
        if(itemIconCache.TryGetValue(item.id,out Texture2D cached))return cached;
        Texture2D loaded=Resources.Load<Texture2D>("UI/ItemIcons/"+item.id);
        if(loaded==null)
            loaded=Resources.Load<Texture2D>("UI/SpecialItemIcons/"+item.id);
        itemIconCache[item.id]=loaded;
        return loaded;
    }

    private void SetSkillTooltip(SkillMasterRow skill)
    {
        if(skill==null)return;
        if(UsesSabertoothDevour(inspectedUnit))
        {SetTraitTooltip(SabertoothDevourRules.TraitId,BombBrickUiTheme.Violet);return;}
        hoveredAbilityTitle=skill.displayName;
        hoveredAbilityCategory="고유 스킬";
        hoveredAbilityBody=MonsterAbilityTooltipContent.SkillSummary(skill)+"\n"+SkillScalingSummary(inspectedUnit);
        hoveredAbilityAccent=BombBrickUiTheme.Violet;
    }

    private void SetPersonalityTooltip(string personalityId)
    {
        PersonalityMasterRow personality=
            MonsterAbilityTooltipContent.Personality(personalityId);
        hoveredAbilityTitle=MonsterInstanceGenerator.PersonalityDisplayName(
            personalityId);
        hoveredAbilityCategory="전투 AI 성격";
