    private void SetTraitTooltip(string traitId,Color accent)
    {
        if(string.IsNullOrWhiteSpace(traitId))return;
        TraitMasterRow trait=MonsterAbilityTooltipContent.Trait(traitId);
        hoveredAbilityTitle=trait==null?TraitName(traitId):trait.displayName;
        hoveredAbilityCategory=MonsterAbilityTooltipContent.TraitCategory(trait);
        hoveredAbilityBody=MonsterAbilityTooltipContent.TraitSummary(trait)+"\n"+SkillScalingSummary(inspectedUnit);
        hoveredAbilityAccent=accent;
    }

    private void DrawMonsterAbilityTooltip()
    {
        if(string.IsNullOrWhiteSpace(hoveredAbilityTitle))return;
        BombBrickUiTheme.DrawHoverTooltip(
            Event.current.mousePosition,hoveredAbilityCategory,
            hoveredAbilityTitle,hoveredAbilityBody,hoveredAbilityAccent);
