    private void DrawItemTooltip()
    {
        ItemMasterRow item=hoveredItemTooltip;
        if(item==null)return;
        DrawItemTooltip(item,Event.current.mousePosition);
    }

    private Rect DrawItemTooltip(ItemMasterRow item,Vector2 pointer)
    {
        if(item==null)return new Rect();
        string effect=ItemSpecialEffectTooltip(item);
        string recipe="";
        if(item.IsCompleted)
        {
            ItemMasterRow first=GameMasterData.Item(item.componentAId);
            ItemMasterRow second=GameMasterData.Item(item.componentBId);
            if(first!=null&&second!=null)
                recipe=GameLocalization.Text(first.displayName)+" + "+
                    GameLocalization.Text(second.displayName);
        }

        const float width=326f;
        string stats=CompactItemStats(item);
        string recipeLabel=recipe.Length>0
            ?GameLocalization.Format("tooltip.item.recipe","조합  ·  {0}",recipe):"";
        GUIStyle statsStyle=BombBrickUiTheme.BodyStyle(13);
        GUIStyle effectStyle=BombBrickUiTheme.BodyStyle(12);
        GUIStyle recipeStyle=BombBrickUiTheme.BodyStyle(11);
        float statsHeight=Mathf.Max(34f,Mathf.Ceil(statsStyle.CalcHeight(
            new GUIContent(stats),width-32f)));
        float effectHeight=Mathf.Max(42f,Mathf.Ceil(effectStyle.CalcHeight(
            new GUIContent(effect),width-32f)));
        float effectY=62f+statsHeight;
        float recipeY=effectY+effectHeight+9f;
        float recipeHeight=recipe.Length>0?Mathf.Max(20f,Mathf.Ceil(
            recipeStyle.CalcHeight(new GUIContent(recipeLabel),width-32f))):0f;
        float height=recipe.Length>0?recipeY+recipeHeight+7f:effectY+effectHeight+10f;
        Rect panel=BombBrickUiLayout.PlacePopup(
            pointer,new Vector2(width,height),UiLayout.safeArea,18f);
        BombBrickUiTheme.DrawPanel(panel,true);
        Color accent=item.IsCompleted?BombBrickUiTheme.Orange:BombBrickUiTheme.Cyan;
        BombBrickUiTheme.Fill(new Rect(panel.x,panel.y,4f,panel.height),accent);

        GUI.Label(new Rect(panel.x+16f,panel.y+13f,panel.width-104f,26f),
            GameLocalization.Text(item.displayName),BombBrickUiTheme.TitleStyle(18));
        BombBrickUiTheme.Badge(new Rect(panel.xMax-86f,panel.y+14f,68f,22f),
            item.IsCompleted
                ?GameLocalization.TextByKey("tooltip.item.completed_badge","완성")
                :GameLocalization.TextByKey("tooltip.item.component_badge","재료"),accent);
        BombBrickUiTheme.Fill(new Rect(panel.x+16f,panel.y+47f,panel.width-32f,1f),
            BombBrickUiTheme.Border);
        GUI.Label(new Rect(panel.x+16f,panel.y+58f,panel.width-32f,statsHeight),
            stats,statsStyle);
        GUI.Label(new Rect(panel.x+16f,panel.y+effectY,panel.width-32f,effectHeight),
            effect,effectStyle);
        if(recipe.Length>0)
        {
            BombBrickUiTheme.Fill(new Rect(panel.x+16f,panel.y+recipeY-6f,
                panel.width-32f,1f),BombBrickUiTheme.Border);
            GUI.Label(new Rect(panel.x+16f,panel.y+recipeY,panel.width-32f,recipeHeight),
                recipeLabel,recipeStyle);
        }
        return panel;
    }

    private static string ItemSpecialEffectTooltip(ItemMasterRow item)
    {
        return GameLocalization.Text(ItemSpecialEffectTooltipKorean(item));
    }

    private static string ItemSpecialEffectTooltipKorean(ItemMasterRow item)
    {
        if(item==null)return "";
        float p1=item.effectParam1;
        float p2=item.effectParam2;
        float p3=item.effectParam3;
        switch(item.specialEffect)
        {
            case "AllDamageAmplification":
                return "가하는 모든 피해 "+SignedPercent(p1);
            case "BasicAttackSpeedRamp":
                return "기본 공격할 때마다 공격 속도 "+SignedPercent(p1)+" 누적";
            case "SkillPowerRamp":
                return "스킬을 사용할 때마다 스킬 위력 "+SignedPercent(p1)+" 누적";
            case "FirstSkillCooldownReduction":
                return "전투 시작 시 첫 스킬 대기시간 "+SignedPercent(-p1);
            case "BasicAttackDamageReduction":
                return "기본 공격으로 받는 물리 피해 "+SignedPercent(-p1);
            case "PeriodicSelfHeal":
                return p2.ToString("0.#")+"초마다 최대 체력의 "+
                    Mathf.RoundToInt(p1*100f)+"% 회복";
            case "BasicAttackDamageRamp":
                return "기본 공격할 때마다 공격력 "+SignedPercent(p1)+" 누적";
            case "Omnivamp":
                return "가한 피해의 "+Mathf.RoundToInt(p1*100f)+"%만큼 회복";
            case "PostSkillBasicDamage":
                return "스킬 사용 후 다음 기본 공격 피해 "+SignedPercent(p1);
            case "CounterGuaranteedCrit":
                return "기본 공격 "+Mathf.RoundToInt(p1)+"회 피격 시 다음 기본 공격 치명타";
            case "BloodTalisman":
                return "피해 흡혈 "+SignedPercent(p1)+" · 체력 "+
                    Mathf.RoundToInt(p2*100f)+"% 이하: 5초 보호막 "+
                    Mathf.RoundToInt(p3*100f)+"%";
            case "KillHeal":
                return "적 처치 시 최대 체력의 "+Mathf.RoundToInt(p1*100f)+"% 회복";
            case "PostSkillAttackSpeed":
                return "스킬 사용 후 "+p2.ToString("0.#")+"초간 공격 속도 "+
                    SignedPercent(p1);
            case "BasicCooldownReduction":
                return "기본 공격 시 스킬 재사용 대기시간 "+p1.ToString("0.##")+"초 감소";
            case "CombatCarapaceRamp":
                return "피격 시 공격 속도 "+SignedPercent(p1)+
                    " · 방어력 +"+p2.ToString("0.#")+" 누적";
            case "StatusRecoveryAttackSpeed":
                return "상태이상 해제 후 "+p2.ToString("0.#")+"초간 공격 속도 "+
                    SignedPercent(p1);
            case "EveryNthBasicHeal":
                return "기본 공격 "+Mathf.RoundToInt(p1)+"회마다 최대 체력의 "+
                    Mathf.RoundToInt(p2*100f)+"% 회복";
            case "CriticalDefenseShred":
                return "치명타 적중 시 "+p2.ToString("0.#")+"초간 대상 방어력 "+
                    SignedPercent(-p1);
            case "TimedSkillPowerRamp":
                return p2.ToString("0.#")+"초마다 스킬 위력 "+SignedPercent(p1)+" 누적";
            case "CrownCarapace":
                return "전투 시작: "+p2.ToString("0.#")+"초 보호막 "+
                    Mathf.RoundToInt(p1*100f)+"% · 소진 시 스킬 위력 "+
                    SignedPercent(p3);
            case "NearbyStatusResistanceReduction":
                return p1.ToString("0.#")+"타일 내 적 상태이상 저항력 -"+
