    }

    private void DrawSelectedMonsterItemSlots(Unit target)
    {
        if(target==null)return;
        Rect row=SelectedUnitSlotRowRect(target);
        if(row.width<=0f)return;
        ExpeditionMonsterStateSave state=ExpeditionItemSystem.MonsterState(expeditionRun,target.stableId);
        Event current=Event.current;
        for(int slot=0;slot<ExpeditionItemSystem.MaxSlots;slot++)
        {
            Rect rect=new Rect(row.x+slot*58f,row.y,52f,48f);
            string instanceId=state!=null?state.itemInstanceIds[slot]:"";
            ExpeditionItemInstanceSave instance=ExpeditionItemSystem.ItemInstance(expeditionRun,instanceId);
            ItemMasterRow item=instance==null?null:GameMasterData.Item(instance.itemId);
            if(item==null)
            {
                DrawEmptyItemSlot(rect);
                if(draggingItem&&!string.IsNullOrEmpty(draggedItemInstanceId))
                {
                    BombBrickUiTheme.Fill(rect,
                        new Color(BombBrickUiTheme.Lime.r*0.15f,
                            BombBrickUiTheme.Lime.g*0.15f,
                            BombBrickUiTheme.Lime.b*0.15f,0.94f));
                    BombBrickUiTheme.Frame(rect,BombBrickUiTheme.Lime,2f);
                }
                GUI.Label(rect,(slot+1).ToString(),
                    BombBrickUiTheme.CaptionStyle(
                        10,TextAnchor.MiddleCenter));
            }
            else if(draggingItem&&instanceId==draggedItemInstanceId)
            {
                DrawEmptyItemSlot(rect);
                BombBrickUiTheme.Frame(rect,BombBrickUiTheme.Cyan,2f);
            }
            else
            {
                DrawItemIcon(rect,item,1);
                if(instance.temporary)DrawTemporaryItemBadge(rect);
                if(instance.transformState==ExpeditionItemTransformState.Radiant)
                {
                    DrawRadiantItemFrame(rect);
                    if(rect.Contains(current.mousePosition))hoveredItemTooltip=
                        ExpeditionItemTransformSystem.ResolveEffectiveMaster(instance);
                }
                if(!battleStarted&&current.type==EventType.MouseDown&&current.button==0&&
                   rect.Contains(current.mousePosition))
                {
                    BeginItemDrag(instanceId);
                    current.Use();
                }
            }
        }
    }

    private void DrawGrowthShopBagTab()
    {
        if(!CanOpenGrowthShop)return;
        Rect button=GrowthShopButtonRect;
        Rect tab=GrowthShopTabRect;
        BombBrickUiTheme.Fill(tab,BombBrickUiTheme.SurfaceRaised);
        BombBrickUiTheme.Frame(tab,BombBrickUiTheme.Lime,1f);
        GUI.Label(new Rect(tab.x+5f,tab.y,tab.width-10f,tab.height),
            "성장",BombBrickUiTheme.TitleStyle(11,TextAnchor.MiddleCenter));
        bool clicked=BombBrickUiTheme.Button(button,"",true,false);
        if(GUI.Button(tab,GUIContent.none,GUIStyle.none))clicked=true;
        if(clicked)
            OpenGrowthShop(true);
        DrawGrowthShopIcon(new Rect(
            button.x+9f,button.y+9f,button.width-18f,button.height-18f));
    }

    private static void DrawGrowthShopIcon(Rect rect)
    {
        float pixel=Mathf.Max(2f,Mathf.Floor(
            Mathf.Min(rect.width,rect.height)/9f));
        Vector2 center=rect.center;
        Color light=BombBrickUiTheme.Lime;
        BombBrickUiTheme.Fill(new Rect(
            center.x-pixel*.5f,center.y-pixel*3f,pixel,pixel),light);
        BombBrickUiTheme.Fill(new Rect(
            center.x-pixel*1.5f,center.y-pixel*2f,pixel*3f,pixel),light);
        BombBrickUiTheme.Fill(new Rect(
            center.x-pixel*2.5f,center.y-pixel,pixel*5f,pixel),light);
        BombBrickUiTheme.Fill(new Rect(
            center.x-pixel*.5f,center.y,pixel,pixel*3f),light);
        BombBrickUiTheme.Fill(new Rect(
            center.x-pixel*1.5f,center.y+pixel*2f,pixel*3f,pixel),
            new Color(0.48f,0.72f,0.18f,1f));
    }

    private void BeginItemDrag(string instanceId)
    {
        draggedItemInstanceId=instanceId;
        draggingItem=!string.IsNullOrEmpty(instanceId);
        ResetFusionHold();
        itemUiMessage="";
    }

    private void DrawDraggedItemOverlay(List<KeyValuePair<string,List<string>>> stacks)
    {
        if(string.IsNullOrEmpty(draggedItemInstanceId)||!draggingItem)return;
        ExpeditionItemInstanceSave dragged=ExpeditionItemSystem.ItemInstance(expeditionRun,draggedItemInstanceId);
        ItemMasterRow draggedMaster=dragged==null?null:GameMasterData.Item(dragged.itemId);
        if(draggedMaster==null)return;
        Vector2 mouse=Event.current.mousePosition;
        const float iconSize=66f;
        Rect draggedRect=DragTokenRect(mouse,iconSize);
        DrawItemIcon(draggedRect,draggedMaster,1);
        if(dragged.temporary)DrawTemporaryItemBadge(draggedRect);
        if(dragged.transformState==ExpeditionItemTransformState.Radiant)
            DrawRadiantItemFrame(draggedRect);
        string targetId=InventoryItemAt(mouse,stacks,draggedItemInstanceId);
        ItemMasterRow preview=FusionPreviewAt(mouse,stacks,draggedItemInstanceId);
        if(preview!=null)
        {
            if(fusionHoverTargetId!=targetId)
            {
                fusionHoverTargetId=targetId;
                fusionHoldStartedAt=Time.unscaledTime;
            }
            float progress=FirstItemCombineGuideVisible
                ?1f:FusionHoldProgress();
            Rect safe=UiLayout.safeArea;
            float resultY=Mathf.Clamp(
                draggedRect.y,safe.y+8f,
                Mathf.Max(safe.y+8f,safe.yMax-iconSize-8f));
            bool placeRight=draggedRect.xMax+38f+iconSize<=safe.xMax-8f;
            float resultX=placeRight
                ?draggedRect.xMax+38f
                :draggedRect.x-38f-iconSize;
            resultX=Mathf.Clamp(
                resultX,safe.x+8f,
                Mathf.Max(safe.x+8f,safe.xMax-iconSize-8f));
            Rect resultRect=new Rect(resultX,resultY,iconSize,iconSize);
            float fusionX=placeRight
                ?Mathf.Lerp(draggedRect.xMax,resultRect.x,0.5f)-12f
                :Mathf.Lerp(resultRect.xMax,draggedRect.x,0.5f)-12f;
            DrawSystemIcon(new Rect(fusionX,resultRect.center.y-12f,24f,24f),
                "fusion",BombBrickUiTheme.Orange,false);
            DrawItemIcon(resultRect,preview,1);
            float groupLeft=Mathf.Min(draggedRect.x,resultRect.x);
            float groupRight=Mathf.Max(draggedRect.xMax,resultRect.xMax);
            float barY=Mathf.Max(draggedRect.yMax,resultRect.yMax)+7f;
            if(barY+7f>safe.yMax-8f)
                barY=Mathf.Min(draggedRect.y,resultRect.y)-14f;
            Rect bar=BombBrickUiLayout.ClampRect(
                new Rect(groupLeft,barY,
                    Mathf.Min(groupRight-groupLeft,safe.width-16f),7f),
                safe,8f);
            BombBrickUiTheme.Fill(bar,new Color(0.03f,0.045f,0.07f,0.98f));
            BombBrickUiTheme.Fill(new Rect(bar.x+1f,bar.y+1f,
                (bar.width-2f)*progress,bar.height-2f),
                progress>=1f?BombBrickUiTheme.Lime:BombBrickUiTheme.Orange);
            BombBrickUiTheme.Frame(bar,BombBrickUiTheme.Border,1f);
            Rect tooltip=DrawItemTooltip(preview,resultRect.center);
            itemFusionPreviewRect=UnionRect(
                UnionRect(draggedRect,resultRect),UnionRect(bar,tooltip));
        }
        else ResetFusionHold();
    }

    private void CompleteItemDrop(Vector2 mouse,List<KeyValuePair<string,List<string>>> stacks)
    {
        string sourceId=draggedItemInstanceId;
        string fusionTargetId=InventoryItemAt(mouse,stacks,sourceId);
        ItemMasterRow fusionPreview=FusionPreviewAt(mouse,stacks,sourceId);
        bool fusionReady=!string.IsNullOrEmpty(fusionTargetId)&&
            fusionTargetId==fusionHoverTargetId&&fusionPreview!=null&&
            (FirstItemCombineGuideVisible||FusionHoldProgress()>=1f);
        draggedItemInstanceId="";draggingItem=false;
        ResetFusionHold();
        ExpeditionItemInstanceSave source=ExpeditionItemSystem.ItemInstance(expeditionRun,sourceId);
        if(source==null)return;
        ItemMasterRow sourceMaster=GameMasterData.Item(source.itemId);
        if(FirstItemCombineGuideVisible&&sourceMaster?.IsBase!=true)
        {
            itemUiMessage="기본 아이템 두 개를 합성하세요.";
            return;
        }
        if(FirstItemEquipGuideVisible&&sourceMaster?.IsCompleted!=true)
        {
            itemUiMessage="완성 아이템을 아군에게 장착하세요.";
            return;
        }
        Unit transferOwner=null;
        if(FirstItemTransferGuideVisible&&
           (sourceMaster?.IsCompleted!=true||
            !TryFindEquippedSlot(sourceId,out transferOwner,out _)))
        {
            itemUiMessage="정보창의 착용 아이템을 드래그하세요.";
            return;
        }

        Unit slotTarget=inspectedUnit!=null&&inspectedUnit.team==Team.Player?inspectedUnit:null;
        if(slotTarget!=null&&!FirstItemCombineGuideVisible&&
           !FirstItemTransferGuideVisible)
        {
            Rect row=SelectedUnitSlotRowRect(slotTarget);
            for(int slot=0;slot<ExpeditionItemSystem.MaxSlots;slot++)
            {
                if(!new Rect(row.x+slot*58f,row.y,52f,48f).Contains(mouse))continue;
                EquipItemToSlot(slotTarget,sourceId,slot);
                return;
            }
        }

        Unit monsterTarget=PlayerUnitAtGuiPoint(mouse);
        if(monsterTarget!=null&&!FirstItemCombineGuideVisible)
        {
            if(FirstItemTransferGuideVisible&&monsterTarget==transferOwner)
            {
                itemUiMessage="다른 아군에게 아이템을 옮기세요.";
                return;
            }
            ExpeditionMonsterStateSave state=ExpeditionItemSystem.MonsterState(expeditionRun,monsterTarget.stableId);
            int empty=state.itemInstanceIds.FindIndex(string.IsNullOrEmpty);
            if(empty<0){itemUiMessage="빈 슬롯이 없습니다.";return;}
            EquipItemToSlot(monsterTarget,sourceId,empty);
            return;
        }

        if(!string.IsNullOrEmpty(fusionTargetId))
        {
            if(FirstItemEquipGuideVisible||FirstItemTransferGuideVisible)
            {
                itemUiMessage=FirstItemTransferGuideVisible
                    ?"완성 아이템을 다른 아군에게 옮기세요."
                    :"완성 아이템을 아군에게 장착하세요.";
                return;
            }
            if(fusionPreview==null)
            {
                itemUiMessage="조합할 수 없는 아이템입니다.";
                return;
            }
            if(!fusionReady)
            {
                itemUiMessage="합성 게이지가 가득 찬 뒤 놓아주세요.";
                return;
            }
            if(ExpeditionItemSystem.TryFuse(expeditionRun,sourceId,fusionTargetId,
                out ExpeditionItemInstanceSave result,out itemUiMessage))
            {
                ItemMasterRow resultMaster=GameMasterData.Item(result.itemId);
                itemUiMessage=(resultMaster==null?result.itemId:resultMaster.displayName)+" 조합 완료";
                RefreshAllPlayerItemStats();
                SaveExpeditionCheckpoint(
                    ExpeditionRunCheckpoint.Preparation,true);
                if(FirstItemCombineGuideVisible)
                {
                    SetFirstExpeditionBattleTutorialStep(5,6);
                    itemUiMessage=(resultMaster==null?result.itemId:
                        resultMaster.displayName)+" 조합 완료";
                }
            }
            return;
        }

        if(ItemBarRect.Contains(mouse)&&TryFindEquippedSlot(sourceId,out Unit owner,out int ownerSlot))
        {
            if(FirstItemTransferGuideVisible)
            {
                itemUiMessage="다른 아군에게 직접 옮기세요.";
                return;
            }
            ExpeditionItemSystem.Unequip(expeditionRun,owner.stableId,ownerSlot,out itemUiMessage);
            RefreshUnitFromOwnedData(owner,owner.definition,owner.ownedInstance);
            itemUiMessage="탐험 가방으로 이동했습니다.";
            SaveExpeditionCheckpoint(
                ExpeditionRunCheckpoint.Preparation,true);
            return;
        }
        itemUiMessage="아이템 이동을 취소했습니다.";
    }

    private float FusionHoldProgress()
    {
        if(fusionHoldStartedAt<0f||string.IsNullOrEmpty(fusionHoverTargetId))return 0f;
        return Mathf.Clamp01((Time.unscaledTime-fusionHoldStartedAt)/FusionHoldDuration);
    }

    private void ResetFusionHold()
    {
        fusionHoverTargetId="";
        fusionHoldStartedAt=-1f;
    }

    private void EquipItemToSlot(Unit target,string instanceId,int slot)
    {
        ExpeditionItemInstanceSave instance=
            ExpeditionItemSystem.ItemInstance(expeditionRun,instanceId);
        ItemMasterRow item=GameMasterData.Item(instance==null?"":instance.itemId);
        bool completesTutorial=FirstItemEquipGuideVisible&&item?.IsCompleted==true;
        TryFindEquippedSlot(instanceId,out Unit previousOwner,out _);
        bool completesTransfer=IsValidFirstTutorialItemTransfer(
            FirstItemTransferGuideVisible,item?.IsCompleted==true,
            previousOwner==null?"":previousOwner.stableId,
            target==null?"":target.stableId);
        if(!ExpeditionItemSystem.Equip(
            expeditionRun,target.stableId,instanceId,slot,out itemUiMessage))return;
        inspectedUnit=target;
        RefreshAllPlayerItemStats();
        itemUiMessage=target.displayName+"의 "+(slot+1)+"번 슬롯에 장착했습니다.";
        SaveExpeditionCheckpoint(
            ExpeditionRunCheckpoint.Preparation,true);
        if(completesTutorial)
        {
            SetFirstExpeditionBattleTutorialStep(6,7);
            inspectedUnit=target;
            itemUiMessage=target.displayName+"에게 "+item.displayName+
                          "을 장착했습니다.";
        }
        else if(completesTransfer)
        {
            SetFirstExpeditionBattleTutorialStep(7,8);
            inspectedUnit=target;
            itemUiMessage=item.displayName+"을 "+target.displayName+
                          "에게 옮겼습니다.";
        }
    }

    public static bool IsValidFirstTutorialItemTransfer(
        bool tutorialActive,bool completedItem,
        string previousOwnerId,string targetOwnerId)
    {
        return tutorialActive&&completedItem&&
               !string.IsNullOrEmpty(previousOwnerId)&&
               !string.IsNullOrEmpty(targetOwnerId)&&
               previousOwnerId!=targetOwnerId;
    }

    private Unit PlayerUnitAtGuiPoint(Vector2 point)
    {
        Unit best=null;float bestDistance=float.MaxValue;
        foreach(Unit unit in units)
        {
            if(unit.team!=Team.Player||!unit.alive||unit.model==null||!unit.model.activeInHierarchy)continue;
            if(!TryGetUnitGuiRect(unit,out Rect rect)||!rect.Contains(point))continue;
            float distance=Vector2.Distance(point,rect.center);
            if(distance>=bestDistance)continue;
            bestDistance=distance;best=unit;
        }
        return best;
    }

    private string InventoryItemAt(
        Vector2 mouse,List<KeyValuePair<string,List<string>>> stacks,string excludedId)
    {
        Rect viewport=ItemInventoryViewportRect;
        if(!viewport.Contains(mouse))return "";
        float localX=mouse.x-viewport.x+itemBarScroll.x;
        int index=Mathf.FloorToInt((localX-4f)/74f);
        if(index<0||index>=stacks.Count)return "";
        List<string> ids=stacks[index].Value;
        return ids.FirstOrDefault(id=>id!=excludedId)??"";
    }

    private ItemMasterRow FusionPreviewAt(
        Vector2 mouse,List<KeyValuePair<string,List<string>>> stacks,string sourceId)
    {
        ExpeditionItemInstanceSave source=ExpeditionItemSystem.ItemInstance(expeditionRun,sourceId);
        string targetId=InventoryItemAt(mouse,stacks,sourceId);
        ExpeditionItemInstanceSave target=ExpeditionItemSystem.ItemInstance(expeditionRun,targetId);
        return source==null||target==null?null:
            ExpeditionItemSystem.PreviewRecipe(source.itemId,target.itemId);
    }

    private bool TryFindEquippedSlot(string itemInstanceId,out Unit owner,out int slot)
    {
        foreach(Unit unit in units)
        {
            if(unit.team!=Team.Player)continue;
            ExpeditionMonsterStateSave state=ExpeditionItemSystem.MonsterState(expeditionRun,unit.stableId);
            int found=state==null?-1:state.itemInstanceIds.IndexOf(itemInstanceId);
            if(found<0)continue;
            owner=unit;slot=found;return true;
        }
        owner=null;slot=-1;return false;
    }

    private void ClearPreparationSelection()
    {
        if(draggingUnit)CancelDraggedUnit();
        pressedUnit=null;
        SetSelectedUnit(null);
        inspectedUnit=null;
        draggedItemInstanceId="";
        draggingItem=false;
        ResetFusionHold();
        draggedSpecialItemInstanceId="";
        draggingSpecialItem=false;
        itemUiMessage="";
    }

    public bool TryClosePreparationShop()
    {
        if(mlEpisodeActive||battleStarted||expeditionRun==null)return false;
        if(!GrowthShopVisible&&!shopVisible)return false;
        PrepareForSystemMenu();
        if(GrowthShopVisible)CompleteGrowthShop();
        else CloseShop();
        return true;
    }

    public void PrepareForSystemMenu()
    {
        StopFamilyRank4CinematicAudio();raptorCinematicStage?.Hide();
        FinishRank4Cinematic();
        EndAllyPreparationSequence();
        CancelRaptorApexCinematic();
        ClearInterruptedInput();
    }

    private void ClearInterruptedInput()
    {
        if(mlEpisodeActive)return;
        if(draggingUnit)CancelDraggedUnit();
        pressedUnit=null;
        draggedItemInstanceId="";
        draggingItem=false;
        draggedSpecialItemInstanceId="";
        draggingSpecialItem=false;
        draggingCaptureNet=false;
        draggedCaptureNetItemId="";
        ResetFusionHold();
        ClearPlacementHover();
    }

    private void RefreshAllPlayerItemStats()
    {
        foreach(Unit unit in units)
            if(unit.team==Team.Player&&unit.ownedInstance!=null)
                RefreshUnitFromOwnedData(unit,unit.definition,unit.ownedInstance);
    }

    private void GrantDebugBasicItems()
    {
        foreach(ItemMasterRow item in GameMasterData.ItemsInPool("default_equipment"))
            ExpeditionItemSystem.CreateItem(expeditionRun,item.id);
        itemUiMessage="개발 확인용 기본 아이템 6종 지급 (F8)";
    }

    private static string CompactItemStats(ItemMasterRow item)
    {
        List<string> values=new List<string>();
        if(item.attackDamageBonus!=0f)values.Add(GameLocalization.Format(
            "tooltip.item.stat.attack","공격 {0}",SignedPercent(item.attackDamageBonus)));
        if(item.attackSpeedBonus!=0f)values.Add(GameLocalization.Format(
            "tooltip.item.stat.attack_speed","공속 {0}",SignedPercent(item.attackSpeedBonus)));
        if(item.maxHealthBonus!=0f)values.Add(GameLocalization.Format(
            "tooltip.item.stat.health","체력 {0}",SignedPercent(item.maxHealthBonus)));
        if(item.damageReductionBonus!=0f)values.Add(GameLocalization.Format(
            "tooltip.item.stat.damage_reduction","피감 {0}",SignedPercent(item.damageReductionBonus)));
        if(item.criticalChance!=0f)values.Add(GameLocalization.Format(
            "tooltip.item.stat.critical","치명 {0}",SignedPercent(item.criticalChance)));
        if(item.skillPowerBonus!=0f)values.Add(GameLocalization.Format(
            "tooltip.item.stat.skill_power","스킬 {0}",SignedPercent(item.skillPowerBonus)));
        if(item.defenseBonus!=0f)values.Add(GameLocalization.Format(
            "tooltip.item.stat.defense","방어 +{0}",item.defenseBonus.ToString("0")));
        if(item.statusResistanceBonus!=0f)values.Add(GameLocalization.Format(
            "tooltip.item.stat.resistance","저항 +{0}",item.statusResistanceBonus.ToString("0")));
        if(item.skillCooldownReductionBonus!=0f)values.Add(GameLocalization.Format(
            "tooltip.item.stat.cooldown_speed","재사용 속도 {0}",
            SignedPercent(item.skillCooldownReductionBonus)));
        return values.Count==0
            ?GameLocalization.TextByKey("tooltip.item.special_effect","특수 효과")
            :string.Join(", ",values);
    }

    private static string SignedPercent(float value)
    {
        return (value>=0f?"+":"")+(value*100f).ToString("0")+"%";
    }

    private static string ShortItemName(string value)
    {
        if(string.IsNullOrEmpty(value))return "?";
        value=GameLocalization.Text(value);
        return value.Length<=7?value:value.Substring(0,7);
    }

    private static TraitMasterRow TraitMaster(string traitId)
    {
        GameMasterDatabase database=GameMasterData.Database;
        return database==null||database.traits==null?null:
            database.traits.FirstOrDefault(row=>row!=null&&row.enabled&&
                string.Equals(row.id,traitId,StringComparison.Ordinal));
    }

    private static string TraitName(string traitId)
    {
        MonsterTraitDefinition trait=MonsterTraitCatalog.Get(traitId);
        return trait==null?(string.IsNullOrWhiteSpace(traitId)?"-":traitId):trait.displayName;
    }

    private static string IntrinsicTraitName(string traitId)
    {
        if(string.IsNullOrWhiteSpace(traitId))return "-";
        TraitMasterRow master=TraitMaster(traitId);
        if(master!=null&&!string.IsNullOrWhiteSpace(master.displayName))
            return master.displayName;
        MonsterTraitDefinition catalog=MonsterTraitCatalog.Get(traitId);
        if(catalog!=null&&!string.IsNullOrWhiteSpace(catalog.displayName))
            return catalog.displayName;
        string[] names=
        {
            RaptorCombatRules.DisplayName(traitId),FrogCombatRules.DisplayName(traitId),
            KingKongCombatRules.DisplayName(traitId),GiraffeCombatRules.DisplayName(traitId),
            CrocodileCombatRules.DisplayName(traitId),JaguarCombatRules.DisplayName(traitId),
            BearCombatRules.DisplayName(traitId),GriffinCombatRules.DisplayName(traitId),
            SpiderCombatRules.DisplayName(traitId),WolfCombatRules.DisplayName(traitId),
            NinjaCatCombatRules.DisplayName(traitId),TyrannoCombatRules.DisplayName(traitId),
            MonkeyCombatRules.DisplayName(traitId),MantisCombatRules.DisplayName(traitId),
            MushroomCombatRules.DisplayName(traitId),MammothCombatRules.DisplayName(traitId),
            BeetleCombatRules.DisplayName(traitId),SpiritDeerCombatRules.DisplayName(traitId),
            WyvernCombatRules.DisplayName(traitId),HaetaeCombatRules.DisplayName(traitId)
        };
        return names.FirstOrDefault(name=>!string.Equals(name,traitId,StringComparison.Ordinal))??traitId;
    }

    private void DrawGrowthShop()
    {
        bool tutorialGuide=FirstGrowthShopGuideVisible;
        bool tutorialNeedsChoice=tutorialGuide&&
            growthShopSelectedMonsterIds.Count==0;
        bool tutorialNeedsConfirm=tutorialGuide&&!tutorialNeedsChoice;
        int researchRerollCost=ExpeditionGrowthSystem.RerollCostFor(
            expeditionRun,playerProfile);
        int blessingGrowthBonus=ExpeditionAugmentRuntime.BlessingGrowthBonus(
            expeditionRun,expeditionRun.wave);
        Color growthAccent=blessingGrowthBonus>0
            ?FickleBlessingColor(2):BombBrickUiTheme.Lime;
        float transitionAge=Mathf.Max(0f,Time.unscaledTime-
            growthShopTransitionStartedAt);
        float transitionDuration=growthShopClosing
            ?GrowthShopCloseDuration:GrowthShopOpenDuration;
        float rawTransition=Mathf.Clamp01(
            transitionAge/Mathf.Max(.01f,transitionDuration));
        float panelT=growthShopClosing
            ?1f-BombBrickUiTheme.EaseOutCubic(rawTransition)
            :BombBrickUiTheme.EaseOutCubic(rawTransition);
        Rect safe=UiLayout.safeArea;
        float width=Mathf.Min(1180f,safe.width-20f);
        float height=Mathf.Min(safe.height-72f,
            Mathf.Clamp(safe.height*.40f,360f,380f));
        Rect panel=new Rect(
            safe.center.x-width*.5f,
            Mathf.Lerp(safe.yMax+6f,safe.yMax-height-8f,panelT),
            width,height);
        bool previousEnabled=GUI.enabled;
        bool interactive=!growthShopClosing&&rawTransition>=.9f;
        BombBrickUiTheme.DrawPanel(panel,true);
        BombBrickUiTheme.Fill(new Rect(panel.x,panel.y,panel.width,5f),
            growthAccent);

        DrawGrowthShopIcon(new Rect(panel.x+18f,panel.y+13f,34f,34f));
        GUI.Label(new Rect(panel.x+62f,panel.y+10f,240f,24f),
            GameLocalization.Format(
                "growth.shop_wave","성장 상점  ·  W {0}",expeditionRun.wave),
            BombBrickUiTheme.TitleStyle(18));
        GUI.Label(new Rect(panel.x+62f,panel.y+32f,420f,18f),
            blessingGrowthBonus>0
                ?GameLocalization.Format(
                    "growth.blessing_bonus","성장의 축복 · 성장량 +{0}",
                    blessingGrowthBonus)
                :"첫 성장 무료 · 이후 골드",
            BombBrickUiTheme.CaptionStyle(10));
        bool headerCanReroll=!tutorialGuide&&
            expeditionRun.expeditionCurrency>=
            researchRerollCost&&interactive;
        GUI.enabled=previousEnabled&&headerCanReroll;
        if(BombBrickUiTheme.Button(new Rect(
            panel.xMax-322f,panel.y+12f,120f,36f),
            GameLocalization.Format(
                "growth.reroll","리롤  {0}",
                researchRerollCost),true,false))
            RerollGrowthShop();
        GUI.enabled=previousEnabled&&interactive;
        Rect goldRect=new Rect(panel.xMax-190f,panel.y+11f,132f,38f);
        BombBrickUiTheme.Fill(goldRect,BombBrickUiTheme.SurfaceRaised);
        float rerollAge=Time.unscaledTime-growthShopRerollFeedbackStartedAt;
        bool rerollFeedback=growthShopRerollFeedbackStartedAt>=0f&&
            rerollAge<0.8f;
        float rerollPulse=rerollFeedback
            ?0.5f+0.5f*Mathf.Sin(rerollAge*22f):0f;
        if(rerollFeedback)
            BombBrickUiTheme.Frame(goldRect,
                Color.Lerp(BombBrickUiTheme.Orange,BombBrickUiTheme.Red,rerollPulse),2f);
        DrawSystemIcon(new Rect(goldRect.x+8f,goldRect.y+7f,24f,24f),
            "gold",BombBrickUiTheme.Orange,false);
        GUI.Label(new Rect(goldRect.x+38f,goldRect.y+2f,goldRect.width-46f,32f),
            expeditionRun.expeditionCurrency.ToString(),
            BombBrickUiTheme.TitleStyle(18,TextAnchor.MiddleRight));
        if(rerollFeedback)
        {
            float alpha=1f-Mathf.Clamp01(rerollAge/0.8f);
            BombBrickUiTheme.Label(new Rect(goldRect.x,goldRect.yMax+2f,
                goldRect.width,20f),"-"+researchRerollCost,
                BombBrickUiTheme.TitleStyle(13,TextAnchor.MiddleRight),
                new Color(BombBrickUiTheme.Red.r,BombBrickUiTheme.Red.g,
                    BombBrickUiTheme.Red.b,alpha));
        }
        List<ExpeditionMonsterStateSave> roster=
            ExpeditionGrowthSystem.ShopCandidates(expeditionRun);
        bool canClose=!tutorialGuide;
        GUI.enabled=previousEnabled&&interactive&&canClose;
        if(BombBrickUiTheme.Button(new Rect(
            panel.xMax-48f,panel.y+14f,30f,30f),"×",true,false))
            CompleteGrowthShop();
        GUI.enabled=previousEnabled&&interactive;
        BombBrickUiTheme.Fill(new Rect(panel.x+16f,panel.y+58f,
            panel.width-32f,1f),BombBrickUiTheme.Border);

        if(growthShopCardsRevealStartedAt<0f)
            growthShopCardsRevealStartedAt=Time.unscaledTime;
        float cardsRevealElapsed=
            Time.unscaledTime-growthShopCardsRevealStartedAt;
        const float gap=10f;
        float gridTop=panel.y+68f;
        float cardWidth=(panel.width-32f-gap*Mathf.Max(0,roster.Count-1))/
            Mathf.Max(1,roster.Count);
        float cardHeight=panel.yMax-54f-gridTop;
        GUI.enabled=previousEnabled&&interactive&&!tutorialNeedsConfirm;
        for(int index=0;index<roster.Count;index++)
        {
            ExpeditionMonsterStateSave state=roster[index];
            Rect card=new Rect(
                panel.x+16f+index*(cardWidth+gap),gridTop,cardWidth,cardHeight);
            if(expeditionRun.growthShopPurchasedMonsterIds.Contains(
                   state.instanceId))
                DrawEmptyGrowthShopSlot(card);
            else DrawGrowthShopMonsterCard(
                card,state,index,cardsRevealElapsed);
        }
        GUI.enabled=previousEnabled&&interactive;

        int selectedCount=growthShopSelectedMonsterIds.Count;
        int selectionCost=ExpeditionGrowthSystem.SelectionCost(
            expeditionRun,growthShopSelectedMonsterIds);
        bool canConfirm=selectedCount>0&&
            expeditionRun.expeditionCurrency>=selectionCost&&
            cardsRevealElapsed>=0.45f&&interactive;
        string footer=selectedCount==0
            ?"성장시킬 몬스터를 선택하세요."
            :GameLocalization.Format(
                "growth.selection_cost","선택 {0}  ·  비용 {1} 골드",
                selectedCount,selectionCost);
        GUI.Label(new Rect(panel.x+18f,panel.yMax-43f,
            panel.width-240f,30f),footer,
            BombBrickUiTheme.CaptionStyle(11,TextAnchor.MiddleLeft));
        string confirmLabel=selectionCost==0
            ?"성장 확정 · 무료":GameLocalization.Format(
                "growth.confirm","성장 확정 · {0}",selectionCost);
        Rect confirmRect=new Rect(
            panel.xMax-218f,panel.yMax-45f,200f,34f);
        GUI.enabled=previousEnabled&&canConfirm;
        if(BombBrickUiTheme.Button(confirmRect,
            confirmLabel,true,true))
            PurchaseSelectedGrowth();
        GUI.enabled=previousEnabled;
        if(tutorialGuide)
        {
            Rect cardTarget=new Rect(panel.x+10f,gridTop-6f,
                panel.width-20f,cardHeight+12f);
            DrawGrowthShopTutorialGuide(
                tutorialNeedsChoice?cardTarget:confirmRect,
                tutorialNeedsChoice
                    ?"성장시킬 몬스터를 선택하세요."
                    :"성장 확정을 눌러 적용하세요.");
        }
    }

    private static void DrawEmptyGrowthShopSlot(Rect card)
    {
        BombBrickUiTheme.Fill(card,new Color(0.015f,0.02f,0.015f,0.96f));
        BombBrickUiTheme.Frame(card,
            new Color(BombBrickUiTheme.Border.r,
                BombBrickUiTheme.Border.g,BombBrickUiTheme.Border.b,0.55f),1f);
    }

    private void DrawGrowthShopTutorialGuide(Rect target,string message)
    {
        float blink=Mathf.PingPong(Time.unscaledTime*2.2f,1f);
        Color accent=Color.Lerp(
            BombBrickUiTheme.Lime,Color.white,0.18f+blink*0.42f);
        Rect focus=new Rect(target.x-4f,target.y-4f,
            target.width+8f,target.height+8f);
        DrawCaptureGuideShade(focus,0.68f);
        BombBrickUiTheme.Frame(focus,accent,3f);

        Rect safe=UiLayout.safeArea;
        float width=Mathf.Min(390f,safe.width-24f);
        Rect hint=new Rect(
            Mathf.Clamp(focus.center.x-width*.5f,
                safe.x+8f,safe.xMax-width-8f),
            Mathf.Max(safe.y+8f,focus.y-52f),width,42f);
        BombBrickUiTheme.DrawPanel(hint,true);
        BombBrickUiTheme.Fill(new Rect(hint.x,hint.y,4f,hint.height),accent);
        GUI.Label(new Rect(hint.x+14f,hint.y+4f,hint.width-28f,hint.height-8f),
            message,BombBrickUiTheme.TitleStyle(13,TextAnchor.MiddleCenter));
    }

    private void DrawGrowthShopMonsterCard(
        Rect card,ExpeditionMonsterStateSave state,int index,float revealElapsed)
    {
        int selectedIndex=growthShopSelectedMonsterIds.IndexOf(state.instanceId);
        bool selected=selectedIndex>=0;
        float revealT=selected?1f:
            Mathf.Clamp01((revealElapsed-0.14f-index*0.09f)/0.38f);
        if(revealT<=0f)return;
        float eased=BombBrickUiTheme.EaseOutBack(revealT,0.72f);
        card.y+=Mathf.Lerp(64f,0f,eased);
        bool hovered=revealT>=0.9f&&card.Contains(Event.current.mousePosition);
        Matrix4x4 previousMatrix=GUI.matrix;
        float scale=Mathf.Lerp(0.96f,1f,eased);
        GUIUtility.ScaleAroundPivot(new Vector2(scale,scale),card.center);

        Unit unit=units.FirstOrDefault(value=>value!=null&&
            value.team==Team.Player&&value.stableId==state.instanceId);
        OwnedMonsterSave owned=unit==null&&playerProfile!=null
            ?playerProfile.monsters.FirstOrDefault(value=>value!=null&&
                value.instanceId==state.instanceId)
            :unit==null?null:unit.ownedInstance;
        MonsterDefinition definition=unit==null
            ?monsterDatabase.Get(state.monsterId):unit.definition;
        bool purchased=expeditionRun.growthShopPurchasedMonsterIds.Contains(
            state.instanceId);
        bool maximum=state.growthTotal>=ExpeditionGrowthSystem.MaximumGrowth;
        int offer=Mathf.Min(ExpeditionGrowthSystem.OfferAmount(
            expeditionRun,state.instanceId),
            ExpeditionGrowthSystem.MaximumGrowth-state.growthTotal);
        int cost=ExpeditionGrowthSystem.PurchaseCost(offer);
        Color accent=state.rank>=ExpeditionMonsterRank.Rank3
            ?BombBrickUiTheme.Violet
            :state.rank>=ExpeditionMonsterRank.Rank2
                ?BombBrickUiTheme.Cyan:BombBrickUiTheme.Lime;
        float feedbackAge=Time.unscaledTime-growthShopFeedbackStartedAt;
        bool feedback=state.instanceId==growthShopFeedbackMonsterId&&
            growthShopFeedbackStartedAt>=0f&&
            feedbackAge<GrowthShopFeedbackDuration;
        float feedbackT=feedback
            ?Mathf.Clamp01(feedbackAge/GrowthShopFeedbackDuration):0f;
        Color frameAccent=feedback?Color.Lerp(Color.white,BombBrickUiTheme.Lime,feedbackT):
            selected?BombBrickUiTheme.Lime:hovered?BombBrickUiTheme.TextSecondary:BombBrickUiTheme.Border;
        BombBrickUiTheme.Fill(card,selected?new Color(.028f,.045f,.030f):
            hovered?BombBrickUiTheme.SurfaceHover:BombBrickUiTheme.Surface);
        BombBrickUiTheme.Frame(card,frameAccent,selected?2f:1f);
        string grade=owned==null?"-":owned.isShiny
            ?"이로치 110":MonsterStatQuality.OverallGrade(owned);
        float gradeWidth=owned!=null&&owned.isShiny?100f:48f;
        BombBrickUiTheme.Label(new Rect(card.xMax-gradeWidth-16f,card.y+16f,gradeWidth,22f),
            grade,BombBrickUiTheme.TitleStyle(14,TextAnchor.MiddleRight),accent);

        Rect portrait=new Rect(card.x+16f,card.y+16f,64f,64f);
        BombBrickUiTheme.Fill(portrait,BombBrickUiTheme.Backdrop);
        DrawPortrait(new Rect(portrait.x+3f,portrait.y+3f,
            portrait.width-6f,portrait.height-6f),definition,owned);
        float textX=portrait.xMax+16f;
        float textWidth=card.xMax-textX-16f;
        GUI.Label(new Rect(textX,card.y+14f,textWidth-gradeWidth-8f,26f),
            definition==null?state.monsterId:definition.displayName,
            BombBrickUiTheme.TitleStyle(16,TextAnchor.MiddleLeft));
        GUI.Label(new Rect(textX,card.y+40f,textWidth,18f),
            new string('★',PresentationStarCount(state)),
            BombBrickUiTheme.TitleStyle(14,TextAnchor.MiddleLeft));
        MonsterGrowthMasterRow master=GameMasterData.MonsterGrowth(state.monsterId);
        string role=master==null||string.IsNullOrWhiteSpace(master.growthRole)
            ?"균형 성장":master.growthRole;
        GUI.Label(new Rect(textX,card.y+62f,textWidth,18f),
            GameLocalization.Text(role),
            BombBrickUiTheme.CaptionStyle(10,TextAnchor.MiddleLeft));

        float progressY=card.y+96f;
        int growthMaximum=ExpeditionGrowthSystem.MaximumGrowth;
        int offeredUntil=Mathf.Min(
            growthMaximum,state.growthTotal+offer);
        Rect progressHeader=new Rect(card.x+16f,progressY,card.width-32f,20f);
        Color offerColor=new Color(1f,.76f,.34f,
            Mathf.Repeat(Time.unscaledTime,1f)<.5f?1f:0f);
        BombBrickUiTheme.Label(new Rect(progressHeader.x,progressHeader.y,140f,20f),
            offer>0?GameLocalization.Format("growth.feedback","성장 +{0}",offer):"최대 성장",
            BombBrickUiTheme.CaptionStyle(12),new Color(1f,.76f,.34f));
        GUI.Label(new Rect(progressHeader.xMax-150f,progressHeader.y,150f,20f),
            state.growthTotal+(offer>0?" → "+offeredUntil:"")+" / "+growthMaximum,
            BombBrickUiTheme.CaptionStyle(12,TextAnchor.MiddleRight));
        float segmentGap=3f;
        float segmentWidth=(progressHeader.width-segmentGap*(growthMaximum-1))/growthMaximum;
        for(int segment=0;segment<growthMaximum;segment++)
        {
            bool offered=segment>=state.growthTotal&&segment<offeredUntil;
            Rect segmentRect=new Rect(
                progressHeader.x+segment*(segmentWidth+segmentGap),
                progressY+26f,segmentWidth,12f);
            BombBrickUiTheme.Fill(segmentRect,
                offered?offerColor:segment<state.growthTotal?
                    new Color(.25f,.56f,.52f):new Color(.065f,.09f,.085f));
        }

        string preview=GrowthPreviewText(state,owned,offer);
        float previewY=progressY+50f;
        float previewHeight=Mathf.Max(28f,card.yMax-48f-previewY);
        GUI.Label(new Rect(card.x+16f,previewY,card.width-32f,previewHeight),
            preview,BombBrickUiTheme.BodyStyle(12,TextAnchor.MiddleLeft));

        bool freeSelection=selected&&
            !expeditionRun.growthShopFreePurchaseUsed&&selectedIndex==0;
        string label=maximum?"최대 성장":purchased?"이번 Wave 성장 완료":
            selected?(freeSelection?"선택 1 · 무료":GameLocalization.Format(
                "growth.select_paid","선택 {0} · +{1} 골드",
                selectedIndex+1,cost)):
            "카드를 클릭해 선택";
        Rect selectionBar=new Rect(card.x+16f,card.yMax-40f,card.width-32f,26f);
        Rect check=new Rect(selectionBar.x,selectionBar.y+4f,18f,18f);
        BombBrickUiTheme.Frame(check,selected?BombBrickUiTheme.Lime:BombBrickUiTheme.Border,2f);
        if(selected)BombBrickUiTheme.Fill(new Rect(check.x+4f,check.y+4f,10f,10f),BombBrickUiTheme.Lime);
        BombBrickUiTheme.Label(new Rect(selectionBar.x+28f,selectionBar.y,selectionBar.width-28f,26f),
            label,BombBrickUiTheme.CaptionStyle(12,TextAnchor.MiddleLeft),
            selected?BombBrickUiTheme.Lime:BombBrickUiTheme.TextSecondary);
        if(feedback)
        {
            float alpha=1f-feedbackT;
            DrawGuiRing(portrait.center,portrait.width*0.55f+feedbackT*42f,
                new Color(accent.r,accent.g,accent.b,alpha),2.4f,28);
            GUIStyle feedbackStyle=BombBrickUiTheme.TitleStyle(
                16,TextAnchor.MiddleCenter);
            BombBrickUiTheme.Label(new Rect(card.x+12f,
                portrait.y-18f-feedbackT*24f,card.width-24f,24f),
                GameLocalization.Format(
                    "growth.feedback","성장 +{0}",growthShopFeedbackAmount),
                feedbackStyle,
                new Color(1f,1f,1f,alpha));
        }
        bool cardSelectable=(!purchased&&!maximum)||selected;
        bool previousEnabled=GUI.enabled;
        GUI.enabled=previousEnabled&&cardSelectable&&revealT>=0.9f;
        bool clicked=GUI.Button(card,GUIContent.none,GUIStyle.none);
        GUI.enabled=previousEnabled;
        GUI.matrix=previousMatrix;
        if(clicked)
        {
            if(selected)growthShopSelectedMonsterIds.Remove(state.instanceId);
            else growthShopSelectedMonsterIds.Add(state.instanceId);
        }
    }

    private static string GrowthPreviewText(
        ExpeditionMonsterStateSave state,OwnedMonsterSave owned,int offer)
    {
        if(state==null||owned==null||offer<=0)
            return GameLocalization.Text("성장 완료");
        int nextTotal=Mathf.Min(
            ExpeditionGrowthSystem.MaximumGrowth,state.growthTotal+offer);
        ExpeditionMonsterRank nextRank=ExpeditionGrowthSystem.RankForGrowth(
            state.monsterId,nextTotal);
        ExpeditionGrowthBonuses current=ExpeditionGrowthSystem.Bonuses(
            state,owned,state.rank,state.growthTotal);
        ExpeditionGrowthBonuses next=ExpeditionGrowthSystem.Bonuses(
            state,owned,nextRank,nextTotal);
        List<string> gains=new List<string>();
        if(next.maxHealth>current.maxHealth)
            gains.Add(GameLocalization.Format(
                "growth.preview_health","체력 +{0}",
                next.maxHealth-current.maxHealth));
        if(next.attackDamage>current.attackDamage)
            gains.Add(GameLocalization.Format(
                "growth.preview_attack","공격 +{0}",
                next.attackDamage-current.attackDamage));
        if(next.attackSpeedScore>current.attackSpeedScore)
            gains.Add(GameLocalization.Format(
                "growth.preview_attack_speed","공속 +{0}",
                next.attackSpeedScore-current.attackSpeedScore));
        if(next.defense>current.defense)
            gains.Add(GameLocalization.Format(
                "growth.preview_defense","방어 +{0}",
                next.defense-current.defense));
        if(next.statusResistance>current.statusResistance)
            gains.Add(GameLocalization.Format(
                "growth.preview_resistance","저항 +{0}",
                next.statusResistance-current.statusResistance));
        if(nextRank>state.rank)
            gains.Insert(0,GameLocalization.Format(
                "growth.preview_rank","{0} 달성",
                new string('★',(int)nextRank)));
        return gains.Count==0?GameLocalization.Text("누적 후 능력치 상승"):
            string.Join(" · ",gains);
    }

    private void DrawGrowthCardDraft()
    {
        Color previous=GUI.color;
        GUI.color=new Color(0.025f,0.032f,0.052f,0.965f);
        GUI.DrawTexture(new Rect(0f,0f,BombBrickUiLayout.Width,BombBrickUiLayout.Height),Texture2D.whiteTexture);
        GUI.color=previous;

        GUIStyle headerStyle=new GUIStyle(GUI.skin.label)
        {
            alignment=TextAnchor.MiddleCenter,fontStyle=FontStyle.Bold,fontSize=24,
            normal={textColor=new Color(0.93f,0.96f,1f)}
        };
        Rect safe=UiLayout.safeArea;
        GUI.Label(new Rect(safe.x+20f,safe.y+22f,safe.width-40f,32f),
            "W "+expeditionRun.wave+" · 전투 성장",headerStyle);
        GUI.color=new Color(0.78f,0.88f,0.28f,0.9f);
        GUI.DrawTexture(new Rect(safe.center.x-28f,safe.y+58f,56f,3f),Texture2D.whiteTexture);
        GUI.color=previous;

        float gap=Mathf.Clamp(safe.width*0.018f,16f,24f);
        float margin=Mathf.Clamp(safe.width*0.055f,28f,72f);
        float cardWidth=Mathf.Min(292f,(safe.width-margin*2f-gap*2f)/3f);
        float cardHeight=Mathf.Min(cardWidth*1.36f,safe.height-160f);
        cardHeight=Mathf.Max(304f,cardHeight);
        float cardsWidth=cardWidth*growthCardDraft.Count+gap*(growthCardDraft.Count-1);
        float cardsX=safe.center.x-cardsWidth*0.5f;
        float cardsY=safe.y+Mathf.Max(82f,(safe.height-cardHeight)*0.45f);
        float dragThreshold=Mathf.Clamp(cardHeight*0.3f,104f,126f);
        if(growthCardRevealStartedAt<0f)BeginGrowthCardReveal();
        float revealElapsed=Time.unscaledTime-growthCardRevealStartedAt;
        bool revealComplete=revealElapsed>=0.76f;
        Rect[] cardRects=new Rect[growthCardDraft.Count];
        for(int i=0;i<cardRects.Length;i++)
            cardRects[i]=new Rect(cardsX+i*(cardWidth+gap),cardsY,cardWidth,cardHeight);

        if(growthCardDragIndex>=cardRects.Length)ResetGrowthCardDrag();
        Event currentEvent=Event.current;
        if(revealComplete&&growthCardCommittedIndex<0&&
           growthCardDragIndex<0&&
           currentEvent.type==EventType.MouseDown&&currentEvent.button==0)
        {
            for(int i=0;i<cardRects.Length;i++)
            {
                if(!cardRects[i].Contains(currentEvent.mousePosition))continue;
                growthCardDragIndex=i;
                growthCardDragStart=currentEvent.mousePosition;
                growthCardDragVector=Vector2.zero;
                growthCardDragArmed=false;
                currentEvent.Use();
                break;
            }
        }
        else if(growthCardCommittedIndex<0&&growthCardDragIndex>=0&&
                currentEvent.type==EventType.MouseDrag)
        {
            growthCardDragVector=currentEvent.mousePosition-growthCardDragStart;
            growthCardDragArmed=growthCardDragVector.magnitude>=dragThreshold;
            currentEvent.Use();
        }
        else if(growthCardCommittedIndex<0&&growthCardDragIndex>=0&&
                currentEvent.type==EventType.MouseUp&&currentEvent.button==0)
        {
            Vector2 releaseVector=currentEvent.mousePosition-growthCardDragStart;
            growthCardDragVector=releaseVector;
            if(growthCardDragArmed&&releaseVector.magnitude>=dragThreshold)
            {
                growthCardCommittedIndex=growthCardDragIndex;
                growthCardCommitStartedAt=Time.unscaledTime;
            }
            else ResetGrowthCardDrag();
            currentEvent.Use();
        }

        for(int i=0;i<growthCardDraft.Count;i++)
        {
            if(i==growthCardDragIndex)continue;
            DrawGrowthCardChoice(cardRects[i],i,Vector2.zero,dragThreshold,
                revealElapsed,previous);
        }
        if(growthCardDragIndex>=0&&growthCardDragIndex<growthCardDraft.Count)
            DrawGrowthCardChoice(cardRects[growthCardDragIndex],growthCardDragIndex,
                growthCardDragVector,dragThreshold,revealElapsed,previous);

        int rerollCost=GrowthCardRerollCost;
        float footerY=Mathf.Min(safe.yMax-45f,cardsY+cardHeight+14f);
        Rect currencyRect=new Rect(safe.center.x-210f,footerY,112f,34f);
        DrawGrowthCardSolid(currencyRect,new Color(0.075f,0.092f,0.13f,0.98f));
        DrawGrowthCardFrame(currencyRect,new Color(0.25f,0.3f,0.39f,0.8f),1f);
        GUIStyle footerStyle=new GUIStyle(GUI.skin.label)
        {
            alignment=TextAnchor.MiddleCenter,fontSize=13,
            normal={textColor=new Color(0.78f,0.83f,0.9f)}
        };
        DrawSystemIcon(new Rect(currencyRect.x+12f,currencyRect.y+6f,22f,22f),
            "gold",BombBrickUiTheme.Orange,false);
        GUI.Label(new Rect(currencyRect.x+38f,currencyRect.y,
            currencyRect.width-48f,currencyRect.height),
            expeditionRun.expeditionCurrency.ToString(),footerStyle);

        bool canReroll=!growthCardDraftRerolled&&expeditionRun.expeditionCurrency>=rerollCost;
        string rerollLabel=growthCardDraftRerolled
            ?"새로고침 사용 완료"
            :"선택지 새로고침  ·  "+rerollCost;
        Rect rerollRect=new Rect(safe.center.x-86f,footerY,296f,34f);
        bool rerollHover=canReroll&&rerollRect.Contains(Event.current.mousePosition);
        DrawGrowthCardSolid(rerollRect,canReroll
            ?(rerollHover?new Color(0.16f,0.2f,0.27f,1f):new Color(0.105f,0.13f,0.18f,1f))
            :new Color(0.07f,0.08f,0.1f,0.8f));
        DrawGrowthCardFrame(rerollRect,canReroll
            ?new Color(0.38f,0.5f,0.64f,0.9f)
            :new Color(0.2f,0.23f,0.28f,0.7f),1f);
        GUI.enabled=canReroll&&growthCardDragIndex<0&&
            growthCardCommittedIndex<0&&revealComplete;
        GUIStyle rerollStyle=new GUIStyle(footerStyle)
        {
            fontStyle=FontStyle.Bold,
            normal={textColor=canReroll
                ?new Color(0.86f,0.91f,0.97f)
                :new Color(0.4f,0.43f,0.49f)}
        };
        DrawSystemIcon(new Rect(rerollRect.x+12f,rerollRect.y+6f,22f,22f),
            "reroll",canReroll?BombBrickUiTheme.Cyan:
                new Color(0.35f,0.38f,0.44f),false);
        if(GUI.Button(new Rect(rerollRect.x+40f,rerollRect.y,
            rerollRect.width-40f,rerollRect.height),rerollLabel,rerollStyle))
            RerollGrowthCardDraft();
        GUI.enabled=true;

        if(growthCardCommittedIndex>=0&&
           Time.unscaledTime-growthCardCommitStartedAt>=GrowthCardCommitDuration)
        {
            int selectedIndex=growthCardCommittedIndex;
            growthCardCommittedIndex=-1;
            growthCardCommitStartedAt=-1f;
            SelectGrowthCard(selectedIndex);
            return;
        }
    }

    private void DrawGrowthCardChoice(Rect baseRect,int index,Vector2 dragVector,
        float dragThreshold,float revealElapsed,Color previous)
    {
        CombatGrowthCardDraftEntry entry=growthCardDraft[index];
        CombatGrowthCardDefinition definition=CombatGrowthCardCatalog.Get(entry.cardId);
        if(definition==null)return;

        float revealDelay=index*0.1f;
        float revealT=Mathf.Clamp01((revealElapsed-revealDelay)/0.48f);
        if(revealT<=0f)return;
        float spreadT=1f-Mathf.Pow(1f-revealT,3f);
        float revealScale=GrowthCardBackEase(revealT);
        Rect safe=UiLayout.safeArea;
        Vector2 stackedCenter=new Vector2(
            safe.center.x+(index-(growthCardDraft.Count-1)*0.5f)*9f,
            safe.yMax+baseRect.height*0.32f);
        Rect animatedBase=baseRect;
        animatedBase.center=Vector2.Lerp(stackedCenter,baseRect.center,spreadT);

        bool dragging=index==growthCardDragIndex;
        bool committing=growthCardCommittedIndex>=0;
        bool committed=committing&&index==growthCardCommittedIndex;
        float commitT=committing?Mathf.Clamp01(
            (Time.unscaledTime-growthCardCommitStartedAt)/
            GrowthCardCommitDuration):0f;
        float commitEase=BombBrickUiTheme.EaseOutCubic(commitT);
        if(committed)
            animatedBase.center=Vector2.Lerp(animatedBase.center,
                new Vector2(safe.center.x,safe.y+42f),commitEase);
        else if(committing)
            animatedBase.center+=new Vector2(
                (index<growthCardCommittedIndex?-1f:1f)*86f*commitEase,
                24f*commitEase);
        bool hovered=!dragging&&growthCardDragIndex<0&&
            baseRect.Contains(Event.current.mousePosition);
        float progress=dragging?Mathf.Clamp01(dragVector.magnitude/dragThreshold):0f;
        Vector2 dragOffset=dragging
            ?Vector2.ClampMagnitude(dragVector,dragThreshold+26f)*
                (committed?1f-commitEase:1f)
            :Vector2.zero;
        float lift=hovered?7f:0f;
        float expand=dragging?5f*progress:(hovered?2f:0f);
        Rect card=new Rect(animatedBase.x+dragOffset.x-expand,
            animatedBase.y+dragOffset.y-lift-expand,
            animatedBase.width+expand*2f,animatedBase.height+expand*2f);
        Color rarityColor=GrowthCardRarityColor(entry.rarity);
        Color frameColor=dragging&&progress>=1f
            ?new Color(0.78f,0.9f,0.28f,1f)
            :rarityColor;

        Matrix4x4 previousMatrix=GUI.matrix;
        float tilt=dragging
            ?Mathf.Clamp(dragVector.x*0.035f,-7f,7f)
            :(index-(growthCardDraft.Count-1)*0.5f)*1.25f*(1f-spreadT);
        GUIUtility.RotateAroundPivot(tilt,card.center);
        GUIUtility.ScaleAroundPivot(new Vector2(revealScale,revealScale),card.center);
        float commitAlpha=committing&&!committed?1f-commitEase:1f;
        GUI.color=growthCardDragIndex>=0&&!dragging
            ?new Color(0.48f,0.5f,0.55f,0.72f*commitAlpha)
            :new Color(1f,1f,1f,commitAlpha);
        float lightWidth=card.width*Mathf.Clamp01(revealT*1.35f);
        DrawGrowthCardSolid(new Rect(card.center.x-lightWidth*0.5f,card.yMax+5f,
            lightWidth,3f),new Color(rarityColor.r,rarityColor.g,rarityColor.b,
            (1f-revealT)*0.75f));
        DrawGrowthCardSolid(new Rect(card.x+7f,card.y+10f,card.width,card.height),
            new Color(0f,0f,0f,0.46f));
        DrawGrowthCardSolid(card,new Color(0.075f,0.09f,0.125f,1f));
        DrawGrowthCardFrame(card,frameColor,hovered||dragging?2f:1f);
        DrawGrowthCardSolid(new Rect(card.x,card.y,card.width,4f),frameColor);

        float inset=7f;
        float artHeight=card.height*0.57f;
        Rect artRect=new Rect(card.x+inset,card.y+inset,
            card.width-inset*2f,artHeight);
        Texture2D art=ResolveGrowthCardArt(definition.id);
        if(art!=null)GUI.DrawTexture(artRect,art,ScaleMode.ScaleAndCrop,false);
        else DrawGrowthCardSolid(artRect,new Color(0.09f,0.11f,0.16f,1f));

        float glintT=Mathf.Clamp01((revealElapsed-revealDelay-0.2f)/0.42f);
        float glintAlpha=Mathf.Sin(glintT*Mathf.PI);
        if(glintAlpha>0.01f)
        {
            GUI.BeginGroup(artRect);
            float glintX=Mathf.Lerp(-22f,artRect.width+8f,glintT);
            DrawGrowthCardSolid(new Rect(glintX,0f,18f,artRect.height),
                new Color(rarityColor.r,rarityColor.g,rarityColor.b,glintAlpha*0.12f));
            DrawGrowthCardSolid(new Rect(glintX+7f,0f,3f,artRect.height),
                new Color(0.92f,0.97f,1f,glintAlpha*0.42f));
            GUI.EndGroup();
        }

        Rect titleShade=new Rect(artRect.x,artRect.yMax-60f,artRect.width,60f);
        DrawGrowthCardSolid(titleShade,new Color(0.025f,0.035f,0.06f,0.88f));

        string category=GrowthCardCategory(definition.effect);
        GUIStyle badgeStyle=new GUIStyle(GUI.skin.label)
        {
            alignment=TextAnchor.MiddleCenter,fontStyle=FontStyle.Bold,fontSize=11,
            normal={textColor=new Color(0.9f,0.94f,1f)}
        };
        float categoryWidth=Mathf.Clamp(badgeStyle.CalcSize(new GUIContent(category)).x+18f,58f,112f);
        Rect categoryBadge=new Rect(artRect.x+9f,artRect.y+9f,categoryWidth,24f);
        DrawGrowthCardSolid(categoryBadge,new Color(0.04f,0.055f,0.085f,0.88f));
        GUI.Label(categoryBadge,category,badgeStyle);

        string rarity=CombatGrowthCardCatalog.RarityDisplayName(entry.rarity);
        GUIStyle rarityStyle=new GUIStyle(badgeStyle)
        {
            normal={textColor=Color.Lerp(rarityColor,Color.white,0.22f)}
        };
        float rarityWidth=Mathf.Clamp(rarityStyle.CalcSize(new GUIContent(rarity)).x+18f,52f,90f);
        Rect rarityBadge=new Rect(artRect.xMax-rarityWidth-9f,artRect.y+9f,rarityWidth,24f);
        DrawGrowthCardSolid(rarityBadge,new Color(0.04f,0.055f,0.085f,0.88f));
        DrawGrowthCardFrame(rarityBadge,new Color(rarityColor.r,rarityColor.g,rarityColor.b,0.72f),1f);
        GUI.Label(rarityBadge,rarity,rarityStyle);

        GUIStyle titleStyle=new GUIStyle(GUI.skin.label)
        {
            alignment=TextAnchor.MiddleLeft,fontStyle=FontStyle.Bold,fontSize=22,
            normal={textColor=new Color(0.95f,0.97f,1f)}
        };
        GUI.Label(new Rect(artRect.x+14f,artRect.yMax-52f,artRect.width-28f,42f),
            definition.displayName,titleStyle);

        float infoY=artRect.yMax+13f;
        GUIStyle effectStyle=new GUIStyle(GUI.skin.label)
        {
            alignment=TextAnchor.UpperLeft,fontSize=15,wordWrap=true,
            normal={textColor=new Color(0.86f,0.89f,0.94f)}
        };
        GUI.Label(new Rect(card.x+17f,infoY,card.width-34f,
            Mathf.Max(54f,card.yMax-infoY-72f)),
            definition.EffectText(entry.rarity),effectStyle);

        DrawGrowthCardSolid(new Rect(card.x+17f,card.yMax-58f,card.width-34f,1f),
            new Color(0.25f,0.3f,0.39f,0.72f));
        int ownedCount=expeditionRun.growthCards.Count(item=>
            item!=null&&item.cardId==entry.cardId);
        GUIStyle stackStyle=new GUIStyle(GUI.skin.label)
        {
            alignment=TextAnchor.MiddleLeft,fontSize=12,
            normal={textColor=new Color(0.57f,0.64f,0.73f)}
        };
        GUI.Label(new Rect(card.x+17f,card.yMax-50f,card.width-92f,20f),
            ownedCount>0?"보유 효과":"신규 효과",stackStyle);
        BombBrickUiTheme.Badge(
            new Rect(card.xMax-69f,card.yMax-49f,52f,20f),
            "× "+ownedCount,
            ownedCount>0?rarityColor:new Color(0.35f,0.4f,0.5f));
        GUI.color=previous;
        GUI.matrix=previousMatrix;

        if(dragging&&!committing)
        {
            Vector2 cursor=Event.current.mousePosition;
            Color progressColor=progress>=1f
                ?new Color(0.78f,0.9f,0.28f,0.96f)
                :Color.Lerp(new Color(0.33f,0.43f,0.55f,0.86f),
                    rarityColor,progress);
            DrawGuiRing(cursor,15f+progress*8f,progressColor,
                progress>=1f?3f:1.5f,24);
            DrawGrowthCardSolid(new Rect(card.x,card.yMax+7f,
                card.width*progress,3f),progressColor);
        }
        else if(committed)
        {
            DrawGuiRing(animatedBase.center,40f+commitEase*58f,
                new Color(rarityColor.r,rarityColor.g,rarityColor.b,
                    1f-commitEase),2.4f,28);
        }
    }

    private static void DrawGrowthCardSolid(Rect rect,Color color)
    {
        Color previous=GUI.color;
        GUI.color=color;
        GUI.DrawTexture(rect,Texture2D.whiteTexture);
        GUI.color=previous;
    }

    private static void DrawGrowthCardFrame(Rect rect,Color color,float thickness)
    {
        DrawGrowthCardSolid(new Rect(rect.x,rect.y,rect.width,thickness),color);
        DrawGrowthCardSolid(new Rect(rect.x,rect.yMax-thickness,rect.width,thickness),color);
        DrawGrowthCardSolid(new Rect(rect.x,rect.y,thickness,rect.height),color);
        DrawGrowthCardSolid(new Rect(rect.xMax-thickness,rect.y,thickness,rect.height),color);
    }

    private void ResetGrowthCardDrag()
    {
        growthCardDragIndex=-1;
        growthCardDragStart=Vector2.zero;
        growthCardDragVector=Vector2.zero;
        growthCardDragArmed=false;
    }

    private void BeginGrowthCardReveal()
    {
        ResetGrowthCardDrag();
        growthCardCommittedIndex=-1;
        growthCardCommitStartedAt=-1f;
        growthCardRevealStartedAt=Time.unscaledTime;
    }

    private static float GrowthCardBackEase(float t)
    {
        t=Mathf.Clamp01(t);
        const float overshoot=1.18f;
        float shifted=t-1f;
        return 1f+(overshoot+1f)*shifted*shifted*shifted+
            overshoot*shifted*shifted;
    }

    private Texture2D ResolveGrowthCardArt(string cardId)
    {
        if(string.IsNullOrWhiteSpace(cardId))return null;
        if(growthCardArtCache.TryGetValue(cardId,out Texture2D art))return art;
        art=Resources.Load<Texture2D>("GrowthCards/"+cardId);
        growthCardArtCache[cardId]=art;
        return art;
    }

    private static string GrowthCardCategory(CombatGrowthCardEffect effect)
    {
        if(effect==CombatGrowthCardEffect.MaxHealth||effect==CombatGrowthCardEffect.AttackDamage||
           effect==CombatGrowthCardEffect.AttackSpeed||effect==CombatGrowthCardEffect.Defense||
           effect==CombatGrowthCardEffect.DamageReduction)return "기초 강화";
        if(effect==CombatGrowthCardEffect.SkillPower||
           effect==CombatGrowthCardEffect.CooldownRecoverySpeed||
           effect==CombatGrowthCardEffect.SkillCycleHeal)return "스킬 전술";
        if(effect==CombatGrowthCardEffect.MissingHealthRegeneration||
           effect==CombatGrowthCardEffect.OpeningShield||
           effect==CombatGrowthCardEffect.LowHealthDamageReduction||
           effect==CombatGrowthCardEffect.StatusResistanceRecoveryGuard||
           effect==CombatGrowthCardEffect.DeathShield)return "생존 전술";
        if(effect==CombatGrowthCardEffect.KillTeamAttackSpeed||
           effect==CombatGrowthCardEffect.VengeanceAttackDamage||
           effect==CombatGrowthCardEffect.TeamKillMissingHealthHeal)return "처치 연계";
        return "공격 전술";
    }

    private static Color GrowthCardRarityColor(CombatGrowthCardRarity rarity)
    {
        if(rarity==CombatGrowthCardRarity.Rare)return new Color(0.35f,0.66f,1f);
        if(rarity==CombatGrowthCardRarity.Epic)return new Color(0.66f,0.4f,0.85f);
        if(rarity==CombatGrowthCardRarity.Legendary)return new Color(1f,0.36f,0.2f);
        return new Color(0.843f,0.937f,1f);
    }

    private void DrawMonsterCard(Rect rect,MonsterDefinition definition,OwnedMonsterSave owned,
        bool selected,string status,bool dragging,bool compact)
    {
        if(definition==null||owned==null)return;
        ExpeditionMonsterStateSave expeditionState=
            ExpeditionItemSystem.MonsterState(expeditionRun,owned.instanceId);
        int rank=DisplayStarCount(expeditionState);
        int growthTotal=expeditionState==null?0:expeditionState.growthTotal;
        string rank2Name=TraitName(expeditionState==null?"":expeditionState.rank2TraitId);
        string rank3Name=TraitName(expeditionState==null?"":expeditionState.rank3TraitId);
        Color gradeColor=new Color(0.28f,0.72f,0.92f);
        Color previous=GUI.color;
        GUI.color=dragging?new Color(0.2f,0.95f,1f):selected?Color.Lerp(gradeColor,Color.white,0.45f):gradeColor;
        GUI.DrawTexture(rect,Texture2D.whiteTexture);
        GUI.color=new Color(0.075f,0.085f,0.105f,0.98f);
        GUI.DrawTexture(new Rect(rect.x+3f,rect.y+3f,rect.width-6f,rect.height-6f),Texture2D.whiteTexture);
        GUI.color=previous;

        if(compact)
        {
            Rect portraitRect=new Rect(rect.x+8f,rect.y+9f,54f,54f);
            DrawPortrait(portraitRect,definition,owned);
            GUIStyle title=new GUIStyle(GUI.skin.label){fontStyle=FontStyle.Bold,fontSize=12};
            GUI.Label(new Rect(rect.x+68f,rect.y+8f,rect.width-103f,21f),definition.displayName,title);
            GUI.Box(new Rect(rect.xMax-33f,rect.y+7f,25f,24f),
                new string('★',rank));
            GUI.Label(new Rect(rect.x+68f,rect.y+29f,rect.width-76f,19f),
                "성장 "+growthTotal+" / "+ExpeditionGrowthSystem.MaximumGrowth+" · "+
                MonsterInstanceGenerator.PersonalityDisplayName(owned.personalityId));
            GUI.Label(new Rect(rect.x+68f,rect.y+49f,rect.width-76f,19f),
                "HP "+Percent(owned.hpMultiplier)+" / 공격 "+Percent(owned.damageMultiplier));
            GUI.Label(new Rect(rect.x+8f,rect.y+69f,rect.width-16f,18f),
                "2★ "+rank2Name+" · 3★ "+rank3Name);
            GUI.Label(new Rect(rect.x+8f,rect.y+89f,rect.width-16f,18f),status);
            return;
        }

        Rect fullPortrait=new Rect(rect.x+12f,rect.y+12f,rect.width-24f,104f);
        DrawPortrait(fullPortrait,definition,owned);
        GUIStyle fullTitle=new GUIStyle(GUI.skin.label){fontStyle=FontStyle.Bold,fontSize=16,alignment=TextAnchor.MiddleLeft};
        GUI.Label(new Rect(rect.x+12f,rect.y+122f,rect.width-58f,24f),definition.displayName,fullTitle);
        GUI.Box(new Rect(rect.xMax-43f,rect.y+121f,31f,28f),
            new string('★',rank));
        GUI.Label(new Rect(rect.x+12f,rect.y+148f,rect.width-24f,20f),
