    private void DrawPortrait(
        Rect rect,MonsterDefinition definition,OwnedMonsterSave owned=null)
    {
        Sprite portrait=ResolveOwnedPortrait(definition,owned);
        Color previous=GUI.color;
        GUI.color=new Color(0.025f,0.03f,0.04f,1f);
        GUI.DrawTexture(rect,Texture2D.whiteTexture);
        GUI.color=previous;
        if(portrait==null)
        {
            GUIStyle emptyStyle=new GUIStyle(GUI.skin.label)
            {
                alignment=TextAnchor.MiddleCenter,
                fontSize=10,
                normal={textColor=new Color(0.55f,0.58f,0.64f)}
            };
            GUI.Label(rect,"SPRITE\nEMPTY",emptyStyle);
            return;
        }

        Rect textureRect=portrait.textureRect;
        Rect uv=new Rect(textureRect.x/portrait.texture.width,textureRect.y/portrait.texture.height,
            textureRect.width/portrait.texture.width,textureRect.height/portrait.texture.height);
        if(!DrawEvolutionPortrait(rect,portrait,owned?.instanceId))GUI.DrawTextureWithTexCoords(rect,portrait.texture,uv,true);
        Rect evolutionBody=rect;
        if(owned!=null&&monsterRankUpPulses.ContainsKey(owned.instanceId))
        {
            Bounds body=PixelMantisReaper.VisibleBody(portrait);
            float ppu=portrait.pixelsPerUnit;
            evolutionBody=new Rect(rect.x+(portrait.pivot.x+body.min.x*ppu)/portrait.rect.width*rect.width,
                rect.y+(1f-(portrait.pivot.y+body.max.y*ppu)/portrait.rect.height)*rect.height,
                body.size.x*ppu/portrait.rect.width*rect.width,body.size.y*ppu/portrait.rect.height*rect.height);
        }
        DrawMonsterRankUpFeedback(evolutionBody,owned?.instanceId);
    }

    private Sprite ResolvePortrait(MonsterDefinition definition)
    {
        return ResolveOwnedPortrait(definition,null);
    }

    private Sprite ResolveOwnedPortrait(
        MonsterDefinition definition,OwnedMonsterSave owned)
    {
        Sprite animatedSprite=ResolveAnimatedSpritePortrait(definition,owned);
        if(animatedSprite!=null)return animatedSprite;
        if(definition==null||string.IsNullOrWhiteSpace(definition.portraitResourcePath))return null;
        if(portraitCache.TryGetValue(definition.portraitResourcePath,out Sprite portrait))return portrait;
        portrait=Resources.Load<Sprite>(definition.portraitResourcePath);
        portraitCache[definition.portraitResourcePath]=portrait;
        return portrait;
    }

    private Sprite ResolveAnimatedSpritePortrait(
        MonsterDefinition definition,OwnedMonsterSave owned=null)
    {
        if(definition==null||string.IsNullOrWhiteSpace(definition.resourcePath))
            return null;
        string resourcePath=owned!=null&&owned.isShiny&&
            !string.IsNullOrWhiteSpace(definition.shinyResourcePath)
                ?definition.shinyResourcePath
                :definition.resourcePath;
        if(!spriteProfileAnimationCache.TryGetValue(
               resourcePath,
               out SpriteMonsterAnimationDriver driver))
        {
            GameObject prefab=Resources.Load<GameObject>(resourcePath);
            driver=prefab!=null
                ?prefab.GetComponentInChildren<SpriteMonsterAnimationDriver>(true)
                :null;
            spriteProfileAnimationCache[resourcePath]=driver;
        }
        return driver!=null?driver.GetIdleFrame(Time.unscaledTime):null;
    }

    private static string Percent(float multiplier)
    {
        float delta=(multiplier-1f)*100f;
        return (delta>=0f?"+":"")+delta.ToString("0")+"%";
    }

    private static string ShortText(string value,int maximum)
    {
        if(string.IsNullOrWhiteSpace(value))return GameLocalization.Text("없음");
        value=GameLocalization.Text(value);
        return value.Length<=maximum?value:value.Substring(0,maximum-1)+"…";
    }

