    private static void DrawRegionAffinityLabel(Rect panel,Unit unit)
    {
        string key=unit.regionDamageMultiplier>1f?"strong":
            unit.regionDamageMultiplier<1f?"weak":"neutral";
        Color previous=GUI.color;
        GUI.color=key=="strong"?BombBrickUiTheme.Lime:
            key=="weak"?BombBrickUiTheme.Red:BombBrickUiTheme.Cyan;
        GUI.Label(new Rect(panel.xMax-230f,panel.y+12f,212f,16f),
            GameLocalization.Format("battle.region_affinity_"+key,
                key=="strong"?"맵 상성 · 유리 ×{0}":
                key=="weak"?"맵 상성 · 불리 ×{0}":"맵 상성 · 중립 ×{0}",
                unit.regionDamageMultiplier.ToString("0.0")),
            BombBrickUiTheme.CaptionStyle(10,TextAnchor.MiddleRight));
        GUI.color=previous;
    }

