    private void DrawUnitPlacementFeedback()
    {
        if(!draggingUnit||selectedUnit==null||battleStarted)return;
        bool hasTile=tiles.TryGetValue(hoveredTile,out Tile tile);
        bool valid=hasTile&&CanDropSelectedUnit(tile);
        bool bench=valid&&tile.bench;
        Color accent=valid?BombBrickUiTheme.Lime:BombBrickUiTheme.Red;
        string symbol=valid?"✓":"×";
        string label=valid?(bench?"대기석":"배치 가능"):"배치 불가";

        Vector2 pointer=Event.current.mousePosition;
        Rect badge=BombBrickUiLayout.PlacePopup(
            pointer,new Vector2(112f,34f),UiLayout.safeArea,22f);
        BombBrickUiTheme.Fill(badge,
            new Color(BombBrickUiTheme.SurfaceRaised.r,
                BombBrickUiTheme.SurfaceRaised.g,
                BombBrickUiTheme.SurfaceRaised.b,0.97f));
        BombBrickUiTheme.Frame(badge,accent,1f);
        BombBrickUiTheme.Fill(new Rect(badge.x,badge.y,4f,badge.height),accent);
        GUI.Label(new Rect(badge.x+10f,badge.y+5f,24f,24f),symbol,
            BombBrickUiTheme.TitleStyle(17,TextAnchor.MiddleCenter));
        GUI.Label(new Rect(badge.x+38f,badge.y+5f,badge.width-46f,24f),label,
            BombBrickUiTheme.CaptionStyle(11,TextAnchor.MiddleLeft));
    }

