    private WaveCombatContribution RefreshCombatContributionPages(float now)
    {
        int wave=expeditionRun==null?1:expeditionRun.wave;
        bool live=battleStarted||battleEnding;
        bool preparing=!live&&string.IsNullOrEmpty(resultText);
        bool currentAvailable=live||preparing&&combatContributionHistory.Count==0;
        bool waveChanged=cachedCombatContributionWave!=wave;
        if(waveChanged||live&&(!cachedCombatContributionCurrentAvailable||
            cachedLiveCombatContribution==null||!cachedLiveCombatContribution.live))
            combatDataSelectedWave=live?wave:
            combatContributionHistory.LastOrDefault()?.wave??wave;
        bool refreshCache=now>=nextCombatContributionRefreshAt||
            waveChanged||
            cachedCombatContributionHistoryCount!=combatContributionHistory.Count||
            cachedCombatContributionCurrentAvailable!=currentAvailable||
            currentAvailable&&(cachedLiveCombatContribution==null||cachedLiveCombatContribution.live!=live);
        if(refreshCache)
        {
            combatContributionPages.Clear();
            for(int i=0;i<combatContributionHistory.Count;i++)
            {
                WaveCombatContribution item=combatContributionHistory[i];
                if(item!=null&&(!currentAvailable||item.wave!=wave))
                    combatContributionPages.Add(item);
            }
            if(currentAvailable)
            {
                cachedLiveCombatContribution??=new WaveCombatContribution();
                PopulateCombatContribution(cachedLiveCombatContribution,preparing);
                combatContributionPages.Add(cachedLiveCombatContribution);
            }
            cachedCombatContributionHistoryCount=combatContributionHistory.Count;
            cachedCombatContributionCurrentAvailable=currentAvailable;
            cachedCombatContributionWave=wave;
            nextCombatContributionRefreshAt=now+0.2f;
        }
        List<WaveCombatContribution> pages=combatContributionPages;
        WaveCombatContribution current=currentAvailable?cachedLiveCombatContribution:null;

        WaveCombatContribution selected=null;
        for(int i=0;i<pages.Count;i++)
        {
            if(pages[i].wave!=combatDataSelectedWave)continue;
            selected=pages[i];
            break;
        }
        if(currentAvailable&&combatDataSelectedWave==wave)
            selected=current;
        if(selected==null&&pages.Count>0)
        {
            selected=current??pages[pages.Count-1];
            combatDataSelectedWave=selected.wave;
        }
        return selected;
    }

    private void DrawCombatContributionPanel()
    {
        float now=Time.realtimeSinceStartup;
        WaveCombatContribution selected=RefreshCombatContributionPages(now);
        List<WaveCombatContribution> pages=combatContributionPages;
        if(combatDataPanelLastRealtime<0f)combatDataPanelLastRealtime=now;
        float realDelta=Mathf.Clamp(now-combatDataPanelLastRealtime,0f,0.05f);
        combatDataPanelLastRealtime=now;
        combatDataPanelSlide=Mathf.MoveTowards(
            combatDataPanelSlide,combatDataPanelOpen?1f:0f,
            realDelta/0.20f);

        Rect safe=UiLayout.safeArea;
        const float width=BombBrickUiLayout.RunHudWidth;
        const float tabWidth=38f;
        const float tabHeight=76f;
        const float tabOverlap=12f;
        const float tabTop=10f;
        const float minimumHeight=tabTop+2f*tabHeight-tabOverlap+5f;
        const float headerHeight=91f;
        const float rowHeight=40f;
        bool showEnemies=combatDataTeam==Team.Enemy;
        List<CombatContributionEntry> entries=showEnemies?selected?.enemies:selected?.allies;
        Color teamColor=showEnemies?BombBrickUiTheme.Red:BombBrickUiTheme.Cyan;
        int rowCount=Mathf.Max(1,entries?.Count??0);
        int maxRows=Mathf.Max(selected?.allies.Count??0,selected?.enemies.Count??0);
        float height=Mathf.Max(minimumHeight,headerHeight+rowCount*rowHeight+12f);
        // Keep the tabs in place when the two teams have different row counts.
        float anchorHeight=Mathf.Max(minimumHeight,headerHeight+maxRows*rowHeight+12f);
        float openX=safe.x+BombBrickUiLayout.Margin;
        float closedX=safe.x-width;
        float eased=BombBrickUiTheme.EaseOutCubic(combatDataPanelSlide);
        Rect panel=new Rect(
            Mathf.Lerp(closedX,openX,eased),
            safe.center.y-anchorHeight*0.5f,width,height);

        BombBrickUiTheme.DrawPanel(panel,true);
        BombBrickUiTheme.Fill(new Rect(panel.x,panel.y,4f,panel.height),teamColor);
        Rect allyTab=new Rect(panel.xMax,panel.y+tabTop,tabWidth,tabHeight);
        Rect enemyTab=new Rect(panel.xMax,allyTab.yMax-tabOverlap,tabWidth,tabHeight);
        Rect foreground=showEnemies?enemyTab:allyTab;
        Team otherTeam=showEnemies?Team.Player:Team.Enemy;
        bool switched=DrawCombatDataTeamTab(showEnemies?allyTab:enemyTab,otherTeam,foreground);
        bool toggled=DrawCombatDataTeamTab(foreground,combatDataTeam,foreground);
        if(switched||toggled)
        {
            bool wasOpen=combatDataPanelOpen;
            if(switched)combatDataTeam=otherTeam;
            combatDataPanelOpen=switched||!wasOpen;
            if(wasOpen!=combatDataPanelOpen)
                GameAudio.Play(combatDataPanelOpen?GameAudio.Cue.SlideOpen:GameAudio.Cue.SlideClose);
        }

        if(combatDataPanelSlide<=0.02f)return;
        Color previous=GUI.color;
        GUI.color=new Color(1f,1f,1f,eased);
        GUI.Label(new Rect(panel.x+14f,panel.y+9f,142f,21f),
            "전투 데이터",BombBrickUiTheme.TitleStyle(14));
        Color statusColor=selected==null?BombBrickUiTheme.TextSecondary:
            selected.preparing?BombBrickUiTheme.Cyan:
            selected.live?BombBrickUiTheme.Red:
            (selected.won?BombBrickUiTheme.Lime:BombBrickUiTheme.Red);
        float statusWidth=selected!=null&&selected.preparing?88f:51f;
        BombBrickUiTheme.Badge(
            new Rect(panel.xMax-statusWidth-13f,panel.y+8f,statusWidth,21f),
            selected==null?"없음":
                selected.preparing?"전투 준비":
                selected.live?"LIVE":(selected.won?"승리":"패배"),statusColor);

        float pageGap=5f;
        float pageWidth=Mathf.Min(44f,
            (panel.width-28f-pageGap*(pages.Count-1))/
            Mathf.Max(1,pages.Count));
        float pagesWidth=pages.Count*pageWidth+
            Mathf.Max(0,pages.Count-1)*pageGap;
        float pagesX=panel.center.x-pagesWidth*0.5f;
        for(int i=0;i<pages.Count;i++)
        {
            WaveCombatContribution page=pages[i];
            Rect pageRect=new Rect(
                pagesX+i*(pageWidth+pageGap),panel.y+35f,pageWidth,22f);
            bool active=ReferenceEquals(page,selected);
            BombBrickUiTheme.Fill(pageRect,
                active?new Color(0.1f,0.24f,0.34f,1f):
                    new Color(0.04f,0.055f,0.08f,0.96f));
            BombBrickUiTheme.Frame(pageRect,
                active?BombBrickUiTheme.Cyan:BombBrickUiTheme.Border,1f);
            GUI.Label(pageRect,"W"+page.wave,
                BombBrickUiTheme.CaptionStyle(10,TextAnchor.MiddleCenter));
            if(GUI.Button(pageRect,string.Empty,
                BombBrickUiTheme.ClearButtonStyle()))
                combatDataSelectedWave=page.wave;
        }

        float metricX=panel.x+144f;
        float metricY=panel.y+62f;
        GUI.Label(new Rect(metricX,metricY,64f,24f),
            "입힌 피해",CombatMetricHeaderStyle(BombBrickUiTheme.Orange));
        GUI.Label(new Rect(metricX+66f,metricY,64f,24f),
            "받은 피해",CombatMetricHeaderStyle(BombBrickUiTheme.Red));
        GUI.Label(new Rect(metricX+132f,metricY,64f,24f),
            "회복량",CombatMetricHeaderStyle(new Color(0.34f,1f,0.52f)));

        float maximumDamage=1f;
        if(entries!=null)
            for(int i=0;i<entries.Count;i++)
                maximumDamage=Mathf.Max(maximumDamage,entries[i].damageDealt);
        for(int i=0;i<rowCount;i++)
        {
            CombatContributionEntry item=entries!=null&&i<entries.Count?entries[i]:null;
            Rect row=new Rect(
                panel.x+8f,panel.y+headerHeight+i*rowHeight,
                panel.width-16f,rowHeight-3f);
            BombBrickUiTheme.Fill(row,
                i%2==0?BombBrickUiTheme.Surface:
                    new Color(0.024f,0.035f,0.055f,0.96f));
            if(item==null)
            {
                GUI.Label(row,"기록 없음",
                    BombBrickUiTheme.CaptionStyle(11,TextAnchor.MiddleCenter));
                continue;
            }
            float ratio=Mathf.Clamp01(item.damageDealt/maximumDamage);
            BombBrickUiTheme.Fill(
                new Rect(row.x,row.yMax-3f,row.width*ratio,3f),
                new Color(teamColor.r,teamColor.g,teamColor.b,0.64f));
            DrawPortrait(new Rect(row.x+3f,row.y+3f,31f,31f),
                item.definition);
            GUIStyle nameStyle=BombBrickUiTheme.CaptionStyle(
                10,TextAnchor.MiddleLeft);
            BombBrickUiTheme.Label(new Rect(row.x+39f,row.y+2f,94f,18f),
                item.displayName,nameStyle,item.survived
                    ?BombBrickUiTheme.TextSecondary
                    :new Color(0.48f,0.51f,0.57f));
            GUIStyle comboStyle=BombBrickUiTheme.CaptionStyle(8,TextAnchor.MiddleLeft);
            BombBrickUiTheme.Label(new Rect(row.x+39f,row.y+19f,94f,17f),
                GameLocalization.Format(
                    "battle.combo_bonus","연계 {0} +{1}",
                    item.comboActivations,
                    CompactCombatValue(item.comboBonusDamage)),comboStyle,
                BombBrickUiTheme.Cyan);
            DrawCombatMetricValue(
                new Rect(row.x+136f,row.y+3f,64f,29f),
                item.damageDealt,BombBrickUiTheme.Orange);
            DrawCombatMetricValue(
                new Rect(row.x+202f,row.y+3f,64f,29f),
                item.damageTaken,BombBrickUiTheme.Red);
            DrawCombatMetricValue(
                new Rect(row.x+268f,row.y+3f,64f,29f),
                item.healingReceived,new Color(0.34f,1f,0.52f));
        }
        GUI.color=previous;
    }

    private bool DrawCombatDataTeamTab(Rect tab,Team team,Rect foreground)
    {
        bool selected=combatDataTeam==team;
        bool close=selected&&combatDataPanelOpen;
        Color accent=team==Team.Enemy?BombBrickUiTheme.Red:BombBrickUiTheme.Cyan;
        Color background=new Color(0.035f,0.055f,0.085f,1f);
        if(!selected)
        {
            tab=new Rect(tab.x,tab.y+4f,tab.width-5f,tab.height-8f);
            accent=Color.Lerp(background,accent,0.58f);
        }
        BombBrickUiTheme.Fill(tab,selected?Color.Lerp(background,accent,0.12f):background);
        BombBrickUiTheme.Frame(tab,accent,selected?2f:1f);
        float glyphX=tab.center.x-9f;
        float glyphBottom=tab.y+34f;
        BombBrickUiTheme.Fill(new Rect(glyphX,glyphBottom-7f,4f,7f),accent);
        BombBrickUiTheme.Fill(new Rect(glyphX+7f,glyphBottom-13f,4f,13f),accent);
        BombBrickUiTheme.Fill(new Rect(glyphX+14f,glyphBottom-19f,4f,19f),accent);
        BombBrickUiTheme.Label(new Rect(tab.x,tab.yMax-30f,tab.width,20f),
            close?"‹":"›",BombBrickUiTheme.TitleStyle(17,TextAnchor.MiddleCenter),accent);
        // The back tab only responds where it is visible.
        Rect hit=tab;
        if(!selected)
        {
            if(tab.y<foreground.y)hit.yMax=Mathf.Min(hit.yMax,foreground.yMin);
            else hit.yMin=Mathf.Max(hit.yMin,foreground.yMax);
        }
        return GUI.Button(hit,string.Empty,BombBrickUiTheme.ClearButtonStyle());
    }

    private void DrawCombatContributionPanelLegacy()
    {
        List<Unit> allies=units.Where(unit=>
                unit!=null&&unit.team==Team.Player&&!unit.inStorage&&
                !unit.augmentShadowClone)
            .OrderByDescending(unit=>unit.damageDealt)
            .ThenBy(unit=>unit.id)
            .Take(8).ToList();
        if(allies.Count==0)return;

        Rect safe=UiLayout.safeArea;
        const float width=306f;
        const float headerHeight=62f;
        const float rowHeight=40f;
        float height=headerHeight+allies.Count*rowHeight+10f;
        float reveal=BombBrickUiTheme.EaseOutBack(
            Mathf.Clamp01(battleElapsed/0.55f),0.65f);
        Rect panel=new Rect(
            Mathf.Lerp(safe.x-width-18f,
                safe.x+BombBrickUiLayout.Margin,reveal),
            safe.center.y-height*0.5f,
            width,height);
        BombBrickUiTheme.DrawPanel(panel,true);
        BombBrickUiTheme.Fill(
            new Rect(panel.x,panel.y,4f,panel.height),
            BombBrickUiTheme.Cyan);
        GUI.Label(new Rect(panel.x+14f,panel.y+9f,142f,21f),
            "전투 데이터",BombBrickUiTheme.TitleStyle(14));
        BombBrickUiTheme.Badge(
            new Rect(panel.xMax-55f,panel.y+8f,42f,21f),
            "LIVE",BombBrickUiTheme.Red);

        float metricX=panel.x+116f;
        GUI.Label(new Rect(metricX,panel.y+34f,54f,18f),
            "입힌 피해",
            CombatMetricHeaderStyle(BombBrickUiTheme.Orange));
        GUI.Label(new Rect(metricX+58f,panel.y+34f,54f,18f),
            "받은 피해",
            CombatMetricHeaderStyle(BombBrickUiTheme.Red));
        GUI.Label(new Rect(metricX+116f,panel.y+34f,54f,18f),
            "회복량",
            CombatMetricHeaderStyle(new Color(0.34f,1f,0.52f)));

        float maximumDamage=Mathf.Max(
            1f,allies.Max(unit=>unit.damageDealt));
        for(int i=0;i<allies.Count;i++)
        {
            Unit unit=allies[i];
            Rect row=new Rect(
                panel.x+8f,panel.y+headerHeight+i*rowHeight,
                panel.width-16f,rowHeight-3f);
            BombBrickUiTheme.Fill(row,
                i%2==0?BombBrickUiTheme.Surface:
                    new Color(0.024f,0.035f,0.055f,0.96f));
            float ratio=Mathf.Clamp01(unit.damageDealt/maximumDamage);
            BombBrickUiTheme.Fill(
                new Rect(row.x,row.yMax-3f,row.width*ratio,3f),
                new Color(BombBrickUiTheme.Cyan.r,
                    BombBrickUiTheme.Cyan.g,
                    BombBrickUiTheme.Cyan.b,0.64f));
            DrawPortrait(new Rect(row.x+3f,row.y+3f,31f,31f),
                unit.definition,unit.ownedInstance);
            GUIStyle nameStyle=BombBrickUiTheme.CaptionStyle(
                10,TextAnchor.MiddleLeft);
            BombBrickUiTheme.Label(new Rect(row.x+39f,row.y+3f,67f,29f),
                ShortText(unit.displayName,7),nameStyle,unit.alive
                    ?BombBrickUiTheme.TextSecondary
                    :new Color(0.48f,0.51f,0.57f));
            DrawCombatMetricValue(
                new Rect(row.x+108f,row.y+3f,54f,29f),
                unit.damageDealt,BombBrickUiTheme.Orange);
            DrawCombatMetricValue(
                new Rect(row.x+166f,row.y+3f,54f,29f),
                unit.damageTaken,BombBrickUiTheme.Red);
            DrawCombatMetricValue(
                new Rect(row.x+224f,row.y+3f,54f,29f),
                unit.healingReceived,new Color(0.34f,1f,0.52f));
        }
    }

    private static GUIStyle CombatMetricHeaderStyle(Color color)
    {
        int key=ColorStyleKey(color);
        if(CombatMetricHeaderStyles.TryGetValue(key,out GUIStyle cached))
            return cached;
        GUIStyle style=BombBrickUiTheme.CaptionStyle(
            9,TextAnchor.MiddleCenter);
        style=new GUIStyle(style);
        style.normal.textColor=Color.Lerp(color,Color.white,0.25f);
        CombatMetricHeaderStyles[key]=style;
        return style;
    }

    private static void DrawCombatMetricValue(
        Rect rect,float value,Color color)
    {
        int key=ColorStyleKey(color);
        if(!CombatMetricValueStyles.TryGetValue(key,out GUIStyle style))
        {
            style=new GUIStyle(BombBrickUiTheme.TitleStyle(
                11,TextAnchor.MiddleRight));
            style.normal.textColor=Color.Lerp(color,Color.white,0.12f);
            CombatMetricValueStyles[key]=style;
        }
        GUI.Label(rect,CompactCombatValue(value),style);
    }

    private static int ColorStyleKey(Color color)
    {
        Color32 value=color;
        return value.r|(value.g<<8)|(value.b<<16)|(value.a<<24);
    }

    private static string CompactCombatValue(float value)
    {
        value=Mathf.Max(0f,value);
        if(value<1000f)return Mathf.RoundToInt(value).ToString();
        if(value<10000f)return (value/1000f).ToString("0.0")+"K";
        return Mathf.RoundToInt(value/1000f)+"K";
    }

    private void DrawUnitHealthBars()
    {
        if(mainCamera==null)return;
        ExpeditionAugmentSelectionSave blessing=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.FickleBlessing);
        ExpeditionAugmentSelectionSave protagonist=
            ExpeditionAugmentRuntime.Selection(
                expeditionRun,ExpeditionAugmentRuntime.Protagonist);
        int blessingMode=blessing==null?-1:
            ExpeditionAugmentRuntime.BlessingMode(blessing,expeditionRun.wave);
        Color playerAccent=blessingMode<0?BombBrickUiTheme.Cyan:
            FickleBlessingColor(blessingMode);
        for(int i=0;i<units.Count;i++)
        {
            Unit unit=units[i];
            if(!TryGetUnitWorldHudRect(unit,out Rect visualBounds))continue;
            Matrix4x4 previousHudMatrix=GUI.matrix;
            GUI.matrix=CombatReadabilityPresentation.WorldHudMatrix(previousHudMatrix,visualBounds);
            float ratio=Mathf.Clamp01(unit.hp/Mathf.Max(1f,unit.maxHp));
            Rect back=HealthBarRectForVisualBounds(visualBounds);
            bool isProtagonist=unit.team==Team.Player&&
                ExpeditionAugmentRuntime.Targets(protagonist,unit.stableId);
            if(isProtagonist)back.y-=14f;
            Color previous=GUI.color;
            Color healthColor=unit.team==Team.Player
                ?new Color(0.24f,0.86f,0.36f)
                :new Color(0.96f,0.22f,0.18f);
            bool endangered=battleStarted&&unit.team==Team.Player&&ratio<=0.30f;
            Color danger=new Color(1f,.18f,.12f,.56f+Mathf.Sin(Time.unscaledTime*7f+unit.id)*.28f);
            DrawSegmentedHealthBar(back,ratio,unit.maxHp,healthColor,
                DamageTrailRatio(ratio,unit.damageTrailRatio,Time.time-unit.damageTrailStartedAt));
            DrawTeamHealthBarFrame(back,unit.team==Team.Player,healthColor);
            if(unit.team==Team.Player&&blessingMode>=0)
                BombBrickUiTheme.Frame(new Rect(back.x-1f,back.y-1f,back.width+2f,back.height+2f),
                    new Color(playerAccent.r,playerAccent.g,playerAccent.b,.72f),1f);
            float shieldAmount=TotalVisibleShield(unit);
            if(shieldAmount>.01f)DrawShieldEnvelope(back,shieldAmount/Mathf.Max(1f,unit.maxHp),unit.id);
            if(endangered)BombBrickUiTheme.Frame(
                new Rect(back.x-2f,back.y-2f,back.width+4f,back.height+4f),danger,1f);
            CombatHudIconArt.DrawRegionAffinity(new Rect(
                back.x-(isProtagonist?33f:18f),back.y-3f,14f,14f),unit.regionDamageMultiplier);
            if(endangered)
                BombBrickUiTheme.Badge(
                    new Rect(back.xMax+4f,back.y-6f,18f,18f),"!",danger);
            CollectCombatHudIcons(unit);
            int presentationStars=RankUpPresentationStarCount(unit,out float stampScale);
            if(presentationStars>0)
            {
                GUIStyle starStyle=BombBrickUiTheme.TitleStyle(
                    16,TextAnchor.MiddleCenter);
                Rect rankRect=RankStarsRect(back);
                if(combatHudIcons.Count>0)
                    rankRect.y=CombatHudIconRect(back,combatHudIcons.Count-1,combatHudIcons.Count).y-22f;
                Matrix4x4 previousStarMatrix=GUI.matrix;
                try
                {
                    GUIUtility.ScaleAroundPivot(Vector2.one*stampScale,rankRect.center);
                    BombBrickUiTheme.Label(rankRect,new string('★',presentationStars),starStyle,
                        presentationStars==1?new Color(1f,.82f,.16f):MonsterRankUpFeedback.RankColor(presentationStars));
                }
                finally{GUI.matrix=previousStarMatrix;}
            }
            if(unit==captureTarget)
            {
                DrawCaptureNetGlyph(
                    new Rect(back.xMax+6f,back.y-7f,21f,21f),
                    CaptureNetCatalog.GradeColor(
                        CaptureNetCatalog.Get(
                            expeditionRun.selectedCaptureNetItemId)?.grade??
                        CaptureNetGrade.Standard),
                    true,expeditionRun.selectedCaptureNetItemId);
            }
            if(unit.skillCooldownDuration>0f)
            {
                float readiness=1f-Mathf.Clamp01(unit.skillTimer/unit.skillCooldownDuration);
                Rect skillBack=new Rect(back.x,back.y+8f,back.width,4f);
                GUI.color=new Color(0.02f,0.025f,0.035f,0.92f);GUI.DrawTexture(skillBack,Texture2D.whiteTexture);
                string behavior=MonsterSkillExecutor<SkillExecutionContext>.Behavior(unit.skillId);
                Color skillColor=string.Equals(behavior,"GuardianTaunt",StringComparison.OrdinalIgnoreCase)
                    ?new Color(0.12f,0.68f,1f)
                    :string.Equals(behavior,"AssassinLeap",StringComparison.OrdinalIgnoreCase)
                        ?new Color(0.72f,0.18f,1f):new Color(1f,0.38f,0.06f);
                GUI.color=readiness>=0.999f?Color.Lerp(skillColor,Color.white,0.55f):skillColor;
                float apexFlash=RaptorApexPredatorActive(unit)
                    ?Mathf.Clamp01(unit.raptorApexCooldownFlash/0.18f):0f;
                GUI.color=Color.Lerp(GUI.color,new Color(1f,0.94f,0.76f),apexFlash);
                GUI.DrawTexture(new Rect(skillBack.x+1f,skillBack.y+1f,(skillBack.width-2f)*readiness,skillBack.height-2f),Texture2D.whiteTexture);
                if(apexFlash>0f)
                    BombBrickUiTheme.Frame(skillBack,new Color(0.86f,0.92f,0.8f,apexFlash),1f);
                if(readiness>=0.999f)
                {
                    GUI.color=Color.white;
                    GUI.DrawTexture(
                        new Rect(skillBack.xMax+3f,skillBack.y-2f,7f,7f),
                        Texture2D.whiteTexture);
                }
            }
            if(isProtagonist)DrawProtagonistGauge(unit,back);
            DrawCombatHudIcons(back,unit);
            DrawFearIndicator(back,unit);
            GUI.color=previous;
            GUI.matrix=previousHudMatrix;
        }
    }

    public static Rect HealthBarRectForVisualBounds(Rect visualBounds)
    {
        const float gapAboveVisual=6f;
        const float height=8f;
        return new Rect(
            visualBounds.center.x-26f,
            visualBounds.yMin-height-gapAboveVisual,
            52f,
            height);
    }

    private static void DrawTeamHealthBarFrame(
        Rect healthBar,bool playerTeam,Color teamColor)
    {
        BombBrickUiTheme.Frame(healthBar,teamColor,1f);
        if(playerTeam)return;
        BombBrickUiTheme.Fill(new Rect(
            healthBar.xMax,healthBar.y+1f,2f,healthBar.height-2f),teamColor);
        BombBrickUiTheme.Fill(new Rect(
            healthBar.xMax+2f,healthBar.y+2f,2f,healthBar.height-4f),teamColor);
        BombBrickUiTheme.Fill(new Rect(
            healthBar.xMax+4f,healthBar.y+3f,1f,healthBar.height-6f),teamColor);
