    public static bool ShouldShowWorldHealthBar(
        bool combatActive,bool inStorage,bool hovered,bool alive)
    {
        return combatActive||inStorage&&hovered&&alive;
    }

    public static Rect RankStarsRect(Rect healthBar)
    {
        return new Rect(healthBar.center.x-40f,healthBar.y-25f,80f,18f);
    }

    private static float ProtagonistGaugeRatio(Unit unit)
    {
        float maximum=ExpeditionAugmentRuntime.ProtagonistParam("gauge_max",100f);
        if(unit.augmentClimaxTimer>0f)
            return Mathf.Clamp01(unit.augmentClimaxTimer/Mathf.Max(.01f,
                ExpeditionAugmentRuntime.ProtagonistParam("climax_duration",8f)));
        return unit.augmentClimaxUsed?0f:
            Mathf.Clamp01(unit.augmentProtagonistGauge/Mathf.Max(1f,maximum));
    }

    private static Rect ProtagonistGaugeRect(Rect healthBar)=>
        BombBrickUiTheme.PixelRect(new Rect(healthBar.x,healthBar.y+16f,healthBar.width,10f));

    private static void DrawProtagonistGauge(Unit unit,Rect healthBar)
    {
        float ratio=ProtagonistGaugeRatio(unit);
        bool active=unit.augmentClimaxTimer>0f;
        bool spent=unit.augmentClimaxUsed&&!active;
        Rect gauge=ProtagonistGaugeRect(healthBar);
        Color gold=new Color(1f,0.7f,0.08f);
        Color previous=GUI.color;
        GUI.color=Color.white;
        BombBrickUiTheme.Fill(gauge,new Color(0.018f,0.022f,0.03f,1f));
        // The shared 2px grid used to round both bright 1px borders across the entire 4px gauge.
        BombBrickUiTheme.Frame(gauge,active?gold:new Color(.26f,.25f,.20f),2f);
        if(ratio>0f)
            BombBrickUiTheme.Fill(new Rect(
                gauge.x+2f,gauge.y+2f,(gauge.width-4f)*ratio,gauge.height-4f),
                active?Color.Lerp(
                    gold,Color.white,0.35f+0.25f*Mathf.Sin(Time.unscaledTime*9f)):gold);
        BombBrickUiTheme.Label(new Rect(gauge.xMax+4f,gauge.y-3f,34f,16f),
            active?unit.augmentClimaxTimer.ToString("0.0")+"s":
                spent?"—":Mathf.FloorToInt(ratio*100f)+"%",
            BombBrickUiTheme.CaptionStyle(9,TextAnchor.MiddleLeft),
            spent?BombBrickUiTheme.TextSecondary:active?Color.white:gold);

        Rect crown=new Rect(healthBar.x-15f,healthBar.y-2f,12f,10f);
        Color crownColor=spent
            ?new Color(0.45f,0.39f,0.22f):gold;
        BombBrickUiTheme.Fill(new Rect(crown.x,crown.y,2f,4f),crownColor);
        BombBrickUiTheme.Fill(new Rect(crown.x+5f,crown.y-2f,2f,6f),crownColor);
        BombBrickUiTheme.Fill(new Rect(crown.x+10f,crown.y,2f,4f),crownColor);
        BombBrickUiTheme.Fill(new Rect(crown.x+1f,crown.y+3f,10f,4f),crownColor);
        BombBrickUiTheme.Fill(new Rect(crown.x+2f,crown.y+8f,8f,2f),crownColor);
        GUI.color=previous;
    }

    private void DrawCaptureNetGlyph(
        Rect rect,Color color,bool selected,string itemId="")
    {
        Texture2D icon=CaptureNetIconTexture(itemId);
        Color previous=GUI.color;
        if(selected)
        {
            BombBrickUiTheme.Fill(
                new Rect(rect.x-2f,rect.y-2f,rect.width+4f,rect.height+4f),
                new Color(color.r,color.g,color.b,0.18f));
            BombBrickUiTheme.Frame(
                new Rect(rect.x-2f,rect.y-2f,rect.width+4f,rect.height+4f),
                color,2f);
        }
        GUI.color=color;
        GUI.DrawTexture(rect,icon,ScaleMode.ScaleToFit,true);
