    }

    private Texture2D CaptureNetIconTexture(string itemId)
    {
        bool rare=string.Equals(
            itemId,CaptureNetCatalog.RareId,StringComparison.Ordinal);
        if(rare)
            return captureNetRareIcon??=
                Resources.Load<Texture2D>(
                    "UI/CaptureNetIcons/capture_net_rare");
        return captureNetStandardIcon??=
            Resources.Load<Texture2D>(
                "UI/CaptureNetIcons/capture_net_common");
    }

    public static float DamageTrailRatio(float currentRatio,float previousRatio,float elapsed)
    {
        currentRatio=Mathf.Clamp01(currentRatio);
        float previous=Mathf.Max(currentRatio,Mathf.Clamp01(previousRatio));
        return Mathf.Max(currentRatio,previous-Mathf.Max(0f,elapsed-.12f)*2.5f);
    }

    private static void DrawSegmentedHealthBar(
        Rect rect,float ratio,float maximumHealth,Color healthColor,float trailRatio)
    {
        BombBrickUiTheme.Fill(rect,new Color(0.012f,0.018f,0.025f,0.96f));
        Rect inner=new Rect(rect.x+1f,rect.y+1f,rect.width-2f,rect.height-2f);
        BombBrickUiTheme.Fill(inner,new Color(0.055f,0.065f,0.075f,1f));
        if(trailRatio>ratio)
            BombBrickUiTheme.Fill(new Rect(inner.x,inner.y,inner.width*trailRatio,inner.height),
                new Color(1f,.73f,.36f));
        if(ratio>0f)
            BombBrickUiTheme.Fill(new Rect(
                inner.x,inner.y,inner.width*ratio,inner.height),healthColor);

        int segments=Mathf.Clamp(
            Mathf.CeilToInt(Mathf.Max(1f,maximumHealth)/150f),1,10);
        Color separator=new Color(0.012f,0.018f,0.025f,0.82f);
        for(int segment=1;segment<segments;segment++)
        {
            float x=Mathf.Round(inner.x+
                inner.width*segment/segments);
            BombBrickUiTheme.Fill(new Rect(
                x,inner.y,1f,inner.height),separator);
        }
        BombBrickUiTheme.Frame(rect,
            new Color(0.2f,0.24f,0.28f,0.95f),1f);
    }

    private static float TotalVisibleShield(Unit unit)
    {
        if(unit==null)return 0f;
        CombatStatusEffect statusShield=
            unit.combatStatuses.Get(CombatStatusKind.Shield);
        return Mathf.Max(0f,unit.crocodileShield)+
               Mathf.Max(0f,unit.griffinShield)+
               Mathf.Max(0f,unit.raptorShield)+
               Mathf.Max(0f,unit.kingKongShield)+
               Mathf.Max(0f,unit.bearMountainShield)+
               Mathf.Max(0f,unit.spiritLifeShield)+
               Mathf.Max(0f,unit.itemShield)+
               (statusShield==null?0f:Mathf.Max(0f,statusShield.magnitude));
    }

    private static void DrawShieldEnvelope(
        Rect healthBar,float shieldRatio,int visualSeed)
    {
        Rect envelope=new Rect(
            healthBar.x-3f,healthBar.y-3f,
            healthBar.width+6f,healthBar.height+6f);
        float pulse=0.68f+0.18f*
            Mathf.Sin(Time.unscaledTime*5.5f+visualSeed*0.73f);
        Color glow=new Color(0.28f,0.8f,1f,0.62f*pulse);
        Color shield=new Color(0.42f,0.9f,1f,1f);
        BombBrickUiTheme.Frame(new Rect(
            envelope.x-1f,envelope.y-1f,
            envelope.width+2f,envelope.height+2f),glow,3f);
        BombBrickUiTheme.Frame(envelope,
            new Color(shield.r,shield.g,shield.b,0.82f),2f);
        DrawRectPerimeterProgress(
            envelope,Mathf.Clamp01(shieldRatio),shield,3f);
        if(shieldRatio>=1f)
            BombBrickUiTheme.Frame(envelope,
                new Color(0.78f,0.97f,1f,0.82f*pulse),2f);
    }

    private static void DrawRectPerimeterProgress(
        Rect rect,float ratio,Color color,float thickness)
    {
        float remaining=(rect.width*2f+rect.height*2f)*
            Mathf.Clamp01(ratio);
        float top=Mathf.Min(remaining,rect.width);
        if(top>0f)BombBrickUiTheme.Fill(
            new Rect(rect.x,rect.y,top,thickness),color);
        remaining-=top;
        float right=Mathf.Min(Mathf.Max(0f,remaining),rect.height);
        if(right>0f)BombBrickUiTheme.Fill(
            new Rect(rect.xMax-thickness,rect.y,thickness,right),color);
        remaining-=right;
        float bottom=Mathf.Min(Mathf.Max(0f,remaining),rect.width);
        if(bottom>0f)BombBrickUiTheme.Fill(
            new Rect(rect.xMax-bottom,rect.yMax-thickness,bottom,thickness),color);
        remaining-=bottom;
        float left=Mathf.Min(Mathf.Max(0f,remaining),rect.height);
        if(left>0f)BombBrickUiTheme.Fill(
            new Rect(rect.x,rect.yMax-left,thickness,left),color);
    }

    private string PermanentMonsterMarkText(
        ExpeditionMonsterStateSave state,string monsterInstanceId)
    {
        if(state==null)return "";
        List<string> marks=new List<string>();
        if(state.appliedSpecialItemIds!=null&&
           state.appliedSpecialItemIds.Contains("special_combined_cast_core"))
            marks.Add(GameLocalization.Text("합동 시전 코어"));
        if(state.appliedSpecialItemIds!=null&&
           state.appliedSpecialItemIds.Contains("special_return_mark"))
            marks.Add(GameLocalization.Text("회귀 표식"));
        ExpeditionAugmentSelectionSave gene=ExpeditionAugmentRuntime.Selection(
            expeditionRun,ExpeditionAugmentRuntime.TranscendenceGene);
        if(state.transcended)marks.Add(GameLocalization.Text("초월"));
        else if(ExpeditionAugmentRuntime.Targets(gene,monsterInstanceId))
            marks.Add(GameLocalization.Text("초월 유전자"));
        return string.Join(" / ",marks);
    }

    private struct CombatHudIcon
    {
        public CombatStatusKind? status;
        public CombatEffectIconKind effect;
        public int stacks;
    }

    private void AddCombatHudIcon(CombatEffectIconKind kind,int stacks=1)
    {
        // Permanent identity/growth marks belong in monster details, not the status row.
        if(kind==CombatEffectIconKind.CombinedCast||kind==CombatEffectIconKind.ReturnMark||
           kind==CombatEffectIconKind.TranscendenceGene||kind==CombatEffectIconKind.Transcended)return;
        if(kind==CombatEffectIconKind.Haste)kind=CombatEffectIconKind.AttackSpeedUp;
        AddCombatHudIconEntry(new CombatHudIcon{effect=kind,stacks=stacks});
    }

    private void AddCombatHudIcon(CombatStatusKind kind,int stacks=1)
    {
        // Equivalent status and timed-effect sources share one slot, not duplicate icons.
        switch(kind)
        {
            case CombatStatusKind.Shield:
            case CombatStatusKind.ComboShielded:AddCombatHudIcon(CombatEffectIconKind.Shield,stacks);return;
            case CombatStatusKind.ComboRally:AddCombatHudIcon(CombatEffectIconKind.AttackSpeedUp,stacks);return;
            case CombatStatusKind.AttackSpeedDown:AddCombatHudIcon(CombatEffectIconKind.AttackSpeedDown,stacks);return;
            case CombatStatusKind.ComboChilled:AddCombatHudIcon(CombatEffectIconKind.Ice,stacks);return;
            case CombatStatusKind.ComboWeakened:AddCombatHudIcon(CombatEffectIconKind.AttackDown,stacks);return;
            case CombatStatusKind.ArmorBroken:AddCombatHudIcon(CombatEffectIconKind.ArmorBroken,stacks);return;
            case CombatStatusKind.ComboBurning:kind=CombatStatusKind.Burning;break;
        }
        AddCombatHudIconEntry(new CombatHudIcon{status=kind,stacks=stacks});
    }

    private void AddCombatHudIconEntry(CombatHudIcon entry)
    {
        for(int i=0;i<combatHudIcons.Count;i++)
        {
            CombatHudIcon current=combatHudIcons[i];
            if(current.status!=entry.status||
               !entry.status.HasValue&&current.effect!=entry.effect)continue;
            current.stacks=Mathf.Max(current.stacks,entry.stacks);
            combatHudIcons[i]=current;
            return;
        }
        combatHudIcons.Add(entry);
    }

    private void CollectCombatHudIcons(Unit unit)
    {
        combatHudIcons.Clear();
        for(int i=0;i<VisibleCombatStatuses.Length;i++)
        {
            CombatStatusKind kind=VisibleCombatStatuses[i];
            if(kind==CombatStatusKind.Fear||!unit.combatStatuses.Has(kind))continue;
            CombatStatusEffect effect=unit.combatStatuses.Get(kind);
            AddCombatHudIcon(kind,effect.stacks);
            if(kind==CombatStatusKind.Root&&SabertoothCombatRules.HasFangLockDebuff(unit.combatStatuses))
                AddCombatHudIcon(CombatEffectIconKind.AttackSpeedDown);
        }
        bool apex=RaptorApexPredatorActive(unit);
        bool shielded=TotalVisibleShield(unit)>0.01f||
                      unit.combatStatuses.Has(CombatStatusKind.ComboShielded);
        bool attackUp=unit.combatEffectIcons.Has(CombatEffectIconKind.AttackUp);
        bool chilled=unit.raptorSlowTimer>0f||unit.kingKongSlowTimer>0f||
                     unit.mammothSlowTimer>0f||
                     unit.combatStatuses.Has(CombatStatusKind.ComboChilled);
        bool burning=unit.combatStatuses.Has(CombatStatusKind.Burning)||
                     unit.combatStatuses.Has(CombatStatusKind.ComboBurning)||
                     unit.itemBurnTimer>0f||unit.solarBurnTimer>0f;
        int toxicStacks=SpiderToxicStacks(unit);
        bool armorBroken=unit.combatStatuses.Has(CombatStatusKind.ArmorBroken);
        bool defenseDown=armorBroken||unit.itemDefenseShredTimer>0f||
                         unit.combatEffectIcons.Has(CombatEffectIconKind.DefenseDown);
        bool resistanceDown=
            unit.familyResistanceShredTimer>0f||
            unit.combatEffectIcons.Has(CombatEffectIconKind.ResistanceDown);
        bool attackDown=unit.kingKongWeakTimer>0f||
                        unit.familyAttackReductionTimer>0f||
                        unit.combatStatuses.Has(CombatStatusKind.ComboWeakened)||
                        unit.combatEffectIcons.Has(CombatEffectIconKind.AttackDown);
        bool healingDown=unit.ninjaHealingReductionTimer>0f||
                         unit.griffinHealingReductionTimer>0f||
                         unit.familyHealingReductionTimer>0f||
                         unit.familyRecoveryShieldReductionTimer>0f||
                         (unit.itemBurnTimer>0f&&unit.itemHealingReduction>0f);
        bool hasted=unit.kingKongRallyTimer>0f||
                    unit.familyAttackSpeedTimer>0f||
                    unit.combatStatuses.Has(CombatStatusKind.ComboRally)||
                    unit.combatEffectIcons.Has(CombatEffectIconKind.Haste);
        bool royal=unit.frogRoyalAttackSpeedTimer>0f;
        bool toughScales=unit.crocodileToughHideTimer>0f||
                         unit.combatEffectIcons.Has(CombatEffectIconKind.ToughScales);
        bool damageReduction=unit.familyDamageReductionTimer>0f||HaetaeOppressionAffects(unit,true)||(TyrannoExtinctionCharging(unit)||TyrannoMarchProtected(unit)||TyrannoMawProtected(unit));
        bool deathMark=unit.crocodileDeathMarkTimer>0f;
        // The action timer also keeps the bear's animation/Rank 3 follow-up alive after its buff is consumed.
        bool resolving=unit.bearResolveTimer>0f&&BearResolveStrength(unit)>0f;
        bool hunted=false;
        foreach(Unit hunter in units)
            if(IsCombatActive(hunter)&&hunter.wolfChaseTimer>0f&&hunter.wolfChaseTarget==unit)
            {hunted=true;break;}
        if(apex)AddCombatHudIcon(CombatEffectIconKind.ApexPredator);
        if(shielded)AddCombatHudIcon(CombatEffectIconKind.Shield);
        if(attackUp)AddCombatHudIcon(CombatEffectIconKind.AttackUp);
        if(chilled)AddCombatHudIcon(CombatEffectIconKind.Ice);
        if(burning)AddCombatHudIcon(CombatStatusKind.Burning);
        if(toxicStacks>0)AddCombatHudIcon(CombatStatusKind.Poison,toxicStacks);
        if(defenseDown)AddCombatHudIcon(armorBroken
            ?CombatEffectIconKind.ArmorBroken:CombatEffectIconKind.DefenseDown);
        if(resistanceDown)AddCombatHudIcon(CombatEffectIconKind.ResistanceDown);
        if(attackDown)AddCombatHudIcon(CombatEffectIconKind.AttackDown);
        if(healingDown)AddCombatHudIcon(CombatEffectIconKind.HealingDown);
        if(hasted)AddCombatHudIcon(CombatEffectIconKind.Haste);
        if(royal)AddCombatHudIcon(CombatEffectIconKind.Royal);
        if(toughScales)AddCombatHudIcon(CombatEffectIconKind.ToughScales);
        if(damageReduction)AddCombatHudIcon(CombatEffectIconKind.DamageReduction);
        if(deathMark)AddCombatHudIcon(CombatEffectIconKind.DeathMark);
        if(hunted)AddCombatHudIcon(CombatEffectIconKind.Hunted);
        if(resolving)AddCombatHudIcon(CombatEffectIconKind.AttackUp,Mathf.Max(1,unit.bearFrenzyStacks));
        foreach(CombatEffectIconKind kind in unit.combatEffectIcons.ActiveKinds)
        {
            // Guardian identity uses Royal too; the temporary frog buff is collected above.
            if(kind==CombatEffectIconKind.Royal&&(unit.regionGuardian||unit.guardianPreview))continue;
            AddCombatHudIcon(kind);
        }
        CollectSupplementalCombatHudIcons(unit);
    }

    private void CollectSupplementalCombatHudIcons(Unit unit)
    {
        foreach(FrogStolenBuff buff in unit.frogStolenBuffs)
            if(buff.remaining>0f)AddCombatHudIcon(FrogStolenBuffIcon(buff.kind,buff.magnitude));
        // Collect independent temporary effects only. Compound buffs/debuffs already have
        // a representative above; omit their derived stats, not other sources of those stats.
        if(unit.griffinRootTimer>0f||unit.crocodileImmobilizedTimer>0f)
            AddCombatHudIcon(CombatStatusKind.Root);
        if(unit.rank3SkillLockTimer>0f)AddCombatHudIcon(CombatStatusKind.Silence);
        if(unit.giraffeStunTimer>0f)AddCombatHudIcon(CombatEffectIconKind.Stun);
        if(unit.forcedTargetTimer>0f&&IsCombatActive(unit.forcedTarget))
            AddCombatHudIcon(CombatEffectIconKind.Taunted);
        bool oppressionSlowed=HaetaeOppressionAffects(unit,false);
        if(unit.frogSlowTimer>0f||oppressionSlowed)
            AddCombatHudIcon(CombatEffectIconKind.MoveSpeedDown);
        if(unit.rank3ActionSlowTimer>0f||oppressionSlowed)
            AddCombatHudIcon(CombatEffectIconKind.AttackSpeedDown);
        if(unit.rank3AttackBonusTimer>0f||unit.counterBonusDamage>0f||
           unit.postSkillBasicDamage>0f||unit.ninjaEmpoweredBasicAttacks>0||
           unit.frogStolenBuffTimer>0f&&unit.frogStolenBuffMagnitude>0f&&unit.frogStolenBuffKind==FrogStolenBuffKind.AttackDamage)
            AddCombatHudIcon(CombatEffectIconKind.AttackUp);
        bool killHaste=false;
        foreach(float expiry in unit.growthKillHasteExpirations)
            if(expiry>battleElapsed){killHaste=true;break;}
        if(unit.itemAttackSpeedTimer>0f||unit.itemPostSkillAttackSpeedTimer>0f||
           unit.itemStatusRecoveryAttackSpeedTimer>0f||unit.rank3AttackSpeedBonusTimer>0f||
           unit.giraffeDanceAttackSpeedTimer>0f||unit.augmentClimaxTimer>0f||
           killHaste||
           unit.frogStolenBuffTimer>0f&&unit.frogStolenBuffMagnitude>0f&&unit.frogStolenBuffKind==FrogStolenBuffKind.AttackSpeed)
            AddCombatHudIcon(CombatEffectIconKind.AttackSpeedUp);
        if(unit.packHuntSpeedTimer>0f||unit.wolfChaseTimer>0f||
           unit.rank3MoveSpeedBonusTimer>0f||unit.familyMoveSpeedTimer>0f||
           unit.mammothHasteTimer>0f||
           unit.frogStolenBuffTimer>0f&&unit.frogStolenBuffMagnitude>0f&&unit.frogStolenBuffKind==FrogStolenBuffKind.MoveSpeed)
            AddCombatHudIcon(CombatEffectIconKind.MoveSpeedUp);
        if(unit.rank3DefenseBonusTimer>0f||
           unit.itemTemporaryStatTimer>0f&&unit.itemTemporaryDefenseBonus>0f||
           unit.itemPostSkillStatTimer>0f&&unit.itemPostSkillDefenseBonus>0f||
           unit.itemTwilightStatTimer>0f&&unit.itemTwilightDefenseBonus>0f||
           unit.frogStolenBuffTimer>0f&&unit.frogStolenBuffMagnitude>0f&&unit.frogStolenBuffKind==FrogStolenBuffKind.Defense||
           unit.fangLockTimer>0f&&MonsterTraitRuntime.Has(unit.activeTraitIds,SabertoothCombatRules.TerakanTraitId))
            AddCombatHudIcon(CombatEffectIconKind.DefenseUp);
        // Paired defense/resistance buffs use defense; resistance-only buffs retain theirs.
        if(unit.itemTemporaryStatTimer>0f&&unit.itemTemporaryResistanceBonus>0f&&unit.itemTemporaryDefenseBonus<=0f||
           unit.itemPostSkillStatTimer>0f&&unit.itemPostSkillResistanceBonus>0f&&unit.itemPostSkillDefenseBonus<=0f||
           unit.itemTwilightStatTimer>0f&&unit.itemTwilightResistanceBonus>0f&&unit.itemTwilightDefenseBonus<=0f)
            AddCombatHudIcon(CombatEffectIconKind.ResistanceUp);
        if(unit.tyrannoResistanceShredTimer>0f||unit.corruptStatusResistanceReductionTimer>0f)
            AddCombatHudIcon(CombatEffectIconKind.ResistanceDown);
        if(unit.guardTimer>0f||FindMammothBraceProtector(unit)!=null||
           unit.growthStatusRecoveryGuardTimer>0f||IsSpiritSanctuaryProtected(unit)||
           unit.corruptDamageReduction>0f)
            AddCombatHudIcon(CombatEffectIconKind.DamageReduction);
        if(unit.itemOpeningImmunityTimer>0f||unit.combatStatuses.DebuffImmune)
            AddCombatHudIcon(CombatEffectIconKind.DebuffImmunity);
        if(unit.rank3ForceImmuneTimer>0f||MantisReaperFlying(unit)||(TyrannoExtinctionCharging(unit)||TyrannoMarchProtected(unit)||TyrannoMawProtected(unit))||unit.ninjaCrossActive||unit.combatStatuses.ControlImmune)
            AddCombatHudIcon(CombatEffectIconKind.ControlImmunity);
        if(unit.ninjaUntargetableTimer>0f||unit.ninjaCrossActive||unit.corruptUntargetable)
            AddCombatHudIcon(CombatEffectIconKind.Untargetable);
        if(unit.augmentReturnTimer>0f||unit.augmentReturnInvulnerabilityTimer>0f||
           unit.griffinSkyfalling)
            AddCombatHudIcon(CombatEffectIconKind.Invulnerable);
        if(unit.corruptIncomingDamageAmpTimer>0f)
            AddCombatHudIcon(CombatEffectIconKind.DamageAmplified);
        if(unit.corruptReflectionRatio>0f||IsBloodRefluxActive(unit))
            AddCombatHudIcon(CombatEffectIconKind.Reflection);
        if(unit.corruptDamageLinkRatio>0f&&IsCombatActive(unit.corruptDamageLinkTarget))
            AddCombatHudIcon(CombatEffectIconKind.DamageLink);
        if(unit.mushroomSporeMarkTimer>0f)
            AddCombatHudIcon(CombatEffectIconKind.SporeMark);
        foreach(Unit owner in units)
            if(IsCombatActive(owner)&&owner.jaguarMarkTimer>0f&&owner.jaguarMarkedTarget==unit)
            {AddCombatHudIcon(CombatStatusKind.Marked);break;}
    }

    public static Rect CombatHudIconRect(Rect healthBar,int index,int count)
    {
        const int columns=6;
        const float size=16f,gap=2f;
        int row=index/columns;
        int rowCount=Mathf.Min(columns,count-row*columns);
        float width=rowCount*size+(rowCount-1)*gap;
        return new Rect(healthBar.center.x-width*0.5f+(index%columns)*(size+gap),
            healthBar.yMin-6f-size-row*(size+gap),size,size);
    }

    private void DrawCombatHudIcons(Rect healthBar,Unit unit)
    {
        for(int i=0;i<combatHudIcons.Count;i++)
        {
            CombatHudIcon entry=combatHudIcons[i];
            Rect rect=CombatHudIconRect(healthBar,i,combatHudIcons.Count);
            if(entry.status.HasValue)DrawCombatStatusIcon(rect,entry.status.Value);
            else DrawCombatEffectIcon(rect,entry.effect);
            if(!entry.status.HasValue&&entry.effect==CombatEffectIconKind.Hunted&&
               unit.preyMarkFlash>0f)
                BombBrickUiTheme.Frame(rect,Color.Lerp(CombatHudIconArt.DebuffAccent,
                    Color.white,unit.preyMarkFlash/0.3f),2f);
            DrawCombatStackCount(rect,entry.stacks);
        }
    }


    private static void DrawCombatStackCount(Rect icon,int stacks)
    {
        if(stacks<=1)return;
        Rect badge=new Rect(icon.xMax-8f,icon.yMax-9f,9f,9f);
        BombBrickUiTheme.Fill(badge,new Color(0.01f,0.015f,0.02f,0.96f));
        BombBrickUiTheme.Label(badge,stacks.ToString(),
            BombBrickUiTheme.CaptionStyle(7,TextAnchor.MiddleCenter),
            Color.white,FontStyle.Bold);
    }

    private static void DrawCombatEffectIcon(Rect rect,CombatEffectIconKind kind)
    {
        DrawCombatHudArtwork(rect,CombatHudIconArt.Get(kind),CombatHudIconArt.Accent(kind));
    }

    private static void DrawCombatStatusIcon(Rect rect,CombatStatusKind kind)
    {
        DrawCombatHudArtwork(rect,CombatHudIconArt.Get(kind),CombatHudIconArt.Accent(kind));
    }

    private static void DrawCombatHudArtwork(Rect rect,Texture2D artwork,Color accent)
    {
        Color previous=GUI.color;
        BombBrickUiTheme.Fill(rect,accent);
        // The originals have opaque black backgrounds. A faint accent shows through
        // without shrinking or recoloring the light symbol into a solid colored glyph.
        GUI.color=new Color(1f,1f,1f,0.86f);
        if(artwork!=null)GUI.DrawTexture(rect,artwork);
        BombBrickUiTheme.Frame(rect,accent,1f);
        GUI.color=previous;
    }

    private void AddCombatFloatText(
        Unit unit,string label,Color color,bool emphasis=false,
        float sizeMultiplier=1f,bool combatResult=false,bool damageImpact=false,
        bool personalityNotice=false)
    {
        // Effect notices stay icon-only; requested personality reactions have their own text channel.
        if(!combatResult&&!personalityNotice)return;
        if(unit==null||unit.model==null||string.IsNullOrEmpty(label))return;
        if(combatFloatTexts.Count>=40)combatFloatTexts.RemoveAt(0);
        float horizontal=((unit.id*37+combatFloatTexts.Count*13)%9-4)*0.035f;
        combatFloatTexts.Add(new CombatFloatText
        {
            world=unit.model.transform.position+
                  new Vector3(horizontal,personalityNotice?2.65f:1.72f,0f),
            label=label,
            color=color,
            startedAt=Time.unscaledTime,
            emphasis=emphasis,
            damageImpact=damageImpact,
            personalityNotice=personalityNotice,
            personalityOwner=personalityNotice?unit:null,
            drift=horizontal<0f?-1f:1f,
            sizeMultiplier=Mathf.Max(1f,sizeMultiplier)
        });
    }

    private void ShowGrowthRankUp(Unit unit,ExpeditionMonsterRank rank)
    {
        if(unit==null)return;
        Color color=rank>=ExpeditionMonsterRank.Rank3
            ?new Color(0.78f,0.42f,1f)
            :new Color(0.2f,0.9f,1f);
        AddCombatFloatText(unit,new string('★',(int)rank),color,true,combatResult:true);
    }

    private void UpdateTraitActivationFeedback(Unit unit)
    {
        if(unit==null||unit.traitActivations<=unit.shownTraitActivations)return;
        unit.shownTraitActivations=unit.traitActivations;
        if(unit.team!=Team.Player||Time.unscaledTime<unit.nextTraitFeedbackAt)return;
        unit.nextTraitFeedbackAt=Time.unscaledTime+0.6f;
        Color color=new Color(0.78f,0.42f,1f);
        AddCombatFloatText(unit,"특성 발동",color,true);
    }

    private static void SampleDamageText(
        float elapsed,bool critical,out float size,out float rise,out float alpha)
    {
        float peak=critical?1.75f:1.5f;
        size=elapsed<.045f
            ?Mathf.Lerp(1.1f,peak,Mathf.SmoothStep(0f,1f,elapsed/.045f))
            :Mathf.Lerp(peak,1f,Mathf.SmoothStep(0f,1f,(elapsed-.045f)/.145f));
        float launch=Mathf.Clamp01(elapsed/.23f);
        rise=(critical?40f:30f)*(1f-Mathf.Pow(1f-launch,3f))
            -9f*Mathf.SmoothStep(0f,1f,(elapsed-.23f)/.49f);
        alpha=1f-Mathf.SmoothStep(0f,1f,(elapsed-.3f)/.42f);
    }

    private void DrawCombatFloatTexts()
    {
        if(mainCamera==null||combatFloatTexts.Count==0)return;
        for(int pass=0;pass<2;pass++)
        for(int i=combatFloatTexts.Count-1;i>=0;i--)
        {
            CombatFloatText entry=combatFloatTexts[i];
            if(entry.personalityNotice!=(pass==1))continue;
            float duration=entry.personalityNotice?1.05f:.72f;
            float elapsed=Time.unscaledTime-entry.startedAt;
            if(elapsed>=duration)
            {
                combatFloatTexts.RemoveAt(i);
                continue;
            }
            Vector3 world=IsCombatActive(entry.personalityOwner)
                ?entry.personalityOwner.model.transform.position+new Vector3(0f,2.65f,0f):entry.world;
            Vector3 screen=mainCamera.WorldToScreenPoint(world);
            if(screen.z<=0f)continue;
            screen/=BombBrickUiLayout.Scale;
            float progress=Mathf.Clamp01(elapsed/duration);
            float alpha=1f-Mathf.SmoothStep(0f,1f,progress);
            float y=BombBrickUiLayout.Height-screen.y-progress*34f;
            if(entry.personalityNotice)y-=12f;
            float size=Mathf.Max(1f,entry.sizeMultiplier);
            if(entry.damageImpact)
            {
                SampleDamageText(elapsed,entry.emphasis,out float pop,out float rise,out alpha);
                size*=pop;
                y=BombBrickUiLayout.Height-screen.y-rise;
                screen.x+=entry.drift*(entry.emphasis?16f:12f)*Mathf.Clamp01(elapsed/.4f);
            }
            else if(entry.emphasis)
            {
                float pop=1f-Mathf.Clamp01(elapsed/.16f);
                size*=1f+.16f*pop*pop;
                y-=Mathf.Sin(Mathf.Clamp01(elapsed/.2f)*Mathf.PI)*5f;
            }
            size*=CombatReadabilityPresentation.BodyVisualScale;
            Rect rect=new Rect(
                screen.x-45f*size,y-12f*size,90f*size,24f*size);
            GUIStyle style=BombBrickUiTheme.TitleStyle(
                Mathf.RoundToInt((entry.emphasis?16f:13f)*size),
                TextAnchor.MiddleCenter);
            if(entry.damageImpact)
                BombBrickUiTheme.Label(new Rect(rect.x+1.5f,rect.y+1.5f,rect.width,rect.height),
                    entry.label,style,new Color(.03f,.04f,.06f,alpha*.85f));
            if(entry.personalityNotice)
                for(int edge=0;edge<4;edge++)
                    BombBrickUiTheme.Label(new Rect(rect.x+(edge<2?(edge==0?-1.5f:1.5f):0f),
                        rect.y+(edge>=2?(edge==2?-1.5f:1.5f):0f),rect.width,rect.height),
                        entry.label,style,new Color(.03f,.04f,.06f,alpha));
            BombBrickUiTheme.Label(rect,entry.label,style,new Color(
                entry.color.r,entry.color.g,entry.color.b,alpha));
        }
    }

    [System.Diagnostics.Conditional("UNITY_EDITOR")]
    [System.Diagnostics.Conditional("DEVELOPMENT_BUILD")]
    private void BeginTelemetryEpisode()
    {
#if UNITY_EDITOR
        if(balanceTestRunning)return;
#endif
        if(telemetryEpisodeStarted)return;
        telemetry=new AutoBattleTelemetryRecorder();
        telemetryEpisodeStarted=true;telemetryEpisodeEnded=false;
        battleElapsed=0f;telemetryTimer=0f;
        telemetry.RecordEpisodeStart(
            Columns,Rows,
            units.Count(unit=>unit.team==Team.Player&&!unit.inStorage),
            units.Count(unit=>unit.team==Team.Enemy&&!unit.inStorage),
            mlEpisodeActive?"ml_training":"game",
            expeditionRun==null?"":expeditionRun.runId,
            expeditionRun==null?"":expeditionRun.regionId,
            expeditionRun==null?"":expeditionRun.difficulty.ToString(),
            expeditionRun==null?0:expeditionRun.wave,
            mlEpisodeActive?mlScenarioSeed:
                expeditionRun==null?0:expeditionRun.activeBattleSeed,
            mlEpisodeActive?mlAcademyStep:0,
            mlEpisodeActive?mlScenarioProfile:"game");
        for(int i=0;i<units.Count;i++)
        {
            Unit unit=units[i];
            ExpeditionMonsterStateSave state=unit.team==Team.Player
                ?ExpeditionItemSystem.MonsterState(expeditionRun,unit.stableId):null;
            ExpeditionMonsterRank rank=unit.team==Team.Enemy
                ?unit.expeditionRank
                :state==null?ExpeditionMonsterRank.Rank1:state.rank;
            string itemIds=state==null
                ?string.Join("|",unit.equippedEnemyItems
                    .Where(item=>item!=null).Select(item=>item.id))
                :string.Join("|",state.itemInstanceIds
                    .Select(instanceId=>ExpeditionItemSystem.ItemInstance(
                        expeditionRun,instanceId)?.itemId)
                    .Where(itemId=>!string.IsNullOrWhiteSpace(itemId)));
            telemetry.RecordPlacement(
                unit.id,unit.stableId,unit.definition.monsterId,
                unit.definition.familyId,unit.team.ToString(),rank.ToString(),
                unit.deploymentSlots,unit.ownedInstance.personalityId,
                unit.ownedInstance.personalitySeed,
                string.Join("|",unit.activeTraitIds),itemIds,
                unit.maxHp,unit.damage,unit.attackInterval,unit.defense,
                unit.statusResistance,unit.attackRange,
                unit.currentTile.x,unit.currentTile.y,unit.footprint.x,unit.footprint.y,unit.inStorage);
        }
    }

    private void RecordTelemetrySteps()
    {
        if(!telemetryEpisodeStarted||telemetryEpisodeEnded||telemetry==null)return;
        float extentX=Mathf.Max(1f,mapBounds.extents.x),extentZ=Mathf.Max(1f,mapBounds.extents.z);
        float diagonal=Mathf.Sqrt(extentX*extentX+extentZ*extentZ)*2f;
        for(int i=0;i<units.Count;i++)
        {
            Unit unit=units[i];if(!IsCombatActive(unit))continue;
            Vector3 p=Flat(unit.model.transform.position);
            int targetId=IsCombatActive(unit.target)?unit.target.id:-1;
            float targetDistance=targetId>=0?Vector3.Distance(p,Flat(unit.target.model.transform.position))/diagonal:1f;
            telemetry.RecordStep(battleElapsed,unit.id,unit.team.ToString(),unit.skillId,
                Mathf.Clamp((p.x-mapBounds.center.x)/extentX,-1f,1f),Mathf.Clamp((p.z-mapBounds.center.z)/extentZ,-1f,1f),
                unit.velocity.x/Mathf.Max(1f,unit.speedTilesPerSecond*TileSize),unit.velocity.z/Mathf.Max(1f,unit.speedTilesPerSecond*TileSize),
                unit.hp/Mathf.Max(1f,unit.maxHp),targetId,targetDistance,
                NearestUnitDistance(unit,unit.team,true)/diagonal,NearestUnitDistance(unit,unit.team,false)/diagonal,
                CountNearby(unit,unit.team,true),CountNearby(unit,unit.team,false),unit.currentAction);
        }
    }

    private float NearestUnitDistance(Unit source,Team team,bool sameTeam)
    {
        float nearest=float.MaxValue;
        Vector3 origin=Flat(source.model.transform.position);
        for(int i=0;i<units.Count;i++)
        {
            Unit other=units[i];
            if(other==source||!IsCombatActive(other)||(sameTeam!=(other.team==team)))continue;
            nearest=Mathf.Min(nearest,Vector3.Distance(origin,Flat(other.model.transform.position)));
        }
        return nearest==float.MaxValue?Mathf.Sqrt(mapBounds.size.x*mapBounds.size.x+mapBounds.size.z*mapBounds.size.z):nearest;
    }

    private int CountNearby(Unit source,Team team,bool sameTeam)
    {
        int count=0;Vector3 origin=Flat(source.model.transform.position);
        for(int i=0;i<units.Count;i++)
        {
            Unit other=units[i];
            if(other==source||!IsCombatActive(other)||(sameTeam!=(other.team==team)))continue;
            if(Vector3.Distance(origin,Flat(other.model.transform.position))<=TileSize*2.5f)count++;
        }
        return count;
    }

    private void EndTelemetryEpisode(Team winner)
    {
        if(!telemetryEpisodeStarted||telemetryEpisodeEnded||telemetry==null)return;
        telemetryEpisodeEnded=true;
        int playerSurvivors=units.Count(unit=>IsCombatActive(unit)&&unit.team==Team.Player);
        int enemySurvivors=units.Count(unit=>IsCombatActive(unit)&&unit.team==Team.Enemy);
        telemetry.RecordEpisodeEnd(battleElapsed,winner.ToString(),playerSurvivors,enemySurvivors);
        for(int i=0;i<units.Count;i++)
        {
            Unit unit=units[i];
            if(unit.inStorage)continue;
            telemetry.RecordUnitResult(unit.id,unit.team.ToString(),unit.skillId,unit.alive,unit.team==winner,
                unit.damageDealt,unit.damageTaken,unit.skillDamage,unit.preventedDamage,unit.skillUses,unit.skillHits,
                unit.kills,unit.targetChanges,string.Join("|",unit.activeTraitIds),unit.traitActivations);
        }
        telemetry.Flush();
    }

    private void OnApplicationPause(bool pauseStatus)
    {
        if(pauseStatus)PrepareForSystemMenu();
        if(pauseStatus&&expeditionRun!=null&&!GameFrontend.HasPendingSave)
            SaveExpeditionCheckpoint(
                expeditionRun.checkpoint,true);
    }

