    {
        if(!hasFocus)ClearInterruptedInput();
    }

    private void ClearPlacementHover()
    {
        hoveredTile=NoHoveredTile;
        hoveredUnit=null;
        ClearPlacementMarkerHighlights();
    }

    private void OnDisable()
    {
        ResetMonsterRankUpFeedback();
        CancelCommonSkillFocus();
        StopFamilyRank4CinematicAudio();raptorCinematicStage?.Hide();
        CombatEffectEndPlayback.Clear(gameObject.scene);
        FrogTongueWhip.ClearBattleEndTails(gameObject.scene);
        foreach(Unit unit in units){EndGriffinHunt(unit);ClearGriffinRoyal(unit);}
        ClearMammothBoulders();
        ClearMushroomGasZones();
        ClearMushroomCrowns();
        ResetFamilyTranscendenceStates();
        UnregisterReadabilityPresentation();
    }

    private void OnDestroy()
    {
        ResetMonsterRankUpFeedback();
        UnregisterReadabilityPresentation();
        DisposeRank4Cinematics();
        CancelCommonSkillFocus();
        raptorCinematicStage?.Dispose();raptorCinematicStage=null;
        familyRank4CinematicAudio?.Dispose();familyRank4CinematicAudio=null;
        sabertoothCinematicStage?.Dispose();sabertoothCinematicStage=null;
        frogCatchCinematicStage?.Dispose();frogCatchCinematicStage=null;
        crocodileAbyssCinematicStage?.Dispose();crocodileAbyssCinematicStage=null;
        kingKongCinematicStage?.Dispose();kingKongCinematicStage=null;
        wizardCygnusCinematicStage?.Dispose();wizardCygnusCinematicStage=null;
        bearAvatarCinematicStage?.Dispose();bearAvatarCinematicStage=null;
        wolfStampedeCinematicStage?.Dispose();wolfStampedeCinematicStage=null;
        ResetFamilyTranscendenceStates();
        combatCameraDirector?.EndBattle();
        CancelCapturePresentation();
#if UNITY_EDITOR
        Time.timeScale=1f;
        Time.captureDeltaTime=balanceTestOriginalCaptureDeltaTime;
#endif
        if(profileStore!=null)profileStore.Changed-=OnPlayerProfileChanged;
        if(tileMaterial!=null)Destroy(tileMaterial);
        if(unitShadowMaterial!=null)Destroy(unitShadowMaterial);
        if(skillRadiusMarkerMaterial!=null)Destroy(skillRadiusMarkerMaterial);
        if(benchTileMesh!=null&&benchTileMesh!=tileMesh)Destroy(benchTileMesh);
        if(tileMesh!=null)Destroy(tileMesh);
        if(placementMarkerSprite!=null)
        {
            Destroy(placementMarkerSprite.texture);
            Destroy(placementMarkerSprite);
        }
        for(int i=0;i<isoTileSprites.Length;i++)
            if(isoTileSprites[i]!=null)Destroy(isoTileSprites[i]);
        for(int i=0;i<units.Count;i++)ClearJaguarHuntMark(units[i]);
        ClearSpiderWebZones();
        ClearSpiritGuardSanctuaries();
        ClearSpiritConcertEchoes();
        ClearMammothBoulders();
        ClearMushroomGasZones();
        ClearMushroomCrowns();
        if(telemetry!=null){telemetry.Dispose();telemetry=null;}
    }
}
